/// The node budget of one transitive self-root walk
/// ([`ProjectSemanticDispatch::transitive_self_roots_from_nodes`]). A walk
/// that exceeds it has NOT established its root set and the result it
/// roots is refused warm — the cap bounds the work, it never truncates the
/// proof silently.
pub const SELF_ROOT_WALK_CAP: usize = 4096;

/// Whether a value's type is the object literal it is initialized with —
/// no authored annotation, no `unique symbol`, no evaluated initializer
/// expression, and an object shape — the anonymous object type whose
/// members `build_typeof` lowers from the literal's own positions.
pub(super) fn value_is_own_object_literal(
    prepared: &verter_session_query::type_solver::PreparedValueDecl,
) -> bool {
    use verter_type_expr::facts::{SemanticTypeSource, ValueAnnotationClass};
    let annotation = &prepared.type_annotation;
    prepared.object_shape.is_some()
        && !annotation.is_unique_symbol
        && annotation.expression_source.is_none()
        && match annotation.classification {
            ValueAnnotationClass::Absent => true,
            ValueAnnotationClass::Direct => !matches!(
                annotation.annotation,
                Some(
                    SemanticTypeSource::Authored(_)
                        | SemanticTypeSource::Closed(
                            verter_type_expr::facts::ClosedTypeFact::Leaf(_)
                        )
                )
            ),
            ValueAnnotationClass::TypeOfAlias | ValueAnnotationClass::InferenceUnavailable(_) => {
                false
            }
        }
}

/// The effective prepared VALUE-decl identity resolved by
/// [`ProjectSemanticDispatch::effective_prepared_value_decl`]: the declaring
/// `(canonical, owner, symbol)` (post value-export-target fallback) plus the
/// prepared value decl itself.
pub(super) type EffectivePreparedValueDecl = (
    verter_type_expr::OwnedStr,
    verter_type_expr::TopLevelOwnerId,
    verter_type_expr::OwnedStr,
    verter_retention::heap_size::OwnedValue<verter_session_query::type_solver::PreparedValueDecl>,
);

/// One folded cross-file augmentation contributor: its version self-root
/// (`canonical` + the `FileWholeHash` the body was lowered from) TOGETHER
/// WITH the exact artifact key the contributor's locator-backed body read
/// served from. One carrier BY CONSTRUCTION: a contributor cannot enter the
/// parent's `self_root_canonicals` without its source-env identity — the
/// version-root fields and the `artifact_key` are inseparable, and the fact
/// emission records the contributor's `FileWholeHash` observation AND its
/// `FileSourceEnv` observation from the SAME element in one step.
#[derive(Clone)]
struct AugmentationContributorRoot {
    canonical: verter_type_expr::OwnedStr,
    whole_hash: crate::semantic_query::HashValue,
    artifact_key: verter_session_query::source::artifact_key::FileArtifactKey,
}

/// Result of a cross-file declaration-augmentation stitch
/// ([`ProjectSemanticDispatch::stitch_module_augmentations`]): the folded
/// [`SemanticNodeData::MergedDecl`] node plus the per-augmenter
/// [`AugmentationContributorRoot`]s whose `(canonical, whole_hash)` version
/// roots must enter the cached value's `self_root_canonicals`.
struct AugmentationStitch {
    merged: SemanticNodeId,
    contributor_roots: Vec<AugmentationContributorRoot>,
    /// `true` when a contributor's coherent source-env identity could not
    /// be observed (a torn / unhealable augmenter entry): the parent result
    /// is served but never warm-admitted.
    source_env_unobservable: bool,
}

/// What one augmenter contributes to the collected declaration.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum AugmentationContribution {
    /// The declaration's type body (an interface or namespace merge).
    TypeBody,
    /// The call signatures its function declarations add to an exported
    /// function VALUE — one overload group per augmenting block.
    FunctionSignatures,
    /// The block of an enum it declares — and, for a global enum, every
    /// script's block — with its members.
    EnumBlocks,
}

/// One block of an enum an augmentation collection gathered
/// ([`AugmentationContribution::EnumBlocks`]): the file and declaration
/// scope declaring it, and its members in declaration order.
pub(super) struct EnumContribution {
    pub(super) canonical: Arc<str>,
    pub(super) owner: verter_type_expr::TopLevelOwnerId,
    /// The ambient block scope declaring it; `None` for the file's own
    /// declaration.
    pub(super) scope: Option<verter_session_query::declarations::AugmentationScopeKind>,
    pub(super) members: Arc<[verter_type_expr::facts::EnumMemberEntry]>,
}

/// One contributor of an augmentation fold, read before the fold so its
/// type bodies can be lowered as one batch: its served source, and for an
/// augmenter its artifact answer and the blocks that contribute to the
/// folded declaration (raw specifier, owner, retained scope).
struct ContributorPrefetch {
    indexed: Arc<verter_session_query::inputs::indexed::IndexedInputRecord>,
    art: Option<crate::resolver_core::request_ports::AugmenterArtifactAnswer>,
    matched: Vec<(
        String,
        verter_type_expr::TopLevelOwnerId,
        verter_session_query::declarations::AugmentationScopeKind,
    )>,
}

/// One contributing type body of an augmentation fold, fetched but not
/// yet projected: its role-free authored shape and everything projecting
/// it reads. Nothing here depends on the demanding projection context, so
/// a fold serves every context its declaration is instantiated under.
pub(crate) struct PlannedContributorBody {
    /// The `LowerLocator` shape; `None` when the locator missed (the
    /// projection is then the shared miss sentinel).
    shape: Option<SemanticNodeId>,
    owner_symbol: verter_type_expr::OwnedStr,
    prepared: verter_retention::heap_size::OwnedValue<PreparedTypeDecl>,
    augmentation: Option<verter_session_query::declarations::AugmentationScopeKind>,
    scope: NodeScopeId,
    scope_payload: Option<crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: crate::resolver_core::scope_shadowing::ScopeShadowing,
}

/// A type-body augmentation fold before projection: the ordered planned
/// bodies and the fold's rails. Shared by every projection context of one
/// dispatch transaction (see [`ProjectSemanticDispatch::collect_augmentation_contributions`]).
pub(crate) struct AugmentationPlan {
    bodies: Vec<PlannedContributorBody>,
    contributor_roots: Vec<AugmentationContributorRoot>,
    source_env_unobservable: bool,
    base_position: Option<usize>,
    /// The target and augmenter-set fingerprint of the stitched event a
    /// projection reports; `None` for a tainted-empty fold.
    stitched: Option<(
        verter_session_query::resolution::AugmentationTargetKind,
        crate::semantic_query::HashValue,
    )>,
    /// Whether every shape fetch answered a value: a recursive or failed
    /// fetch depends on the demand stack that met it, so its plan serves
    /// only the context that built it.
    context_free: bool,
}

/// A fold as the transaction holds it: lowered contributions, or a shared
/// type-body plan.
enum TransactionFold {
    Contributions(AugmentationContributions),
    Plan(Arc<AugmentationPlan>),
}

/// What an augmentation fold produced: lowered contributions, the
/// unprojected plan of a type-body fold, or the read that no declaration
/// beside the base exists for the target.
enum FoldedAugmentation {
    Contributions(AugmentationContributions),
    Plan(AugmentationPlan),
    /// Neither an augmenting block nor another file-scope declaration
    /// contributes to the declaration. Decided by the augmenter set and the
    /// contributors' retained declarations alone, never by the declaration's
    /// arguments or projection context, so it answers every instantiation of
    /// the declaration alike.
    Absent,
}

impl FoldedAugmentation {
    fn into_transaction_fold(self) -> Option<TransactionFold> {
        match self {
            Self::Contributions(contributions) => {
                Some(TransactionFold::Contributions(contributions))
            }
            Self::Plan(plan) => Some(TransactionFold::Plan(Arc::new(plan))),
            Self::Absent => None,
        }
    }
}

/// Shared return shape of the augmenter-fold path
/// ([`ProjectSemanticDispatch::collect_augmentation_contributions`]): the
/// ordered augmenter contributor nodes, one [`AugmentationContributorRoot`]
/// per contributing augmenter, and whether any contributor's source-env
/// identity was unobservable (torn state ⇒ no warm admission).
pub(crate) struct AugmentationContributions {
    pub(super) contributor_nodes: Vec<SemanticNodeId>,
    contributor_roots: Vec<AugmentationContributorRoot>,
    pub(super) source_env_unobservable: bool,
    /// Where the excluded contributor's own declaration falls among
    /// `contributor_nodes` in declaration precedence order: the count of
    /// contributions that precede it. `None` when no contributor was
    /// excluded.
    base_position: Option<usize>,
    /// The call signatures each augmenting block contributes, one group per
    /// block in declaration order, when the collected contribution is
    /// [`AugmentationContribution::FunctionSignatures`]; empty otherwise.
    pub(super) signature_groups: Vec<Vec<SemanticNodeId>>,
    /// The enum blocks gathered, in declaration precedence order, when the
    /// collected contribution is [`AugmentationContribution::EnumBlocks`];
    /// empty otherwise.
    pub(super) enum_blocks: Vec<EnumContribution>,
}

/// Record a completed semantic augmentation stitch using the public typed
/// audit schema. This is emitted only after at least one augmenter contributed
/// and after the exact augmenter-set fingerprint has been observed by the
/// consumer's fact tracer.
fn emit_module_augmentation_stitched_event<M: verter_audit::observe::ObserveExec>(
    observation: &crate::request_observers::CaptureTargets,
    target: &verter_session_query::resolution::AugmentationTargetKind,
    augmenter_count: u32,
    fingerprint: crate::semantic_query::HashValue,
) {
    let _ = observation;
    // Optional capture: the event and its payload are built only when an
    // accumulator is installed, and never in a default build.
    crate::component_meta_trace_structured!(M => on observation.accumulator.as_deref() => {
        use verter_audit::AugmentationTargetKindTag;
        use verter_session_query::resolution::AugmentationTargetKind;

        let (target_kind_tag, external_specifier, resolved_relative_canonical, wildcard_pattern) =
            match target {
                AugmentationTargetKind::ExternalSpecifier(specifier) => (
                    AugmentationTargetKindTag::ExternalSpecifier,
                    Some(Arc::<str>::from(specifier.as_ref())),
                    None,
                    None,
                ),
                AugmentationTargetKind::ResolvedRelativeCanonical(canonical) => (
                    AugmentationTargetKindTag::ResolvedRelativeCanonical,
                    None,
                    Some(Arc::clone(canonical)),
                    None,
                ),
                AugmentationTargetKind::WildcardAmbient(pattern) => (
                    AugmentationTargetKindTag::WildcardAmbient,
                    None,
                    None,
                    Some(Arc::<str>::from(pattern.as_ref())),
                ),
                AugmentationTargetKind::GlobalAugmentation => (
                    AugmentationTargetKindTag::GlobalAugmentation,
                    None,
                    None,
                    None,
                ),
            };

        verter_audit::structured_event::StructuredAuditEvent::ModuleAugmentationStitched {
            target_kind_tag,
            external_specifier,
            resolved_relative_canonical,
            wildcard_pattern,
            augmenter_count,
            fingerprint,
        }
    });
}

/// One resolved heritage base from a class's `extends` clause
/// ([`ProjectSemanticDispatch::class_heritage_bases`]): the base decl's
/// `(canonical, symbol)` identity plus the heritage clause's authored
/// type-argument LOCATORS (`extends Base<string>` — producer-minted
/// content-free positions; the Static composer derefs + lowers them on
/// demand, never an embedded body).
type HeritageBase = (
    verter_type_expr::OwnedStr,
    verter_type_expr::TopLevelOwnerId,
    verter_type_expr::OwnedStr,
    Arc<[verter_type_expr::locators::TypeArgLocator]>,
);

/// What a class declaration's `extends` VALUE gives it
/// ([`ProjectSemanticDispatch::class_value_base`]).
pub(super) struct ClassValueBase {
    /// The base constructor type — the value's type.
    pub(super) constructor_type: SemanticNodeId,
    /// Its construct signatures, instantiated with the heritage clause's
    /// type arguments, in declaration order.
    pub(super) construct_signatures: Vec<SemanticNodeId>,
    /// The base instance type, when the first signature returns a valid
    /// base type.
    pub(super) instance: Option<SemanticNodeId>,
}

/// One class declaration's heritage answer plus the PROOF status of that
/// answer ([`ProjectSemanticDispatch::class_heritage_reading`]): `decidable`
/// is `true` only when the declaration IS a readable class whose every
/// authored `extends` clause minted a base fact, so an empty `bases` under
/// it is a proof that the class has no heritage at all.
pub(super) struct ClassHeritageReading {
    pub(super) bases: Vec<HeritageBase>,
    pub(super) decidable: bool,
}

impl ClassHeritageReading {
    /// No readable class heritage AND no proof of its absence — an
    /// unpreparable declaration, a non-class declaration, or an `extends`
    /// clause the fact producer could not name.
    fn undecidable() -> Self {
        Self {
            bases: Vec::new(),
            decidable: false,
        }
    }
}

/// One declaration's TRANSITIVE class ancestry — the nominal derivation
/// fact behind every `instanceof` decision, answered in ONE read
/// ([`ProjectSemanticDispatch::class_heritage_ancestry`]).
///
/// The recursive walk over the base chain belongs to this authority, not
/// to its callers: an asker states a declaration and gets its whole
/// ancestry, its proof status, and the observations it must root.
pub(crate) struct ClassAncestryReading {
    /// Every declaration identity the chain reaches, base-first, each
    /// distinct declaration listed once.
    pub(super) ancestors: Vec<crate::semantic_query::DeclIdentity>,
    /// Every declaration file the walk read, at the whole-hash it was
    /// served at. The walk reads prepared decls through a `ReturnOnly`
    /// accessor that records no fact of its own, so the ASKER must fold
    /// these into its own self-roots or a warm result built on this
    /// ancestry can survive an edit to an intermediate base class.
    pub(super) observed: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot>,
    /// Whether the ancestry is a PROOF. A reachability claim needs only
    /// the hops the walk found — a truncated chain can never fabricate a
    /// derivation — but the NEGATIVE claim ("not in that family") is only
    /// as strong as the walk's completeness. `false` when any visited
    /// declaration could not be SERVED (its edits would be invisible to a
    /// warm result) or could not be READ as a class with fully-named
    /// heritage (see [`ClassHeritageReading`]).
    pub(super) decided: bool,
}

/// The dispatch-scoped memo behind [`ProjectSemanticDispatch::class_heritage_ancestry`],
/// keyed by the rooted declaration identity (canonical, owner, name).
pub(crate) type HeritageAncestryMemo = std::cell::RefCell<
    rustc_hash::FxHashMap<
        (
            verter_type_expr::OwnedStr,
            verter_type_expr::TopLevelOwnerId,
            verter_type_expr::OwnedStr,
        ),
        Arc<ClassAncestryReading>,
    >,
>;

/// Whether two declaration identities name the SAME declaration:
/// canonical, owner, and name — the content hash is generation-local and
/// never distinguishes two spellings of one declaration inside a single
/// evaluation.
pub(super) fn same_class_identity(
    a: &crate::semantic_query::DeclIdentity,
    b: &crate::semantic_query::DeclIdentity,
) -> bool {
    a.canonical_id == b.canonical_id && a.owner == b.owner && a.decl_name == b.decl_name
}

/// The `prototype` property of a class constructor type, whose type is
/// `prototype` — the class instance with `any` for each of its own type
/// parameters. The checker declares it for every class (declaration and
/// expression alike): public, writable, with no authored declaration site.
pub(super) fn class_prototype_member(
    prototype: SemanticNodeId,
    declaration_origin: Option<verter_type_expr::OwnedStr>,
) -> SurfaceMember {
    SurfaceMember {
        key: crate::semantic_query::AuthoredPropertyKey::string("prototype"),
        value: prototype,
        optional: false,
        readonly: false,
        method_kind: None,
        has_implementation_body: false,
        visibility: verter_type_expr::MemberVisibility::Public,
        excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
        spans: verter_type_expr::MemberSpans::default(),
        declaration_origin,
        declared_in_macro_type_arg: crate::semantic_query::MacroOwnBodyStamp::NEUTRAL,
        merge_role: crate::semantic_query::MergeRoleStamp::NEUTRAL,
    }
}

pub(super) use super::template_product::TemplatePiece;
use super::template_product::{TemplateConcatenation, TemplateConstituent, TemplatePlan};

/// What a template literal type's spans settle to.
enum TemplateSpans {
    /// The product, factored.
    Plan(TemplatePlan),
    /// Some expression does not settle; the template stays authored.
    Open,
    /// The template's product reaches the checker's limit (TS2590).
    TooComplex(crate::semantic_query::checker_policy::OperationRefusal),
    /// The connected-work ledger refused the construction.
    Exhausted(crate::semantic_query::PartialReasonSet),
    /// An interpolant is neither a literal nor a placeholder type (an enum
    /// member whose value is not a constant): the template is `string`.
    AnyString,
}

/// The constituents one interpolated expression contributes.
enum TemplateArgAlternatives {
    /// Every constituent, in order; none for `never`.
    Finite(Vec<TemplateConstituent>),
    /// The expression does not distribute into constituents.
    Stop(TemplateSpans),
}

/// Canonical TypeScript stringification of a literal interpolated into a
/// template-literal type (`` `${...}` ``). Typed-IR only — it reads the
/// interned [`LiteralValue`], never source text. Mirrors TS lexing: a string
/// literal contributes its text; a numeric literal its JS `Number`→string
/// form; a boolean `"true"` / `"false"`; a bigint its base-10 digits (the
/// `n` suffix is literal syntax, not part of the interpolated string).
fn literal_value_template_text(value: &LiteralValue) -> String {
    match value {
        LiteralValue::String(text) => text.clone(),
        LiteralValue::Number(number) => js_number_to_string(*number),
        LiteralValue::Boolean(flag) => if *flag { "true" } else { "false" }.to_string(),
        // `LiteralValue::BigInt` stores the signed base-10 magnitude with no
        // `n` suffix and an unsigned zero (see `TypeExpr::bigint_literal`),
        // which is exactly TS's interpolated form of a bigint literal.
        LiteralValue::BigInt(digits) => digits.clone(),
    }
}

// The canonical numeric-spelling cluster (`js_number_to_string`, the
// `integer_convention_index_key` admission fold, the ECMA-262 even
// tie-break) lives in `crate::semantic_query::index_key` — the module
// that OWNS the `IndexKey::Number` payload (`CanonicalIndexInt`,
// private field, blessed constructors only). Re-exported here because
// the dispatch submodules are its main consumers.
pub(crate) use crate::semantic_query::index_key::{
    integer_convention_index_key, js_number_to_string,
};

/// Encode a [`ProjectionReductionContext`] as a compact u32 bit
/// pattern used in the mapped-member-materialization
/// identity tuple. Layout: bits 0–1 (demand tag), bit 2 (Vue heritage
/// policy), and bits 3+ (mode tag).
#[inline]
pub(super) fn encode_projection_reduction_context_bits(
    context: crate::semantic_query::ProjectionReductionContext,
) -> u32 {
    let mode_tag: u32 = match context.mode {
        ProjectionMode::Identity => 0,
        ProjectionMode::Navigate => 1,
        ProjectionMode::Shallow => 2,
        ProjectionMode::Expanded => 3,
        ProjectionMode::Skeleton => 4,
    };
    // 2-bit demand tag (four closed demands).
    let demand_tag: u32 = match context.demand {
        ReductionDemand::Published => 0,
        ReductionDemand::StructuralTransit => 1,
        ReductionDemand::MacroObjectSurface => 2,
        ReductionDemand::VueRuntimeObjectSurface => 3,
    };
    let vue_heritage_policy_tag: u32 = match context.vue_heritage_policy {
        crate::semantic_query::VueHeritagePolicy::RetainAll => 0,
        crate::semantic_query::VueHeritagePolicy::SuppressIgnored => 1,
    };
    // Policy is value-affecting even after runtime publication demotes to
    // StructuralTransit. Keep it disjoint from both the demand and mode tags.
    (mode_tag << 3) | (vue_heritage_policy_tag << 2) | demand_tag
}

/// Test-only visibility bridge for crate-level invariant tests. Production
/// callers remain confined to the owning dispatch module.
#[cfg(any(test, feature = "test-support"))]
pub fn encode_projection_reduction_context_bits_for_tests(
    context: crate::semantic_query::ProjectionReductionContext,
) -> u32 {
    encode_projection_reduction_context_bits(context)
}

// Per-call counter (test-only). Incremented every time
// `find_longest_warm_prefix` returns `Some(_)` during a
// `ProjectSemanticDispatch::build_project_path` invocation. Used by
// `project_path_prefix_peek_short_circuits_sibling_walk` to discriminate
// pre-fix (counter never increments — peek helper not yet wired) vs
// post-fix (counter delta is exactly 1 across a sibling-prefix replay).
//
// Diagnostic-only — never read on the hot path. Tests using this
// counter MUST reset it before measuring (`with(|c| *c.borrow_mut() = 0)`)
// because the thread-local persists across tests in the same process.
#[cfg(any(test, feature = "test-support"))]
thread_local! {
    pub static PREFIX_PEEK_HITS: std::cell::RefCell<u32> = const { std::cell::RefCell::new(0) };
}

/// What [`ProjectSemanticDispatch::infer_scan`] finds under a node: its
/// `infer` declarations, and whether a nested conditional or mapped type
/// scopes binders of its own there.
#[derive(Debug, Default)]
pub(super) struct InferScan {
    pub(super) infers: Vec<SemanticNodeId>,
    pub(super) binder_scope: bool,
}

/// The dispatcher's witness that every step of the computation it is
/// building was a complete function of its state: nothing it read was a
/// partial (a refused child, a recursion carrier, a missing input) or a
/// result its memo would not keep, and the request was not cancelled. Only
/// [`ProjectSemanticDispatch::exact_steps`] and
/// [`ProjectSemanticDispatch::exact_steps_since`] mint one, and a divergence
/// is certified only with it
/// ([`CertifiedDivergence`](crate::semantic_query::checker_policy::CertifiedDivergence)).
pub(crate) struct ExactSteps {
    _proof: (),
}

/// The dispatcher's witness that a conditional tail run grows without end:
/// one argument is wrapped in the same structural constructor at every
/// step, the others pass through unchanged, and the conditional selects the
/// recursive branch for EVERY argument that constructor can hold — decided
/// by the checker's own definitely-true / definitely-false tests over the
/// wrapped type parameter, not by the steps taken so far. Only
/// [`ProjectSemanticDispatch::uniform_growth`] mints one
/// ([`CertifiedDivergence::uniform_growth`](crate::semantic_query::checker_policy::CertifiedDivergence::uniform_growth)).
pub(crate) struct UniformGrowth {
    _proof: (),
}

/// A declaration that grows one of its type parameters uniformly
/// ([`ProjectSemanticDispatch::read_growth_shape`]): its recursive branch
/// passes `wrapper` — a structural constructor over `parameter`, the type
/// parameter at clause position `index` — and the conditional selects
/// that branch for every instantiation of the wrapper.
#[derive(Debug, Clone, Copy)]
struct GrowthShape {
    index: usize,
    parameter: SemanticNodeId,
    wrapper: SemanticNodeId,
}

/// Whether a build frame's steps so far are exact: it holds no partial and
/// nothing its memo would refuse to keep.
fn frame_is_exact(frame: &super::BuildLocalTaint) -> bool {
    !frame.result_is_partial && !frame.cache_suppress
}

/// Whether the frame on `frames` producing the instantiation `claimed` at
/// `site` and every frame built on top of it are exact. The producer is
/// the frame building exactly that key at that site, as the memo claim
/// matches it; a frame building any other key or site is an ordinary frame
/// on the way. `false` when no frame on the stack produces it: frames below
/// the producer belong to its callers and are not consulted.
fn exact_since_producer(
    frames: &[super::BuildLocalTaint],
    claimed: &SemanticQueryKey,
    site: crate::semantic_query::checker_policy::TupleSplicePosition,
) -> bool {
    for frame in frames.iter().rev() {
        if !frame_is_exact(frame) {
            return false;
        }
        if frame
            .produces
            .as_ref()
            .is_some_and(|production| production.is(claimed, site))
        {
            return true;
        }
    }
    false
}

impl<'a, C: crate::resolver_core::ResolverCapabilities> ProjectSemanticDispatch<'a, C> {
    /// Native Omit key insertions and membership probes on this thread.
    #[cfg(any(test, feature = "test-support"))]
    pub fn omit_key_filter_steps_for_tests() -> usize {
        OMIT_KEY_FILTER_STEPS.with(std::cell::Cell::get)
    }

    /// Collect the observed self-roots of a set of input `SemanticNodeId`s.
    ///
    /// A node kind keyed by already-interned input nodes (`ProjectPath` /
    /// `ProjectMember` / `IndexedAccess` rooted at `base`; `KeyOf` /
    /// `MappedType` / `Conditional` / `ReduceUnion` /
    /// `ReduceIntersection` over their input nodes) produces a result
    /// whose identity transitively depends on the file content each
    /// file-derived input was lowered from. The input node's origin scope
    /// — recorded in the arena sidecar at intern time — names that file
    /// and the content version (`whole_hash`) it was observed at.
    ///
    /// This helper reads [`crate::semantic_query_memo::SemanticGraphStore::node_scope`]
    /// for each input id and yields one `(canonical, observed_whole_hash)`
    /// self-root per [`crate::semantic_query::NodeScopeId::File`]-scoped
    /// input. `Global`-scoped inputs (primitives, structural helper
    /// intermediates) and sidecar-exempt inputs contribute nothing — a
    /// fully structural result has no file self-root.
    ///
    /// The `whole_hash` is the version the input node already carries in
    /// its scope sidecar — captured when the node was interned. This
    /// helper never re-reads current content; it only projects the
    /// already-observed identity each input node carries.
    pub fn observed_self_roots_from_nodes(
        &self,
        nodes: impl IntoIterator<Item = SemanticNodeId>,
    ) -> Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> {
        let graph = self.graph();
        let mut roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> = Vec::new();
        // Few distinct roots: compared linearly until a set pays.
        let mut seen: Option<FxHashSet<crate::semantic_query_memo::ObservedGraphSelfRoot>> = None;
        for node in nodes {
            super::call_resolve::note_root_union_work(1);
            if let Some(NodeScopeId::File {
                canonical_id,
                whole_hash,
                ..
            }) = graph.node_scope(node)
            {
                let root = (canonical_id, whole_hash);
                let fresh = match &mut seen {
                    Some(seen) => seen.insert(root.clone()),
                    None => !roots.contains(&root),
                };
                if fresh {
                    roots.push(root);
                    if seen.is_none() && roots.len() > 16 {
                        seen = Some(roots.iter().cloned().collect());
                    }
                }
            }
        }
        roots
    }

    /// Collect the observed self-roots of a set of input nodes
    /// TRANSITIVELY: like [`Self::observed_self_roots_from_nodes`], but a
    /// `Global`-scoped input is walked down to the `File`-scoped leaves it
    /// is composed of, so a scope-less composite (a canonical union /
    /// intersection over file-derived arms, a structural object shell, an
    /// anonymous signature over file-derived parameter types) roots on
    /// every file its identity actually depends on.
    ///
    /// The walk is bounded, deterministic and deduplicated: depth-first in
    /// child order, each node visited once, at most
    /// [`SELF_ROOT_WALK_CAP`] nodes. A `File`-scoped node contributes its
    /// `(canonical, observed_whole_hash)` and is NOT descended — its scope
    /// already pins the content version everything lowered under it was
    /// observed at, and a child lowered from another file carries its own
    /// scope in its own interned identity. Structural leaves (primitives,
    /// literals, references) contribute nothing.
    ///
    /// Returns `Err` when the root set could NOT be established: the walk
    /// exceeded its cap, reached a node with no payload, or reached a
    /// scope-less payload whose children are sealed and unenumerable. An
    /// incomplete root set is never a partial answer — the caller routes
    /// the result `ReturnOnly` under the incomplete-self-rooting rule.
    ///
    /// Like its non-transitive sibling this never re-reads current
    /// content; it only projects the identities the input nodes already
    /// carry.
    pub(super) fn transitive_self_roots_from_nodes(
        &self,
        nodes: impl IntoIterator<Item = SemanticNodeId>,
    ) -> Result<
        Vec<crate::semantic_query_memo::ObservedGraphSelfRoot>,
        crate::cache_runtime::NonAdmissionReason,
    > {
        let graph = self.graph();
        let mut roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> = Vec::new();
        let mut visited: FxHashSet<SemanticNodeId> = FxHashSet::default();
        let mut seen_roots = FxHashSet::default();
        // Depth-first from the LAST pushed node; inputs are pushed in
        // reverse so the first input is walked first.
        let mut stack: Vec<SemanticNodeId> = nodes.into_iter().collect();
        stack.reverse();
        let mut children: Vec<SemanticNodeId> = Vec::new();
        while let Some(node) = stack.pop() {
            if !visited.insert(node) {
                continue;
            }
            if visited.len() > SELF_ROOT_WALK_CAP {
                return Err(crate::cache_runtime::NonAdmissionReason::UnresolvedProvenance);
            }
            match graph.node_scope(node) {
                Some(NodeScopeId::File {
                    canonical_id,
                    whole_hash,
                    ..
                }) => {
                    let root = (canonical_id, whole_hash);
                    if seen_roots.insert(root.clone()) {
                        roots.push(root);
                    }
                }
                Some(NodeScopeId::Global) => {
                    let Some(data) = graph.node_data(node) else {
                        return Err(crate::cache_runtime::NonAdmissionReason::UnresolvedProvenance);
                    };
                    children.clear();
                    if data.for_each_child(|child| children.push(child))
                        != crate::semantic_query::ChildWalk::Enumerated
                    {
                        return Err(crate::cache_runtime::NonAdmissionReason::UnresolvedProvenance);
                    }
                    stack.extend(children.iter().rev().copied());
                }
                None => {
                    return Err(crate::cache_runtime::NonAdmissionReason::UnresolvedProvenance);
                }
            }
        }
        Ok(roots)
    }

    /// Resolve a top-level declaration lookup via the host's shallow state.
    ///
    /// Declaration identity is carried by the `Instantiate` key's
    /// `DeclIdentity` field directly — no separate `DeclAnchor` node is
    /// interned. This builder validates that the name exists in the
    /// shallow state, records the file scope in the sidecar, and returns
    /// an `Opaque(Miss)` placeholder node; the actual identity is carried
    /// by the caller via the key.
    pub(super) fn build_resolve_decl(
        &self,
        key: &ResolveDeclKey,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        verter_audit::attribute_scope!(ResolveDecl);
        // Self-version rooting: observe the scope canonical.s
        // `IndexedReady` ONCE through `ensure_indexed_ready_serve` — the
        // overlay-aware host accessor (a `SessionResolverContext`
        // observes the overlay artifact, not the base file). The
        // single observed artifact roots both the node.s
        // `NodeScopeId::File` and the memo entry.s self-root
        // `FileWholeHash` on `indexed.whole_hash`, and its
        // `shallow_state` is the shallow inventory this builder reads
        // — value basis and self-root descend from one observation, so
        // a concurrent edit cannot tear them. `shallow_file_state` is
        // deliberately not used: it reads the base file hash under an
        // overlay and re-reads content outside the single observation.
        let indexed = match self
            .ctx
            .ensure_indexed_ready_serve(key.scope.canonical_id.as_ref())
            .map(|serve| serve.indexed)
        {
            Some(indexed) => indexed,
            None => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
        };
        let shallow = &indexed.shallow_state;
        let observed_hash = indexed.whole_hash;

        // Local PRESENCE through the CENTRALIZED effective header lookup — a
        // user/synthesized declaration first, then (rune-module-gated) the
        // ambient rune inventory, so a Svelte rune module's `$state`/`$derived`/
        // `$effect`/`$inspect` is treated as locally declared and resolves at
        // this dispatch surface. A plain `.ts` is unaffected (the effective
        // lookup is rune-module-gated, so it reduces to the header-index probe).
        // No per-site rune branch — the single authority lives on
        // `ShallowFileState`.
        let has_type_symbol =
            shallow.effective_type_header_present_in(key.scope.owner, key.name.as_ref());
        let has_value_symbol =
            shallow.effective_value_header_present_in(key.scope.owner, key.name.as_ref());
        let is_ordinary = key.scope.owner == verter_type_expr::TopLevelOwnerId::ordinary_file();
        let has_export = is_ordinary && shallow.exports.contains_key(key.name.as_ref());
        let has_import_local = shallow
            .import_target_in(key.scope.owner, key.name.as_ref())
            .is_some();
        // A `declare global { ... }` declaration is not on the file surface but
        // IS resolvable as the merged global declaration (the prepared-decl
        // builder falls back to the global augmentation inventory), and so is
        // the type of the one `declare module "…"` block declaring the name.
        // An owner's global-augmentation scope declares exactly its own
        // `declare global` members.
        let has_global_augmentation = if key.scope.owner.is_global_augmentation() {
            shallow.declares_global_augmentation_type_in(key.scope.owner, key.name.as_ref())
        } else {
            is_ordinary
                && shallow
                    .type_fallback_augmentation_scope(key.scope.owner, key.name.as_ref())
                    .is_some()
        };

        // A name DECLARED in this file (type / value symbol, or a
        // `declare global` contribution) resolves here. A name that is
        // only re-exported / imported through this file resolves at its
        // DEFINING file instead — see the fall-through below.
        let has_local_declaration = has_type_symbol || has_value_symbol || has_global_augmentation;

        if !has_local_declaration {
            // Re-export fall-through. A barrel reaches the declaration via
            // `export * from './base'` (no direct symbol / named export),
            // `export { X } from './base'`, or `import { X } ...; export
            // { X }`. In every shape the declaration is authored elsewhere:
            // follow the export graph (the shared route resolver already
            // implements direct > aliased > wildcard precedence) to the
            // defining `(canonical, name)` and resolve THAT declaration, so
            // the declaration's scope — and every member's
            // `declaration_origin`, which anchors typeinfo JSDoc enrichment
            // — labels the file the author wrote it in, not the barrel hop.
            if has_export || has_import_local || (is_ordinary && shallow.has_wildcard_reexports()) {
                let scope_payload = self
                    .ctx
                    .prepared_decl_bundle(key.scope.canonical_id.as_ref())
                    .map(|bundle| {
                        crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                            &bundle,
                            key.scope.owner,
                        )
                    });
                if let Some(target) =
                    crate::resolver_core::bare_name_resolve::resolve_bare_name_in_scope(
                        self.ctx,
                        self,
                        key.scope.canonical_id.as_ref(),
                        key.scope.owner,
                        scope_payload.as_ref(),
                        key.name.as_ref(),
                    )
                {
                    if target.canonical_id.as_ref() != key.scope.canonical_id.as_ref()
                        || target.owner != key.scope.owner
                        || target.symbol_name.as_ref() != key.name.as_ref()
                    {
                        let resolved_key = ResolveDeclKey {
                            scope: crate::semantic_query::ScopeId {
                                canonical_id: target.canonical_id.clone(),
                                owner: target.owner,
                                local_scope: None,
                                binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(
                                    target.owner,
                                ),
                            },
                            name: target.symbol_name.clone(),
                        };
                        // Re-root the barrel-resolved entry on BOTH the
                        // barrel file (whose export surface selected the
                        // target) AND the resolved declaration's own
                        // self-roots, so a content edit to EITHER the
                        // barrel's re-export clause or the defining file
                        // misses the warm read.
                        let inner = self.build_resolve_decl(&resolved_key);
                        let barrel_root = (key.scope.canonical_id.clone(), observed_hash);
                        let mut roots = inner.observed_self_roots.clone();
                        if !roots
                            .iter()
                            .any(|(c, h)| *c == barrel_root.0 && *h == barrel_root.1)
                        {
                            roots.push(barrel_root);
                        }
                        return inner.with_observed_self_roots(roots);
                    }
                }
            }
            if !(has_export || has_import_local) {
                return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
            }
            // The export graph could not resolve the defining site (e.g. an
            // unresolvable specifier): fall through to the legacy
            // placeholder scoped to this file, whose prepared-declaration
            // builder follows the import lazily.
        }

        // Record the declaration's origin scope in the sidecar so
        // dispatch builders reached from this placeholder can route
        // per-base-scope lookups through the scope's declaration-scope
        // payload.
        let scope = NodeScopeId::File {
            canonical_id: key.scope.canonical_id.clone(),
            owner: key.scope.owner,
            whole_hash: observed_hash,
            local_scope: key
                .scope
                .local_scope
                .map(|ordinal| NodeLocalScopeId::Lexical(LocalScopeId(ordinal))),
        };
        let signature = self.dep_signature_for(&key.scope.canonical_id, observed_hash);
        // Return a DeclPlaceholder that carries enough identity for
        // callers to construct Instantiate keys.
        let node_id = self.graph().intern_node_with_scope(
            SemanticNodeData::Opaque(QueryError::DeclPlaceholder {
                canonical_id: key.scope.canonical_id.clone(),
                owner: key.scope.owner,
                name: key.name.clone(),
                whole_hash: observed_hash,
            }),
            scope,
        );
        crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node_id),
            signature,
        ))
        .with_observed_self_roots([(key.scope.canonical_id.clone(), observed_hash)])
    }

    /// `typeof`-rooted declaration lookup. Shape mirrors [`Self::build_resolve_decl`]
    /// but routes through the shallow value-symbol space so the result is
    /// keyed by the value binding's identity.
    ///
    /// `context` is the caller's projection-reduction demand: the value's
    /// annotation / object shape / signature surface / enum surface lowers
    /// AT that demand, so a `Skeleton` / `Navigate` / `Shallow` caller gets
    /// carrier-preserving lowering (member-value type references intern as
    /// `DeclRef` / `InstantiationRef` carriers) while a genuine `Expanded`
    /// caller keeps eager lowering. The overload-visibility projection rule
    /// below is mode-independent semantics and applies in every mode.
    pub(super) fn build_typeof(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let _site = self
            .checking_site_scope(crate::semantic_query::checker_policy::TupleSplicePosition::Type);
        self.build_typeof_suspending(value_root, path, context, None)
    }

    /// Begin a `typeof` build on the continuation runtime: answer it at
    /// once, or — when the value's type is lowered from its authored value
    /// position (its annotation, its inferred initializer or its
    /// const-object shape) — begin that lowering as a projection that stops
    /// at each instantiation and `typeof` it reaches, the build
    /// [`Self::drain_typeof`] carries on. A chain of instantiations the
    /// annotation names (an interface whose heritage nests a hundred
    /// levels), or of values each initialized from the one before, then
    /// waits in heap-owned frames instead of nesting natively.
    pub(super) fn begin_typeof(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> TypeofStart {
        let _site = self
            .checking_site_scope(crate::semantic_query::checker_policy::TupleSplicePosition::Type);
        let mut suspended = None;
        let output = self.build_typeof_suspending(value_root, path, context, Some(&mut suspended));
        match suspended {
            Some(build) => TypeofStart::Build(build),
            None => TypeofStart::Done(Box::new(output)),
        }
    }

    /// Lower a value's type from the authored value position `locator` —
    /// its annotation, its inferred initializer or its const-object shape —
    /// or, on the continuation runtime (`suspend`), begin that lowering as a
    /// projection that stops at each instantiation and `typeof` it reaches,
    /// the build [`Self::drain_typeof`] carries on. `None` means the build
    /// suspended: a chain of values each typed by the one before then waits
    /// in heap-owned frames instead of nesting natively.
    #[allow(clippy::too_many_arguments)]
    fn lower_typeof_body_or_suspend(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
        suspend: Option<&mut Option<Box<TypeofBuild>>>,
        lowering: TypeofBodyScope<'_>,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        observed_hash: verter_session_query::analysis::types::Hash16,
    ) -> Option<SemanticNodeId> {
        let TypeofBodyScope {
            prepared,
            env,
            scope,
            scope_payload,
            shadowing,
            mut substitutions,
        } = lowering;
        let Some(suspended) = suspend else {
            return Some(self.lower_located_body_with_provenance(
                locator,
                verter_session_query::declarations::TypeDeclKind::Alias,
                &[],
                &prepared.name_resolution,
                &env,
                &scope,
                scope_payload.as_ref(),
                &shadowing,
                &mut substitutions,
                context,
            ));
        };
        let mut build = Box::new(TypeofBuild {
            redirects: Vec::new(),
            prepared: prepared.clone(),
            env,
            scope,
            scope_payload,
            shadowing,
            substitutions,
            self_value: None,
            body: TypeofBody::Unstarted,
            then: TypeofThen::Value,
            value_root: value_root.clone(),
            path: verter_type_expr::OwnedSlice::from(path),
            context,
            observed_hash,
        });
        self.begin_typeof_body(&mut build, prepared.clone(), locator);
        *suspended = Some(build);
        None
    }

    /// Begin lowering the next member position of `build`'s member path as
    /// its current body: a projection that stops at each instantiation and
    /// `typeof` it reaches. `false` once every position is lowered.
    fn begin_next_member_body(&self, build: &mut TypeofBuild) -> bool {
        let TypeofThen::Member(member) = &mut build.then else {
            unreachable!("a member lowering continues a member path's build")
        };
        let Some((ordinal, facts)) = member.members.positions.pop_front() else {
            return false;
        };
        member.current = Some(facts);
        let locator = member.members.locator(ordinal);
        build.self_value = match &locator {
            verter_type_expr::locators::AuthoredBodyLocator::DeclBody(slot) => {
                Some(slot.anchor.clone())
            }
            _ => None,
        };
        build.body = TypeofBody::Lowering(self.begin_located_body_lowering(
            locator,
            verter_session_query::declarations::TypeDeclKind::Alias,
            &member.members.class_type_params,
            &build.env,
            &build.scope,
            &mut build.substitutions,
            member.members.context,
            &[],
            super::locator_view_worklist::ProjectionSeam::suspending(),
        ));
        true
    }

    /// The output of a member path's `typeof` whose first member `own` was
    /// lowered where `declaring` declares it: the rest of the path read from
    /// it, rooted on the declaring file's content version as the composed
    /// surface would be.
    #[allow(clippy::too_many_arguments)]
    fn member_typeof_output(
        &self,
        own: SemanticNodeId,
        base_partial: bool,
        declaring: &verter_type_expr::OwnedStr,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        observed_hash: verter_session_query::analysis::types::Hash16,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let mut output = self.project_typeof_path(own, path, context, observed_hash, value_root);
        output.fold_partial(base_partial);
        if declaring.as_ref() == value_root.scope.canonical_id.as_ref() {
            return output;
        }
        match self.ctx.ensure_indexed_ready_serve(declaring.as_ref()) {
            Some(serve) => {
                output.with_observed_self_roots([(declaring.clone(), serve.indexed.whole_hash)])
            }
            None => {
                output.cache_suppress = true;
                output
            }
        }
    }

    /// Begin lowering `locator`, a body `prepared` declares, as `build`'s
    /// current body: a projection that stops at each instantiation and
    /// `typeof` it reaches.
    fn begin_typeof_body(
        &self,
        build: &mut TypeofBuild,
        prepared: verter_retention::heap_size::OwnedValue<
            verter_session_query::type_solver::PreparedValueDecl,
        >,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
    ) {
        build.self_value = match &locator {
            verter_type_expr::locators::AuthoredBodyLocator::DeclBody(slot)
                if slot.anchor.space == verter_type_expr::locators::LocatorSymbolSpace::Value =>
            {
                Some(slot.anchor.clone())
            }
            _ => None,
        };
        build.prepared = prepared;
        build.body = TypeofBody::Lowering(self.begin_located_body_lowering(
            locator,
            verter_session_query::declarations::TypeDeclKind::Alias,
            &[],
            &build.env,
            &build.scope,
            &mut build.substitutions,
            build.context,
            &[],
            super::locator_view_worklist::ProjectionSeam::suspending(),
        ));
    }

    /// Lower a function value's signatures — its own declaration's, then
    /// every declaration it merges — or, on the continuation runtime
    /// (`suspend`), begin lowering them one at a time as projections that
    /// stop at each instantiation and `typeof` they reach, the build
    /// [`Self::drain_typeof`] carries on: a chain of functions each typed by
    /// the one before (`declare function h1(): ReturnType<typeof h0>`) then
    /// waits in heap-owned frames instead of nesting natively.
    #[allow(clippy::too_many_arguments)]
    fn lower_value_signatures_or_suspend(
        &self,
        mut signatures: SignatureLowering,
        suspend: Option<&mut Option<Box<TypeofBuild>>>,
        lowering: TypeofBodyScope<'_>,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        observed_hash: verter_session_query::analysis::types::Hash16,
    ) -> SignaturesLowered {
        let TypeofBodyScope {
            prepared,
            env,
            scope,
            scope_payload,
            shadowing,
            mut substitutions,
        } = lowering;
        let Some(suspended) = suspend else {
            loop {
                match self.next_value_signature(&mut signatures) {
                    None => return SignaturesLowered::Miss,
                    Some(None) => {
                        return SignaturesLowered::Lowered(
                            self.finish_value_signatures(signatures, &scope, context),
                        )
                    }
                    Some(Some(job)) => {
                        let node = self.lower_located_body_with_provenance(
                            job.locator,
                            verter_session_query::declarations::TypeDeclKind::Alias,
                            &[],
                            &job.prepared.name_resolution,
                            &env,
                            &scope,
                            scope_payload.as_ref(),
                            &shadowing,
                            &mut substitutions,
                            context,
                        );
                        let node = self.normalize_widened_object_literals(
                            node,
                            self.nullability_for(job.prepared.root_identity.canonical_id.as_ref()),
                        );
                        signatures.record(node);
                    }
                }
            }
        };
        let job = match self.next_value_signature(&mut signatures) {
            None => return SignaturesLowered::Miss,
            Some(None) => {
                return SignaturesLowered::Lowered(
                    self.finish_value_signatures(signatures, &scope, context),
                )
            }
            Some(Some(job)) => job,
        };
        let mut build = Box::new(TypeofBuild {
            redirects: Vec::new(),
            prepared: prepared.clone(),
            env,
            scope,
            scope_payload,
            shadowing,
            substitutions,
            self_value: None,
            body: TypeofBody::Unstarted,
            then: TypeofThen::Signatures(Box::new(signatures)),
            value_root: value_root.clone(),
            path: verter_type_expr::OwnedSlice::from(path),
            context,
            observed_hash,
        });
        self.begin_typeof_body(&mut build, job.prepared, job.locator);
        *suspended = Some(build);
        SignaturesLowered::Suspended
    }

    /// Apply each imported qualified head after its suspended value finishes.
    /// The value itself keeps lowering under its declaring scope.
    pub(super) fn drain_typeof(
        &self,
        build: &mut TypeofBuild,
        delivery: Option<super::query_frames::FrameDelivery>,
    ) -> InstantiatePoll {
        match self.drain_typeof_body(build, delivery) {
            InstantiatePoll::Done(output) => {
                let mut output = *output;
                for redirect in &build.redirects {
                    output = self.finish_typeof_redirect(output, redirect);
                }
                InstantiatePoll::Done(Box::new(output))
            }
            need => need,
        }
    }

    fn finish_typeof_redirect(
        &self,
        mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput,
        redirect: &TypeofRedirect,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        // A nominal carrier's head is the reference this file wrote
        // (`Ns.A_KIND`), never the declaration the import reached, whose
        // name is not in scope here; the declaring identity rides the
        // payload either way.
        if let QueryResult::Value(node) = output.result {
            let authored = self.graph().node_data(node).and_then(|data| {
                let (root, head_path) = data.typeof_head()?;
                let identity = data.typeof_nominal_identity()?;
                (*root == redirect.declaring && head_path.is_empty()).then(|| identity.clone())
            });
            if let Some(identity) = authored {
                output.result =
                    QueryResult::Value(
                        self.intern_nominal_typeof(
                            redirect.authored.clone(),
                            redirect.path.clone(),
                            identity,
                            NodeScopeId::File {
                                canonical_id: redirect.authored.scope.canonical_id.clone(),
                                owner: redirect.authored.scope.owner,
                                whole_hash: redirect.observed_hash,
                                local_scope: redirect.authored.scope.local_scope.map(|ordinal| {
                                    NodeLocalScopeId::Lexical(LocalScopeId(ordinal))
                                }),
                            },
                        ),
                    );
            }
        }
        // A member read through an import also depends on this file's
        // import binding.
        output.with_observed_self_roots([(
            redirect.authored.scope.canonical_id.clone(),
            redirect.observed_hash,
        )])
    }

    /// Carry a suspended `typeof` build on: its current body's projection
    /// resumes with `delivery`, the instantiation or `typeof` it waited on
    /// (or its initializer's evaluation resumes with the `typeof` of the
    /// value it named), and either needs another, begins the value's next
    /// signature, or completes the build's output.
    fn drain_typeof_body(
        &self,
        build: &mut TypeofBuild,
        delivery: Option<super::query_frames::FrameDelivery>,
    ) -> InstantiatePoll {
        let _site = self.checking_site_scope(build.checking_site());
        let mut delivery = match &mut build.body {
            TypeofBody::Unstarted => unreachable!("a build begins its first body before it drains"),
            TypeofBody::Lowering(_) => {
                delivery.map(|delivery| self.consume_frame_delivery(delivery))
            }
            TypeofBody::Expression(run) => {
                let source = build
                    .prepared
                    .type_annotation
                    .expression_source
                    .as_ref()
                    .expect("an initializer evaluating has an expression source");
                let evaluated = match self.drain_semantic_expression_source(source, run, delivery) {
                    super::flow_return::ExpressionSourcePoll::Need(key) => {
                        return InstantiatePoll::Need(key)
                    }
                    super::flow_return::ExpressionSourcePoll::Done(evaluated) => evaluated,
                };
                let owner = run.owner();
                let Some(node) =
                    self.expression_source_value_type(&build.prepared, source, owner, evaluated)
                else {
                    return InstantiatePoll::Done(Box::new(
                        (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
                    ));
                };
                let node = self.normalize_inferred_value_type(&build.prepared, node);
                let output = self.typeof_output(
                    node,
                    false,
                    &build.value_root,
                    &build.path,
                    build.context,
                    build.observed_hash,
                );
                return InstantiatePoll::Done(Box::new(self.with_augmentation_roots(
                    output,
                    Vec::new(),
                    false,
                )));
            }
        };
        loop {
            let TypeofBuild {
                prepared,
                env,
                scope,
                scope_payload,
                shadowing,
                substitutions,
                self_value,
                body,
                ..
            } = &mut *build;
            let TypeofBody::Lowering(body) = body else {
                unreachable!("a build lowering a body keeps lowering bodies")
            };
            let poll = self.drain_located_body_lowering(
                body,
                &crate::project_semantic_dispatch::locator_view::LocatorViewInputs {
                    env,
                    scope,
                    name_resolution: &prepared.name_resolution,
                    scope_payload: scope_payload.as_ref(),
                    shadowing,
                    authored_resolution_debt: None,
                    self_value: self_value.as_ref(),
                },
                substitutions,
                delivery.take(),
            );
            let node = match poll {
                BodyPoll::Need(key) => return InstantiatePoll::Need(key),
                BodyPoll::Done(node, _) => node,
            };
            let (node, roots, unobservable) = match &mut build.then {
                TypeofThen::Value => (
                    self.normalize_inferred_value_type(
                        &build.prepared,
                        self.widen_declared_read_positions(node, &build.prepared),
                    ),
                    Vec::new(),
                    false,
                ),
                TypeofThen::Member(member) => {
                    let facts = member
                        .current
                        .take()
                        .expect("a member lowering records the position it lowered");
                    member.members.record(facts, node);
                    if self.begin_next_member_body(build) {
                        continue;
                    }
                    let TypeofThen::Member(member) =
                        std::mem::replace(&mut build.then, TypeofThen::Value)
                    else {
                        unreachable!("the build lowers member positions")
                    };
                    let MemberLowering {
                        members, declaring, ..
                    } = *member;
                    let own = self.finish_value_members(members, build.scope.clone());
                    let own = self.widen_declared_read_positions(own, &build.prepared);
                    return InstantiatePoll::Done(Box::new(self.member_typeof_output(
                        own,
                        false,
                        &declaring,
                        &build.value_root,
                        &build.path,
                        build.context,
                        build.observed_hash,
                    )));
                }
                TypeofThen::Signatures(signatures) => {
                    let node = self.normalize_widened_object_literals(
                        node,
                        self.nullability_for(build.prepared.root_identity.canonical_id.as_ref()),
                    );
                    signatures.record(node);
                    match self.next_value_signature(signatures) {
                        Some(Some(job)) => {
                            self.begin_typeof_body(build, job.prepared, job.locator);
                            continue;
                        }
                        None => {
                            return InstantiatePoll::Done(Box::new(
                                (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
                            ))
                        }
                        Some(None) => {
                            let TypeofThen::Signatures(signatures) =
                                std::mem::replace(&mut build.then, TypeofThen::Value)
                            else {
                                unreachable!("the build lowers signatures")
                            };
                            self.finish_value_signatures(*signatures, &build.scope, build.context)
                        }
                    }
                }
            };
            let output = self.typeof_output(
                node,
                false,
                &build.value_root,
                &build.path,
                build.context,
                build.observed_hash,
            );
            return InstantiatePoll::Done(Box::new(self.with_augmentation_roots(
                output,
                roots,
                unobservable,
            )));
        }
    }

    /// The output of a `typeof` whose value has the type `node`: the
    /// value's own type rooted on its declaring file, or the member `path`
    /// reads from it.
    fn typeof_output(
        &self,
        node: SemanticNodeId,
        composed_partial: bool,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        observed_hash: verter_session_query::analysis::types::Hash16,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        if path.is_empty() {
            let signature = self.dep_signature_for(&value_root.scope.canonical_id, observed_hash);
            let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(node),
                signature,
            ))
            .with_observed_self_roots([(value_root.scope.canonical_id.clone(), observed_hash)]);
            // Two-signal fold: a partial composed class-surface read surfaces as
            // a partial `TypeOf` result (it would otherwise pass through with
            // `result_is_partial = false`).
            output.fold_partial(composed_partial);
            output.with_positional_guarantee()
        } else {
            let mut output =
                self.project_typeof_path(node, path, context, observed_hash, value_root);
            output.fold_partial(composed_partial);
            output
        }
    }

    /// [`Self::build_typeof`], which with `suspend` stops where the value's
    /// type lowers from its authored value position (its annotation, its
    /// inferred initializer, its const-object shape): it hands that lowering
    /// over in `suspend` for [`Self::drain_typeof`] to carry on, and its own
    /// output is then not the answer.
    fn build_typeof_suspending(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        mut suspend: Option<&mut Option<Box<TypeofBuild>>>,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        // Telemetry for the typeof traversal site.
        verter_audit::observe!(C::Observe => on self.observation.observer.as_deref() => |observer| {
            observer.record_event(verter_audit::AuditEvent::BuildTypeofCall);
        });
        // Self-version rooting: observe the value-root scope
        // canonical.s `IndexedReady` ONCE through the overlay-aware
        // `ensure_indexed_ready_serve` accessor. The single observed
        // artifact roots both the node.s `NodeScopeId::File` and the
        // memo entry.s self-root `FileWholeHash` on
        // `indexed.whole_hash`; its `shallow_state` is the shallow
        // inventory this builder reads — value basis and self-root
        // descend from one observation.
        let indexed = match self.transaction_indexed_record(value_root.scope.canonical_id.as_ref())
        {
            Some(indexed) => indexed,
            None => {
                // Telemetry: prepared-value miss site.
                verter_audit::observe!(C::Observe => on self.observation.observer.as_deref() => |observer| {
                    observer.record_event(verter_audit::AuditEvent::BuildTypeofPreparedValueMiss);
                });
                return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
            }
        };
        let shallow = &indexed.shallow_state;
        let observed_hash = indexed.whole_hash;
        // A value rooted while lowering an ambient namespace body keeps the
        // exact module scope. Same-named namespaces in other modules and
        // file declarations cannot replace this inventory entry.
        let ambient_scope = Self::ambient_value_scope(&value_root.scope, &shallow.headers);

        // An `import X = N.M` alias names what `N.M` names: a path it heads
        // reads from the entity's qualified path.
        if value_root.scope.local_scope.is_none() {
            if let Some(expanded) = shallow
                .headers
                .expand_namespace_alias(value_root.scope.owner, value_root.name.as_ref())
            {
                let mut segments = expanded.split('.').map(verter_type_expr::OwnedStr::from);
                let root = segments
                    .next()
                    .expect("a qualified name has a first segment");
                let aliased_path: Vec<verter_type_expr::OwnedStr> =
                    segments.chain(path.iter().cloned()).collect();
                let aliased_root = ValueRootKey {
                    scope: value_root.scope.clone(),
                    name: root,
                };
                return self.build_typeof_suspending(
                    &aliased_root,
                    &aliased_path,
                    context,
                    suspend,
                );
            }
            // An import of a module's `export import X = N.M` alias reads
            // what the alias names, in the module that declares it.
            if let Some(alias) = crate::resolver_core::bare_name_resolve::imported_namespace_alias(
                self.ctx,
                value_root.scope.canonical_id.as_ref(),
                value_root.scope.owner,
                value_root.name.as_ref(),
            ) {
                let declaring = ValueRootKey {
                    scope: crate::semantic_query::ScopeId {
                        canonical_id: verter_type_expr::OwnedStr::from(alias.module.as_str()),
                        owner: alias.owner,
                        local_scope: None,
                        binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(
                            alias.owner,
                        ),
                    },
                    name: verter_type_expr::OwnedStr::from(alias.name.as_str()),
                };
                let output =
                    self.build_typeof_suspending(&declaring, path, context, suspend.as_deref_mut());
                let redirect = TypeofRedirect {
                    declaring,
                    authored: value_root.clone(),
                    path: verter_type_expr::OwnedSlice::default(),
                    observed_hash,
                };
                if let Some(Some(build)) = suspend {
                    build.redirects.push(redirect);
                    return output;
                }
                return self.finish_typeof_redirect(output, &redirect);
            }
        }

        // A namespace member path: a namespace block has no value surface
        // the path could walk, and its members register under their
        // QUALIFIED names, so `typeof N.M.f` reads the value `N.M.f` names
        // — a member the namespace exports: read from outside its body, a
        // private one is no member of it. A function-local root is never a
        // namespace (a namespace declares only at file or namespace scope).
        if value_root.scope.local_scope.is_none() {
            let mut joined = value_root.name.to_string();
            for (split, segment) in path.iter().enumerate() {
                joined.push('.');
                joined.push_str(segment);
                let declared = match ambient_scope {
                    Some(augmentation) => shallow
                        .headers
                        .augmentation_value_header_in(augmentation, value_root.scope.owner, &joined)
                        .is_some(),
                    None => matches!(
                        shallow.visible_value_binding(value_root.scope.owner, &joined),
                        Some(verter_session_query::inputs::shallow::LexicalValueBinding::Local(_))
                    ),
                };
                if declared
                    && shallow
                        .headers
                        .namespace_member_is_exported(value_root.scope.owner, &joined)
                {
                    let member_root = ValueRootKey {
                        scope: value_root.scope.clone(),
                        name: verter_type_expr::OwnedStr::from(joined),
                    };
                    return self.build_typeof_suspending(
                        &member_root,
                        &path[split + 1..],
                        context,
                        suspend,
                    );
                }
            }
        }

        // Local PRESENCE through the CENTRALIZED effective header lookup so a
        // rune module's ambient `$state`/`$derived`/… value (and the rune
        // namespace types) is seen as locally declared at the `typeof`-rooted
        // dispatch surface. Plain `.ts` is unaffected (rune-module-gated).
        let visible_value = ambient_scope
            .is_none()
            .then(|| {
                shallow.visible_value_binding(value_root.scope.owner, value_root.name.as_ref())
            })
            .flatten();
        // A member of one of the file's `declare module "…"` blocks is a
        // value the root's identity names too (an import of the ambient
        // module reaches it here).
        let has_value = match ambient_scope {
            Some(augmentation) => shallow
                .headers
                .augmentation_value_header_in(
                    augmentation,
                    value_root.scope.owner,
                    value_root.name.as_ref(),
                )
                .is_some(),
            None => {
                matches!(
                    visible_value,
                    Some(verter_session_query::inputs::shallow::LexicalValueBinding::Local(_))
                ) || (visible_value.is_none()
                    && matches!(
                        shallow.value_fallback_augmentation_scope(
                            value_root.scope.owner,
                            value_root.name.as_ref()
                        ),
                        Some(verter_session_query::declarations::AugmentationScopeKind::Module(_))
                    ))
            }
        };
        let has_import_local = matches!(
            visible_value,
            Some(verter_session_query::inputs::shallow::LexicalValueBinding::Import(_))
        );
        // Namespace-qualified root: `Ns.Member` where `Ns` is an import
        // alias (`import * as Ns from './m'`). The shallow state indexes
        // only the top-level alias; the dotted name itself never appears
        // as a literal symbol. Defer resolution to `resolve_bare_name_in_scope`,
        // which handles the namespace-member case via
        // `resolve_namespace_member_from_facts`.
        let has_namespace_prefix = value_root.name.split_once('.').is_some_and(|(prefix, _)| {
            matches!(
                shallow.visible_value_binding(value_root.scope.owner, prefix),
                Some(verter_session_query::inputs::shallow::LexicalValueBinding::Import(_))
            )
        });

        // A namespace's value member is its own declaration, named by its
        // qualified path (`NS.Inner.f`): the longest prefix of the path that
        // names one reads the rest of the path from it. The namespace a
        // function or class merges with contributes its members this way too.
        let unbound = !(has_value || has_import_local || has_namespace_prefix);
        if let Some((member_root, consumed)) = ambient_scope
            .is_none()
            .then(|| self.qualified_value_member_root(value_root, path, shallow, unbound))
            .flatten()
        {
            let output = self.build_typeof_suspending(
                &member_root,
                &path[consumed..],
                context,
                suspend.as_deref_mut(),
            );
            if member_root.scope.canonical_id == value_root.scope.canonical_id {
                return output;
            }
            let redirect = TypeofRedirect {
                declaring: member_root,
                authored: value_root.clone(),
                path: verter_type_expr::OwnedSlice::from(&path[..consumed]),
                observed_hash,
            };
            if let Some(Some(build)) = suspend {
                build.redirects.push(redirect);
                return output;
            }
            return self.finish_typeof_redirect(output, &redirect);
        }
        // A namespace import, or a namespace this file declares, read whole
        // is its module object; the rest of the path reads its properties.
        if !has_value {
            if let Some((object, roots)) = self.module_object_of_root(value_root, shallow, context)
            {
                let output = if path.is_empty() {
                    crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                        QueryResult::Value(object),
                        self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
                    ))
                } else {
                    self.project_typeof_path(object, path, context, observed_hash, value_root)
                };
                return output.with_observed_self_roots(
                    std::iter::once((value_root.scope.canonical_id.clone(), observed_hash))
                        .chain(roots),
                );
            }
        }
        // A name no value scope declares or imports is read in the program's GLOBAL
        // scope: `globalThis` is the global object, and any other name its
        // global value declaration. The global root replaces the bare-name
        // resolution below; the segments `globalThis` consumed leave `path`.
        let mut global_via_global_this = false;
        // A function declared in several files: every later file's
        // declaration, whose overloads join the first's.
        let mut global_peers: Vec<ResolvedRootIdentity> = Vec::new();
        let (global_root, path) = if has_value || has_import_local || has_namespace_prefix {
            (None, path)
        } else if value_root.name.as_ref() == "globalThis" {
            // Every leading `globalThis` segment is the global object again.
            let mut rest = path;
            while rest
                .first()
                .is_some_and(|segment| segment.as_ref() == "globalThis")
            {
                rest = &rest[1..];
            }
            // The whole global object spans every global of the program
            // AND of its libs, which this lane does not enumerate: it
            // stays the deferred `typeof globalThis` carrier, whose
            // members a projection reads through this same root.
            let Some((member, rest)) = rest.split_first() else {
                let scope = NodeScopeId::File {
                    canonical_id: value_root.scope.canonical_id.clone(),
                    owner: value_root.scope.owner,
                    whole_hash: observed_hash,
                    local_scope: value_root
                        .scope
                        .local_scope
                        .map(|ordinal| NodeLocalScopeId::Lexical(LocalScopeId(ordinal))),
                };
                let carrier = self.graph().intern_node_with_scope(
                    SemanticNodeData::new_typeof(
                        value_root.clone(),
                        verter_type_expr::OwnedSlice::default(),
                        Arc::from(Vec::<SemanticNodeId>::new().into_boxed_slice()),
                    ),
                    scope,
                );
                return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(carrier),
                    self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
                ))
                .with_observed_self_roots([(
                    value_root.scope.canonical_id.clone(),
                    observed_hash,
                )]);
            };
            // Only a `var` and a function are properties of the global
            // object; `let`, `const`, `class` and `enum` are global by
            // name alone (the checker's TS2339 on `globalThis.x`).
            use verter_session_query::declarations::ValueDeclKind;
            match self
                .global_value_declarations(value_root.scope.canonical_id.as_ref(), member)
                .as_deref()
            {
                Some(
                    [(
                        identity,
                        ValueDeclKind::Var | ValueDeclKind::Function | ValueDeclKind::AsyncFunction,
                    ), peers @ ..],
                ) => {
                    global_via_global_this = true;
                    global_peers = peers.iter().map(|(peer, _)| peer.clone()).collect();
                    (Some(identity.clone()), rest)
                }
                _ => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
            }
        } else {
            match self
                .global_value_declarations(
                    value_root.scope.canonical_id.as_ref(),
                    value_root.name.as_ref(),
                )
                .as_deref()
            {
                Some([(identity, _), peers @ ..]) => {
                    global_peers = peers.iter().map(|(peer, _)| peer.clone()).collect();
                    (Some(identity.clone()), path)
                }
                // A global namespace without a value of its own
                // declaration is its object.
                _ => {
                    let Some((object, roots)) = self.global_namespace_object(
                        value_root.scope.canonical_id.as_ref(),
                        value_root.name.as_ref(),
                        context,
                    ) else {
                        return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    };
                    let output = if path.is_empty() {
                        crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                            QueryResult::Value(object),
                            self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
                        ))
                    } else {
                        self.project_typeof_path(object, path, context, observed_hash, value_root)
                    };
                    return output.with_observed_self_roots(
                        std::iter::once((value_root.scope.canonical_id.clone(), observed_hash))
                            .chain(roots),
                    );
                }
            }
        };

        // Same scope-recording rule as `build_resolve_decl` — the value
        // binding's origin scope is the owning canonical so dispatch
        // builders downstream can reach the correct declaration file.
        let scope = NodeScopeId::File {
            canonical_id: value_root.scope.canonical_id.clone(),
            owner: value_root.scope.owner,
            whole_hash: observed_hash,
            local_scope: value_root
                .scope
                .local_scope
                .map(|ordinal| NodeLocalScopeId::Lexical(LocalScopeId(ordinal))),
        };
        let scope_payload = self
            .ctx
            .prepared_decl_bundle(value_root.scope.canonical_id.as_ref())
            .map(|bundle| {
                self.declaration_scope_payload(
                    &bundle,
                    value_root.scope.canonical_id.as_ref(),
                    value_root.scope.owner,
                    value_root.name.as_ref(),
                )
            });
        // R15/F11 — capture the scope-shadowing context
        // once for the whole `build_typeof` body so every recursive
        // lowering observes the same shadow set.
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let resolved_root = match global_root {
            Some(global) => Some(global),
            None if ambient_scope.is_some() => Some(ResolvedRootIdentity::new_in_owner(
                value_root.scope.canonical_id.clone(),
                value_root.scope.owner,
                value_root.name.as_ref(),
            )),
            None => crate::resolver_core::bare_name_resolve::resolve_bare_name_in_scope(
                self.ctx,
                self,
                value_root.scope.canonical_id.as_ref(),
                value_root.scope.owner,
                scope_payload.as_ref(),
                value_root.name.as_ref(),
            )
            .or_else(|| {
                // A `declare module "…"` block member is the file's own
                // declaration of the name.
                (has_value && visible_value.is_none()).then(|| {
                    ResolvedRootIdentity::new_in_owner(
                        value_root.scope.canonical_id.clone(),
                        value_root.scope.owner,
                        value_root.name.as_ref(),
                    )
                })
            }),
        };
        let root_identity = match resolved_root {
            Some(identity) => identity,
            None => {
                // `typeof name` where `name` is an IMPORT whose specifier
                // does not (yet) resolve — `import theme from './theme'`
                // before `/theme.ts` exists. The miss is a MissingDependency
                // result: it MUST invalidate the moment the dependency
                // appears. The build-layer fence (`WholeHash` /
                // `RouteGeneration` / `ProjectGeneration`) carries NO
                // import-route rail — the only rail that moves when a
                // known-miss specifier resolves (a synthetic
                // project-generation dep is the wrong correctness rail, per
                // the architecture ruling). So when the name is
                // import-backed we OBSERVE the owner's import-route
                // RESOLUTION WITNESS into the active tracer (the sealed
                // transaction's exhausted probe set for the miss, which the
                // dependency's appearance advances) — bubbling it into the
                // outer
                // component-meta result signature so the warm read misses
                // after the dependency is added. When the route fact cannot
                // be produced (no import-route surface to root on), the
                // miss is unrootable and MUST be cache-suppressed
                // (`ReturnOnly`): the value still flows, but no warm entry
                // publishes, so the next request recomputes cold and
                // recovers. A non-import miss (a genuinely absent LOCAL
                // symbol) stays the ordinary unrooted Miss.
                let is_import_backed = has_import_local
                    || has_namespace_prefix
                    || scope_payload.as_ref().is_some_and(|p| {
                        p.import_bindings().contains_key(value_root.name.as_ref())
                    });
                let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
                    (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                if is_import_backed {
                    let owner_canonical = value_root.scope.canonical_id.as_ref();
                    // Best-effort: observe the owner's import-route
                    // resolution witness into the active tracer so any
                    // consumer cache whose validity rail consults
                    // import-route facts re-validates when the specifier
                    // resolves.
                    self.ctx.observe_owner_import_route_witness(owner_canonical);
                    // The build-layer fence cannot carry the import-route
                    // rail (no `DepVersion` variant expresses a resolution
                    // witness) and a value-import known-miss may not even surface
                    // in the owner's type-import route table — so the route
                    // fact above is NOT a guaranteed invalidation rail for
                    // EVERY consuming memo (the `TypeOf` memo, the
                    // `evaluate_deferred` memo, the field-materialize memo, the
                    // resolved-meta result cache). A `typeof <unresolved
                    // import>` is a genuine `MissingDependency` PARTIAL: the
                    // resolution is structurally incomplete because a dependency
                    // is absent. Marking it `result_is_partial` makes EVERY
                    // consuming cache refuse warm admission (the no-poison
                    // invariant — `result_is_partial` folds through every
                    // nested read and the finalisation boundary forces
                    // `cache_suppress`), so the next request after the
                    // dependency appears recomputes cold and recovers. Also
                    // mark the request-scoped materialization suppress sticky
                    // (which OR-folds into the resolved-meta result's
                    // `synthesis_should_suppress` gate) for the no-`RequestContext`
                    // belt-and-braces. (Per the architecture ruling: when the
                    // route fact cannot guarantee invalidation, the degraded
                    // MissingDependency result is `ReturnOnly`.)
                    output.mark_partial();
                    output.cache_suppress = true;
                    crate::request_context::mark_request_result_partial();
                }
                return output;
            }
        };
        // Effective post-fallback identity: when the resolved root names a
        // re-exporting canonical with no local prepared VALUE decl, the
        // export-target walk yields the DECLARING decl — every downstream
        // consumer (the class-surface slot in particular) keys and lowers
        // under THAT identity, never the stale re-export root.
        let effective = self.effective_prepared_value_decl_in_augmentation(
            &root_identity.canonical_id,
            root_identity.owner,
            &root_identity.symbol_name,
            ambient_scope,
        );
        let Some((effective_canonical, effective_owner, effective_symbol, prepared)) = effective
        else {
            return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
        };
        // A nominal carrier's head is the asked root, and `globalThis` is not
        // the declaration a `globalThis.x` carrier would have to name.
        if global_via_global_this && prepared.type_annotation.is_unique_symbol {
            return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
        }
        // A `unique symbol` value is TypeScript's one NOMINAL type, and its
        // widened inhabitant — the bare `symbol` primitive — is interned ONCE
        // per graph. Lowering the annotation here would therefore hand every
        // consumer of this query the SAME node for `typeof A_KIND` and
        // `typeof B_KIND`, erasing the declaring identity that IS the type
        // before any consumer can read it. The `typeof` CARRIER is the answer
        // instead, and this is its SOLE mint site for DECLARATION ROOTS: every
        // typeof-resolving
        // consumer (the deferred evaluator, the path walker, the locator
        // projection, the carrier normalizer, the raising reducer, the eager
        // lowering) resolves a carrier head through the same
        // [`SemanticQueryKey::TypeOf`] key, so a declaration root converges
        // here however it was reached and no consumer mints a second marked
        // node from a projected value. Each of them classifies the result:
        // a consumer asking a NOMINAL question reads the carrier as terminal,
        // and a consumer asking a STRUCTURAL one takes the widened inhabitant
        // through `widened_nominal_typeof`. The nominal relation resolves the
        // carrier back to the DECLARING value identity (chasing aliases /
        // imports / re-exports), so one declaration names one type however it
        // was referenced. The carrier is minted from the `prepared` facts this
        // builder already read — no second lookup.
        //
        // A MEMBER-qualified `typeof C.K` is the SAME query with a non-empty
        // path. The member's own nominal carrier is minted HERE when the
        // declaring value (or a type it aliases) records the member as an
        // authored `unique symbol`; every other member shape projects below.
        if prepared.type_annotation.is_unique_symbol {
            let identity = verter_type_expr::facts::ValueDeclIdentityPart {
                canonical_id: effective_canonical.clone(),
                owner: effective_owner,
                symbol: effective_symbol.clone(),
                member_path: verter_type_expr::OwnedSlice::from(
                    Vec::<String>::new().into_boxed_slice(),
                ),
            };
            // The carrier's head is the ASKED root — the reference the
            // consumer wrote — while the declaring identity rides the
            // payload. A renamed import therefore still displays and anchors
            // as the local spelling, and still compares EQUAL to every other
            // reference to the same declaration.
            let carrier = self.intern_nominal_typeof(
                value_root.clone(),
                verter_type_expr::OwnedSlice::default(),
                identity,
                scope.clone(),
            );
            if path.is_empty() {
                return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(carrier),
                    self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
                ))
                .with_observed_self_roots([(
                    value_root.scope.canonical_id.clone(),
                    observed_hash,
                )]);
            }
            // `typeof TOKEN.description` — remaining segments read the
            // `Symbol` interface on the widened primitive.
            let widened = self
                .widened_nominal_typeof(carrier)
                .expect("a unique-symbol root always widens");
            return self.project_typeof_path(widened, path, context, observed_hash, value_root);
        }
        // The member rail reuses the root this builder already resolved —
        // the effective declaration and its prepared facts — instead of
        // repeating the bare-name resolve and export-target walk.
        let effective_root: EffectivePreparedValueDecl = (
            effective_canonical.clone(),
            effective_owner,
            effective_symbol.clone(),
            prepared.clone(),
        );
        if let Some(nominal) =
            self.member_nominal_typeof(value_root, path, &effective_root, Some(scope.clone()))
        {
            if global_via_global_this {
                return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
            }
            return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(nominal),
                self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
            ))
            .with_observed_self_roots([(value_root.scope.canonical_id.clone(), observed_hash)]);
        }
        let empty_env = FxHashMap::default();
        let mut substitutions = Vec::new();
        // CONVERGENCE (scope-bounded to a synthesized `.vue`/typeinfo-scratch
        // `default` ONLY): when the resolved value root is EXACTLY the
        // synthesized `.vue` public-instance `default` — `root_identity`'s symbol
        // is `default` AND the resolved canonical's shallow `default` value
        // symbol carries the `is_synthesised_component_default` provenance flag — the
        // construct-signature RETURN must be produced by the keyed
        // `Instantiate(.vue default)` query, not by re-lowering the synthesized
        // default's first signature `return_type` here. This keeps `typeof
        // Foo` / `InstanceType<typeof Foo>` (Foo a `.vue`) on the SAME semantic
        // identity + recursion guard the bare-`Ref` `.vue` route uses. NOTHING
        // else changes: non-`.vue` `typeof`, userland `.vue` defaults, ordinary
        // `.ts`/`.tsx` constructors/classes/functions/enums/object-literals, and
        // generic `InstanceType<T>` all fall through to the unchanged chain
        // below.
        let synthesised_default: Option<crate::semantic_query::HashValue> =
            if root_identity.symbol_name.as_ref() == "default" {
                self.ctx
                    .ensure_indexed_ready_serve(root_identity.canonical_id.as_ref())
                    .map(|serve| serve.indexed)
                    .and_then(|indexed| {
                        indexed
                            .shallow_state
                            .value_symbol_in(root_identity.owner, "default")
                            .filter(|sym| sym.is_synthesised_component_default)
                            .map(|_| indexed.whole_hash)
                    })
            } else {
                None
            };
        // A member path reads the member where the value declares it — a
        // class's own static, an object literal's own member — never the
        // whole surface: the checker resolves a value's members one at a
        // time, so `typeof C.m` whose return names `C` does not build `C`.
        if let (Some(first), None) = (path.first(), synthesised_default) {
            let is_class =
                prepared.kind == verter_session_query::declarations::ValueDeclKind::Class;
            let own_literal = !is_class && value_is_own_object_literal(&prepared);
            if (is_class && first.as_ref() != "prototype") || own_literal {
                let member_context = if is_class {
                    crate::semantic_query::ProjectionReductionContext::published(context.mode)
                } else {
                    context
                };
                // On the continuation runtime the member's positions lower
                // as the frame's projections, each waiting on the
                // instantiations and `typeof`s its value names.
                if let Some(suspended) = suspend.as_mut() {
                    if let Some((member_scope, members)) = self.value_member_plan(
                        effective_canonical.as_ref(),
                        effective_owner,
                        effective_symbol.as_ref(),
                        &prepared,
                        first.as_ref(),
                        member_context,
                    ) {
                        let mut build = Box::new(TypeofBuild {
                            redirects: Vec::new(),
                            prepared: prepared.clone(),
                            env: member_scope.env,
                            scope: member_scope.scope,
                            scope_payload: member_scope.scope_payload,
                            shadowing: member_scope.shadowing,
                            substitutions: Vec::new(),
                            self_value: None,
                            body: TypeofBody::Unstarted,
                            then: TypeofThen::Member(Box::new(MemberLowering {
                                members,
                                current: None,
                                declaring: verter_type_expr::OwnedStr::from(&effective_canonical),
                            })),
                            value_root: value_root.clone(),
                            path: verter_type_expr::OwnedSlice::from(path),
                            context,
                            observed_hash,
                        });
                        let begun = self.begin_next_member_body(&mut build);
                        verter_debug_assert!(begun, "a member plan holds a position");
                        **suspended = Some(build);
                        return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    }
                }
                let mut base_partial = false;
                let source = self
                    .value_member_source(
                        effective_canonical.as_ref(),
                        effective_owner,
                        effective_symbol.as_ref(),
                        &prepared,
                        first.as_ref(),
                        member_context,
                    )
                    .or_else(|| {
                        // A static the class inherits reads off the base
                        // statics that declare it.
                        if !is_class {
                            return None;
                        }
                        let (bases, partial) = self.class_base_static_surfaces(
                            effective_canonical.as_ref(),
                            effective_owner,
                            effective_symbol.as_ref(),
                            context.mode,
                        );
                        base_partial = partial;
                        let declaring: Vec<SemanticNodeId> = bases
                            .into_iter()
                            .filter(|base| self.surface_declares_member(*base, first.as_ref()))
                            .collect();
                        declaring
                            .into_iter()
                            .reduce(|composed, base| self.merge_static_surfaces(composed, base))
                    });
                if let Some(own) = source {
                    let own = self.widen_declared_read_positions(own, &prepared);
                    // The member lowered from the DECLARING file roots on
                    // its content version as the composed surface would.
                    return self.member_typeof_output(
                        own,
                        base_partial,
                        &verter_type_expr::OwnedStr::from(&effective_canonical),
                        value_root,
                        path,
                        context,
                        observed_hash,
                    );
                }
            }
        }
        let mut composed_partial = false;
        // The files whose `declare module` blocks the value merged, and
        // whether one of them could not be observed.
        let mut augmentation_roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> =
            Vec::new();
        let mut augmentation_unobservable = false;
        let node_id = if let Some(_resolved_default_whole_hash) = synthesised_default {
            let resolved_default_canonical =
                verter_type_expr::OwnedStr::from(&root_identity.canonical_id);
            self.build_synthesized_vue_default_construct_object(
                &resolved_default_canonical,
                root_identity.owner,
                &scope,
            )
        } else if prepared.kind == verter_session_query::declarations::ValueDeclKind::Class {
            // Class value root — `typeof C` IS the class's STATIC surface,
            // whose owning composer is `ResolveClassSurface::Static` (own
            // statics + ctor PLUS heritage statics). Delegate through the
            // keyed query so the composed surface is addressable, memoised
            // per class identity, and fact-rooted on every heritage
            // contributor. The composer lowers the prepared value decl
            // directly (it never dispatches `TypeOf` back), so this
            // delegation cannot recurse onto itself. The slot carries the
            // EFFECTIVE (post-fallback) identity: a re-export root would
            // key, lower, and invalidate the composed surface against the
            // wrong canonical.
            let slot = self.type_slot_for(
                effective_canonical.clone(),
                effective_owner,
                effective_symbol.clone(),
            );
            let class_context =
                self.class_surface_context_for(effective_canonical.as_ref(), context.mode);
            let read = self.execute_read(SemanticQueryKey::ResolveClassSurface {
                decl_slot: slot,
                type_args: Arc::from(Vec::<SemanticNodeId>::new().into_boxed_slice()),
                side: crate::semantic_query::ClassSurfaceSide::Static,
                context: class_context,
            });
            composed_partial |= read.result_is_partial();
            match read.value {
                QueryResult::Value(id) => id,
                _ => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
            }
        } else if matches!(
            prepared.type_annotation.literal_freshness,
            verter_type_expr::facts::DeclaredLiteralFreshness::WideningNullish
        ) && !self
            .nullability_for(effective_canonical.as_ref())
            .is_strict()
        {
            // With `strictNullChecks` off a `null` / `undefined` initializer
            // widens: the declaration's type is `any`.
            self.graph()
                .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Any))
        } else if !matches!(
            prepared.type_annotation.classification,
            verter_type_expr::facts::ValueAnnotationClass::Absent
        ) {
            if let Some(source) = prepared.type_annotation.expression_source.as_ref() {
                let evaluated = match suspend {
                    None => self.execute_semantic_expression_source(source, effective_owner),
                    // On the continuation runtime the source evaluates as
                    // the frame's build, waiting on each value it names.
                    Some(suspended) => {
                        *suspended = Some(Box::new(TypeofBuild {
                            redirects: Vec::new(),
                            prepared: prepared.clone(),
                            env: empty_env,
                            scope,
                            scope_payload,
                            shadowing,
                            substitutions,
                            self_value: None,
                            body: TypeofBody::Expression(Box::new(
                                super::flow_return::ExpressionSourceRun::new(effective_owner),
                            )),
                            then: TypeofThen::Value,
                            value_root: value_root.clone(),
                            path: verter_type_expr::OwnedSlice::from(path),
                            context,
                            observed_hash,
                        }));
                        return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    }
                };
                match self.expression_source_value_type(
                    &prepared,
                    source,
                    effective_owner,
                    evaluated,
                ) {
                    Some(node) => node,
                    None => {
                        // No expression value was produced, so there is no
                        // addressed representation for a positional guarantee.
                        return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    }
                }
            } else {
                // The annotation FACT carries either a trivially-closed leaf (an
                // inferred primitive/literal annotation) or routes to the authored
                // value-annotation POSITION — lowered through the ONE located body
                // source (`LowerLocator` deref of the value anchor), never a
                // stored typed body.
                match prepared.type_annotation.annotation.as_ref() {
                    Some(verter_type_expr::facts::SemanticTypeSource::Closed(
                        verter_type_expr::facts::ClosedTypeFact::Leaf(leaf),
                    )) => self.shallow_lower_type_expr_with_context(
                        &super::lower::leaf_type_fact_expr(leaf),
                        &empty_env,
                        &scope,
                        &prepared.name_resolution,
                        scope_payload.as_ref(),
                        &shadowing,
                        &mut substitutions,
                        context,
                    ),
                    // An authored annotation lowers its own position; a
                    // complex INFERRED annotation carries no closed fact and
                    // is recovered by demand through the SAME authored
                    // value-position locator (the transient value-part
                    // re-borrow serves the initializer-inferred typed IR).
                    annotation => {
                        let locator = match annotation {
                            Some(verter_type_expr::facts::SemanticTypeSource::Authored(
                                locator,
                            )) => locator.clone(),
                            _ => value_position_locator(&prepared, ambient_scope),
                        };
                        let locator = match &locator {
                            verter_type_expr::locators::AuthoredBodyLocator::DeclBody(slot) => {
                                scoped_type_body_locator(slot, ambient_scope)
                            }
                            _ => locator,
                        };
                        match self.lower_typeof_body_or_suspend(
                            locator,
                            suspend,
                            TypeofBodyScope {
                                prepared: &prepared,
                                env: empty_env,
                                scope,
                                scope_payload,
                                shadowing,
                                substitutions,
                            },
                            value_root,
                            path,
                            context,
                            observed_hash,
                        ) {
                            Some(node) => self.widen_declared_read_positions(node, &prepared),
                            None => {
                                return (QueryResult::Error(QueryError::Miss), empty_signature())
                                    .into()
                            }
                        }
                    }
                }
            }
        } else if prepared.object_shape.is_some() {
            // Const-object shape: the members' value positions are content-
            // free locators of the authored object — lower the WHOLE authored
            // value position through the located body source (the transient
            // value-part re-borrow serves the object initializer's typed IR).
            match self.lower_typeof_body_or_suspend(
                value_position_locator(&prepared, ambient_scope),
                suspend,
                TypeofBodyScope {
                    prepared: &prepared,
                    env: empty_env,
                    scope,
                    scope_payload,
                    shadowing,
                    substitutions,
                },
                value_root,
                path,
                context,
                observed_hash,
            ) {
                Some(node) => self.widen_declared_read_positions(node, &prepared),
                None => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
            }
        } else if !prepared.signatures.is_empty() {
            // The composed constructor-like object is interned directly.
            let is_class =
                prepared.kind == verter_session_query::declarations::ValueDeclKind::Class;
            // One signature group per declaration the function merges, in
            // declaration order: every later file's declaration of a global
            // function follows the first's.
            let signatures = SignatureLowering::new(
                self,
                &prepared,
                is_class,
                std::mem::take(&mut global_peers),
                ambient_scope,
            );
            match self.lower_value_signatures_or_suspend(
                signatures,
                suspend,
                TypeofBodyScope {
                    prepared: &prepared,
                    env: empty_env,
                    scope,
                    scope_payload,
                    shadowing,
                    substitutions,
                },
                value_root,
                path,
                context,
                observed_hash,
            ) {
                SignaturesLowered::Lowered((node, roots, unobservable)) => {
                    augmentation_roots.extend(roots);
                    augmentation_unobservable |= unobservable;
                    node
                }
                SignaturesLowered::Miss | SignaturesLowered::Suspended => {
                    return (QueryResult::Error(QueryError::Miss), empty_signature()).into()
                }
            }
        } else if let Some(enumeration) = self.enum_declaration_of(
            effective_canonical.clone(),
            effective_owner,
            effective_symbol.clone(),
            &prepared,
            ambient_scope,
        ) {
            // The enum object: every member, a constant one and a computed
            // one alike, as a readonly property of its literal type.
            self.enum_object(&enumeration)
        } else {
            return (QueryResult::Error(QueryError::Miss), empty_signature()).into();
        };
        let node_id = self.normalize_inferred_value_type(&prepared, node_id);
        // A namespace of a class's name merges into its value: the
        // namespace's exported values are properties of the class's static
        // side (a function's join in `finish_value_signatures`).
        let node_id = if synthesised_default.is_none()
            && prepared.kind == verter_session_query::declarations::ValueDeclKind::Class
        {
            let (object, roots) = self.namespace_merged_into_value(
                effective_canonical.as_ref(),
                effective_owner,
                effective_symbol.as_ref(),
                context,
            );
            augmentation_roots.extend(roots);
            match object {
                Some(object) => self.merged_value_and_namespace(
                    node_id,
                    object,
                    NodeScopeId::File {
                        canonical_id: value_root.scope.canonical_id.clone(),
                        owner: value_root.scope.owner,
                        whole_hash: observed_hash,
                        local_scope: value_root
                            .scope
                            .local_scope
                            .map(|ordinal| NodeLocalScopeId::Lexical(LocalScopeId(ordinal))),
                    },
                ),
                None => node_id,
            }
        } else {
            node_id
        };
        let output = self.typeof_output(
            node_id,
            composed_partial,
            value_root,
            path,
            context,
            observed_hash,
        );
        self.with_augmentation_roots(output, augmentation_roots, augmentation_unobservable)
    }

    /// Inferred declarations widen their object literals in the same context
    /// as return and yield joins. Authored annotations keep their own types.
    fn normalize_inferred_value_type(
        &self,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        node: SemanticNodeId,
    ) -> SemanticNodeId {
        if matches!(
            prepared.type_annotation.annotation,
            Some(verter_type_expr::facts::SemanticTypeSource::Authored(_))
        ) {
            return node;
        }
        let nullability = self.nullability_for(prepared.root_identity.canonical_id.as_ref());
        self.normalize_inferred_initializer_type(node, nullability)
    }

    fn normalize_inferred_initializer_type(
        &self,
        node: SemanticNodeId,
        nullability: verter_session_query::flow::policy::NullabilityPolicy,
    ) -> SemanticNodeId {
        let normalized = self.normalize_widened_object_literals(node, nullability);
        self.regularized_source_node_with_policy(normalized, nullability)
    }

    /// Class surfaces publish each field as an independent initializer. Work
    /// only on the shape already lowered; reference carriers stay deferred.
    fn normalize_class_initializers(
        &self,
        node: SemanticNodeId,
        nullability: verter_session_query::flow::policy::NullabilityPolicy,
    ) -> SemanticNodeId {
        let graph = self.graph();
        let Some(data) = graph.node_data(node) else {
            return node;
        };
        let normalized = match data.as_ref() {
            SemanticNodeData::Object(view) => {
                let entries = view
                    .entries
                    .iter()
                    .map(|entry| match entry {
                        SurfaceEntry::Member(member) => SurfaceEntry::Member(SurfaceMember {
                            value: self
                                .normalize_inferred_initializer_type(member.value, nullability),
                            ..member.clone()
                        }),
                        SurfaceEntry::ConstructSignature(signature) => {
                            SurfaceEntry::ConstructSignature(
                                self.normalize_widened_object_literals(*signature, nullability),
                            )
                        }
                        _ => entry.clone(),
                    })
                    .collect();
                SemanticNodeData::Object(SurfaceView::from_entries(
                    entries,
                    view.keyspace,
                    view.has_known_index_signature(),
                ))
            }
            SemanticNodeData::Intersection(arms) => {
                let normalized: Arc<[_]> = arms
                    .iter()
                    .map(|arm| self.normalize_class_initializers(*arm, nullability))
                    .collect();
                if arms.iter().eq(normalized.iter()) {
                    return node;
                }
                SemanticNodeData::Intersection(
                    crate::semantic_query::composite::CompositeList::rebuilt_from(
                        arms.origin_category(),
                        normalized,
                    ),
                )
            }
            SemanticNodeData::MergedDecl { contributors } => SemanticNodeData::MergedDecl {
                contributors: contributors
                    .iter()
                    .map(|contributor| self.normalize_class_initializers(*contributor, nullability))
                    .collect::<Vec<_>>()
                    .into(),
            },
            _ => return node,
        };
        if normalized == *data {
            node
        } else {
            graph.intern_preserving_scope(node, normalized)
        }
    }

    /// The type of a value whose declared type is its initializer's
    /// `evaluated` value: a mutable declaration widens the fresh literal its
    /// initializer call returns (`let m = f(1)` over `f<T>(x: T): T` is
    /// `number`). `None` when the initializer produced no value.
    fn expression_source_value_type(
        &self,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        source: &verter_type_expr::facts::SemanticExpressionSource,
        owner: verter_type_expr::TopLevelOwnerId,
        evaluated: Option<SemanticNodeId>,
    ) -> Option<SemanticNodeId> {
        let node = evaluated?;
        if !matches!(
            prepared.kind,
            verter_session_query::declarations::ValueDeclKind::Let
                | verter_session_query::declarations::ValueDeclKind::Var
        ) || !self.semantic_expression_source_is_fresh(source, owner)
        {
            return Some(node);
        }
        let members = match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Union(members)) => {
                Some(members.iter().copied().collect::<Vec<_>>())
            }
            _ => None,
        };
        Some(match members {
            Some(arms) => {
                let widened: Vec<SemanticNodeId> =
                    arms.iter().map(|arm| self.widened_literal(*arm)).collect();
                self.intern_normalized_union_or_intersection(&widened, true)
            }
            None => self.widened_literal(node),
        })
    }

    /// The augmenting blocks' function signatures for an exported function
    /// `prepared`, when its declaring file is a module that exports it
    /// under that name.
    fn exported_function_augmentations(
        &self,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<AugmentationContributions> {
        let canonical = &prepared.root_identity.canonical_id;
        let exported = prepared
            .exported_name
            .as_deref()
            .unwrap_or(prepared.root_identity.symbol_name.as_ref());
        let indexed = self.transaction_indexed_record(canonical.as_ref())?;
        let exports_this_declaration = matches!(
            indexed.shallow_state.export_target(exported),
            Some(verter_session_query::inputs::shallow::ExportTarget::Local { owner, symbol_name })
                if *owner == prepared.root_identity.owner
                    && symbol_name.as_str() == prepared.root_identity.symbol_name.as_ref()
        );
        if !exports_this_declaration {
            return None;
        }
        self.function_augmentations(canonical, exported, context)
    }

    /// Whether `canonical` is a MODULE file (`classify_module_kind`): a
    /// script's top-level declarations are globals, merged with every other
    /// script's same-name declarations.
    pub(super) fn canonical_is_module(&self, canonical: &str) -> bool {
        self.transaction_indexed_record(canonical)
            .is_some_and(|indexed| {
                verter_session_query::inputs::contributors::classify_shallow_module_kind(
                    &indexed.shallow_state,
                ) == verter_session_query::inputs::contributors::FileModuleKind::Module
            })
    }

    /// Root a `typeof` output on the augmenting files its value merged, and
    /// keep it out of the shared memo when one of them was unobservable.
    fn with_augmentation_roots(
        &self,
        mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput,
        roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot>,
        unobservable: bool,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let fresh: Vec<_> = roots
            .into_iter()
            .filter(|root| !output.observed_self_roots.contains(root))
            .collect();
        output = output.with_observed_self_roots(fresh);
        if unobservable {
            output.cache_suppress = true;
            crate::fact_tracing::note_non_cacheable_read_fan_out(
                verter_session_query::facts::reuse::NonCacheableReadReason::UnobservableSource,
            );
        }
        output
    }

    /// The visible value signatures of one prepared function declaration,
    /// each with the declaration block it groups by, in declaration order.
    ///
    /// Overload visibility (projection-time rule) comes from the ONE shared
    /// authority — the same rule the member-position overload carrier
    /// applies, so a group reached as `typeof f` and the same group reached
    /// as `C['m']` publish the same contributors. Each visible signature
    /// lowers through the located body source at its GROUP-level
    /// `ValueSignature` ordinal (the whole-signature deref recovers the
    /// function IR from the retained snapshot — binding the signature's own
    /// type parameters — and names a body-derived return's served function
    /// position so the lowering demands it from the whole-function producer
    /// through the sealed helper).
    ///
    /// A file's top-level overloads are ONE declaration. A namespace
    /// member's or a `declare global` block's overloads group by the block
    /// that declares them: the checker's candidate order tries a later
    /// block's before an earlier one's.
    fn value_signature_jobs(
        &self,
        prepared: &verter_retention::heap_size::OwnedValue<
            verter_session_query::type_solver::PreparedValueDecl,
        >,
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> Vec<SignatureJob> {
        let identity = &prepared.root_identity;
        let by_block = identity.symbol_name.contains('.')
            || self
                .transaction_indexed_record(identity.canonical_id.as_ref())
                .is_some_and(|indexed| {
                    indexed
                        .shallow_state
                        .headers
                        .value_header_in(identity.owner, identity.symbol_name.as_ref())
                        .is_none()
                });
        let visible = crate::semantic_query::visible_overload_ordinals(
            prepared
                .signatures
                .iter()
                .map(|sig| sig.has_implementation_body),
        );
        visible
            .into_iter()
            .enumerate()
            .map(|(position, ordinal)| {
                let block = by_block
                    .then(|| match &prepared.signatures[ordinal].spans_origin {
                        verter_type_expr::span_origins::FunctionSpansOrigin::AliasBody {
                            anchor,
                        }
                        | verter_type_expr::span_origins::FunctionSpansOrigin::Member {
                            anchor,
                            ..
                        } => Some(anchor.contributor_index),
                        verter_type_expr::span_origins::FunctionSpansOrigin::Synthetic(_) => None,
                    })
                    .flatten();
                let locator = scoped_type_body_locator(
                    &verter_type_expr::locators::TypeBodySlot {
                        anchor: verter_type_expr::locators::AuthoredAnchor {
                            canonical_id: identity.canonical_id.clone(),
                            owner: identity.owner,
                            symbol: identity.symbol_name.clone(),
                            space: verter_type_expr::locators::LocatorSymbolSpace::Value,
                        },
                        path: verter_type_expr::OwnedSlice::from(
                            vec![
                                verter_type_expr::locators::TypeBodyPathStep::ValueSignature {
                                    ordinal: u32::try_from(ordinal).unwrap_or(u32::MAX),
                                },
                            ]
                            .into_boxed_slice(),
                        ),
                    },
                    augmentation,
                );
                SignatureJob {
                    prepared: prepared.clone(),
                    locator,
                    block,
                    opens_declaration: position == 0,
                }
            })
            .collect()
    }

    /// The next signature `signatures` lowers: its own declaration's, then
    /// each merged declaration's in turn, read as its turn comes. `Some(None)`
    /// once every one lowered; `None` when a merged declaration has no
    /// prepared value, which leaves the value without a type.
    fn next_value_signature(
        &self,
        signatures: &mut SignatureLowering,
    ) -> Option<Option<SignatureJob>> {
        loop {
            if let Some(job) = signatures.jobs.pop_front() {
                signatures.lowering = Some((job.block, job.opens_declaration));
                return Some(Some(job));
            }
            let Some(peer) = signatures.peers.pop_front() else {
                return Some(None);
            };
            let (_, _, _, peer_prepared) = self.effective_prepared_value_decl(
                &peer.canonical_id,
                peer.owner,
                &peer.symbol_name,
            )?;
            signatures
                .jobs
                .extend(self.value_signature_jobs(&peer_prepared, None));
        }
    }

    /// Compose a function value's lowered signatures into its type: one
    /// surface, or one overload arm per declaration it merges, after the
    /// augmenting blocks' overloads of an exported function. Also the files
    /// those blocks live in, and whether one of them was unobservable.
    fn finish_value_signatures(
        &self,
        signatures: SignatureLowering,
        scope: &NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> (
        SemanticNodeId,
        Vec<crate::semantic_query_memo::ObservedGraphSelfRoot>,
        bool,
    ) {
        let SignatureLowering {
            own,
            is_class,
            mut groups,
            ..
        } = signatures;
        let mut augmentation_roots = Vec::new();
        let mut augmentation_unobservable = false;
        // An EXPORTED function of a module takes further overloads from
        // every `declare module` block that augments it, one group per
        // block after the declaration's own: call resolution reads them
        // later-declaration-first, as the checker does.
        if !is_class {
            if let Some(contributions) = self.exported_function_augmentations(&own, context) {
                for root in &contributions.contributor_roots {
                    augmentation_roots.push((root.canonical.clone(), root.whole_hash));
                }
                augmentation_unobservable |= contributions.source_env_unobservable;
                groups.extend(contributions.signature_groups);
            }
        }
        let signatures = if !is_class && groups.len() > 1 {
            self.merged_declaration_signatures_node(groups)
        } else {
            let signature_nodes: Vec<SemanticNodeId> = groups.into_iter().flatten().collect();
            self.value_signature_surface(signature_nodes, is_class, scope)
        };
        // A namespace of the function's name merges into its value, whether
        // the function is declared once or merged from several declarations:
        // the namespace's exported values are properties of `typeof f`.
        let is_function = matches!(
            own.kind,
            verter_session_query::declarations::ValueDeclKind::Function
                | verter_session_query::declarations::ValueDeclKind::AsyncFunction
        );
        let node = if is_function {
            let identity = &own.root_identity;
            let (object, roots) = self.namespace_merged_into_value(
                identity.canonical_id.as_ref(),
                identity.owner,
                identity.symbol_name.as_ref(),
                context,
            );
            augmentation_roots.extend(roots);
            match object {
                Some(object) => self.merged_value_and_namespace(signatures, object, scope.clone()),
                None => signatures,
            }
        } else {
            signatures
        };
        (node, augmentation_roots, augmentation_unobservable)
    }

    /// A function's or a class's value merged with the object of the
    /// namespace of its name: one merged declaration whose contributors are
    /// the value, then the namespace, in declaration order. The peer-merge
    /// reducer keeps the value's call and construct signatures and adds the
    /// namespace's values as properties.
    fn merged_value_and_namespace(
        &self,
        value: SemanticNodeId,
        namespace: SemanticNodeId,
        scope: NodeScopeId,
    ) -> SemanticNodeId {
        self.graph().intern_node_with_scope(
            SemanticNodeData::MergedDecl {
                contributors: crate::semantic_query::PayloadArray::from(
                    vec![value, namespace].into_boxed_slice(),
                ),
            },
            scope,
        )
    }

    /// A function value's signatures as one surface: its call signatures,
    /// or for a class its construct signatures.
    fn value_signature_surface(
        &self,
        signature_nodes: Vec<SemanticNodeId>,
        is_class: bool,
        scope: &NodeScopeId,
    ) -> SemanticNodeId {
        let entries = if is_class {
            // A class's value signatures ARE its construct signatures —
            // normalise their kind to `Construct`.
            signature_nodes
                .into_iter()
                .map(|sig| SurfaceEntry::ConstructSignature(self.construct_kind_twin(sig)))
                .collect()
        } else {
            signature_nodes
                .into_iter()
                .map(SurfaceEntry::CallSignature)
                .collect()
        };
        let surface = crate::semantic_query::SurfaceView::from_entries(entries, None, false);
        self.graph()
            .intern_node_with_scope(SemanticNodeData::Object(surface), scope.clone())
    }

    /// The overload set of a function merged from several declarations:
    /// one arm per declaration, in declaration order — a lone signature, or
    /// the declaration's own ordered overload group. `SignaturesOfType`
    /// lists every arm's signatures in that order; call resolution tries a
    /// later declaration's first.
    fn merged_declaration_signatures_node(
        &self,
        groups: Vec<Vec<SemanticNodeId>>,
    ) -> SemanticNodeId {
        use crate::semantic_query::composite::CompositeList;
        let arms: Vec<SemanticNodeId> = groups
            .into_iter()
            .map(|group| match group.as_slice() {
                [lone] => *lone,
                _ => self.graph().intern_node(SemanticNodeData::Intersection(
                    CompositeList::overload_group(Arc::from(group.into_boxed_slice())),
                )),
            })
            .collect();
        self.graph().intern_node(SemanticNodeData::Intersection(
            CompositeList::merged_overload_group(Arc::from(arms.into_boxed_slice())),
        ))
    }

    /// Whether `member` of the class instance `instance` (a reference to a
    /// class declaration) is a `readonly` property without an annotation
    /// whose literal initializer declares its fresh literal type
    /// ([`DeclaredLiteralFreshness::WideningMembers`]): a read of it widens
    /// as a bare literal does (`k.r` over `readonly r = 1` is `number` at a
    /// return).
    ///
    /// A type parameter receiver reads through its constraint, and a union
    /// receiver widens when every arm's declaration of the member holds a
    /// fresh literal (the union property's type is their union, fresh when
    /// it is one literal: `K | K2` over `class K2 extends K {}` reads
    /// `number`; a union of two different literals is no fresh literal, so
    /// `K | KS` reads `1 | 2`).
    pub(super) fn instance_member_read_widens(
        &self,
        instance: SemanticNodeId,
        member: &str,
    ) -> bool {
        let instance = self.type_parameter_apparent_receiver(instance);
        let arms: Vec<SemanticNodeId> = match self.graph().node_data(instance).as_deref() {
            Some(SemanticNodeData::Union(members)) => members.iter().copied().collect(),
            _ => vec![instance],
        };
        arms.into_iter().all(|arm| {
            let arm = self.type_parameter_apparent_receiver(arm);
            self.instance_member_literal_is_fresh(arm, member) == Some(true)
        })
    }

    /// Whether the declaration `member` of the class instance `instance`
    /// reads off — the receiver's own, else the nearest base class or
    /// interface that declares it (`class K2 extends K {}` reads `K`'s
    /// `r`) — declares it by a fresh literal. `None` when the receiver is
    /// no class reference or nothing in its ancestry declares it.
    fn instance_member_literal_is_fresh(
        &self,
        instance: SemanticNodeId,
        member: &str,
    ) -> Option<bool> {
        use verter_type_expr::facts::DeclaredLiteralFreshness;
        let identity = match self.graph().node_data(instance).as_deref() {
            Some(SemanticNodeData::DeclRef { identity }) => identity.clone(),
            _ => return None,
        };
        let ancestry = self.class_heritage_ancestry(&identity);
        self.deposit_operand_self_roots(&ancestry.observed);
        for declaration in std::iter::once(&identity).chain(ancestry.ancestors.iter()) {
            let widens = self
                .effective_prepared_value_decl(
                    &declaration.canonical_id,
                    declaration.owner,
                    &declaration.decl_name,
                )
                .is_some_and(|(_, _, _, prepared)| {
                    matches!(
                        &prepared.type_annotation.literal_freshness,
                        DeclaredLiteralFreshness::WideningMembers { instance, .. }
                            if instance.iter().any(|widening| widening.as_str() == member)
                    )
                });
            if widens {
                return Some(true);
            }
            let declares = self
                .ctx
                .prepared_type_decl_return_only(
                    &declaration.canonical_id,
                    declaration.owner,
                    &declaration.decl_name,
                )
                .is_some_and(|prepared| {
                    prepared
                        .member_index
                        .keys()
                        .any(|key| key.as_string() == Some(member))
                });
            if declares {
                return Some(false);
            }
        }
        None
    }

    /// The type a member read off `receiver` reads through: a type
    /// parameter's constraint (the checker's apparent type of a type
    /// parameter), followed through a chain of constrained parameters. Any
    /// other receiver, an unconstrained parameter, a polymorphic `this`
    /// binder and a constraint cycle read as they are.
    pub(super) fn type_parameter_apparent_receiver(
        &self,
        receiver: SemanticNodeId,
    ) -> SemanticNodeId {
        let graph = self.graph();
        let mut visited: rustc_hash::FxHashSet<SemanticNodeId> = rustc_hash::FxHashSet::default();
        let mut current = receiver;
        loop {
            let next = match graph.node_data(current).as_deref() {
                Some(SemanticNodeData::TypeParam {
                    constraint: Some(constraint),
                    param_index,
                    ..
                }) if *param_index != super::substitute::THIS_BINDER_INDEX => *constraint,
                _ => return current,
            };
            if !visited.insert(current) {
                return receiver;
            }
            current = next;
        }
    }

    /// Whether a read of the value `path` names, in `canonical`'s `owner`
    /// scope, yields a WIDENING literal: the value's declared type is the
    /// fresh literal type a `const` takes from its literal initializer
    /// (`const c = 1`), directly or through the values it copies
    /// (`const d = c`). The checker widens such a read wherever it widens a
    /// bare literal — a return, a mutable binding, an object or array
    /// member, a call argument. The path resolves as a `typeof` reference to
    /// it does: a namespace member, an import, a global.
    pub fn value_read_widens(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        path: &[String],
    ) -> bool {
        let Some((root, rest)) = path.split_first() else {
            return false;
        };
        let value_root = ValueRootKey {
            scope: crate::semantic_query::ScopeId {
                canonical_id: verter_type_expr::OwnedStr::from(canonical),
                owner,
                local_scope: None,
                binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(owner),
            },
            name: verter_type_expr::OwnedStr::from(root.as_str()),
        };
        let rest: Vec<verter_type_expr::OwnedStr> = rest
            .iter()
            .map(|segment| verter_type_expr::OwnedStr::from(segment.as_str()))
            .collect();
        self.declared_literal_widens(&value_root, &rest, &mut FxHashSet::default())
    }

    /// [`Self::value_read_widens`] from a resolved value root. `visited`
    /// holds the references this read has already followed: a copy cycle
    /// (`const a = b; const b = a`) is the checker's own error and reads no
    /// literal.
    fn declared_literal_widens(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        visited: &mut FxHashSet<(ValueRootKey, Vec<verter_type_expr::OwnedStr>)>,
    ) -> bool {
        use verter_type_expr::facts::DeclaredLiteralFreshness;
        let Some((identity, path)) = self.value_path_declaration(value_root, path, visited) else {
            return false;
        };
        // A member of a value (`obj.a`) is not a declaration of its own,
        // except a class's static member (`C.s`) and an enum's member
        // (`E.A`).
        let static_member = match path.as_slice() {
            [] => None,
            [member] => Some(member),
            _ => return false,
        };
        let Some((declaring_canonical, declaring_owner, _, prepared)) = self
            .effective_prepared_value_decl(
                &identity.canonical_id,
                identity.owner,
                &identity.symbol_name,
            )
        else {
            return false;
        };
        if let Some(member) = static_member {
            // Every enum member declares the fresh literal type of its
            // value, so a read of one widens as a bare literal does.
            if prepared.kind == verter_session_query::declarations::ValueDeclKind::Enum {
                return prepared.enum_members.as_ref().is_some_and(|members| {
                    members
                        .members
                        .iter()
                        .any(|entry| entry.name.as_str() == member.as_ref())
                });
            }
            return matches!(
                &prepared.type_annotation.literal_freshness,
                DeclaredLiteralFreshness::WideningMembers { statics, .. }
                    if statics.iter().any(|widening| widening.as_str() == member.as_ref())
            );
        }
        match &prepared.type_annotation.literal_freshness {
            // A `const` initialized by a call reads as fresh as the call's
            // result is (`const m = f(1)` over `f<T>(x: T): T`).
            DeclaredLiteralFreshness::Regular
                if prepared.kind == verter_session_query::declarations::ValueDeclKind::Const =>
            {
                prepared
                    .type_annotation
                    .expression_source
                    .as_ref()
                    .is_some_and(|source| {
                        self.semantic_expression_source_is_fresh(source, declaring_owner)
                    })
            }
            DeclaredLiteralFreshness::Regular
            | DeclaredLiteralFreshness::WideningMembers { .. }
            | DeclaredLiteralFreshness::WideningNullish => false,
            DeclaredLiteralFreshness::Widening => true,
            DeclaredLiteralFreshness::Follows(copied) => {
                // A copy written in a namespace body reads that body's own
                // scope first, which holds members no qualified name
                // records; the file scope would name another value.
                if identity.symbol_name.contains('.') {
                    return false;
                }
                let Some((first, rest)) = copied.split_first() else {
                    return false;
                };
                let copied_root = ValueRootKey {
                    scope: crate::semantic_query::ScopeId {
                        canonical_id: declaring_canonical,
                        owner: declaring_owner,
                        local_scope: None,
                        binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(
                            declaring_owner,
                        ),
                    },
                    name: verter_type_expr::OwnedStr::from(first.as_str()),
                };
                let rest: Vec<verter_type_expr::OwnedStr> = rest
                    .iter()
                    .map(|segment| verter_type_expr::OwnedStr::from(segment.as_str()))
                    .collect();
                self.declared_literal_widens(&copied_root, &rest, visited)
            }
        }
    }

    /// The value declaration the longest declared prefix of a value path
    /// names, and the path's remaining segments: the value declared under
    /// the root's name in its scope — or, when no scope declares it, among
    /// the program's globals — and a namespace's member, declared under its
    /// qualified name (`NS.Inner`) in its own file. A reference to a
    /// value resolves here as a `typeof` of it does. `visited` holds the
    /// roots already followed, so a cycle of re-exports resolves nothing.
    pub(super) fn value_path_declaration(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        visited: &mut FxHashSet<(ValueRootKey, Vec<verter_type_expr::OwnedStr>)>,
    ) -> Option<(ResolvedRootIdentity, Vec<verter_type_expr::OwnedStr>)> {
        use verter_session_query::inputs::shallow::LexicalValueBinding;
        if !visited.insert((value_root.clone(), path.to_vec())) {
            return None;
        }
        let canonical = value_root.scope.canonical_id.as_ref();
        let owner = value_root.scope.owner;
        let name = value_root.name.as_ref();
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(canonical)
            .map(|serve| serve.indexed)?;
        let shallow = &indexed.shallow_state;
        let visible = shallow.visible_value_binding(owner, name);
        let unbound = visible.is_none()
            && shallow.visible_local_type_owner(owner, name).is_none()
            && !name.split_once('.').is_some_and(|(prefix, _)| {
                matches!(
                    shallow.visible_value_binding(owner, prefix),
                    Some(LexicalValueBinding::Import(_))
                )
            });
        if let Some((member_root, consumed)) =
            self.qualified_value_member_root(value_root, path, shallow, unbound)
        {
            return self.value_path_declaration(&member_root, &path[consumed..], visited);
        }
        let identity = if unbound {
            if name == "globalThis" {
                return None;
            }
            self.global_value_declaration(canonical, name)?.0
        } else {
            let scope_payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
                crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                    &bundle, owner,
                )
            });
            crate::resolver_core::bare_name_resolve::resolve_bare_name_in_scope(
                self.ctx,
                self,
                canonical,
                owner,
                scope_payload.as_ref(),
                name,
            )?
        };
        Some((identity, path.to_vec()))
    }

    /// The value a module assigns with `export = X`, as a root in the
    /// module's own scope. `None` for a module without one.
    pub(super) fn export_assignment_root(&self, module: &str) -> Option<ValueRootKey> {
        let indexed = self.ctx.ensure_indexed_ready_serve(module)?.indexed;
        let assigned = indexed.shallow_state.export_assignment_target()?;
        let owner = verter_type_expr::TopLevelOwnerId::ordinary_file();
        Some(ValueRootKey {
            scope: crate::semantic_query::ScopeId {
                canonical_id: verter_type_expr::OwnedStr::from(module),
                owner,
                local_scope: None,
                binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(owner),
            },
            name: verter_type_expr::OwnedStr::from(assigned),
        })
    }

    /// The declaration the longest declared prefix of a value path names,
    /// and how many path segments that prefix consumes. A namespace's value
    /// member is its own declaration under its qualified name
    /// (`NS.Inner.f`), declared in this file — or, when `unbound`, among the
    /// program's globals — or in the file that declares a namespace this
    /// file imports by name or reaches through a namespace import.
    fn qualified_value_member_root(
        &self,
        value_root: &ValueRootKey,
        path: &[verter_type_expr::OwnedStr],
        shallow: &verter_session_query::inputs::shallow::ShallowInputRecord,
        unbound: bool,
    ) -> Option<(ValueRootKey, usize)> {
        use verter_session_query::inputs::shallow::LexicalValueBinding;
        let qualified = |base: &str, segments: &[verter_type_expr::OwnedStr]| {
            let mut name = base.to_string();
            for segment in segments {
                name.push('.');
                name.push_str(segment);
            }
            name
        };
        let owner = value_root.scope.owner;
        let canonical = value_root.scope.canonical_id.as_ref();
        if let Some(LexicalValueBinding::Import(target)) =
            shallow.visible_value_binding(owner, value_root.name.as_ref())
        {
            let Some(dependency) = self
                .ctx
                .resolve_type_dependency_canonical(canonical, &target.source_specifier)
            else {
                // No file answers the specifier: the program's ambient
                // declaration of the module names the member.
                return self.ambient_import_member_root(canonical, target, path);
            };
            // The imported namespace's own file names its members.
            let (declaring, skipped) = if target.is_namespace {
                // A module whose value is `export = X`: an import assignment
                // binds X itself, and a namespace import reads X's members —
                // its `default` is X when `SignaturesOfType` finds a call or
                // construct signature on X (TypeScript 7's interop).
                let assigned = self.export_assignment_root(&dependency);
                if let Some(assigned_root) = &assigned {
                    if target.is_import_equals() {
                        return Some((assigned_root.clone(), 0));
                    }
                    if path
                        .first()
                        .is_some_and(|first| first.as_ref() == "default")
                    {
                        return self
                            .value_has_call_or_construct_signatures(assigned_root)?
                            .then(|| (assigned_root.clone(), 1));
                    }
                }
                let (first, _) = path.split_first()?;
                let resolved = if assigned.is_none() {
                    let table = self.ctx.module_export_table(&dependency)?;
                    self.ctx.observe_borrowed_signature(&table.facts);
                    match table.bindings.get(first.as_str()) {
                        Some(Some(verter_session_query::declarations::module_exports::ModuleExportBinding::Value(root))) => Some(root.clone()),
                        // Namespace carriers and excluded names project through
                        // the same whole-module object as indexed access.
                        _ => None,
                    }
                } else {
                    let (resolved, route_facts) = self
                        .ctx
                        .resolve_imported_type_root_with_facts(&dependency, first);
                    self.ctx.observe_borrowed_signature(&route_facts);
                    resolved
                };
                match (resolved, assigned) {
                    (Some(resolved), _) => (resolved, 1),
                    // A member no namespace merged into X declares is one
                    // of X's own (a class's static, a function's property).
                    (None, Some(assigned_root)) => return Some((assigned_root, 0)),
                    (None, None) => return None,
                }
            } else {
                let scope_payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
                    crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                        &bundle, owner,
                    )
                });
                (
                    crate::resolver_core::bare_name_resolve::resolve_bare_name_in_scope(
                        self.ctx,
                        self,
                        canonical,
                        owner,
                        scope_payload.as_ref(),
                        value_root.name.as_ref(),
                    )?,
                    0,
                )
            };
            let declaring_state = self
                .ctx
                .ensure_indexed_ready_serve(declaring.canonical_id.as_ref())?
                .indexed;
            let rest = &path[skipped..];
            let declaring_scope = crate::semantic_query::ScopeId {
                canonical_id: declaring.canonical_id.clone(),
                owner: declaring.owner,
                local_scope: None,
                binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(declaring.owner),
            };
            // Through a namespace import, the export the first segment names
            // is itself the declaration when no longer path names one.
            let export_root = (target.is_namespace).then(|| {
                (
                    ValueRootKey {
                        scope: declaring_scope.clone(),
                        name: declaring.symbol_name.clone(),
                    },
                    skipped,
                )
            });
            return (1..=rest.len())
                .rev()
                .find_map(|length| {
                    let name = qualified(declaring.symbol_name.as_ref(), &rest[..length]);
                    // Read from outside the namespace, only an exported
                    // member is visible.
                    (matches!(
                        declaring_state
                            .shallow_state
                            .visible_value_binding(declaring.owner, &name),
                        Some(LexicalValueBinding::Local(_))
                    ) && declaring_state
                        .shallow_state
                        .headers
                        .namespace_member_is_exported(declaring.owner, &name))
                    .then(|| {
                        (
                            ValueRootKey {
                                scope: declaring_scope.clone(),
                                name: verter_type_expr::OwnedStr::from(name),
                            },
                            skipped + length,
                        )
                    })
                })
                .or(export_root);
        }
        (1..=path.len()).rev().find_map(|length| {
            let name = qualified(value_root.name.as_ref(), &path[..length]);
            let visible = shallow.visible_value_binding(owner, &name);
            // A qualified read names a namespace's member from outside its
            // body: one the namespace does not export is no member of it
            // (TS2339).
            let declared = (matches!(visible, Some(LexicalValueBinding::Local(_)))
                && shallow.headers.namespace_member_is_exported(owner, &name))
                || (visible.is_none()
                    && matches!(
                        shallow.value_fallback_augmentation_scope(owner, &name),
                        Some(verter_session_query::declarations::AugmentationScopeKind::Module(_))
                    ))
                || (unbound
                    && value_root.name.as_ref() != "globalThis"
                    && self.global_value_declaration(canonical, &name).is_some());
            declared.then(|| {
                (
                    ValueRootKey {
                        scope: value_root.scope.clone(),
                        name: verter_type_expr::OwnedStr::from(name),
                    },
                    length,
                )
            })
        })
    }

    fn project_typeof_path(
        &self,
        base: SemanticNodeId,
        path: &[verter_type_expr::OwnedStr],
        context: crate::semantic_query::ProjectionReductionContext,
        observed_hash: verter_session_query::analysis::types::Hash16,
        value_root: &ValueRootKey,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let projection_path: verter_type_expr::OwnedSlice<PathSegment> =
            verter_type_expr::OwnedSlice::from(
                path.iter()
                    .map(|segment| PathSegment::Member(PropertyKey::identifier(segment.clone())))
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
            );
        // The intermediate-hop rule: the typeof query's REMAINING member
        // path projects in `Navigate` — matching the evaluate / raise arms —
        // with only the orthogonal axes inherited from the caller's context.
        // The mode rides the key itself, and the cfg(test) probe records
        // exactly what the key carried, so a regression to caller-mode
        // inheritance is observable at the asserting test.
        let internal_context =
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Navigate)
                .with_orthogonal_axes_from(context);
        #[cfg(any(test, feature = "test-support"))]
        super::walk::observe_typeof_internal_path_mode(internal_context.mode);
        let read = self.execute_read(SemanticQueryKey::ProjectPath {
            base,
            path: projection_path.clone(),
            context: internal_context,
        });
        let node = match read.value {
            QueryResult::Value(id) => id,
            _ => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
        };
        // The member's declared polymorphic `this` is the reference it is
        // read through (`typeof t.self` over `self(): this` is `() => T`):
        // the value the path's last member is read off.
        let node = if self.receiver_this_types(node).is_empty() {
            node
        } else {
            let receiver = match path.split_last() {
                Some((_, [])) | None => Some(base),
                Some((_, object)) => match self
                    .execute_read(SemanticQueryKey::ProjectPath {
                        base,
                        path: verter_type_expr::OwnedSlice::from(&projection_path[..object.len()]),
                        context: internal_context,
                    })
                    .value
                {
                    QueryResult::Value(id) => Some(id),
                    _ => None,
                },
            };
            match receiver {
                Some(receiver) => self.bind_callee_receiver(node, receiver),
                None => return (QueryResult::Error(QueryError::Miss), empty_signature()).into(),
            }
        };
        let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node),
            self.dep_signature_for(&value_root.scope.canonical_id, observed_hash),
        ))
        .with_observed_self_roots([(value_root.scope.canonical_id.clone(), observed_hash)]);
        output.fold_partial(read.result_is_partial());
        output.add_partial_reasons(read.partial_reason_classes());
        // Forward the completed path's typed position through receiver binding.
        output.with_positional_guarantee()
    }

    /// The local value name a dependency module's CommonJS `export = X`
    /// assigns the whole module to, read from the dependency's shallow export
    /// inventory. `None` for an ordinary ESM module (or an unloadable dep).
    fn import_export_assignment_target(&self, dep_canonical: &str) -> Option<Arc<str>> {
        self.ctx
            .shallow_file_state(dep_canonical)?
            .export_assignment_target()
            .map(Arc::<str>::from)
    }

    /// Build the VALUE-export namespace object for `typeof import("./m")`:
    /// the module object ([`Self::file_module_object`]) — one member per
    /// value the module exports, each the `typeof` its declaration reads
    /// through the shared `TypeOf` rail, so a type-only export is no member.
    ///
    /// A module assigned with `export = X` is instead the type of X (the
    /// CommonJS whole-module value): `typeof import("…")` applies no interop.
    pub(super) fn build_import_value_namespace(
        &self,
        dep_canonical: &str,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        // Ambient `export = X`: the value namespace IS `typeof X`, resolved
        // through the SAME `TypeOf` rail as a named export.
        if let Some(assign_target) = self.import_export_assignment_target(dep_canonical) {
            return match self
                .execute_read(self.typeof_key_for(
                    ValueRootKey {
                        scope: crate::semantic_query::ScopeId {
                            canonical_id: verter_type_expr::OwnedStr::from(dep_canonical),
                            owner: verter_type_expr::TopLevelOwnerId::ordinary_file(),
                            local_scope: None,
                            binder_scope_id: crate::semantic_query::BinderScopeId::file_scope(
                                verter_type_expr::TopLevelOwnerId::ordinary_file(),
                            ),
                        },
                        name: verter_type_expr::OwnedStr::from(assign_target),
                    },
                    context,
                ))
                .value
            {
                QueryResult::Value(id) => id,
                _ => self.opaque(QueryError::Miss),
            };
        }
        match self.file_module_object(dep_canonical, context) {
            Some((object, _)) => object,
            None => self.opaque(QueryError::Miss),
        }
    }

    /// Build a synthesized component-default PUBLIC INSTANCE surface for
    /// `Instantiate{ <component>, "default", [] }` (the `.vue` SFC and every
    /// framework synth leg share this one production site).
    ///
    /// The canonical's `IndexedReady` carries a synthesized `default` VALUE
    /// symbol (`resolver_core::vue_default_synth` /
    /// `resolver_core::svelte_default_synth`) whose annotation FACT carries the
    /// fabricated instance shape `{ $props, $emit, $slots, … }` as a
    /// closed/synthesized source; the authored member payloads inside it are
    /// content-free locators. This raises that source through the SHARED
    /// source-raising bridge (no second resolver) in the component's scope,
    /// returning a normal [`SemanticNodeData::Object`]`(SurfaceView)` so
    /// `ProjectPath` / walkers navigate `$props` / `$emit` / `$slots`.
    ///
    /// Returns `None` when the canonical carries no synthesized `default` with an
    /// instance shape (a `.vue` with no type-based macros), letting
    /// `build_instantiate` fall through to its ordinary `resolve_prepared_type_decl`
    /// miss handling.
    ///
    /// Termination is by QUERY IDENTITY, not a depth bound. Under the lazy
    /// design a circular `.vue` import is a FINITE SHALLOW SURFACE containing
    /// recursive `DeclRef` carriers, NOT an error: the common bound is the
    /// lazy route itself, with two guards reserved for genuine in-flight
    /// re-entry — do not over-claim that a cycle reaches the
    /// active-instantiation guard:
    ///
    /// - **lazy cycle** (the PRODUCTION shape — a mutual bare-`Ref`
    ///   `defineProps<{ peer: Other }>()` with a reciprocal `E ↔ F`, an
    ///   `InstanceType<typeof Peer>` pair, or a same-file self-cycle): the
    ///   inner cyclic reference stays / presents as the shallow
    ///   instance-identity `DeclRef` carrier (`Ref { name: "default" }`)
    ///   instead of re-dispatching `Instantiate`, and each
    ///   `Instantiate(.vue default)` frame completes and pops before the next
    ///   is demanded — so the SAME `(decl_canonical, "default")` frame is
    ///   NEVER active at the back-edge. The result is a bounded SHALLOW
    ///   `Object`, NOT a `RecursiveRef`. This branch's
    ///   `push_instantiate_active` is paired correctly but is not the bound
    ///   for this shape.
    /// - **memo same-key `Instantiate` sentinel** (`semantic_query_memo`):
    ///   when a re-entry dispatches the SAME
    ///   `Instantiate{ .vue default, [], context }` KEY (identical context)
    ///   that is already in flight, the memo's same-key recursion sentinel
    ///   returns `Opaque(RecursiveRef)`.
    /// - **`push_instantiate_active` / `is_instantiate_active` guard**
    ///   (below): the residual same-identity re-entry backstop — when a
    ///   re-dispatch reaches this same `(decl_canonical, "default")` identity
    ///   under a DIFFERENT context key while this frame is still on the stack
    ///   (so the memo sentinel does not fire), the guard short-circuits to
    ///   `Opaque(RecursiveRef)` before recursing. Genuine in-flight re-entry
    ///   ONLY (the same semantic op cannot progress); the lazy production
    ///   routes above never reach it.
    ///
    /// None of the three is a depth bound.
    fn build_vue_default_instance(
        &self,
        decl_canonical: &verter_type_expr::OwnedStr,
        decl_owner: verter_type_expr::TopLevelOwnerId,
        decl_whole_hash: crate::semantic_query::HashValue,
        scope: &NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<crate::project_semantic_dispatch::walk::QueryBuildOutput> {
        // The synthesized `default` value symbol's construct-signature return
        // type is the instance object. Read it ONCE from the observed
        // `IndexedReady` (the same artifact that roots the memo entry below).
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(decl_canonical.as_ref())?
            .indexed;
        let default_symbol = indexed
            .shallow_state
            .value_symbol_in(decl_owner, "default")?;
        // PROVENANCE gate (prefer-direct-structural-facts-over-heuristics): only
        // the SYNTHESIZED `.vue` public-instance `default` symbol drives this
        // branch. A USERLAND `export default` in a `.vue`'s `<script>` (synthesis
        // skipped, userland default present) carries `is_synthesised_component_default
        // == false` — even when its value type superficially looks like an
        // instance (`(): { $props: ... } => ...`) — so it falls through to the
        // ordinary prepared-decl path instead of being mistreated as the public
        // instance.
        if !default_symbol.is_synthesised_component_default {
            return None;
        }
        let default_body =
            self.ctx
                .lowered_value_decl(&indexed.shallow_state, decl_owner, "default")?;
        // The synthesized instance shape rides the annotation FACT as the
        // closed/synthesized four-source arm
        // (`lowered_value_decl_for_synthesised_default`): the fabricated
        // member skeleton is a closed fact, and each authored member payload
        // (the macro type arguments) is a content-free locator lowered on
        // demand through the ONE dispatch. An absent annotation source (a
        // synth without a recoverable instance source) is a fail-closed miss:
        // no instance surface, never a fabricated shape.
        let instance_source: verter_type_expr::facts::SemanticTypeSource =
            default_body.type_annotation.annotation.clone()?;
        let observed_hash = indexed.whole_hash;

        // Query-identity recursion control: push `(decl_canonical, "default")`
        // before lowering. A circular `.vue` import whose instance shape
        // transitively re-references this same identity sees the active entry in
        // `shallow_lower_type_expr` and emits `Opaque(RecursiveRef)` at the
        // back-edge — bounded, no hang.
        let active_identity: super::InstantiateIdentity = (
            verter_type_expr::OwnedStr::from(decl_canonical),
            decl_owner,
            verter_type_expr::OwnedStr::from("default"),
        );
        let pushed = self.push_instantiate_active(active_identity, Arc::from([]));
        if !pushed {
            return Some(
                (
                    QueryResult::Value(self.opaque(QueryError::RecursiveRef {
                        name: verter_type_expr::OwnedStr::from("default"),
                        args: Default::default(),
                    })),
                    empty_signature(),
                )
                    .into(),
            );
        }

        // Raise the synthesized instance source through the shared
        // source-raising bridge: the fabricated skeleton composes directly and
        // every authored member payload lowers through the single-engine
        // authored-locator routing (the macro hot-mirror producer / the
        // memoized locator deref) — inert shallow carriers the consuming
        // walkers resolve on demand, so the result is a normal object
        // `ProjectPath` navigates.
        let raised = self.raise_semantic_type_source_to_hot(
            &instance_source,
            super::semantic_source::SourceRaiseContext {
                scope_canonical_id: decl_canonical.as_ref(),
                scope_owner: decl_owner,
                context,
                interior_failures: None,
            },
        );
        self.pop_instantiate_active();
        // A source with no live graph representation under the current view is
        // the same fail-closed miss as an absent source (a `Synthesized`
        // skeleton always raises; only a bare authored/projected source can
        // miss here).
        let result = raised.at_optional_boundary()?.node();

        // Origin edge + dep signature, mirroring `build_instantiate`'s shell. The
        // instance object is synthesized from the `.vue`'s macro type arguments,
        // so the result depends on the `.vue`'s content version — root the memo
        // entry on `(decl_canonical, observed_hash)`.
        self.graph().record_instantiate();
        let fence = self.dep_signature_for(decl_canonical, observed_hash);
        crate::semantic_query_memo::record_origin_edge!(
            self.graph(),
            result,
            OriginEdgeKind::Instantiate,
            Arc::from([self.graph().intern_node_with_scope(
                SemanticNodeData::Opaque(QueryError::Miss),
                scope.clone(),
            )]),
            OriginMeta::None,
            fence.clone(),
        );

        // `decl_whole_hash` (re-sourced live at value-compute from
        // `ensure_indexed_ready_serve(base.defining_canonical)`'s serve
        // carrier `indexed.whole_hash` — the
        // content-free `Instantiate` key carries no version) and
        // `observed_hash` (the artifact just read) agree under a stable
        // content generation; root on the observed hash, which is the basis the
        // instance shape was actually read from.
        let _ = decl_whole_hash;
        Some(
            crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(result),
                fence,
            ))
            .with_observed_self_roots([(decl_canonical.clone(), observed_hash)]),
        )
    }

    /// `build_typeof` convergence for a synthesized `.vue`/typeinfo-scratch
    /// `default`: build the constructor-like value type (an Object carrying a
    /// single construct signature) whose construct-signature RETURN node is
    /// produced by the keyed `Instantiate{ .vue, "default", [] }` query — NOT by
    /// directly re-lowering the synthesized default's first signature
    /// `return_type`.
    ///
    /// `typeof Foo` (Foo a synthesized `.vue` default) and `InstanceType<typeof
    /// Foo>` therefore share ONE semantic identity for the instance shape: the
    /// `.vue default` instance object. `InstanceType` stays generic — it extracts
    /// this construct signature's return as usual — so there is no second
    /// `.vue`-aware production site to diverge in cache identity or recursion.
    /// Cyclic `InstanceType<typeof …>` re-entry on this shared identity is
    /// bounded by the `Instantiate(.vue default)` recursion machinery: a same-key
    /// in-flight re-entry hits the memo's same-key sentinel, and an EAGER
    /// re-entry of the SAME `(canonical, "default")` identity while the outer
    /// frame is still active (the `InstanceType<typeof Self>` self-cycle under
    /// `Published(Expanded)`) hits `push_instantiate_active` — both yielding
    /// `Opaque(RecursiveRef)`. (The lazy bare-`Ref` MUTUAL route is bounded
    /// differently — a shallow `DeclRef` carrier, not `RecursiveRef`; see
    /// [`Self::build_vue_default_instance`].)
    ///
    /// The synthesized default's construct signature takes no parameters and no
    /// type parameters (`vue_default_synth`), so the `Function` node is composed
    /// directly with an empty parameter list and the instance node as its return
    /// — faithful to what the ordinary lowering of that empty-param construct
    /// signature would intern, but with the return rooted on the shared query.
    fn build_synthesized_vue_default_construct_object(
        &self,
        resolved_default_canonical: &verter_type_expr::OwnedStr,
        resolved_default_owner: verter_type_expr::TopLevelOwnerId,
        scope: &NodeScopeId,
    ) -> SemanticNodeId {
        // The instance shape is the keyed `Instantiate(.vue default)` result —
        // the SOLE semantic identity for the `.vue`'s public instance. Navigate /
        // structural-transit keeps the instance members shallow (the consumer
        // drives any deeper projection), matching `resolve_vue_public_type`'s
        // own intermediate-hop demand.
        let instance_read = self.execute_read(SemanticQueryKey::Instantiate(
            crate::semantic_query::InstantiateKey::new(
                self.type_slot_for(
                    resolved_default_canonical.clone(),
                    resolved_default_owner,
                    Arc::from("default"),
                ),
                Arc::from(Vec::new().into_boxed_slice()),
                self.instantiate_context_for(
                    resolved_default_canonical,
                    crate::semantic_query::ProjectionReductionContext::structural_transit_with_mode(
                        ProjectionMode::Navigate,
                    ),
                ),
            ),
        ));
        // Two-signal fold: the `.vue` instance synthesis helper returns a
        // bare node, so a genuinely-incomplete nested `Instantiate` (budget /
        // recursion / walker-fatal) folds onto the request's sticky partial
        // flag — the component-meta / materialize warm gates consult it and
        // refuse the partial-tainted result. (`.vue` import is the hardest
        // macro-traversal case; this is exactly where a leaked partial
        // would warm a poisoned result.)
        crate::request_context::observe_component_meta_read_suppress(&instance_read);
        let instance_return = match instance_read.value {
            QueryResult::Value(node) => node,
            QueryResult::Recursive(node) => node,
            // A `.vue` whose synthesized instance shape could not be produced
            // (e.g. mid-flight recursion supersession) yields the opaque miss as
            // the construct return — the value type stays a well-formed
            // constructor object, the instance is just unresolved.
            QueryResult::Error(err) => self.opaque(err),
        };

        // Construct signature `new (): <instance>`: empty params + empty type
        // params (the synthesized default takes neither), no source spans.
        let ctor_fn = self.graph().intern_node_with_scope(
            SemanticNodeData::Signature {
                kind: crate::semantic_query::SignatureKind::Construct,
                params: crate::semantic_query::PayloadArray::from(Vec::new().into_boxed_slice()),
                return_type: instance_return,
                type_parameters: crate::semantic_query::PayloadArray::from(
                    Vec::new().into_boxed_slice(),
                ),
                occurrence: None,
                // The synthesized default-constructor instance is a concrete
                // seed, never a body-derived obligation.
                return_carrier: crate::semantic_query::SignatureReturnCarrier::Declared(
                    instance_return,
                ),
                signature_span: None,
                return_type_span: None,
                predicate: None,
                is_abstract: false,
            },
            scope.clone(),
        );

        // Constructor-like value type: an Object carrying exactly that one
        // construct signature — the same shape `typeof <class>` produces, so
        // `InstanceType<typeof Foo>` extracts the construct return generically.
        let view =
            SurfaceView::from_entries(vec![SurfaceEntry::ConstructSignature(ctor_fn)], None, false);
        self.graph()
            .intern_node_with_scope(SemanticNodeData::Object(view), scope.clone())
    }

    /// Class instance / static surface (the dual-space model).
    ///
    /// Realises the class dual-space algorithm through the ONE shared
    /// typed-IR dispatch — there is NO query-time OXC, NO per-surface
    /// walker, NO re-parse:
    ///
    /// - `Instance` → instantiate the TYPE-space half under `Shallow`
    ///   (`execute(Instantiate { base: type_slot, args, published(Shallow) })`).
    /// - `Static` → `TypeOf` the VALUE-space half's constructor value
    ///   (`execute(TypeOf { value_root: value_root_of(value_slot) })`).
    ///
    /// The `side` selects the half; the slot's `symbol_space` does not feed
    /// the composed sub-query, because both the env-bearing
    /// [`ResolvedDeclSlotIdentity`](crate::semantic_query::ResolvedDeclSlotIdentity)
    /// base and
    /// [`value_root_of`](crate::semantic_query::value_root_of) are
    /// symbol-space-agnostic (they read only `(defining_canonical,
    /// merged_symbol_name)`).
    ///
    /// The post-query projection is THIN / non-owning: the build returns
    /// the composed sub-query node directly (identity projection) and does
    /// NOT walk heritage and does NOT eagerly materialise members. A deep
    /// instance/static surface projection (heritage descent, member-demand
    /// materialisation) is not part of this producer.
    ///
    /// Self-rooting: the composed surface roots on the class
    /// declaration's own file-content version (re-sourced live from the
    /// indexed view, R6/R20), so a same-canonical edit misses the warm
    /// read. The cross-file dependency facts of the composed sub-query
    /// fan out to this build's fact tracer automatically. When the decl's
    /// live content version cannot be observed (the file is unknown to
    /// the live view) the build is marked non-cacheable (`cache_suppress`)
    /// — the value still flows to the caller, the memo refuses admission.
    pub(super) fn build_class_surface(
        &self,
        decl_slot: &crate::semantic_query::ResolvedDeclSlotIdentity,
        type_args: &Arc<[SemanticNodeId]>,
        side: crate::semantic_query::ClassSurfaceSide,
        context: crate::semantic_query::ClassSurfaceContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        use crate::semantic_query::{ClassSurfaceSide, ProjectionReductionContext};

        // Self-root the composed surface on the class declaration's own
        // live content version (R6/R20 — the key is content-free).
        let defining_canonical = &decl_slot.defining_canonical;
        let observed = self
            .ctx
            .ensure_indexed_ready_serve(defining_canonical.as_ref())
            .map(|serve| serve.indexed);
        let observed_self_roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> =
            match &observed {
                Some(indexed) => vec![(defining_canonical.clone(), indexed.whole_hash)],
                None => Vec::new(),
            };

        // Dual-space — both sides route through `execute` (the ONE shared
        // engine). No query-time OXC. The env-bearing `ResolvedDeclSlotIdentity`
        // base / `value_root_of` read only
        // `(defining_canonical, merged_symbol_name)`, so the slot's
        // `symbol_space` is not re-tagged here — `side` is the selector.
        let composed = match side {
            ClassSurfaceSide::Instance => {
                // Instance side = the TYPE-space half: instantiate under
                // Shallow. The class slot is already the env-bearing
                // type-space slot; canonicalize its symbol space to `Type`
                // for the `Instantiate` base (the dual-space selector is
                // `side`, not the slot's space).
                let base =
                    decl_slot.with_symbol_space(crate::semantic_query::SemanticSymbolSpace::Type);
                let inst_ctx = self.instantiate_context_for(
                    &decl_slot.defining_canonical,
                    ProjectionReductionContext::published(ProjectionMode::Shallow),
                );
                self.execute_read(SemanticQueryKey::Instantiate(
                    crate::semantic_query::InstantiateKey::new(
                        base,
                        Arc::clone(type_args),
                        inst_ctx,
                    ),
                ))
            }
            ClassSurfaceSide::Static => {
                // Static side — the OWNING composer. Own statics + own
                // ctor come from the prepared VALUE decl's constructor
                // shape (lowered directly — never a `TypeOf` re-dispatch,
                // which would recurse: `build_typeof` delegates class
                // values HERE). Base statics compose recursively through
                // the SAME keyed query via the type-side heritage refs on
                // the sibling slot's `PreparedTypeDecl.body` (Intersection
                // fold, base-first), with shadow precedence: own members
                // shadow base members; an own DECLARED ctor replaces the
                // base's; a ctor-LESS subclass inherits the base ctor's
                // parameters with the DERIVED instance return. Heritage
                // type-arguments (`extends Base<string>`) lower in THIS
                // class's defining scope and ride the recursive base key's
                // `type_args` — instantiated surfaces are semantic meaning,
                // so the substitution is part of the base query identity.
                // The key's own `type_args` specialize THIS class's type
                // parameters across the composed surface: statics cannot
                // legally reference class type parameters (TS2302), so the
                // substitution reaches only the constructor signatures the
                // shells survive into (a static method's OWN same-name
                // generic is protected by the shadow-aware collection).
                // The composed surface carries the `prototype` property the
                // checker gives every class constructor type
                // ([`Self::with_class_prototype_property`]), so `keyof`,
                // indexed access, property reads and relations all read it.
                //
                // Effective post-fallback identity (the ONE shared
                // export-target fallback rail — `build_typeof` keys NEW
                // slots with it already): a slot that still names a
                // re-exporting canonical rebases HERE, so the constructor
                // shape lowers in the DECLARING file's scope, heritage
                // reads the declaring type-side sibling decl, and the
                // entry self-roots on the declaring content version.
                let mut observed_self_roots = observed_self_roots;
                let effective = self.effective_prepared_value_decl(
                    defining_canonical.as_ref(),
                    decl_slot.owner,
                    decl_slot.merged_symbol_name.as_ref(),
                );
                let Some((own_canonical, own_owner, own_symbol, prepared)) = effective else {
                    let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
                        (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    if observed.is_none() {
                        output.cache_suppress = true;
                    }
                    return output.with_observed_self_roots(observed_self_roots);
                };
                let mut effective_root_missing = false;
                if own_canonical.as_ref() != defining_canonical.as_ref() {
                    // Self-root derivation observes the declaring file's
                    // whole hash; fenced-ness flows via the chokepoint flag
                    // into the dispatch executor's admission gate.
                    match self
                        .ctx
                        .ensure_indexed_ready_serve(own_canonical.as_ref())
                        .map(|serve| serve.indexed)
                    {
                        Some(indexed) => {
                            observed_self_roots.push((own_canonical.clone(), indexed.whole_hash))
                        }
                        // The declaring file's content version could not be
                        // observed — refuse warm admission (the value would
                        // otherwise survive a declaring-file edit).
                        None => effective_root_missing = true,
                    }
                }
                let own = self.lower_class_constructor_object(
                    own_canonical.as_ref(),
                    own_owner,
                    own_symbol.as_ref(),
                    &prepared,
                    ProjectionReductionContext::published(context.mode),
                );
                let Some(own_node) = own else {
                    let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
                        (QueryResult::Error(QueryError::Miss), empty_signature()).into();
                    if observed.is_none() || effective_root_missing {
                        output.cache_suppress = true;
                    }
                    return output.with_observed_self_roots(observed_self_roots);
                };
                let (base_surfaces, composed_partial) = self.class_base_static_surfaces(
                    own_canonical.as_ref(),
                    own_owner,
                    own_symbol.as_ref(),
                    context.mode,
                );
                let mut composed_node =
                    base_surfaces.into_iter().fold(own_node, |composed, base| {
                        self.merge_static_surfaces(composed, base)
                    });
                composed_node = self.with_class_prototype_property(
                    own_canonical.as_ref(),
                    own_owner,
                    own_symbol.as_ref(),
                    composed_node,
                );
                // Specialize THIS class's own type parameters with the key's
                // `type_args` (produced by a derived class's heritage hop
                // above, or any caller instantiating the static surface).
                // With no key arguments, the class's type parameters are its
                // construct signatures' OWN clause instead (`new <T>(v: T) =>
                // C<T>`), so a `new C(…)` infers them from its arguments.
                composed_node = if type_args.is_empty() {
                    self.generic_class_construct_signatures(
                        own_canonical.as_ref(),
                        own_owner,
                        own_symbol.as_ref(),
                        composed_node,
                    )
                } else {
                    self.apply_class_surface_type_args(
                        own_canonical.as_ref(),
                        own_owner,
                        own_symbol.as_ref(),
                        composed_node,
                        type_args,
                    )
                };
                let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput = (
                    QueryResult::Value(composed_node),
                    self.project_generation_signature(),
                )
                    .into();
                output.fold_partial(composed_partial);
                if observed.is_none() || effective_root_missing {
                    output.cache_suppress = true;
                }
                output.approximation = Some(if composed_partial {
                    super::projection_fact::ProjectionInterpretation::PresenceOnly
                } else {
                    super::projection_fact::ProjectionInterpretation::Positional
                });
                return output.with_observed_self_roots(observed_self_roots);
            }
        };

        // Two-signal fold: fold the composed sub-query read's partiality so
        // a budget/recursion/walker-fatal nested side surfaces as a partial
        // (it would otherwise return through the identity projection with
        // `result_is_partial=false`).
        let composed_is_partial = composed.result_is_partial();
        // Identity projection: return the composed sub-query node directly.
        let result = composed.value;
        let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
            (result, self.project_generation_signature()).into();
        output.fold_partial(composed_is_partial);
        if observed.is_none() {
            // Could not self-root on the decl's live content version —
            // refuse warm admission; the value still flows to the caller.
            output.cache_suppress = true;
        }
        output
            .with_observed_self_roots(observed_self_roots)
            .with_positional_guarantee()
    }

    /// The EFFECTIVE prepared VALUE-decl identity for a `(canonical,
    /// symbol)` root: the root itself when its prepared value decl exists
    /// locally; otherwise the value-export-target walk's declaring identity
    /// (the post-fallback canonical) — the ONE shared fallback rail for
    /// re-exported value roots (`build_typeof`, the class-surface Static
    /// composer, and the `Enum.Member` projection hook all consume it, so the
    /// rails cannot drift). Returns `None` when neither side has a prepared
    /// value decl.
    pub(super) fn effective_prepared_value_decl(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
    ) -> Option<EffectivePreparedValueDecl> {
        if let Some(prepared) = self
            .ctx
            .prepared_value_decl_return_only(canonical, owner, symbol)
        {
            return Some((
                verter_type_expr::OwnedStr::from(canonical),
                owner,
                verter_type_expr::OwnedStr::from(symbol),
                prepared,
            ));
        }
        if canonical.is_empty() {
            return None;
        }
        let target = self.ctx.resolve_value_export_target(canonical, symbol)?;
        if target.canonical_id == canonical && target.owner == owner && target.name == symbol {
            return None;
        }
        let prepared = self.ctx.prepared_value_decl_return_only(
            &target.canonical_id,
            target.owner,
            &target.name,
        )?;
        Some((
            verter_type_expr::OwnedStr::from(target.canonical_id.as_str()),
            target.owner,
            verter_type_expr::OwnedStr::from(target.name.as_str()),
            prepared,
        ))
    }

    /// The exact ambient inventory wins over file/export fallback when a
    /// caller already carries its module scope.
    pub(super) fn effective_prepared_value_decl_in_augmentation(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> Option<EffectivePreparedValueDecl> {
        let Some(augmentation) = augmentation else {
            return self.effective_prepared_value_decl(canonical, owner, symbol);
        };
        let bundle = self.ctx.prepared_decl_bundle(canonical)?;
        match self
            .ctx
            .prepare_augmentation_value(&bundle, augmentation, owner, symbol)
        {
            verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(Some(prepared)) => {
                Some((
                    canonical.into(),
                    owner,
                    symbol.into(),
                    verter_retention::heap_size::OwnedValue::new(prepared),
                ))
            }
            verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(None) => None,
            verter_session_query::inputs::prepared::PreparedDeclOutcome::LeaseMiss
            | verter_session_query::inputs::prepared::PreparedDeclOutcome::Failed(_) => {
                self.fold_into_top_build_local_taint(false, true);
                crate::fact_tracing::note_non_cacheable_read_fan_out(
                    verter_session_query::facts::reuse::NonCacheableReadReason::UnobservableSource,
                );
                None
            }
        }
    }

    /// Recover a value root's retained augmentation inventory: the
    /// `declare module "…"` or `declare global` block scope it heads in.
    pub(super) fn ambient_value_scope<'headers>(
        scope: &crate::semantic_query::ScopeId,
        headers: &'headers verter_session_query::declarations::header_index::DeclHeaderIndex,
    ) -> Option<&'headers verter_session_query::declarations::AugmentationScopeKind> {
        if scope.binder_scope_id == crate::semantic_query::BinderScopeId::file_scope(scope.owner) {
            return None;
        }
        headers.augmentation_blocks.iter().find_map(|block| {
            use verter_session_query::declarations::AugmentationScopeKind;
            let block_scope_id = match &block.scope {
                AugmentationScopeKind::Module(specifier) => {
                    crate::semantic_query::BinderScopeId::augmentation_module_scope(
                        block.owner,
                        specifier.as_str().into(),
                    )
                }
                AugmentationScopeKind::Global => {
                    crate::semantic_query::BinderScopeId::augmentation_global_scope(block.owner)
                }
            };
            (block.owner == scope.owner && scope.binder_scope_id == block_scope_id)
                .then_some(&block.scope)
        })
    }

    /// `ResolveOverloadSet` — the ordered candidates of ONE of a callee's
    /// signature buckets.
    ///
    /// The candidates are the callee's shared signature list of `kind`
    /// (`SignaturesOfType`); the public `execute` boundary converts the
    /// produced group node into the `OverloadSet(Arc<[SignatureRef]>)`
    /// value domain. Carrier settlement, alias and constraint hops,
    /// apparent globals, and the union and intersection procedures all
    /// belong to the list: a union callee arrives as its common or
    /// synthesized union signatures, never as per-arm buckets. Visibility
    /// is `build_typeof`'s projection rule, applied upstream where the
    /// callee node was produced. The OTHER bucket is never read: a call
    /// site demands exactly its own bucket, so that bucket's settlement is
    /// the only settlement that gates the set.
    ///
    /// - A callee whose bucket is complete and empty is an honest `Miss`.
    /// - A bucket that did not settle is a `Miss` that is never admitted.
    /// - Non-empty `type_args` instantiate each candidate positionally; a
    ///   candidate that cannot accept the argument list DROPS from the set
    ///   (TS overload resolution under explicit type arguments);
    ///   all-dropped is an honest `Miss`.
    ///
    /// Self-version rooting: on the file-derived origins of EVERY input
    /// node — the callee AND each explicit type argument — plus the
    /// produced group, collected transitively so a scope-less composite
    /// roots on every file leaf. An incomplete self-root proof is
    /// `cache_suppress`ed: origin is provenance, never the admission
    /// oracle.
    pub(super) fn build_resolve_overload_set(
        &self,
        callee: SemanticNodeId,
        kind: crate::semantic_query::SignatureKind,
        type_args: &Arc<[SemanticNodeId]>,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let miss = || -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
            (QueryResult::Error(QueryError::Miss), empty_signature()).into()
        };
        // The candidates ARE the shared signature list of the callee's
        // requested bucket, in the order call resolution tries them. The
        // list owns carrier settlement, alias and constraint hops, apparent
        // globals, and the union and intersection procedures, and the kernel
        // owns the resolution order; this reducer chooses nothing.
        let sigs = match self.shared_signature_nodes_in_resolution_order(callee, kind) {
            super::signature_discovery::SharedSignatureNodes::Nodes(nodes) => nodes,
            super::signature_discovery::SharedSignatureNodes::Incomplete(_) => {
                // An unsettled list is never a proven-empty one: the miss
                // is not admitted, so the next read settles it again.
                let mut output = miss();
                output.cache_suppress = true;
                return output;
            }
        };
        if sigs.is_empty() {
            return miss();
        }
        let result_node = if type_args.is_empty() {
            self.overload_group_node(kind, sigs)
        } else {
            match self.instantiate_overload_group(kind, &sigs, type_args) {
                Some(node) => node,
                None => return miss(),
            }
        };

        let (observed_self_roots, proof_complete) = match self.transitive_self_roots_from_nodes(
            std::iter::once(callee)
                .chain(type_args.iter().copied())
                .chain(std::iter::once(result_node)),
        ) {
            Ok(roots) => (roots, true),
            Err(_) => (Vec::new(), false),
        };
        let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
            crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(result_node),
                self.project_generation_signature(),
            ))
            .with_observed_self_roots(observed_self_roots);
        output.cache_suppress |= !proof_complete;
        output
    }

    /// The group-bearing node of one ordered candidate list of `kind`: a
    /// lone signature IS its group, anything else is a signature-only
    /// surface carrying that one bucket.
    fn overload_group_node(
        &self,
        kind: crate::semantic_query::SignatureKind,
        sigs: Vec<SemanticNodeId>,
    ) -> SemanticNodeId {
        if let [lone] = sigs.as_slice() {
            return *lone;
        }
        let sigs: Arc<[SemanticNodeId]> = Arc::from(sigs.into_boxed_slice());
        let empty: Arc<[SemanticNodeId]> = Arc::from(Vec::new().into_boxed_slice());
        let (call_signatures, construct_signatures) = match kind {
            crate::semantic_query::SignatureKind::Call => (sigs, empty),
            crate::semantic_query::SignatureKind::Construct => (empty, sigs),
        };
        self.graph().intern_node(SemanticNodeData::Object(
            crate::semantic_query::surface_view! {
                members: Arc::from(Vec::new().into_boxed_slice()),
                call_signatures,
                construct_signatures,
                index_signatures: Arc::from(Vec::new().into_boxed_slice()),
                keyspace: None,
                has_index_signature: false,
            },
        ))
    }

    /// Apply explicit type arguments to an ordered overload group of
    /// `kind`: instantiate per candidate; a candidate that cannot accept
    /// the argument list DROPS from the set; all-dropped is `None`.
    fn instantiate_overload_group(
        &self,
        kind: crate::semantic_query::SignatureKind,
        sigs: &[SemanticNodeId],
        type_args: &Arc<[SemanticNodeId]>,
    ) -> Option<SemanticNodeId> {
        let instantiated: Vec<SemanticNodeId> = sigs
            .iter()
            .filter_map(|sig| self.instantiate_call_candidate(*sig, type_args))
            .collect();
        if instantiated.is_empty() {
            return None;
        }
        Some(self.overload_group_node(kind, instantiated))
    }

    /// Lower the class's OWN constructor-object surface — the prepared
    /// VALUE decl's `object_shape` (construct signature + own statics with
    /// visibility) — in the DECLARING file's scope. The own half of the
    /// `ResolveClassSurface::Static` composer; heritage is composed by the
    /// caller, which also resolves the effective post-fallback identity
    /// (`canonical`/`symbol`/`prepared` arrive already rebased — this
    /// helper performs NO export-target walk of its own). Returns `None`
    /// when the declaring file cannot be indexed or the prepared decl
    /// carries no constructor shape.
    fn lower_class_constructor_object(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        let indexed = self.ctx.ensure_indexed_ready_serve(canonical)?.indexed;
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        // The constructor-object SHAPE is a narrowed fact whose member value
        // positions are content-free locators — the authored surface lowers
        // through the ONE located body source (the value anchor's whole
        // position; the transient value-part re-borrow serves the
        // constructor shape when no annotation shadows it).
        prepared.object_shape.as_ref()?;
        // Bind the class's OWN type parameters as `TypeParam` shells so a
        // declared `constructor(x: T)` lowers `T` to the substitutable
        // binder node (the heritage hop specializes it through the key's
        // `type_args`). Statics cannot legally reference class type
        // parameters, so the shells surface only through the ctor. The
        // located pipeline re-derives the SAME binder identities from the
        // class's narrow parameter facts and substitutes these shells in.
        let env =
            self.class_type_param_shell_env(canonical, owner, symbol, indexed.whole_hash, &scope);
        let class_type_params = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
            .map(|type_side| type_side.type_parameters.clone())
            .unwrap_or_default();
        // The class header owns signature sources before a member body can
        // demand this same constructor. Deferred sources retain the actual
        // header binder images for the later value demand.
        let _header = super::flow_return_fact::SignatureSourceHeaderGuard::enter(
            &self.signature_source_headers,
            canonical,
            owner,
            symbol,
        );
        let mut substitutions = Vec::new();
        let source = verter_type_expr::locators::AuthoredBodyLocator::DeclBody(
            verter_type_expr::locators::TypeBodySlot {
                anchor: verter_type_expr::locators::AuthoredAnchor {
                    canonical_id: verter_type_expr::OwnedStr::from(canonical),
                    owner,
                    symbol: verter_type_expr::OwnedStr::from(symbol),
                    space: verter_type_expr::locators::LocatorSymbolSpace::Value,
                },
                path: verter_type_expr::OwnedSlice::default(),
            },
        );
        let QueryResult::Value(shape) = self.lower_locator(source) else {
            return None;
        };
        // Constructor composition consumes the indexed header, not its static
        // property values. Preserve their source carriers until a member demand
        // selects them; projecting the whole shape would evaluate every field.
        let shape = self.bind_located_shape_parameters(
            shape,
            &verter_type_expr::OwnedStr::from(symbol),
            &class_type_params,
            &env,
            &scope,
            &mut substitutions,
            None,
        );
        let shape = self.normalize_class_initializers(shape, self.nullability_for(canonical));
        if context.mode != ProjectionMode::Expanded {
            return Some(shape);
        }
        let graph = self.graph();
        let Some(SemanticNodeData::Object(view)) = graph
            .node_data(shape)
            .as_deref()
            .map(crate::semantic_query::SemanticNodeData::clone)
        else {
            return Some(shape);
        };
        // An expanded constructor demand owns its return position. Project
        // only that instance source; sibling static values remain deferred.
        let entries = view
            .entries
            .iter()
            .map(|entry| {
                let SurfaceEntry::ConstructSignature(signature) = entry else {
                    return entry.clone();
                };
                let Some(mut data) = graph
                    .node_data(*signature)
                    .as_deref()
                    .map(crate::semantic_query::SemanticNodeData::clone)
                else {
                    return entry.clone();
                };
                if let SemanticNodeData::Signature {
                    return_type,
                    return_carrier:
                        carrier @ crate::semantic_query::SignatureReturnCarrier::Declared(_),
                    ..
                } = &mut data
                {
                    *return_type = self.resolve_signature_source_carrier(*return_type, context);
                    *carrier =
                        crate::semantic_query::SignatureReturnCarrier::Declared(*return_type);
                }
                SurfaceEntry::ConstructSignature(graph.intern_preserving_scope(*signature, data))
            })
            .collect();
        Some(graph.intern_preserving_scope(
            shape,
            SemanticNodeData::Object(SurfaceView::from_entries(
                entries,
                view.keyspace,
                view.has_known_index_signature(),
            )),
        ))
    }

    /// The static surfaces a class's heritage contributes, base by base in
    /// clause order — each base's composed static side (or a value base's
    /// constructor surface), instantiated with the clause's type arguments —
    /// and whether any base read was partial.
    fn class_base_static_surfaces(
        &self,
        own_canonical: &str,
        own_owner: verter_type_expr::TopLevelOwnerId,
        own_symbol: &str,
        mode: ProjectionMode,
    ) -> (Vec<SemanticNodeId>, bool) {
        use crate::semantic_query::{ClassSurfaceSide, ProjectionReductionContext};
        let mut surfaces = Vec::new();
        let mut partial = false;
        for (base_canonical, base_owner, base_name, base_args) in
            self.class_heritage_bases(own_canonical, own_owner, own_symbol)
        {
            let lowered_args: Vec<SemanticNodeId> = if base_args.is_empty() {
                Vec::new()
            } else {
                match self.lower_class_heritage_args(
                    own_canonical,
                    own_owner,
                    own_symbol,
                    base_args.as_ref(),
                    mode,
                ) {
                    Some(nodes) => nodes,
                    // The authored argument positions could not be
                    // re-borrowed (broken lease / drift) — never
                    // fabricate a differently-instantiated base; this
                    // base contributes nothing.
                    None => continue,
                }
            };
            // A base that names a value the type space does not
            // declare contributes its constructor type's members
            // and construct signatures.
            if self.heritage_names_value_only(&base_canonical, base_owner, &base_name) {
                if let Some(base) = self.class_value_base(
                    &verter_type_expr::OwnedStr::from(&base_canonical),
                    base_owner,
                    &verter_type_expr::OwnedStr::from(&base_name),
                    &lowered_args,
                    ProjectionReductionContext::published(mode),
                ) {
                    let base_node = self.class_value_base_static_surface(
                        &base,
                        ProjectionReductionContext::published(mode),
                    );
                    surfaces.push(base_node);
                }
                continue;
            }
            let base_slot =
                self.type_slot_for(base_canonical.clone(), base_owner, base_name.clone());
            let base_context = self.class_surface_context_for(base_canonical.as_ref(), mode);
            let read = self.execute_read(SemanticQueryKey::ResolveClassSurface {
                decl_slot: base_slot,
                type_args: Arc::from(lowered_args.into_boxed_slice()),
                side: ClassSurfaceSide::Static,
                context: base_context,
            });
            partial |= read.result_is_partial();
            if let QueryResult::Value(base_node) = read.value {
                surfaces.push(base_node);
            }
        }
        (surfaces, partial)
    }

    /// Interned `TypeParam` shell nodes for a class declaration's own type
    /// parameters, env-keyed by parameter name. Bound during value-side
    /// constructor-shape lowering and heritage-argument lowering so the
    /// class-level binders stay substitutable (mirrors `build_instantiate`'s
    /// Skeleton shell binding). A class with no type-side sibling decl (or
    /// no parameters) yields an empty env.
    fn class_type_param_shell_env(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        whole_hash: crate::semantic_query::HashValue,
        scope: &NodeScopeId,
    ) -> FxHashMap<String, SemanticNodeId> {
        let mut env: FxHashMap<String, SemanticNodeId> = FxHashMap::default();
        let Some(type_decl) = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
        else {
            return env;
        };
        for (index, param) in type_decl.type_parameters.iter().enumerate() {
            let shell = self.graph().intern_node_with_scope(
                SemanticNodeData::TypeParam {
                    decl: crate::semantic_query::DeclIdentity {
                        canonical_id: verter_type_expr::OwnedStr::from(canonical),
                        owner,
                        whole_hash,
                        decl_name: verter_type_expr::OwnedStr::from(symbol),
                    },
                    param_index: index as u16,
                    constraint: None,
                    default: None,
                    display_name: OwnedStr::from(param.name.as_str()),
                },
                scope.clone(),
            );
            env.insert(param.name.clone(), shell);
        }
        env
    }

    /// Lower a heritage clause's type-arguments (`extends Base<...>`) in the
    /// DERIVED class's defining scope — the arguments are authored there, so
    /// imports resolve through the derived decl's `name_resolution` and the
    /// derived class's own type parameters bind as shells (`class Mid<U>
    /// extends Base<U>` lowers `U` to Mid's binder shell, which Mid's own
    /// `type_args` substitution later specializes).
    ///
    /// The arguments arrive as producer-minted content-free
    /// [`TypeArgLocator`](verter_type_expr::locators::TypeArgLocator)s (the
    /// heritage-base FACT's argument positions): each derefs LAZILY here —
    /// only when the Static composer demands the base — through the ONE
    /// shared locator-deref (lease-only), then lowers through the shared
    /// lowering path. Fail-closed: `None` when an authored argument position
    /// cannot be re-borrowed (broken lease / drift) — the caller must not
    /// fabricate a differently-instantiated base.
    fn lower_class_heritage_args(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        args: &[verter_type_expr::locators::TypeArgLocator],
        mode: crate::semantic_query::ProjectionMode,
    ) -> Option<Vec<SemanticNodeId>> {
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(canonical)
            .map(|serve| serve.indexed)?;
        let type_decl = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)?;
        // Deref each authored argument position through the shared
        // locator-deref — a typed deref failure fails the whole argument
        // list closed (never a fabricated / partially-instantiated base).
        let mut authored: Vec<TypeExpr> = Vec::with_capacity(args.len());
        for locator in args {
            match self
                .ctx
                .deref_type_argument(&indexed.shallow_state, locator)
            {
                Ok(expr) => authored.push(expr),
                Err(_) => return None,
            }
        }
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        let scope_payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
            crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                &bundle, owner,
            )
        });
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let env =
            self.class_type_param_shell_env(canonical, owner, symbol, indexed.whole_hash, &scope);
        let mut substitutions = Vec::new();
        Some(
            authored
                .iter()
                .zip(args.iter())
                .map(|(arg, locator)| {
                    let infer_binders =
                        crate::semantic_query::InferBinderFactory::for_authored_type_arg_locator(
                            &scope, arg, locator,
                        );
                    self.lower_type_expr_with_infer_factory(
                        &infer_binders,
                        arg,
                        &env,
                        &scope,
                        &type_decl.name_resolution,
                        scope_payload.as_ref(),
                        &shadowing,
                        &mut substitutions,
                        crate::semantic_query::ProjectionReductionContext::published(mode),
                    )
                })
                .collect(),
        )
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn lower_class_heritage_args_for_tests(
        &self,
        canonical: &str,
        symbol: &str,
    ) -> Vec<SemanticNodeId> {
        let owner = verter_type_expr::TopLevelOwnerId::ordinary_file();
        let (_, _, _, locators) = self
            .class_heritage_bases(canonical, owner, symbol)
            .into_iter()
            .next()
            .expect("test class must have one prepared heritage base");
        self.lower_class_heritage_args(
            canonical,
            owner,
            symbol,
            &locators,
            crate::semantic_query::ProjectionMode::Shallow,
        )
        .expect("prepared heritage arguments must dereference")
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn lower_class_heritage_args_via_body_locator_for_tests(
        &self,
        canonical: &str,
        symbol: &str,
    ) -> Vec<SemanticNodeId> {
        let owner = verter_type_expr::TopLevelOwnerId::ordinary_file();
        let (_, _, _, locators) = self
            .class_heritage_bases(canonical, owner, symbol)
            .into_iter()
            .next()
            .expect("test class must have one prepared heritage base");
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(canonical)
            .expect("test class must be indexed")
            .indexed;
        let type_decl = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
            .expect("test class must be prepared");
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        let scope_payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
            crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                &bundle, owner,
            )
        });
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let env =
            self.class_type_param_shell_env(canonical, owner, symbol, indexed.whole_hash, &scope);
        let mut substitutions = Vec::new();
        locators
            .iter()
            .map(|locator| {
                let arg = self
                    .ctx
                    .deref_type_argument(&indexed.shallow_state, locator)
                    .expect("test heritage argument must dereference");
                let body_locator =
                    crate::semantic_query::InferBinderFactory::authored_body_locator_for_type_arg(
                        locator,
                    );
                self.shallow_lower_type_expr_with_context_at_locator(
                    &arg,
                    &body_locator,
                    &env,
                    &scope,
                    &type_decl.name_resolution,
                    scope_payload.as_ref(),
                    &shadowing,
                    &mut substitutions,
                    crate::semantic_query::ProjectionReductionContext::published(
                        crate::semantic_query::ProjectionMode::Shallow,
                    ),
                )
            })
            .collect()
    }

    /// The composed static surface of a declared class with the `prototype`
    /// property the checker gives every class constructor type: the class
    /// instance with `any` for each of its type parameters
    /// (`getTypeOfPrototypeProperty` — `(typeof G)['prototype']` is
    /// `G<any>`), first among the members. It replaces a `prototype` the
    /// class declares as a static (TS2699, whose declared type the checker
    /// does not read) or inherits from its base's constructor.
    fn with_class_prototype_property(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        surface: SemanticNodeId,
    ) -> SemanticNodeId {
        let view = match self.graph().node_data(surface).as_deref() {
            Some(SemanticNodeData::Object(view)) => view.clone(),
            _ => return surface,
        };
        let Some(indexed) = self
            .ctx
            .ensure_indexed_ready_serve(canonical)
            .map(|serve| serve.indexed)
        else {
            return surface;
        };
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        let identity = crate::semantic_query::DeclIdentity::from_scope(&scope, Arc::from(symbol));
        let arity = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
            .map_or(0, |type_decl| type_decl.type_parameters.len());
        let prototype = if arity == 0 {
            self.graph()
                .intern_node_with_scope(SemanticNodeData::DeclRef { identity }, scope)
        } else {
            let any = self
                .graph()
                .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Any));
            let args: Arc<[SemanticNodeId]> = vec![any; arity].into();
            self.graph().intern_node_with_scope(
                SemanticNodeData::InstantiationRef {
                    base: identity,
                    args: crate::semantic_query::PayloadArray::from(args),
                },
                scope,
            )
        };
        let member =
            class_prototype_member(prototype, Some(verter_type_expr::OwnedStr::from(canonical)));
        let mut entries: Vec<SurfaceEntry> = Vec::with_capacity(view.entries.len() + 1);
        entries.push(SurfaceEntry::Member(member));
        entries.extend(
            view.entries
                .iter()
                .filter(|entry| {
                    !matches!(entry, SurfaceEntry::Member(existing)
                if existing.key.as_string() == Some("prototype"))
                })
                .map(crate::semantic_query::SurfaceEntry::clone),
        );
        self.graph()
            .intern_node(SemanticNodeData::Object(SurfaceView::from_entries(
                entries,
                view.keyspace,
                view.has_known_index_signature(),
            )))
    }

    /// Substitute a class's OWN type parameters positionally with the
    /// `ResolveClassSurface` key's `type_args` across the composed static
    /// surface. Unfilled trailing parameters keep their open shells (the
    /// instance rail's `Instantiate` owns default settlement). Collection is
    /// shadow-aware, so a static method re-declaring a same-name generic
    /// keeps its own binder.
    fn apply_class_surface_type_args(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        surface: SemanticNodeId,
        args: &Arc<[SemanticNodeId]>,
    ) -> SemanticNodeId {
        let Some(type_decl) = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
        else {
            return surface;
        };
        let mut result = surface;
        for (index, param) in type_decl.type_parameters.iter().enumerate() {
            let Some(arg) = args.get(index).copied() else {
                continue;
            };
            for binder in self.collect_type_param_nodes_by_name(
                result,
                param.name.as_str(),
                /* root_is_own_signature */ false,
                crate::semantic_query::ClauseSpelling::Bound,
            ) {
                result = self.substitute_semantic_type_param(result, binder, arg);
            }
        }
        result
    }

    /// The construct signatures of an UNAPPLIED generic class's static
    /// surface, generic over the class's own type parameters — the
    /// checker's class construct signature carries the class's
    /// `localTypeParameters` as its own clause and returns the class
    /// instance applied to them (`new <T>(v: T) => C<T>` for `class C<T>
    /// { constructor(v: T) }`), which is what lets a `new C(1)` infer `T`
    /// from its arguments. A derived class's inherited parameters already
    /// carry the derived class's binder shells (the heritage arguments are
    /// lowered in its scope), so they generalize over the derived clause.
    ///
    /// The class-level shells the constructor shape was lowered over are
    /// rewritten to the declaration-header binders, whose constraints and
    /// defaults the call executor reads, and the class-instance return
    /// becomes the class applied to those binders. A non-generic class, a
    /// class whose type-side declaration is unavailable, and a signature
    /// that already declares a clause are returned unchanged.
    fn generic_class_construct_signatures(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        surface: SemanticNodeId,
    ) -> SemanticNodeId {
        let Some(type_decl) = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
        else {
            return surface;
        };
        if type_decl.type_parameters.is_empty() {
            return surface;
        }
        let Some(indexed) = self
            .ctx
            .ensure_indexed_ready_serve(canonical)
            .map(|serve| serve.indexed)
        else {
            return surface;
        };
        let view = match self.graph().node_data(surface).as_deref() {
            Some(SemanticNodeData::Object(view)) if !view.construct_signatures.is_empty() => {
                view.clone()
            }
            _ => return surface,
        };
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        let shells =
            self.class_type_param_shell_env(canonical, owner, symbol, indexed.whole_hash, &scope);
        let binders = self.locator_binder_frame_from_narrow_params(
            &scope,
            &verter_type_expr::OwnedStr::from(symbol),
            &type_decl.type_parameters,
        );
        let clause: Vec<crate::semantic_query::TypeParamDecl> = binders
            .iter()
            .zip(type_decl.type_parameters.iter())
            .map(|((name, binder), param)| {
                let (constraint, default) = match self.graph().node_data(*binder).as_deref() {
                    Some(SemanticNodeData::TypeParam {
                        constraint,
                        default,
                        ..
                    }) => (*constraint, *default),
                    _ => (None, None),
                };
                crate::semantic_query::TypeParamDecl {
                    name: OwnedStr::from(name),
                    param: *binder,
                    constraint,
                    default,
                    original: None,
                    is_const: param.is_const,
                }
            })
            .collect();
        let clause: Arc<[crate::semantic_query::TypeParamDecl]> =
            Arc::from(clause.into_boxed_slice());
        let instance_args: Arc<[SemanticNodeId]> = binders
            .iter()
            .map(|(_, binder)| *binder)
            .collect::<Vec<_>>()
            .into();
        let generalize = |signature: SemanticNodeId| -> SemanticNodeId {
            let mut rebound = signature;
            for (name, binder) in binders.iter() {
                if let Some(shell) = shells.get(name.as_ref()) {
                    rebound = self.substitute_semantic_type_param(rebound, *shell, *binder);
                }
            }
            let Some(SemanticNodeData::Signature {
                kind,
                params,
                return_type,
                type_parameters,
                occurrence,
                return_carrier: _,
                signature_span,
                return_type_span,
                predicate,
                is_abstract,
            }) = self
                .graph()
                .node_data(rebound)
                .as_deref()
                .map(crate::semantic_query::SemanticNodeData::clone)
            else {
                return signature;
            };
            if !type_parameters.is_empty() {
                return signature;
            }
            let return_type = match self.graph().node_data(return_type).as_deref() {
                Some(SemanticNodeData::DeclRef { identity })
                    if identity.canonical_id.as_ref() == canonical
                        && identity.owner == owner
                        && identity.decl_name.as_ref() == symbol =>
                {
                    let scope = self
                        .graph()
                        .node_scope(return_type)
                        .unwrap_or_else(|| scope.clone());
                    self.graph().intern_node_with_scope(
                        SemanticNodeData::InstantiationRef {
                            base: identity.clone(),
                            args: crate::semantic_query::PayloadArray::from(Arc::clone(
                                &instance_args,
                            )),
                        },
                        scope,
                    )
                }
                _ => return_type,
            };
            self.graph().intern_node(SemanticNodeData::Signature {
                kind,
                params,
                return_type,
                type_parameters: crate::semantic_query::PayloadArray::from(Arc::clone(&clause)),
                occurrence,
                return_carrier: crate::semantic_query::SignatureReturnCarrier::Declared(
                    return_type,
                ),
                signature_span,
                return_type_span,
                predicate,
                is_abstract,
            })
        };
        let entries: Vec<SurfaceEntry> = view
            .entries
            .iter()
            .map(|entry| match entry {
                SurfaceEntry::ConstructSignature(signature) => {
                    SurfaceEntry::ConstructSignature(generalize(*signature))
                }
                other => other.clone(),
            })
            .collect();
        self.graph()
            .intern_node(SemanticNodeData::Object(SurfaceView::from_entries(
                entries,
                view.keyspace,
                view.has_known_index_signature(),
            )))
    }

    /// The class's heritage bases, base-first, read from the PRODUCER-MINTED
    /// content-free heritage-base FACTS on the type-side sibling slot's
    /// prepared decl (`PreparedTypeDecl.heritage_bases`, extracted once at
    /// lazy decl-body lowering from the class body's Intersection fold —
    /// heritage `Ref` arms before the own `Object` arm). This reader makes
    /// ZERO query-time `TypeExpr` decision: each fact's HEAD resolves here
    /// through the prepared decl's own `name_resolution` (import-aware; an
    /// unresolved bare name falls back to the same file), and the third
    /// element carries the fact's authored type-argument LOCATORS
    /// (`extends Base<string>`) — the Static composer derefs + lowers only
    /// the demanded arguments in the derived class's scope. Non-class decls
    /// and heritage-free classes return an empty list.
    pub(super) fn class_heritage_bases(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
    ) -> Vec<HeritageBase> {
        self.class_heritage_reading(canonical, owner, symbol).bases
    }

    /// [`Self::class_heritage_bases`] with the PROOF status of its own
    /// answer, read through ONE prepared-decl read.
    ///
    /// The base list alone is ambiguous: the SAME empty list stands for a
    /// heritage-free class, a declaration this generation cannot prepare at
    /// all (an unresolved heritage import), a NON-class declaration (an
    /// interface's `extends` arms are read by the ancestry authority
    /// alone), and a class whose `extends`
    /// clause is an EXPRESSION the fact producer could not name
    /// (`class X extends mixin(K) {}`). Only the first is a proof of
    /// absence. A NOMINAL consumer — anything that concludes "not derived"
    /// from a chain that failed to reach its target — must gate on
    /// `decidable` before publishing that conclusion; reading the emptiness
    /// alone turns an undecidable heritage into a fabricated negative. The
    /// STRUCTURAL composer needs no such gate: it composes exactly the
    /// bases it can read and never asserts a negative, which is why
    /// [`Self::class_heritage_bases`] keeps the bare list.
    pub(super) fn class_heritage_reading(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
    ) -> ClassHeritageReading {
        self.declared_heritage_reading(canonical, owner, symbol, false)
    }

    /// [`Self::class_heritage_reading`] of a class or, when `interfaces`
    /// holds, of an interface too: an interface's `extends` clauses are
    /// its bases (`hasBaseType` reads them), each an entity name the fact
    /// producer names.
    fn declared_heritage_reading(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        interfaces: bool,
    ) -> ClassHeritageReading {
        use verter_session_query::declarations::TypeDeclKind;
        let Some(prepared) = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, symbol)
        else {
            return ClassHeritageReading::undecidable();
        };
        let readable = match prepared.kind {
            TypeDeclKind::Class => true,
            TypeDeclKind::Interface => interfaces,
            _ => false,
        };
        if !readable {
            return ClassHeritageReading::undecidable();
        }
        let bases = prepared
            .heritage_bases
            .iter()
            .map(|fact| {
                match prepared
                    .name_resolution
                    .get(fact.name_resolution_ref.as_str())
                {
                    Some(root) => (
                        root.canonical_id.clone(),
                        root.owner,
                        root.symbol_name.clone(),
                        Arc::clone(&fact.type_args),
                    ),
                    // Same-file base not in the name-resolution map —
                    // resolve locally.
                    None => (
                        verter_type_expr::OwnedStr::from(canonical),
                        owner,
                        verter_type_expr::OwnedStr::from(fact.name.as_str()),
                        Arc::clone(&fact.type_args),
                    ),
                }
            })
            .collect();
        ClassHeritageReading {
            bases,
            decidable: !prepared.heritage_undecidable,
        }
    }

    /// Whether a class `extends` reference names a VALUE the type space
    /// does not declare — `class K extends Ctor` over `declare const Ctor:
    /// new () => …`. TypeScript resolves every class heritage through the
    /// value; a class base names a type as well, and its constructor's
    /// instance IS that type, so only a value-only name needs the value
    /// route ([`Self::class_value_base`]).
    pub(super) fn heritage_names_value_only(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
    ) -> bool {
        self.ctx
            .prepared_type_decl_return_only(canonical, owner, name)
            .is_none()
            && self
                .ctx
                .prepared_value_decl_return_only(canonical, owner, name)
                .is_some()
    }

    /// The base a class declaration's `extends` VALUE gives it — TypeScript's
    /// `getBaseConstructorTypeOfClass` and `resolveBaseTypesOfClass` over
    /// the value `name` declared at `(canonical, owner)`, with the heritage
    /// clause's type arguments `type_args`.
    ///
    /// The base constructor type is the value's type. Its construct
    /// signatures, instantiated with the type arguments (a signature that
    /// cannot take them drops), make the base constructor: the derived
    /// class's static side inherits its members, and a derived class
    /// without a constructor of its own inherits its construct signatures.
    /// The base INSTANCE type is the FIRST signature's return, and only an
    /// object type, `object`, `any` or an intersection of those is a base
    /// type (`isValidBaseType`). Measured on the pinned checker: over
    /// `declare const CtorO: { new (a: string): { o: 'str' }; new (a:
    /// number): { o: 'num' } }`, `KO['o']` is `"str"` (TS2510) while
    /// `ConstructorParameters<typeof KO>` is `[a: number]`; a union of
    /// constructors whose union signature returns a union gives no base
    /// type, and a value with no construct signature gives none (TS2507).
    pub(super) fn class_value_base(
        &self,
        canonical: &verter_type_expr::OwnedStr,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &verter_type_expr::OwnedStr,
        type_args: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<ClassValueBase> {
        let root = crate::semantic_query::ValueRootKey {
            scope: crate::semantic_query::ScopeId::file(canonical.clone(), owner),
            name: verter_type_expr::OwnedStr::from(name),
        };
        let constructor_type = match self
            .execute_read(self.typeof_key_with_path(
                root,
                verter_type_expr::OwnedSlice::from([]),
                context,
            ))
            .value
        {
            QueryResult::Value(node) => node,
            _ => return None,
        };
        let signatures = match self.shared_signature_nodes(
            constructor_type,
            crate::semantic_query::SignatureKind::Construct,
        ) {
            super::signature_discovery::SharedSignatureNodes::Nodes(nodes) => nodes,
            super::signature_discovery::SharedSignatureNodes::Incomplete(_) => return None,
        };
        let signatures: Vec<SemanticNodeId> = if type_args.is_empty() {
            signatures
        } else {
            signatures
                .into_iter()
                .filter_map(|signature| self.instantiate_call_candidate(signature, type_args))
                .collect()
        };
        // Only an object or intersection constructor type (or `any`) gives
        // base types; a union of constructors gives none, though its union
        // signature still constructs (measured on the pinned checker: over
        // `(new (x: string) => { a: 1 }) | (new (x: number) => { a: 1 })`
        // the derived class has no `a` and its constructor takes `x: never`).
        let settled_constructor = self.resolve_signature_source_carrier(constructor_type, context);
        let constructor_gives_bases = matches!(
            self.graph().node_data(settled_constructor).as_deref(),
            Some(
                SemanticNodeData::Object(_)
                    | SemanticNodeData::Signature { .. }
                    | SemanticNodeData::Intersection(_)
                    | SemanticNodeData::Primitive(PrimitiveKind::Any)
            )
        );
        let instance = signatures
            .first()
            .filter(|_| constructor_gives_bases)
            .and_then(|first| {
                let instance = match self.graph().node_data(*first).as_deref() {
                    Some(SemanticNodeData::Signature { return_type, .. }) => *return_type,
                    _ => return None,
                };
                let settled = self.resolve_signature_source_carrier(instance, context);
                self.is_valid_base_type(settled).then_some(instance)
            });
        Some(ClassValueBase {
            constructor_type,
            construct_signatures: signatures,
            instance,
        })
    }

    /// TypeScript's `isValidBaseType` over a settled node: an object type
    /// (an object surface, array, tuple, signature, class or interface
    /// instance), `object`, `any`, or an intersection of those, each arm
    /// settled through its carriers, at any nesting. A union or a primitive
    /// is not a base type, and neither is an intersection that contains
    /// itself.
    /// [`Self::is_valid_base_type`], for the tests beside this module.
    #[cfg(any(test, feature = "test-support"))]
    pub fn is_valid_base_type_for_tests(&self, node: SemanticNodeId) -> bool {
        self.is_valid_base_type(node)
    }

    fn is_valid_base_type(&self, node: SemanticNodeId) -> bool {
        use crate::graph_walk::Verdict;
        // The nodes already settled: the start, and each arm's settlement.
        let mut settled: FxHashSet<SemanticNodeId> = FxHashSet::from_iter([node]);
        crate::graph_walk::classify(node, |node| {
            if settled.insert(node) {
                let resolved = self.resolve_signature_source_carrier(
                    node,
                    crate::semantic_query::ProjectionReductionContext::structural_transit(),
                );
                if resolved != node {
                    settled.insert(resolved);
                    return Verdict::As(resolved);
                }
            }
            let Some(data) = self.graph().node_data(node) else {
                return Verdict::Leaf(Some(false));
            };
            Verdict::Leaf(Some(match data.as_ref() {
                SemanticNodeData::Object(_)
                | SemanticNodeData::Array { .. }
                | SemanticNodeData::Tuple { .. }
                | SemanticNodeData::Signature { .. }
                | SemanticNodeData::ClassExpressionInstance { .. }
                | SemanticNodeData::MergedDecl { .. }
                | SemanticNodeData::Primitive(PrimitiveKind::Object | PrimitiveKind::Any) => true,
                SemanticNodeData::DeclRef { identity }
                | SemanticNodeData::InstantiationRef { base: identity, .. } => matches!(
                    self.prepared_decl_kind(identity),
                    Some(
                        verter_session_query::declarations::TypeDeclKind::Interface
                            | verter_session_query::declarations::TypeDeclKind::Class
                    )
                ),
                SemanticNodeData::Intersection(arms) => {
                    return Verdict::All(arms.members_arc().to_vec());
                }
                _ => false,
            }))
        })
        .unwrap_or(false)
    }

    /// The static-side contribution of a class value base: the base
    /// constructor type's members with its construct signatures (already
    /// instantiated with the heritage type arguments), as one constructor
    /// surface [`Self::merge_static_surfaces`] composes under the derived
    /// class's own.
    pub(super) fn class_value_base_static_surface(
        &self,
        base: &ClassValueBase,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let settled = self.resolve_signature_source_carrier(base.constructor_type, context);
        let static_members: Arc<[SurfaceMember]> = match self.graph().node_data(settled).as_deref()
        {
            Some(SemanticNodeData::Object(view)) => view
                .positive_members()
                .iter()
                .map(crate::semantic_query::SurfaceMember::clone)
                .collect(),
            _ => Arc::from(Vec::new().into_boxed_slice()),
        };
        self.graph().intern_node(SemanticNodeData::Object(
            crate::semantic_query::surface_view! {
                members: static_members,
                call_signatures: Arc::from(Vec::new().into_boxed_slice()),
                construct_signatures: Arc::from(base.construct_signatures.clone().into_boxed_slice()),
                index_signatures: Arc::from(Vec::new().into_boxed_slice()),
                keyspace: None,
                has_index_signature: false,
            },
        ))
    }

    /// The TRANSITIVE class ancestry of one declaration — ONE heritage
    /// read from the asker's side, with this authority owning the
    /// recursive walk and memoizing its answer for the dispatch.
    ///
    /// Each distinct declaration is read at most once per walk
    /// (seen-guarded worklist, cycle-safe), a repeated QUESTION is a memo
    /// hit, and a hop whose own ancestry is already memoized is folded in
    /// whole instead of re-walked — so the reads a LONGER chain pays
    /// after a shorter one is cached are only the hops above it. The
    /// converse does not hold: a fresh walk memoizes the REQUESTED
    /// declaration only, so a shorter chain asked after a longer one
    /// re-walks the shared part. See
    /// [`ProjectSemanticDispatch::heritage_ancestry`] for why that is
    /// left alone.
    ///
    /// None of that is what bounds the caller. An `instanceof` guard over
    /// a union pays one ancestry QUESTION per arm per edge whatever the
    /// hierarchies look like, because the walk is on this side of the
    /// question.
    ///
    /// Every visited declaration must be OBSERVABLE and READABLE, or the
    /// answer is not a proof — see [`ClassAncestryReading::decided`]. The
    /// observations are returned rather than recorded here because the
    /// self-root set belongs to the asking computation, not to this
    /// authority.
    pub(super) fn class_heritage_ancestry(
        &self,
        root: &crate::semantic_query::DeclIdentity,
    ) -> Arc<ClassAncestryReading> {
        let key = (
            root.canonical_id.clone(),
            root.owner,
            root.decl_name.clone(),
        );
        if let Some(memo) = self.heritage_ancestry.borrow().get(&key) {
            return Arc::clone(memo);
        }
        let mut ancestors: Vec<crate::semantic_query::DeclIdentity> = Vec::new();
        let mut observed: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> = Vec::new();
        let mut decided = true;
        let mut queue: Vec<crate::semantic_query::DeclIdentity> = vec![root.clone()];
        while let Some(current) = queue.pop() {
            // A hop whose OWN ancestry is already memoized is folded in
            // whole rather than re-walked: its cached ancestors are
            // exactly its transitive ancestors, its observations are the
            // files that answer for them, and its proof status is the
            // proof status of that whole suffix. This is what makes the
            // per-declaration bound hold ACROSS questions — asking about
            // `Chain3` after `Chain1` is already cached stops at
            // `Chain1` instead of re-reading it.
            let cached = self
                .heritage_ancestry
                .borrow()
                .get(&(
                    current.canonical_id.clone(),
                    current.owner,
                    current.decl_name.clone(),
                ))
                .map(Arc::clone);
            if let Some(cached) = cached {
                if !cached.decided {
                    decided = false;
                }
                for observation in cached.observed.iter() {
                    if !observed.contains(observation) {
                        observed.push(observation.clone());
                    }
                }
                for ancestor in cached.ancestors.iter() {
                    if ancestors
                        .iter()
                        .chain(std::iter::once(root))
                        .any(|seen| same_class_identity(seen, ancestor))
                    {
                        continue;
                    }
                    ancestors.push(ancestor.clone());
                }
                continue;
            }
            match self
                .ctx
                .ensure_indexed_ready_serve(current.canonical_id.as_ref())
            {
                Some(serve) => {
                    let observation = (current.canonical_id.clone(), serve.indexed.whole_hash);
                    if !observed.contains(&observation) {
                        observed.push(observation);
                    }
                }
                // A file that cannot be served still contributes whatever
                // bases a request memo or a validated bundle cache answers
                // with, so the miss cannot be ignored: it leaves the answer
                // unrooted, which makes it no proof.
                None => decided = false,
            }
            let reading = self.declared_heritage_reading(
                &current.canonical_id,
                current.owner,
                &current.decl_name,
                true,
            );
            if !reading.decidable {
                decided = false;
            }
            for (base_canonical, base_owner, base_name, _args) in reading.bases {
                let base = crate::semantic_query::DeclIdentity {
                    canonical_id: base_canonical,
                    owner: base_owner,
                    whole_hash: crate::semantic_query::HashValue::default(),
                    decl_name: base_name,
                };
                if ancestors
                    .iter()
                    .chain(std::iter::once(root))
                    .any(|seen| same_class_identity(seen, &base))
                {
                    continue;
                }
                ancestors.push(base.clone());
                queue.push(base);
            }
        }
        let reading = Arc::new(ClassAncestryReading {
            ancestors,
            observed,
            decided,
        });
        self.heritage_ancestry
            .borrow_mut()
            .insert(key, Arc::clone(&reading));
        reading
    }

    /// Merge a class's own static surface with ONE base class's composed
    /// static surface (shadow precedence):
    ///
    /// - own members shadow base members by name (visibility carried);
    /// - an own DECLARED constructor (signature span present) replaces the
    ///   base's; a ctor-LESS class (its construct signatures are all
    ///   synthesized — no signature span) inherits the base constructor's
    ///   parameters with the DERIVED instance return type;
    /// - call/index signatures union own-first.
    ///
    /// Non-object inputs return `own` unchanged (a miss on either side
    /// never fabricates a surface).
    fn merge_static_surfaces(&self, own: SemanticNodeId, base: SemanticNodeId) -> SemanticNodeId {
        let Some(own_data) = self.graph().node_data(own) else {
            return own;
        };
        let SemanticNodeData::Object(own_view) = &*own_data else {
            return own;
        };
        let own_view = own_view.clone();
        drop(own_data);
        let Some(base_data) = self.graph().node_data(base) else {
            return own;
        };
        let SemanticNodeData::Object(base_view) = &*base_data else {
            return own;
        };
        let base_view = base_view.clone();
        drop(base_data);

        let mut members: Vec<SurfaceMember> = own_view
            .positive_members()
            .iter()
            .map(crate::semantic_query::SurfaceMember::clone)
            .collect::<Vec<_>>();
        for base_member in base_view.positive_members().iter() {
            if !members
                .iter()
                .any(|own_member| own_member.key == base_member.key)
            {
                members.push(base_member.clone());
            }
        }

        let function_signature_span = |node: SemanticNodeId| -> Option<verter_span::Span> {
            match self.graph().node_data(node).as_deref() {
                Some(SemanticNodeData::Signature { signature_span, .. }) => *signature_span,
                _ => None,
            }
        };
        let own_ctor_declared = own_view
            .construct_signatures
            .iter()
            .any(|sig| function_signature_span(*sig).is_some());
        let construct_signatures: Vec<SemanticNodeId> =
            if own_ctor_declared || base_view.construct_signatures.is_empty() {
                own_view.construct_signatures.to_vec()
            } else {
                // Ctor-less class: inherit the base constructor's parameters,
                // keep the DERIVED instance return (the own synthesized
                // construct signature's return IS the derived instance ref).
                let own_instance_return = own_view.construct_signatures.first().and_then(|sig| {
                    match self.graph().node_data(*sig).as_deref() {
                        Some(SemanticNodeData::Signature {
                            return_type,
                            is_abstract,
                            ..
                        }) => Some((*return_type, *is_abstract)),
                        _ => None,
                    }
                });
                match own_instance_return {
                    // The inherited signatures are the DERIVED class's: they
                    // are abstract exactly when it is
                    // (`getDefaultConstructSignatures`).
                    Some((derived_return, derived_abstract)) => base_view
                        .construct_signatures
                        .iter()
                        .map(
                            |base_sig| match self.graph().node_data(*base_sig).as_deref() {
                                Some(SemanticNodeData::Signature {
                                    kind,
                                    params,
                                    type_parameters,
                                    ..
                                }) => self.graph().intern_node(SemanticNodeData::Signature {
                                    kind: *kind,
                                    params: params.share(),
                                    return_type: derived_return,
                                    type_parameters: type_parameters.share(),
                                    // A synthesized inheritance twin — no
                                    // authored position of its own.
                                    occurrence: None,
                                    // The derived instance return is a
                                    // concrete seed.
                                    return_carrier:
                                        crate::semantic_query::SignatureReturnCarrier::Declared(
                                            derived_return,
                                        ),
                                    // Composed signature — no single source site.
                                    signature_span: None,
                                    return_type_span: None,
                                    // A construct signature carries no
                                    // predicate.
                                    predicate: None,
                                    is_abstract: derived_abstract,
                                }),
                                _ => *base_sig,
                            },
                        )
                        .collect(),
                    None => own_view.construct_signatures.to_vec(),
                }
            };

        // Union dedup is STRUCTURAL, not id-only: `intern_node_with_scope`
        // can fork two ids for byte-identical signature data lowered under
        // different scopes, and an id-only `contains` would double-list the
        // same declaration. Distinct declarations stay distinct — their
        // source spans participate in node data, so two same-shape
        // signatures from different sites never compare equal.
        let same_node_data = |a: SemanticNodeId, b: SemanticNodeId| -> bool {
            a == b || self.graph().node_data(a) == self.graph().node_data(b)
        };
        let mut call_signatures: Vec<SemanticNodeId> = own_view.call_signatures.to_vec();
        for sig in base_view.call_signatures.iter() {
            if !call_signatures
                .iter()
                .any(|existing| same_node_data(*existing, *sig))
            {
                call_signatures.push(*sig);
            }
        }
        let mut index_signatures = own_view
            .index_signatures
            .iter()
            .map(crate::semantic_query::IndexSignature::clone)
            .collect::<Vec<_>>();
        for sig in base_view.index_signatures.iter() {
            let duplicate = index_signatures.iter().any(|existing| {
                existing == sig
                    || (existing.readonly == sig.readonly
                        && existing.spans == sig.spans
                        && same_node_data(existing.key_type, sig.key_type)
                        && same_node_data(existing.value_type, sig.value_type))
            });
            if !duplicate {
                index_signatures.push(sig.clone());
            }
        }
        let has_index_signature = !index_signatures.is_empty();
        let mut remaining_members: indexmap::IndexMap<
            crate::semantic_query::AuthoredPropertyKey,
            SurfaceMember,
        > = members
            .into_iter()
            .map(|member| (member.key.clone(), member))
            .collect();
        let mut seen_calls = Vec::new();
        let mut seen_indexes = Vec::new();
        let mut emitted_constructs = false;
        let mut entries = Vec::new();
        for entry in own_view.entries.iter().chain(base_view.entries.iter()) {
            match entry {
                SurfaceEntry::Member(member) => {
                    if let Some(member) = remaining_members.shift_remove(&member.key) {
                        entries.push(SurfaceEntry::Member(member));
                    }
                }
                SurfaceEntry::CallSignature(signature)
                    if call_signatures
                        .iter()
                        .any(|candidate| same_node_data(*candidate, *signature))
                        && !seen_calls
                            .iter()
                            .any(|seen| same_node_data(*seen, *signature)) =>
                {
                    seen_calls.push(*signature);
                    entries.push(SurfaceEntry::CallSignature(*signature));
                }
                SurfaceEntry::ConstructSignature(_) if !emitted_constructs => {
                    emitted_constructs = true;
                    entries.extend(
                        construct_signatures
                            .iter()
                            .copied()
                            .map(SurfaceEntry::ConstructSignature),
                    );
                }
                SurfaceEntry::IndexSignature(signature)
                    if index_signatures.contains(signature)
                        && !seen_indexes.contains(signature) =>
                {
                    seen_indexes.push(signature.clone());
                    entries.push(SurfaceEntry::IndexSignature(signature.clone()));
                }
                _ => {}
            }
        }
        entries.extend(remaining_members.into_values().map(SurfaceEntry::Member));
        self.graph()
            .intern_node(SemanticNodeData::Object(SurfaceView::from_entries(
                entries,
                None,
                has_index_signature,
            )))
    }

    /// Generic instantiation.
    ///
    /// Receives the content-free `ResolvedDeclSlotIdentity` slot directly
    /// from the `Instantiate` key — declaration identity is part of the
    /// key rather than a separate `DeclAnchor` node. The slot carries the
    /// env dims only; the live content version (`decl_whole_hash`) is
    /// re-sourced at value-compute from
    /// `ensure_indexed_ready_serve(base.defining_canonical)`'s serve
    /// carrier `indexed.whole_hash`, never
    /// from the key. Fetches the [`PreparedTypeDecl`] via
    /// [`SessionDispatchHost`] and produces **one shell level** of the
    /// declaration's structural shape with `args` bound to the decl's
    /// type parameters.
    ///
    /// The `InstantiateContext`'s embedded `projection_reduction` mode
    /// controls how the decl body and its argument expressions are
    /// lowered after substitution. Memo entries split per the
    /// `InstantiateContext` (its `projection_reduction` mode plus the
    /// `resolve_env_hash` env dim; see `family_and_slot` in
    /// [`semantic_query_memo`](crate::semantic_query_memo)) so a Navigate
    /// caller and an Expanded caller never collide on the same shell
    /// result. Member bodies are not recursively lowered — nested
    /// references emit `Opaque(Miss)` placeholders per the
    /// lazy-materialisation rule; deeper lowering is driven by
    /// `ProjectPath` sub-queries through the family memo.
    ///
    /// Origin edges emitted:
    /// - One [`OriginEdgeKind::Instantiate`] edge on the result, sourced
    ///   from `[base_placeholder, args...]`.
    /// - One [`OriginEdgeKind::SubstituteTypeParam`] edge per type-parameter
    ///   reference visited at the shell level, sourced from the bound arg.
    pub(super) fn build_instantiate(
        &self,
        base: &crate::semantic_query::ResolvedDeclSlotIdentity,
        args: &Arc<[SemanticNodeId]>,
        source: &crate::semantic_query::InstantiateSource,
        instantiate_context: crate::semantic_query::InstantiateContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        match self.begin_instantiate(base, args, source, instantiate_context, false) {
            InstantiateStart::Done(output) => *output,
            InstantiateStart::Build(mut build) => match self.drain_instantiate(&mut build, None) {
                InstantiatePoll::Done(output) => *output,
                InstantiatePoll::Need(_) => {
                    unreachable!("an inline instantiation evaluates the instantiations it reaches")
                }
            },
        }
    }

    /// Begin a generic instantiation: answer it at once (an authored or
    /// `.vue` default instance, a builtin, a missing declaration, a
    /// same-declaration back-edge), or bind its arguments, enter the active
    /// instantiation and begin lowering its body — the build
    /// [`Self::drain_instantiate`] carries on. `suspend` makes the body
    /// projection stop at each instantiation it reaches instead of
    /// evaluating it in place.
    pub(super) fn begin_instantiate(
        &self,
        base: &crate::semantic_query::ResolvedDeclSlotIdentity,
        args: &Arc<[SemanticNodeId]>,
        source: &crate::semantic_query::InstantiateSource,
        instantiate_context: crate::semantic_query::InstantiateContext,
        suspend: bool,
    ) -> InstantiateStart {
        verter_audit::attribute_scope!(Instantiate);
        verter_audit::attribute_n!(Substitute, args.len());
        // The key carries an `InstantiateContext` (embedded
        // projection-reduction identity + the `resolve_env_hash` env dim).
        // Destructure into the embedded `ProjectionReductionContext` so the
        // rest of the lowering pipeline keeps consulting `context`
        // unchanged; `resolve_env_hash` is threaded onto any nested
        // `Instantiate` sub-key this build re-emits via
        // `instantiate_context_for`.
        let context = instantiate_context.projection_reduction();
        if let Some(authored) = source.authored_source() {
            return InstantiateStart::Done(Box::new(self.build_authored_instantiation(
                base,
                authored.identity().locator(),
                args,
                authored.projection(),
                instantiate_context,
            )));
        }
        // demand-driven reducer spec: the call-site provides
        // the publication / structural-transit context. `body_mode` is
        // shorthand for `context.mode` everywhere the existing lowering
        // pipeline consults it; the demand axis flows through to
        // builtin-utility dispatch and nested operator builders so a
        // `StructuralTransit` instantiation never reifies `keyof` /
        // `Mapped` operators along its decl body.
        let body_mode = context.mode;
        // Count Instantiate dispatches that ask for the Expanded body
        // mode. Used by the slot-binding regression `enrich_does_not_eagerly_instantiate_carrier`
        // to enforce that synthesis stays in Navigate mode and never
        // re-enters the giant-tree pathology through the carrier walk.
        //
        // Two counters are bumped: the process-global
        // `SLOT_BINDING_EXPANDED_INSTANTIATE_CALLS` (preserves existing
        // semantics for warm-pass tests that read it without an active
        // RequestContext) AND the active request's per-request mirror
        // when a context is installed in TLS. The per-request mirror
        // surfaces on the audit payload so attribution tests can assert
        // "no synthesis-attributable Instantiate{Expanded} fired during
        // this request" without false positives from peer dispatches in
        // workspace-parallel runs.
        if matches!(body_mode, crate::semantic_query::ProjectionMode::Expanded) {
            #[cfg(any(test, feature = "test-support", feature = "semantic-observe"))]
            if cfg!(any(test, feature = "test-support"))
                || <C::Observe as verter_audit::observe::ObserveExec>::CAPTURED
            {
                crate::loop5_instrumentation::SLOT_BINDING_EXPANDED_INSTANTIATE_CALLS
                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            }
            crate::observe_request!(C::Observe => on self.observation.request.as_deref() => |ctx| {
                ctx.expanded_instantiate_calls
                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            });
            // Synthesis-scoped attribution: bump the
            // synthesis-attributable counter ONLY when the slot-binding
            // synthesis phase is active. The request-wide counter above
            // also counts the canonical macro-surface PRODUCER's Expanded
            // expansions (legitimate); the synthesis-scoped counter isolates
            // "an Expanded Instantiate fired INSIDE slot-binding synthesis"
            // — the eagerness defect `enrich_does_not_eagerly_instantiate_carrier`
            // gates on (must stay zero).
            crate::request_context::note_expanded_instantiate_for_synthesis_scope::<C::Observe>(
                crate::resolver_core::resolver_context::capture_targets(self.ctx),
            );
        }

        let decl_canonical = &base.defining_canonical;
        let decl_owner = base.owner;
        let decl_name = &base.merged_symbol_name;

        // R6 / R20: the key is content-free. Re-source the base file's
        // content version from the live indexed view at value-build
        // time, so the cached `MemoEntry` self-roots on the current
        // generation's whole_hash. Three classes of non-file base
        // exist and must NOT invent a synthetic `FileWholeHash`:
        //  - the global / structural sentinel (`canonical_id == ""`);
        //  - built-in utility carriers (`canonical_id == "__builtin__"`);
        //  - synthetic test identities (`canonical_id == "<synthetic>"`).
        // These bases root self-version through their `args` nodes
        // only (no file fact). A real-file base whose `ensure_indexed_ready_serve`
        // returns `None` (the file is unknown to the live view) is a
        // stale key — the build cannot publish a cacheable result and
        // returns `cache_suppress` below.
        let decl_canonical_str = decl_canonical.as_ref();
        let is_non_file_base = crate::semantic_query::is_non_file_base(decl_canonical_str);
        let live_indexed: Option<Arc<verter_session_query::inputs::indexed::IndexedInputRecord>> =
            if is_non_file_base {
                None
            } else {
                self.transaction_indexed_record(decl_canonical_str)
            };
        let decl_whole_hash: crate::semantic_query::HashValue = match &live_indexed {
            Some(indexed) => indexed.whole_hash,
            None => crate::semantic_query::HashValue::default(),
        };

        // Intern a scope-carrying placeholder so the adapter lookups
        // (resolve_builtin_utility, resolve_prepared_type_decl) can look
        // up the declaration scope via node_scope(base).
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(decl_canonical),
            owner: decl_owner,
            whole_hash: decl_whole_hash,
            local_scope: None,
        };
        let base = self
            .graph()
            .intern_node_with_scope(SemanticNodeData::Opaque(QueryError::Miss), scope.clone());

        let adapter = SessionDispatchHost::from_facade(self);

        // 1b. `.vue` synthesized `default` public-instance dispatch.
        //
        // A `.vue` SFC has no userland `default` TYPE declaration — its public
        // component type is the SYNTHESIZED instance object
        // `{ $props, $emit, $slots }` carried as the construct-signature return
        // type of a synthesized `default` VALUE symbol
        // (`resolver_core::vue_default_synth`). `Instantiate{ .vue, "default", [] }`
        // is the SOLE semantic identity for that public instance — the public
        // API (`resolve_vue_public_type`) and a `.vue`-importing-`.vue` reference
        // (`Ref("Foo")` → `DeclRef{Foo.vue, "default"}` → `Instantiate`) BOTH
        // route here, so there is exactly one query identity and one resolver.
        //
        // Without this branch the query would fall through to
        // `resolve_prepared_type_decl` below (a `.vue` has no prepared `default`
        // TYPE decl) and miss. The branch is gated on the STRUCTURAL PROVENANCE
        // flag `is_synthesised_component_default` of the resolved `default` value
        // symbol (NOT the file-classifier `is_synthesis_candidate`), so a
        // userland `export default` — in a `.ts` file OR in a `.vue`'s
        // `<script>` block — is never hijacked even when its value type looks
        // instance-shaped. It requires `args.is_empty()` (the synthesized
        // default takes no type arguments).
        //
        // Termination is by query identity (NO depth bound): the memo's
        // same-key `Instantiate` recursion sentinel (`mod.rs`) returns
        // `Opaque(RecursiveRef)` for a circular `A.vue ↔ B.vue` import, and the
        // `push_instantiate_active`/`pop` discipline below catches same-identity
        // re-entry while the instance shape is lowering.
        if decl_name.as_ref() == "default"
            && args.is_empty()
            && self
                .ctx
                .ensure_indexed_ready_serve(decl_canonical.as_ref())
                .map(|serve| serve.indexed)
                .and_then(|indexed| {
                    indexed
                        .shallow_state
                        .value_symbol_in(decl_owner, "default")
                        .map(|sym| sym.is_synthesised_component_default)
                })
                .unwrap_or(false)
        {
            if let Some(output) = self.build_vue_default_instance(
                decl_canonical,
                decl_owner,
                decl_whole_hash,
                &scope,
                context,
            ) {
                return InstantiateStart::Done(Box::new(output));
            }
        }

        // The COMPLETE builtin application carrier, returned verbatim where
        // instantiating a builtin must not (or cannot) materialise a body.
        let builtin_identity = crate::semantic_query::DeclIdentity {
            canonical_id: decl_canonical.clone(),
            owner: decl_owner,
            whole_hash: decl_whole_hash,
            decl_name: decl_name.clone(),
        };
        let builtin_application_carrier = |identity: crate::semantic_query::DeclIdentity| {
            let carrier = self.graph().intern_node_with_scope(
                SemanticNodeData::InstantiationRef {
                    base: identity,
                    args: crate::semantic_query::PayloadArray::from(Arc::clone(args)),
                },
                scope.clone(),
            );
            // Mirror `build_builtin_utility`'s `Instantiate` origin edge so
            // origin-walks resolve through the carrier: sources are the
            // builtin base node + each arg.
            let fence = self.project_generation_signature();
            crate::semantic_query_memo::record_origin_edge!(
                self.graph(),
                carrier,
                OriginEdgeKind::Instantiate,
                std::iter::once(base).chain(args.iter().copied()).collect(),
                OriginMeta::None,
                fence.clone(),
            );
            // Root the carrier value on the same file-derived arg set the
            // materialised builtin would (an edit to a file-derived arg
            // rejects this entry on the strict warm-read validator).
            let observed_self_roots = self.observed_self_roots_from_nodes(args.iter().copied());
            let output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
                (QueryResult::Value(carrier), fence).into();
            output.with_observed_self_roots(observed_self_roots)
        };

        // 1c. A builtin runtime NOMINAL (`Promise<T>`, `Function`, …) has no
        // declaration body in this graph: its application carrier IS the
        // type, and its members come from the lib through the apparent
        // type. Instantiating it answers that carrier — `Promise<number>` is
        // `Promise<number>`, never a miss.
        if self.runtime_nominal_identity(&builtin_identity).is_some() {
            return InstantiateStart::Done(Box::new(builtin_application_carrier(builtin_identity)));
        }

        // 2. Built-in utility dispatch.
        // A utility name (Partial, Pick, ReturnType, etc.) that the user
        // has NOT shadowed routes through the utility-specific dispatch
        // path — producing the same shell structure + origin edges a
        // userland-equivalent alias would produce (userland-equivalence
        // rule). Shadowed names fall through to the ordinary
        // `resolve_prepared_type_decl` path.
        // One gate decision: the shadowing check and the proven identity come
        // from the same scope read.
        if let super::BuiltinUtilityResolution::Builtin(builtin_utility) =
            adapter.resolve_builtin_utility(base, decl_name.as_ref())
        {
            // Route/mode-INDEPENDENT L1 carrier-stop (Instantiate-EXECUTION
            // entrance). An object-filter builtin (`Pick`/`Omit`) whose
            // enumeration domain (argument 0) is OPEN must NOT route into
            // `build_builtin_utility` — that helper materialises argument 0's
            // source surface, which degenerates into full cross-file generic
            // expansion of an open source (the Table.vue
            // `Omit<CoreOptions<T>, …>` structural decl-body-lowering
            // memo-cycle). Instead return the COMPLETE `InstantiationRef`
            // carrier verbatim. The shared open-domain predicate decides
            // openness (no second walker); a CLOSED domain falls through to
            // `build_builtin_utility` and materialises path-precisely.
            if crate::project_semantic_dispatch::raise::utility_enumeration_domain_is_open_or_unknown(
                self,
                &builtin_identity,
                args.as_ref(),
            ) {
                return InstantiateStart::Done(Box::new(builtin_application_carrier(builtin_identity)));
            }

            return InstantiateStart::Done(Box::new(self.build_instantiated_builtin_utility(
                base,
                decl_name,
                args,
                context,
                builtin_utility,
            )));
        }

        // 3. Resolve prepared type decl via `SessionDispatchHost` — the adapter
        // routes through the sidecar-recorded scope for `base`.
        //
        // The prepared decl is recovered from the declaration artifact
        // pinned to `(decl_canonical, decl_whole_hash)` — `decl_whole_hash`
        // was re-sourced above from the live indexed view. When the
        // prepared decl cannot be recovered the result is left
        // non-cacheable (`cache_suppress`): the value still flows to
        // the caller but the memo refuses admission rather than rooting
        // an entry on a decl identity whose artifact is gone.
        //
        // R6 non-file fork: when the base names a real file but the
        // live indexed view yields no `IndexedReady`, the key is stale
        // (file dropped or never loaded) — refuse admission so the
        // next caller cold-recomputes against the current state.
        if !is_non_file_base && live_indexed.is_none() {
            let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(self.opaque(QueryError::Miss)),
                empty_signature(),
            ));
            out.cache_suppress = true;
            return InstantiateStart::Done(Box::new(out));
        }
        self.begin_prepared_instantiation(
            base,
            args,
            &builtin_identity,
            is_non_file_base,
            scope,
            context,
            suspend,
        )
    }

    /// Build the builtin answer without retaining declaration-building locals.
    #[inline(never)]
    fn build_instantiated_builtin_utility(
        &self,
        base: SemanticNodeId,
        decl_name: &OwnedStr,
        args: &Arc<[SemanticNodeId]>,
        context: crate::semantic_query::ProjectionReductionContext,
        builtin_utility: Option<BuiltinUtility>,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        // A built-in utility instantiation (`Pick<X, K>`, `Omit<X, K>`,
        // `ReturnType<F>`, …) inspects its argument nodes to form the
        // result — `build_builtin_utility` reads `X`'s Object surface,
        // enumerates `K`'s key space, walks `F`'s call signature, etc.
        // The result therefore transitively depends on the file
        // content each file-derived argument was lowered from. Derive
        // the self-roots from the `args` node set (the same
        // file-derived-input rooting `KeyOf` / `MappedType` /
        // `IndexedAccess` use): each `NodeScopeId::File`-scoped arg
        // contributes one `(canonical, observed_hash)` self-root so an
        // edit to that file rejects this utility memo entry on the
        // strict warm-read validator. Structural args (`Global`-scoped
        // primitives, literal-union key sets) contribute nothing.
        let observed_self_roots = self.observed_self_roots_from_nodes(args.iter().copied());
        // Builtin-utility results are NEVER macro-T own-body (by
        // design): `defineProps<Omit<Vendor, K>>()` surfaces
        // members that came from `Vendor` via the utility, none of
        // which the author wrote in the macro T body. Downgrade the
        // provenance to structural so the utility's produced members
        // report `declared_in_macro_type_arg = false`. (A carrier
        // `CarrierProps extends Omit<Vendor, K>` is the SEPARATE
        // direct-decl case: CarrierProps's own body is stamped below
        // and only its `extends`-reached members go through this
        // utility path as structural.)
        // `builtin_utility` is the identity the gate proved; builders never
        // resolve a spelling themselves.
        let (utility_result, utility_fence, utility_is_partial, approximation) = self
            .build_builtin_utility(
                base,
                decl_name.as_ref(),
                builtin_utility,
                args,
                context.into_structural_provenance(),
            );
        let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
            (utility_result, utility_fence).into();
        // Two-signal fold: a mapper-utility surface whose
        // nested KeyOf/MappedType subquery was genuinely incomplete
        // (budget / recursion / walker-fatal) surfaces here as a
        // complete-looking `Value` shell — carry its partiality
        // through the published value so the component-meta + shape /
        // materialize warm gates refuse it. Benign non-cacheability of
        // the nested read does NOT taint this (it is `cache_suppress`
        // on the inner memo only).
        output.fold_partial(utility_is_partial);
        output.approximation = approximation;
        output.with_observed_self_roots(observed_self_roots)
    }

    /// Keep declaration lookup, binding and its build frame off the builtin
    /// utility path's recursive stack. In debug builds, the unused locals of
    /// this path otherwise enlarge every nested builtin instantiation frame.
    #[inline(never)]
    fn begin_prepared_instantiation(
        &self,
        base: SemanticNodeId,
        args: &Arc<[SemanticNodeId]>,
        identity: &crate::semantic_query::DeclIdentity,
        is_non_file_base: bool,
        scope: NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
        suspend: bool,
    ) -> InstantiateStart {
        let decl_canonical = &identity.canonical_id;
        let decl_owner = identity.owner;
        let decl_name = &identity.decl_name;
        let decl_whole_hash = identity.whole_hash;
        let body_mode = context.mode;

        let adapter = SessionDispatchHost::from_facade(self);
        let ri = ResolvedRootIdentity::new_in_owner(
            decl_canonical.as_ref(),
            decl_owner,
            decl_name.as_ref(),
        );
        let (prepared, authored_resolution_debt) = match adapter
            .resolve_prepared_type_decl(base, &ri)
        {
            PreparedTypeDeclResolution::Complete(declaration) => (declaration, None),
            PreparedTypeDeclResolution::AuthoredPartial {
                root_identity,
                declaration,
                failure,
            } => {
                verter_debug_assert_eq!(root_identity, declaration.root_identity);
                let verter_session_query::inputs::prepared::PreparationFailure::MissingExternalOwner {
                    ..
                } = failure
                else {
                    unreachable!("AuthoredPartial is reserved for unresolved external owners")
                };
                let debt =
                    crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame::new(
                        &root_identity,
                    );
                (declaration, Some(debt))
            }
            PreparedTypeDeclResolution::Missing => {
                // A name only the value space declares, read where a class
                // instance is composed (a class expression's `extends`):
                // the base instance of that value's constructor, by the
                // same first-construct-signature rule a class declaration's
                // heritage follows.
                let value_instance = (!is_non_file_base
                    && self.heritage_names_value_only(decl_canonical, decl_owner, decl_name))
                .then(|| {
                    self.class_value_base(decl_canonical, decl_owner, decl_name, args, context)
                })
                .flatten()
                .and_then(|value_base| value_base.instance);
                let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(
                        value_instance.unwrap_or_else(|| self.opaque(QueryError::Miss)),
                    ),
                    empty_signature(),
                ));
                out.cache_suppress = true;
                return InstantiateStart::Done(Box::new(out));
            }
            PreparedTypeDeclResolution::Failed { failure, .. } => {
                crate::fact_tracing::note_non_cacheable_read_fan_out(
                    verter_session_query::facts::reuse::NonCacheableReadReason::PreparationFailure,
                );
                tracing::error!(
                    ?failure,
                    canonical_id = decl_canonical.as_ref(),
                    ?decl_owner,
                    symbol = decl_name.as_ref(),
                    "prepared type declaration failed without an authored partial carrier"
                );
                let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(self.opaque(QueryError::Miss)),
                    empty_signature(),
                ));
                out.cache_suppress = true;
                return InstantiateStart::Done(Box::new(out));
            }
        };

        // 3b. A type alias whose authored body is the `intrinsic` keyword is
        // the compiler-provided type its name selects (the checker's
        // `intrinsicTypeKinds`), whether the lib declares it or the user does:
        // a local `type NoInfer<T> = intrinsic` is `NoInfer`. A name that
        // selects no implemented intrinsic is that unsupported intrinsic, never
        // the body it spells: the keyword is not a reference to evaluate.
        if prepared.body_facts.classification == verter_type_expr::facts::TypeBodyClass::Intrinsic {
            let mut output = match adapter.resolve_intrinsic_alias(decl_name.as_ref()) {
                Some(utility) => self.build_instantiated_builtin_utility(
                    base,
                    decl_name,
                    args,
                    context,
                    Some(utility),
                ),
                None => (
                    QueryResult::Value(self.opaque(QueryError::UnsupportedIntrinsic {
                        name: verter_type_expr::OwnedStr::from(decl_name.as_ref()),
                    })),
                    self.project_generation_signature(),
                )
                    .into(),
            };
            // The answer exists because the declaring file spells the alias
            // `intrinsic`: root it on that file's observed version, as the
            // ordinary declaration path does, so an edit to the alias misses
            // the warm read. A non-file base has no version.
            if !is_non_file_base {
                output.dep_signature = output
                    .dep_signature
                    .iter()
                    .cloned()
                    .chain(
                        self.dep_signature_for(decl_canonical, decl_whole_hash)
                            .iter()
                            .cloned(),
                    )
                    .collect();
                output =
                    output.with_observed_self_roots([(decl_canonical.clone(), decl_whole_hash)]);
            }
            return InstantiateStart::Done(Box::new(output));
        }

        // 4. Bind type parameters to args (positional). When a
        // parameter has no explicit arg but carries a default
        // expression, lower the default in the decl's scope and bind
        // it — mirrors the solver's `resolve_type_parameters_in_body`
        // behaviour at solve.rs:2580.
        // Instrumentation: callsite attribution for
        // `prepared_decl_bundle_warm` reads from `build_instantiate`.
        verter_audit::observe!(C::Observe => on self.observation.observer.as_deref() => |obs| {
            obs.record_event(verter_audit::AuditEvent::PreparedDeclBundleCallsiteBuildInstantiate);
        });
        let scope_payload = self
            .ctx
            .prepared_decl_bundle(decl_canonical.as_ref())
            .map(|bundle| {
                self.declaration_scope_payload(
                    &bundle,
                    decl_canonical.as_ref(),
                    decl_owner,
                    decl_name.as_ref(),
                )
            });
        // R15/F11 — capture the scope-shadowing context
        // once for the whole `build_instantiate` body so every
        // recursive lowering observes the same shadow set.
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let mut substitutions: Vec<(Arc<str>, SemanticNodeId)> = Vec::new();
        let binding_scope = DeclarationBindingScope {
            scope: &scope,
            scope_payload: scope_payload.as_ref(),
            shadowing: &shadowing,
            authored_resolution_debt: authored_resolution_debt.as_ref(),
            augmentation: None,
        };
        let unbound_parameter = |index: usize, param: &verter_type_expr::facts::NarrowTypeParam| {
            // Skeleton mode preserves open generics: an unbound
            // parameter binds a TypeParam shell so body lowering
            // produces TypeParam graph nodes (instead of resolving
            // T-refs to Opaque(Miss)). The relation engine treats
            // TypeParam as deferred → Conditional branches stay live
            // → the cycle gate's ref collector walks both → recursive
            // refs through nested mapped/template-literal/conditional
            // bodies become visible to the cycle gate. Every other mode
            // leaves it unbound, so `Opaque(Miss)` propagates through
            // the body; callers that genuinely need open-generic access
            // must explicitly request Skeleton mode.
            (body_mode == crate::semantic_query::ProjectionMode::Skeleton).then(|| {
                let decl_identity = crate::semantic_query::DeclIdentity {
                    canonical_id: decl_canonical.clone(),
                    owner: decl_owner,
                    whole_hash: decl_whole_hash,
                    decl_name: decl_name.clone(),
                };
                self.graph().intern_node_with_scope(
                    SemanticNodeData::TypeParam {
                        decl: decl_identity,
                        param_index: index as u16,
                        constraint: None,
                        default: None,
                        display_name: OwnedStr::from(param.name.as_str()),
                    },
                    scope.clone(),
                )
            })
        };
        let (env, bindings) = self.bind_declared_type_arguments(
            &prepared,
            args,
            &binding_scope,
            &mut substitutions,
            context,
            unbound_parameter,
        );

        // Keep every supplied argument: a merged peer may introduce additional
        // defaulted parameters beyond this declaration's clause. Only append
        // defaults for positions the application did not supply.
        let effective_args: Arc<[SemanticNodeId]> = args
            .iter()
            .copied()
            .chain(
                bindings
                    .into_iter()
                    .skip(args.len())
                    .take_while(Option::is_some)
                    .flatten(),
            )
            .collect();

        // Every declaring file names the same global interface. Assemble
        // it through its first declaration's shared instantiation, so a
        // demand from another base does not lower all contributors again.
        if authored_resolution_debt.is_none()
            && self.declares_global_interface(decl_canonical, decl_owner, decl_name, prepared.kind)
        {
            if let Some(first) = self.first_global_declaration(decl_canonical, decl_name) {
                if first.canonical_id != *decl_canonical
                    && self
                        .ctx
                        .prepared_type_decl(&first.canonical_id, first.owner, &first.symbol_name)
                        .ok()
                        .flatten()
                        .is_some_and(|decl| {
                            decl.kind == verter_session_query::declarations::TypeDeclKind::Interface
                        })
                {
                    let read = self.execute_read(SemanticQueryKey::Instantiate(
                        crate::semantic_query::InstantiateKey::new(
                            self.type_slot_for(
                                first.canonical_id.clone(),
                                first.owner,
                                first.symbol_name.clone(),
                            ),
                            Arc::clone(&effective_args),
                            self.instantiate_context_for(&first.canonical_id, context),
                        ),
                    ));
                    let completeness = read.fact_status.completeness();
                    let approximation = read.fact_status.interpretation();
                    let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                        read.value,
                        self.dep_signature_for(decl_canonical, decl_whole_hash),
                    ))
                    .with_observed_self_roots([(decl_canonical.clone(), decl_whole_hash)]);
                    out.merge_completeness(completeness);
                    out.approximation = approximation;
                    out.walker_diagnostics = read
                        .walker_diagnostics
                        .iter()
                        .map(crate::project_semantic_dispatch::walk::ShallowDiagnostic::clone)
                        .collect::<Vec<_>>();
                    out.cache_suppress = read.cache_suppress;
                    return InstantiateStart::Done(Box::new(out));
                }
            }
        }

        // 5. Shallow-lower the body. Collects substitution facts for
        // origin-edge emission. `name_resolution` is the prepared
        // decl's map from bare names used inside its body to the
        // resolved declaration identities — the walker consults this
        // when it encounters `TypeExpr::Ref { name, args }` so member
        // bodies that reference other declarations produce proper
        // sub-Instantiate shells instead of opaque placeholders.
        //
        // Recursive-ref guard: push `(decl_canonical, decl_name)` over the
        // arguments onto the dispatcher's `instantiate_active` stack before
        // body lowering. A nested reference in a position the checker
        // defers (an object member, an array or tuple element, a signature,
        // an interface's type argument) resolving back to the same
        // declaration — e.g. `type TreeNode = { children: TreeNode[] }` —
        // sees the active entry and emits `Opaque(RecursiveRef)` at the
        // back-edge instead of recursing. When this same instantiation is
        // already active (the memo's same-path claim answers that first,
        // but safely handled), short-circuit to `RecursiveRef` here too;
        // the declaration over other arguments is another instantiation.
        let active_identity: super::InstantiateIdentity =
            (decl_canonical.clone(), decl_owner, decl_name.clone());
        let pushed = self.push_instantiate_active(active_identity.clone(), Arc::clone(args));
        if !pushed {
            let unresolved_owner_debt = authored_resolution_debt
                .as_ref()
                .is_some_and(|debt| debt.finish());
            if unresolved_owner_debt {
                crate::fact_tracing::note_non_cacheable_read_fan_out(
                    verter_session_query::facts::reuse::NonCacheableReadReason::PreparationFailure,
                );
                self.fold_local_partial_completeness(
                    crate::semantic_query::PartialReasonSet::MISSING_DEPENDENCY,
                );
            }
            let mut output: crate::project_semantic_dispatch::walk::QueryBuildOutput<_> = (
                QueryResult::Value(self.opaque(QueryError::RecursiveRef {
                    name: verter_type_expr::OwnedStr::from(decl_name),
                    args: Arc::clone(args).into(),
                })),
                empty_signature(),
            )
                .into();
            output.fold_partial(unresolved_owner_debt);
            output.cache_suppress = unresolved_owner_debt;
            return InstantiateStart::Done(Box::new(output));
        }
        let generic = !prepared.type_parameters.is_empty();
        let mut build = Box::new(InstantiateBuild {
            active_identity,
            decl_canonical: decl_canonical.clone(),
            decl_owner,
            decl_name: decl_name.clone(),
            is_non_file_base,
            decl_whole_hash,
            base,
            args: Arc::clone(args),
            effective_args,
            scope,
            prepared,
            scope_payload,
            shadowing,
            authored_resolution_debt,
            context,
            body_mode,
            env,
            substitutions,
            tail: crate::semantic_query::checker_policy::ConditionalTail::resumed(0),
            tail_arguments: std::iter::once(Arc::clone(args)).collect(),
            tail_current: Arc::clone(args),
            growth: None,
            conditional_body: None,
            generic,
            suspend,
            complete_structure: false,
            enum_body: false,
            body: BodyLowering::Ready(base),
        });
        // Propagate the full `ProjectionReductionContext` through body
        // lowering so a `StructuralTransit` instantiation lowers its body in
        // transit demand: intermediate-hop `keyof T` / `{ [K in S]: V }`
        // operators along the decl body must never reach the
        // publication-edge loops. Surface provenance follows the per-arm
        // rule of the decl-body projection: inline `Object` arms keep the
        // caller's provenance, reference arms (an author intersection's
        // named refs, an interface's `extends` heritage) go structural.
        build.body = self.begin_instantiated_body(&mut build);
        InstantiateStart::Build(build)
    }

    /// [`ExactSteps`] for the computation being built, when its steps so far
    /// are exact: its build frame holds no partial and nothing its memo
    /// would refuse to keep, and the request is live. `None` is no proof —
    /// the caller evaluates on under its budget instead of certifying.
    fn exact_steps(&self) -> Option<ExactSteps> {
        if self.cancellation.is_cancelled() {
            return None;
        }
        let frames = self.build_local_taint.borrow();
        let frame = frames.last()?;
        frame_is_exact(frame).then_some(ExactSteps { _proof: () })
    }

    /// [`ExactSteps`] for every step since the instantiation `claimed` began
    /// on this path: the frame producing it is on this thread's build stack
    /// ([`super::BuildLocalTaint::produces`]) and neither it nor any frame
    /// built on top of it holds a partial or a result its memo would not
    /// keep, and the request is live. `None` — the producer's frame is not
    /// on the stack (a suspended continuation's), or a step read a partial —
    /// is no proof. The producer is the frame building exactly `claimed` at
    /// the current checking site, the claim's own producer.
    fn exact_steps_since(&self, claimed: &SemanticQueryKey) -> Option<ExactSteps> {
        if self.cancellation.is_cancelled() {
            return None;
        }
        exact_since_producer(
            &self.build_local_taint.borrow(),
            claimed,
            self.checking_site.get(),
        )
        .then_some(ExactSteps { _proof: () })
    }

    /// [`UniformGrowth`] for the tail run of `build` stepping from its
    /// current arguments to `next`: exactly one argument changed, the
    /// declaration grows that parameter uniformly ([`GrowthShape`]), the
    /// current argument holds no type parameter (so neither does any later
    /// one, and no later step defers), and `next`'s argument IS the wrapper
    /// over the current one — this step took the recursive branch. Every
    /// later step is then that branch again over a wrapped argument, with
    /// no end. `None` is no proof.
    fn uniform_growth(
        &self,
        build: &mut InstantiateBuild,
        next: &[SemanticNodeId],
    ) -> Option<UniformGrowth> {
        let current = Arc::clone(&build.tail_current);
        if current.len() != next.len() {
            return None;
        }
        let mut changed = (0..next.len()).filter(|&position| current[position] != next[position]);
        let index = changed.next()?;
        if changed.next().is_some() {
            return None;
        }
        let shape = self.growth_shape(build)?;
        if shape.index != index || !self.type_params_within(&[current[index]]).is_empty() {
            return None;
        }
        (self.substitute_semantic_type_param(shape.wrapper, shape.parameter, current[index])
            == next[index])
            .then_some(UniformGrowth { _proof: () })
    }

    /// The declaration's [`GrowthShape`], read once per build.
    fn growth_shape(&self, build: &mut InstantiateBuild) -> Option<GrowthShape> {
        if let Some(known) = build.growth {
            return known;
        }
        let shape = self.read_growth_shape(build);
        build.growth = Some(shape);
        shape
    }

    /// The uniform growth `build`'s declaration declares, when its body is
    /// a conditional `P extends E ? X : Y` over one of its own type
    /// parameters `P`, written bare, where:
    ///
    /// - `E` is closed: no type parameter, no `infer`;
    /// - exactly one branch applies the declaration again, passing every
    ///   other parameter through unchanged and `P` wrapped in one structural
    ///   constructor — a tuple without rest elements, an array or an object
    ///   type, never a union, a spread or `never` whatever it holds — that
    ///   mentions no other type variable;
    /// - the checker's own generic test selects that branch for EVERY
    ///   instantiation of the wrapper: definitely true when the wrapper over
    ///   the parameter without its constraint relates to `E`
    ///   (`getRestrictiveInstantiation`), definitely false when the wrapper
    ///   over the wildcard does not (`getPermissiveInstantiation`).
    ///
    /// The decision reads the declaration and `E` only, never the run's
    /// arguments, and its reads are this build's dependencies. Anything
    /// else — a check that is not the bare parameter (`Acc["length"]`), an
    /// open `E`, a branch the test leaves undecided — is no shape.
    fn read_growth_shape(&self, build: &InstantiateBuild) -> Option<GrowthShape> {
        let identity = crate::semantic_query::DeclIdentity {
            canonical_id: build.decl_canonical.clone(),
            owner: build.decl_owner,
            whole_hash: build.decl_whole_hash,
            decl_name: build.decl_name.clone(),
        };
        let body = self.declared_alias_body(&identity)??;
        let graph = self.graph();
        let (check, extends, true_branch, false_branch) = match graph.node_data(body).as_deref() {
            Some(SemanticNodeData::Conditional {
                check,
                extends,
                true_branch_ref,
                false_branch_ref,
                pending: None,
                ..
            }) => (*check, *extends, *true_branch_ref, *false_branch_ref),
            _ => return None,
        };
        let own_parameter = |node: SemanticNodeId| match graph.node_data(node).as_deref() {
            Some(SemanticNodeData::TypeParam {
                decl, param_index, ..
            }) if decl.canonical_id == build.decl_canonical
                && decl.owner == build.decl_owner
                && decl.decl_name == build.decl_name =>
            {
                Some(usize::from(*param_index))
            }
            _ => None,
        };
        let index = own_parameter(check)?;
        let applies = |branch: SemanticNodeId| {
            self.conditional_tail_arguments(
                branch,
                &build.decl_canonical,
                build.decl_owner,
                &build.decl_name,
                || true,
            )
        };
        let (recurs_when_true, arguments) = match (applies(true_branch), applies(false_branch)) {
            (Some(arguments), None) => (true, arguments),
            (None, Some(arguments)) => (false, arguments),
            _ => return None,
        };
        let passes_through = arguments.iter().enumerate().all(|(position, argument)| {
            position == index || own_parameter(*argument) == Some(position)
        });
        let wrapper = *arguments.get(index)?;
        if !passes_through
            || !self.is_growth_constructor(wrapper)
            || self.type_params_within(&[wrapper]) != [check]
            || !self.type_params_within(&[extends]).is_empty()
            || self.declares_or_reads_infer(wrapper)
            || self.declares_or_reads_infer(extends)
        {
            return None;
        }
        let decided = if recurs_when_true {
            matches!(
                self.restrictive_relation(wrapper, extends, &[check]),
                super::dispatch_txn::RelationStep::Assignable { .. }
            )
        } else {
            matches!(
                self.permissive_relation(wrapper, extends, &[check]),
                super::dispatch_txn::RelationStep::NotAssignable
            )
        };
        decided.then_some(GrowthShape {
            index,
            parameter: check,
            wrapper,
        })
    }

    /// Whether `node` is a structural constructor whose instantiation is
    /// never a union, a spread or `never`, whatever it holds: a tuple
    /// without rest elements, an array or an object type.
    fn is_growth_constructor(&self, node: SemanticNodeId) -> bool {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Tuple { elements, .. }) => {
                elements.iter().all(|element| !element.rest)
            }
            Some(SemanticNodeData::Array { .. } | SemanticNodeData::Object(_)) => true,
            _ => false,
        }
    }

    /// Whether `node` declares or reads an `infer` type variable anywhere
    /// below it.
    fn declares_or_reads_infer(&self, node: SemanticNodeId) -> bool {
        let graph = self.graph();
        let mut seen = rustc_hash::FxHashSet::default();
        let mut stack = vec![node];
        while let Some(node) = stack.pop() {
            if !seen.insert(node) {
                continue;
            }
            let Some(data) = graph.node_data(node) else {
                continue;
            };
            if matches!(
                data.as_ref(),
                SemanticNodeData::Infer { .. } | SemanticNodeData::InferRef { .. }
            ) {
                return true;
            }
            let _ = data.for_each_child(|child| stack.push(child));
        }
        false
    }

    /// Carry an instantiation's build on as far as it can go. `delivery` is
    /// the node of the instantiation its body projection last stopped at,
    /// when it stopped at one. An inline build always finishes; a
    /// suspending build stops at each instantiation its body reaches.
    pub(super) fn drain_instantiate(
        &self,
        build: &mut InstantiateBuild,
        mut delivery: Option<
            crate::project_semantic_dispatch::locator_view_worklist::ProjectionDelivery,
        >,
    ) -> InstantiatePoll {
        verter_audit::attribute_scope!(Instantiate);
        loop {
            let lowered = match self.drain_instantiated_body(build, delivery.take()) {
                BodyPoll::Need(key) => return InstantiatePoll::Need(key),
                BodyPoll::Done(node, complete_structure) => {
                    build.complete_structure = complete_structure;
                    node
                }
            };
            // Member-index overlay (carries the caller's provenance):
            // `member_index` holds the declaration's OWN-body direct members.
            // It APPENDS own members not yet on the surface (the heritage /
            // member-index split) and RE-STAMPS any surface member that
            // matches an own-body index entry. With per-arm body lowering the
            // own `Object` arm members already carry the correct bit, so the
            // re-stamp is a no-op for those; the overlay remains the authority
            // for own members appended from `member_index` and is the safety
            // net for surfaces where the own members were lowered structurally.
            let mut result = self.backfill_member_index_surface(
                lowered,
                &build.prepared,
                &build.env,
                &build.scope,
                build.scope_payload.as_ref(),
                &build.shadowing,
                &mut build.substitutions,
                build.context,
                build.authored_resolution_debt.as_ref(),
            );

            // The checker's tail loop (`getConditionalType`): a generic body
            // whose selected branch is this declaration applied to OTHER
            // arguments is the next step of one tail run, evaluated here in
            // place of a nested instantiation, and counted by the checker
            // compatibility policy. The run fails with the checker's TS2589 at
            // Verter's tail budget, far past the checker's tail limit, or at
            // once, as a certified divergence, when the arguments come round
            // again through exact steps. Each step is charged to the
            // connected-work ledger; a trip leaves the step's back-edge as a
            // typed partial.
            let next = build
                .generic
                .then(|| {
                    let canonical = build.decl_canonical.clone();
                    let owner = build.decl_owner;
                    let name = build.decl_name.clone();
                    self.conditional_tail_arguments(result, &canonical, owner, &name, || {
                        self.declares_conditional_body(build) == Some(true)
                    })
                })
                .flatten();
            use crate::semantic_query::{checker_policy, CheckerDiagnosticOperation};
            if next.is_some() && self.declares_conditional_body(build) == Some(false) {
                // The body applies the declaration itself with no conditional
                // type of its own deciding: the alias's declared type
                // requires itself — the checker's TS2456, a checker error
                // (`any`) and a complete answer, never a step of a tail run.
                let alias = self.graph().intern_node(SemanticNodeData::DeclRef {
                    identity: crate::semantic_query::DeclIdentity {
                        canonical_id: build.decl_canonical.clone(),
                        owner: build.decl_owner,
                        whole_hash: build.decl_whole_hash,
                        decl_name: build.decl_name.clone(),
                    },
                });
                result = checker_policy::circular_type_alias_recovery(self.graph(), alias);
            } else if let Some(next) = next {
                // A run that comes back to arguments it already took — the
                // same declaration, context and phase, this build's — is in
                // the state it was in then, and when each step was a complete
                // function of that state it repeats forever: a certified
                // divergence. So is a run that wraps one argument in the
                // same constructor at every step when the conditional takes
                // its recursive branch for whatever the constructor holds
                // (`Self::uniform_growth`). Arguments that came round, or
                // grew, after a step read a partial prove nothing, and the
                // run goes on under its budget.
                let operation = CheckerDiagnosticOperation::ConditionalTail;
                let certificate = if build.tail_arguments.contains(&next) {
                    self.exact_steps().map(|exact| {
                        checker_policy::CertifiedDivergence::exact_recurrence(operation, exact)
                    })
                } else {
                    self.uniform_growth(build, &next).and_then(|growth| {
                        self.exact_steps().map(|exact| {
                            checker_policy::CertifiedDivergence::uniform_growth(
                                operation, exact, growth,
                            )
                        })
                    })
                };
                if let Some(certificate) = certificate {
                    result = checker_policy::divergence_recovery(self.graph(), certificate, None);
                } else if let Err(refusal) = self
                    .connected_demand
                    .tail_step(&mut build.tail, CheckerDiagnosticOperation::ConditionalTail)
                {
                    // Verter's tail budget stopped the run, not a proof:
                    // whether it is reached depends on the budget, so
                    // neither the recovery nor anything built from it is
                    // kept in the memo.
                    self.fold_into_top_build_local_taint(false, true);
                    result = self.recover_at_operation_budget(refusal, None);
                } else if let Err(reasons) = self.charge_connected_work() {
                    self.fold_local_partial_completeness(reasons);
                } else {
                    build.tail_arguments.insert(Arc::clone(&next));
                    build.tail_current = Arc::clone(&next);
                    build.substitutions.clear();
                    let (next_env, _) = self.bind_instantiate_arguments(build, &next);
                    build.env = next_env;
                    build.body = self.begin_instantiated_body(build);
                    continue;
                }
            }
            return InstantiatePoll::Done(Box::new(self.finish_instantiate(build, result)));
        }
    }

    /// Bind `args` to the declaration's type parameters the way the build's
    /// first binding did: an unbound parameter in `Skeleton` mode binds a
    /// `TypeParam` shell so the body keeps its open generics.
    fn bind_instantiate_arguments(
        &self,
        build: &mut InstantiateBuild,
        args: &[SemanticNodeId],
    ) -> (
        FxHashMap<String, SemanticNodeId>,
        Vec<Option<SemanticNodeId>>,
    ) {
        let binding_scope = DeclarationBindingScope {
            scope: &build.scope,
            scope_payload: build.scope_payload.as_ref(),
            shadowing: &build.shadowing,
            authored_resolution_debt: build.authored_resolution_debt.as_ref(),
            augmentation: None,
        };
        let body_mode = build.body_mode;
        let decl_identity = crate::semantic_query::DeclIdentity {
            canonical_id: build.decl_canonical.clone(),
            owner: build.decl_owner,
            whole_hash: build.decl_whole_hash,
            decl_name: build.decl_name.clone(),
        };
        let scope = build.scope.clone();
        let unbound_parameter = |index: usize, param: &verter_type_expr::facts::NarrowTypeParam| {
            (body_mode == crate::semantic_query::ProjectionMode::Skeleton).then(|| {
                self.graph().intern_node_with_scope(
                    SemanticNodeData::TypeParam {
                        decl: decl_identity.clone(),
                        param_index: index as u16,
                        constraint: None,
                        default: None,
                        display_name: OwnedStr::from(param.name.as_str()),
                    },
                    scope.clone(),
                )
            })
        };
        self.bind_declared_type_arguments(
            &build.prepared,
            args,
            &binding_scope,
            &mut build.substitutions,
            build.context,
            unbound_parameter,
        )
    }

    /// Begin lowering the declaration's body under the build's current
    /// bindings: an enum's member union at once, else the projection of its
    /// substituted locator shape.
    fn begin_instantiated_body(&self, build: &mut InstantiateBuild) -> BodyLowering {
        let prepared = build.prepared.clone();
        // An enum's type is the union of its members' literal types, read
        // off the member inventory its value declaration carries.
        if let Some(enumeration) = self.enum_declared_at(
            prepared.root_identity.canonical_id.as_ref(),
            prepared.root_identity.owner,
            prepared.root_identity.symbol_name.as_ref(),
        ) {
            build.enum_body = true;
            return BodyLowering::Ready(self.enum_type(&enumeration));
        }
        // The declaration's OWN decl-body locator (whole body).
        let canonical = prepared.root_identity.canonical_id.clone();
        let locator = verter_type_expr::locators::AuthoredBodyLocator::DeclBody(
            verter_type_expr::locators::TypeBodySlot {
                anchor: verter_type_expr::locators::AuthoredAnchor {
                    canonical_id: canonical,
                    owner: prepared.root_identity.owner,
                    symbol: prepared.root_identity.symbol_name.clone(),
                    space: verter_type_expr::locators::LocatorSymbolSpace::Type,
                },
                path: verter_type_expr::OwnedSlice::default(),
            },
        );
        let seam = if build.suspend {
            super::locator_view_worklist::ProjectionSeam::suspending()
        } else {
            super::locator_view_worklist::ProjectionSeam::inline()
        };
        self.begin_located_body_lowering(
            locator,
            prepared.kind,
            &prepared.type_parameters,
            &build.env,
            &build.scope,
            &mut build.substitutions,
            build.context,
            &prepared.vue_ignored_heritage,
            seam,
        )
    }

    /// Carry the build's body lowering on as far as it can go.
    fn drain_instantiated_body(
        &self,
        build: &mut InstantiateBuild,
        delivery: Option<
            crate::project_semantic_dispatch::locator_view_worklist::ProjectionDelivery,
        >,
    ) -> BodyPoll {
        let InstantiateBuild {
            prepared,
            env,
            scope,
            scope_payload,
            shadowing,
            authored_resolution_debt,
            substitutions,
            body,
            ..
        } = build;
        self.drain_located_body_lowering(
            body,
            &crate::project_semantic_dispatch::locator_view::LocatorViewInputs {
                env,
                scope,
                name_resolution: &prepared.name_resolution,
                scope_payload: scope_payload.as_ref(),
                shadowing,
                authored_resolution_debt: authored_resolution_debt.as_ref(),
                self_value: None,
            },
            substitutions,
            delivery,
        )
    }

    /// Finish an instantiation whose body lowered to `result`: merge its
    /// cross-file augmentations, leave the active instantiation, record its
    /// origin edges and root its result on everything it read.
    fn finish_instantiate(
        &self,
        build: &mut InstantiateBuild,
        mut result: SemanticNodeId,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let substitutions = std::mem::take(&mut build.substitutions);
        let authored_resolution_debt = build.authored_resolution_debt.take();
        let decl_canonical = &build.decl_canonical;
        let decl_name = &build.decl_name;
        let decl_owner = build.decl_owner;
        let decl_whole_hash = build.decl_whole_hash;
        let is_non_file_base = build.is_non_file_base;
        let args = &build.args;
        let context = build.context;
        let scope = &build.scope;
        let prepared = &build.prepared;
        let base = build.base;
        // Cross-file declaration augmentation (`declare module "X"` /
        // `declare global` interface merging from sibling files). Fold every
        // augmenter file's contributed body into the base body through the ONE
        // `MergedDecl` peer-merge carrier — there is no second merge engine.
        // Performed while `(decl_canonical, decl_name)` is still on the
        // instantiate-active stack so a self-referential augmenter body
        // terminates at the recursive-ref back-edge instead of recursing.
        let mut augmenter_contributor_roots: Vec<AugmentationContributorRoot> = Vec::new();
        let mut augmentation_source_env_unobservable = false;
        // An enum's member union already holds every block's members, an
        // augmenting block's included: it is no type body to merge.
        if !is_non_file_base && !build.enum_body {
            if let Some(stitch) =
                self.stitch_module_augmentations(decl_canonical, decl_name, result, scope, context)
            {
                result = stitch.merged;
                augmenter_contributor_roots = stitch.contributor_roots;
                augmentation_source_env_unobservable = stitch.source_env_unobservable;
            }
            // A GLOBAL interface's other declarations — every other
            // module's `declare global` and script's file-scope interface —
            // merge in through the same peer-merge carrier, whichever of
            // them the reference named.
            if self.declares_global_interface(
                decl_canonical.as_ref(),
                decl_owner,
                decl_name.as_ref(),
                prepared.kind,
            ) {
                if let Some(stitch) = self.stitch_global_declarations(
                    decl_canonical,
                    decl_name,
                    &build.effective_args,
                    result,
                    scope,
                    context,
                ) {
                    result = stitch.merged;
                    augmenter_contributor_roots.extend(stitch.contributor_roots);
                    augmentation_source_env_unobservable |= stitch.source_env_unobservable;
                }
            }
        }
        self.pop_instantiate_active();

        // 6. Emit origin edges + build dep signature.
        self.graph().record_instantiate();
        let fence = self.dep_signature_for(decl_canonical, decl_whole_hash);

        // Instantiate edge: result <- [base, args...].
        crate::semantic_query_memo::record_origin_edge!(
            self.graph(),
            result,
            OriginEdgeKind::Instantiate,
            std::iter::once(base).chain(args.iter().copied()).collect(),
            OriginMeta::None,
            fence.clone(),
        );

        // SubstituteTypeParam edges on the shell result: one per visited
        // substituted occurrence — edges emitted at substitution
        // position; at shell level this aggregates on the result node
        // per lazy block.
        for (param_name, arg_id) in substitutions {
            crate::semantic_query_memo::record_origin_edge!(
                self.graph(),
                result,
                OriginEdgeKind::SubstituteTypeParam,
                Arc::from(vec![arg_id].into_boxed_slice()),
                OriginMeta::SubstitutedParam(verter_type_expr::OwnedStr::from(param_name)),
                fence.clone(),
            );
        }

        // Self-version rooting: the instantiated shell's body and member
        // structure were lowered from the prepared decl declared in
        // `decl_canonical` at the observed `decl_whole_hash` (re-sourced
        // from the live indexed view above) AND from the generic
        // `args` substituted into the decl body. The result therefore
        // transitively depends on the file content each file-derived
        // argument was lowered from — the same file-derived-input rooting
        // the built-in utility path applies. Root the memo entry on the
        // declaring file's observed content version AND on each
        // `NodeScopeId::File`-scoped arg's `(canonical, observed_hash)`
        // self-root so a content edit to the declaring file OR to any
        // argument's originating file misses the warm read. Structural
        // args (`Global`-scoped primitives) contribute nothing.
        //
        // R6 non-file fork: when the base names no file (the global /
        // structural sentinel `canonical_id == ""`, the built-in
        // utility carrier `"__builtin__"`, or the synthetic test
        // sentinel `"<synthetic>"`), there is no `FileWholeHash` to
        // root on the file — `decl_whole_hash` is the default sentinel
        // `0`. Recording `(non_file_canonical, 0)` as a self-root
        // would either be a no-op (the sentinel canonical is never
        // tracked by the live view, so strict validation would
        // optimistically accept) or — worse — would pretend the
        // builtin/global has a content version. Skip the file-side
        // self-root in those cases and rely entirely on the args
        // self-roots (the same rule the builtin-utility path applies).
        let mut observed_self_roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> =
            if is_non_file_base {
                Vec::new()
            } else {
                vec![(decl_canonical.clone(), decl_whole_hash)]
            };
        for arg_root in self.observed_self_roots_from_nodes(args.iter().copied()) {
            if !observed_self_roots
                .iter()
                .any(|(c, h)| *c == arg_root.0 && *h == arg_root.1)
            {
                observed_self_roots.push(arg_root);
            }
        }
        // Cross-file augmentation self-roots: each contributor root's
        // `(canonical, whole_hash)` (`self_root_canonicals = {base} ∪
        // {augmenters}`), so a content edit to ANY augmenter misses the warm
        // read. Every root entering here already carried its artifact key
        // through the fold, so its `FileSourceEnv` observation is on this
        // build's read-set by construction.
        let mut seen_roots: rustc_hash::FxHashSet<_> =
            observed_self_roots.iter().cloned().collect();
        for aug_root in augmenter_contributor_roots {
            let root = (aug_root.canonical, aug_root.whole_hash);
            if seen_roots.insert(root.clone()) {
                observed_self_roots.push(root);
            }
        }
        let unresolved_owner_debt = authored_resolution_debt
            .as_ref()
            .is_some_and(|debt| debt.finish());
        if unresolved_owner_debt {
            crate::fact_tracing::note_non_cacheable_read_fan_out(
                verter_session_query::facts::reuse::NonCacheableReadReason::PreparationFailure,
            );
            self.fold_local_partial_completeness(
                crate::semantic_query::PartialReasonSet::MISSING_DEPENDENCY,
            );
        }
        let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(result),
            fence,
        ))
        .with_observed_self_roots(observed_self_roots);
        // A contributor whose source-env identity could not be observed
        // coherently routes the parent result through no-warm-admission
        // semantics: the value is served, never published warm.
        if augmentation_source_env_unobservable {
            output.cache_suppress = true;
            // Fan the generalized non-cacheability rail onto EVERY active tracer.
            // This is the SINGLE consumer of the relative stitch's
            // `source_env_unobservable`, so firing here covers every unobservable
            // source (an unservable / unhealable augmenter, a LeaseMiss
            // contributor). The build-local `cache_suppress` above refuses only
            // THIS build's inner memo; without this fan-out the enclosing
            // component-meta tracer would launder the under-merged augmentation
            // into its warm cache (the read-side fact rail cannot reject it — the
            // facts validate live while a contributor's source-env is
            // unobservable). Same rail as the external augmentation collector
            // (`collect_augmentation_contributions`).
            crate::fact_tracing::note_non_cacheable_read_fan_out(
                verter_session_query::facts::reuse::NonCacheableReadReason::UnobservableSource,
            );
        }
        if unresolved_owner_debt {
            output.mark_partial();
            output.cache_suppress = true;
        }
        if build.complete_structure {
            output = output.with_positional_guarantee();
        }
        output
    }

    /// Cross-file declaration-augmentation stitch (`declare module "./local"`
    /// or `declare module "<package>"` interface merging from other files).
    ///
    /// Given a base declaration `(decl_canonical, decl_name)` and its
    /// already-lowered base body `base_result`, this finds every augmenter file
    /// whose `declare module "<specifier>"` block resolves to `decl_canonical` and
    /// augments `decl_name`, lowers each augmenter's RETAINED inner body in the
    /// augmenter's own file context, and folds all contributions into a single
    /// [`SemanticNodeData::MergedDecl`] peer-merge carrier — the ONE
    /// declaration-merge path (no second merge engine; no source slicing —
    /// bodies come from the typed `augmentation_scopes` inventory).
    ///
    /// Returns `None` when there are no contributing augmenters (the caller
    /// keeps `base_result` unchanged). On a hit it returns the merged node and
    /// the per-augmenter `FileWholeHash` self-roots, and observes the
    /// `ModuleAugmentationIndexShape` (augmenter-set) fact plus each augmenter's
    /// `FileWholeHash` onto the active fact tracer so the cached value
    /// invalidates on an augmenter add/remove OR an augmenter content edit.
    /// This is the production augmentation-stitch fact rail.
    fn stitch_module_augmentations(
        &self,
        decl_canonical: &verter_type_expr::OwnedStr,
        decl_name: &verter_type_expr::OwnedStr,
        base_result: SemanticNodeId,
        base_scope: &NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<AugmentationStitch> {
        use verter_session_query::resolution::AugmentationTargetKind;

        // Candidate-augmenter discovery (program completeness for relative
        // augmentation): an augmenter `declare module "./base"` block lives in a
        // file that depends on the base — so the base's reverse-dependency set
        // is exactly the candidate-augmenter set. Ensure each is indexed BEFORE
        // the augmentation-index scan (which only sees loaded artifacts), so a
        // sibling augmenter pulled in via a side-effect `import "./base"` is
        // discovered rather than silently dropped. Loads are idempotent /
        // content-hash cached; the augmentation index is then built once.
        let index_candidates = || {
            for rdep in self
                .ctx
                .reverse_dependency_canonicals(decl_canonical.as_ref())
            {
                let _ = self.ctx.source_is_available(&rdep);
            }
        };

        let target = AugmentationTargetKind::ResolvedRelativeCanonical(
            std::sync::Arc::<str>::from(decl_canonical.as_str()),
        );
        let contributions = self.collect_augmentation_contributions_after(
            AugmentationContribution::TypeBody,
            target,
            decl_name.as_ref(),
            &[],
            context,
            decl_canonical.as_ref(),
            None,
            index_candidates,
        )?;
        Some(self.merge_into_base(base_result, base_scope, contributions))
    }

    /// The call signatures `declare module` blocks in other files add to
    /// the exported function `decl_name` of `decl_canonical`: one overload
    /// group per augmenting block, in declaration order. `None` when no
    /// block contributes.
    pub(super) fn function_augmentations(
        &self,
        decl_canonical: &str,
        decl_name: &str,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<AugmentationContributions> {
        // Candidate-augmenter discovery, exactly as the declaration stitch
        // does it: an augmenting block lives in a file that depends on the
        // augmented module.
        for rdep in self.ctx.reverse_dependency_canonicals(decl_canonical) {
            let _ = self.ctx.source_is_available(&rdep);
        }
        self.collect_augmentation_contributions(
            AugmentationContribution::FunctionSignatures,
            verter_session_query::resolution::AugmentationTargetKind::ResolvedRelativeCanonical(
                std::sync::Arc::<str>::from(decl_canonical),
            ),
            decl_name,
            &[],
            context,
            decl_canonical,
            None,
        )
    }

    /// Fold a GLOBAL interface's other declarations into the base body
    /// `Instantiate` lowered from one of them (`decl_canonical`'s): every
    /// other module's `declare global` contribution and every other
    /// script's file-scope interface of the name, in declaration precedence
    /// order, through the same peer-merge carrier a relative augmentation
    /// takes. `type_arguments` bind each contributor's own clause.
    ///
    /// The folder observes the contributor population and every folded
    /// contributor's content version, so an edit to ANY declaration of the
    /// global misses the warm read. `None` when no other declaration
    /// exists.
    fn stitch_global_declarations(
        &self,
        decl_canonical: &verter_type_expr::OwnedStr,
        decl_name: &verter_type_expr::OwnedStr,
        type_arguments: &[SemanticNodeId],
        base_result: SemanticNodeId,
        base_scope: &NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<AugmentationStitch> {
        let contributions = self.collect_augmentation_contributions(
            AugmentationContribution::TypeBody,
            verter_session_query::resolution::AugmentationTargetKind::GlobalAugmentation,
            decl_name.as_ref(),
            type_arguments,
            context,
            decl_canonical.as_ref(),
            Some(decl_canonical.as_ref()),
        )?;
        Some(self.merge_into_base(base_result, base_scope, contributions))
    }

    /// Merge collected augmenter `contributions` into `base_result` as ONE
    /// peer-merge carrier.
    fn merge_into_base(
        &self,
        base_result: SemanticNodeId,
        base_scope: &NodeScopeId,
        contributions: AugmentationContributions,
    ) -> AugmentationStitch {
        let AugmentationContributions {
            contributor_nodes,
            contributor_roots,
            source_env_unobservable,
            base_position,
            signature_groups: _,
            enum_blocks: _,
        } = contributions;
        // Tainted-EMPTY collection: augmenters targeted this decl but every
        // contribution was unobservable. Keep the base body UNCHANGED (no false
        // single-contributor `MergedDecl` wrapper) but propagate the no-warm
        // taint so the enclosing `instantiate_shell` sets
        // `output.cache_suppress`. `source_env_unobservable` is `true` here (the
        // collector returns `None` for a genuine no-augmentation empty).
        if contributor_nodes.is_empty() {
            return AugmentationStitch {
                merged: base_result,
                contributor_roots: Vec::new(),
                source_env_unobservable,
            };
        }

        // Build the single peer-merge carrier: base contributors ∪ augmenter
        // contributions. If the base body is itself a `MergedDecl` (same-file
        // merge), flatten its contributors so the augmenter peers merge AT THE
        // SAME LEVEL in declaration order. The shared contributor splitter also
        // traverses nested groups supplied by other files' same-file merges.
        let base_contributors: Vec<SemanticNodeId> = match self.graph().node_data(base_result) {
            Some(data) => match data.as_ref() {
                SemanticNodeData::MergedDecl { contributors } => contributors.to_vec(),
                _ => vec![base_result],
            },
            None => vec![base_result],
        };
        // The base keeps its own place in declaration precedence order: a
        // global read from a later declaration's file still lists the earlier
        // files' declarations first. Augmentations follow the declaration
        // they augment.
        let position = base_position.unwrap_or(0).min(contributor_nodes.len());
        let mut all_contributors: Vec<SemanticNodeId> = contributor_nodes[..position].to_vec();
        all_contributors.extend(base_contributors);
        all_contributors.extend_from_slice(&contributor_nodes[position..]);
        let merged = self.graph().intern_node_with_scope(
            SemanticNodeData::MergedDecl {
                contributors: crate::semantic_query::PayloadArray::from(
                    all_contributors.into_boxed_slice(),
                ),
            },
            base_scope.clone(),
        );
        AugmentationStitch {
            merged,
            contributor_roots,
            source_env_unobservable,
        }
    }

    /// The contributions every augmenter and every other declaration of
    /// `decl_name` adds to the declaration `target` names, projected under
    /// `context` (see [`Self::fold_augmentation_contributions`]).
    ///
    /// A type-body fold is context-free up to its projection: which files
    /// contribute, their prepared declarations, scopes and authored shapes
    /// do not depend on the demanding context. A declaration instantiated
    /// under several contexts in one dispatch transaction — `keyof M` reads
    /// `M` published, `M[K]` reads it in structural transit — therefore
    /// folds once; every later context replays the fold's reads into the
    /// scopes live now and projects the planned bodies. The plan lives
    /// exactly as long as the transaction and is kept only when complete.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn collect_augmentation_contributions(
        &self,
        contribution: AugmentationContribution,
        target: verter_session_query::resolution::AugmentationTargetKind,
        decl_name: &str,
        type_arguments: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
        request_canonical: &str,
        excluded_contributor: Option<&str>,
    ) -> Option<AugmentationContributions> {
        self.collect_augmentation_contributions_after(
            contribution,
            target,
            decl_name,
            type_arguments,
            context,
            request_canonical,
            excluded_contributor,
            || {},
        )
    }

    /// [`Self::collect_augmentation_contributions`], running `prepare` first
    /// whenever the fold runs — inside the fold's recorded reads, so a
    /// reused fold replays what `prepare` read and skips its work.
    #[allow(clippy::too_many_arguments)]
    fn collect_augmentation_contributions_after(
        &self,
        contribution: AugmentationContribution,
        target: verter_session_query::resolution::AugmentationTargetKind,
        decl_name: &str,
        type_arguments: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
        request_canonical: &str,
        excluded_contributor: Option<&str>,
        prepare: impl FnOnce(),
    ) -> Option<AugmentationContributions> {
        let key = (contribution == AugmentationContribution::TypeBody).then(|| {
            super::dispatch_txn::AugmentationPlanKey {
                target: target.clone(),
                decl_name: Arc::from(decl_name),
                type_arguments: Arc::from(type_arguments),
                request_canonical: Arc::from(request_canonical),
                excluded_contributor: excluded_contributor.map(Arc::from),
            }
        });
        if let Some(plan) = key
            .as_ref()
            .and_then(|key| self.reusable_augmentation_plan(key))
        {
            return Some(self.project_augmentation_plan(&plan, type_arguments, context));
        }
        if key
            .as_ref()
            .is_some_and(|key| self.reuse_augmentation_absence(&key.absence()))
        {
            return None;
        }
        let fold = || {
            self.fold_augmentation_contributions(
                contribution,
                target,
                decl_name,
                context,
                request_canonical,
                excluded_contributor,
                prepare,
            )
        };
        let folded = match key {
            Some(key) => self.record_augmentation_plan(key, fold),
            None => fold().and_then(FoldedAugmentation::into_transaction_fold),
        }?;
        Some(match folded {
            TransactionFold::Contributions(contributions) => contributions,
            TransactionFold::Plan(plan) => {
                self.project_augmentation_plan(&plan, type_arguments, context)
            }
        })
    }

    /// A type-body fold this transaction completed for `key`, after
    /// replaying what folding it read — its facts, refusal, file self-roots
    /// and canonical evidence — into the scopes live now, exactly as
    /// folding it again would.
    fn reusable_augmentation_plan(
        &self,
        key: &super::dispatch_txn::AugmentationPlanKey,
    ) -> Option<Arc<AugmentationPlan>> {
        let txn = self.dispatch_txn.borrow();
        let completed = txn.augmentation.get(key)?;
        let replay = &completed.replay;
        replay.reads.replay();
        crate::fact_tracing::replay_reuse_refusal(&completed.reuse);
        self.deposit_operand_self_roots(&replay.observed_self_roots);
        if replay.canonical_evidence_deposited {
            self.canonical_evidence_epoch
                .set(self.canonical_evidence_epoch.get().wrapping_add(1));
        }
        Some(Arc::clone(&completed.plan))
    }

    /// Whether this transaction already read that nothing augments the
    /// declaration `key` names; a hit replays that read — its facts,
    /// refusal and file self-roots — into the scopes live now, exactly as
    /// folding it again would.
    fn reuse_augmentation_absence(
        &self,
        key: &super::dispatch_txn::AugmentationAbsenceKey,
    ) -> bool {
        let txn = self.dispatch_txn.borrow();
        let Some(completed) = txn.augmentation.absence(key) else {
            return false;
        };
        let replay = &completed.replay;
        replay.reads.replay();
        crate::fact_tracing::replay_reuse_refusal(&completed.reuse);
        self.deposit_operand_self_roots(&replay.observed_self_roots);
        if replay.canonical_evidence_deposited {
            self.canonical_evidence_epoch
                .set(self.canonical_evidence_epoch.get().wrapping_add(1));
        }
        true
    }

    /// Fold a type body, keeping a complete plan for the rest of the
    /// transaction with what reusing it replays. A fold is recorded only
    /// when every channel an enclosing build observes is observable here
    /// (the rule the flow-result table applies); anything else folds
    /// exactly as before and is never reused.
    fn record_augmentation_plan(
        &self,
        key: super::dispatch_txn::AugmentationPlanKey,
        fold: impl FnOnce() -> Option<FoldedAugmentation>,
    ) -> Option<TransactionFold> {
        let completeness_scope_active =
            crate::request_context::cold_compute_completeness_scope_active();
        let recordable = crate::resolver_core::resolver_context::fact_tracer_installed()
            && !self.build_local_taint.borrow().is_empty()
            && !(completeness_scope_active
                && crate::request_context::current_cold_compute_completeness().is_partial());
        if !recordable {
            return fold().and_then(FoldedAugmentation::into_transaction_fold);
        }
        let private_completeness = (!completeness_scope_active)
            .then(crate::request_context::ColdComputeCompletenessScope::enter);
        let evidence_epoch = self.canonical_evidence_epoch.get();
        let frame = super::BuildLocalTaintGuard::push(&self.build_local_taint);
        let refusals = crate::fact_tracing::RefusalObservationScope::enter();
        let (folded, reads) = crate::resolver_core::resolver_context::record_fact_reads(fold);
        let refused = refusals.observed();
        drop(refusals);
        let observed = frame.finish();
        let folded_partial =
            crate::request_context::current_cold_compute_completeness().is_partial();
        if let Some(scope) = private_completeness {
            scope.discard();
        }
        // The frame's rails reach the enclosing build exactly as if they had
        // folded there directly.
        self.fold_observed_frame_into_top(&observed);
        let refusal = match refused {
            Some(reason) => verter_session_query::facts::reuse::ObservedRefusal::Typed(reason),
            None if reads.non_cacheable || observed.cache_suppress => {
                verter_session_query::facts::reuse::ObservedRefusal::Unattributed
            }
            None => verter_session_query::facts::reuse::ObservedRefusal::None,
        };
        let complete_read = !observed.result_is_partial && !folded_partial;
        let folded = match folded? {
            FoldedAugmentation::Absent => {
                let reuse =
                    verter_session_query::facts::reuse::classify_reuse(refusal, complete_read);
                self.dispatch_txn
                    .borrow_mut()
                    .augmentation
                    .complete_absence(
                        key.absence(),
                        super::dispatch_txn::TransactionAugmentationAbsence {
                            reuse,
                            replay: super::dispatch_txn::FlowMemberReuse {
                                reads,
                                observed_self_roots: observed.observed_self_roots,
                                canonical_evidence_deposited: self.canonical_evidence_epoch.get()
                                    != evidence_epoch,
                            },
                        },
                    );
                return None;
            }
            folded => folded.into_transaction_fold()?,
        };
        let TransactionFold::Plan(plan) = &folded else {
            return Some(folded);
        };
        let complete = plan.context_free && complete_read;
        let reuse = verter_session_query::facts::reuse::classify_reuse(refusal, complete);
        if reuse.is_request_reusable() {
            self.dispatch_txn.borrow_mut().augmentation.complete(
                key,
                super::dispatch_txn::TransactionAugmentationPlan {
                    plan: Arc::clone(plan),
                    reuse,
                    replay: super::dispatch_txn::FlowMemberReuse {
                        reads,
                        observed_self_roots: observed.observed_self_roots,
                        canonical_evidence_deposited: self.canonical_evidence_epoch.get()
                            != evidence_epoch,
                    },
                },
            );
        }
        Some(folded)
    }

    /// Project a planned type-body fold under `context`: each planned body
    /// bound to the augmented declaration's arguments and projected exactly
    /// as [`Self::lower_located_body_with_provenance`] projects a located
    /// body, in fold order.
    fn project_augmentation_plan(
        &self,
        plan: &AugmentationPlan,
        type_arguments: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> AugmentationContributions {
        let mut contributor_nodes = Vec::with_capacity(plan.bodies.len());
        for body in &plan.bodies {
            let mut substitutions: Vec<(Arc<str>, SemanticNodeId)> = Vec::new();
            let (env, _) = self.bind_declared_type_arguments(
                &body.prepared,
                type_arguments,
                &DeclarationBindingScope {
                    scope: &body.scope,
                    scope_payload: body.scope_payload.as_ref(),
                    shadowing: &body.shadowing,
                    authored_resolution_debt: None,
                    augmentation: body.augmentation.as_ref(),
                },
                &mut substitutions,
                context,
                |_, _| None,
            );
            let env = &env;
            let mut lowering = match body.shape {
                Some(shape) => self.begin_shape_lowering(
                    shape,
                    &body.owner_symbol,
                    body.prepared.kind,
                    &body.prepared.type_parameters,
                    env,
                    &body.scope,
                    &mut substitutions,
                    context.into_structural_provenance(),
                    &[],
                    crate::project_semantic_dispatch::locator_view_worklist::ProjectionSeam::inline(
                    ),
                    body.augmentation.as_ref(),
                ),
                None => BodyLowering::Ready(self.opaque(QueryError::Miss)),
            };
            let inputs = crate::project_semantic_dispatch::locator_view::LocatorViewInputs {
                env,
                scope: &body.scope,
                name_resolution: &body.prepared.name_resolution,
                scope_payload: body.scope_payload.as_ref(),
                shadowing: &body.shadowing,
                authored_resolution_debt: None,
                self_value: None,
            };
            match self.drain_located_body_lowering(&mut lowering, &inputs, &mut substitutions, None)
            {
                BodyPoll::Done(node, _) => contributor_nodes.push(node),
                BodyPoll::Need(_) => {
                    unreachable!("an inline body lowering evaluates the instantiations it reaches")
                }
            }
        }
        if let Some((target, fingerprint)) = &plan.stitched {
            emit_module_augmentation_stitched_event::<C::Observe>(
                crate::resolver_core::resolver_context::capture_targets(self.ctx),
                target,
                plan.contributor_roots.len() as u32,
                *fingerprint,
            );
        }
        AugmentationContributions {
            contributor_nodes,
            contributor_roots: plan.contributor_roots.clone(),
            source_env_unobservable: plan.source_env_unobservable,
            base_position: plan.base_position,
            signature_groups: Vec::new(),
            enum_blocks: Vec::new(),
        }
    }

    /// Shared augmenter-contribution folder — the ONE cross-file
    /// declaration-merge augmenter path, used by BOTH the relative-canonical
    /// stitch ([`Self::stitch_module_augmentations`]) and the external
    /// string-literal resolution ([`Self::resolve_external_module_augmentation`]).
    ///
    /// Scans the overlay-aware augmentation index for `target`, lowers each
    /// contributing augmenter's RETAINED `decl_name` body in the augmenter's own
    /// file context (typed-IR `augmentation_scopes` inventory — never a source
    /// scan), and returns the ordered contributor nodes plus their per-augmenter
    /// `FileWholeHash` self-roots. Augmenter order is the stable
    /// `canonical` key (`AugmenterSet.entries` is pre-sorted
    /// that way — deterministic, discovery-order-independent).
    ///
    /// Observes the augmenter-set fingerprint (`ModuleAugmentationIndexShape`)
    /// plus each augmenter's `FileWholeHash` onto the active fact tracer
    /// so the cached value invalidates on an augmenter
    /// add/remove/reorder OR an augmenter content edit.
    /// These two facts are the sole cache-validity rail for the merged value:
    /// a member-body edit that leaves the augmenter skeleton (hence the
    /// set fingerprint) intact still moves the augmenter's `FileWholeHash`, so
    /// the per-augmenter whole-hash fact is what catches it.
    ///
    /// Type bodies retain their prepared declarations for projection. Each
    /// contributor then binds the application's arguments positionally,
    /// applying its own defaults through the same binder as Instantiate.
    /// An unsupplied parameter without a default stays unbound.
    ///
    /// `excluded_contributor` names a file whose contribution the caller
    /// already holds as the base body (a global declaration's own file):
    /// it is skipped, never folded twice.
    ///
    /// Returns [`FoldedAugmentation::Absent`] when no augmenter contributes.
    ///
    /// `contribution` is what each augmenter contributes: a type body, or
    /// the call signatures an augmenting block's function declarations add
    /// to an exported function value (file-scope global declarations never
    /// contribute those).
    #[allow(clippy::too_many_arguments)]
    fn fold_augmentation_contributions(
        &self,
        contribution: AugmentationContribution,
        target: verter_session_query::resolution::AugmentationTargetKind,
        decl_name: &str,
        context: crate::semantic_query::ProjectionReductionContext,
        request_canonical: &str,
        excluded_contributor: Option<&str>,
        prepare: impl FnOnce(),
    ) -> Option<FoldedAugmentation> {
        use verter_session_query::declarations::AugmentationScopeKind;
        use verter_session_query::resolution::AugmentationTargetKind;

        prepare();
        // Every read the fold consumes from here on — the index read, the
        // augmenter target resolutions, the contributor artifacts — decides
        // whether its healed keys may be written back to the shared index.
        let refusals = crate::fact_tracing::RefusalObservationScope::enter();
        // The source boundary captures the same session population and host
        // environment, ingests program roots, and returns an owned index read.
        let (key, augmenter_set, index_resolutions) =
            self.ctx.augmentation_index_with_resolutions(target.clone());
        // A specifier the index population resolved in this read is not
        // resolved again: the answer is the one the same fold just read.
        let resolve_module_file = |augmenter: &str, spec: &str| -> Option<Arc<str>> {
            if let Some(resolved) = index_resolutions.get(augmenter).and_then(|specs| {
                specs
                    .iter()
                    .find(|(resolved_spec, _)| resolved_spec.as_ref() == spec)
            }) {
                return resolved.1.clone();
            }
            self.ctx
                .resolve_type_dependency_canonical(augmenter, spec)
                .map(Arc::from)
        };

        // Fact rail, part 1 — the augmenter-set shape fact (invalidates on
        // augmenter add/remove/reorder and binding-owner/name/space changes). Observed onto the active tracer so it
        // enters this build's `ReadSetSignature.facts`.
        //
        // Observed HERE, immediately after the index read and BEFORE every
        // early return, because the NEGATIVE outcomes are reads too and their
        // results are cacheable:
        //   - empty set: "no augmenter targets this module" is a read of the
        //     index whose answer changes the moment an augmenter appears;
        //   - non-empty set, no contributor for this declaration: the set is
        //     keyed by target MODULE, not by declaration, so an existing
        //     augmenter GAINING this declaration moves the set fingerprint
        //     (it folds each augmenter's matching binding membership).
        // A cacheable "no augmentation" surface published without this fact
        // has nothing keyed on the augmenter set and serves stale once either
        // of those happens.
        //
        // The fingerprint is stable across the rest of this function: the
        // stale-key self-heal below re-publishes under the IDENTICAL
        // fingerprint by construction, so observing before it is equivalent to
        // observing after it.
        //
        // The shape fact's `canonical_id` is attribution only —
        // `ModuleAugmentationIndexShape` validation keys entirely on the typed
        // `FactKey` (target kind + specifier/canonical) and `expected_hash`,
        // never on this field.
        let shape_attribution: Arc<str> = match &target {
            AugmentationTargetKind::ResolvedRelativeCanonical(canon) => Arc::clone(canon),
            AugmentationTargetKind::ExternalSpecifier(spec) => Arc::clone(&spec.0),
            AugmentationTargetKind::WildcardAmbient(pat) => Arc::clone(&pat.0),
            AugmentationTargetKind::GlobalAugmentation => Arc::default(),
        };
        crate::resolver_core::resolver_context::observe_fan_out(
            verter_session_query::facts::fact_cache::FactVersionRef::RouteSurface(
                verter_session_query::facts::fact_cache::RouteSurfaceFactRef {
                    canonical_id: Arc::clone(&shape_attribution),
                    key: verter_session_query::source::augmentation_keys::build_module_augmentation_index_shape_fact_key(
                        &target,
                    ),
                    lane: verter_session_query::facts::FactLane::Semantic,
                    expected_hash: augmenter_set.fingerprint,
                },
            ),
        );

        // The file-scope declarations collected beside the augmenters: a
        // type body's interfaces and namespaces, an enum's script blocks.
        let (selection, space) = match contribution {
            AugmentationContribution::EnumBlocks => (
                verter_session_query::inputs::contributors::FileScopeContribution::EnumBlock,
                Some(verter_session_query::facts::SymbolSpace::Value),
            ),
            AugmentationContribution::TypeBody | AugmentationContribution::FunctionSignatures => (
                verter_session_query::inputs::contributors::FileScopeContribution::TypeBody,
                None,
            ),
        };
        let population_answer =
            self.ctx
                .contributor_answer(request_canonical, &target, decl_name, space);
        let population_hit = population_answer.contributors;
        crate::resolver_core::resolver_context::observe_fan_out(
            verter_session_query::facts::fact_cache::FactVersionRef::RouteSurface(
                verter_session_query::facts::fact_cache::RouteSurfaceFactRef {
                    canonical_id: shape_attribution,
                    key:
                        verter_session_query::inputs::contributors::population_contributor_fact_key(
                            &target, decl_name,
                        ),
                    lane: verter_session_query::facts::FactLane::Semantic,
                    expected_hash: population_answer.population_fingerprint,
                },
            ),
        );
        let has_file_scope = population_hit.entries.iter().any(|entry| {
            use verter_session_query::inputs::contributors::ContributorOrigin;
            match selection {
                verter_session_query::inputs::contributors::FileScopeContribution::TypeBody => {
                    matches!(
                        entry.origin,
                        ContributorOrigin::FileScopeInterface
                            | ContributorOrigin::FileScopeNamespace
                    )
                }
                verter_session_query::inputs::contributors::FileScopeContribution::EnumBlock => {
                    entry.origin == ContributorOrigin::FileScopeValue
                }
            }
        });
        if augmenter_set.entries.is_empty() && !has_file_scope {
            return Some(FoldedAugmentation::Absent);
        }

        // An empty, nongeneric interface adds neither a member nor a
        // diagnostic-producing evaluation to a nongeneric class. Establish
        // the base header inside this fold's recorded reads, so a cached
        // absence cannot outlive a change to the class's binder frame.
        let neutral_class_base = contribution == AugmentationContribution::TypeBody
            && matches!(&target, AugmentationTargetKind::ResolvedRelativeCanonical(canonical)
                if self.ctx.prepared_type_decl_return_only(canonical,
                    verter_type_expr::TopLevelOwnerId::ordinary_file(), decl_name)
                    .is_some_and(|base| base.kind == verter_session_query::declarations::TypeDeclKind::Class
                        && base.type_parameters.is_empty()));

        let mut contributor_nodes: Vec<SemanticNodeId> = Vec::new();
        // A type body's contributions are planned here and projected under
        // each demanding context by the caller.
        let mut planned_bodies: Vec<PlannedContributorBody> = Vec::new();
        let mut context_free = true;
        let mut signature_groups: Vec<Vec<SemanticNodeId>> = Vec::new();
        let mut enum_blocks: Vec<EnumContribution> = Vec::new();
        // One root per contributing augmenter: the version self-root AND the
        // EXACT artifact key the contributor `LowerLocator` served from,
        // inseparable in one carrier — recorded below as paired
        // `FileWholeHash` + `FileSourceEnv` observations on the parent
        // read-set.
        let mut contributor_roots: Vec<AugmentationContributorRoot> = Vec::new();
        let mut source_env_unobservable = false;
        // Stale-key self-heals discovered below are written back into the
        // cached `AugmenterSet` after the loop so the NEXT stitch hits the
        // fast exact-key path instead of re-healing every call.
        let mut refreshed_keys: Vec<(
            usize,
            verter_session_query::source::artifact_key::FileArtifactKey,
        )> = Vec::new();
        let mut base_position: Option<usize> = None;
        use verter_session_query::inputs::contributors::AugmentationCandidate as OrderedOrigin;
        let ordered = self.ctx.augmentation_contributor_order(
            request_canonical,
            &key,
            &augmenter_set,
            decl_name,
            &population_hit,
            selection,
        );
        // An enum's blocks are its program's: a file another project owns
        // declares another project's enum of the name.
        let request_project = (contribution == AugmentationContribution::EnumBlocks)
            .then(|| self.ctx.project_stable_key_for_canonical(request_canonical));
        let candidate_canonical = |candidate: OrderedOrigin| -> &str {
            match candidate {
                OrderedOrigin::Augmenter(i) => augmenter_set.entries[i].canonical().as_ref(),
                OrderedOrigin::FileScope(i) => {
                    population_hit.entries[i].artifact_key.canonical.as_ref()
                }
            }
        };
        // Which declaration blocks of an augmenter contribute to
        // `decl_name`: each `ModuleAugmentationFact` of the block that
        // targets this declaration, as its raw specifier (the key its typed
        // inner body is retained under) and its owner.
        let matched_augmentations =
            |augmenter_canonical: &str,
             art: &crate::resolver_core::request_ports::AugmenterArtifactAnswer|
             -> Vec<(
                String,
                verter_type_expr::TopLevelOwnerId,
                AugmentationScopeKind,
            )> {
                let mut matched_specs: Vec<(
                    String,
                    verter_type_expr::TopLevelOwnerId,
                    AugmentationScopeKind,
                )> = Vec::new();
                for fact in art.augmentations.iter() {
                    if fact.augmented_name.as_ref() != decl_name {
                        continue;
                    }
                    if contribution != AugmentationContribution::TypeBody
                        && fact.space != verter_session_query::facts::registry::SymbolSpace::Value
                    {
                        continue;
                    }
                    let resolved = if matches!(key.target, verter_session_query::resolution::AugmentationTargetKind::ResolvedRelativeCanonical(_))
                    && verter_session_query::source::augmentation::fact_augments_resolved_module(fact) {
                    resolve_module_file(augmenter_canonical, fact.specifier.as_ref())
                } else { None };
                    if !verter_session_query::source::augmentation::augmenter_matches_target(
                        fact,
                        &key,
                        resolved.as_deref(),
                    ) {
                        continue;
                    }
                    let spec = fact.specifier.as_ref();
                    if matched_specs
                        .iter()
                        .any(|(matched, owner, _)| matched == spec && *owner == fact.owner)
                    {
                        continue;
                    }
                    // A `declare global` augmenter is indexed under the global
                    // tag; its retained body lives in the GLOBAL augmentation
                    // scope, not in a module scope named after the tag.
                    let scope = if spec
                        == verter_session_query::source::augmentation::GLOBAL_AUGMENTATION_TAG
                    {
                        AugmentationScopeKind::Global
                    } else {
                        AugmentationScopeKind::Module(spec.to_string())
                    };
                    matched_specs.push((spec.to_string(), fact.owner, scope));
                }
                matched_specs
            };
        // Every contributor's source, artifact answer and contributing
        // blocks, read once up front so the type bodies the fold lowers can
        // be lowered as ONE batch — one lowering-service rendezvous per
        // worker shard — before the fold reads them one by one.
        let mut prefetched: Vec<Option<ContributorPrefetch>> = Vec::with_capacity(ordered.len());
        for candidate in ordered.iter().copied() {
            let canonical = candidate_canonical(candidate);
            if excluded_contributor == Some(canonical) || request_project.is_some() {
                prefetched.push(None);
                continue;
            }
            let Some(indexed) = self
                .ctx
                .ensure_indexed_ready_serve(canonical)
                .map(|serve| serve.indexed)
            else {
                prefetched.push(None);
                continue;
            };
            let mut prefetch = ContributorPrefetch {
                indexed,
                art: None,
                matched: Vec::new(),
            };
            if let OrderedOrigin::Augmenter(augmenter_idx) = candidate {
                let declares_from_script =
                    matches!(target, AugmentationTargetKind::GlobalAugmentation)
                        && verter_session_query::inputs::contributors::classify_shallow_module_kind(
                            &prefetch.indexed.shallow_state,
                        ) == verter_session_query::inputs::contributors::FileModuleKind::Script;
                if !declares_from_script {
                    let augmenter = &augmenter_set.entries[augmenter_idx];
                    if let Some(art) = self.ctx.augmenter_artifact_answer(
                        &augmenter.artifact_key,
                        prefetch.indexed.whole_hash,
                    ) {
                        prefetch.matched = matched_augmentations(canonical, &art);
                        prefetch.art = Some(art);
                    }
                }
            }
            prefetched.push(Some(prefetch));
        }
        let _batched_bodies = (contribution == AugmentationContribution::TypeBody).then(|| {
            let mut demands: Vec<verter_session_query::source::demand::TypeBodyBatchDemand<'_>> =
                Vec::new();
            for (candidate, prefetch) in ordered.iter().zip(&prefetched) {
                let Some(prefetch) = prefetch else {
                    continue;
                };
                let source = &*prefetch.indexed.shallow_state;
                if let OrderedOrigin::FileScope(i) = *candidate {
                    demands.push(verter_session_query::source::demand::TypeBodyBatchDemand {
                        source,
                        owner: population_hit.entries[i].owner,
                        name: decl_name,
                        scope: None,
                    });
                }
                for (_, owner, scope) in &prefetch.matched {
                    demands.push(verter_session_query::source::demand::TypeBodyBatchDemand {
                        source,
                        owner: *owner,
                        name: decl_name,
                        scope: Some(scope),
                    });
                }
            }
            self.ctx.batch_type_bodies(&demands)
        });
        for (position, candidate) in ordered.iter().copied().enumerate() {
            let canonical = candidate_canonical(candidate);
            if excluded_contributor == Some(canonical) {
                base_position.get_or_insert(contributor_nodes.len() + planned_bodies.len());
                continue;
            }
            if let Some(project) = &request_project {
                let owner = self.ctx.project_stable_key_for_canonical(canonical);
                if owner.is_some() && owner != *project {
                    continue;
                }
            }
            let prefetch = prefetched[position].take();
            match candidate {
                OrderedOrigin::Augmenter(augmenter_idx) => {
                    let augmenter = &augmenter_set.entries[augmenter_idx];
                    let augmenter_canonical = augmenter.canonical();
                    let (prefetched_art, prefetched_matched, prefetched_indexed) = match prefetch {
                        Some(prefetch) => {
                            (prefetch.art, Some(prefetch.matched), Some(prefetch.indexed))
                        }
                        None => (None, None, None),
                    };
                    let Some(indexed) = prefetched_indexed.or_else(|| {
                        self.ctx
                            .ensure_indexed_ready_serve(augmenter_canonical.as_ref())
                            .map(|serve| serve.indexed)
                    }) else {
                        // A set member the live view cannot serve is a torn state:
                        // its contribution (and source-env identity) cannot be
                        // observed coherently — the parent result must not warm. The
                        // generalized non-cacheability rail is fanned ONCE at the single
                        // CONSUMER (`instantiate_shell`, where this flag becomes
                        // `output.cache_suppress`), covering every unobservable source.
                        source_env_unobservable = true;
                        continue;
                    };
                    // `declare global` augments the global scope only from a
                    // MODULE: in a script it is an error and binds nothing
                    // (the augmenter set still fingerprints the file, so the
                    // script gaining module syntax misses the warm read).
                    if matches!(target, AugmentationTargetKind::GlobalAugmentation)
                        && verter_session_query::inputs::contributors::classify_shallow_module_kind(
                            &indexed.shallow_state,
                        ) == verter_session_query::inputs::contributors::FileModuleKind::Script
                    {
                        continue;
                    }
                    // The addressable contribution pointers: each augmenter
                    // `ModuleAugmentationFact` that targets THIS decl gives the raw
                    // `declare module "<spec>"` specifier under which the typed inner
                    // body is retained in `augmentation_scopes`.
                    //
                    // Self-heal a STALE captured `artifact_key`: a cosmetic /
                    // member-body re-key of the augmenter advances its content hash
                    // (draining the captured key) without moving its decl skeleton,
                    // so the cached `AugmenterSet` keeps the pre-edit key. Skipping
                    // the augmenter on that miss would silently drop a real
                    // augmentation. `ensure_indexed_ready_serve` above already materialised
                    // the augmenter's CURRENT version, so `indexed.whole_hash` is the
                    // scheduler-authoritative current content hash.
                    let (art, matched_specs) = match prefetched_art {
                        Some(art) => (art, prefetched_matched.unwrap_or_default()),
                        None => {
                            let Some(art) = self.ctx.augmenter_artifact_answer(
                                &augmenter.artifact_key,
                                indexed.whole_hash,
                            ) else {
                                // Unhealable captured key: the augmenter's exact artifact
                                // identity is unobservable — refuse warm admission. The
                                // generalized non-cacheability rail is fanned ONCE at the
                                // consumer (see the unservable arm above).
                                source_env_unobservable = true;
                                continue;
                            };
                            let matched = matched_augmentations(augmenter_canonical.as_ref(), &art);
                            (art, matched)
                        }
                    };
                    // The EXACT key the contributor read serves from (the healed
                    // current key when the captured one was stale).
                    let refreshed_key = art.refreshed_key.clone();
                    let effective_artifact_key = refreshed_key
                        .clone()
                        .unwrap_or_else(|| augmenter.artifact_key.clone());
                    if let Some(refreshed_key) = refreshed_key {
                        refreshed_keys.push((augmenter_idx, refreshed_key));
                    }
                    if matched_specs.is_empty() {
                        continue;
                    }

                    let Some(bundle) = self.ctx.prepared_decl_bundle(augmenter_canonical.as_ref())
                    else {
                        source_env_unobservable = true;
                        continue;
                    };

                    let mut any_contribution = false;
                    for (spec, contributor_owner, _) in &matched_specs {
                        let aug_scope = NodeScopeId::File {
                            canonical_id: verter_type_expr::OwnedStr::from(augmenter_canonical),
                            owner: *contributor_owner,
                            whole_hash: indexed.whole_hash,
                            local_scope: None,
                        };
                        let aug_scope_payload = Some(
                    crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                        &bundle,
                        *contributor_owner,
                    ),
                );
                        let aug_shadowing =
                    crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
                        aug_scope_payload.as_ref(),
                    );
                        // A `declare global` augmenter is indexed under the global tag;
                        // its retained body lives in the GLOBAL augmentation scope, not
                        // in a module scope named after the tag.
                        let is_global = spec.as_str()
                            == verter_session_query::source::augmentation::GLOBAL_AUGMENTATION_TAG;
                        let scope_kind = if is_global {
                            AugmentationScopeKind::Global
                        } else {
                            AugmentationScopeKind::Module(spec.clone())
                        };
                        let aug_scope = Self::augmentation_body_scope(
                            aug_scope,
                            &indexed.shallow_state.headers,
                            &scope_kind,
                            decl_name,
                        );
                        if contribution == AugmentationContribution::EnumBlocks {
                            // The block's members, read in the block's own
                            // scope: a same-named declaration of the file
                            // itself is another declaration.
                            let prepared = match self.ctx.prepare_augmentation_value(
                                &bundle,
                                &scope_kind,
                                *contributor_owner,
                                decl_name,
                            ) {
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                    Some(prepared),
                                ) => prepared,
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                    None,
                                ) => continue,
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::LeaseMiss
                                | verter_session_query::inputs::prepared::PreparedDeclOutcome::Failed(_) => {
                                    source_env_unobservable = true;
                                    continue;
                                }
                            };
                            let Some(members) = prepared.enum_members.as_ref().filter(|_| {
                                prepared.kind
                                    == verter_session_query::declarations::ValueDeclKind::Enum
                            }) else {
                                continue;
                            };
                            enum_blocks.push(EnumContribution {
                                canonical: Arc::clone(augmenter_canonical),
                                owner: *contributor_owner,
                                scope: Some(scope_kind),
                                members: Arc::clone(&members.members),
                            });
                            any_contribution = true;
                            continue;
                        }
                        if contribution == AugmentationContribution::FunctionSignatures {
                            let prepared = match self.ctx.prepare_augmentation_value(&bundle,
                                &scope_kind,
                                *contributor_owner,
                                decl_name,
                            ) {
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                    Some(prepared),
                                ) => prepared,
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                    None,
                                ) => continue,
                                verter_session_query::inputs::prepared::PreparedDeclOutcome::LeaseMiss
                                | verter_session_query::inputs::prepared::PreparedDeclOutcome::Failed(_) => {
                                    source_env_unobservable = true;
                                    continue;
                                }
                            };
                            let signatures: Vec<SemanticNodeId> =
                                crate::semantic_query::visible_overload_ordinals(
                                    prepared
                                        .signatures
                                        .iter()
                                        .map(|signature| signature.has_implementation_body),
                                )
                                .into_iter()
                                .map(|ordinal| {
                                    let locator =
                                        verter_type_expr::locators::AuthoredBodyLocator::AugmentationBody(
                                            verter_type_expr::locators::AugmentationBodyLocator {
                                                anchor: verter_type_expr::locators::AuthoredAnchor {
                                                    canonical_id: verter_type_expr::OwnedStr::from(augmenter_canonical),
                                                    owner: *contributor_owner,
                                                    symbol: verter_type_expr::OwnedStr::from(decl_name),
                                                    space: verter_type_expr::locators::LocatorSymbolSpace::Value,
                                                },
                                                scope: if is_global {
                                                    verter_type_expr::locators::AuthoredAugmentationScope::Global
                                                } else {
                                                    verter_type_expr::locators::AuthoredAugmentationScope::Module {
                                                        specifier: verter_type_expr::OwnedStr::from(spec.as_str()),
                                                    }
                                                },
                                                path: verter_type_expr::OwnedSlice::from(
                                                    vec![verter_type_expr::locators::TypeBodyPathStep::ValueSignature {
                                                        ordinal: u32::try_from(ordinal).unwrap_or(u32::MAX),
                                                    }]
                                                    .into_boxed_slice(),
                                                ),
                                            },
                                        );
                                    let mut subs: Vec<(Arc<str>, SemanticNodeId)> = Vec::new();
                                    self.lower_located_body_with_provenance(
                                        locator,
                                        verter_session_query::declarations::TypeDeclKind::Alias,
                                        &[],
                                        &prepared.name_resolution,
                                        &FxHashMap::default(),
                                        &aug_scope,
                                        aug_scope_payload.as_ref(),
                                        &aug_shadowing,
                                        &mut subs,
                                        context.into_structural_provenance(),
                                    )
                                })
                                .collect();
                            if signatures.is_empty() {
                                continue;
                            }
                            contributor_nodes.extend(signatures.iter().copied());
                            signature_groups.push(signatures);
                            any_contribution = true;
                            continue;
                        }
                        let aug_prepared = match self.ctx.prepare_augmentation_type(
                            &bundle,
                            &scope_kind,
                            *contributor_owner,
                            decl_name,
                        ) {
                            verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                Some(prepared),
                            ) => prepared,
                            // Genuine absence: this augmenter has no contributor for the spec.
                            verter_session_query::inputs::prepared::PreparedDeclOutcome::Ready(
                                None,
                            ) => continue,
                            // A broken decl-body lease pin (the augmenter body demand
                            // ReturnOnly'd): the augmenter's source-env is UNOBSERVABLE —
                            // fold into the fold's no-warm rail so the enclosing query's
                            // `cache_suppress` is set, rather than silently dropping the
                            // contributor and warm-admitting an under-merged surface. The
                            // generalized non-cacheability rail is fanned ONCE at the
                            // consumer (`instantiate_shell`) for every unobservable
                            // source, so the enclosing component-meta tracer refuses the
                            // final result too. A later demand under a live lease recovers.
                            verter_session_query::inputs::prepared::PreparedDeclOutcome::LeaseMiss => {
                                source_env_unobservable = true;
                                continue;
                            }
                            verter_session_query::inputs::prepared::PreparedDeclOutcome::Failed(_) => {
                                source_env_unobservable = true;
                                continue;
                            }
                        };
                        // Demand the augmenter's RETAINED contribution body through
                        // the augmenter's OWN `LowerLocator` (the augmentation-scoped
                        // locator leaf) — never an inline lowering of another file's
                        // prepared body. An augmenter contribution is never the
                        // macro-T own body — the projection downgrades provenance to
                        // structural (same rule the builtin / heritage paths apply).
                        let locator =
                            verter_type_expr::locators::AuthoredBodyLocator::AugmentationBody(
                                verter_type_expr::locators::AugmentationBodyLocator {
                                    anchor: verter_type_expr::locators::AuthoredAnchor {
                                        canonical_id: verter_type_expr::OwnedStr::from(
                                            augmenter_canonical,
                                        ),
                                        owner: *contributor_owner,
                                        symbol: verter_type_expr::OwnedStr::from(decl_name),
                                        space: verter_type_expr::locators::LocatorSymbolSpace::Type,
                                    },
                                    scope: if is_global {
                                        verter_type_expr::locators::AuthoredAugmentationScope::Global
                                    } else {
                                        verter_type_expr::locators::AuthoredAugmentationScope::Module {
                                specifier: verter_type_expr::OwnedStr::from(spec.as_str()),
                            }
                                    },
                                    // The whole augmentation contribution body (no sub-slot).
                                    path: verter_type_expr::OwnedSlice::from(
                                        Vec::<verter_type_expr::locators::TypeBodyPathStep>::new()
                                            .into_boxed_slice(),
                                    ),
                                },
                            );
                        if neutral_class_base
                            && aug_prepared.kind
                                == verter_session_query::declarations::TypeDeclKind::Interface
                            && aug_prepared.type_parameters.is_empty()
                            && aug_prepared.member_index.is_empty()
                        {
                            let empty = |body: &TypeExpr| {
                                matches!(body,
                                TypeExpr::Object(object) if object.properties.is_empty())
                            };
                            if self.ctx.deref_authored_body(&indexed.shallow_state, &locator).is_ok_and(|body| {
                                body.type_parameters.is_empty() && match &body.shape {
                                    verter_session_query::source::deref::DerefedBodyShape::Single(body) => empty(body),
                                    verter_session_query::source::deref::DerefedBodyShape::Merged(bodies) => !bodies.is_empty() && bodies.iter().all(empty),
                                }
                            }) {
                                // The exact body port already observed content.
                                // Keep the previous source-environment/refusal
                                // rail even though no graph body is demanded.
                                if crate::fact_signature_helpers::observe_file_source_env_from_artifact_key(
                                    self.ctx, Some(&effective_artifact_key)).is_none() {
                                    source_env_unobservable = true;
                                }
                                continue;
                            }
                        }
                        let shape = self.fetch_located_shape(locator);
                        context_free &= shape.is_some();
                        planned_bodies.push(PlannedContributorBody {
                            shape,
                            owner_symbol: verter_type_expr::OwnedStr::from(decl_name),
                            prepared: verter_retention::heap_size::OwnedValue::new(aug_prepared),
                            augmentation: Some(scope_kind),
                            scope: aug_scope,
                            scope_payload: aug_scope_payload,
                            shadowing: aug_shadowing,
                        });
                        any_contribution = true;
                    }
                    if any_contribution {
                        // Root on the OVERLAY-AWARE content version the body was
                        // actually lowered from (`indexed.whole_hash` == `aug_scope`'s
                        // hash), NOT `get_whole_hash` (which can report the BASE hash
                        // under a session view). A session-overlay augmenter rooted on
                        // the base hash would tear: the value reflects overlay content
                        // but the fact pins base content, so a BASE re-query validates
                        // the session candidate and is poisoned. Rooting on the
                        // overlay hash makes the base re-query miss and recompute.
                        // The version root and the source-env artifact key travel as
                        // ONE carrier: a contributor cannot be version-rooted without
                        // its source-env identity.
                        contributor_roots.push(AugmentationContributorRoot {
                            canonical: verter_type_expr::OwnedStr::from(augmenter_canonical),
                            whole_hash: indexed.whole_hash,
                            artifact_key: effective_artifact_key,
                        });
                    }
                }
                OrderedOrigin::FileScope(_)
                    if contribution == AugmentationContribution::FunctionSignatures =>
                {
                    continue;
                }
                // A script's block of the global enum: its own declaration
                // of the name.
                OrderedOrigin::FileScope(file_scope_idx)
                    if contribution == AugmentationContribution::EnumBlocks =>
                {
                    let entry = &population_hit.entries[file_scope_idx];
                    let canonical = entry.artifact_key.canonical.as_ref();
                    let Some(indexed) = prefetch.map(|prefetch| prefetch.indexed).or_else(|| {
                        self.ctx
                            .ensure_indexed_ready_serve(canonical)
                            .map(|serve| serve.indexed)
                    }) else {
                        source_env_unobservable = true;
                        continue;
                    };
                    let Some(art) = self
                        .ctx
                        .augmenter_artifact_answer(&entry.artifact_key, indexed.whole_hash)
                    else {
                        source_env_unobservable = true;
                        continue;
                    };
                    let prepared =
                        match self
                            .ctx
                            .prepared_value_decl(canonical, entry.owner, decl_name)
                        {
                            Ok(Some(prepared)) => prepared,
                            Ok(None) => continue,
                            Err(_) => {
                                source_env_unobservable = true;
                                continue;
                            }
                        };
                    let Some(members) = prepared.enum_members.as_ref().filter(|_| {
                        prepared.kind == verter_session_query::declarations::ValueDeclKind::Enum
                    }) else {
                        continue;
                    };
                    enum_blocks.push(EnumContribution {
                        canonical: Arc::clone(&entry.artifact_key.canonical),
                        owner: entry.owner,
                        scope: None,
                        members: Arc::clone(&members.members),
                    });
                    contributor_roots.push(AugmentationContributorRoot {
                        canonical: verter_type_expr::OwnedStr::from(
                            entry.artifact_key.canonical.clone(),
                        ),
                        whole_hash: indexed.whole_hash,
                        artifact_key: art
                            .refreshed_key
                            .clone()
                            .unwrap_or_else(|| entry.artifact_key.clone()),
                    });
                }
                OrderedOrigin::FileScope(file_scope_idx) => {
                    let entry = &population_hit.entries[file_scope_idx];
                    let canonical = entry.artifact_key.canonical.as_ref();
                    let Some(indexed) = prefetch.map(|prefetch| prefetch.indexed).or_else(|| {
                        self.ctx
                            .ensure_indexed_ready_serve(canonical)
                            .map(|serve| serve.indexed)
                    }) else {
                        source_env_unobservable = true;
                        continue;
                    };
                    let Some(art) = self
                        .ctx
                        .augmenter_artifact_answer(&entry.artifact_key, indexed.whole_hash)
                    else {
                        source_env_unobservable = true;
                        continue;
                    };
                    let refreshed_key = art.refreshed_key.clone();
                    let effective_artifact_key = refreshed_key
                        .clone()
                        .unwrap_or_else(|| entry.artifact_key.clone());

                    let Some(bundle) = self.ctx.prepared_decl_bundle(canonical) else {
                        source_env_unobservable = true;
                        continue;
                    };
                    let prepared =
                        match self
                            .ctx
                            .prepared_type_from_input(&bundle, entry.owner, decl_name)
                        {
                            Ok(Some(prepared)) => prepared,
                            Ok(None) => continue,
                            Err(_) => {
                                source_env_unobservable = true;
                                continue;
                            }
                        };
                    let aug_scope = NodeScopeId::File {
                        canonical_id: verter_type_expr::OwnedStr::from(
                            entry.artifact_key.canonical.clone(),
                        ),
                        owner: entry.owner,
                        whole_hash: indexed.whole_hash,
                        local_scope: None,
                    };
                    let aug_scope_payload = Some(self.declaration_scope_payload(
                        &bundle,
                        canonical,
                        entry.owner,
                        decl_name,
                    ));
                    let aug_shadowing =
                        crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
                            aug_scope_payload.as_ref(),
                        );
                    let locator = verter_type_expr::locators::AuthoredBodyLocator::DeclBody(
                verter_type_expr::locators::TypeBodySlot {
                    anchor: verter_type_expr::locators::AuthoredAnchor {
                        canonical_id: verter_type_expr::OwnedStr::from(entry.artifact_key.canonical.clone()),
                        owner: entry.owner,
                        symbol: verter_type_expr::OwnedStr::from(decl_name),
                        space: if entry.origin
                            == verter_session_query::inputs::contributors::ContributorOrigin::FileScopeNamespace
                        {
                            verter_type_expr::locators::LocatorSymbolSpace::Namespace
                        } else {
                            verter_type_expr::locators::LocatorSymbolSpace::Type
                        },
                    },
                    path: verter_type_expr::OwnedSlice::from(
                        Vec::<verter_type_expr::locators::TypeBodyPathStep>::new()
                            .into_boxed_slice(),
                    ),
                },
            );
                    let shape = self.fetch_located_shape(locator);
                    context_free &= shape.is_some();
                    planned_bodies.push(PlannedContributorBody {
                        shape,
                        owner_symbol: verter_type_expr::OwnedStr::from(decl_name),
                        prepared,
                        augmentation: None,
                        scope: aug_scope,
                        scope_payload: aug_scope_payload,
                        shadowing: aug_shadowing,
                    });
                    contributor_roots.push(AugmentationContributorRoot {
                        canonical: verter_type_expr::OwnedStr::from(
                            entry.artifact_key.canonical.clone(),
                        ),
                        whole_hash: indexed.whole_hash,
                        artifact_key: effective_artifact_key,
                    });
                    let _ = art;
                }
            }
        }

        // Test-injection: taint the (successfully-collected) contribution set as
        // if one contributor's source-env identity were unobservable — the exact
        // no-warm state a torn/unhealable/unservable augmenter organically
        // produces, but with a deterministic trigger and WITHOUT emptying the
        // contribution set (so the resolved surface stays a real merged type,
        // isolating the `source_env_unobservable` fold from the unrelated
        // import-miss suppress rail). Gated
        // `#[cfg(any(test, feature = "test-support"))]` so a production build
        // has NO field and NO load on this augmentation-collection hot path.
        #[cfg(any(test, feature = "test-support"))]
        if self.ctx.augmentation_source_env_forced_unobservable() {
            source_env_unobservable = true;
        }

        // Persist any healed exact keys back into the cached `AugmenterSet`.
        // Content changes can advance an exact artifact locator while keeping
        // population membership identical. Each served artifact independently
        // observed its content; the conditional refresh preserves the recorded
        // population fingerprint without replacing a concurrent population.
        // A fold that consumed a read the process did not keep — an
        // unretained or refused resolution among them — answers this request
        // only: nothing it derived, healed keys included, enters the index.
        if refusals.observed().is_none() {
            self.ctx
                .refresh_augmentation_keys(&key, &augmenter_set, refreshed_keys);
        }
        drop(refusals);

        if contributor_nodes.is_empty() && planned_bodies.is_empty() && enum_blocks.is_empty() {
            // DISTINGUISH the two empty outcomes (they are NOT the same):
            //   - `source_env_unobservable == true`: augmenters targeted this
            //     decl but EVERY contribution was unobservable (torn / unhealable
            //     / unservable). This is NOT "no augmentation" — the merged
            //     surface would be incomplete, so the caller must fold a no-warm
            //     `cache_suppress` signal. Return a tainted-empty outcome (no
            //     nodes, no roots, `source_env_unobservable = true`) so the
            //     relative and external callers route it to the semantic
            //     cache-suppress rail instead of publishing a base-only / miss
            //     result warm.
            //   - `source_env_unobservable == false`: genuinely no augmenter
            //     contributes this decl — a real, cacheable no-augmentation
            //     result. Whether an augmenter contributes depends on the
            //     augmenter set and each augmenter's retained declarations,
            //     never on this instantiation's arguments or projection, so
            //     it is the same `Absent` answer an empty augmenter set gives:
            //     the caller keeps the base body unchanged, warms normally, and
            //     later instantiations in the transaction replay this read.
            if source_env_unobservable {
                return Some(FoldedAugmentation::Contributions(
                    AugmentationContributions {
                        contributor_nodes: Vec::new(),
                        contributor_roots: Vec::new(),
                        source_env_unobservable: true,
                        base_position: None,
                        signature_groups: Vec::new(),
                        enum_blocks: Vec::new(),
                    },
                ));
            }
            return Some(FoldedAugmentation::Absent);
        }

        // Fact rail, part 2 — each contributing augmenter's whole-hash
        // (invalidates on augmenter content edit). The augmenter-set shape
        // fact that pairs with these was observed above, before the early
        // returns, so the negative outcomes carry it too.
        //
        // Parent transitive contributor rule, emitted from the ONE carrier in
        // ONE step per contributor: the content-version fact
        // (`FileWholeHash`) AND the typed SOURCE-ENV observation
        // (`FileSourceEnv`) — its parser-version/file-language identity taken
        // from the EXACT artifact key the contributor `LowerLocator` served
        // from (never re-derived from canonical/path at this site, never a
        // stale index entry), its parse-env dimension the contributor
        // canonical's LIVE per-canonical parse env (the SAME dimension the
        // contributor `LowerLocator` key folds; the base key's own slot is
        // the zero sentinel, not an env identity). A warm parent hit
        // revalidates the source-env identity against the live view — a
        // contributor parse-env / parser-version / file-language move with
        // UNCHANGED content misses the warm read and recomputes through the
        // contributor's new `LowerLocator`. Because both facts come from the
        // same element, a contributor that is version-rooted on the parent is
        // source-env-observed by construction.
        for root in &contributor_roots {
            crate::resolver_core::resolver_context::observe_fan_out(
                verter_session_query::facts::fact_cache::FactVersionRef::FileWholeHash {
                    canonical_id: Arc::from(root.canonical.as_str()),
                    hash: root.whole_hash,
                },
            );
            if crate::fact_signature_helpers::observe_file_source_env_from_artifact_key(
                self.ctx,
                Some(&root.artifact_key),
            )
            .is_none()
            {
                source_env_unobservable = true;
            }
        }

        if contribution == AugmentationContribution::TypeBody {
            return Some(FoldedAugmentation::Plan(AugmentationPlan {
                bodies: planned_bodies,
                contributor_roots,
                source_env_unobservable,
                base_position,
                stitched: Some((target, augmenter_set.fingerprint)),
                context_free,
            }));
        }
        emit_module_augmentation_stitched_event::<C::Observe>(
            crate::resolver_core::resolver_context::capture_targets(self.ctx),
            &target,
            contributor_roots.len() as u32,
            augmenter_set.fingerprint,
        );

        Some(FoldedAugmentation::Contributions(
            AugmentationContributions {
                contributor_nodes,
                contributor_roots,
                source_env_unobservable,
                base_position,
                signature_groups,
                enum_blocks,
            },
        ))
    }

    /// Resolve a named ambient value export through the import value owner.
    /// Contributor-set and declaration observations join the active fact tracer.
    pub fn ambient_value_export_root(
        &self,
        importer: &str,
        specifier: &str,
        name: &str,
    ) -> Option<ResolvedRootIdentity> {
        let target = verter_session_query::inputs::shallow::ImportTarget {
            source_specifier: specifier.to_owned(),
            imported_name: name.to_owned(),
            is_namespace: false,
        };
        let (root, _) = self.ambient_import_member_root(importer, &target, &[])?;
        Some(ResolvedRootIdentity::new_in_owner(
            root.scope.canonical_id,
            root.scope.owner,
            root.name,
        ))
    }

    /// The declaration an import of an AMBIENT module names through `path`
    /// (see [`Self::qualified_value_member_root`]), and how many path
    /// segments it consumes: the binding's member of the first
    /// `declare module` block declaring it — `default` its `export default`
    /// declaration, an import assignment its `export = X` value, a namespace
    /// import's first segment the member it names — then the longest
    /// declared qualified member (`AN.f`) the rest of the path names.
    pub(super) fn ambient_import_member_root(
        &self,
        importer: &str,
        target: &verter_session_query::inputs::shallow::ImportTarget,
        path: &[verter_type_expr::OwnedStr],
    ) -> Option<(ValueRootKey, usize)> {
        let blocks = self.ambient_module_blocks(importer, &target.source_specifier);
        let (member, skipped): (Arc<str>, usize) = if target.is_import_equals() {
            let block = blocks
                .iter()
                .find(|block| block.export_assignment.is_some())?;
            let assigned = Arc::clone(block.export_assignment.as_ref()?);
            return self
                .ambient_block_declares_value(block, &assigned)
                .then(|| (block.root(assigned), 0));
        } else if target.is_namespace {
            (std::sync::Arc::<str>::from(path.first()?.as_str()), 1)
        } else {
            (Arc::from(target.imported_name.as_str()), 0)
        };
        blocks.iter().find_map(|block| {
            // A module assigned with `export = X` names X by `default` too
            // (TypeScript 7 always applies the interop).
            let name: Arc<str> = if member.as_ref() == "default" {
                Arc::clone(
                    block
                        .default_export
                        .as_ref()
                        .or(block.export_assignment.as_ref())?,
                )
            } else if let Some(assigned) = self.ambient_assigned_namespace(block) {
                Arc::from(format!("{assigned}.{member}"))
            } else {
                Arc::clone(&member)
            };
            let rest = &path[skipped..];
            let exported = |qualified: &str| {
                self.ctx
                    .ensure_indexed_ready_serve(block.canonical.as_ref())
                    .is_some_and(|serve| {
                        serve
                            .indexed
                            .shallow_state
                            .headers
                            .namespace_member_is_exported(block.owner, qualified)
                    })
            };
            (1..=rest.len())
                .rev()
                .find_map(|length| {
                    let mut qualified = name.to_string();
                    for segment in &rest[..length] {
                        qualified.push('.');
                        qualified.push_str(segment);
                    }
                    (self.ambient_block_declares_value(block, &qualified) && exported(&qualified))
                        .then(|| (block.root(Arc::from(qualified)), skipped + length))
                })
                .or_else(|| {
                    self.ambient_block_declares_value(block, &name)
                        .then(|| (block.root(Arc::clone(&name)), skipped))
                })
        })
    }

    /// The ambient declarations of the module `specifier` names when no
    /// file answers it — every `declare module "specifier" { … }` block of
    /// the program, in declaration precedence order. The augmenter set is observed onto the active
    /// tracer, so a block that appears, disappears or changes shape later
    /// misses every warm read that went through it, including a read that
    /// found no block.
    pub(super) fn ambient_module_blocks(
        &self,
        anchor: &str,
        specifier: &str,
    ) -> Vec<AmbientModuleBlock> {
        use verter_session_query::facts::registry::InternedSpecifier;
        use verter_session_query::resolution::AugmentationTargetKind;
        let scope =
            verter_session_query::declarations::AugmentationScopeKind::Module(specifier.to_owned());
        self.module_augmentation_blocks(
            anchor,
            AugmentationTargetKind::ExternalSpecifier(InternedSpecifier::from(specifier)),
            specifier,
            |_, block_scope| *block_scope == scope,
        )
    }

    /// The `declare module` blocks the augmentation index lists for
    /// `target`, filtered by `declares(augmenter, scope)`, in declaration
    /// precedence order, with the augmenter set observed onto the active
    /// tracer. `attribution` names the target in the shape fact.
    fn module_augmentation_blocks(
        &self,
        anchor: &str,
        target: verter_session_query::resolution::AugmentationTargetKind,
        attribution: &str,
        declares: impl Fn(&str, &verter_session_query::declarations::AugmentationScopeKind) -> bool,
    ) -> Vec<AmbientModuleBlock> {
        let (_, augmenter_set) = self.ctx.augmentation_index(target.clone());
        crate::resolver_core::resolver_context::observe_fan_out(
            verter_session_query::facts::fact_cache::FactVersionRef::RouteSurface(
                verter_session_query::facts::fact_cache::RouteSurfaceFactRef {
                    canonical_id: attribution.into(),
                    key: verter_session_query::source::augmentation_keys::build_module_augmentation_index_shape_fact_key(
                        &target,
                    ),
                    lane: verter_session_query::facts::FactLane::Semantic,
                    expected_hash: augmenter_set.fingerprint,
                },
            ),
        );
        let mut canonicals: Vec<Arc<str>> = augmenter_set
            .entries
            .iter()
            .map(|entry| Arc::clone(entry.canonical()))
            .collect();
        self.sort_in_program_order(
            anchor,
            &mut canonicals,
            |canonical| canonical,
            |_, _| std::cmp::Ordering::Equal,
        );
        canonicals.dedup();
        let mut blocks = Vec::new();
        for canonical in canonicals {
            let Some(indexed) = self
                .ctx
                .ensure_indexed_ready_serve(canonical.as_ref())
                .map(|serve| serve.indexed)
            else {
                continue;
            };
            for block in &indexed.shallow_state.headers.augmentation_blocks {
                if declares(canonical.as_ref(), &block.scope) {
                    blocks.push(AmbientModuleBlock {
                        canonical: Arc::clone(&canonical),
                        owner: block.owner,
                        scope: block.scope.clone(),
                        default_export: block.default_export.as_deref().map(Arc::from),
                        export_assignment: block.export_assignment.as_deref().map(Arc::from),
                    });
                }
            }
        }
        blocks
    }

    /// Whether the exact ambient module inventory declares a value or namespace.
    pub(super) fn ambient_block_declares_value(
        &self,
        block: &AmbientModuleBlock,
        name: &str,
    ) -> bool {
        self.ctx
            .ensure_indexed_ready_serve(block.canonical.as_ref())
            .is_some_and(|serve| {
                let headers = &serve.indexed.shallow_state.headers;
                headers
                    .augmentation_value_header_in(&block.scope, block.owner, name)
                    .is_some()
                    || headers
                        .augmentation_namespace_blocks
                        .iter()
                        .any(|(scope, namespace)| {
                            scope == &block.scope
                                && namespace.owner == block.owner
                                && namespace.qualified_name == name
                                && namespace.instantiated
                        })
            })
    }

    fn ambient_assigned_namespace(&self, block: &AmbientModuleBlock) -> Option<Arc<str>> {
        let assigned = block.export_assignment.as_ref()?;
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(block.canonical.as_ref())?
            .indexed;
        indexed
            .shallow_state
            .headers
            .augmentation_namespace_blocks
            .iter()
            .any(|(scope, namespace)| {
                scope == &block.scope
                    && namespace.owner == block.owner
                    && namespace.qualified_name == assigned.as_ref()
            })
            .then(|| Arc::clone(assigned))
    }

    /// Route an imported type through an ambient module's retained inventory.
    /// The imported spelling, rather than its local alias, selects the member.
    /// An assigned namespace contributes its exported qualified members under
    /// the module's own scope; no file-scope identity is fabricated for them.
    pub(super) fn external_module_type_target(
        &self,
        importer: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
    ) -> Option<(String, String)> {
        use verter_session_query::inputs::shallow::LexicalValueBinding;

        let indexed = self.ctx.ensure_indexed_ready_serve(importer)?.indexed;
        let (head, rest) = name.split_once('.').unwrap_or((name, ""));
        let LexicalValueBinding::Import(target) =
            indexed.shallow_state.visible_value_binding(owner, head)?
        else {
            return None;
        };
        let member = if target.is_namespace || target.is_import_equals() {
            if rest.is_empty() {
                return None;
            }
            rest.to_owned()
        } else if rest.is_empty() {
            target.imported_name.clone()
        } else {
            format!("{}.{rest}", target.imported_name)
        };
        let blocks = self.ambient_module_blocks(importer, &target.source_specifier);
        let assigned = blocks.iter().find_map(|block| {
            self.ambient_assigned_namespace(block)
                .map(|assigned| format!("{assigned}.{member}"))
        });
        let decl_name = assigned.unwrap_or(member);
        let declared = blocks.iter().any(|block| {
            self.ctx
                .ensure_indexed_ready_serve(block.canonical.as_ref())
                .is_some_and(|serve| {
                    let headers = &serve.indexed.shallow_state.headers;
                    headers
                        .augmentation_type_header_in(&block.scope, block.owner, &decl_name)
                        .is_some()
                        && headers.namespace_member_is_exported(block.owner, &decl_name)
                })
        });
        declared.then(|| (target.source_specifier.clone(), decl_name))
    }

    /// Preserve the retained namespace block addressing an ambient body.
    /// The namespace address is an ordinal in `augmentation_namespace_blocks`,
    /// pinned by the scope's owner and whole-file hash; it holds no siblings.
    pub(super) fn augmentation_body_scope(
        mut scope: NodeScopeId,
        headers: &verter_session_query::declarations::header_index::DeclHeaderIndex,
        augmentation: &verter_session_query::declarations::AugmentationScopeKind,
        symbol: &str,
    ) -> NodeScopeId {
        let NodeScopeId::File {
            owner, local_scope, ..
        } = &mut scope
        else {
            return scope;
        };
        if !matches!(
            augmentation,
            verter_session_query::declarations::AugmentationScopeKind::Module(_)
        ) {
            return scope;
        }
        let span = headers
            .augmentation_type_header_in(augmentation, *owner, symbol)
            .map(|header| header.span)
            .or_else(|| {
                headers
                    .augmentation_value_header_in(augmentation, *owner, symbol)
                    .map(|header| header.span)
            });
        let Some((prefix, _)) = symbol.rsplit_once('.') else {
            *local_scope = headers
                .augmentation_blocks
                .iter()
                .position(|block| {
                    &block.scope == augmentation
                        && block.owner == *owner
                        && span.is_some_and(|span| {
                            block.span.start <= span.start && span.end <= block.span.end
                        })
                })
                .and_then(|ordinal| u32::try_from(ordinal).ok())
                .map(NodeLocalScopeId::AugmentationModule);
            return scope;
        };
        *local_scope = headers
            .augmentation_namespace_blocks
            .iter()
            .position(|(kind, block)| {
                kind == augmentation
                    && block.owner == *owner
                    && block.qualified_name == prefix
                    && span.is_some_and(|span| {
                        block.span.start <= span.start && span.end <= block.span.end
                    })
            })
            .and_then(|ordinal| u32::try_from(ordinal).ok())
            .map(NodeLocalScopeId::AugmentationNamespace);
        scope
    }

    /// A lexical type reference in an ambient namespace, before file/import
    /// lookup. Walk enclosing namespaces within the exact module inventory;
    /// a private sibling is visible here even when imports cannot name it.
    pub(super) fn ambient_namespace_type_target(
        &self,
        scope: &NodeScopeId,
        name: &str,
    ) -> Option<(String, String)> {
        self.ambient_namespace_target(scope, name, GlobalSpace::Type)
    }

    pub(super) fn ambient_namespace_target(
        &self,
        scope: &NodeScopeId,
        name: &str,
        space: GlobalSpace,
    ) -> Option<(String, String)> {
        use verter_session_query::declarations::AugmentationScopeKind;
        let NodeScopeId::File {
            canonical_id,
            owner,
            whole_hash,
            local_scope: Some(local_scope),
        } = scope
        else {
            return None;
        };
        if matches!(local_scope, NodeLocalScopeId::Lexical(_)) {
            return None;
        }
        let indexed = self
            .ctx
            .ensure_indexed_ready_serve(canonical_id.as_ref())?
            .indexed;
        if indexed.whole_hash != *whole_hash {
            return None;
        }
        let headers = &indexed.shallow_state.headers;
        let (augmentation, scope_owner, mut prefix) = match local_scope {
            NodeLocalScopeId::AugmentationNamespace(ordinal) => {
                let (augmentation, block) = headers
                    .augmentation_namespace_blocks
                    .get(*ordinal as usize)?;
                (augmentation, block.owner, block.qualified_name.as_str())
            }
            NodeLocalScopeId::AugmentationModule(ordinal) => {
                let block = headers.augmentation_blocks.get(*ordinal as usize)?;
                (&block.scope, block.owner, "")
            }
            NodeLocalScopeId::Lexical(_) => return None,
        };
        let AugmentationScopeKind::Module(specifier) = augmentation else {
            return None;
        };
        if scope_owner != *owner {
            return None;
        }
        loop {
            let qualified = if prefix.is_empty() {
                name.to_owned()
            } else {
                format!("{prefix}.{name}")
            };
            let declared = match space {
                GlobalSpace::Type => headers
                    .augmentation_type_header_in(augmentation, *owner, &qualified)
                    .is_some(),
                GlobalSpace::Value => {
                    headers
                        .augmentation_value_header_in(augmentation, *owner, &qualified)
                        .is_some()
                        || headers
                            .augmentation_namespace_blocks
                            .iter()
                            .any(|(kind, namespace)| {
                                kind == augmentation
                                    && namespace.owner == *owner
                                    && namespace.qualified_name == qualified
                            })
                }
            };
            if declared {
                return Some((specifier.clone(), qualified));
            }
            if prefix.is_empty() {
                return None;
            }
            prefix = prefix.rsplit_once('.').map_or("", |(parent, _)| parent);
        }
    }

    /// Resolve a type name imported from a NON-FILE (external / ambient)
    /// module specifier through `declare module "<spec>" { ... }` augmentation.
    ///
    /// This is the canonical Vue/Vite `vite/client` pattern: a virtual module
    /// `"<spec>"` is declared and/or augmented across one or more files, none of
    /// which is a workspace FILE the specifier resolves to. The imported name
    /// therefore has no file-scope declaration and `resolve_bare_name_in_scope`
    /// returns `None`. Every contributing `declare module "<spec>"` block is a
    /// PEER (TS merges them with no base-vs-augmenter distinction), so the merged
    /// surface is built PURELY from the `ExternalSpecifier(spec)` augmentation
    /// index — there is NO base body. Folding routes through the SAME
    /// [`Self::collect_augmentation_contributions`] augmenter path + `MergedDecl`
    /// peer-merge carrier the relative stitch uses (one merge engine, no source
    /// scan).
    ///
    /// Returns `None` when no `declare module` block contributes `name`.
    /// The caller retains an unresolved carrier or returns a typed miss,
    /// according to the projection mode. A relative / wildcard / global specifier is
    /// excluded by `augmenter_matches_target`'s `ExternalSpecifier` arm, so the
    /// index scan returns empty and this yields `None`.
    pub(super) fn resolve_external_module_augmentation(
        &self,
        specifier: &str,
        name: &str,
        type_arguments: &[SemanticNodeId],
        scope: &NodeScopeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        use verter_session_query::facts::registry::InternedSpecifier;
        use verter_session_query::resolution::AugmentationTargetKind;

        let NodeScopeId::File { canonical_id, .. } = scope else {
            return None;
        };
        let scope_canonical = canonical_id.as_ref();

        // Contributor discovery for ambient external modules is the
        // ingestion-time global contributor population: a program-root
        // `.d.ts` that nothing imports is recorded when its `IndexedReady`
        // publishes, so lookup does not scan program membership.
        let target = AugmentationTargetKind::ExternalSpecifier(InternedSpecifier::from(specifier));
        let AugmentationContributions {
            contributor_nodes,
            // The external path DISCARDS the returned `contributor_roots`
            // (the relative stitch folds them into the enclosing
            // `instantiate_shell` output's `observed_self_roots`; there is no
            // such per-base output here — the carrier is interned mid-reference
            // resolution and returned as a bare node). This is COMPENSATED, not
            // a hole: `collect_augmentation_contributions` ALREADY observed each
            // folded contributor's `FileWholeHash` + `FileSourceEnv` onto the
            // active fact tracer (the enclosing `Instantiate` read-set), so a
            // contributor content edit OR source-env move rejects the warm
            // parent through the strict per-contributor reject rail — proven
            // end-to-end by
            // `cross_file_augmentation_merge_equivalence_tests::external_module_augmentation_warm_parent_rejects_contributor_content_edit_end_to_end`.
            contributor_roots: _,
            source_env_unobservable,
            base_position: _,
            signature_groups: _,
            enum_blocks: _,
        } = self.collect_augmentation_contributions(
            AugmentationContribution::TypeBody,
            target,
            name,
            type_arguments,
            context,
            scope_canonical,
            None,
        )?;
        // A torn contributor (unobservable source-env identity — a
        // torn/unhealable/unservable augmenter) is SERVED but must NEVER be
        // warm-admitted. This carrier is interned mid-reference-resolution and
        // returned as a bare node, so it owns no `QueryBuildOutput` of its own;
        // fold the no-warm signal into the ENCLOSING cold build's local taint
        // frame — the SAME semantic `QueryBuildOutput.cache_suppress` rail the
        // relative stitch uses (`instantiate_shell` sets `output.cache_suppress`
        // from the collector's `source_env_unobservable`). That is the rail memo
        // admission actually consults; it also reaches the evaluator-scoped
        // carrier observation frame when this augmentation resolves under a
        // carrier subject. An unobservable source-env is a VALID (Complete)
        // but non-cacheable serve: fold ONLY `cache_suppress` (the
        // `(false, true)` classification), NEVER the request-partial rail —
        // marking partiality here would false-`Partial` a complete result. The
        // completion fence separately covers a mid-flight torn contributor
        // (revalidate-before-publish).
        //
        // ALSO fan the generalized non-cacheability onto every active tracer:
        // the build-local fold marks only the enclosing build's frame, but the
        // component-meta entry's admission consults its OWN fact tracer's
        // `non_cacheable_read_observed` bit — the rail that (with the
        // request-partial mark removed here) now carries the torn-augmenter
        // refusal to the component-meta warm gate WITHOUT false-`Partial`ing it.
        if source_env_unobservable {
            self.fold_into_top_build_local_taint(false, true);
            crate::fact_tracing::note_non_cacheable_read_fan_out(
                verter_session_query::facts::reuse::NonCacheableReadReason::UnobservableSource,
            );
        }
        // A tainted-EMPTY collection (augmenters targeted the specifier but were
        // all unobservable) produces no body: the taint is already folded, so
        // fall through to the caller's `Opaque(Miss)` sentinel WITHOUT
        // synthesising a false zero-contributor `MergedDecl`.
        if contributor_nodes.is_empty() {
            return None;
        }
        // A type alias contributes its actual type, which may be a scalar or
        // a reference. Peer surface merging applies only to multiple bodies.
        if contributor_nodes.len() == 1 {
            return Some(contributor_nodes[0]);
        }

        // Peer-merge carrier from the augmenter contributions ONLY (no base
        // body): every `declare module "<spec>"` block is a peer. The carrier is
        // interned in the importing file's scope so its surface projects in the
        // caller's context; the per-augmenter `FileWholeHash` facts the folder
        // observed onto the active tracer are the cache-validity rail (each
        // contributor's `MergedDecl` reduction validates on those facts).
        let merged = self.graph().intern_node_with_scope(
            SemanticNodeData::MergedDecl {
                contributors: crate::semantic_query::PayloadArray::from(
                    contributor_nodes.into_boxed_slice(),
                ),
            },
            scope.clone(),
        );
        Some(merged)
    }

    /// Sort `items` into declaration precedence among program files: the
    /// file order of `anchor`'s program (or, when no configured project
    /// owns `anchor`, of the canonically first item one does), then
    /// canonical spelling, then `then`. The program order is read — and
    /// observed onto the active tracer — only when the items span two or
    /// more program files; the sort is stable, so one file's items keep
    /// their source order.
    pub(super) fn sort_in_program_order<T>(
        &self,
        anchor: &str,
        items: &mut [T],
        canonical: impl Fn(&T) -> &str,
        then: impl Fn(&T, &T) -> std::cmp::Ordering,
    ) {
        if !verter_session_query::inputs::program_order::orders_across_files(
            items.iter().map(&canonical),
        ) {
            items.sort_by(|left, right| {
                canonical(left)
                    .cmp(canonical(right))
                    .then_with(|| then(left, right))
            });
            return;
        }
        let order = self
            .ctx
            .program_file_order(anchor, &mut items.iter().map(&canonical));
        crate::resolver_core::resolver_context::observe_program_file_order(&order);
        items.sort_by(|left, right| {
            order
                .rank(canonical(left))
                .cmp(&order.rank(canonical(right)))
                .then_with(|| canonical(left).cmp(canonical(right)))
                .then_with(|| then(left, right))
        });
    }

    /// The program's contributors to the global `name` in `space`, with the
    /// global contributor population observed onto the active fact tracer:
    /// a contributor added, removed or reordered misses every warm read that
    /// named the global through them — including a read that found none.
    pub(super) fn global_contributors_in(
        &self,
        demand_canonical: &str,
        name: &str,
        space: verter_session_query::facts::SymbolSpace,
    ) -> verter_session_query::inputs::contributors::SymbolContributors {
        use verter_session_query::resolution::AugmentationTargetKind;
        let target = AugmentationTargetKind::GlobalAugmentation;
        let answer = self
            .ctx
            .global_contributor_answer(demand_canonical, name, space);
        crate::resolver_core::resolver_context::observe_fan_out(
            verter_session_query::facts::fact_cache::FactVersionRef::RouteSurface(
                verter_session_query::facts::fact_cache::RouteSurfaceFactRef {
                    canonical_id: Arc::default(),
                    key:
                        verter_session_query::inputs::contributors::population_contributor_fact_key(
                            &target, name,
                        ),
                    lane: verter_session_query::facts::FactLane::Semantic,
                    expected_hash: answer.population_fingerprint,
                },
            ),
        );
        answer.contributors
    }

    /// The declaration of the global `name` in `space` that the library of
    /// `demand_canonical`'s project holds — the environment a checker reads
    /// from its `lib` files, whose declarations precede every program file
    /// in declaration order. Consulting the library records the consumer's
    /// dependency on it, so re-registering the library misses every warm
    /// read that named the global through it. `None` when the project
    /// registers no library, or none that declares `name` in `space`.
    ///
    /// Every reader of a library global asks this one lookup: an authored
    /// global reference, a `typeof` of a global value, a primitive's
    /// apparent wrapper and the builtin availability check. It reads the
    /// project's symbol index and the declaring library's header index,
    /// never the library's declarations.
    pub(super) fn lib_global_declaration(
        &self,
        demand_canonical: &str,
        name: &str,
        space: GlobalSpace,
    ) -> Option<ResolvedRootIdentity> {
        let project = self.project_stable_key_for_canonical(demand_canonical)?;
        let identity = crate::resolver_core::ambient_resolve::resolve_ambient_global(
            self.ctx,
            demand_canonical,
            project,
            name,
            match space {
                GlobalSpace::Type => crate::resolver_core::request_ports::AmbientSymbolSpace::Type,
                GlobalSpace::Value => {
                    crate::resolver_core::request_ports::AmbientSymbolSpace::Value
                }
            },
        )?;
        // A library the view cannot serve is still the declaring file: the
        // read of its declaration that follows fails as that read does.
        let Some(indexed) = self
            .ctx
            .ensure_indexed_ready_serve(identity.canonical_id.as_ref())
            .map(|serve| serve.indexed)
        else {
            return Some(identity);
        };
        let headers = &indexed.shallow_state.headers;
        let declared = match space {
            GlobalSpace::Type => headers.type_header_in(identity.owner, name).is_some(),
            GlobalSpace::Value => headers.value_header_in(identity.owner, name).is_some(),
        };
        declared.then_some(identity)
    }

    /// The identity of the merged GLOBAL declaration named `name` that a
    /// reference in `demand_canonical` reads: its FIRST declaration in
    /// declaration precedence order — the project's library
    /// ([`Self::lib_global_declaration`]), then the program's files in
    /// program file order, then by canonical path — among every
    /// module's `declare global` contribution and every script's file-scope
    /// interface, each addressed by its global identity
    /// ([`Self::global_contribution_identity`]). `None` when none
    /// declares such a global type.
    ///
    /// A `declare global` block in a SCRIPT is an error that binds nothing.
    /// The declaration's `Instantiate` folds in every later declaration.
    pub(super) fn first_global_declaration(
        &self,
        demand_canonical: &str,
        name: &str,
    ) -> Option<ResolvedRootIdentity> {
        if let Some(lib) = self.lib_global_declaration(demand_canonical, name, GlobalSpace::Type) {
            return Some(lib);
        }
        let population = self.global_contributors_in(
            demand_canonical,
            name,
            verter_session_query::facts::SymbolSpace::Type,
        );
        let first = population
            .entries
            .iter()
            .find(|entry| declares_global_type(entry))?;
        Some(self.global_contribution_identity(first, name))
    }

    /// Whether `(canonical, owner, name)` addresses ONE declaration of the
    /// merged GLOBAL type `name` a reference in `demand_canonical` reads —
    /// a declaration of the project's library, a module's `declare global`
    /// contribution or a script's file-scope declaration — not only the
    /// first of them ([`Self::first_global_declaration`]): every one of
    /// them declares the same global symbol, and every library that
    /// declares it is one of them.
    pub(super) fn is_global_type_declaration(
        &self,
        demand_canonical: &str,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
    ) -> bool {
        use verter_session_query::inputs::contributors::{ContributorOrigin, FileModuleKind};
        if self
            .lib_global_declaration(demand_canonical, name, GlobalSpace::Type)
            .is_some_and(|lib| lib.canonical_id.as_ref() == canonical && lib.owner == owner)
        {
            return true;
        }
        let population = self.global_contributors_in(
            demand_canonical,
            name,
            verter_session_query::facts::SymbolSpace::Type,
        );
        population.entries.iter().any(|entry| {
            entry.artifact_key.canonical.as_ref() == canonical
                && (declares_global_type(entry)
                    || (entry.is_automatic_lib
                        && entry.module_kind == FileModuleKind::Script
                        && matches!(
                            entry.origin,
                            ContributorOrigin::FileScopeInterface
                                | ContributorOrigin::FileScopeType
                        )))
                && self.global_contribution_identity(entry, name).owner == owner
        })
    }

    /// The identity that addresses the global contributor `entry`'s
    /// contribution to the GLOBAL type `name`: `(canonical, owner, name)`,
    /// except for a module's `declare global` contribution when the module
    /// also binds the name in module scope, by a type of its own or an
    /// import — that identity names the module-scope binding, which the
    /// module's own references (and its importers) read — whose
    /// contribution is addressed by the owner's
    /// [`TopLevelOwnerId::global_augmentation`] scope instead.
    ///
    /// [`TopLevelOwnerId::global_augmentation`]: verter_type_expr::TopLevelOwnerId::global_augmentation
    fn global_contribution_identity(
        &self,
        entry: &verter_session_query::inputs::contributors::ContributorEntry,
        name: &str,
    ) -> ResolvedRootIdentity {
        let shadowed = entry.origin
            == verter_session_query::inputs::contributors::ContributorOrigin::DeclareGlobal
            && self
                .ctx
                .ensure_indexed_ready_serve(entry.artifact_key.canonical.as_ref())
                .is_some_and(|serve| {
                    serve
                        .indexed
                        .shallow_state
                        .binds_module_scope_type_in(entry.owner, name)
                });
        ResolvedRootIdentity::new_in_owner(
            Arc::clone(&entry.artifact_key.canonical),
            if shadowed {
                entry.owner.global_augmentation()
            } else {
                entry.owner
            },
            name,
        )
    }

    /// Whether the declaration `(canonical, owner, name)` a reference in
    /// `demand_canonical` resolves to is the contextual-this marker: a
    /// declaration of the GLOBAL `ThisType`, whichever of its declarations
    /// it is ([`Self::is_global_type_declaration`]). The checker identifies
    /// the marker by the merged global symbol, so a module-scope
    /// `ThisType` is an ordinary type.
    pub(in crate::project_semantic_dispatch) fn names_contextual_this_marker(
        &self,
        demand_canonical: &str,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
    ) -> bool {
        name == "ThisType"
            && self.is_global_type_declaration(demand_canonical, canonical, owner, name)
    }

    /// The declaration-scope payload the body of the declaration
    /// `decl_name` of `canonical`'s `owner` resolves its names in. A
    /// script's namespace block is a block of the GLOBAL namespace, so a
    /// declaration it declares also reads the members other scripts'
    /// blocks of its enclosing namespaces contribute
    /// ([`DeclarationScopePayload::within_global_namespace`]).
    pub(super) fn declaration_scope_payload(
        &self,
        bundle: &impl crate::resolver_core::bare_name_resolve::PreparedInputSource,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        decl_name: &str,
    ) -> crate::resolver_core::bare_name_resolve::DeclarationScopePayload {
        let payload = crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
            bundle, owner,
        );
        match decl_name.rsplit_once('.') {
            Some((namespace, _))
                if owner == verter_type_expr::TopLevelOwnerId::ordinary_file()
                    && !self.canonical_is_module(canonical) =>
            {
                payload.within_global_namespace(verter_type_expr::OwnedStr::from(namespace))
            }
            _ => payload,
        }
    }

    /// The type a name written in a block of the global namespace
    /// `namespace` names as a member of an enclosing namespace:
    /// `{N}.{name}` for each namespace `N` enclosing the block, innermost
    /// first (`A.B`, then `A`), whichever script's block of `N` exports it
    /// ([`Self::global_namespace_type_declaration`], which observes the
    /// namespace's contributors). The walk stops before `outer_bound`, the
    /// namespace whose member the declaration's own scope already binds the
    /// name to, so only a more inner namespace's member shadows it. `None`
    /// when no enclosing namespace declares the name.
    pub(super) fn enclosing_namespace_type_member(
        &self,
        demand_canonical: &str,
        namespace: &str,
        name: &str,
        outer_bound: Option<&str>,
    ) -> Option<ResolvedRootIdentity> {
        let mut current = Some(namespace);
        while let Some(prefix) = current {
            if outer_bound == Some(prefix) {
                return None;
            }
            if let Some(member) = self
                .global_namespace_type_declaration(demand_canonical, &format!("{prefix}.{name}"))
            {
                return Some(member);
            }
            current = prefix.rsplit_once('.').map(|(outer, _)| outer);
        }
        None
    }

    /// The qualified value a `typeof` path written in a block of the global
    /// namespace `namespace` heads as a member of an enclosing namespace,
    /// with the number of path segments it consumes: for each namespace
    /// `N` enclosing the block, innermost first, the longest prefix of the
    /// path that `{N}.{prefix}` names a global value of
    /// ([`Self::global_value_declarations`]). The walk stops before
    /// `outer_bound`, the namespace whose member the declaration's own scope
    /// already binds the path's head to, so only a more inner namespace's
    /// member shadows it. `None` when no enclosing namespace declares such a
    /// value.
    pub(super) fn enclosing_namespace_value_root(
        &self,
        demand_canonical: &str,
        namespace: &str,
        path: &[String],
        outer_bound: Option<&str>,
    ) -> Option<(verter_type_expr::OwnedStr, usize)> {
        let mut current = Some(namespace);
        while let Some(prefix) = current {
            if outer_bound == Some(prefix) {
                return None;
            }
            let mut qualified = String::from(prefix);
            let mut candidates = Vec::with_capacity(path.len());
            for segment in path {
                qualified.push('.');
                qualified.push_str(segment);
                candidates.push(qualified.clone());
            }
            for (index, candidate) in candidates.iter().enumerate().rev() {
                if self
                    .global_value_declarations(demand_canonical, candidate)
                    .is_some_and(|declarations| !declarations.is_empty())
                {
                    return Some((
                        verter_type_expr::OwnedStr::from(candidate.as_str()),
                        index + 1,
                    ));
                }
            }
            current = prefix.rsplit_once('.').map(|(outer, _)| outer);
        }
        None
    }

    /// The declaration the qualified type name `name` (`Ns.T`,
    /// `Ns.Inner.T`) names through the GLOBAL namespace its head names: the
    /// member a script's top-level namespace of that name exports, the first
    /// in declaration precedence order. `None` when no script's namespace
    /// declares it.
    pub(super) fn global_namespace_type_declaration(
        &self,
        demand_canonical: &str,
        name: &str,
    ) -> Option<ResolvedRootIdentity> {
        use verter_session_query::inputs::contributors::{ContributorOrigin, FileModuleKind};
        let (head, _) = name.split_once('.')?;
        let population = self.global_contributors_in(
            demand_canonical,
            head,
            verter_session_query::facts::SymbolSpace::Namespace,
        );
        let mut declarations: Vec<&verter_session_query::inputs::contributors::ContributorEntry> =
            population
                .entries
                .iter()
                .filter(|entry| {
                    !entry.is_automatic_lib
                        && entry.origin == ContributorOrigin::FileScopeNamespace
                        && entry.module_kind == FileModuleKind::Script
                })
                .collect();
        self.sort_in_program_order(
            demand_canonical,
            &mut declarations,
            |entry| entry.artifact_key.canonical.as_ref(),
            |_, _| std::cmp::Ordering::Equal,
        );
        declarations.into_iter().find_map(|entry| {
            let indexed = self
                .ctx
                .ensure_indexed_ready_serve(entry.artifact_key.canonical.as_ref())?
                .indexed;
            let headers = &indexed.shallow_state.headers;
            (headers.type_header_in(entry.owner, name).is_some()
                && headers.namespace_member_is_exported(entry.owner, name))
            .then(|| {
                ResolvedRootIdentity::new_in_owner(
                    Arc::clone(&entry.artifact_key.canonical),
                    entry.owner,
                    name,
                )
            })
        })
    }

    /// The GLOBAL value declaration named `name` that a reference in
    /// `demand_canonical` reads — the project's library declaration, a
    /// module's `declare global { var / let / const / function / class }`
    /// member or a script's file-scope value — with its declaration kind:
    /// the first of [`Self::global_value_declarations`].
    pub(super) fn global_value_declaration(
        &self,
        demand_canonical: &str,
        name: &str,
    ) -> Option<(
        ResolvedRootIdentity,
        verter_session_query::declarations::ValueDeclKind,
    )> {
        self.global_value_declarations(demand_canonical, name)?
            .into_iter()
            .next()
    }

    /// Every declaration of the GLOBAL value `name` a reference in
    /// `demand_canonical` reads, in declaration precedence order — the
    /// project's library ([`Self::lib_global_declaration`]) before the
    /// program's files — each with its kind. A `var` declared in several
    /// files is ONE variable whose type is its first declaration's (the
    /// checker requires every later declaration to repeat it, TS2403), so
    /// only that one is listed; a function declared in several files is
    /// one function whose overloads are every file's, so all are; an enum
    /// declared in several files is one enum, listed by its first
    /// declaration, which carries every file's members. `None`
    /// when neither declares such a global value, or when this lane cannot
    /// address it:
    ///
    /// - declarations of other kinds, or of mixed kinds, span more than
    ///   one file: a block-scoped global declared twice is the checker's
    ///   TS2451;
    /// - a declaration listed is a module's `declare global` one while the
    ///   module also declares a module-scope value of the same name, which
    ///   the identity `(module, name)` addresses instead. (An enum or a
    ///   `var` listed by an earlier declaration still reads it: an enum's
    ///   blocks are assembled in their own declaration scopes.)
    ///
    /// A `declare global` block in a SCRIPT binds nothing.
    pub(super) fn global_value_declarations(
        &self,
        demand_canonical: &str,
        name: &str,
    ) -> Option<
        Vec<(
            ResolvedRootIdentity,
            verter_session_query::declarations::ValueDeclKind,
        )>,
    > {
        use verter_session_query::declarations::ValueDeclKind;
        use verter_session_query::inputs::contributors::{ContributorOrigin, FileModuleKind};
        let lib = self
            .lib_global_declaration(demand_canonical, name, GlobalSpace::Value)
            .and_then(|identity| {
                let indexed = self
                    .ctx
                    .ensure_indexed_ready_serve(identity.canonical_id.as_ref())?
                    .indexed;
                let kind = indexed
                    .shallow_state
                    .headers
                    .value_header_in(identity.owner, name)?
                    .kind;
                Some((identity, kind))
            });
        let population = self.global_contributors_in(
            demand_canonical,
            name,
            verter_session_query::facts::SymbolSpace::Value,
        );
        // Each declaration with its kind, and whether its identity would
        // address the declaring module's own value of the name instead.
        let mut declarations: Vec<(
            &verter_session_query::inputs::contributors::ContributorEntry,
            ValueDeclKind,
            bool,
        )> = Vec::new();
        for entry in population.entries.iter() {
            let declares = !entry.is_automatic_lib
                && match entry.origin {
                    ContributorOrigin::DeclareGlobal => entry.module_kind == FileModuleKind::Module,
                    ContributorOrigin::FileScopeValue => true,
                    ContributorOrigin::FileScopeInterface
                    | ContributorOrigin::FileScopeNamespace
                    | ContributorOrigin::FileScopeType
                    | ContributorOrigin::ModuleAugmentation => false,
                };
            if !declares {
                continue;
            }
            let indexed = self
                .ctx
                .ensure_indexed_ready_serve(&entry.artifact_key.canonical)?
                .indexed;
            let headers = &indexed.shallow_state.headers;
            let (kind, shadowed) = if entry.origin == ContributorOrigin::FileScopeValue {
                (headers.value_header_in(entry.owner, name)?.kind, false)
            } else {
                (
                    headers
                        .augmentation_value_header_in(
                            &verter_session_query::declarations::AugmentationScopeKind::Global,
                            entry.owner,
                            name,
                        )?
                        .kind,
                    indexed.shallow_state.has_value_symbol_in(entry.owner, name),
                )
            };
            declarations.push((entry, kind, shadowed));
        }
        self.sort_in_program_order(
            demand_canonical,
            &mut declarations,
            |(entry, _, _)| entry.artifact_key.canonical.as_ref(),
            |(left, _, _), (right, _, _)| left.parse_stable_hash.cmp(&right.parse_stable_hash),
        );
        let mut declarations: Vec<(ResolvedRootIdentity, ValueDeclKind, bool)> = lib
            .map(|(identity, kind)| (identity, kind, false))
            .into_iter()
            .chain(declarations.into_iter().map(|(entry, kind, shadowed)| {
                (
                    ResolvedRootIdentity::new_in_owner(
                        Arc::clone(&entry.artifact_key.canonical),
                        entry.owner,
                        name,
                    ),
                    kind,
                    shadowed,
                )
            }))
            .collect();
        let first = declarations.first()?.0.canonical_id.clone();
        let spans_files = declarations
            .iter()
            .any(|(identity, _, _)| identity.canonical_id != first);
        if spans_files {
            let is_function = |kind: &ValueDeclKind| {
                matches!(kind, ValueDeclKind::Function | ValueDeclKind::AsyncFunction)
            };
            // An enum declared in several files is ONE enum too, whose
            // first declaration carries every file's members
            // (`enum_blocks`).
            if declarations
                .iter()
                .all(|(_, kind, _)| *kind == ValueDeclKind::Var)
                || declarations
                    .iter()
                    .all(|(_, kind, _)| *kind == ValueDeclKind::Enum)
            {
                declarations.truncate(1);
            } else if !declarations.iter().all(|(_, kind, _)| is_function(kind)) {
                return None;
            }
        }
        if declarations.iter().any(|(_, _, shadowed)| *shadowed) {
            return None;
        }
        Some(
            declarations
                .into_iter()
                .map(|(identity, kind, _)| (identity, kind))
                .collect(),
        )
    }

    /// The global `TemplateStringsArray` type — a tagged template's first
    /// argument — read from `canonical`'s `owner` scope
    /// ([`Self::global_named_type`]).
    pub(super) fn global_template_strings_array(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
    ) -> Option<SemanticNodeId> {
        self.global_named_type(canonical, owner, "TemplateStringsArray")
    }

    /// The GLOBAL type named `name` a compiler-internal operation reads (the
    /// template strings array, the symbol constructor the iterator protocol
    /// keys by), read from `canonical`'s `owner` scope.
    ///
    /// The checker reads its GLOBAL type, so a same-named declaration or
    /// import in the operation's own scope does not rename it. A scope that
    /// binds no such name resolves the bare reference exactly like an
    /// authored reference to the global (the program's global declaration,
    /// else the unresolved lib carrier every reference in the scope
    /// shares); a scope that shadows it reads the program's global
    /// declaration from its own file, and has no answer when the program
    /// declares none.
    pub(super) fn global_named_type(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &'static str,
    ) -> Option<SemanticNodeId> {
        let reference = verter_type_expr::TypeExpr::Ref {
            name: Arc::from(name),
            type_arguments: Arc::from(Vec::new().into_boxed_slice()),
        };
        let payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
            crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                &bundle, owner,
            )
        });
        let shadowed = crate::resolver_core::bare_name_resolve::resolve_bare_name_in_scope(
            self.ctx,
            self,
            canonical,
            owner,
            payload.as_ref(),
            name,
        )
        .is_some();
        let global;
        let (scope_canonical, scope_owner) = if shadowed {
            global = self.first_global_declaration(canonical, name)?;
            (global.canonical_id.as_ref(), global.owner)
        } else {
            (canonical, owner)
        };
        self.lower_type_expr_in_owner_scope_with_mode(
            scope_canonical,
            scope_owner,
            &reference,
            crate::semantic_query::ProjectionMode::Navigate,
        )
    }

    /// Whether the TYPE declaration `name` in `canonical` is (one
    /// declaration of) a GLOBAL declaration: a `declare global` interface
    /// of a module that binds the name in no module scope (no type, no
    /// import), or that its owner's global-augmentation scope addresses, or
    /// a file-scope interface of a script. Every other declaration of the
    /// same global lives in another file, and its `Instantiate` folds them
    /// in.
    fn declares_global_interface(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
        kind: verter_session_query::declarations::TypeDeclKind,
    ) -> bool {
        if kind != verter_session_query::declarations::TypeDeclKind::Interface {
            return false;
        }
        if owner.is_global_augmentation() {
            return self
                .transaction_indexed_record(canonical)
                .is_some_and(|indexed| {
                    indexed
                        .shallow_state
                        .declares_global_augmentation_type_in(owner, name)
                });
        }
        if owner != verter_type_expr::TopLevelOwnerId::ordinary_file() {
            return false;
        }
        let Some(indexed) = self.transaction_indexed_record(canonical) else {
            return false;
        };
        let shallow = &indexed.shallow_state;
        match verter_session_query::inputs::contributors::classify_shallow_module_kind(
            &indexed.shallow_state,
        ) {
            verter_session_query::inputs::contributors::FileModuleKind::Module => {
                !shallow.binds_module_scope_type_in(owner, name)
                    && shallow.has_global_augmentation(name)
            }
            verter_session_query::inputs::contributors::FileModuleKind::Script => {
                shallow.has_type_symbol_in(owner, name)
            }
        }
    }

    /// Bind a prepared declaration's type parameters for one application,
    /// in declaration order: the supplied argument at each position, else
    /// the parameter's declared DEFAULT, else whatever `unbound` supplies
    /// (`None` leaves the parameter unbound).
    ///
    /// A default is a content-free locator of the authored `T = D`
    /// position, lowered through the ONE located body source in the
    /// declaration's scope. The prior-sibling PREFIX params re-derive the
    /// bound's own binder frame, and the arguments bound so far substitute
    /// an earlier parameter the default names — `<T, U = T[]>` applied to
    /// `number` binds `U` to `number[]`. The full
    /// `ProjectionReductionContext` propagates so a `StructuralTransit`
    /// instantiation survives; provenance downgrades to structural — a
    /// type-parameter default is a substituted value, not the macro-T own
    /// body.
    ///
    /// Returns the binding environment by parameter name and each
    /// parameter's binding in declaration order.
    fn bind_declared_type_arguments(
        &self,
        prepared: &PreparedTypeDecl,
        args: &[SemanticNodeId],
        binding_scope: &DeclarationBindingScope<'_>,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
        mut unbound: impl FnMut(
            usize,
            &verter_type_expr::facts::NarrowTypeParam,
        ) -> Option<SemanticNodeId>,
    ) -> (
        FxHashMap<String, SemanticNodeId>,
        Vec<Option<SemanticNodeId>>,
    ) {
        let mut env: FxHashMap<String, SemanticNodeId> = FxHashMap::default();
        let mut bindings = Vec::with_capacity(prepared.type_parameters.len());
        for (index, param) in prepared.type_parameters.iter().enumerate() {
            let binding = match (args.get(index).copied(), param.default.as_ref()) {
                (Some(explicit), _) => Some(explicit),
                (None, Some(default)) => Some(self.lower_located_body_with_resolution_debt(
                    scoped_type_body_locator(default, binding_scope.augmentation),
                    prepared.kind,
                    &prepared.type_parameters[..index],
                    &prepared.name_resolution,
                    &env,
                    binding_scope.scope,
                    binding_scope.scope_payload,
                    binding_scope.shadowing,
                    substitutions,
                    context.into_structural_provenance(),
                    binding_scope.authored_resolution_debt,
                )),
                (None, None) => unbound(index, param),
            };
            if let Some(binding) = binding {
                env.insert(param.name.clone(), binding);
            }
            bindings.push(binding);
        }
        (env, bindings)
    }

    /// The COMPLETE argument list the generic declaration `identity` binds
    /// for an application that supplies `args`: the supplied arguments,
    /// then each omitted parameter's declared default under the bindings
    /// before it — the application the checker names when it prints the
    /// reference (`WithDefault` is `WithDefault<string>`, `Chain<number>`
    /// is `Chain<number, number[]>`). The same binding
    /// ([`Self::bind_declared_type_arguments`]) `Instantiate` applies, so
    /// the named application and its instantiated body cannot disagree.
    ///
    /// `None` when the declaration cannot be recovered, or a parameter is
    /// neither supplied nor defaulted.
    pub(super) fn declared_application_arguments(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
        args: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<Arc<[SemanticNodeId]>> {
        let whole_hash = self
            .transaction_indexed_record(identity.canonical_id.as_ref())
            .map(|indexed| indexed.whole_hash)
            .unwrap_or_default();
        let scope = NodeScopeId::File {
            canonical_id: identity.canonical_id.clone(),
            owner: identity.owner,
            whole_hash,
            local_scope: None,
        };
        let base = self
            .graph()
            .intern_node_with_scope(SemanticNodeData::Opaque(QueryError::Miss), scope.clone());
        let ri = ResolvedRootIdentity::new_in_owner(
            identity.canonical_id.as_ref(),
            identity.owner,
            identity.decl_name.as_ref(),
        );
        let prepared =
            match SessionDispatchHost::from_facade(self).resolve_prepared_type_decl(base, &ri) {
                PreparedTypeDeclResolution::Complete(prepared) => prepared,
                PreparedTypeDeclResolution::AuthoredPartial { .. }
                | PreparedTypeDeclResolution::Missing
                | PreparedTypeDeclResolution::Failed { .. } => return None,
            };
        if args.len() > prepared.type_parameters.len() {
            return None;
        }
        let scope_payload = self
            .ctx
            .prepared_decl_bundle(identity.canonical_id.as_ref())
            .map(|bundle| {
                crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                    &bundle,
                    identity.owner,
                )
            });
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let (_env, bindings) = self.bind_declared_type_arguments(
            &prepared,
            args,
            &DeclarationBindingScope {
                scope: &scope,
                scope_payload: scope_payload.as_ref(),
                shadowing: &shadowing,
                authored_resolution_debt: None,
                augmentation: None,
            },
            &mut Vec::new(),
            context,
            |_, _| None,
        );
        bindings
            .into_iter()
            .collect::<Option<Vec<_>>>()
            .map(Arc::from)
    }

    /// The live `IndexedReady` record of `canonical` as a build reads it: a
    /// declaration file's content version and shallow inventory, or an
    /// augmentation candidate made indexed before the augmentation scan. An
    /// instantiation reads its declaration file's record several times (its
    /// content version, the global-interface and member-index checks, the
    /// augmentation candidates), and every instantiation of a declaration
    /// reads the same files, so a record this transaction already served
    /// under the same edit clocks answers again by replaying what serving it
    /// read — its facts, refusal and self-roots reach the enclosing build
    /// exactly as serving it again would deliver them.
    pub(super) fn transaction_indexed_record(
        &self,
        canonical: &str,
    ) -> Option<Arc<verter_session_query::inputs::indexed::IndexedInputRecord>> {
        let served_at = self.workspace_edit();
        let completed = self
            .dispatch_txn
            .borrow()
            .indexed_serves
            .get(canonical, served_at)
            .cloned();
        if let Some(completed) = completed {
            self.replay_transaction_read(&completed.reuse, &completed.replay);
            return completed.record;
        }
        let (record, recorded) = self.record_transaction_read(
            || {
                self.ctx
                    .ensure_indexed_ready_serve(canonical)
                    .map(|serve| serve.indexed)
            },
            Option::is_some,
        );
        if let Some((reuse, replay)) = recorded {
            self.dispatch_txn.borrow_mut().indexed_serves.complete(
                Arc::from(canonical),
                super::dispatch_txn::TransactionIndexedServe {
                    record: record.clone(),
                    served_at,
                    reuse,
                    replay,
                },
            );
        }
        record
    }

    /// Resolve the typed declaration kind of a prepared declaration rooted at
    /// `identity` (Alias vs Interface vs Class).
    ///
    /// Used by the empty-path Shallow walker to decide whether a declaration
    /// body's reference arms are REAL interface/class heritage (which shadows)
    /// or an authored intersection (which intersects) — the P2-1
    /// distinguishing fact. Returns `None` when the prepared decl cannot be
    /// recovered, in which case the caller treats the body as non-heritage.
    pub(super) fn prepared_decl_kind(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
    ) -> Option<verter_session_query::declarations::TypeDeclKind> {
        if let Some(completed) = self.dispatch_txn.borrow().decl_kinds.get(identity) {
            // A declaration identity names one content version, so its
            // kind cannot change under it.
            self.replay_transaction_read(&completed.reuse, &completed.replay);
            return completed.kind;
        }
        let (kind, recorded) = self.record_transaction_read(
            || {
                self.prepared_type_decl(identity)
                    .map(|prepared| prepared.kind)
            },
            |_| true,
        );
        if let Some((reuse, replay)) = recorded {
            self.dispatch_txn.borrow_mut().decl_kinds.complete(
                identity.clone(),
                super::dispatch_txn::TransactionDeclKind {
                    kind,
                    reuse,
                    replay,
                },
            );
        }
        kind
    }

    /// Run a read whose value the rest of this transaction may reuse, and
    /// record what reusing it must replay: its fact reads, refusal, file
    /// self-roots and canonical evidence. `None` when the read is not
    /// reusable — it ran where an enclosing build could not observe a
    /// channel, it was partial, `complete` rejects its value, or its refusal
    /// is not one a later reader of this transaction may share. Either way
    /// every rail reaches the enclosing build exactly as if the read had run
    /// there directly.
    pub(super) fn record_transaction_read<T>(
        &self,
        read: impl FnOnce() -> T,
        complete: impl FnOnce(&T) -> bool,
    ) -> (
        T,
        Option<(
            verter_session_query::facts::reuse::ReuseClass,
            super::dispatch_txn::FlowMemberReuse,
        )>,
    ) {
        let Some(recording) = self.begin_transaction_read() else {
            return (read(), None);
        };
        let value = read();
        let complete = complete(&value);
        let recorded = recording.finish(self, complete);
        (value, recorded)
    }

    /// Begin recording a transaction read whose work does not run inside one
    /// closure (the explicit-stack form of [`Self::record_transaction_read`]):
    /// every channel the reads in between reach is recorded until
    /// [`TransactionReadRecording::finish`]. `None` when the read could not
    /// be replayed — no live tracer, no live build-local frame, or a
    /// cold-compute completeness already partial. Recordings nest, and each
    /// finishes before the one begun before it.
    pub(super) fn begin_transaction_read(&self) -> Option<TransactionReadRecording<'_>> {
        // A recording is only replayable when every channel an enclosing
        // build observes is observable here: a live tracer, a live
        // build-local frame and a cold-compute completeness that can show
        // a partial fold (see the flow-member recorder).
        let completeness_scope_active =
            crate::request_context::cold_compute_completeness_scope_active();
        let recordable = crate::resolver_core::resolver_context::fact_tracer_installed()
            && !self.build_local_taint.borrow().is_empty()
            && !(completeness_scope_active
                && crate::request_context::current_cold_compute_completeness().is_partial());
        if !recordable {
            return None;
        }
        let private_completeness = (!completeness_scope_active)
            .then(crate::request_context::ColdComputeCompletenessScope::enter);
        let evidence_epoch = self.canonical_evidence_epoch.get();
        let frame = super::BuildLocalTaintGuard::push(&self.build_local_taint);
        let refusals = crate::fact_tracing::RefusalObservationScope::enter();
        let reads = crate::resolver_core::resolver_context::FactReadRecording::begin();
        Some(TransactionReadRecording {
            reads,
            refusals,
            frame,
            private_completeness,
            evidence_epoch,
        })
    }

    /// Replay a read [`Self::record_transaction_read`] recorded into the
    /// scopes live now, exactly as running it again would.
    pub(super) fn replay_transaction_read(
        &self,
        reuse: &verter_session_query::facts::reuse::ReuseClass,
        replay: &super::dispatch_txn::FlowMemberReuse,
    ) {
        replay.reads.replay();
        crate::fact_tracing::replay_reuse_refusal(reuse);
        self.deposit_operand_self_roots(&replay.observed_self_roots);
        if replay.canonical_evidence_deposited {
            self.canonical_evidence_epoch
                .set(self.canonical_evidence_epoch.get().wrapping_add(1));
        }
    }

    /// Whether the prepared declaration rooted at `identity` declares type
    /// parameters.
    pub(super) fn prepared_decl_is_generic(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
    ) -> Option<bool> {
        self.prepared_type_decl(identity)
            .map(|prepared| !prepared.type_parameters.is_empty())
    }

    pub(super) fn prepared_type_decl(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
    ) -> Option<verter_retention::heap_size::OwnedValue<PreparedTypeDecl>> {
        let scope = NodeScopeId::File {
            canonical_id: identity.canonical_id.clone(),
            owner: identity.owner,
            whole_hash: identity.whole_hash,
            local_scope: None,
        };
        let base = self
            .graph()
            .intern_node_with_scope(SemanticNodeData::Opaque(QueryError::Miss), scope);
        let adapter = SessionDispatchHost::from_facade(self);
        let ri = ResolvedRootIdentity::new_in_owner(
            identity.canonical_id.as_ref(),
            identity.owner,
            identity.decl_name.as_ref(),
        );
        match adapter.resolve_prepared_type_decl(base, &ri) {
            PreparedTypeDeclResolution::Complete(prepared) => Some(prepared),
            PreparedTypeDeclResolution::AuthoredPartial {
                declaration: prepared,
                ..
            } => Some(prepared),
            PreparedTypeDeclResolution::Missing => None,
            PreparedTypeDeclResolution::Failed { .. } => {
                crate::fact_tracing::note_non_cacheable_read_fan_out(
                    verter_session_query::facts::reuse::NonCacheableReadReason::PreparationFailure,
                );
                None
            }
        }
    }

    /// Re-derive a declaration's ordered `(name, binder)` bindings from its
    /// NARROW type-parameter FACTS — the fact-side entry into the ONE
    /// shared binder-frame constructor (`build_type_param_binder_frame`,
    /// which the shape build's inline bound lowering also routes through).
    /// Binder identity is content-addressed over the same scope + owner +
    /// ordinal + display name + bound NODES: each constraint / default
    /// bound is a content-free locator lowered through the memoized
    /// `LowerLocator` query, whose build derefs the bound position and
    /// lowers it under the SAME TS-exact per-position frame the shape
    /// build's inline bound lowering used — so the two derivations intern
    /// the SAME binder ids and the substitution step rewrites the fetched
    /// shape's binders exactly. A bound-lowering miss (a broken lease pin)
    /// leaves that binder's bound `None`; the resulting identity divergence
    /// degrades substitution to a no-op for that parameter while the
    /// read-boundary fold (`lower_locator`'s `execute_read`) taints the
    /// enclosing build's warm admission — degraded, never poisoned.
    pub(in crate::project_semantic_dispatch) fn locator_binder_frame_from_narrow_params(
        &self,
        scope: &NodeScopeId,
        owner_symbol: &verter_type_expr::OwnedStr,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
    ) -> Vec<(Arc<str>, SemanticNodeId)> {
        self.locator_binder_frame_from_narrow_params_in(scope, owner_symbol, type_parameters, None)
    }

    fn locator_binder_frame_from_narrow_params_in(
        &self,
        scope: &NodeScopeId,
        owner_symbol: &verter_type_expr::OwnedStr,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> Vec<(Arc<str>, SemanticNodeId)> {
        use crate::project_semantic_dispatch::locator_shape::{
            BinderIdentityMode, TypeParamBinderSpec,
        };
        let specs: Vec<TypeParamBinderSpec> = type_parameters
            .iter()
            .map(|param| TypeParamBinderSpec {
                name: Arc::from(param.name.as_str()),
                has_constraint: param.constraint.is_some(),
                has_default: param.default.is_some(),
            })
            .collect();
        // The facts carry no lexical-resolution inputs — bound lowering
        // happens inside the memoized query, not inline — so the base
        // context is frame-empty and resolution-input-free.
        let base = crate::project_semantic_dispatch::locator_shape::LocatorShapeCtx::new(
            scope,
            &[],
            None,
            None,
        );
        let (_frame, built) = self.build_type_param_binder_frame(
            &base,
            BinderIdentityMode::DeclHeader { owner_symbol },
            &specs,
            verter_type_expr::locators::TypeParamVisibility::Body,
            |ordinal, position, _bound_ctx| {
                let param = type_parameters.get(ordinal as usize)?;
                let slot = match position {
                    verter_type_expr::locators::TypeParamBoundPosition::Constraint => {
                        param.constraint.as_ref()
                    }
                    verter_type_expr::locators::TypeParamBoundPosition::Default => {
                        param.default.as_ref()
                    }
                }?;
                match self.lower_locator(scoped_type_body_locator(slot, augmentation)) {
                    QueryResult::Value(node) => Some(node),
                    QueryResult::Recursive(_) | QueryResult::Error(_) => None,
                }
            },
        );
        built
            .into_iter()
            .map(|binder| (binder.name, binder.binder))
            .collect()
    }

    /// Lower an authored body named by `locator` under the caller's demand:
    /// fetch the ROLE-FREE unsubstituted shape through the memoized
    /// `LowerLocator` query, apply the caller's `env` bindings via semantic
    /// type-param substitution over the declaration's binder shells, and
    /// ONLY THEN project the demand-specific view (`ProjectionStamp`
    /// application + deferred-carrier evaluation) under `context`.
    ///
    /// This is the SOLE production body source — a locator miss surfaces as
    /// the query's miss semantics (`Opaque(Miss)`), never a prepared-body
    /// read. An `env` name with no binding substitutes the shared miss
    /// sentinel (open generics are preserved only when the caller pre-bound
    /// `TypeParam` shells, e.g. Skeleton-mode instantiation).
    #[allow(clippy::too_many_arguments)]
    pub(super) fn lower_located_body_with_provenance(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
        decl_kind: verter_session_query::declarations::TypeDeclKind,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        name_resolution: &FxHashMap<verter_type_expr::OwnedStr, ResolvedRootIdentity>,
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        scope_payload: Option<&crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
        shadowing: &crate::resolver_core::scope_shadowing::ScopeShadowing,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        self.lower_located_body_with_resolution_debt(
            locator,
            decl_kind,
            type_parameters,
            name_resolution,
            env,
            scope,
            scope_payload,
            shadowing,
            substitutions,
            context,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn lower_located_body_with_resolution_debt(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
        decl_kind: verter_session_query::declarations::TypeDeclKind,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        name_resolution: &FxHashMap<verter_type_expr::OwnedStr, ResolvedRootIdentity>,
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        scope_payload: Option<&crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
        shadowing: &crate::resolver_core::scope_shadowing::ScopeShadowing,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
        authored_resolution_debt: Option<
            &crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame,
        >,
    ) -> SemanticNodeId {
        self.lower_located_body_with_vue_heritage_policy(
            locator,
            decl_kind,
            type_parameters,
            name_resolution,
            env,
            scope,
            scope_payload,
            shadowing,
            substitutions,
            context,
            authored_resolution_debt,
            &[],
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn lower_located_body_with_vue_heritage_policy(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
        decl_kind: verter_session_query::declarations::TypeDeclKind,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        name_resolution: &FxHashMap<verter_type_expr::OwnedStr, ResolvedRootIdentity>,
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        scope_payload: Option<&crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
        shadowing: &crate::resolver_core::scope_shadowing::ScopeShadowing,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
        authored_resolution_debt: Option<
            &crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame,
        >,
        vue_ignored_heritage: &[verter_type_expr::facts::VueIgnoredHeritageFact],
    ) -> SemanticNodeId {
        let self_value = match &locator {
            verter_type_expr::locators::AuthoredBodyLocator::DeclBody(slot)
                if slot.anchor.space == verter_type_expr::locators::LocatorSymbolSpace::Value =>
            {
                Some(slot.anchor.clone())
            }
            _ => None,
        };
        let mut lowering = self.begin_located_body_lowering(
            locator,
            decl_kind,
            type_parameters,
            env,
            scope,
            substitutions,
            context,
            vue_ignored_heritage,
            crate::project_semantic_dispatch::locator_view_worklist::ProjectionSeam::inline(),
        );
        let inputs = crate::project_semantic_dispatch::locator_view::LocatorViewInputs {
            env,
            scope,
            name_resolution,
            scope_payload,
            shadowing,
            authored_resolution_debt,
            self_value: self_value.as_ref(),
        };
        match self.drain_located_body_lowering(&mut lowering, &inputs, substitutions, None) {
            BodyPoll::Done(node, _) => node,
            BodyPoll::Need(_) => {
                unreachable!("an inline body lowering evaluates the instantiations it reaches")
            }
        }
    }

    /// Begin lowering a located declaration body: fetch its fixed authored
    /// shape, apply the caller's bindings by type-parameter substitution,
    /// and plan the projection of the demanded view.
    #[allow(clippy::too_many_arguments)]
    fn begin_located_body_lowering(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
        decl_kind: verter_session_query::declarations::TypeDeclKind,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
        vue_ignored_heritage: &[verter_type_expr::facts::VueIgnoredHeritageFact],
        seam: crate::project_semantic_dispatch::locator_view_worklist::ProjectionSeam,
    ) -> BodyLowering {
        let owner_symbol = match &locator {
            verter_type_expr::locators::AuthoredBodyLocator::DeclBody(slot) => {
                slot.anchor.symbol.clone()
            }
            verter_type_expr::locators::AuthoredBodyLocator::AugmentationBody(aug) => {
                aug.anchor.symbol.clone()
            }
            verter_type_expr::locators::AuthoredBodyLocator::JsdocTypedefBody(typedef) => {
                typedef.anchor.symbol.clone()
            }
            verter_type_expr::locators::AuthoredBodyLocator::MacroPayload(payload) => {
                payload.anchor.symbol.clone()
            }
        };

        let augmentation = match &locator {
            verter_type_expr::locators::AuthoredBodyLocator::AugmentationBody(body) => {
                Some(match &body.scope {
                    verter_type_expr::locators::AuthoredAugmentationScope::Global => {
                        verter_session_query::declarations::AugmentationScopeKind::Global
                    }
                    verter_type_expr::locators::AuthoredAugmentationScope::Module { specifier } => {
                        verter_session_query::declarations::AugmentationScopeKind::Module(
                            specifier.to_string(),
                        )
                    }
                })
            }
            _ => None,
        };

        // 1. Fetch the fixed authored shape (one reusable body-shape family
        //    per locator/source-env).
        let Some(shape) = self.fetch_located_shape(locator) else {
            return BodyLowering::Ready(self.opaque(QueryError::Miss));
        };
        self.begin_shape_lowering(
            shape,
            &owner_symbol,
            decl_kind,
            type_parameters,
            env,
            scope,
            substitutions,
            context,
            vue_ignored_heritage,
            seam,
            augmentation.as_ref(),
        )
    }

    /// The fixed authored shape `locator` names, or `None` when its
    /// `LowerLocator` query answers no value.
    fn fetch_located_shape(
        &self,
        locator: verter_type_expr::locators::AuthoredBodyLocator,
    ) -> Option<SemanticNodeId> {
        match self.lower_locator(locator) {
            QueryResult::Value(node) => Some(node),
            QueryResult::Recursive(_) | QueryResult::Error(_) => None,
        }
    }

    /// Begin lowering an already fetched authored `shape`: apply the
    /// caller's bindings and plan the projection of the demanded view.
    #[allow(clippy::too_many_arguments)]
    fn begin_shape_lowering(
        &self,
        shape: SemanticNodeId,
        owner_symbol: &verter_type_expr::OwnedStr,
        decl_kind: verter_session_query::declarations::TypeDeclKind,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        context: crate::semantic_query::ProjectionReductionContext,
        vue_ignored_heritage: &[verter_type_expr::facts::VueIgnoredHeritageFact],
        seam: crate::project_semantic_dispatch::locator_view_worklist::ProjectionSeam,
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> BodyLowering {
        let shape = if context.suppresses_vue_ignored_heritage() && !vue_ignored_heritage.is_empty()
        {
            self.filter_vue_ignored_heritage(shape, vue_ignored_heritage)
        } else {
            shape
        };

        // 2. Apply the caller's bindings via semantic type-param
        //    substitution. Binder identity is re-derived deterministically
        //    from the declaration's NARROW parameter facts (content-addressed
        //    interning — the same ids the shape build bound). An unbound
        //    parameter substitutes the shared miss sentinel, mirroring the
        //    "unbound param propagates a miss through the body" rule.
        let substituted = self.bind_located_shape_parameters(
            shape,
            owner_symbol,
            type_parameters,
            env,
            scope,
            substitutions,
            augmentation,
        );
        let substituted = if decl_kind == verter_session_query::declarations::TypeDeclKind::Class {
            let canonical = scope.canonical_file();
            verter_debug_assert!(
                canonical.is_some(),
                "a class initializer has an owning file"
            );
            canonical.map_or(substituted, |canonical| {
                self.normalize_class_initializers(substituted, self.nullability_for(&canonical))
            })
        } else {
            substituted
        };

        // 3. Plan the projection of the demanded view: per-arm
        //    ProjectionStamp application + deferred-carrier evaluation under
        //    the caller's context.
        BodyLowering::Project(Box::new(self.begin_decl_body_projection(
            substituted,
            decl_kind,
            substitutions.len(),
            context,
            seam,
        )))
    }

    /// Bind a fixed locator shape without demanding any member value.
    /// Header composition and demanded body projection share this substitution.
    #[allow(clippy::too_many_arguments)]
    fn bind_located_shape_parameters(
        &self,
        shape: SemanticNodeId,
        owner_symbol: &verter_type_expr::OwnedStr,
        type_parameters: &[verter_type_expr::facts::NarrowTypeParam],
        env: &FxHashMap<String, SemanticNodeId>,
        scope: &NodeScopeId,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> SemanticNodeId {
        let bindings = self.locator_binder_frame_from_narrow_params_in(
            scope,
            owner_symbol,
            type_parameters,
            augmentation,
        );
        let mut substituted = shape;
        for (name, binder) in bindings {
            let bound = env.get(name.as_ref()).copied();
            let replacement = bound.unwrap_or_else(|| self.opaque(QueryError::Miss));
            let next = self.substitute_semantic_type_param(substituted, binder, replacement);
            if next != substituted {
                if let Some(arg_id) = bound {
                    substitutions.push((name, arg_id));
                }
            }
            substituted = next;
        }

        substituted
    }

    /// Carry a located body lowering on as far as it can go. A partial
    /// projection folds its reasons into the enclosing build.
    fn drain_located_body_lowering(
        &self,
        lowering: &mut BodyLowering,
        inputs: &crate::project_semantic_dispatch::locator_view::LocatorViewInputs<'_>,
        substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
        delivery: Option<
            crate::project_semantic_dispatch::locator_view_worklist::ProjectionDelivery,
        >,
    ) -> BodyPoll {
        let projection = match lowering {
            BodyLowering::Ready(node) => return BodyPoll::Done(*node, false),
            BodyLowering::Project(projection) => projection,
        };
        match self.drain_decl_body_projection(projection, inputs, substitutions, delivery) {
            crate::project_semantic_dispatch::locator_view::BodyProjectionPoll::Need(key) => {
                BodyPoll::Need(key)
            }
            crate::project_semantic_dispatch::locator_view::BodyProjectionPoll::Done(projected) => {
                if let crate::semantic_query::ResultCompleteness::Partial(reasons) =
                    projected.completeness
                {
                    self.fold_local_partial_completeness(reasons);
                }
                BodyPoll::Done(
                    projected.node,
                    projected.extent.has_positional_representation(),
                )
            }
        }
    }

    /// Remove only producer-addressed Vue runtime heritage arms from the
    /// fixed, role-free declaration shape. Filtering happens before generic
    /// substitution, carrier resolution, or peer/heritage merge, so an ignored
    /// imported head creates no nested demand and cannot leak members into the
    /// runtime surface.
    fn filter_vue_ignored_heritage(
        &self,
        shape: SemanticNodeId,
        facts: &[verter_type_expr::facts::VueIgnoredHeritageFact],
    ) -> SemanticNodeId {
        let mut ignored_by_contributor: FxHashMap<u32, FxHashSet<u32>> = FxHashMap::default();
        for fact in facts {
            ignored_by_contributor
                .entry(fact.contributor_ordinal)
                .or_default()
                .insert(fact.intersection_arm_ordinal);
        }

        let Some(data) = self.graph().node_data(shape) else {
            return shape;
        };
        let SemanticNodeData::MergedDecl { contributors } = data.as_ref() else {
            let Some(ignored) = ignored_by_contributor.get(&0) else {
                return shape;
            };
            return self.filter_vue_ignored_contributor(shape, ignored);
        };
        let contributors = Arc::clone(contributors.as_arc());
        drop(data);

        let mut changed = false;
        let filtered: Vec<_> = contributors
            .iter()
            .enumerate()
            .map(|(ordinal, contributor)| {
                let Ok(ordinal) = u32::try_from(ordinal) else {
                    return *contributor;
                };
                let Some(ignored) = ignored_by_contributor.get(&ordinal) else {
                    return *contributor;
                };
                let next = self.filter_vue_ignored_contributor(*contributor, ignored);
                changed |= next != *contributor;
                next
            })
            .collect();
        if !changed {
            return shape;
        }
        self.graph().intern_preserving_scope(
            shape,
            SemanticNodeData::MergedDecl {
                contributors: crate::semantic_query::PayloadArray::from(
                    filtered.into_boxed_slice(),
                ),
            },
        )
    }

    /// Filter the addressed heritage ordinals from one declaration contributor.
    /// Alias peeling/rebuild is iterative and bounded only by the shared graph;
    /// there is no syntax rescan or fixed depth escape.
    fn filter_vue_ignored_contributor(
        &self,
        contributor: SemanticNodeId,
        ignored: &FxHashSet<u32>,
    ) -> SemanticNodeId {
        let mut aliases = Vec::new();
        let mut visited = FxHashSet::default();
        let mut current = contributor;
        let arms = loop {
            if !visited.insert(current) {
                return contributor;
            }
            let Some(data) = self.graph().node_data(current) else {
                return contributor;
            };
            match data.as_ref() {
                SemanticNodeData::Alias(target) => {
                    aliases.push(current);
                    current = *target;
                }
                SemanticNodeData::Intersection(arms) => break arms.members_arc(),
                _ => return contributor,
            }
        };

        let mut heritage_ordinal = 0_u32;
        let mut changed = false;
        let mut filtered = Vec::with_capacity(arms.len());
        for arm in arms.iter().copied() {
            if self.vue_heritage_arm_is_own_object(arm) {
                filtered.push(arm);
                continue;
            }
            let suppress = ignored.contains(&heritage_ordinal);
            heritage_ordinal = heritage_ordinal.saturating_add(1);
            if suppress {
                changed = true;
            } else {
                filtered.push(arm);
            }
        }
        if !changed || filtered.is_empty() {
            return contributor;
        }

        // ORDERED-carrier companion filter: the heritage intersection's
        // arm order (own-body-last topology, rendered type text) survives
        // the suppression filter verbatim — never the commutative route.
        let mut filtered_node = self.graph().intern_preserving_scope(
            current,
            SemanticNodeData::Intersection(
                crate::semantic_query::composite::CompositeList::ordered_carrier(Arc::from(
                    filtered.into_boxed_slice(),
                )),
            ),
        );
        for alias in aliases.into_iter().rev() {
            filtered_node = self
                .graph()
                .intern_preserving_scope(alias, SemanticNodeData::Alias(filtered_node));
        }
        filtered_node
    }

    /// Whether an interface contributor arm is its authored Object body rather
    /// than an `extends` carrier. Alias traversal is graph-only and iterative;
    /// it never resolves the heritage head or observes nested members.
    fn vue_heritage_arm_is_own_object(&self, arm: SemanticNodeId) -> bool {
        let mut visited = FxHashSet::default();
        let mut current = arm;
        loop {
            if !visited.insert(current) {
                return false;
            }
            let Some(data) = self.graph().node_data(current) else {
                return false;
            };
            match data.as_ref() {
                SemanticNodeData::Object(_) => return true,
                SemanticNodeData::Alias(target) => current = *target,
                _ => return false,
            }
        }
    }

    /// Where member `name` of the class declaration `class` (applied to
    /// `args`) reads from, found without lowering the class's other
    /// members: an object of the class's OWN members of that name, each
    /// lowered from its own member position, else the `extends` arm that
    /// supplies it. The class body is never lowered whole: the declaration
    /// body is re-borrowed from the retained parse only for the class
    /// elements declaring `name` (`ClassMembersNamed`) and the `extends`
    /// reference (`ClassHeritage`). A member body reading its own class
    /// (`this.v`) reads a sibling this way; lowering the whole class body
    /// would lower the reading member's own body-derived return and
    /// re-enter it.
    ///
    /// The read follows the demanded name up the inheritance path one class
    /// at a time, iteratively, however deep the chain: each base answers
    /// through its own member position, applied to the arguments the
    /// `extends` clause passes, and keeps the base as its declaring owner.
    /// A base the selective route cannot serve (a value-only base, a merged
    /// class) or one the path already followed (a circular chain) is read
    /// through the previous class's `extends` arm whole.
    pub(super) fn class_member_source(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        class: &str,
        args: &[SemanticNodeId],
        name: &str,
    ) -> Option<SemanticNodeId> {
        let mut followed: FxHashSet<(
            verter_type_expr::OwnedStr,
            verter_type_expr::TopLevelOwnerId,
            verter_type_expr::OwnedStr,
        )> = FxHashSet::default();
        let mut at: (
            Arc<str>,
            verter_type_expr::TopLevelOwnerId,
            Arc<str>,
            Vec<SemanticNodeId>,
        ) = (
            std::sync::Arc::<str>::from(verter_type_expr::OwnedStr::from(canonical)),
            owner,
            std::sync::Arc::<str>::from(verter_type_expr::OwnedStr::from(class)),
            args.to_vec(),
        );
        // The `extends` arm of the class last followed: what the read
        // answers with when the next class cannot answer selectively.
        let mut through: Option<SemanticNodeId> = None;
        loop {
            let (canonical, owner, class, args) = at;
            if !followed.insert((
                verter_type_expr::OwnedStr::from(canonical.clone()),
                owner,
                verter_type_expr::OwnedStr::from(class.clone()),
            )) {
                return through;
            }
            match self.class_member_step(&canonical, owner, &class, &args, name) {
                None => return through,
                Some(ClassMemberStep::Declared(node)) => return Some(node),
                Some(ClassMemberStep::Inherited { heritage, base }) => {
                    through = Some(heritage);
                    let Some((base, base_args)) = base else {
                        return through;
                    };
                    at = (
                        std::sync::Arc::<str>::from(base.canonical_id.as_str()),
                        base.owner,
                        std::sync::Arc::<str>::from(base.decl_name.as_str()),
                        base_args,
                    );
                }
            }
        }
    }

    /// One class of the inheritance path a [`Self::class_member_source`]
    /// read follows: the class's own members named `name`, else its
    /// `extends` arm and the class declaration that arm references.
    fn class_member_step(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        class: &str,
        args: &[SemanticNodeId],
        name: &str,
    ) -> Option<ClassMemberStep> {
        if !self.class_takes_module_augmentation(canonical, class) {
            if let Some(input) = self.ctx.class_member_input(canonical, owner, class, name) {
                if let verter_session_query::source::deref::DerefedBodyShape::Single(
                    TypeExpr::Object(ref members),
                ) = input.selected.shape
                {
                    if let Some(node) = self.precise_class_member_read(
                        canonical,
                        owner,
                        name,
                        members,
                        &input.name_resolution,
                    ) {
                        return Some(ClassMemberStep::Declared(node));
                    }
                }
            }
        }
        let prepared = self
            .ctx
            .prepared_type_decl_return_only(canonical, owner, class)?;
        if prepared.kind != verter_session_query::declarations::TypeDeclKind::Class {
            return None;
        }
        let body_slot = prepared.body_facts.body_slot.clone();
        let serve = self.ctx.ensure_indexed_ready_serve(canonical)?;
        let members_step = verter_type_expr::locators::TypeBodyPathStep::ClassMembersNamed {
            name_hash: verter_type_expr::locators::class_member_name_hash(name),
        };
        let member_slot = verter_type_expr::locators::TypeBodySlot {
            anchor: body_slot.anchor.clone(),
            path: verter_type_expr::OwnedSlice::from(vec![members_step].into_boxed_slice()),
        };
        // The demanded members, selected from the retained parse; a class
        // the selective route cannot serve (a merged declaration) is no
        // source.
        let members = super::raise::deref_slot_body(self.ctx, &member_slot)?;
        let TypeExpr::Object(ref members) = members else {
            return None;
        };
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: serve.indexed.whole_hash,
            local_scope: None,
        };
        let scope_payload = self.ctx.prepared_decl_bundle(canonical).map(|bundle| {
            crate::resolver_core::bare_name_resolve::DeclarationScopePayload::from_bundle(
                &bundle, owner,
            )
        });
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        let env: FxHashMap<String, SemanticNodeId> = prepared
            .type_parameters
            .iter()
            .zip(args.iter())
            .map(|(param, arg)| (param.name.to_string(), *arg))
            .collect();
        let key = crate::semantic_query::PropertyKey::identifier(Arc::from(name));
        let context = crate::semantic_query::ProjectionReductionContext::published(
            crate::semantic_query::ProjectionMode::Navigate,
        )
        .into_structural_provenance();
        let mut substitutions: Vec<(Arc<str>, SemanticNodeId)> = Vec::new();
        let lower_at =
            |path: Vec<verter_type_expr::locators::TypeBodyPathStep>,
             substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
             context: crate::semantic_query::ProjectionReductionContext| {
                self.lower_located_body_with_resolution_debt(
                    verter_type_expr::locators::AuthoredBodyLocator::DeclBody(
                        verter_type_expr::locators::TypeBodySlot {
                            anchor: body_slot.anchor.clone(),
                            path: verter_type_expr::OwnedSlice::from(path.into_boxed_slice()),
                        },
                    ),
                    prepared.kind,
                    &prepared.type_parameters,
                    &prepared.name_resolution,
                    &env,
                    &scope,
                    scope_payload.as_ref(),
                    &shadowing,
                    substitutions,
                    context,
                    None,
                )
            };
        let mut own: Vec<SurfaceEntry> = Vec::new();
        {
            for (raw_index, member) in members.properties.iter().enumerate() {
                let (member_key, optional, readonly, method_kind, has_body, visibility) =
                    match member {
                        ObjectMember::Property(property) => (
                            property.key.cloned_known(),
                            property.optional,
                            property.readonly,
                            None,
                            false,
                            property.visibility,
                        ),
                        ObjectMember::Method(method) => (
                            method.key.cloned_known(),
                            method.optional,
                            false,
                            Some(method.method_kind),
                            method.has_implementation_body,
                            method.visibility,
                        ),
                        _ => continue,
                    };
                if member_key.as_ref() != Some(&key) {
                    continue;
                }
                let path = vec![
                    members_step,
                    verter_type_expr::locators::TypeBodyPathStep::Member {
                        ordinal: u32::try_from(raw_index).unwrap_or(u32::MAX),
                    },
                    verter_type_expr::locators::TypeBodyPathStep::MemberValue,
                ];
                let value = lower_at(
                    path,
                    &mut substitutions,
                    context.with_merge_role(crate::semantic_query::MemberMergeRole::OwnBody),
                );
                let value = self
                    .normalize_inferred_initializer_type(value, self.nullability_for(canonical));
                own.push(SurfaceEntry::Member(SurfaceMember {
                    key: crate::semantic_query::AuthoredPropertyKey::from_known(key.clone()),
                    value,
                    optional,
                    readonly,
                    method_kind,
                    has_implementation_body: has_body,
                    visibility,
                    excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                    spans: verter_type_expr::MemberSpans::default(),
                    declaration_origin: Some(verter_type_expr::OwnedStr::from(canonical)),
                    declared_in_macro_type_arg: crate::semantic_query::MacroOwnBodyStamp::default(),
                    merge_role: context.stamp_role(crate::semantic_query::MemberMergeRole::OwnBody),
                }));
            }
        }
        if !own.is_empty() {
            return Some(ClassMemberStep::Declared(
                self.graph().intern_node_with_scope(
                    SemanticNodeData::Object(SurfaceView::from_entries(own, None, false)),
                    scope,
                ),
            ));
        }
        // A class another module augments (`declare module "./c" {
        // interface C { … } }`) declares members its own body does not, so a read its own body
        // does not answer and that is about to follow `extends` decides it: only
        // the whole declaration, which merges the augmentations, answers.
        if self.class_takes_module_augmentation(canonical, class) {
            return None;
        }
        // An inherited member reads off the base the class extends: its
        // `extends` arm lowers to a lazy reference, which binds no `this`, so
        // the member keeps the polymorphic `this` the reading receiver binds.
        let heritage_slot = verter_type_expr::locators::TypeBodySlot {
            anchor: body_slot.anchor.clone(),
            path: verter_type_expr::OwnedSlice::from(
                vec![verter_type_expr::locators::TypeBodyPathStep::ClassHeritage]
                    .into_boxed_slice(),
            ),
        };
        super::raise::deref_slot_body(self.ctx, &heritage_slot)?;
        let heritage = lower_at(
            vec![verter_type_expr::locators::TypeBodyPathStep::ClassHeritage],
            &mut substitutions,
            context,
        );
        // A base that is itself a class declaration answers through its own
        // member position; the caller follows it.
        let base = match self.graph().node_data(heritage).as_deref() {
            Some(SemanticNodeData::DeclRef { identity }) => Some((identity.clone(), Vec::new())),
            Some(SemanticNodeData::InstantiationRef { base, args }) => {
                Some((base.clone(), args.to_vec()))
            }
            _ => None,
        };
        Some(ClassMemberStep::Inherited { heritage, base })
    }

    /// The member-precise answer of a read of `name` that the class's own
    /// elements declare, when every element declaring it is a property
    /// whose type names nothing: no reference, type parameter, `this`,
    /// `typeof` or operator — only keywords, literals and unions, arrays
    /// and tuples of them (the independent-member type predicate). Such a type
    /// is fixed by the elements' own text, so the read roots on the class's
    /// `Member` fact for the name (the declaring elements and the `extends`
    /// reference, observed at `observed_hash`) instead of the file's whole
    /// hash, and lowers to scope-free nodes through no locator query, so
    /// neither its nodes nor a locator memo entry root the read on the
    /// class's file: an edit to another member of the class, or anywhere
    /// else in its file, leaves the read's evidence in place, while an edit
    /// to an element declaring the name, to how many elements do, or to the
    /// `extends` clause moves it.
    ///
    /// Unsupported signatures and binding-sensitive types keep the general
    /// content path. Imported heads are accepted only from the source port's
    /// exact resolved map; no file-scope fallback runs under Global.
    #[allow(clippy::too_many_arguments)]
    fn precise_class_member_read(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &str,
        members: &verter_type_expr::ObjectExpr,
        name_resolution: &FxHashMap<verter_type_expr::OwnedStr, ResolvedRootIdentity>,
    ) -> Option<SemanticNodeId> {
        if owner != verter_type_expr::TopLevelOwnerId::ordinary_file() {
            return None;
        }
        let key = crate::semantic_query::PropertyKey::identifier(Arc::from(name));
        let mut declaring = Vec::new();
        for member in members.properties.iter() {
            match member {
                ObjectMember::Property(property) => {
                    if property.key.cloned_known().as_ref() != Some(&key) {
                        continue;
                    }
                    if !is_independent_member_type(&property.ty, name_resolution) {
                        return None;
                    }
                    declaring.push((
                        property.ty.clone(),
                        property.optional,
                        property.readonly,
                        None,
                        false,
                        property.visibility,
                    ));
                }
                ObjectMember::Method(method)
                    if method.key.cloned_known().as_ref() == Some(&key) =>
                {
                    let function = &method.function;
                    if function.flow_return.is_some()
                        || !function.type_parameters.is_empty()
                        || function.predicate.is_some()
                        || !function
                            .return_type
                            .as_deref()
                            .is_some_and(|ty| is_independent_member_type(ty, name_resolution))
                        || !function.parameters.iter().all(|parameter| {
                            is_independent_member_type(&parameter.ty, name_resolution)
                        })
                    {
                        return None;
                    }
                    declaring.push((
                        TypeExpr::Function(Arc::new({
                            let mut signature = function.clone();
                            signature.spans = Default::default();
                            for parameter in &mut signature.parameters {
                                parameter.span = None;
                            }
                            signature
                        })),
                        method.optional,
                        false,
                        Some(method.method_kind),
                        method.has_implementation_body,
                        method.visibility,
                    ));
                }
                _ => {}
            }
        }
        if declaring.is_empty() {
            return None;
        }
        // The scope-free nodes carry no declaring file, so a later array
        // mapping reads the default nullability options; a file compiled
        // under other options keeps the whole-file read, which lowers with
        // the file's own scope.
        let options = self.ctx.semantic_compiler_options_for(canonical);
        if !options.strict_null_checks || options.exact_optional_property_types {
            return None;
        }
        let context = crate::semantic_query::ProjectionReductionContext::published(
            crate::semantic_query::ProjectionMode::Navigate,
        )
        .into_structural_provenance();
        let shadowing =
            crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(None);
        let env: FxHashMap<String, SemanticNodeId> = FxHashMap::default();
        let mut substitutions: Vec<(Arc<str>, SemanticNodeId)> = Vec::new();
        let own: Vec<SurfaceEntry> = declaring
            .into_iter()
            .map(
                |(ty, optional, readonly, method_kind, has_implementation_body, visibility)| {
                    let value = self.shallow_lower_type_expr_with_context(
                        &ty,
                        &env,
                        &NodeScopeId::Global,
                        name_resolution,
                        None,
                        &shadowing,
                        &mut substitutions,
                        context.with_merge_role(crate::semantic_query::MemberMergeRole::OwnBody),
                    );
                    SurfaceEntry::Member(SurfaceMember {
                        key: crate::semantic_query::AuthoredPropertyKey::from_known(key.clone()),
                        value,
                        optional,
                        readonly,
                        method_kind,
                        has_implementation_body,
                        visibility,
                        excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                        spans: verter_type_expr::MemberSpans::default(),
                        declaration_origin: Some(Arc::<str>::from(canonical).into()),
                        declared_in_macro_type_arg:
                            crate::semantic_query::MacroOwnBodyStamp::default(),
                        merge_role: context
                            .stamp_role(crate::semantic_query::MemberMergeRole::OwnBody),
                    })
                },
            )
            .collect();
        Some(self.graph().intern_node_with_scope(
            SemanticNodeData::Object(SurfaceView::from_entries(own, None, false)),
            NodeScopeId::Global,
        ))
    }

    /// Whether another module's `declare module` block contributes to the
    /// class `class` of `canonical` — the augmentation the whole
    /// declaration's instantiation merges in. The augmenter population is
    /// observed onto the active fact tracer, so an augmentation appearing
    /// later misses a read that found none.
    fn class_takes_module_augmentation(&self, canonical: &str, class: &str) -> bool {
        // Candidate augmenters are the files that depend on the class's
        // module, indexed before the augmentation index is read — as the
        // declaration's own stitch reads it.
        for rdep in self.ctx.reverse_dependency_canonicals(canonical) {
            // Populate the target's contributor index; no source payload is
            // consumed here. The following population observation owns its
            // membership, and actual contributions own their content reads.
            let _ = self.ctx.source_is_available(&rdep);
        }
        let canonical_text: Arc<str> = Arc::from(canonical);
        let target =
            verter_session_query::resolution::AugmentationTargetKind::ResolvedRelativeCanonical(
                Arc::clone(&canonical_text),
            );
        // The common case — no module augments this one — is decided from the
        // augmenter set alone, observed so a later augmenter misses a warm
        // read; only a module with augmenters pays for the contributor read.
        let (_, augmenter_set) = self.ctx.augmentation_index(target.clone());
        crate::resolver_core::resolver_context::observe_fan_out(
            verter_session_query::facts::fact_cache::FactVersionRef::RouteSurface(
                verter_session_query::facts::fact_cache::RouteSurfaceFactRef {
                    canonical_id: canonical_text,
                    key: verter_session_query::source::augmentation_keys::build_module_augmentation_index_shape_fact_key(
                        &target,
                    ),
                    lane: verter_session_query::facts::FactLane::Semantic,
                    expected_hash: augmenter_set.fingerprint,
                },
            ),
        );
        if augmenter_set.entries.is_empty() {
            return false;
        }
        self.collect_augmentation_contributions(
            AugmentationContribution::TypeBody,
            target,
            class,
            &[],
            crate::semantic_query::ProjectionReductionContext::published(
                crate::semantic_query::ProjectionMode::Navigate,
            )
            .into_structural_provenance(),
            canonical,
            None,
        )
        .is_some()
    }

    /// Whether the object surface `node` declares a member spelled `name`.
    fn surface_declares_member(&self, node: SemanticNodeId, name: &str) -> bool {
        matches!(
            self.graph().node_data(node).as_deref(),
            Some(SemanticNodeData::Object(surface))
                if surface
                    .positive_members()
                    .iter()
                    .any(|member| member.key.as_string() == Some(name))
        )
    }

    /// Where member `name` of the value `prepared` declares reads from,
    /// found without lowering its other members: an object of the value's
    /// OWN members of that name — a class's statics, or the members of the
    /// object literal a variable is initialized with — each lowered from
    /// its own member position. The checker resolves a value's members one
    /// at a time, so a member whose return names the value itself (a static
    /// `return this`, a literal's `obj.v`) never builds the whole surface
    /// it is part of.
    ///
    /// `None` when the member is not the value's own (a base class's
    /// static), or when the own shape cannot prove which member a name
    /// reads: a spread or a computed key may supply it.
    pub(super) fn value_member_source(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        name: &str,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        let (member_scope, mut members) =
            self.value_member_plan(canonical, owner, symbol, prepared, name, context)?;
        let mut substitutions = Vec::new();
        while let Some((ordinal, facts)) = members.positions.pop_front() {
            let value = self.lower_located_body_with_provenance(
                members.locator(ordinal),
                verter_session_query::declarations::TypeDeclKind::Alias,
                &members.class_type_params,
                &prepared.name_resolution,
                &member_scope.env,
                &member_scope.scope,
                member_scope.scope_payload.as_ref(),
                &member_scope.shadowing,
                &mut substitutions,
                members.context,
            );
            members.record(facts, value);
        }
        Some(self.finish_value_members(members, member_scope.scope))
    }

    /// The own member positions of `name` the value's authored object or
    /// class declares, and the scope their values lower in; `None` when it
    /// declares none (or a spread or computed key may declare it).
    fn value_member_plan(
        &self,
        canonical: &str,
        owner: verter_type_expr::TopLevelOwnerId,
        symbol: &str,
        prepared: &verter_session_query::type_solver::PreparedValueDecl,
        name: &str,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<(ValueMemberScope, ValueMembers)> {
        use verter_type_expr::facts::ObjectMemberFact;
        let shape = prepared.object_shape.as_ref()?;
        // Each own member position of the name, with its modifiers.
        let mut positions: std::collections::VecDeque<(u32, ValueMemberFacts)> =
            std::collections::VecDeque::new();
        for (raw_index, member) in shape.members.iter().enumerate() {
            let ordinal = u32::try_from(raw_index).unwrap_or(u32::MAX);
            let (key, optional, readonly, method_kind, has_body, visibility) = match member {
                ObjectMemberFact::Property(property) => (
                    &property.key,
                    property.optional,
                    property.readonly,
                    None,
                    false,
                    property.visibility,
                ),
                ObjectMemberFact::Method(method) => (
                    &method.key,
                    method.optional,
                    false,
                    Some(method.method_kind),
                    method.function.has_implementation_body,
                    method.visibility,
                ),
                ObjectMemberFact::Spread(_) => return None,
                ObjectMemberFact::CallSignature(_)
                | ObjectMemberFact::ConstructSignature(_)
                | ObjectMemberFact::IndexSignature(_) => continue,
            };
            let Some(spelling) = key.as_string() else {
                // A computed key may name the member.
                key.cloned_known()?;
                continue;
            };
            if spelling != name {
                continue;
            }
            positions.push_back((
                ordinal,
                ValueMemberFacts {
                    optional,
                    readonly,
                    method_kind,
                    has_body,
                    visibility,
                },
            ));
        }
        if positions.is_empty() {
            return None;
        }
        let indexed = self.ctx.ensure_indexed_ready_serve(canonical)?.indexed;
        let scope = NodeScopeId::File {
            canonical_id: verter_type_expr::OwnedStr::from(canonical),
            owner,
            whole_hash: indexed.whole_hash,
            local_scope: None,
        };
        // The members lower in the scope the whole value lowers in
        // ([`Self::declaration_scope_payload`]).
        let scope_payload = self
            .ctx
            .prepared_decl_bundle(canonical)
            .map(|bundle| self.declaration_scope_payload(&bundle, canonical, owner, symbol));
        let shadowing = crate::resolver_core::scope_shadowing::ScopeShadowing::from_scope_payload(
            scope_payload.as_ref(),
        );
        // A class's own type parameters bind as the shells its constructor
        // shape lowers them to (statics cannot name them otherwise).
        let is_class = prepared.kind == verter_session_query::declarations::ValueDeclKind::Class;
        let (env, class_type_params) = if is_class {
            (
                self.class_type_param_shell_env(
                    canonical,
                    owner,
                    symbol,
                    indexed.whole_hash,
                    &scope,
                ),
                self.ctx
                    .prepared_type_decl_return_only(canonical, owner, symbol)
                    .map(|type_side| type_side.type_parameters.clone())
                    .unwrap_or_default(),
            )
        } else {
            (FxHashMap::default(), Vec::new())
        };
        let own = Vec::with_capacity(positions.len());
        Some((
            ValueMemberScope {
                env,
                scope,
                scope_payload,
                shadowing,
            },
            ValueMembers {
                name: verter_type_expr::OwnedStr::from(name),
                canonical: verter_type_expr::OwnedStr::from(canonical),
                owner,
                symbol: verter_type_expr::OwnedStr::from(symbol),
                positions,
                class_type_params,
                context,
                own,
            },
        ))
    }

    /// The member surface of the values `members` lowered.
    fn finish_value_members(
        &self,
        mut members: ValueMembers,
        scope: NodeScopeId,
    ) -> SemanticNodeId {
        let nullability = self.nullability_for(members.canonical.as_ref());
        for entry in &mut members.own {
            let SurfaceEntry::Member(member) = entry else {
                continue;
            };
            member.value = self.normalize_widened_object_literals(member.value, nullability);
        }
        let node = self.graph().intern_node_with_scope(
            SemanticNodeData::Object(SurfaceView::from_entries(members.own, None, false)),
            scope,
        );
        self.regularized_source_node_with_policy(node, nullability)
    }

    construction_ordinal_seam! {
        fn backfill_member_index_surface(
            &self,
            result: SemanticNodeId,
            prepared: &PreparedTypeDecl,
            env: &FxHashMap<String, SemanticNodeId>,
            scope: &NodeScopeId,
            scope_payload: Option<&crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
            shadowing: &crate::resolver_core::scope_shadowing::ScopeShadowing,
            substitutions: &mut Vec<(Arc<str>, SemanticNodeId)>,
            context: crate::semantic_query::ProjectionReductionContext,
            authored_resolution_debt: Option<
                &crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame,
            >,
        ) -> SemanticNodeId {
            let Some(data) = self.graph().node_data(result) else {
                return result;
            };
            let SemanticNodeData::Object(surface) = data.as_ref() else {
                return result;
            };
            if prepared.member_index.is_empty() {
                return result;
            }

            // `member_index` is the declaration's OWN-body direct-member
            // index (by design — authoritative own-member
            // overlay). `PreparedTypeDecl::build_member_index` populates it
            // from direct Object members only, skipping heritage `extends`
            // `Ref` arms. So a member present in `member_index` is
            // author-declared in this declaration's own body; under a
            // macro-type-argument own-body instantiation it carries
            // `declared_in_macro_type_arg = true`.
            let own_body_bit = context.is_macro_type_arg_own_body();
            let existing: FxHashSet<crate::semantic_query::PropertyKey> = surface
                .positive_members()
                .iter()
                .filter_map(|member| member.key.cloned_known())
                .collect();

            // (1) RE-STAMP existing surface members that are own-body index
            // entries. The interface body was lowered STRUCTURALLY (heritage
            // arms must stay `false`), so own members already on the surface
            // carry `false`; the overlay marks exactly the own-body ones
            // `own_body_bit`. Heritage members (not in `member_index`) are
            // left untouched. This is the "replace/mark, not only append"
            // requirement — without it a plain "append missing" overlay
            // would leave own members `false` after structural body lowering.
            let mut restamped_any = false;
            let mut members: Vec<SurfaceMember> = surface
                .positive_members()
                .iter()
                .map(|member| {
                    if own_body_bit
                        && !member.declared_in_macro_type_arg.get()
                        && member
                            .key
                            .cloned_known()
                            .is_some_and(|key| prepared.member_index.contains_key(&key))
                    {
                        restamped_any = true;
                        SurfaceMember {
                            declared_in_macro_type_arg: context.own_body_stamp(),
                            ..member.clone()
                        }
                    } else {
                        member.clone()
                    }
                })
                .collect();

            // (2) APPEND own-body members not yet on the surface. Member
            // VALUE lowering downgrades to structural provenance: a nested
            // object inside the member's type is NOT the macro-T own body —
            // only the member's PRESENCE on this declaration is. The member
            // fact's `ty` is the content-free locator of its authored value
            // position (lowered through the ONE located body source); its
            // declaration-site spans are RECOVERED from the declaring file's
            // retained parse via the fact's span-recovery origin.
            let member_span_memo =
                self.transaction_indexed_record(prepared.root_identity.canonical_id.as_ref());
            let mut added: Vec<SurfaceMember> = prepared
                .member_index
                .iter()
                .filter(|(key, _)| !existing.contains(*key))
                .map(|(key, member)| {
                    // Backfilled entries are declaration OWN-body members just as
                    // surely as entries already present on the lowered Object.
                    // Stamp the same role before lowering their value so a missing
                    // nested reference stays member-local instead of being
                    // misclassified as a root/surface-composition arm.
                    let member_context = context
                        .into_structural_provenance()
                        .with_merge_role(crate::semantic_query::MemberMergeRole::OwnBody);
                    let value = self.lower_located_body_with_resolution_debt(
                        verter_type_expr::locators::AuthoredBodyLocator::DeclBody(member.ty.clone()),
                        prepared.kind,
                        &prepared.type_parameters,
                        &prepared.name_resolution,
                        env,
                        scope,
                        scope_payload,
                        shadowing,
                        substitutions,
                        member_context,
                        authored_resolution_debt,
                    );
                    SurfaceMember {
                        key: crate::semantic_query::AuthoredPropertyKey::from_known(key.clone()),
                        value,
                        optional: member.optional,
                        readonly: member.readonly,
                        method_kind: member.method_kind,
                        has_implementation_body: member.has_implementation_body,
                        // Declaration-domain member (prepared-decl own body):
                        // declaration materialization is never a literal origin.
                        excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                        // The `PreparedMemberFact` carries the IR member's declared
                        // accessibility verbatim, so the overlay append preserves
                        // it (Public for every non-class origin).
                        visibility: member.visibility,
                        // Spans are recovered on demand from the retained parse
                        // via the fact's span-recovery origin; any recovery miss
                        // is the honest all-absent default, never a fabricated
                        // byte range.
                        spans: member_span_memo
                            .as_ref()
                            .map(|indexed| {
                                self.ctx
                                    .recover_member_spans(&indexed.shallow_state, &member.span_origin)
                            })
                            .unwrap_or_default(),
                        declaration_origin: match &member.declaration_origin {
                            verter_type_expr::facts::DeclarationOrigin::Declared(canonical) => {
                                Some(verter_type_expr::OwnedStr::from(canonical))
                            }
                            verter_type_expr::facts::DeclarationOrigin::Synthetic => None,
                        },
                        declared_in_macro_type_arg: context.own_body_stamp(),
                        // `member_index` is the declaration's OWN-body direct
                        // member index (heritage `extends` arms are excluded), so
                        // an appended member is own-body — it SHADOWS an inherited
                        // heritage member of the same name.
                        merge_role: context.stamp_role(crate::semantic_query::MemberMergeRole::OwnBody),
                    }
                })
                .collect::<Vec<_>>();

            if added.is_empty() && !restamped_any {
                return result;
            }

            added.sort_unstable_by(|left, right| left.key.as_known().cmp(&right.key.as_known()));
            members.extend(added);
            let mut members = members.into_iter();
            let mut entries: Vec<SurfaceEntry> = surface
                .entries
                .iter()
                .map(|entry| match entry {
                    SurfaceEntry::Member(_) => SurfaceEntry::Member(
                        members.next().expect("derived member index matches stream"),
                    ),
                    other => other.clone(),
                })
                .collect();
            entries.extend(members.map(SurfaceEntry::Member));
            self.graph().intern_node_with_scope(
                SemanticNodeData::Object(SurfaceView::from_entries(
                    entries,
                    surface.keyspace,
                    surface.has_known_index_signature(),
                )),
                scope.clone(),
            )
        }
    }

    /// Read the source surface of an object-filter utility (`Pick` /
    /// `Omit`), carrier-complete.
    ///
    /// The source of `Pick<X, K>` / `Omit<X, K>` is usually a resolved
    /// `Object` after `evaluate_deferred_semantic_node_with_context` — that
    /// fast path preserves every signature kind (call / construct / index)
    /// verbatim. But a CROSS-FILE source (`Omit<ImportedBase, K>` reached
    /// from a heritage arm) lowers to a `DeclRef` / `InstantiationRef`
    /// carrier in `Navigate` / `Skeleton`, which the deferred evaluator
    /// deliberately does NOT unwrap (it would over-evaluate symbolic
    /// IndexedAccess hops — see `evaluate.rs`). For those carrier sources we
    /// read the one-level surface through the shared empty-path `Shallow`
    /// reader [`Self::resolve_typeinfo_surface_view`], which routes through the
    /// SOLE query-time resolver and returns the core [`SurfaceView`]
    /// PRESERVING call / construct / index signatures + keyspace. The `Omit`
    /// arm then carries those signatures through (TS semantics: `Omit<T, K>`
    /// filters property names only), where the old `MacroSurfaceView` reader
    /// silently dropped construct / index signatures for a carrier-sourced
    /// `Omit`. The fresh `Published(Shallow)` demand inherits the caller's
    /// orthogonal Vue heritage policy, so a runtime Pick/Omit cannot reintroduce
    /// producer-addressed ignored heritage while ordinary TypeScript callers
    /// retain it.
    fn object_filter_source_surface(
        &self,
        source_resolved: SemanticNodeId,
        caller_context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SurfaceView> {
        match self.graph().node_data(source_resolved).as_deref() {
            Some(SemanticNodeData::Object(view)) => Some(view.clone()),
            Some(
                SemanticNodeData::DeclRef { .. }
                | SemanticNodeData::InstantiationRef { .. }
                // Compound carriers — an `Intersection` / `Union` source arises
                // when the Pick/Omit source is itself a HERITAGE-bearing
                // declaration: `Omit<SelectMenuProps<T>, K>` where
                // `interface SelectMenuProps<T> extends Pick<RootProps<T>, …> { … }`
                // resolves its instantiated body to
                // `Intersection([<extends-Pick arm>, <own body>])`, NOT a flat
                // `Object`. Reading that compound surface through the SAME
                // shared empty-path Shallow reader merges the heritage arm(s)
                // with the own body into one `SurfaceView`, so the inherited
                // members survive the outer `Omit`/`Pick`. Without this arm the
                // utility collapses the heritage-bearing source to
                // `Opaque(Miss)` and every inherited member is lost (the
                // generic-Omit-of-Pick-of-generic heritage collapse).
                | SemanticNodeData::Intersection(_)
                | SemanticNodeData::Union(_),
            ) => {
                // A Pick/Omit source is never the macro-T own body — read it
                // under the structural `published(Shallow)` context.
                self.resolve_typeinfo_surface_view(
                    source_resolved,
                    crate::semantic_query::ProjectionReductionContext::published(
                        ProjectionMode::Shallow,
                    )
                    .with_orthogonal_axes_from(caller_context),
                )
            }
            _ => None,
        }
    }

    /// Drop the call/construct signatures whose Vue emit event NAME (the first
    /// parameter's string-literal type — or each literal of a union first
    /// parameter) is in `omit_set`. A signature whose first parameter is not a
    /// string literal, or whose event name is not omitted, is kept verbatim.
    ///
    /// This is the call-signature analogue of property-name `Omit`: a Vue emit
    /// interface declares each event as a call signature `(e: 'name', …): void`,
    /// so omitting `'name'` must remove that signature. The event-name read uses
    /// the SAME first-parameter-literal rule the emit normalizer
    /// (`emits_from_typeinfo_surface`) uses, so the two agree on which signatures
    /// represent which events.
    fn filter_omitted_event_signatures(
        &self,
        signatures: &[SemanticNodeId],
        omit_set: &FxHashSet<&str>,
    ) -> Arc<[SemanticNodeId]> {
        let kept: Vec<SemanticNodeId> = signatures
            .iter()
            .filter(|sig| {
                // Keep the signature unless EVERY event name it declares is
                // omitted (a single signature can declare a union of event
                // names; only drop it when all are omitted, mirroring how the
                // normalizer would surface the surviving names).
                match self.call_signature_event_names(**sig) {
                    Some(names) if !names.is_empty() => {
                        !names.iter().all(|name| omit_set.contains(name.as_ref()))
                    }
                    // No string-literal event name → not an omittable emit
                    // signature; keep it (general TS `Omit` leaves it intact).
                    _ => true,
                }
            })
            .copied()
            .collect();
        Arc::from(kept.into_boxed_slice())
    }

    /// The Vue emit event name(s) a call/construct signature declares — its
    /// first parameter's string-literal type, or each literal of a union first
    /// parameter. `None` when the node is not a `Function`, has no parameters,
    /// or the first parameter is not a string-literal (union). Mirrors the
    /// first-parameter event-name rule in `emits_from_typeinfo_surface`.
    fn call_signature_event_names(&self, sig: SemanticNodeId) -> Option<Vec<Arc<str>>> {
        let data = self.graph().node_data(sig)?;
        // CALL kind only: a construct signature never declares a Vue emit
        // event, so it is never an omittable emit signature (kept verbatim
        // by the Omit filter, exactly like any non-emit signature).
        let SemanticNodeData::Signature {
            kind: crate::semantic_query::SignatureKind::Call,
            params,
            ..
        } = data.as_ref()
        else {
            return None;
        };
        let first = params.first()?;
        let mut names = Vec::new();
        self.collect_string_literal_names(first.ty, &mut names);
        if names.is_empty() {
            None
        } else {
            Some(names)
        }
    }

    /// Push the string-literal value(s) carried by `node` into `out` — the node
    /// itself when it is a `Literal(String)`, or each `Literal(String)` arm when
    /// it is a `Union`. A `Union` arm that is not a string literal is skipped
    /// (the surrounding event-name rule only recognises string literals).
    fn collect_string_literal_names(&self, node: SemanticNodeId, out: &mut Vec<Arc<str>>) {
        let resolved = self.evaluate_deferred_semantic_node(node);
        let Some(data) = self.graph().node_data(resolved) else {
            return;
        };
        match data.as_ref() {
            SemanticNodeData::Literal(LiteralValue::String(name)) => {
                out.push(Arc::from(name.as_str()))
            }
            SemanticNodeData::Union(members) => {
                for member in members.iter() {
                    self.collect_string_literal_names(*member, out);
                }
            }
            _ => {}
        }
    }

    /// Built-in utility dispatch.
    ///
    /// Routes recognised utility names (`Partial`, `Required`, `Readonly`,
    /// `Record`, `NoInfer`, string intrinsics, etc.) through the same
    /// `SemanticQueryKey::{MappedType, ProjectMember, ProjectPath, Normalize}`
    /// dispatch as userland aliases. Userland equivalence rule: a userland
    /// alias `type MyPartial<T> = { [K in keyof T]?: T[K] }` and the
    /// built-in `Partial<T>` produce the same `SemanticNodeId` and the
    /// same origin-edge structure when they route through the same
    /// `MappedType` dispatch key.
    ///
    /// Utilities are classified into three groups by implementation shape:
    ///
    /// - **Mapper-based** (`Partial`, `Required`, `Readonly`, `Record`):
    ///   synthesise a `MapperKey` whose modifiers encode the utility
    ///   transformation and dispatch through `SemanticQueryKey::MappedType`.
    ///   The resulting node is shared with any userland mapped type that
    ///   happens to produce an equivalent `MapperKey` because the memo
    ///   dedups on the full key.
    /// - **Identity** (`NoInfer`): returns the first argument as an `Alias`
    ///   node, emitting `Instantiate` + `SubstituteTypeParam` +
    ///   `AliasResolve` edges.
    /// - **Object-filter** (`Pick`, `Omit`): produce an Object surface
    ///   filtered by enumerable key set; preserve modifier flags +
    ///   (for `Omit`) source signatures.
    /// - **Union-filter** (`Extract`, `Exclude`): per-member
    ///   assignability via the relation authority (`execute_relate_pair`); survivors reconstituted via
    ///   `intern_normalized_union_or_intersection` so empty and
    ///   singleton surviving sets canonicalise to `Never` / the lone
    ///   member respectively. This closes the literal-type reduction;
    ///   non-literal arms still fall through to the deferred shell.
    /// - **Awaited**: routed by the proven `BuiltinUtility::Awaited`
    ///   identity to the LIB conditional (`lib_awaited_node`) — never the
    ///   compiler's `AwaitedNormalize` relation, which types malformed
    ///   thenables differently. A deferred application keeps the authored
    ///   carrier.
    /// - **Opaque** (`NonNullable`, function-signature
    ///   utilities when the argument shape does not match, string
    ///   intrinsics with a broad/open carrier): return a shell anchored
    ///   to the utility + arg identity with `Instantiate` +
    ///   `SubstituteTypeParam` edges. The shell's body is lazy —
    ///   callers projecting into it follow the normal `ProjectPath`
    ///   route which terminates with `Miss` until a later track
    ///   implements the full shape. String intrinsics reduce
    ///   literal/union inputs to the transformed literal/union
    ///   (`Uppercase<"a">`→`"A"`, distributing over unions); only a
    ///   broad/open carrier (`string`/non-literal) widens to `String`,
    ///   and a bare `TypeParam` is preserved as an `InstantiationRef`
    ///   carrier.
    ///
    /// Every utility path emits the `Instantiate` edge with sources
    /// `[base, args...]` and per-arg `SubstituteTypeParam` edges so the
    /// origin graph is walkable end-to-end.
    pub(super) fn build_builtin_utility(
        &self,
        base: SemanticNodeId,
        name: &str,
        // The PROVEN builtin identity, resolved by the caller AFTER the
        // shadowing/resolution gate. The `Awaited` relation routes on this
        // identity; the other utilities still route on `name` below (they
        // sit behind the same gate), and `name` also labels the origin-edge
        // type parameters.
        utility: Option<BuiltinUtility>,
        args: &Arc<[SemanticNodeId]>,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> (
        QueryResult<SemanticNodeId>,
        DepSignature,
        bool,
        Option<super::projection_fact::ProjectionInterpretation>,
    ) {
        use crate::semantic_query::{MapperKey, OptionalityMod, ReadonlyMod};

        let graph = self.graph();
        let fence = self.project_generation_signature();
        self.graph().record_instantiate();

        // Two-signal taxonomy fold. The mapper-based
        // utilities (`Partial` / `Required` / `Readonly` / `Record` and
        // the shared `keyof source` reification) surface their result
        // through nested `KeyOf` / `MappedType` subqueries. When such a
        // nested subquery is GENUINELY INCOMPLETE — budget exceeded,
        // same-path recursion, walker fatal/pathological — the utility's
        // produced surface is itself partial even though it surfaces as a
        // complete-looking `QueryResult::Value` (an `Opaque(Miss)` shell).
        // `result_is_partial` accumulates that partiality across every
        // nested read so the cold-build helper can mark the published
        // value partial and the component-meta / shape / materialize warm
        // gates refuse it. A benign non-cacheable nested read (signature
        // overflow, unrootable, ReturnOnly) is COMPLETE — it does NOT set
        // this flag (it only blocks the inner memo via `cache_suppress`).
        let result_is_partial = std::cell::Cell::new(false);

        // Look up the utility's real TS type-parameter names so
        // `SubstituteTypeParam` edges carry names identical to those
        // the userland-equivalent alias would emit. `Partial<T>` and
        // `type MyPartial<T> = ...` both produce
        // `SubstituteTypeParam("T", arg)` — a synthesised `"T0"`-style
        // name would break origin-walk equivalence.
        let param_names = utility_param_names(name);

        // Helper: emit the common `Instantiate` + per-arg
        // `SubstituteTypeParam` edges on a utility result node.
        let record_utility_edges = |result_id: SemanticNodeId| {
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                result_id,
                OriginEdgeKind::Instantiate,
                std::iter::once(base).chain(args.iter().copied()).collect(),
                OriginMeta::None,
                fence.clone(),
            );
            for (idx, arg_id) in args.iter().enumerate() {
                // Use the utility's declared type-parameter name when
                // known; fall back to a positional label only for
                // unknown utilities (which return Opaque anyway).
                crate::semantic_query_memo::record_origin_edge!(
                    graph,
                    result_id,
                    OriginEdgeKind::SubstituteTypeParam,
                    Arc::from([*arg_id]),
                    OriginMeta::SubstitutedParam(verter_type_expr::OwnedStr::from(
                        param_names
                            .get(idx)
                            .map(|n| Arc::<str>::from(*n))
                            .unwrap_or_else(|| Arc::<str>::from(format!("T{idx}"))),
                    )),
                    fence.clone(),
                );
            }
        };

        // ---- the lib Awaited CONDITIONAL, by PROVEN IDENTITY ----
        // Decided by the typed `BuiltinUtility` the caller proved after the
        // shadowing/resolution gate — never by spelling. A userland
        // `type Awaited<T>` never reaches here at all (the gate classifies it
        // `BuiltinUtilityResolution::Shadowed`).
        //
        // An authored `Awaited<T>` is the LIB conditional, not the compiler's
        // runtime awaited relation: they agree on promises and valid
        // thenables but not on malformed ones (`Awaited<{ then(): void }>` is
        // `never`, where `await` of the same value is `any`), so this reads
        // `lib_awaited_node` and never the `AwaitedNormalize` family. A
        // deferred application keeps the authored carrier.
        if matches!(utility, Some(BuiltinUtility::Awaited)) && args.len() == 1 {
            let result = match self.lib_awaited_node(args[0]) {
                LibAwaited::Reduced(node) => node,
                LibAwaited::Deferred => self.lib_awaited_carrier(args[0]),
                LibAwaited::Refused => self.opaque(QueryError::Miss),
            };
            record_utility_edges(result);
            return (QueryResult::Value(result), fence, false, None);
        }

        // Mapper-based utilities route through `SemanticQueryKey::MappedType`.
        // The mapper's `value_expr` is an `Opaque(Miss)` shell marker, never
        // a substitution target: these mappers classify as
        // `MapperKind::Identity`, and every Identity per-key producer reads
        // the matching source member's value directly or dispatches
        // `source[K]` through the shared `IndexedAccess` query.
        let mapper_for = |opt: OptionalityMod, ro: ReadonlyMod, source: SemanticNodeId| {
            // Thread the outer instantiation's context so a builtin
            // utility called under `StructuralTransit` (e.g.
            // `Partial<Record<keyof T, undefined>>` reached through a
            // relation-engine `infer`-binding pass) does NOT reify
            // `keyof source` into a literal-anchor union.
            let key_space_read = self.execute_read(SemanticQueryKey::KeyOf {
                base: source,
                context,
            });
            // FOLD: a genuinely-incomplete nested KeyOf (budget /
            // recursion / walker-fatal) taints the utility surface.
            if key_space_read.result_is_partial() {
                result_is_partial.set(true);
            }
            let key_space = match key_space_read.value {
                QueryResult::Value(node) => node,
                _ => self.opaque(QueryError::Miss),
            };
            // Shell marker only — no per-key producer reads an Identity
            // mapper's `value_expr`. `build_mapped_type` reuses a matching
            // source member's value directly; a key without a projectable
            // source member dispatches `source[K]` through the shared
            // `IndexedAccess` query, publishing the addressable deferred
            // `IndexedAccess` carrier when the access cannot close.
            let value_expr = self.opaque(QueryError::Miss);
            // Synthesise a TypeParam binder node for the utility
            // mapper's `K`: the param_index is the
            // source SemanticNodeId itself (truncated to u16) so
            // two utility invocations on the SAME source share
            // the SAME binder identity → same `MapperKey` → same
            // `SemanticQueryKey::MappedType` cache key. Distinct
            // sources naturally get distinct ordinals via the
            // SemanticNodeId.
            //
            // For sources whose SemanticNodeId exceeds u16 the
            // truncated ordinals can theoretically collide, but
            // the arena dedup also includes the `display_name`,
            // `decl`, and `constraint` fields — two utility
            // mappers with the same display_name + decl that
            // happen to alias at u16 are extremely unlikely AND
            // the failure mode is "two mappers share a binder
            // SemanticNodeId" which causes a substitute walk to
            // bind the same K for both — semantically benign
            // because the consumer's source-keyed dispatch
            // remains source-specific via the outer
            // `SemanticQueryKey::MappedType.source`.
            let param_index = (source.0 & 0xFFFF) as u16;
            let parameter_node = self.graph().intern_node(SemanticNodeData::TypeParam {
                decl: crate::semantic_query::DeclIdentity {
                    canonical_id: verter_type_expr::OwnedStr::from("<utility>"),
                    owner: verter_type_expr::TopLevelOwnerId::ordinary_file(),
                    whole_hash: crate::semantic_query::HashValue::default(),
                    decl_name: verter_type_expr::OwnedStr::from("<utility-mapper>"),
                },
                param_index,
                constraint: None,
                default: None,
                display_name: OwnedStr::from("K"),
            });
            MapperKey {
                parameter_node,
                key_space,
                value_expr,
                optionality: opt,
                readonly: ro,
                name_remap: None,
                // Partial / Required / Readonly are the canonical
                // `{ [K in keyof T]: T[K] }` mappers — classify them
                // as `Identity` explicitly. The placeholder
                // `value_expr = Miss` is a shell marker (the build
                // path never reads it for Identity mappers; it reads
                // source member values directly), not a
                // runtime-discoverable `T[K]` shape.
                kind: crate::semantic_query::MapperKind::Identity,
                // `{ [K in keyof T]…: T[K] }` over the utility's own `T`.
                over_type_variable: true,
                modifiers_type: None,
            }
        };

        // Degenerate-operand short-circuit (shared §22-style table in
        // `absorb.rs`). A DIRECT lattice-extreme source operand resolves the
        // utility before any signature walk / keyspace enumeration / mapped
        // dispatch / per-arm relation runs — `ReturnType<any>` is `any`
        // without consulting call signatures, `Exclude<any, U>` is `any`
        // without entering the relation loop. Non-degenerate operands fall
        // through to the structural arms below unchanged.
        if let Some(absorbed) = self.absorb_builtin_utility_degenerate(name, args.as_ref()) {
            record_utility_edges(absorbed);
            return (QueryResult::Value(absorbed), fence, false, None);
        }

        // ---- Function-signature utilities ----
        // One keyed read over the shared signature list: the subject settles
        // at this demand point (a decl-placeholder / alias-shell / `DeclRef`
        // carrier argument resolves to its signature-bearing surface), a union
        // subject distributes arm by arm under the same context, and the
        // utility infers from it. An unanswerable subject publishes the opaque
        // shell so downstream consumers still see an `Instantiate` edge
        // anchored to the utility identity.
        if let (Some(utility), [subject]) = (
            super::signature_utility::SignatureUtility::from_builtin_name(name),
            args.as_ref(),
        ) {
            let source_resolved = self.resolve_signature_source_carrier(*subject, context);
            let result = self.resolve_signature_utility(utility, source_resolved, context);
            let approximation = result
                .is_some()
                .then_some(super::projection_fact::ProjectionInterpretation::Positional);
            let result = result.unwrap_or_else(|| self.opaque(QueryError::Miss));
            record_utility_edges(result);
            return (QueryResult::Value(result), fence, false, approximation);
        }

        match name {
            // ---- Mapper-based utilities ----
            "Partial" if args.len() == 1 => {
                let source = args[0];
                let mapper = mapper_for(OptionalityMod::Add, ReadonlyMod::Keep, source);
                let mapped_read = self.execute_read(SemanticQueryKey::MappedType {
                    source,
                    mapper,
                    context,
                });
                let approximation = matches!(mapped_read.value, QueryResult::Value(_))
                    .then_some(super::projection_fact::ProjectionInterpretation::PresenceOnly);
                if mapped_read.result_is_partial() {
                    result_is_partial.set(true);
                }
                let result = match mapped_read.value {
                    QueryResult::Value(node) => node,
                    _ => self.opaque(QueryError::Miss),
                };
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    result_is_partial.get(),
                    approximation,
                )
            }
            "Required" if args.len() == 1 => {
                let source = args[0];
                let mapper = mapper_for(OptionalityMod::Remove, ReadonlyMod::Keep, source);
                let mapped_read = self.execute_read(SemanticQueryKey::MappedType {
                    source,
                    mapper,
                    context,
                });
                let approximation = matches!(mapped_read.value, QueryResult::Value(_))
                    .then_some(super::projection_fact::ProjectionInterpretation::PresenceOnly);
                if mapped_read.result_is_partial() {
                    result_is_partial.set(true);
                }
                let result = match mapped_read.value {
                    QueryResult::Value(node) => node,
                    _ => self.opaque(QueryError::Miss),
                };
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    result_is_partial.get(),
                    approximation,
                )
            }
            "Readonly" if args.len() == 1 => {
                let source = args[0];
                let mapper = mapper_for(OptionalityMod::Keep, ReadonlyMod::Add, source);
                let mapped_read = self.execute_read(SemanticQueryKey::MappedType {
                    source,
                    mapper,
                    context,
                });
                let approximation = matches!(mapped_read.value, QueryResult::Value(_))
                    .then_some(super::projection_fact::ProjectionInterpretation::PresenceOnly);
                if mapped_read.result_is_partial() {
                    result_is_partial.set(true);
                }
                let result = match mapped_read.value {
                    QueryResult::Value(node) => node,
                    _ => self.opaque(QueryError::Miss),
                };
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    result_is_partial.get(),
                    approximation,
                )
            }
            "Record" if args.len() == 2 => {
                // Record<K, V>: map K's key space to V.
                let key_arg = args[0];
                let value_arg = args[1];
                // Key space is K itself (usually a union of literals).
                // For equivalence with userland `{ [P in K]: V }`, both
                // paths set `key_space = K` and `value_expr = V`.
                // Synthesise a TypeParam binder node id for `P`.
                //
                // The param_index is derived from
                // (key_arg, value_arg) so two `Record<K, V>`
                // invocations on the same K, V share the SAME
                // binder identity → same `MapperKey` → same
                // `SemanticQueryKey::MappedType` cache key.
                let param_index = ((key_arg.0 ^ value_arg.0.rotate_left(8)) & 0xFFFF) as u16;
                let parameter_node = self.graph().intern_node(SemanticNodeData::TypeParam {
                    decl: crate::semantic_query::DeclIdentity {
                        canonical_id: verter_type_expr::OwnedStr::from("<utility>"),
                        owner: verter_type_expr::TopLevelOwnerId::ordinary_file(),
                        whole_hash: crate::semantic_query::HashValue::default(),
                        decl_name: verter_type_expr::OwnedStr::from("<utility-mapper>"),
                    },
                    param_index,
                    constraint: None,
                    default: None,
                    display_name: OwnedStr::from("P"),
                });
                let mapper = MapperKey {
                    parameter_node,
                    key_space: key_arg,
                    value_expr: value_arg,
                    optionality: OptionalityMod::Keep,
                    readonly: ReadonlyMod::Keep,
                    name_remap: None,
                    // `Record<K, V>` maps every key to the same `V`
                    // expression — a computed projection, not the
                    // identity `T[K]`. Tag as `Computed` so
                    // `build_mapped_type` takes the substitute +
                    // evaluate path.
                    kind: crate::semantic_query::MapperKind::Computed,
                    over_type_variable: false,
                    // `K extends keyof any`: no modifiers.
                    modifiers_type: None,
                };
                // Source is K; `build_mapped_type` reads names from K's
                // keyspace branch when the source isn't an Object.
                let mapped_read = self.execute_read(SemanticQueryKey::MappedType {
                    source: key_arg,
                    mapper,
                    context,
                });
                let approximation = matches!(mapped_read.value, QueryResult::Value(_))
                    .then_some(super::projection_fact::ProjectionInterpretation::PresenceOnly);
                if mapped_read.result_is_partial() {
                    result_is_partial.set(true);
                }
                let result = match mapped_read.value {
                    QueryResult::Value(node) => node,
                    _ => self.opaque(QueryError::Miss),
                };
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    result_is_partial.get(),
                    approximation,
                )
            }

            // ---- Identity utility ----
            // `NoInfer<T>` over a generic operand is the compiler's
            // `NoInfer` application (no inference site for a call's type
            // parameters); over any other operand it is the operand
            // (`getNoInferType`).
            "NoInfer" if args.len() == 1 && self.type_is_generic(args[0]) => {
                let result = graph.intern_node(
                    SemanticNodeData::intrinsic_application(
                        crate::semantic_query::CompilerIntrinsicTypeOp::NoInfer,
                        Arc::clone(args),
                    )
                    .expect("one operand"),
                );
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }
            "NoInfer" if args.len() == 1 => {
                let source = args[0];
                let result = graph.intern_node(SemanticNodeData::Alias(source));
                crate::semantic_query_memo::record_origin_edge!(
                    graph,
                    result,
                    OriginEdgeKind::AliasResolve,
                    Arc::from(vec![source].into_boxed_slice()),
                    OriginMeta::None,
                    fence.clone(),
                );
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }

            // ---- String intrinsics ----
            // `Uppercase` / `Lowercase` / `Capitalize` / `Uncapitalize` are
            // the checker's `getStringMappingType` over the operand the
            // application denotes where written — see
            // [`Self::apply_string_intrinsic`]. Typed-IR only: the case
            // transform applies to interned literal values, never to source
            // or display text.
            "Uppercase" | "Lowercase" | "Capitalize" | "Uncapitalize" if args.len() == 1 => {
                let result = self.apply_string_intrinsic(name, args[0], context);
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }

            // ---- Object-filter utilities ----
            // `Pick<X, K>` produces an Object surface containing the
            // subset of `X`'s members whose names appear in `K`'s
            // enumerable key space. `Omit<X, K>` is the inverse —
            // members of `X` whose names are NOT in `K`. Both
            // implementations preserve the source's per-member
            // optional / readonly / is_method flags so downstream
            // path-walking lands on the same value SemanticNodeIds
            // a userland-equivalent definition would emit.
            //
            // When `K` cannot be enumerated (e.g. still a TypeParam
            // or deferred shell) OR `X` does not resolve to an
            // Object surface, the utility falls through to the
            // deferred shell so callers re-dispatch once the inputs
            // become enumerable.
            "Pick" if args.len() == 2 => {
                let source = args[0];
                let keys_arg = args[1];
                let pick_names = match self.key_names_from_keyspace_node(keys_arg) {
                    Some(names) => names,
                    None => {
                        let result = self.opaque(QueryError::Miss);
                        record_utility_edges(result);
                        return (QueryResult::Value(result), fence, false, None);
                    }
                };
                // Context-propagating deferred
                // resolution. Under `StructuralTransit(_)` the source's
                // nested operators carrier-stop (`may_reduce_operator
                // (StructuralTransit(_)) == false`); the Pick falls through
                // to its deferred shell (Opaque(Miss)) so callers re-
                // dispatch once admission lifts to publication demand.
                // Closes the V chain leak empirically traced to this
                // call (`evaluate_deferred_semantic_node` defaulted to
                // `Published(Expanded)`, breaking context propagation
                // when the outer caller dispatched with
                // `StructuralTransit(Shallow)`).
                let source_resolved = self
                    .evaluate_deferred_semantic_node_with_context(
                        source,
                        context.with_mode(ProjectionMode::Shallow),
                    )
                    .into_active_query_build_node(self);
                // `Pick<any, K>` (pinned tsgo): a CLOSED surface holding
                // exactly the enumerated keys, each `any` and required —
                // `Pick<any, "x">` = `{ x: any }`, `Pick<any, never>` = `{}`.
                // Materialised AFTER key enumeration because the result
                // depends on K (a non-enumerable K already deferred above);
                // the source-side `any` check sits here, not in the absorb
                // table, for the same reason.
                if matches!(
                    self.peek_special(source_resolved),
                    Some((super::absorb::SpecialKind::Any, _))
                ) {
                    let any_node = graph.intern_node(SemanticNodeData::Primitive(
                        crate::semantic_query::PrimitiveKind::Any,
                    ));
                    let members: Vec<SurfaceMember> = pick_names
                        .iter()
                        .map(|key| SurfaceMember {
                            key: crate::semantic_query::AuthoredPropertyKey::from_known(
                                key.clone(),
                            ),
                            value: any_node,
                            optional: false,
                            readonly: false,
                            method_kind: None,
                            has_implementation_body: false,
                            visibility: verter_type_expr::MemberVisibility::Public,
                            // Synthetic mapped-produced members are never a
                            // literal origin.
                            excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                            // Synthetic mapped-produced members: no single
                            // source declaration site.
                            spans: verter_type_expr::MemberSpans::default(),
                            declaration_origin: None,
                            declared_in_macro_type_arg:
                                crate::semantic_query::MacroOwnBodyStamp::NEUTRAL,
                            merge_role: crate::semantic_query::MergeRoleStamp::NEUTRAL,
                        })
                        .collect();
                    let result_surface = SurfaceView::from_members(members, None);
                    let result = graph.intern_node(SemanticNodeData::Object(result_surface));
                    record_utility_edges(result);
                    return (QueryResult::Value(result), fence, false, None);
                }
                let surface = match self.object_filter_source_surface(source_resolved, context) {
                    Some(view) => view,
                    None => {
                        let result = self.opaque(QueryError::Miss);
                        record_utility_edges(result);
                        return (QueryResult::Value(result), fence, false, None);
                    }
                };
                let pick_set: FxHashSet<&PropertyKey> = pick_names.iter().collect();
                // `Pick<C, K>` is a PUBLIC-keyspace projection (TS:
                // `Pick<T, K extends keyof T>`, and `keyof ClassType` excludes
                // protected/private members). Filter non-public source members
                // BEFORE the name predicate so a `Pick` whose key names a
                // non-public class member yields an empty surface rather than
                // re-minting the non-public member — the same public-only
                // keyspace `source_members_for_published_projection` /
                // `build_key_of` apply. The full member set (incl. non-public)
                // stays recorded on the source surface for the keep-all
                // `native_props` carrier; only this DERIVATION is gated.
                // An accessor is selected by its property's `keyof` key, so
                // `get 1` / `set "1"` are picked together as one property.
                let selection =
                    crate::semantic_query::AccessorSelectionKeys::of(surface.positive_members());
                let picked: Vec<SurfaceMember> = surface
                    .positive_members()
                    .iter()
                    .filter(|m| m.visibility.is_public())
                    .filter(|m| {
                        selection
                            .selection_key(m)
                            .is_some_and(|key| pick_set.contains(&key))
                    })
                    .map(crate::semantic_query::SurfaceMember::clone)
                    .collect();
                // `Pick` is a mapping over the source's properties: an
                // accessor maps as the property it is.
                let picked = crate::semantic_query::members_with_accessors_as_properties(
                    picked,
                    &self.graph(),
                    |signature| self.materialize_returned_callable(signature),
                );
                let result_surface = SurfaceView::from_members(picked, None);
                let result = graph.intern_node(SemanticNodeData::Object(result_surface));
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    false,
                    Some(super::projection_fact::ProjectionInterpretation::PresenceOnly),
                )
            }
            "Omit" if args.len() == 2 => {
                let source = args[0];
                let keys_arg = args[1];
                let omit_names = match self.key_names_from_keyspace_node(keys_arg) {
                    Some(names) => names,
                    None => {
                        let result = self.opaque(QueryError::Miss);
                        record_utility_edges(result);
                        return (QueryResult::Value(result), fence, false, None);
                    }
                };
                // Context-propagating deferred
                // resolution (see Pick comment above for chain).
                let source_resolved = self
                    .evaluate_deferred_semantic_node_with_context(
                        source,
                        context.with_mode(ProjectionMode::Shallow),
                    )
                    .into_active_query_build_node(self);
                // `Omit<any, K-literals>` (pinned tsgo): the index-signature
                // surface `{ [x: string]: any; [x: number]: any;
                // [x: symbol]: any }`, independent of WHICH literal keys are
                // omitted (excluding finite literals from the broad key
                // domain removes nothing). A non-enumerable K (e.g.
                // `Omit<any, string>`, whose tsgo result drops the string
                // signature) already deferred above.
                if matches!(
                    self.peek_special(source_resolved),
                    Some((super::absorb::SpecialKind::Any, _))
                ) {
                    let result = self.any_index_signature_object(&[
                        crate::semantic_query::PrimitiveKind::String,
                        crate::semantic_query::PrimitiveKind::Number,
                        crate::semantic_query::PrimitiveKind::Symbol,
                    ]);
                    record_utility_edges(result);
                    return (QueryResult::Value(result), fence, false, None);
                }
                let surface = match self.object_filter_source_surface(source_resolved, context) {
                    Some(view) => view,
                    None => {
                        let result = self.opaque(QueryError::Miss);
                        record_utility_edges(result);
                        return (QueryResult::Value(result), fence, false, None);
                    }
                };
                let omit_set: FxHashSet<&PropertyKey> = omit_names
                    .iter()
                    .inspect(|_| {
                        #[cfg(any(test, feature = "test-support"))]
                        OMIT_KEY_FILTER_STEPS.with(|count| count.set(count.get() + 1));
                    })
                    .collect();
                let omitted_event_names: FxHashSet<&str> = omit_names
                    .iter()
                    .filter_map(PropertyKey::as_string)
                    .collect();
                // `Omit<C, K>` = `Pick<C, Exclude<keyof C, K>>` — a PUBLIC-keyspace
                // projection. Filter non-public source members BEFORE the name
                // predicate so an `Omit` over a class never LEAVES a non-public
                // member published (the keyspace `Omit` derives from is
                // public-only). The non-public members stay recorded on the
                // source surface for the keep-all `native_props` carrier; only
                // this derivation is gated.
                // `Omit<T, K>` over a property surface leaves call/construct
                // signatures intact (TS mapped-type semantics touch only named
                // properties). For a Vue EMIT interface the events are call
                // signatures whose first parameter is a string-literal event
                // NAME, so omitting an event name must drop the matching call
                // signature(s) — the call-sig event name is the conceptual key.
                // A signature whose first parameter is NOT a string literal in
                // `omit_set` (any non-emit call signature) is unaffected.
                let kept_call_signatures = self.filter_omitted_event_signatures(
                    &surface.call_signatures,
                    &omitted_event_names,
                );
                let kept_construct_signatures = self.filter_omitted_event_signatures(
                    &surface.construct_signatures,
                    &omitted_event_names,
                );
                // An accessor is omitted by its property's `keyof` key, so
                // `get 1` / `set "1"` are omitted together as one property.
                let omit_selection = crate::semantic_query::AccessorSelectionKeys::of(
                    surface.entries.iter().filter_map(|entry| match entry {
                        SurfaceEntry::Member(member) => Some(member),
                        _ => None,
                    }),
                );
                let entries: Vec<SurfaceEntry> = surface
                    .entries
                    .iter()
                    .filter_map(|entry| match entry {
                        SurfaceEntry::Member(member)
                            if member.visibility.is_public()
                                && omit_selection.selection_key(member).is_none_or(|key| {
                                    #[cfg(any(test, feature = "test-support"))]
                                    OMIT_KEY_FILTER_STEPS.with(|count| count.set(count.get() + 1));
                                    !omit_set.contains(&key)
                                }) =>
                        {
                            Some(entry.clone())
                        }
                        SurfaceEntry::CallSignature(signature)
                            if kept_call_signatures.contains(signature) =>
                        {
                            Some(entry.clone())
                        }
                        SurfaceEntry::ConstructSignature(signature)
                            if kept_construct_signatures.contains(signature) =>
                        {
                            Some(entry.clone())
                        }
                        SurfaceEntry::IndexSignature(_) => Some(entry.clone()),
                        _ => None,
                    })
                    .collect();
                // `Omit` is a mapping over the source's kept properties: an
                // accessor maps as the property it is.
                let has_accessor = entries.iter().any(|entry| {
                    matches!(entry, SurfaceEntry::Member(member)
                        if crate::semantic_query::is_public_accessor(member))
                });
                let kept_members: Vec<SurfaceMember> = if has_accessor {
                    entries
                        .iter()
                        .filter_map(|entry| match entry {
                            SurfaceEntry::Member(member) => Some(member.clone()),
                            _ => None,
                        })
                        .collect()
                } else {
                    Vec::new()
                };
                let entries = match crate::semantic_query::accessor_property_slots(
                    &kept_members,
                    &self.graph(),
                    |signature| self.materialize_returned_callable(signature),
                ) {
                    Some(slots) => {
                        let mut slots = slots.into_iter();
                        entries
                            .into_iter()
                            .filter_map(|entry| match entry {
                                SurfaceEntry::Member(_) => {
                                    slots.next().flatten().map(SurfaceEntry::Member)
                                }
                                other => Some(other),
                            })
                            .collect()
                    }
                    None => entries,
                };
                let result_surface = SurfaceView::from_entries(
                    entries,
                    surface.keyspace,
                    surface.has_known_index_signature(),
                );
                let result = graph.intern_node(SemanticNodeData::Object(result_surface));
                record_utility_edges(result);
                (
                    QueryResult::Value(result),
                    fence,
                    false,
                    Some(super::projection_fact::ProjectionInterpretation::PresenceOnly),
                )
            }

            // ---- Union-filter utilities ----
            // `Extract<T, U>` keeps each member of `T`'s union that is
            // assignable to `U`; `Exclude<T, U>` keeps each member that
            // is NOT assignable to `U`. Both delegate per-member
            // assignability to the sole relation authority (`execute_relate_pair`),
            // which already decides literal-vs-literal equality
            // (`literals_equal`) plus the broader assignability
            // lattice. The reduction reconstitutes the survivors as a
            // canonical Union via
            // `intern_normalized_union_or_intersection`, which yields
            // `Primitive(Never)` for an empty survivor set and the
            // single member directly for a one-element survivor.
            //
            // When the source `T` does not resolve to a Union /
            // Literal / Primitive after `evaluate_deferred_semantic_node`
            // OR any per-member relation returns `Unknown`, the
            // utility falls through to the deferred shell so callers
            // re-dispatch once the inputs become decidable. This
            // preserves the prior `Opaque(Miss)` semantics for
            // genuinely-undecidable shapes (TypeParam, Conditional
            // shells, opaque carriers) while closing the literal-type
            // case the `mapped_types` seed exercises.
            //
            // `Exclude<U, F>` / `Extract<U, F>` concrete-literal
            // reduction. The relation engine's union-distribution path
            // already handles each per-member judgement; this arm
            // composes those judgements into the utility's result.
            "Extract" | "Exclude" if args.len() == 2 => {
                let source_arg = args[0];
                let filter_arg = args[1];
                // Context-propagating resolution (see Pick comment above for
                // chain). A declaration carrier settles to what it declares,
                // so an application that is a union (`Partial<A | B>`)
                // distributes like one.
                let source_resolved = self.resolve_signature_source_carrier(source_arg, context);

                // A `keyof` whose keys settle IS that key union
                // (`Exclude<keyof Box<string>, "size">` filters
                // `"value" | "size"`).
                let keyof_base = match graph.node_data(source_resolved).as_deref() {
                    Some(SemanticNodeData::KeyOf { base }) => Some(*base),
                    _ => None,
                };
                let source_resolved = keyof_base
                    .and_then(|base| self.key_set_of(base))
                    .unwrap_or(source_resolved);
                // The FILTER operand resolves through the same deferred
                // evaluator: a carrier filter (`R` still a reference shell)
                // would judge every per-member relation `Unknown` and defer
                // the whole utility even when the source is fully settled.
                let filter_resolved = self
                    .evaluate_deferred_semantic_node_with_context(filter_arg, context)
                    .into_active_query_build_node(self);
                // A refused operand is the operation's recovery, not an
                // undecidable source to turn into a semantic miss. Keep its
                // diagnostic and resource partial through every enclosing alias.
                if let Some(recovery) =
                    [source_resolved, filter_resolved].into_iter().find(|node| {
                        matches!(
                            graph.node_data(*node).as_deref(),
                            Some(SemanticNodeData::Opaque(QueryError::CheckerRecovery {
                                basis: crate::semantic_query::RecoveryBasis::Budget,
                                ..
                            }))
                        )
                    })
                {
                    self.fold_local_partial_completeness(
                        crate::semantic_query::PartialReasonSet::OPERATION_BUDGET,
                    );
                    record_utility_edges(recovery);
                    return (
                        QueryResult::Value(recovery),
                        fence,
                        true,
                        Some(crate::semantic_query::FactInterpretation::CheckerRecovery),
                    );
                }
                let source_data = graph.node_data(source_resolved);
                let arms: Vec<SemanticNodeId> = match source_data.as_deref() {
                    Some(SemanticNodeData::Union(members)) => members.iter().copied().collect(),
                    // A settled non-union type is the one constituent the
                    // distribution filters.
                    Some(
                        SemanticNodeData::Literal(_)
                        | SemanticNodeData::Primitive(_)
                        | SemanticNodeData::Object(_)
                        | SemanticNodeData::Array { .. }
                        | SemanticNodeData::Tuple { .. }
                        | SemanticNodeData::Signature { .. }
                        | SemanticNodeData::TemplateLiteral { .. },
                    ) => {
                        vec![source_resolved]
                    }
                    _ => {
                        // Source did not resolve to a decidable shape;
                        // fall through to the deferred shell.
                        let result = self.opaque(QueryError::Miss);
                        record_utility_edges(result);
                        return (QueryResult::Value(result), fence, false, None);
                    }
                };
                // A single constituent that survives is the source as
                // written (`Extract<Face, { a: 1 }>` is `Face`).
                let single = !matches!(source_data.as_deref(), Some(SemanticNodeData::Union(_)));
                drop(source_data);
                let keep_assignable = name == "Extract";
                let mut survivors: Vec<SemanticNodeId> = Vec::with_capacity(arms.len());
                let written = |arm: SemanticNodeId| if single { source_arg } else { arm };
                for arm in arms.iter().copied() {
                    // Per-arm routing through the SOLE relation authority
                    // (`execute(Relate)`); an undecided arm defers the whole
                    // reduction, never treated as negative.
                    match self.execute_relate_pair(arm, filter_resolved) {
                        crate::project_semantic_dispatch::dispatch_txn::RelationStep::Assignable {
                            ..
                        } => {
                            if keep_assignable {
                                survivors.push(written(arm));
                            }
                        }
                        crate::project_semantic_dispatch::dispatch_txn::RelationStep::NotAssignable => {
                            if !keep_assignable {
                                survivors.push(written(arm));
                            }
                        }
                        crate::project_semantic_dispatch::dispatch_txn::RelationStep::Unknown
                        | crate::project_semantic_dispatch::dispatch_txn::RelationStep::BudgetExceeded(..)
                        | crate::project_semantic_dispatch::dispatch_txn::RelationStep::Assumed(
                            _,
                        ) => {
                            // Any undecidable arm forces the whole
                            // utility result to defer — partial
                            // reduction would silently drop
                            // information.
                            let result = self.opaque(QueryError::Miss);
                            record_utility_edges(result);
                            return (QueryResult::Value(result), fence, false, None);
                        }
                    }
                }
                let result = self.intern_normalized_union_or_intersection(&survivors, true);
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }

            // `NonNullable<T>` strips `null` / `undefined` from a
            // SETTLED operand: a settled union filters its nullish
            // arms (empty result ⇒ `never`); a settled non-nullable
            // shape (function / object / literal / intersection /
            // template literal / non-nullish primitive) passes
            // through; nullish primitives reduce to `never`. An
            // UNSETTLED operand (a carrier, an unresolved shape, a
            // union with an unsettled arm) keeps the deferred
            // `Opaque(Miss)` shell — the demand points re-dispatch
            // once the operand settles (the conditional oracle's
            // carrier-check materialisation relies on this arm to
            // close `NonNullable<ChatSlots["header"]>` to the
            // member's function shape).
            "NonNullable" if args.len() == 1 => {
                use crate::semantic_query::PrimitiveKind;
                // Context-propagating deferred resolution (see Pick comment
                // above for the chain): an alias / indexed-access shell
                // operand (`NonNullable<T["items"]>`) settles to its
                // canonical shape before the nullish filter; a genuinely
                // unsettled operand returns its carrier and keeps the
                // deferred shell below.
                let nullish = |id: SemanticNodeId| {
                    matches!(
                        graph.node_data(id).as_deref(),
                        Some(SemanticNodeData::Primitive(
                            PrimitiveKind::Null | PrimitiveKind::Undefined
                        ))
                    )
                };
                // An interface or class reference names an object type,
                // which is never nullish: `NonNullable<Foo | null>` is
                // `Foo` (measured on TypeScript 7.0.2).
                let names_object_declaration = |id: SemanticNodeId| {
                    let identity = match graph.node_data(id).as_deref() {
                        Some(SemanticNodeData::DeclRef { identity }) => identity.clone(),
                        Some(SemanticNodeData::InstantiationRef { base, .. }) => base.clone(),
                        _ => return false,
                    };
                    self.ctx
                        .prepared_type_decl_return_only(
                            &identity.canonical_id,
                            identity.owner,
                            &identity.decl_name,
                        )
                        .is_some_and(|prepared| {
                            matches!(
                                prepared.kind,
                                verter_session_query::declarations::TypeDeclKind::Interface
                                    | verter_session_query::declarations::TypeDeclKind::Class
                            )
                        })
                };
                let settled_non_nullable = |id: SemanticNodeId| {
                    (matches!(
                        graph.node_data(id).as_deref(),
                        Some(
                            SemanticNodeData::Signature { .. }
                                | SemanticNodeData::Object(_)
                                | SemanticNodeData::Literal(_)
                                | SemanticNodeData::Intersection(_)
                                | SemanticNodeData::TemplateLiteral { .. }
                                | SemanticNodeData::Primitive(_)
                                | SemanticNodeData::Array { .. }
                                | SemanticNodeData::Tuple { .. }
                        )
                    ) || names_object_declaration(id))
                        && !nullish(id)
                };
                let arg = if names_object_declaration(args[0]) {
                    args[0]
                } else {
                    self.resolve_signature_source_carrier(args[0], context)
                };
                // `NonNullable<T>` is `T & {}`: `unknown & {}` collapses to
                // the empty-object base (the trap row — NOT `unknown`, NOT
                // `never`). `any`/`never` pass through the settled arms
                // below (`any & {}` = `any`; distribution over `never`
                // collapses).
                if matches!(
                    self.peek_special(arg),
                    Some((
                        crate::project_semantic_dispatch::absorb::SpecialKind::Unknown,
                        _
                    ))
                ) {
                    let result = graph.intern_node(SemanticNodeData::Object(
                        crate::project_semantic_dispatch::walk::empty_surface_view(),
                    ));
                    record_utility_edges(result);
                    return (QueryResult::Value(result), fence, false, None);
                }
                let reduced: Option<SemanticNodeId> = match graph.node_data(arg).as_deref() {
                    Some(SemanticNodeData::Union(arms))
                        if arms.iter().all(|a| nullish(*a) || settled_non_nullable(*a)) =>
                    {
                        let survivors: Vec<SemanticNodeId> =
                            arms.iter().copied().filter(|a| !nullish(*a)).collect();
                        // Canonical construction: the utility-reducer
                        // survivor union (empty folds to `never`, singleton
                        // to the member — the canonical folds).
                        Some(self.intern_normalized_union_or_intersection(&survivors, true))
                    }
                    _ if nullish(arg) => {
                        Some(graph.intern_node(SemanticNodeData::Primitive(PrimitiveKind::Never)))
                    }
                    _ if settled_non_nullable(arg) => Some(arg),
                    _ => None,
                };
                let result = reduced.unwrap_or_else(|| self.opaque(QueryError::Miss));
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }

            // ---- Deferred utilities ----
            // Unknown / not-yet-implemented utilities emit an
            // `Opaque(Miss)` shell anchored to the instantiate identity so
            // the origin walk remains coherent.
            _ => {
                let result = self.opaque(QueryError::Miss);
                record_utility_edges(result);
                (QueryResult::Value(result), fence, false, None)
            }
        }
    }

    /// Demand-point carrier resolution for a function-signature utility's
    /// SOURCE argument (`ReturnType<F>` / `Parameters<F>` /
    /// `ConstructorParameters<C>` / `InstanceType<C>`) and for the
    /// `ResolveOverloadSet` reducer's callee — every signature-demanding
    /// settlement runs through this ONE rail so the rails never diverge on
    /// the same carrier node.
    ///
    /// The deferred-shell evaluator deliberately leaves `DeclRef` /
    /// `InstantiationRef` carriers symbolic (intermediate indexed-access
    /// hops must stay carrier-shaped), but a signature utility IS a
    /// demand point: its argument's call/construct surface must settle
    /// before the signature walk can read it. Mirrors the keyspace
    /// enumerator's carrier demand point
    /// (`key_names_from_keyspace_node`): resolve the carrier through the
    /// shared `Instantiate` dispatch under the CALLER's context (a
    /// structural-transit caller carrier-stops as usual), then re-settle
    /// deferred shells. Bounded carrier-chain unwrap; an unresolvable
    /// carrier returns itself so the utility falls through to its
    /// deferred `Opaque(Miss)` shell.
    pub(super) fn resolve_signature_source_carrier(
        &self,
        node: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let mut current = self
            .evaluate_deferred_semantic_node_with_context(node, context)
            .into_active_query_build_node(self);
        // Sound termination on the residual chain: a `visited` set detects
        // exact resolution cycles, and the connected work envelope bounds
        // fresh-node regrowth the visited set cannot (each `Instantiate` step
        // can mint a NEW node id). Both
        // abnormal stops are TYPED: they fold a partial into the enclosing
        // query build's taint frame (refusing warm admission) instead of
        // silently returning an intermediate carrier the signature-utility
        // caller would classify as settled.
        let mut visited = crate::semantic_query::small_node_set::SmallNodeSet::default();
        // Bounded loop: exact-identity cycle detection plus the shared
        // connected work envelope, both typed-partial on trip.
        loop {
            let (slot, inst_args, owner_canonical) =
                match self.graph().node_data(current).as_deref() {
                    Some(SemanticNodeData::DeclRef { identity }) => (
                        self.type_slot_for(
                            identity.canonical_id.clone(),
                            identity.owner,
                            identity.decl_name.clone(),
                        ),
                        Arc::from(Vec::<SemanticNodeId>::new().into_boxed_slice()),
                        identity.canonical_id.clone(),
                    ),
                    Some(SemanticNodeData::InstantiationRef { base, args }) => (
                        self.type_slot_for(
                            base.canonical_id.clone(),
                            base.owner,
                            base.decl_name.clone(),
                        ),
                        self.evaluate_carrier_arguments(base, args, context)
                            .into_active_query_build_arguments(self),
                        base.canonical_id.clone(),
                    ),
                    // Settled (non-carrier) — the stable stop; checked BEFORE the
                    // work budget so a chain that settles on exactly the last
                    // permitted step is never falsely partial.
                    _ => return current,
                };
            if !visited.insert(current) {
                // Residual-carrier resolution cycle: the chain can never
                // settle — typed partial, never a silent carrier return.
                self.fold_local_partial_completeness(
                    crate::semantic_query::PartialReasonSet::SAME_PATH_RECURSION,
                );
                return current;
            }
            if let Err(reasons) = self.charge_connected_work() {
                // Fresh-node regrowth exhausted the shared connected envelope.
                self.fold_local_partial_completeness(reasons);
                return current;
            }
            let read = self.execute_read(SemanticQueryKey::Instantiate(
                crate::semantic_query::InstantiateKey::new(
                    slot,
                    inst_args,
                    self.instantiate_context_for(&owner_canonical, context),
                ),
            ));
            // A2 signal-split: fold a genuinely-incomplete carrier resolve.
            crate::request_context::observe_component_meta_read_suppress(&read);
            let next = match read.value {
                QueryResult::Value(id) => id,
                _ => return current,
            };
            if next == current {
                return current;
            }
            current = self
                .evaluate_deferred_semantic_node_with_context(next, context)
                .into_active_query_build_node(self);
        }
    }

    /// Whether `name`, within the `__builtin__` sentinel namespace the
    /// shadowing gates mint for an unshadowed global, is the runtime
    /// nominal `Promise` ([`RuntimeNominal`](crate::intrinsic_registry::RuntimeNominal)).
    pub(super) fn is_promise_global_name(&self, name: &str) -> bool {
        matches!(
            self.runtime_nominal_global_name(name),
            Some(crate::intrinsic_registry::RuntimeNominal::Promise)
        )
    }

    pub(super) fn runtime_nominal_global_name(
        &self,
        name: &str,
    ) -> Option<crate::intrinsic_registry::RuntimeNominal> {
        crate::intrinsic_registry::RuntimeNominal::from_global_name(name)
    }

    pub(super) fn runtime_nominal_identity(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
    ) -> Option<crate::intrinsic_registry::RuntimeNominal> {
        crate::intrinsic_registry::RuntimeNominal::of_builtin_identity(identity)
    }

    /// Whether `canonical` is a file of the project's lib environment (an
    /// automatic lib's virtual id). A free name resolves there only when no
    /// program file declares it (the `typeof` builder's global root reads
    /// the program first), so a lib declaration reached that way is the
    /// name's only one.
    pub(super) fn is_lib_environment_canonical(&self, canonical: &str) -> bool {
        verter_session_query::inputs::contributors::is_automatic_lib_canonical(canonical)
    }

    /// Whether `identity` is the builtin-sentinel `Function` carrier the
    /// lowering fast path interns for an unshadowed global `Function`
    /// reference.
    pub(super) fn is_function_global_identity(
        &self,
        identity: &crate::semantic_query::DeclIdentity,
    ) -> bool {
        matches!(
            self.runtime_nominal_identity(identity),
            Some(crate::intrinsic_registry::RuntimeNominal::Function)
        )
    }

    /// Whether `identity` is the builtin-sentinel `Promise` carrier
    /// identity the lowering fast path interns for an unshadowed global
    /// `Promise<...>` reference.
    fn is_promise_global_identity(&self, identity: &crate::semantic_query::DeclIdentity) -> bool {
        matches!(
            self.runtime_nominal_identity(identity),
            Some(crate::intrinsic_registry::RuntimeNominal::Promise)
        )
    }

    /// Re-intern a call-kind `Signature` node as its CONSTRUCT twin
    /// (identical params/return/type-params/spans). Non-signature nodes
    /// (and already-construct signatures) pass through unchanged — used by
    /// producers whose surface position (a class's construct bucket)
    /// defines the kind.
    pub(super) fn construct_kind_twin(&self, node: SemanticNodeId) -> SemanticNodeId {
        let graph = self.graph();
        let Some(data) = graph.node_data(node) else {
            return node;
        };
        let SemanticNodeData::Signature {
            kind: crate::semantic_query::SignatureKind::Call,
            params,
            return_type,
            type_parameters,
            occurrence,
            return_carrier,
            signature_span,
            return_type_span,
            predicate,
            is_abstract,
        } = data.as_ref()
        else {
            return node;
        };
        let twin = SemanticNodeData::Signature {
            kind: crate::semantic_query::SignatureKind::Construct,
            params: params.share(),
            return_type: *return_type,
            type_parameters: type_parameters.share(),
            // The kind twin is the SAME authored position and carrier.
            occurrence: occurrence.clone(),
            return_carrier: return_carrier.clone(),
            signature_span: *signature_span,
            return_type_span: *return_type_span,
            predicate: *predicate,
            is_abstract: *is_abstract,
        };
        drop(data);
        graph.intern_preserving_scope(node, twin)
    }

    /// Instantiate a signature-utility extraction at the BASE signature of
    /// `function_node`: every type parameter it owns that survives into
    /// `extracted` substitutes to its base constraint (see
    /// [`Self::instantiate_clause_at_base_constraints`]) —
    /// `ReturnType<typeof id>` for `id<T>(x: T): T` is `unknown`, and for
    /// `id<T extends string>(x: T): T` it is `string`. A non-generic
    /// signature returns `extracted` unchanged.
    ///
    /// The `Function` node's `type_parameters` carry [`TypeParamDecl`]s
    /// (name + constraint/default), not binder node ids; the binder NODES
    /// the body's references interned are discovered by walking
    /// `extracted` for `TypeParam` nodes whose `display_name` matches a
    /// declared parameter name — consistent with the file-scoped
    /// name-keyed `TypeParam` identity the lowering uses. The walk is
    /// SHADOWING-AWARE: a function node inside `extracted` (its root
    /// included — `extracted` is not the owning signature) that
    /// re-declares the name owns every same-name binder in its subtree,
    /// so those occurrences stay generic. Each discovered binder node
    /// substitutes through the shared binder-identity substitution (never
    /// a name-rewrite of the subtree).
    pub(super) fn instantiate_signature_params_at_base_constraints(
        &self,
        function_node: SemanticNodeId,
        extracted: SemanticNodeId,
    ) -> SemanticNodeId {
        let Some(data) = self.graph().node_data(function_node) else {
            return extracted;
        };
        let Some(header) =
            data.callable_header(&crate::semantic_query::ResolveOverloadSetConsumer::witness())
        else {
            return extracted;
        };
        let type_parameters = Arc::clone(header.type_parameters);
        drop(data);
        self.instantiate_clause_at_base_constraints(
            type_parameters
                .iter()
                .map(|decl| (decl.name.as_ref(), decl.constraint)),
            extracted,
            crate::semantic_query::ClauseSpelling::Bound,
            crate::semantic_query::ClauseSpelling::Bound,
        )
    }

    /// `signature`'s base signature (`getBaseSignature`): each of its type
    /// parameters instantiated at its base constraint
    /// ([`Self::instantiate_signature_params_at_base_constraints`]), and the
    /// clause dropped. A signature that declares no type parameters is
    /// itself; `None` when `signature` is no signature or its return is
    /// not a declared type.
    pub(super) fn base_signature(&self, signature: SemanticNodeId) -> Option<SemanticNodeId> {
        let graph = self.graph();
        let data = graph.node_data(signature)?;
        let SemanticNodeData::Signature {
            kind,
            params,
            return_type,
            type_parameters,
            occurrence,
            return_carrier: crate::semantic_query::SignatureReturnCarrier::Declared(_),
            signature_span,
            return_type_span,
            predicate,
            is_abstract,
        } = data.as_ref()
        else {
            return None;
        };
        if type_parameters.is_empty() {
            return Some(signature);
        }
        // One clause, one base substitution: the clause's base constraints
        // are computed once and applied to every parameter and the return,
        // never re-derived per position.
        let substitution = self.clause_base_substitution(
            type_parameters
                .iter()
                .map(|decl| (decl.name.as_ref(), decl.constraint)),
            crate::semantic_query::ClauseSpelling::Bound,
        );
        let substitution = crate::semantic_query::CanonicalTypeSubstitution::new(
            graph,
            type_parameters
                .iter()
                .zip(&substitution.bases)
                .map(|(decl, base)| (decl.param, *base))
                .collect(),
        );
        let base = |node| self.substitute_canonical(node, &substitution);
        let params: Arc<[crate::semantic_query::FunctionParam]> = params
            .iter()
            .map(crate::semantic_query::FunctionParam::copy)
            .map(|mut param| {
                param.ty = base(param.ty);
                param
            })
            .collect();
        let return_type = base(*return_type);
        Some(graph.intern_node(SemanticNodeData::Signature {
            kind: *kind,
            params: crate::semantic_query::PayloadArray::from(params),
            return_type,
            type_parameters: crate::semantic_query::PayloadArray::from(
                Vec::new().into_boxed_slice(),
            ),
            occurrence: occurrence.clone(),
            return_carrier: crate::semantic_query::SignatureReturnCarrier::Declared(return_type),
            signature_span: *signature_span,
            return_type_span: *return_type_span,
            predicate: *predicate,
            is_abstract: *is_abstract,
        }))
    }

    /// The signature-utility rule addressed by type-parameter NAME and
    /// constraint rather than by an owning `Signature` node: TypeScript's
    /// BASE signature (`getBaseSignature`), which is what `ReturnType` /
    /// `Parameters` infer from when their argument is a generic signature.
    ///
    /// [`Self::instantiate_signature_params_at_base_constraints`] reads the
    /// clause off a signature node and is the entry for every caller that
    /// HAS one. A caller that holds only a signature's RETURN — the
    /// flow-return rail, whose callee answers with a bare return node and
    /// never composes a signature — applies the same rule to the callee's
    /// separately-inventoried clause through this body.
    ///
    /// Each parameter instantiates at its constraint (`unknown` when it has
    /// none; a DEFAULT is never consulted), with sibling parameters inside
    /// a constraint replaced by THEIR constraints for `N - 1` rounds and
    /// every parameter still referenced after that erased to `any`. So
    /// `<A extends string, B extends A>` reads `B` as `string`,
    /// `<T extends { next: T }>` reads `T` as `{ next: any }`, and
    /// `<A extends B[], B extends C[], C extends A[]>` reads each as
    /// `any[][][]`. A constraint that reaches its own parameter through
    /// bare parameter references alone (`<A extends B, B extends A>`, also
    /// through a union or intersection arm) is circular: TypeScript
    /// rejects it (TS2313) and treats the parameter as unconstrained.
    ///
    /// `constraint_spelling` names the spellings of a clause parameter
    /// inside the constraints, `spelling` those inside `extracted` — the
    /// two can be lowered in different scopes. An empty clause returns
    /// `extracted` unchanged.
    pub(super) fn instantiate_clause_at_base_constraints<'n>(
        &self,
        clause: impl IntoIterator<Item = (&'n str, Option<SemanticNodeId>)>,
        extracted: SemanticNodeId,
        constraint_spelling: crate::semantic_query::ClauseSpelling,
        spelling: crate::semantic_query::ClauseSpelling,
    ) -> SemanticNodeId {
        let substitution = self.clause_base_substitution(clause, constraint_spelling);
        self.apply_clause_base_substitution(&substitution, extracted, spelling)
    }

    /// Substitute a clause's base constraints
    /// ([`Self::clause_base_substitution`]) out of `extracted`, claiming
    /// the clause parameters by `spelling`.
    fn apply_clause_base_substitution(
        &self,
        substitution: &ClauseBaseSubstitution<'_>,
        extracted: SemanticNodeId,
        spelling: crate::semantic_query::ClauseSpelling,
    ) -> SemanticNodeId {
        if substitution.names.is_empty() {
            return extracted;
        }
        self.instantiate_clause_params(
            substitution
                .names
                .iter()
                .copied()
                .zip(substitution.bases.iter().copied().map(Some)),
            extracted,
            spelling,
        )
    }

    /// The base constraint of each clause parameter, the substitution
    /// [`Self::instantiate_clause_at_base_constraints`] applies. A round
    /// is a pure function of the previous round's bases, so the rounds
    /// stop at the first one that changes nothing: a clause whose
    /// constraints name no sibling settles after one round instead of
    /// `N - 1`.
    fn clause_base_substitution<'n>(
        &self,
        clause: impl IntoIterator<Item = (&'n str, Option<SemanticNodeId>)>,
        constraint_spelling: crate::semantic_query::ClauseSpelling,
    ) -> ClauseBaseSubstitution<'n> {
        let clause: Vec<(&str, Option<SemanticNodeId>)> = clause.into_iter().collect();
        if clause.is_empty() {
            return ClauseBaseSubstitution {
                names: Vec::new(),
                bases: Vec::new(),
            };
        }
        let names: Vec<&str> = clause.iter().map(|(name, _)| *name).collect();
        let circular = self.circular_clause_constraints(&clause, constraint_spelling);
        let intern = |primitive| {
            self.graph()
                .intern_node(SemanticNodeData::Primitive(primitive))
        };
        let unknown = intern(crate::semantic_query::PrimitiveKind::Unknown);
        let constraints: Vec<SemanticNodeId> = clause
            .iter()
            .zip(&circular)
            .map(|((_, constraint), circular)| match constraint {
                Some(constraint) if !circular => *constraint,
                _ => unknown,
            })
            .collect();
        // Round 0 erases every parameter a constraint still names; round
        // `r` replaces each named parameter with its round `r - 1` base.
        // The substituted values name no clause parameter, so the
        // per-name substitution is a simultaneous one.
        let any = intern(crate::semantic_query::PrimitiveKind::Any);
        let mut bases: Vec<SemanticNodeId> = constraints
            .iter()
            .map(|&constraint| {
                self.instantiate_clause_params(
                    names.iter().map(|&name| (name, Some(any))),
                    constraint,
                    constraint_spelling,
                )
            })
            .collect();
        for _ in 1..clause.len() {
            let next: Vec<SemanticNodeId> = constraints
                .iter()
                .map(|&constraint| {
                    self.instantiate_clause_params(
                        names.iter().copied().zip(bases.iter().copied().map(Some)),
                        constraint,
                        constraint_spelling,
                    )
                })
                .collect();
            if next == bases {
                break;
            }
            bases = next;
        }
        ClauseBaseSubstitution { names, bases }
    }

    /// Per clause parameter: whether its constraint reaches the parameter
    /// itself through bare parameter references alone (a reference, or a
    /// union / intersection arm that is one) — TypeScript's circular
    /// constraint (TS2313), which it drops.
    fn circular_clause_constraints(
        &self,
        clause: &[(&str, Option<SemanticNodeId>)],
        spelling: crate::semantic_query::ClauseSpelling,
    ) -> Vec<bool> {
        // The parameters each constraint names bare.
        let edges: Vec<Vec<usize>> = clause
            .iter()
            .map(|(_, constraint)| {
                let mut targets = Vec::new();
                let mut stack: Vec<SemanticNodeId> = constraint.iter().copied().collect();
                let mut visited: FxHashSet<SemanticNodeId> = FxHashSet::default();
                while let Some(node) = stack.pop() {
                    if !visited.insert(node) {
                        continue;
                    }
                    let Some(data) = self.graph().node_data(node) else {
                        continue;
                    };
                    match data.as_ref() {
                        SemanticNodeData::Union(_) | SemanticNodeData::Intersection(_) => {
                            let members = data.composite_members().expect("composite arm");
                            stack.extend(members.iter().copied());
                        }
                        SemanticNodeData::Alias(target) => stack.push(*target),
                        SemanticNodeData::TypeParam { .. }
                        | SemanticNodeData::BareRef(_)
                        | SemanticNodeData::DeclRef { .. } => {
                            drop(data);
                            targets.extend(clause.iter().enumerate().filter_map(
                                |(index, (name, _))| {
                                    self.collect_type_param_nodes_by_name(
                                        node, name, /* root_is_own_signature */ false,
                                        spelling,
                                    )
                                    .contains(&node)
                                    .then_some(index)
                                },
                            ));
                        }
                        _ => {}
                    }
                }
                targets
            })
            .collect();
        (0..clause.len())
            .map(|start| {
                let mut seen = vec![false; clause.len()];
                let mut stack = edges[start].clone();
                while let Some(index) = stack.pop() {
                    if index == start {
                        return true;
                    }
                    if !std::mem::replace(&mut seen[index], true) {
                        stack.extend(edges[index].iter().copied());
                    }
                }
                false
            })
            .collect()
    }

    construction_ordinal_seam! {
        /// The CALL-SITE form of the clause rule, and the one the flow
        /// evaluator's callee gate
        /// ([`crate::project_semantic_dispatch::flow_return_callee`]) drives.
        ///
        /// Two differences from the signature-utility form above, both
        /// call-site semantics:
        ///
        /// - a parameter with a DECLARED DEFAULT instantiates to that
        ///   default, because an argument-free call resolves it without
        ///   inference (`f<T = number>()` IS `number`). A signature UTILITY
        ///   does not: `ReturnType<typeof f>` is `unknown` there, which is
        ///   why the two entrances stay separate rather than sharing one
        ///   default policy;
        /// - the claimed SPELLINGS are chosen by the caller, because they
        ///   depend on where the instantiated node was lowered rather than
        ///   on the call: a DECLARED return lowers in file owner scope where
        ///   the clause is invisible (so a resolved same-named declaration
        ///   IS the parameter), while a body-derived return is evaluated
        ///   with the clause bound (so a resolved same-named declaration is
        ///   a foreign symbol). See
        ///   [`ClauseSpelling`](crate::semantic_query::ClauseSpelling).
        fn instantiate_clause_params_at_call<'n>(
            &self,
            params: impl IntoIterator<Item = (&'n str, Option<SemanticNodeId>)>,
            extracted: SemanticNodeId,
            spelling: crate::semantic_query::ClauseSpelling,
        ) -> SemanticNodeId {
            self.instantiate_clause_params(params, extracted, spelling)
        }
    }

    /// The smallest ordinal among `params` whose type mentions `name` —
    /// the resolved-shape half of the call-site inference oracle
    /// (`ClauseParamInference`), mirroring the authored-shape
    /// `FunctionProgramTypeParam::first_parameter_occurrence`.
    ///
    /// Reuses the SAME shadowing-aware per-name collector the
    /// instantiation itself uses, so "the parameter occurs here" means
    /// exactly what "the parameter is claimed here" means — the two
    /// cannot drift.
    pub(super) fn first_signature_param_occurrence(
        &self,
        params: &[crate::semantic_query::FunctionParam],
        name: &str,
    ) -> Option<u32> {
        params.iter().enumerate().find_map(|(ordinal, param)| {
            (!self
                .collect_type_param_nodes_by_name(
                    param.ty,
                    name,
                    /* root_is_own_signature */ false,
                    crate::semantic_query::ClauseSpelling::WithOwnerScopeResolution,
                )
                .is_empty())
            .then_some(ordinal as u32)
        })
    }

    /// The shared body: substitute each named clause parameter out of
    /// `extracted`, at its declared default when one is supplied and at
    /// `unknown` otherwise.
    fn instantiate_clause_params<'n>(
        &self,
        params: impl IntoIterator<Item = (&'n str, Option<SemanticNodeId>)>,
        extracted: SemanticNodeId,
        spelling: crate::semantic_query::ClauseSpelling,
    ) -> SemanticNodeId {
        let mut unknown: Option<SemanticNodeId> = None;
        let mut result = extracted;
        for (name, default) in params {
            // Shadowing-aware per-name collection: `extracted` is NOT the
            // owning signature, so a function node ANYWHERE in it (its root
            // included) that re-declares `name` owns every same-name
            // binder in its subtree — those occurrences are the nested
            // binder's, never the free outer parameter being instantiated.
            for binder in self.collect_type_param_nodes_by_name(
                result, name, /* root_is_own_signature */ false, spelling,
            ) {
                let substitution = match default {
                    Some(default) => default,
                    None => *unknown.get_or_insert_with(|| {
                        self.graph().intern_node(SemanticNodeData::Primitive(
                            crate::semantic_query::PrimitiveKind::Unknown,
                        ))
                    }),
                };
                result = self.substitute_semantic_type_param(result, binder, substitution);
            }
        }
        result
    }

    /// Apply instantiation type arguments to the sealed index-composed
    /// callable carrier. Substitution runs over the carrier's OWN
    /// parameters and binder constraints/defaults; the consumed type
    /// parameters are stripped, and both the occurrence and the deferred
    /// return carrier are preserved — an instantiated candidate is the
    /// same occurrence with the same equation edge. An unsatisfiable
    /// argument list is an honest miss.
    fn instantiate_deferred_callable(
        &self,
        callable: &crate::semantic_query::DeferredCallable,
        args: &[SemanticNodeId],
    ) -> SemanticNodeId {
        let parts = callable.parts(&crate::semantic_query::ResolveCallConsumer::witness());
        let type_parameters = Arc::clone(parts.type_parameters);
        if type_parameters.is_empty() || args.len() > type_parameters.len() {
            return self.opaque(QueryError::Miss);
        }
        let mut params: Vec<crate::semantic_query::FunctionParam> = parts
            .params
            .iter()
            .map(crate::semantic_query::FunctionParam::copy)
            .collect::<Vec<_>>();
        let mut bound: Vec<(SemanticNodeId, SemanticNodeId)> = Vec::new();
        for (index, decl) in type_parameters.iter().enumerate() {
            let arg = match self.instantiation_argument(args, index, decl.default, &bound) {
                Some(arg) => arg,
                None => return self.opaque(QueryError::Miss),
            };
            for param in &mut params {
                param.ty = self.substitute_semantic_type_param(param.ty, decl.param, arg);
            }
            bound.push((decl.param, arg));
        }
        let source = callable.map_source_values(|mut image| {
            for (binder, argument) in &bound {
                image = self.substitute_semantic_type_param(image, *binder, *argument);
            }
            image
        });
        let source = source.with_instantiated_clause(
            type_parameters
                .iter()
                .zip(bound.iter())
                .map(|(decl, (_, argument))| (Arc::<str>::from(&decl.name), *argument)),
        );
        self.graph()
            .intern_node(SemanticNodeData::DeferredCallable(source.with_substituted(
                Arc::from(params.into_boxed_slice()),
                Arc::from(Vec::<crate::semantic_query::TypeParamDecl>::new().into_boxed_slice()),
            )))
    }

    /// The type argument binding the type parameter at `index`: the
    /// supplied argument, otherwise its declared default.
    ///
    /// A default may REFERENCE an earlier parameter (`<T, U = T>`), and by
    /// the time it is read those earlier parameters have already been
    /// substituted away — reading the declared node verbatim would leave a
    /// binder with no binding. `bound` carries the bindings fixed so far,
    /// in declaration order, and the default is instantiated under them.
    /// `None` means the parameter is neither supplied nor defaulted.
    fn instantiation_argument(
        &self,
        args: &[SemanticNodeId],
        index: usize,
        default: Option<SemanticNodeId>,
        bound: &[(SemanticNodeId, SemanticNodeId)],
    ) -> Option<SemanticNodeId> {
        if let Some(arg) = args.get(index).copied() {
            return Some(arg);
        }
        let mut default = default?;
        for (param, arg) in bound {
            default = self.substitute_semantic_type_param(default, *param, *arg);
        }
        Some(default)
    }

    /// Apply instantiation-expression type arguments to a signature-bearing
    /// OBJECT (`typeof f<string>` over a function declaration, `typeof
    /// C<string>` over a generic class): every call and construct signature
    /// the object carries — read from `SignaturesOfType` — whose own
    /// type-parameter list accepts the arguments is instantiated, the
    /// others are dropped, and the object's members and index signatures
    /// are kept as they are. TypeScript's `getInstantiationExpressionType`
    /// instantiates the same way. An object with no signature that accepts
    /// the arguments is the same honest `Opaque(Miss)` a lone signature
    /// answers, so every caller's drop contract holds.
    fn instantiate_object_signatures(
        &self,
        node: SemanticNodeId,
        surface: &crate::semantic_query::SurfaceView,
        args: &[SemanticNodeId],
    ) -> SemanticNodeId {
        let Ok((calls, constructs)) = self.shared_signature_buckets(node) else {
            return self.opaque(QueryError::Miss);
        };
        let instantiate = |signatures: &[SemanticNodeId]| -> Vec<SemanticNodeId> {
            signatures
                .iter()
                .filter_map(|signature| self.instantiate_call_candidate(*signature, args))
                .collect()
        };
        let mut call_signatures = Some(instantiate(&calls));
        let mut construct_signatures = Some(instantiate(&constructs));
        if call_signatures.as_ref().is_some_and(Vec::is_empty)
            && construct_signatures.as_ref().is_some_and(Vec::is_empty)
        {
            return self.opaque(QueryError::Miss);
        }
        // The authored entry order is kept: each signature list takes the
        // place of the first entry of its kind.
        let mut entries = Vec::with_capacity(surface.entries.len());
        for entry in surface.entries.iter() {
            match entry {
                crate::semantic_query::SurfaceEntry::CallSignature(_) => entries.extend(
                    call_signatures
                        .take()
                        .into_iter()
                        .flatten()
                        .map(crate::semantic_query::SurfaceEntry::CallSignature),
                ),
                crate::semantic_query::SurfaceEntry::ConstructSignature(_) => entries.extend(
                    construct_signatures
                        .take()
                        .into_iter()
                        .flatten()
                        .map(crate::semantic_query::SurfaceEntry::ConstructSignature),
                ),
                other => entries.push(other.clone()),
            }
        }
        entries.extend(
            call_signatures
                .into_iter()
                .flatten()
                .map(crate::semantic_query::SurfaceEntry::CallSignature),
        );
        entries.extend(
            construct_signatures
                .into_iter()
                .flatten()
                .map(crate::semantic_query::SurfaceEntry::ConstructSignature),
        );
        self.graph().intern_preserving_scope(
            node,
            SemanticNodeData::Object(crate::semantic_query::SurfaceView::from_entries(
                entries,
                surface.keyspace,
                surface.closed().has_index_signature(),
            )),
        )
    }

    /// Apply a call site's explicit type arguments to ONE candidate
    /// signature. `None` when the candidate cannot accept the argument
    /// list, which drops it from that call site's ordered bucket.
    ///
    /// The single authority for that drop: the ordered bucket a call site
    /// sees and the raw bucket its executor pairs each candidate back to
    /// must be filtered identically, or a surviving candidate is paired
    /// with a dropped candidate's binders.
    pub(super) fn instantiate_call_candidate(
        &self,
        signature: SemanticNodeId,
        type_args: &[SemanticNodeId],
    ) -> Option<SemanticNodeId> {
        let instantiated = self.apply_typeof_instantiation_args(signature, type_args);
        let dropped = matches!(
            self.graph().node_data(instantiated).as_deref(),
            Some(SemanticNodeData::Opaque(_))
        );
        (!dropped).then_some(instantiated)
    }

    /// Apply instantiation-expression type arguments
    /// (`typeof C.make<string>`) to a resolved generic signature node:
    /// each of the function's OWN type parameters substitutes positionally
    /// to the matching argument (an unfilled trailing parameter takes its
    /// declared default when present), and the instantiated signature is
    /// re-interned WITHOUT the consumed type parameters — an instantiation
    /// expression yields a non-generic signature. A signature-bearing
    /// object instantiates every signature it carries
    /// ([`Self::instantiate_object_signatures`]). Returns the deferred
    /// `Opaque(Miss)` shell when the node is not a generic function or the
    /// arguments cannot satisfy the parameter list (an honest miss, never
    /// a partially-substituted signature).
    pub(super) fn apply_typeof_instantiation_args(
        &self,
        node: SemanticNodeId,
        args: &[SemanticNodeId],
    ) -> SemanticNodeId {
        let Some(data) = self.graph().node_data(node) else {
            return self.opaque(QueryError::Miss);
        };
        // The sealed index-composed carrier instantiates in place: its
        // parameters and binders substitute, the occurrence and the
        // deferral are preserved.
        if let SemanticNodeData::DeferredCallable(callable) = &*data {
            let callable = callable.clone();
            drop(data);
            return self.instantiate_deferred_callable(&callable, args);
        }
        if let SemanticNodeData::Object(surface) = &*data {
            let surface = surface.clone();
            drop(data);
            return self.instantiate_object_signatures(node, &surface, args);
        }
        let SemanticNodeData::Signature {
            type_parameters, ..
        } = &*data
        else {
            return self.opaque(QueryError::Miss);
        };
        let type_parameters = Arc::clone(type_parameters.as_arc());
        drop(data);
        if type_parameters.is_empty() || args.len() > type_parameters.len() {
            return self.opaque(QueryError::Miss);
        }
        let mut result = node;
        let mut bound: Vec<(SemanticNodeId, SemanticNodeId)> = Vec::new();
        for (index, decl) in type_parameters.iter().enumerate() {
            let arg = match self.instantiation_argument(args, index, decl.default, &bound) {
                Some(arg) => arg,
                // Unsatisfied non-defaulted parameter — honest miss.
                None => return self.opaque(QueryError::Miss),
            };
            bound.push((decl.param, arg));
            // The walked root IS the signature whose own parameters are being
            // instantiated — its own `type_parameters` entry for `decl.name`
            // must not shadow; NESTED functions re-declaring the name do.
            for binder in self.collect_type_param_nodes_by_name(
                result,
                decl.name.as_ref(),
                /* root_is_own_signature */ true,
                crate::semantic_query::ClauseSpelling::Bound,
            ) {
                result = self.substitute_semantic_type_param(result, binder, arg);
            }
        }
        // Strip the consumed type parameters — the instantiated signature
        // is non-generic. Instantiation PRESERVES the occurrence; a
        // declared carrier retargets the instantiated return.
        match self.graph().node_data(result).as_deref() {
            Some(SemanticNodeData::Signature {
                kind,
                params,
                return_type,
                occurrence,
                return_carrier,
                signature_span,
                return_type_span,
                predicate,
                is_abstract,
                ..
            }) => self.graph().intern_node(SemanticNodeData::Signature {
                kind: *kind,
                params: params.share(),
                return_type: *return_type,
                type_parameters: crate::semantic_query::PayloadArray::from(
                    Vec::<crate::semantic_query::TypeParamDecl>::new().into_boxed_slice(),
                ),
                occurrence: occurrence.clone(),
                return_carrier: match return_carrier {
                    crate::semantic_query::SignatureReturnCarrier::Declared(_) => {
                        crate::semantic_query::SignatureReturnCarrier::Declared(*return_type)
                    }
                    crate::semantic_query::SignatureReturnCarrier::Function(source) => {
                        crate::semantic_query::SignatureReturnCarrier::Function(source.clone())
                    }
                    crate::semantic_query::SignatureReturnCarrier::DeferredFlow(_)
                    | crate::semantic_query::SignatureReturnCarrier::EvaluatedFlow(_) => {
                        return_carrier.clone()
                    }
                },
                signature_span: *signature_span,
                return_type_span: *return_type_span,
                // The substituted predicate target rides through: an
                // instantiated `x is T` narrows to the argument.
                predicate: *predicate,
                is_abstract: *is_abstract,
            }),
            _ => result,
        }
    }

    construction_ordinal_seam! {
        /// Bounded subtree walk collecting the distinct `TypeParam` binder
        /// NODES under `root` whose `display_name` is `name`. Cycle-guarded
        /// via the visited set; descends the same structural child edges the
        /// substitute engine rewrites through
        /// ([`Self::substitute_semantic_type_param`]) — including
        /// `InstantiationRef` type-argument vectors, `Conditional` operands,
        /// `Mapped` sub-trees, and `MergedDecl` contributors — so every
        /// position substitution can reach is also a position collection
        /// discovers. Two deliberate divergences from that mirror: the
        /// `Function` and `Mapped` descents are NAME-shadowing-aware (below;
        /// substitution shadows by binder node identity instead, which the
        /// per-name collection decides up front), and `Infer { name }` nodes
        /// are never collected — an `infer X` DECLARES a fresh
        /// conditional-scoped binder, never an occurrence of a function's
        /// declared type parameter. The substitute engine's cross-variant
        /// Infer name-bridge is Infer-BINDER-gated in both directions, so
        /// collection-driven substitutions — whose binders come from
        /// `Function::type_parameters` and always lower as `TypeParam`
        /// shells — never rewrite `infer` declarations; the bridge fires
        /// only for its dedicated Infer-binder consumer (the Conditional
        /// reducer's infer-arm substitution, which passes an `Infer` node
        /// as the binder directly).
        ///
        /// SHADOWING-AWARE: a `Function` node whose own `type_parameters`
        /// re-declare `name` is NOT descended into — its subtree's same-name
        /// occurrences belong to the nested binder (TS lexical shadowing), so
        /// rewriting them for an OUTER parameter would corrupt the inner
        /// signature (`outer<T>(): <T>(x: T) => T` — the inner `T` survives an
        /// outer instantiation). A NON-shadowing nested function is walked in
        /// full, including its own `type_parameters[*].constraint` / `.default`
        /// nodes — those positions can reference the searched outer binder
        /// (`<U extends T>` / `<U = T>`) and the substitute engine descends
        /// into them, so collection mirrors that coverage.
        /// `root_is_own_signature` exempts the ROOT node
        /// from the shadow check: when the walked root is exactly the signature
        /// whose own parameters are being instantiated, its own declaration of
        /// `name` is the parameter being substituted, not a shadow. The
        /// file-scoped name-keyed `TypeParam` identity itself is unchanged —
        /// this stops CROSS-BINDER rewrites within one extraction only.
        fn collect_type_param_nodes_by_name(
            &self,
            root: SemanticNodeId,
            name: &str,
            root_is_own_signature: bool,
            spelling: crate::semantic_query::ClauseSpelling,
        ) -> Vec<SemanticNodeId> {
            use crate::semantic_query::IndexKey;
            let mut visited: FxHashSet<SemanticNodeId> = FxHashSet::default();
            let mut stack: Vec<SemanticNodeId> = vec![root];
            let mut found: Vec<SemanticNodeId> = Vec::new();
            while let Some(node) = stack.pop() {
                if !visited.insert(node) {
                    continue;
                }
                #[cfg(any(test, feature = "test-support"))]
                BINDER_COLLECTION_VISITS.with(|visits| visits.set(visits.get() + 1));
                let Some(data) = self.graph().node_data(node) else {
                    continue;
                };
                match data.as_ref() {
                    SemanticNodeData::TypeParam { display_name, .. } => {
                        if display_name.as_ref() == name {
                            found.push(node);
                        }
                    }
                    SemanticNodeData::Alias(target) => stack.push(*target),
                    SemanticNodeData::ClassExpressionInstance {
                        type_arguments,
                        surface,
                        ..
                    } => {
                        stack.extend(type_arguments.iter().copied());
                        stack.push(*surface);
                    }
                    composite @ (SemanticNodeData::Union(_) | SemanticNodeData::Intersection(_)) => {
                        let members = composite.composite_members().expect("composite arm");
                        stack.extend(members.iter().copied());
                    }
                    SemanticNodeData::Array { element, .. } => stack.push(*element),
                    SemanticNodeData::Tuple { elements, .. } => {
                        stack.extend(elements.iter().map(|element| element.value));
                    }
                    SemanticNodeData::Object(surface) => {
                        stack.extend(surface.positive_members().iter().map(|member| member.value));
                        stack.extend(surface.call_signatures.iter().copied());
                        stack.extend(surface.construct_signatures.iter().copied());
                        for signature in surface.index_signatures.iter() {
                            stack.push(signature.key_type);
                            stack.push(signature.value_type);
                        }
                        if let Some(keyspace) = surface.keyspace {
                            stack.push(keyspace);
                        }
                    }
                    SemanticNodeData::Signature {
                        params,
                        return_type,
                        type_parameters,
                        predicate,
                        return_carrier,
                        ..
                    } => {
                        // A nested signature re-declaring `name` shadows: its
                        // subtree's `name` binders are its own — skip descent
                        // (including its own type-parameter constraint/default
                        // nodes: the re-declaring function owns its WHOLE
                        // subtree).
                        let shadows = type_parameters
                            .iter()
                            .any(|decl| decl.name.as_ref() == name)
                            && !(node == root && root_is_own_signature);
                        if shadows {
                            continue;
                        }
                        if let crate::semantic_query::SignatureReturnCarrier::DeferredFlow(source) =
                            return_carrier
                        {
                            stack.extend(source.bindings().iter().map(|(_, image)| *image));
                        }
                        stack.extend(params.iter().map(|param| param.ty));
                        stack.push(*return_type);
                        stack.extend(predicate.and_then(|predicate| predicate.ty));
                        // A non-shadowing nested signature's own type-parameter
                        // declarations can reference the searched OUTER binder in
                        // constraint/default position (`<U extends T>` /
                        // `<U = T>`). The substitute engine descends into these
                        // nodes, so collection must walk them too — otherwise
                        // `outer<T>(): <U = T>() => U` leaves `T` unspecialized
                        // when its only occurrence is the nested default.
                        for decl in type_parameters.iter() {
                            if let Some(constraint) = decl.constraint {
                                stack.push(constraint);
                            }
                            if let Some(default) = decl.default {
                                stack.push(default);
                            }
                        }
                    }
                    SemanticNodeData::TemplateLiteral { expressions, .. } => {
                        stack.extend(expressions.iter().copied());
                    }
                    SemanticNodeData::KeyOf { base } => stack.push(*base),
                    SemanticNodeData::IndexedAccess { object, index } => {
                        stack.push(*object);
                        if let IndexKey::Computed(idx_node) = index {
                            stack.push(*idx_node);
                        }
                    }
                    // A generic-application carrier's type-argument vector is a
                    // substitutable position (`Boxed<T>` — the carrier-preserving
                    // lowering of a generic type reference); `base` is a
                    // declaration identity with no binder occurrences.
                    SemanticNodeData::InstantiationRef { args, .. } => {
                        stack.extend(args.iter().copied());
                    }
                    SemanticNodeData::Conditional {
                        check,
                        extends,
                        true_branch_ref,
                        false_branch_ref,
                        pending,
                        ..
                    } => {
                        if let Some(pending) = pending {
                            stack.extend(pending.argument_nodes());
                        }
                        stack.push(*check);
                        stack.push(*extends);
                        stack.push(*true_branch_ref);
                        stack.push(*false_branch_ref);
                    }
                    SemanticNodeData::Mapped { source, mapper } => {
                        // The mapped SOURCE and key space evaluate in the outer
                        // scope; the VALUE / name-remap positions are inside the
                        // mapper binder's scope, so a mapped type whose OWN
                        // binder re-declares `name` owns every same-name
                        // occurrence there (TS lexical shadowing) — the same
                        // shadow stop the substitute engine applies to a
                        // shadowing mapper, decided per-name here because the
                        // binder node is what this walk is discovering.
                        stack.push(*source);
                        stack.push(mapper.key_space);
                        let mapper_shadows = self
                            .graph()
                            .node_data(mapper.parameter_node)
                            .as_deref()
                            .is_some_and(|binder| {
                                matches!(
                                    binder,
                                    SemanticNodeData::TypeParam { display_name, .. }
                                        if display_name.as_ref() == name
                                )
                            });
                        if !mapper_shadows {
                            stack.push(mapper.value_expr);
                            if let Some(remap) = mapper.name_remap {
                                stack.push(remap);
                            }
                        }
                    }
                    SemanticNodeData::MergedDecl { contributors } => {
                        stack.extend(contributors.iter().copied());
                    }
                    // A `BareRef` / `TypeOf` / `ImportType` carrier applies its
                    // arguments at the reference site — a substitutable position the
                    // substitute engine reaches, mirroring the `InstantiationRef`
                    // arm above. Descend the carrier args via the shared accessor
                    // (args-only; the carrier head is not resolved). The depth /
                    // visited guards bound the walk; carrier args are finite interned
                    // nodes (no infinite recursion via `apply_typeof_instantiation_args`,
                    // which calls this fn).
                    SemanticNodeData::BareRef(_) => {
                        // A DEFERRED head spelling the searched parameter, under
                        // `WithDeferredHeads`. A declaration's own type
                        // parameter is not in scope where its DECLARED return
                        // locator lowers (file owner scope), so `f<T>(): T`
                        // interns its return as an unbound `BareRef("T")` rather
                        // than a resolved binder — the same parameter, one
                        // resolution state earlier, and a caller instantiating
                        // the clause must claim both spellings or the deferred
                        // one escapes as a dangling name. The shadow stops above
                        // apply unchanged: a nested signature (or mapper) that
                        // re-declares the name is never descended into, so only
                        // occurrences the searched clause actually binds are
                        // claimed.
                        if spelling.claims_deferred_heads()
                            && data.bare_ref_head().is_some_and(|(head, _)| head == name)
                        {
                            found.push(node);
                        }
                        stack.extend(data.carrier_type_args().iter().copied());
                    }
                    SemanticNodeData::DeclRef { identity } => {
                        // A RESOLVED head spelling the searched parameter,
                        // under `WithOwnerScopeResolution` — the third
                        // resolution state of one clause parameter, alongside
                        // the bound `TypeParam` and the deferred `BareRef`.
                        //
                        // A declaration's own clause is not in scope where its
                        // DECLARED return locator lowers (file owner scope), so
                        // `f<T>(): T` interns its return as a bare `T` head —
                        // and when the file ALSO declares a type named `T`,
                        // that owner-scope lowering RESOLVES it, to the wrong
                        // symbol. `interface Item {}` beside
                        // `function first<Item>(xs: Item[]): Item` is the
                        // shape: the clause shadows the interface inside the
                        // function, so every `Item` in that return is the
                        // parameter, and a caller instantiating the clause must
                        // claim this spelling too — otherwise the callee
                        // publishes the unrelated INTERFACE as the caller's
                        // value, cleanly and warm, and the name-keyed check
                        // that catches the unresolved spelling sees nothing.
                        //
                        // This claim is NAME-scoped, and the name alone
                        // cannot tell the misresolution apart from an
                        // unrelated declaration that merely shares it — the
                        // interface `QQ` is the same node whether `aye<QQ>`
                        // exists or not. What discriminates is PROVENANCE:
                        // only a node lowered where the clause was out of
                        // scope can contain the misresolution at all, and a
                        // node evaluated with the clause BOUND spells the
                        // parameter `TypeParam` and nothing else. The caller
                        // supplies that provenance as the spelling level, so
                        // a body-derived arm never claims a foreign symbol.
                        //
                        // The shadow stops above apply unchanged: a nested
                        // signature (or mapper) re-declaring the name is never
                        // descended into, so only occurrences the searched
                        // clause actually binds are claimed.
                        if spelling.claims_owner_scope_resolution()
                            && identity.decl_name.as_ref() == name
                        {
                            found.push(node);
                        }
                    }
                    SemanticNodeData::TypeOf(_)
                    | SemanticNodeData::TypeOfNominal(_)
                    | SemanticNodeData::ImportType(_) => {
                        stack.extend(data.carrier_type_args().iter().copied());
                    }
                    _ => {}
                }
            }
            found
        }
    }

    /// Build a tuple node whose elements are the function's parameter
    /// types — the surface shape of `Parameters<F>` /
    /// `ConstructorParameters<F>`. Labels carry over from the parameter
    /// names (TS reflects them in hover); optional / rest flags track
    /// the original signature. `function_node` must be a
    /// `SemanticNodeData::Signature`; returns `None` otherwise.
    /// Re-intern `function_node`'s call signature with `ordinary` as its whole
    /// parameter list — the authored `this` receiver removed. Every other axis
    /// (kind, return type and carrier, binders, occurrence, spans) is carried
    /// through unchanged: the signature is the same occurrence minus its
    /// receiver slot. A type predicate does not survive: TypeScript rebuilds
    /// the signature as `(...args: A) => R` (measured on 7.0.2:
    /// `OmitThisParameter<(this: Foo, x: unknown) => x is Foo>` is
    /// `(x: unknown) => boolean`).
    pub(super) fn intern_signature_without_receiver(
        &self,
        function_node: SemanticNodeId,
        ordinary: &[crate::semantic_query::FunctionParam],
    ) -> SemanticNodeId {
        let Some(data) = self.graph().node_data(function_node) else {
            return function_node;
        };
        if let SemanticNodeData::DeferredCallable(callable) = data.as_ref() {
            return self.graph().intern_preserving_scope(
                function_node,
                SemanticNodeData::DeferredCallable(callable.without_receiver(ordinary)),
            );
        }
        let SemanticNodeData::Signature {
            kind,
            is_abstract,
            return_type,
            type_parameters,
            occurrence,
            return_carrier,
            signature_span,
            return_type_span,
            ..
        } = &*data
        else {
            return function_node;
        };
        let rebuilt = SemanticNodeData::Signature {
            kind: *kind,
            params: crate::semantic_query::PayloadArray::from(
                ordinary
                    .iter()
                    .map(crate::semantic_query::FunctionParam::copy)
                    .collect::<Vec<_>>()
                    .into_boxed_slice(),
            ),
            return_type: *return_type,
            type_parameters: type_parameters.share(),
            occurrence: occurrence.clone(),
            return_carrier: return_carrier.clone(),
            signature_span: *signature_span,
            return_type_span: *return_type_span,
            predicate: None,
            is_abstract: *is_abstract,
        };
        drop(data);
        self.graph().intern_preserving_scope(function_node, rebuilt)
    }

    pub(super) fn intern_function_params_tuple(
        &self,
        function_node: SemanticNodeId,
    ) -> Option<SemanticNodeId> {
        self.intern_function_params_tuple_from(function_node, 0)
    }

    /// [`Self::intern_function_params_tuple`] over the ordinary parameters
    /// from position `from` on — the checker's `getRestTypeAtPosition`.
    pub(super) fn intern_function_params_tuple_from(
        &self,
        function_node: SemanticNodeId,
        from: usize,
    ) -> Option<SemanticNodeId> {
        use crate::semantic_query::TupleElement;

        let data = self.graph().node_data(function_node)?;
        let params = match data.as_ref() {
            SemanticNodeData::Signature { params, .. } => Arc::clone(params.as_arc()),
            SemanticNodeData::DeferredCallable(callable) => Arc::clone(
                callable
                    .parts(&crate::semantic_query::ResolveOverloadSetConsumer::witness())
                    .params,
            ),
            _ => return None,
        };
        drop(data);
        // The authored `this` receiver takes no positional slot: TypeScript's
        // `Parameters<F>` / `ConstructorParameters<F>` publish the ordinary
        // parameters only.
        let elements: Vec<TupleElement> = crate::semantic_query::split_this_receiver(&params)
            .1
            .iter()
            .skip(from)
            .map(|param| TupleElement {
                label: param.name.clone(),
                // An optional parameter's tuple SLOT type is
                // `T | undefined` (TS widens the optional slot), while the
                // `optional` marker below keeps the `?` surface flag —
                // both are part of the published `Parameters<F>` shape.
                value: if param.optional {
                    let undefined = self.graph().intern_node(SemanticNodeData::Primitive(
                        crate::semantic_query::PrimitiveKind::Undefined,
                    ));
                    self.intern_normalized_union_or_intersection(&[param.ty, undefined], true)
                } else {
                    param.ty
                },
                optional: param.optional,
                rest: param.rest,
            })
            .collect();
        // Normalize-on-intern: a `(...args: E[])` signature's sole rest
        // slot collapses to `E[]`; concrete rest-of-tuple slots splice.
        // The Parameters tuple is mutable.
        Some(
            match self.normalize_tuple_spread(&elements, /* readonly */ false) {
                NormalizedTupleShape::Array(array_node) => array_node,
                NormalizedTupleShape::Tuple(elements) => {
                    self.graph().intern_node(SemanticNodeData::Tuple {
                        elements: elements.into(),
                        readonly: false,
                    })
                }
            },
        )
    }

    // Declaration identity is carried directly by
    // `SemanticQueryKey::Instantiate.base` (the env-bearing content-free
    // `ResolvedDeclSlotIdentity` slot), so there is no arena node to unwrap.

    /// Single-hop union-index distribution — the `IndexedAccessUnionDistribution`
    /// reduction for `Obj[A | B]`. Resolves the index node; when it denotes a
    /// closed set of literal keys or broad key kinds (a key union, `keyof T`
    /// over a closed `T`, or an intersection of those), projects `Obj[key]`
    /// per domain member through the shared `IndexedAccess`
    /// query and renormalises the results through `ReduceUnion`. Returns
    /// `None` (fall through to the path walker) for a non-`TypeNode` index, a
    /// single literal or broad key, an open/generic key, or any per-key projection
    /// miss — so symbolic / partial cases keep their carrier.
    fn distribute_union_index(
        &self,
        base: SemanticNodeId,
        index: &crate::semantic_query::IndexKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<crate::project_semantic_dispatch::walk::QueryBuildOutput> {
        use crate::semantic_query::IndexKey;
        let IndexKey::Computed(index_node) = index else {
            return None;
        };
        // A key-domain demand consumes the source index, not a published
        // keyof union that would be sorted only to enumerate it again.
        let domain_keys = matches!(
            self.graph().node_data(*index_node).as_deref(),
            Some(SemanticNodeData::KeyOf { .. })
        )
        .then(|| self.index_keys_from_keyspace_node(*index_node))
        .flatten();
        let resolved = if domain_keys.is_some() {
            *index_node
        } else {
            self.evaluate_deferred_semantic_node_with_context(*index_node, context)
                .into_active_query_build_node(self)
        };
        match self.graph().node_data(resolved).as_deref() {
            Some(SemanticNodeData::Literal(_)) => return None,
            Some(SemanticNodeData::Primitive(PrimitiveKind::Never)) => {
                let never = self.primitive_node(PrimitiveKind::Never);
                return Some(
                    super::walk::QueryBuildOutput::from((
                        QueryResult::Value(never),
                        self.project_generation_signature(),
                    ))
                    .with_observed_self_roots(self.observed_self_roots_from_nodes([base])),
                );
            }
            _ => {}
        }
        let keys = domain_keys
            .or_else(|| self.finite_index_keys(resolved))
            .or_else(|| self.index_keys_from_keyspace_node(resolved))?;
        if keys.is_empty() {
            let never = self.primitive_node(PrimitiveKind::Never);
            return Some(
                crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(never),
                    self.project_generation_signature(),
                ))
                .with_observed_self_roots(self.observed_self_roots_from_nodes([base])),
            );
        }
        // A single broad key belongs to the walker. Re-dispatching that same
        // index would recurse instead of selecting the mapped binder.
        if matches!(keys.as_slice(), [IndexKey::Computed(node)] if *node == resolved) {
            return None;
        }
        // Resolve the shared subject once through the same declaration and
        // peer-merge owners the per-key walker uses, with all their
        // contributor facts observed on this batch. No key-sized memo entry
        // needs to copy that full dependency closure.
        let subject = self
            .normalize_node_for_structural_fact_demand(
                base,
                context.into_structural_transit_with_mode(ProjectionMode::Shallow),
            )
            .into_complete_node()?;
        let object = match self.graph().node_data(subject).as_deref() {
            Some(SemanticNodeData::MergedDecl { contributors }) => {
                self.reduce_merged_decl(contributors)
            }
            _ => subject,
        };
        if let Some(data) = self.graph().node_data(object) {
            let fence = self.project_generation_signature();
            let mut walker = PathWalker::new(self, context, &fence);
            let values = match data.as_ref() {
                SemanticNodeData::Object(surface) => {
                    walker.finite_object_index_values(base, object, surface, &keys)
                }
                SemanticNodeData::Mapped { source, mapper } => {
                    match walker.finite_mapped_index_values(
                        object,
                        *source,
                        mapper,
                        &keys,
                        *index_node,
                    ) {
                        super::walk::FiniteMappedIndexValues::NotApplicable => None,
                        super::walk::FiniteMappedIndexValues::Complete(values) => Some(values),
                        super::walk::FiniteMappedIndexValues::Stopped(output) => {
                            return Some(*output)
                        }
                    }
                }
                _ => None,
            };
            if walker.completeness.is_partial() {
                let carrier = self.graph().intern_preserving_scope(
                    base,
                    SemanticNodeData::IndexedAccess {
                        object: base,
                        index: index.clone(),
                    },
                );
                let mut out = super::walk::QueryBuildOutput::from((
                    QueryResult::Value(carrier),
                    fence.clone(),
                ))
                .with_observed_self_roots(self.observed_self_roots_from_nodes([base, object]));
                out.merge_completeness(walker.completeness);
                out.cache_suppress = true;
                out.walker_diagnostics = std::mem::take(&mut walker.walker_diagnostics);
                return Some(out);
            }
            if let Some(values) = values {
                let norm = self.execute_read(SemanticQueryKey::ReduceUnion {
                    members: Arc::from(values.into_boxed_slice()),
                    nullability: verter_session_query::flow::policy::NullabilityPolicy::Strict,
                });
                if let QueryResult::Value(id) = norm.value {
                    let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                        QueryResult::Value(id),
                        fence.clone(),
                    ))
                    .with_observed_self_roots(self.observed_self_roots_from_nodes([base, object]));
                    out.fold_partial(norm.result_is_partial());
                    out.merge_completeness(walker.completeness);
                    out.cache_suppress |= walker.cache_suppress;
                    out.walker_diagnostics = std::mem::take(&mut walker.walker_diagnostics);
                    return Some(out);
                }
            }
        }
        let mut projected: Vec<SemanticNodeId> = Vec::with_capacity(keys.len());
        let mut any_partial = false;
        for member_index in keys {
            let read = self.execute_read(SemanticQueryKey::IndexedAccess {
                base,
                index: member_index,
                mode: context.mode,
            });
            if read.result_is_partial() {
                any_partial = true;
            }
            match read.value {
                // An arm whose KEY is absent aborts the distribution —
                // the walker reports an absent member as the
                // `Opaque(Miss)` sentinel, and tsgo ERRORS on
                // `Obj[1.5 | 2.5]` when an arm has no member, so
                // fabricating a partial union of the arms that DID
                // resolve would be unsound. Falling through to the path
                // walker keeps the honest single-needle miss. An arm
                // whose key EXISTS but whose VALUE is an opaque carrier
                // (a deferred `DeclPlaceholder` shell, an unresolved
                // declaration) is NOT a miss: the per-arm read returns
                // the member's stored value verbatim — exactly what the
                // single-key `Obj['b']` access publishes — so the
                // carrier contributes to the union (per-arm single-key
                // consistency; carrier-preserving shallow-by-default).
                //
                // This classification is sound only under the sentinel
                // discipline that `Opaque(Miss)` never surfaces as an
                // EXISTING member's per-arm terminal: existing members
                // project as real value nodes or addressable carriers
                // (`DeclPlaceholder`, `DeclRef`, `InstantiationRef`,
                // `Mapped`, deferred `IndexedAccess`). Every per-key
                // producer that could forge `Opaque(Miss)` for an
                // existing key by substituting into a builtin Identity
                // utility's lazy `value_expr` placeholder dispatches
                // `source[K]` through the shared `IndexedAccess` query
                // instead — the PathWalker's Mapped narrowing (guard:
                // `identity_utility_mapped_carrier_projects_existing_members_not_miss`),
                // the Shallow walker's `synthesise_mapped_surface` (guard:
                // `identity_utility_shallow_empty_path_surface_publishes_source_member_values_not_miss`),
                // and `build_mapped_type`'s per-key value selection (guard:
                // `identity_mapped_build_without_projectable_source_publishes_addressable_carrier_not_miss`).
                QueryResult::Value(id)
                    if !matches!(
                        self.graph().node_data(id).as_deref(),
                        Some(SemanticNodeData::Opaque(
                            crate::semantic_query::QueryError::Miss
                        ))
                    ) =>
                {
                    projected.push(id)
                }
                _ => return None,
            }
        }
        let norm = self.execute_read(SemanticQueryKey::ReduceUnion {
            members: Arc::from(projected.into_boxed_slice()),
            nullability: verter_session_query::flow::policy::NullabilityPolicy::Strict,
        });
        match norm.value {
            QueryResult::Value(id) => {
                let observed_self_roots = self.observed_self_roots_from_nodes([base]);
                let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(id),
                    self.project_generation_signature(),
                ))
                .with_observed_self_roots(observed_self_roots);
                out.fold_partial(any_partial || norm.result_is_partial());
                Some(out)
            }
            _ => None,
        }
    }

    /// The finite literal keys the resolved index node `index` denotes, in
    /// order, or `None` when it is not a finite set of literal keys:
    ///
    /// - a literal key is itself (a NUMERIC literal outside the bounded
    ///   integer convention — `Obj[1.5 | 1e21]` — stays a `TypeNode` key,
    ///   so the per-key `IndexedAccess` recovers its canonical
    ///   `js_number_to_string` needle through the same path as a single-key
    ///   access);
    /// - a union is every arm's keys;
    /// - `keyof T` over a `T` whose keys enumerate (a declaration carrier
    ///   resolves first) is those keys — `Box[keyof Box]` reads every
    ///   property;
    /// - an intersection is the keys common to every arm, in the first
    ///   arm's order — `'opt' & keyof Box` is `'opt'`;
    /// - a named key type (`type K = keyof Box`) is the keys its declaration
    ///   resolves to.
    ///
    /// Composites nest to any depth: they are read from a work list, and a
    /// key type that contains itself is not finite.
    /// [`Self::finite_index_keys`], for the tests beside this module.
    #[cfg(any(test, feature = "test-support"))]
    pub fn finite_index_keys_for_tests(
        &self,
        index: SemanticNodeId,
    ) -> Option<Vec<crate::semantic_query::IndexKey>> {
        self.finite_index_keys(index)
    }

    fn finite_index_keys(
        &self,
        index: SemanticNodeId,
    ) -> Option<Vec<crate::semantic_query::IndexKey>> {
        use crate::semantic_query::IndexKey;
        /// A key type waiting on its parts' keys.
        enum Pending {
            /// A union: every member's keys, first occurrence first — the
            /// keys kept so far deduplicated through a set, since a scan of
            /// them made a long key union quadratic.
            Union {
                node: SemanticNodeId,
                members: Arc<[SemanticNodeId]>,
                next: usize,
                keys: Vec<IndexKey>,
                seen: FxHashSet<IndexKey>,
            },
            /// A named key type: its declaration's keys.
            Named { node: SemanticNodeId },
        }
        let mut pending: Vec<Pending> = Vec::new();
        let mut open: FxHashSet<SemanticNodeId> = FxHashSet::default();
        let mut visit = Some(index);
        loop {
            // The keys of the node visited, when it has no parts.
            let mut keys: Option<Vec<IndexKey>> = None;
            // The set `keys` are deduplicated through, when a union handed
            // them up: a union whose first member is a union adopts both,
            // so a nest of unions hashes each key once, not once per level.
            let mut keys_seen: Option<FxHashSet<IndexKey>> = None;
            if let Some(node) = visit.take() {
                if open.contains(&node) {
                    return None;
                }
                let data = self.graph().node_data(node)?;
                match data.as_ref() {
                    SemanticNodeData::Union(members) => {
                        let members = members.members_arc();
                        drop(data);
                        open.insert(node);
                        pending.push(Pending::Union {
                            node,
                            keys: Vec::with_capacity(members.len()),
                            members,
                            next: 0,
                            seen: FxHashSet::default(),
                        });
                    }
                    SemanticNodeData::Intersection(_) | SemanticNodeData::KeyOf { .. } => {
                        drop(data);
                        let domain = self.key_literals_from_keyspace_node(node)?;
                        keys = Some(
                            domain
                                .into_iter()
                                .map(|key| match key.literal {
                                    Some(literal) => self.normalized_index_key_node(
                                        self.graph()
                                            .intern_node(SemanticNodeData::Literal(literal)),
                                    ),
                                    None => match key.key {
                                        crate::semantic_query::PropertyKey::UniqueSymbol(
                                            symbol,
                                        ) => IndexKey::UniqueSymbol(symbol),
                                        _ => unreachable!(
                                            "a string or numeric key carries its literal"
                                        ),
                                    },
                                })
                                .collect(),
                        );
                    }
                    SemanticNodeData::Literal(_) => {
                        drop(data);
                        keys = Some(vec![match self.normalized_index_key_node(node) {
                            key @ (IndexKey::String(_)
                            | IndexKey::Number(_)
                            | IndexKey::UniqueSymbol(_)) => key,
                            IndexKey::Computed(resolved) => {
                                match self.graph().node_data(resolved).as_deref() {
                                    Some(SemanticNodeData::Literal(LiteralValue::Number(_))) => {
                                        IndexKey::Computed(resolved)
                                    }
                                    _ => return None,
                                }
                            }
                        }]);
                    }
                    SemanticNodeData::DeclRef { .. }
                    | SemanticNodeData::InstantiationRef { .. } => {
                        drop(data);
                        let context = crate::semantic_query::ProjectionReductionContext::published(
                            ProjectionMode::Expanded,
                        );
                        let settled = self.resolve_signature_source_carrier(node, context);
                        if settled == node {
                            return None;
                        }
                        let settled = self
                            .evaluate_deferred_semantic_node_with_context(settled, context)
                            .into_active_query_build_node(self);
                        open.insert(node);
                        pending.push(Pending::Named { node });
                        visit = Some(settled);
                        continue;
                    }
                    _ => {
                        drop(data);
                        keys = Some(match self.normalized_index_key_node(node) {
                            key @ (IndexKey::String(_)
                            | IndexKey::Number(_)
                            | IndexKey::UniqueSymbol(_)) => vec![key],
                            IndexKey::Computed(_) => return None,
                        });
                    }
                }
            }
            // Deliver `keys` to the innermost waiting key type, closing each
            // one its parts complete.
            loop {
                let Some(top) = pending.last_mut() else {
                    return keys;
                };
                match top {
                    Pending::Union {
                        members,
                        next,
                        keys: collected,
                        seen,
                        ..
                    } => {
                        match (keys.take(), keys_seen.take()) {
                            (Some(delivered), Some(delivered_seen)) if collected.is_empty() => {
                                *collected = delivered;
                                *seen = delivered_seen;
                            }
                            (delivered, _) => {
                                for key in delivered.into_iter().flatten() {
                                    if first_index_key(seen, &key) {
                                        collected.push(key);
                                    }
                                }
                            }
                        }
                        if let Some(member) = members.get(*next) {
                            *next += 1;
                            visit = Some(*member);
                            break;
                        }
                        keys = Some(std::mem::take(collected));
                        keys_seen = Some(std::mem::take(seen));
                    }
                    Pending::Named { .. } => {}
                }
                let closed = match pending.pop().expect("the waiting key type") {
                    Pending::Union { node, .. } | Pending::Named { node } => node,
                };
                open.remove(&closed);
            }
        }
    }

    /// Path-precise projection. Walks each [`PathSegment`]
    /// from `base` via a fresh [`PathWalker`] that dispatches per-hop on
    /// every shell variant (`Object`, `Union`, `Intersection`,
    /// `Conditional`, `Alias`) and emits per-segment origin edges
    /// (`ProjectMember` / `ProjectIndex` / `AliasResolve` /
    /// `ConditionalSelect`). An empty path returns `base` directly —
    /// that is the canonical form of "expand the whole surface" (the
    /// retired `Expand` variant).
    ///
    /// Alias-cycle detection terminates with
    /// `Opaque(QueryError::AliasCycle)`; stack depth is additionally
    /// bounded by [`PathWalker::max_depth`]. Open conditionals
    /// distribute the remaining path into both branches via
    /// `SemanticQueryApi::execute` re-entry so each branch-projection
    /// is a separately memoised sub-query.
    ///
    /// Emits a whole-path `ProjectPath` edge on the result (when the
    /// result differs from the base) so consumers can recover the
    /// entry path without rebuilding it from per-segment edges.
    pub(super) fn build_project_path(
        &self,
        base: SemanticNodeId,
        path: &verter_type_expr::OwnedSlice<PathSegment>,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        verter_audit::attribute_n!(MacroMemberWalk, path.len());
        // A member read off a class's polymorphic `this` reads the class
        // instance, and binds `this` in the member to the binder itself.
        if let Some(instance) = self.this_binder_instance(base) {
            let mut output = self.build_project_path(instance, path, context);
            if let QueryResult::Value(node) = output.result {
                output.result = QueryResult::Value(self.bind_this_receiver(node, base));
            }
            return output;
        }
        // §22 fast-reject for the `?[K]` indexed-access shape: `any[K]=any`,
        // `never[K]=never`, `unknown[K]`=UNCONDITIONAL error, `error[K]=error`.
        // Member projection (`.foo`) is a distinct surface left to the walker.
        if Self::project_path_is_indexed_access(path) {
            if let Some(absorbed) = self.absorb_indexed_access(base) {
                return absorbed;
            }
        }
        // Union-index distribution (`Obj[A | B]` = `Obj[A] | Obj[B]`). A
        // single-hop indexed access whose closed domain contains literal keys
        // or broad key kinds distributes through the shared `IndexedAccess`
        // query and renormalises. Multi-segment paths, a single broad key, and
        // open/generic domains fall through to the path walker unchanged
        // (one engine — this re-dispatches the shared key, never hand-reduces).
        if let [PathSegment::Index(index)] = path.as_ref() {
            if let Some(distributed) = self.distribute_union_index(base, index, context) {
                return distributed;
            }
        }
        let fence = self.project_generation_signature();
        self.graph().record_path_length(path.len() as u32);
        // Longest-prefix-first peek. Skip when path.len() < 2.
        // Prefix entries are cached as Navigate regardless
        // of the caller's mode (path-precise rule — intermediate hops are
        // Navigate, terminal hop is the caller's mode).
        let (start_base, start_index) = if path.len() < 2 {
            (base, 0usize)
        } else {
            find_longest_warm_prefix(self.graph().store(), self.ctx, base, path, |receipt| {
                self.admits_served(receipt)
            })
            .unwrap_or((base, 0))
        };
        let walker_path: verter_type_expr::OwnedSlice<PathSegment> = if start_index == 0 {
            path.clone()
        } else {
            verter_type_expr::OwnedSlice::from(path[start_index..].to_vec().into_boxed_slice())
        };
        // The walker carries the full `ProjectionReductionContext`
        // (not just `mode`) so the empty-path Shallow synthesiser can
        // gate per-key Mapped surface materialisation on the demand
        // axis. Published(Shallow) walks enumerate & substitute mapped
        // members; StructuralTransit walks carrier-stop without
        // enumeration (per the boundary constraint that transit is the
        // non-publication rail).
        let mut walker = PathWalker::new(self, context, &fence);
        walker.record_prefix_receipts(start_base, &walker_path);
        let result = walker.walk(start_base, walker_path.as_ref());
        let prefix_receipts = walker.take_prefix_receipts();
        let intermediate_nodes = std::mem::take(&mut walker.intermediate_nodes);
        // A member read through a reference binds the member's polymorphic
        // `this` to that reference: a class member's `this` binder, and an
        // interface member's declared `this` (`x: this["y"]` read through
        // `A` is `A["y"]`), as the checker instantiates a member's `this`
        // type with the reference it is accessed through.
        let result = if path.len() == 1 && self.is_this_receiver(base) {
            self.bind_callee_receiver(result, base)
        } else {
            result
        };
        // Drain the walker's diagnostics + cache_suppress flag so the
        // memo no-poison contract sees them at admission time.
        let walker_diagnostics: Vec<crate::project_semantic_dispatch::walk::ShallowDiagnostic> =
            std::mem::take(&mut walker.walker_diagnostics);
        let cache_suppress = walker.cache_suppress;
        // The walker's OWN fatal / pathological stops name no class; the
        // classes it accumulated came from nested reads. A partial with an
        // empty set rides the anonymous bridge so the build never reports
        // "partial with no class".
        let completeness = match walker.completeness {
            crate::semantic_query::ResultCompleteness::Partial(reasons) if reasons.is_empty() => {
                crate::semantic_query::ResultCompleteness::Partial(
                    crate::semantic_query::PartialReasonSet::PROPAGATED,
                )
            }
            other => other,
        };
        // A completed member path has addressed every demanded position.
        // It can preserve a usable child's positional value without claiming
        // that an incomplete enclosing domain proves absence or exactness.
        // A stopped walk has no such interpretation. An opaque terminal can
        // forward only the explicit guarantee of its adopted child producer.
        let approximation =
            if let Some(interpretation) = walker.completed_child_interpretation(result) {
                Some(interpretation)
            } else if path.is_empty()
                && context.mode == ProjectionMode::Shallow
                && matches!(
                    self.graph().node_data(result).as_deref(),
                    Some(
                        SemanticNodeData::Object(_)
                            | SemanticNodeData::ObjectSpreadProgram(_)
                            | SemanticNodeData::Union(_)
                            | SemanticNodeData::Intersection(_)
                    )
                )
            {
                // Shallow synthesis emits positive member evidence. It never
                // establishes absent members or exact member values from a subset.
                Some(super::projection_fact::ProjectionInterpretation::PresenceOnly)
            } else if path.is_empty()
                && matches!(
                    self.graph().node_data(result).as_deref(),
                    Some(
                        SemanticNodeData::Conditional { .. }
                            | SemanticNodeData::Mapped { .. }
                            | SemanticNodeData::KeyOf { .. }
                            | SemanticNodeData::IndexedAccess { .. }
                            | SemanticNodeData::InstantiationRef { .. }
                            | SemanticNodeData::TemplateLiteral { .. }
                    )
                )
            {
                // The whole demand retained this expression and all its operands
                // as a suspended source at exactly the addressed position.
                Some(super::projection_fact::ProjectionInterpretation::Positional)
            } else {
                None
            };
        drop(walker);
        // Supplement §5.D.0 r17 — surface a budget-exceeded
        // sentinel as `QueryResult::Recursive` so §5.D.4
        // `no_cache_promotion_for_budget_exceeded_*` callers can
        // discriminate via a type-level `matches!(_, Recursive(_))`
        // check. The walker itself emits an `Opaque(RecursiveRef)`
        // node id; we surface it through the QueryResult variant so
        // the result is NOT cached as a warm `Value` (per CLAUDE.md
        // "cancelled / superseded / interrupted / budget-exceeded
        // ... must not be promoted as warm shared cache entries").
        if let Some(crate::semantic_query::SemanticNodeData::Opaque(
            crate::semantic_query::QueryError::RecursiveRef { .. },
        )) = self.graph().node_data(result).as_deref()
        {
            return crate::project_semantic_dispatch::walk::QueryBuildOutput {
                result: QueryResult::Recursive(result),
                dep_signature: fence,
                walker_diagnostics,
                cache_suppress,
                completeness,
                approximation: None,
                taint: crate::semantic_query::ResultTaint::Clean,
                observed_self_roots: Vec::new(),
                graph_carrier: None,
                self_root_canonicals: Arc::from([]),
                pending_prefix_backfills: Vec::new(),
                // Recursive / budget-exceeded sentinel — never warm-published,
                // so it records nothing the §3.4 gate could reuse.
                satisfied_projection: crate::semantic_query::demand::MaterializedSet::empty(),
                flow_completion: None,
            };
        }
        // Emit a whole-path `ProjectPath` edge on the result so consumers
        // can recover the entry path without rebuilding it from per-hop
        // edges.
        if result != base {
            crate::semantic_query_memo::record_origin_edge!(
                self.graph(),
                result,
                OriginEdgeKind::ProjectPath,
                Arc::from(vec![base].into_boxed_slice()),
                OriginMeta::Path(path.clone()),
                fence.clone(),
            );
        }
        // Collect intermediate path-prefix backfill records so a
        // sibling dispatch sharing the same prefix can short-circuit
        // through `find_longest_warm_prefix`. Backfill always targets
        // Navigate (path-precise rule — intermediate hops are
        // Navigate-mode entries). The terminal full-path key keeps the
        // caller's mode and is published by `execute_cooperative`'s
        // admission flow, not by this helper.
        //
        // Carrier-aware publication: the records accumulate onto
        // `QueryBuildOutput.pending_prefix_backfills` and the shared
        // cold-build helper publishes them AFTER `install_fact_tracer`
        // returns Ok so each backfilled memo entry's carrier holds the
        // parent's authoritative path-precise fact signature. Publishing
        // here before the tracer finalises would attach a legacy-only
        // signature derived from the fence (the pre-carrier behaviour
        // flagged in `publish_warm_if_absent`).
        let pending_prefix_backfills = collect_prefix_backfills(
            start_base,
            &walker_path,
            &intermediate_nodes,
            prefix_receipts,
        );
        // §3.4 materialised-record set for the TERMINAL entry: the
        // terminal point at the FULL path (the caller's terminal mode)
        // PLUS one `Demand::navigate(prefix)` per CONTIGUOUS LINEAR walked
        // intermediate (§3.5). This is what the compute ACTUALLY
        // materialised — a deep terminal that only `Navigate`-walked its
        // intermediates records a `Navigate` point there, NEVER the
        // terminal mode it never expanded at the prefix. The navigate-hop
        // points are inert for THIS family's warm-hit gate (every request
        // to family `(base, full_path)` is at `full_path`, so only the
        // terminal point can match), but they record the honest
        // materialisation per §3.4 and never inflate a prefix to the
        // terminal mode.
        let satisfied_projection =
            path_walk_materialized_set(path, context.mode, start_index, &intermediate_nodes);
        // Self-version rooting: the projection result depends on the
        // file content the projection `base` was lowered from. The
        // base node's origin scope (recorded in the arena sidecar)
        // names that file and the version observed at intern time —
        // root the memo entry on it so a content edit to the base's
        // file misses the warm read.
        let observed_self_roots = self.observed_self_roots_from_nodes([base]);
        crate::project_semantic_dispatch::walk::QueryBuildOutput {
            result: QueryResult::Value(result),
            dep_signature: fence,
            walker_diagnostics,
            cache_suppress,
            completeness,
            approximation,
            taint: crate::semantic_query::ResultTaint::Clean,
            observed_self_roots,
            graph_carrier: None,
            self_root_canonicals: Arc::from([]),
            pending_prefix_backfills,
            satisfied_projection,
            flow_completion: None,
        }
    }

    /// `keyof` projection. For an `Object` surface, materializes a union of
    /// the member names as `Primitive(String)` anchors — this matches the
    /// TS semantics that `keyof T` yields a union of string literals.
    /// For non-objects, returns `Opaque(Miss)`.
    ///
    /// Emits one `ProjectMember` edge per keyspace literal back to the
    /// source object base, carrying the member name in
    /// `OriginMeta::ProjectedMember` with provenance
    /// `MemberEdgeProvenance::KeyOfEnumerated`. The edge lets walkers
    /// reconstruct which source member each keyspace literal derives from.
    pub(super) fn build_key_of(
        &self,
        base: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        // §22 fast-reject: `keyof any`/`keyof never` = `string|number|symbol`,
        // `keyof unknown` = `never`, `keyof error` = `error`. A lattice-extreme
        // base resolves to a fully-determined keyspace regardless of mode, so
        // this runs before the carrier-stop and the structural keyspace walk.
        if let Some(absorbed) = self.absorb_key_of(base) {
            return absorbed;
        }
        let data = self.graph().node_data(base);
        let fence = self.project_generation_signature();
        // demand-driven reducer carrier-stop: when the
        // caller's context is not a publication-mode-Expanded demand,
        // return a deferred `KeyOf { base }` carrier instead of
        // reifying the keyspace as a literal-anchor union with one
        // `ProjectMember` edge per literal. Member-anchor reification
        // is publication-only work — relation-engine binding, generic
        // substitution, and other structural-transit callers consume
        // the carrier without paying for it. The check is purely on
        // `context`; no operand-name inspection.
        if !crate::semantic_query::may_reduce_operator(context) {
            let node = self.graph().intern_node(SemanticNodeData::KeyOf { base });
            let observed_self_roots = self.observed_self_roots_from_nodes([base]);
            return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(node),
                fence,
            ))
            .with_observed_self_roots(observed_self_roots);
        }
        // Two-signal fold: a `keyof` over an Intersection/Union enumerates
        // its keyspace through `member_names_for_published_projection`,
        // whose underlying ProjectPath read can be genuinely incomplete
        // (budget / recursion / walker-fatal). Carry that partiality onto
        // the published keyof surface.
        let keyof_is_partial = std::cell::Cell::new(false);
        let enumerated = std::cell::Cell::new(false);
        // The names a composite's surface publishes. A stopped enumeration
        // holds only the names it reached, so its keys stay the deferred
        // `keyof`, never that subset (an empty one would read as `never`).
        let published_names = || match self.member_names_for_published_projection(base) {
            Some((_, true)) => {
                keyof_is_partial.set(true);
                None
            }
            Some((names, false)) => Some(names),
            None => self.key_names_from_base_node(base),
        };
        let intern_keys = |names| {
            let node = self.intern_keyspace_keys(base, names, &fence);
            if node.is_some() {
                enumerated.set(true);
            }
            node
        };
        let node = match data.as_deref() {
            // The non-primitive `object` declares no member, so it has no
            // key (`keyof object` is `never`), as nullish types have none.
            Some(SemanticNodeData::Primitive(
                PrimitiveKind::Null | PrimitiveKind::Undefined | PrimitiveKind::Object,
            )) => self.primitive_node(PrimitiveKind::Never),
            // `keyof ClassType` yields only public keys (TS semantics): a
            // private/protected member is not part of the keyspace. Filter
            // non-public members out here, the direct-Object keyof chokepoint.
            Some(SemanticNodeData::Object(surface)) => {
                let keys = surface
                    .positive_members()
                    .iter()
                    .filter(|member| member.visibility.is_public())
                    .filter_map(|member| member.key.cloned_known())
                    .collect::<Vec<_>>();
                // An index signature contributes its key type — a `string`
                // one `string | number`, since a numeric key reads it too
                // (`getLiteralTypeFromProperties`) — beside the members'
                // literal keys, which a `string` key type absorbs. An enum's
                // reverse mapping is no key of its object.
                let enum_object = self.is_enum_object(base);
                let index_keys: Vec<SemanticNodeId> = surface
                    .index_signatures
                    .iter()
                    .filter(|_| !enum_object)
                    .flat_map(|signature| {
                        let string_key = matches!(
                            self.graph().node_data(signature.key_type).as_deref(),
                            Some(SemanticNodeData::Primitive(PrimitiveKind::String))
                        );
                        std::iter::once(signature.key_type).chain(string_key.then(|| {
                            self.graph()
                                .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Number))
                        }))
                    })
                    .collect();
                let literal_keys = intern_keys(keys);
                match (literal_keys, index_keys.is_empty()) {
                    (Some(literal_keys), true) => literal_keys,
                    (Some(literal_keys), false) => {
                        let members: Vec<SemanticNodeId> =
                            std::iter::once(literal_keys).chain(index_keys).collect();
                        self.intern_normalized_union_or_intersection(&members, true)
                    }
                    (None, _) => self.graph().intern_node(SemanticNodeData::KeyOf { base }),
                }
            }
            Some(SemanticNodeData::Intersection(members)) => {
                let members = members.members_arc();
                match self.key_of_composite(&members, false) {
                    Some(keys) => { enumerated.set(true); keys },
                    // An arm over a generic (`keyof (S & { a: 1 })`) has
                    // keys only its instantiation names: the keys stay the
                    // deferred `keyof`, never the other arms' names alone.
                    None if self.intersection_key_arms(&members).into_iter().any(|arm| {
                        self.key_set_of(arm).is_none()
                            && super::raise::builtin_lowering_argument_is_open(self, arm)
                    }) =>
                    {
                        self.graph().intern_node(SemanticNodeData::KeyOf { base })
                    }
                    None => published_names()
                        .and_then(&intern_keys)
                        .unwrap_or_else(|| {
                            self.graph().intern_node(SemanticNodeData::KeyOf { base })
                        }),
                }
            }
            Some(SemanticNodeData::Union(members))
                if self.key_of_composite(&members.members_arc(), true).is_some() =>
            {
                enumerated.set(true);
                self.key_of_composite(&members.members_arc(), true)
                    .expect("the keys settled")
            }
            Some(SemanticNodeData::Union(_)) => published_names()
                .and_then(&intern_keys)
                .unwrap_or_else(|| self.graph().intern_node(SemanticNodeData::KeyOf { base })),
            // Declaration Merging (CRITICAL): `keyof <merged decl>` routes
            // through the single peer-merge reducer to the merged
            // `Object`/`Intersection` surface, then re-runs THIS keyspace
            // reducer on it — `keyof` is a `MergedDecl` consumer of
            // `reduce_merged_decl` (a bare `Intersection` is forbidden as the
            // merged-decl representation, so the Intersection arm must not own
            // the merge). The reduced surface is freshly interned with no file
            // scope of its own, and the `MergedDecl` carrier is scoped only to
            // its base/importing file — but an AUGMENTED `MergedDecl`
            // (cross-file `declare module` / `declare global`) carries
            // contributor nodes lowered in AUGMENTER file scopes (Declaration
            // Augmentation CRITICAL). Root the entry on `base` PLUS every
            // contributor node, deduped — the same self-root collection the
            // peer-merge surface roots on. A SAME-FILE merge's contributors are
            // all base-scoped, so this folds back to `[base]`; for a cross-file
            // augmented merge it additionally records each augmenter's
            // `FileWholeHash`, so an edit to ANY contributor file (base OR
            // augmenter) misses the warm keyof entry. Nested-read partiality
            // (an incomplete heritage projection) folds through the
            // re-dispatched output verbatim.
            // A class expression's instance has the keys of the surface it
            // reads through: its public members (a `#private` or
            // `private` member is no key). Two or more keep the class as
            // their origin, the checker's `keyof (Anonymous class)` /
            // `keyof Expr`; the key set a relation reads is
            // [`Self::key_set_of`].
            Some(SemanticNodeData::ClassExpressionInstance { .. }) => {
                drop(data);
                let Some(surface) = self.class_expression_read_surface(base) else {
                    return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                        QueryResult::Value(self.opaque(QueryError::Miss)),
                        fence,
                    ));
                };
                let observed_self_roots = self.observed_self_roots_from_nodes([base, surface]);
                let mut keys = self.build_key_of(surface, context);
                let keeps_origin = matches!(
                    &keys.result,
                    QueryResult::Value(node) if matches!(
                        self.graph().node_data(*node).as_deref(),
                        Some(SemanticNodeData::Union(members)) if members.len() > 1
                    )
                );
                if keeps_origin {
                    keys.result =
                        QueryResult::Value(self.graph().intern_node(SemanticNodeData::KeyOf { base }));
                }
                return keys.with_observed_self_roots(observed_self_roots);
            }
            Some(SemanticNodeData::MergedDecl { contributors }) => {
                let merged = self.reduce_merged_decl(contributors);
                let observed_self_roots = self.observed_self_roots_from_nodes(
                    std::iter::once(base).chain(contributors.iter().copied()),
                );
                return self
                    .build_key_of(merged, context)
                    .with_observed_self_roots(observed_self_roots);
            }
            // An array's keys are its apparent wrapper's (`keyof T[]` IS
            // `keyof Array<T>`).
            Some(SemanticNodeData::Array { .. }) => {
                drop(data);
                return self.build_array_key_of(base, context);
            }
            // A function or constructor type has no properties: its call
            // and construct signatures name no key.
            Some(SemanticNodeData::Signature { .. }) => self.primitive_node(PrimitiveKind::Never),
            Some(SemanticNodeData::Mapped { .. }) => self
                .key_of_through_carrier(base, context)
                .unwrap_or_else(|| self.graph().intern_node(SemanticNodeData::KeyOf { base })),
            Some(
                SemanticNodeData::TypeParam { .. }
                | SemanticNodeData::IndexedAccess { .. }
                | SemanticNodeData::TypeOf(_)
                | SemanticNodeData::TypeOfNominal(_)
                | SemanticNodeData::Conditional { .. }
                | SemanticNodeData::Alias(_)
                // Un-resolved reference carriers. Navigate / Skeleton body
                // lowering deliberately preserves a no-args named reference
                // as a `DeclRef` / `InstantiationRef` shell (cycle-BFS
                // visibility — the carrier-preservation branch in
                // `lower.rs`), so a COLD reduce-demanded keyof can receive
                // one as its operand. Per this builder's contract
                // (documented at the `materialize_through_aliases` KeyOf
                // bridge arm), an un-resolved reference operand returns the
                // DEFERRED carrier — the bridge surfaces the operand through
                // the shared empty-path projection and re-dispatches —
                // rather than degrading the whole reduction to a
                // `semanticMiss` terminal.
                | SemanticNodeData::DeclRef { .. }
                | SemanticNodeData::InstantiationRef { .. }
                | SemanticNodeData::Opaque(QueryError::DeclPlaceholder { .. }),
            ) => self.graph().intern_node(SemanticNodeData::KeyOf { base }),
            // A construction program base enumerates through the shared
            // key-name enumerator (its program arm projects the correlated
            // formula): a CLOSED formula yields the exact keyspace; an
            // open / multi-alternative formula has no exact key domain, so
            // keyof is the DEFERRED `KeyOf` carrier (re-dispatchable when
            // the operand closes) — never a bare warm-admittable
            // `Opaque(Miss)`.
            Some(SemanticNodeData::ObjectSpreadProgram(_)) => self
                .key_names_from_base_node(base)
                .and_then(intern_keys)
                .unwrap_or_else(|| self.graph().intern_node(SemanticNodeData::KeyOf { base })),
            _ => self.opaque(QueryError::Miss),
        };
        // Self-version rooting: `keyof base` depends on `base`'s member
        // surface, which was lowered from the file `base` originates in.
        // Root the memo entry on that file's observed content version.
        let observed_self_roots = self.observed_self_roots_from_nodes([base]);
        let mut keyof_output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node),
            fence,
        ))
        .with_observed_self_roots(observed_self_roots);
        keyof_output.fold_partial(keyof_is_partial.get());
        // The enumeration above emitted only keys contributed by the source;
        // an unresolved source retains its addressed keyof continuation.
        keyof_output.approximation = enumerated
            .get()
            .then_some(super::projection_fact::ProjectionInterpretation::PresenceOnly);
        keyof_output
    }

    /// Whether the intersection of `arms` is one the checker reduces to
    /// `never` (`getReducedType`): the object types its arms name declare
    /// one property whose literal types conflict (`{ c: 1 }` beside
    /// `{ c: 2 }`), read through the declarations the arms name.
    pub(super) fn intersection_arms_reduce_to_never(&self, arms: &[SemanticNodeId]) -> bool {
        let published =
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Expanded);
        let surfaces: Vec<SemanticNodeId> = arms
            .iter()
            .map(|arm| self.resolve_signature_source_carrier(*arm, published))
            .collect();
        let mut evidence = super::canonical_algebra::CanonicalEvidence::default();
        let conflicts = super::canonical_algebra::object_arms_conflict_on_a_literal_property(
            self.graph(),
            &surfaces,
            self.construction_meter(),
            &mut evidence,
        );
        self.deposit_canonical_evidence(evidence);
        conflicts
    }

    /// `keyof` over a union or intersection as the checker's `getIndexType`
    /// reads it: the keys every member of a union has (the intersection of
    /// their key types) and the keys of any member of an intersection (their
    /// union), each member's keys read whole — its index signatures'
    /// key types beside its property names — and `keyof never` for an
    /// intersection the checker reduces to `never` (a property whose
    /// literal types conflict, `getReducedType`). `None` when a member's
    /// keys do not settle, or when every member's keys are property names
    /// alone (the name enumeration reads those).
    fn key_of_composite(
        &self,
        members: &[SemanticNodeId],
        is_union: bool,
    ) -> Option<SemanticNodeId> {
        if !is_union && self.intersection_arms_reduce_to_never(members) {
            return Some(self.string_number_symbol());
        }
        let flattened;
        let members = if is_union {
            members
        } else {
            flattened = self.intersection_key_arms(members);
            &flattened
        };
        let keys: Vec<SemanticNodeId> = members
            .iter()
            .map(|member| self.key_set_of(*member))
            .collect::<Option<_>>()?;
        // A union has only keys shared by every arm. An empty arm's key
        // set is complete negative evidence, including nullish operands.
        if is_union
            && keys.iter().any(|key| {
                matches!(
                    self.graph().node_data(*key).as_deref(),
                    Some(SemanticNodeData::Primitive(PrimitiveKind::Never))
                )
            })
        {
            return Some(self.primitive_node(PrimitiveKind::Never));
        }
        let names_alone = keys.iter().all(|keys| {
            let graph = self.graph();
            let literal = |node: SemanticNodeId| {
                matches!(
                    graph.node_data(node).as_deref(),
                    Some(
                        SemanticNodeData::Literal(_)
                            | SemanticNodeData::Primitive(PrimitiveKind::Never)
                    )
                )
            };
            match graph.node_data(*keys).as_deref() {
                Some(SemanticNodeData::Union(members)) => {
                    members.members_arc().iter().all(|m| literal(*m))
                }
                _ => literal(*keys),
            }
        });
        if names_alone {
            return None;
        }
        Some(self.intern_normalized_union_or_intersection(&keys, !is_union))
    }

    /// The arms of an intersection whose keys `keyof` unions, with every
    /// nested intersection spread in place — one written inside it, or the
    /// body a declaration or application resolves to (an interface's or
    /// class's heritage) — the flattening the checker's `getIntersectionType`
    /// gives the same type. The walk is iterative, so a chain of N heritage
    /// levels or N nested `&` operands is N sibling key reads, never N
    /// nested `keyof` queries.
    fn intersection_key_arms(&self, members: &[SemanticNodeId]) -> Vec<SemanticNodeId> {
        let transit = crate::semantic_query::ProjectionReductionContext::structural_transit();
        let mut arms = Vec::with_capacity(members.len());
        let mut seen = FxHashSet::default();
        let mut pending: Vec<SemanticNodeId> = members.iter().rev().copied().collect();
        while let Some(arm) = pending.pop() {
            if !seen.insert(arm) {
                continue;
            }
            let nested = match self.graph().node_data(arm).as_deref() {
                Some(SemanticNodeData::Intersection(nested)) => Some(nested.members_arc()),
                Some(
                    SemanticNodeData::DeclRef { .. } | SemanticNodeData::InstantiationRef { .. },
                ) => {
                    let settled = self.resolve_signature_source_carrier(arm, transit);
                    match self.graph().node_data(settled).as_deref() {
                        Some(SemanticNodeData::Intersection(nested)) if settled != arm => {
                            Some(nested.members_arc())
                        }
                        _ => None,
                    }
                }
                _ => None,
            };
            match nested {
                Some(nested) => pending.extend(nested.iter().rev().copied()),
                None => arms.push(arm),
            }
        }
        arms
    }

    /// `keyof` over a carrier the checker resolves: a declaration, an
    /// application, a mapped type. A mapped type's keys are its key space
    /// — for a homomorphic one, `keyof` of its source (`keyof Partial<X>`
    /// is `keyof X`) — and a builtin utility's are the keys it produces
    /// (`keyof Pick<X, 'a' | 'b'>` is `"a" | "b"`); a declaration's are its
    /// public members, read off the surface it resolves to. A key union of
    /// two or more over a declaration or a user generic application stays
    /// that type's `keyof` carrier, the origin the checker prints (`keyof
    /// Face`, `keyof G<1>`); one key is that key (`keyof D1` over `class
    /// D1 { p = 1 }` is `"p"`). The key set a relation reads is
    /// [`Self::key_set_of`]. `None` when the carrier does not resolve (an
    /// open operand keeps its carrier).
    pub(super) fn key_of_through_carrier(
        &self,
        base: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        let read = |base: SemanticNodeId| self.complete_key_of(base, context);
        let settled_keys = |keys: SemanticNodeId| {
            (!matches!(
                self.graph().node_data(keys).as_deref(),
                Some(SemanticNodeData::KeyOf { .. } | SemanticNodeData::Opaque(_))
            ))
            .then_some(keys)
        };
        let named = match self.graph().node_data(base).as_deref() {
            Some(SemanticNodeData::DeclRef { identity }) => Some(identity.clone()),
            Some(SemanticNodeData::InstantiationRef { base: identity, .. })
                if identity.canonical_id.as_ref() != "__builtin__" =>
            {
                Some(identity.clone())
            }
            _ => None,
        };
        // A mapped type — written, or a declaration or application whose
        // body is one — is read before it materializes, so a homomorphic
        // one answers `keyof` its source. A declaration materializes once,
        // under the demand every other reader of it shares.
        let transit_settled = match self.graph().node_data(base).as_deref() {
            Some(SemanticNodeData::Mapped { .. }) => Some(base),
            Some(SemanticNodeData::InstantiationRef { .. } | SemanticNodeData::DeclRef { .. }) => {
                Some(self.resolve_signature_source_carrier(
                    base,
                    crate::semantic_query::ProjectionReductionContext::structural_transit(),
                ))
            }
            _ => None,
        };
        // The checker reads a mapped type's keys off its constraint
        // (`getIndexTypeForMappedType`), never as a declaration's key list:
        // they carry no `keyof` origin of their own.
        let mut mapped = false;
        if let Some(SemanticNodeData::Mapped { source, mapper }) = transit_settled
            .and_then(|settled| self.graph().node_data(settled))
            .as_deref()
        {
            if crate::project_semantic_dispatch::raise::mapped_type_key_domain_is_open_or_unknown(
                self, *source, mapper,
            ) {
                return None;
            }
            mapped = true;
            // A key remapping's keys are the remapped names the
            // materialized type holds (`keyof Getters<{ a: 1 }>` is
            // `"getA"`).
            if mapper.name_remap.is_none() {
                return match self.graph().node_data(mapper.key_space).as_deref() {
                    Some(SemanticNodeData::KeyOf { base: keyed }) if *keyed == *source => {
                        read(*source).and_then(|keys| {
                            // `keyof` over the source keeps its own printed
                            // form (`keyof Partial<Face>` prints `keyof Face`).
                            match self.graph().node_data(keys).as_deref() {
                                Some(SemanticNodeData::Opaque(_)) => None,
                                _ => Some(keys),
                            }
                        })
                    }
                    _ => settled_keys(
                        self.evaluate_deferred_semantic_node_with_context(
                            mapper.key_space,
                            context,
                        )
                        .into_active_query_build_node(self),
                    ),
                };
            }
        }
        // A settled source surface already owns the member names and index
        // signatures. Reuse that key-domain demand instead of materializing
        // another declaration body at the published value's altitude.
        let settled = transit_settled
            .filter(|node| {
                matches!(
                    self.graph().node_data(*node).as_deref(),
                    Some(SemanticNodeData::Object(_))
                )
            })
            .unwrap_or_else(|| {
                self.resolve_signature_source_carrier(
                    base,
                    context.with_mode(ProjectionMode::Navigate),
                )
            });
        if settled == base {
            return None;
        }
        let keys = read(settled)?;
        // A class expression's instance is the class the checker names its
        // keys by (`keyof (Anonymous class)`), whatever alias or application
        // reaches it.
        if let Some(SemanticNodeData::KeyOf { base: kept }) =
            self.graph().node_data(keys).as_deref()
        {
            if matches!(
                self.graph().node_data(*kept).as_deref(),
                Some(SemanticNodeData::ClassExpressionInstance { .. })
            ) {
                return Some(keys);
            }
        }
        let keys = settled_keys(keys)?;
        // A union's keys are those every member shares and an
        // intersection's those of any member (`getIndexType` over a union or
        // intersection), read off the members, so an alias naming one leaves
        // no `keyof` origin (`keyof U` over `type U = { k: 1 } | { k: 2 }`
        // prints `"k"`); a class or interface keeps its own even where its
        // heritage resolves to an intersection.
        let composite = named.as_ref().is_some_and(|identity| {
            self.prepared_decl_kind(identity)
                == Some(verter_session_query::declarations::TypeDeclKind::Alias)
        }) && matches!(
            self.graph().node_data(settled).as_deref(),
            Some(SemanticNodeData::Union(_) | SemanticNodeData::Intersection(_))
        );
        match self.graph().node_data(keys).as_deref() {
            // The checker's key list is one type per property and per index
            // signature — a `string` index contributing its prebuilt
            // `string | number` — and a one-type list is that type itself,
            // with no `keyof` origin (`keyof Rec` over `{ [k: string]:
            // number }` prints `string | number`; a property or a second
            // index signature beside it keeps the origin).
            Some(SemanticNodeData::Union(_)) if self.keys_are_one_string_index(settled) => {
                Some(keys)
            }
            Some(SemanticNodeData::Union(members))
                if named.is_some() && !mapped && !composite && members.len() > 1 =>
            {
                None
            }
            _ => Some(keys),
        }
    }

    /// Whether `surface` declares no property and exactly one index
    /// signature, keyed by `string`.
    fn keys_are_one_string_index(&self, surface: SemanticNodeId) -> bool {
        match self.graph().node_data(surface).as_deref() {
            Some(SemanticNodeData::Object(view)) => {
                view.positive_members().is_empty()
                    && matches!(
                        view.index_signatures.as_ref(),
                        [signature] if matches!(
                            self.graph().node_data(signature.key_type).as_deref(),
                            Some(SemanticNodeData::Primitive(PrimitiveKind::String))
                        )
                    )
            }
            _ => false,
        }
    }

    /// The `keyof base` query's answer when it is complete. A read that
    /// stopped short holds no key set — an empty one would read as
    /// `never` — so its partiality folds into the caller and the answer
    /// is `None`.
    fn complete_key_of(
        &self,
        base: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        let read = self.execute_read(SemanticQueryKey::KeyOf { base, context });
        if read.result_is_partial() {
            self.fold_local_partial_completeness(read.partial_reason_classes());
            return None;
        }
        match read.value {
            QueryResult::Value(node) => Some(node),
            _ => None,
        }
    }

    /// The literal keys `keyof base` denotes — the set a relation or a
    /// comparability question reads, whichever `keyof` carrier stands for
    /// it in print. `None` when the keys do not settle or their read
    /// stopped short.
    pub(super) fn key_set_of(&self, base: SemanticNodeId) -> Option<SemanticNodeId> {
        let published =
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Expanded);
        let read = |base: SemanticNodeId| self.complete_key_of(base, published);
        // Each step settles the carrier a `keyof` kept to the type it
        // stands for — a declaration or application to its body, a class
        // expression's instance (which keeps its `keyof` origin) to the
        // surface it reads through — until the keys settle; a carrier that
        // settles to itself keeps its keys open.
        let mut keys = read(base)?;
        let mut seen = FxHashSet::default();
        loop {
            let kept = match self.graph().node_data(keys).as_deref() {
                Some(SemanticNodeData::KeyOf { base: kept }) => *kept,
                _ => return Some(keys),
            };
            if !seen.insert(kept) {
                return None;
            }
            let settled = match self.class_expression_read_surface(kept) {
                Some(surface) => surface,
                None => self.resolve_signature_source_carrier(
                    kept,
                    crate::semantic_query::ProjectionReductionContext::structural_transit(),
                ),
            };
            if settled == kept {
                return None;
            }
            keys = read(settled)?;
        }
    }

    pub(super) fn intern_keyspace_keys<I>(
        &self,
        base: SemanticNodeId,
        keys: I,
        fence: &DepSignature,
    ) -> Option<SemanticNodeId>
    where
        I: IntoIterator<Item = PropertyKey>,
    {
        let mut seen = FxHashSet::default();
        let mut member_literals: Vec<(SemanticNodeId, PropertyKey)> = Vec::new();
        for key in keys {
            if !seen.insert(key.clone()) {
                continue;
            }
            let node = match &key {
                PropertyKey::String(name) => {
                    self.graph()
                        .intern_node(SemanticNodeData::Literal(LiteralValue::String(
                            name.as_ref().to_string(),
                        )))
                }
                PropertyKey::Number(number) => {
                    self.graph()
                        .intern_node(SemanticNodeData::Literal(LiteralValue::Number(
                            number.get() as f64,
                        )))
                }
                PropertyKey::UniqueSymbol(identity) => self.unique_symbol_key_type(identity),
            };
            member_literals.push((node, key));
        }
        for (lit_id, key) in &member_literals {
            crate::semantic_query_memo::record_origin_edge!(
                self.graph(),
                *lit_id,
                OriginEdgeKind::ProjectMember,
                Arc::from(vec![base].into_boxed_slice()),
                OriginMeta::ProjectedMember {
                    key: key.clone(),
                    provenance: verter_audit::MemberEdgeProvenance::KeyOfEnumerated,
                },
                fence.clone(),
            );
        }
        let ids: Vec<SemanticNodeId> = member_literals.into_iter().map(|(id, _)| id).collect();
        // Canonical construction: the enumerated `keyof` key union (empty
        // folds to `never`, singleton to the lone key — the canonical folds).
        Some(self.intern_normalized_union_or_intersection(&ids, true))
    }

    /// The type a mapped type's binder takes for one key of its domain: the
    /// key's literal, or a `unique symbol` key's nominal type
    /// ([`Self::unique_symbol_key_type`]).
    pub(super) fn key_domain_binder(
        &self,
        key: &super::enumerate::KeyDomainKey,
    ) -> Option<SemanticNodeId> {
        if let Some(binder) = key.binder {
            return Some(binder);
        }
        match (&key.literal, &key.key) {
            (Some(literal), _) => Some(
                self.graph()
                    .intern_node(SemanticNodeData::Literal(literal.clone())),
            ),
            (None, PropertyKey::UniqueSymbol(identity)) => {
                Some(self.unique_symbol_key_type(identity))
            }
            (None, _) => None,
        }
    }

    /// The type of a `unique symbol` property key: the nominal `typeof`
    /// carrier of the symbol's declaration, headed by that declaration's own
    /// name (the nominal relation compares the declaring identity, so it is
    /// the symbol's type wherever it was written). Interned once per
    /// declaration, and released with the declaring file
    /// (`payload_binds_canonical` reads the identity).
    pub(super) fn unique_symbol_key_type(
        &self,
        identity: &verter_type_expr::facts::ValueDeclIdentityPart,
    ) -> SemanticNodeId {
        let value_root = crate::semantic_query::ValueRootKey {
            scope: crate::semantic_query::ScopeId::file(
                identity.canonical_id.clone(),
                identity.owner,
            ),
            name: identity.symbol.clone(),
        };
        let path: verter_type_expr::OwnedSlice<verter_type_expr::OwnedStr> = identity
            .member_path
            .iter()
            .map(|segment| verter_type_expr::OwnedStr::from(segment.as_str()))
            .collect();
        self.graph()
            .intern_node(SemanticNodeData::new_nominal_typeof(
                value_root,
                path,
                identity.clone(),
            ))
    }

    pub(super) fn uses_synthetic_mapped_key_names(&self, members: &[SurfaceMember]) -> bool {
        !members.is_empty()
            && members.iter().all(|member| {
                member
                    .string_name()
                    .and_then(|name| name.strip_prefix("key_"))
                    .is_some_and(|suffix| {
                        !suffix.is_empty() && suffix.chars().all(|ch| ch.is_ascii_digit())
                    })
            })
    }

    construction_ordinal_seam! {
        /// Resolve a source carrier to the one-level published member surface.
        ///
        /// Mapped-type publication needs full [`SurfaceMember`] records, not
        /// names alone: identity mappers (`Partial<T>` / `Required<T>` /
        /// `Readonly<T>`) must reuse each source member's `value`, while
        /// modifier-preserving mappers inherit `optional` and `readonly`.
        /// The global key-name enumerators intentionally return names only
        /// and do not unwrap `DeclRef` / `InstantiationRef` carriers, so
        /// publication code uses this local surface helper when a source is
        /// not already an `Object`.
        ///
        /// Non-public members are EXCLUDED from the result. This is the keyof /
        /// mapped / Pick keyspace chokepoint: TypeScript's `keyof ClassType`
        /// yields only public keys, so `Partial<ClassWithPrivate>` /
        /// `Pick<ClassWithPrivate, K>` / `{ [K in keyof ClassWithPrivate]: V }`
        /// must not carry the non-public members at all. The keep-all native
        /// surface (`native_props`) reads the member surface DIRECTLY (it does
        /// not route through this published-projection helper), so it is
        /// unaffected by this filter.
        /// Returns the source's public members for a published projection,
        /// PLUS the partiality CLASSES of the underlying `ProjectPath` read
        /// (two-signal fold, class-preserving). A genuinely-incomplete
        /// projection (budget / recursion / walker-fatal) surfaces a
        /// complete-looking member list here; the typed reason set carries
        /// that partiality so `build_mapped_type` / the Shallow walker's
        /// `synthesise_mapped_surface` can taint their surfaces WITHOUT
        /// collapsing the class to a bare bool — a classless partial re-lifts
        /// as the anonymous `PROPAGATED` bridge downstream, turning a
        /// contained positional class (a member-local flow-return marker) into
        /// a request-class fault no consumer lane contains. The fast path over
        /// an already-resolved `Object` node is always complete (empty set).
        fn source_members_for_published_projection(
            &self,
            source: SemanticNodeId,
            caller_context: crate::semantic_query::ProjectionReductionContext,
        ) -> Option<(Vec<SurfaceMember>, crate::semantic_query::PartialReasonSet)> {
            self.source_projection_with_key_domain(source, caller_context, false)
                .map(|(members, reasons, _, _)| (members, reasons))
        }
    }

    /// Keep the shallow surface's finite-domain witness beside its members.
    /// Dropping this witness makes a named dictionary look like a finite map.
    /// The surface's listed index signatures ride beside it: a homomorphic
    /// mapping maps each one, as it maps each member. `keys_only` when the
    /// caller reads the members' keys and modifiers but never their values
    /// ([`Self::declared_non_object_projection`]).
    fn source_projection_with_key_domain(
        &self,
        source: SemanticNodeId,
        caller_context: crate::semantic_query::ProjectionReductionContext,
        keys_only: bool,
    ) -> Option<(
        Vec<SurfaceMember>,
        crate::semantic_query::PartialReasonSet,
        bool,
        Vec<crate::semantic_query::IndexSignature>,
    )> {
        fn public_members(members: &[SurfaceMember]) -> Vec<SurfaceMember> {
            members
                .iter()
                .filter(|member| member.visibility.is_public())
                .map(crate::semantic_query::SurfaceMember::clone)
                .collect()
        }

        if let Some(SemanticNodeData::Object(view)) = self.graph().node_data(source).as_deref() {
            return Some((
                public_members(view.positive_members()),
                crate::semantic_query::PartialReasonSet::empty(),
                view.key_domain_is_closed(),
                view.index_signatures
                    .iter()
                    .map(crate::semantic_query::IndexSignature::clone)
                    .collect(),
            ));
        }

        // A construction-program source never fabricates a closed `Object`
        // (the walker's open-safe rule): project the correlated spread
        // formula instead. A single CLOSED alternative yields its exact
        // members (complete, empty set); an open / multi-alternative
        // formula yields POSITIVE evidence only and always taints so the
        // mapped build never treats the partial member set as the source's
        // complete domain. The taint is DERIVED (no underlying read
        // carries classes for it), so it rides the same anonymous
        // `PROPAGATED` class a classless partial would bridge to.
        if matches!(
            self.graph().node_data(source).as_deref(),
            Some(SemanticNodeData::ObjectSpreadProgram(_))
        ) {
            return self
                .spread_program_members_for_published_projection(source, caller_context)
                .map(|(members, partial)| {
                    (
                        public_members(&members),
                        if partial {
                            crate::semantic_query::PartialReasonSet::PROPAGATED
                        } else {
                            crate::semantic_query::PartialReasonSet::empty()
                        },
                        !partial,
                        Vec::new(),
                    )
                });
        }

        // Mapped/keyof source enumeration retains ordinary TypeScript
        // Published(Shallow) intersection semantics. Only the orthogonal Vue
        // heritage policy crosses this boundary: a runtime source carrier must
        // suppress its producer-addressed heritage before head resolution,
        // while all ordinary callers retain the complete source surface.
        let source_context =
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Shallow)
                .with_orthogonal_axes_from(caller_context);
        let read = self.execute_read(SemanticQueryKey::ProjectPath {
            base: source,
            path: verter_type_expr::OwnedSlice::from(Vec::<PathSegment>::new().into_boxed_slice()),
            context: source_context,
        });
        crate::meta_resolve::emit_dispatch_dep_signature_facts(self, &read.dep_signature);
        // `partial_reason_classes` bridges a classless partial to
        // `PROPAGATED` itself, so the fold below is verdict-identical to
        // the old bare-bool hand-off whenever the read named no class.
        let read_partial_classes = read.partial_reason_classes();
        let node = match read.value {
            QueryResult::Value(id) => id,
            QueryResult::Recursive(_) | QueryResult::Error(_) => return None,
        };
        let projected = match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Object(view)) => Some((
                public_members(view.positive_members()),
                read_partial_classes,
                view.key_domain_is_closed(),
                view.index_signatures
                    .iter()
                    .map(crate::semantic_query::IndexSignature::clone)
                    .collect(),
            )),
            // A carrier that resolved to a construction program (the
            // walker's typed open evidence) degrades through the same
            // correlated-query rule as a direct program source.
            Some(SemanticNodeData::ObjectSpreadProgram(_)) => self
                .spread_program_members_for_published_projection(node, caller_context)
                .map(|(members, partial)| {
                    (
                        public_members(&members),
                        if partial {
                            crate::semantic_query::PartialReasonSet::PROPAGATED
                        } else {
                            crate::semantic_query::PartialReasonSet::empty()
                        },
                        !partial,
                        Vec::new(),
                    )
                }),
            _ => None,
        };
        // A surface that projected no member and no index signature may be
        // a type whose properties the shallow surface does not carry: read
        // what the source declares.
        let projected_nothing = projected
            .as_ref()
            .is_none_or(|(members, _, _, signatures)| members.is_empty() && signatures.is_empty());
        if projected_nothing {
            if let Some(declared) =
                self.declared_non_object_projection(source, source_context, keys_only)
            {
                return Some(declared);
            }
        }
        projected
    }

    /// The surface of a source that declares a function or constructor
    /// type, an array or a tuple — kinds whose properties the shallow
    /// projection does not list. A function type has no properties and no
    /// index signatures (`keyof (() => void)` is `never`); an array or tuple
    /// maps the properties of its apparent type, a tuple's positions and
    /// `length` over the `Array` wrapper's members and index signature
    /// (`{ [K in keyof [1, 'a'] as …]: … }`). `None` for any other kind.
    /// `keys_only` reads the wrapper's members as carriers
    /// ([`Self::array_like_apparent_object`]).
    fn declared_non_object_projection(
        &self,
        source: SemanticNodeId,
        source_context: crate::semantic_query::ProjectionReductionContext,
        keys_only: bool,
    ) -> Option<(
        Vec<SurfaceMember>,
        crate::semantic_query::PartialReasonSet,
        bool,
        Vec<crate::semantic_query::IndexSignature>,
    )> {
        let declared = self.resolve_signature_source_carrier(source, source_context);
        let apparent = match self.graph().node_data(declared).as_deref()? {
            SemanticNodeData::Signature { .. } => {
                return Some((
                    Vec::new(),
                    crate::semantic_query::PartialReasonSet::empty(),
                    true,
                    Vec::new(),
                ));
            }
            SemanticNodeData::Tuple { .. } | SemanticNodeData::Array { .. } => {
                self.array_like_apparent_object(declared, keys_only)?
            }
            _ => return None,
        };
        match self.graph().node_data(apparent).as_deref() {
            Some(SemanticNodeData::Object(view)) => Some((
                view.positive_members()
                    .iter()
                    .filter(|member| member.visibility.is_public())
                    .map(crate::semantic_query::SurfaceMember::clone)
                    .collect(),
                crate::semantic_query::PartialReasonSet::empty(),
                true,
                view.index_signatures
                    .iter()
                    .map(crate::semantic_query::IndexSignature::clone)
                    .collect(),
            )),
            _ => None,
        }
    }

    /// The apparent object type of the array or tuple `node`
    /// (`getApparentType`): a tuple's own positions and `length` over the
    /// project's `Array` / `ReadonlyArray` wrapper, an array that wrapper
    /// alone. `None` when the wrapper read does not settle, or an array's
    /// project declares none.
    ///
    /// `keys_only` reads the wrapper under structural transit, its member
    /// values kept carriers, for a caller that reads the members' keys and
    /// modifiers alone: the wrapper's own members may map over its keys
    /// (`Array`'s `[Symbol.unscopables]: { [K in keyof any[]]?: boolean }`),
    /// so evaluating their values to read those keys would re-enter the
    /// wrapper's own instantiation.
    fn array_like_apparent_object(
        &self,
        node: SemanticNodeId,
        keys_only: bool,
    ) -> Option<SemanticNodeId> {
        let (name, args) = self.apparent_wrapper_of(node)?;
        let canonical = self
            .graph()
            .node_scope(node)
            .and_then(|scope| scope.canonical_file())
            .or_else(|| self.wrapper_demand_canonical())?;
        let surface = if keys_only {
            self.global_wrapper_surface_in(
                name,
                &args,
                canonical.as_ref(),
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
        } else {
            self.global_wrapper_surface(name, &args, canonical.as_ref())
        };
        let wrapper = match surface {
            super::apparent_type::GlobalWrapper::Surface(surface) => {
                Some(match self.graph().node_data(surface).as_deref() {
                    Some(SemanticNodeData::MergedDecl { contributors }) => {
                        self.reduce_merged_decl(contributors)
                    }
                    _ => surface,
                })
            }
            super::apparent_type::GlobalWrapper::Absent => None,
            super::apparent_type::GlobalWrapper::Unsettled => return None,
        };
        match self.graph().node_data(node).as_deref()? {
            SemanticNodeData::Tuple { elements, readonly } => {
                Some(self.tuple_apparent_surface(wrapper, elements, *readonly))
            }
            _ => wrapper,
        }
    }

    construction_ordinal_seam! {
        /// Project a construction-program source through the correlated spread
        /// query for published-projection member enumeration. Returns the
        /// positive member evidence plus the completeness flag: `false` only
        /// for a single closed alternative (the exact complete domain),
        /// `true` for open / multi-alternative formulas (positive-only).
        fn spread_program_members_for_published_projection(
            &self,
            program: SemanticNodeId,
            caller_context: crate::semantic_query::ProjectionReductionContext,
        ) -> Option<(Vec<SurfaceMember>, bool)> {
            let formula = match self.project_object_spread_for_consumer(
                program,
                crate::semantic_query::ObjectProjectionSelector::Surface,
                caller_context,
            ) {
                QueryResult::Value(formula) => formula,
                QueryResult::Recursive(_) | QueryResult::Error(_) => return None,
            };
            let single_closed = formula.width() == 1 && formula.all_alternatives_closed();
            let members = self
                .spread_formula_positive_members_for_macro(&formula)
                .ok()?;
            Some((members, !single_closed))
        }
    }

    fn member_names_for_published_projection(
        &self,
        source: SemanticNodeId,
    ) -> Option<(Vec<PropertyKey>, bool)> {
        self.source_members_for_published_projection(
            source,
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Shallow),
        )
        .map(|(members, partial_classes)| {
            (
                members
                    .into_iter()
                    .filter_map(|member| member.key.into_known().ok())
                    .collect(),
                !partial_classes.is_empty(),
            )
        })
    }

    /// TypeScript's instantiation of a mapped type declared over `keyof T`
    /// for a type parameter `T` ([`MapperKey::over_type_variable`]) at the
    /// type `source` stands for — `instantiateMappedType`. Returns `None`
    /// when `source` is an object type (or still open), which the ordinary
    /// mapping answers:
    ///
    /// - a union maps each constituent and unites the results
    ///   (`Partial<A | B>` is `Partial<A> | Partial<B>`), so its keys are no
    ///   longer the constituents' COMMON keys;
    /// - a primitive, a literal, `object`, `null` and `undefined` pass
    ///   through unchanged (`Partial<string>` is `string`), with or without
    ///   an `as` clause; `never` is `never`, and `unknown` maps to `{}`;
    /// - a function or constructor type, having no properties, maps to `{}`;
    /// - without an `as` clause, an array maps its element (`Partial<number[]>`
    ///   is `(number | undefined)[]`) and a tuple each element, the
    ///   modifiers applying to the element flags (`Partial<[1, 2?]>` is
    ///   `[(1 | undefined)?, (2 | undefined)?]`, `Readonly<[1]>` is
    ///   `readonly [1]`).
    ///
    /// [`MapperKey::over_type_variable`]: crate::semantic_query::MapperKey::over_type_variable
    fn instantiate_homomorphic_mapped(
        &self,
        source: SemanticNodeId,
        mapper: &crate::semantic_query::MapperKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<crate::project_semantic_dispatch::walk::QueryBuildOutput> {
        // A declaration carrier settles to what it declares, so an alias
        // of a union, tuple or primitive maps as that type.
        let resolved = self.resolve_signature_source_carrier(source, context);
        let data = self.graph().node_data(resolved)?;
        let fence = self.project_generation_signature();
        let finish = |node: SemanticNodeId, partial: bool| {
            let mut out = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(node),
                fence.clone(),
            ))
            .with_observed_self_roots(self.observed_self_roots_from_nodes([source, resolved]));
            out.fold_partial(partial);
            out
        };
        match data.as_ref() {
            SemanticNodeData::Primitive(PrimitiveKind::Any) => None,
            SemanticNodeData::Primitive(PrimitiveKind::Unknown) => {
                drop(data);
                Some(finish(self.empty_object(), false))
            }
            SemanticNodeData::Primitive(_)
            | SemanticNodeData::Literal(_)
            | SemanticNodeData::TemplateLiteral { .. }
            | SemanticNodeData::TypeOfNominal(_) => {
                drop(data);
                Some(finish(resolved, false))
            }
            // A function or constructor type is an object with no properties
            // and no index signatures: its signatures are not mapped, so the
            // mapping is `{}` (`Partial<() => void>`).
            SemanticNodeData::Signature { .. } => {
                drop(data);
                Some(finish(self.empty_object(), false))
            }
            SemanticNodeData::Union(members) => {
                let members = members.members_arc();
                drop(data);
                let mut mapped: Vec<SemanticNodeId> = Vec::with_capacity(members.len());
                let mut partial = false;
                for &arm in members.iter() {
                    let read = self.execute_read(SemanticQueryKey::MappedType {
                        source: arm,
                        mapper: self.homomorphic_mapper_at(mapper, source, arm, context),
                        context,
                    });
                    partial |= read.result_is_partial();
                    match read.value {
                        QueryResult::Value(node) | QueryResult::Recursive(node) => {
                            mapped.push(node)
                        }
                        QueryResult::Error(_) => return None,
                    }
                }
                let united = self.execute_read(SemanticQueryKey::ReduceUnion {
                    members: Arc::from(mapped.into_boxed_slice()),
                    nullability: verter_session_query::flow::policy::NullabilityPolicy::Strict,
                });
                match united.value {
                    QueryResult::Value(node) => {
                        Some(finish(node, partial || united.result_is_partial()))
                    }
                    _ => None,
                }
            }
            SemanticNodeData::Array { readonly, .. } if mapper.name_remap.is_none() => {
                let readonly = *readonly;
                drop(data);
                let key = self.primitive_node(PrimitiveKind::Number);
                let value =
                    self.homomorphic_template(mapper, source, resolved, key, None, context)?;
                // The mapped array keeps its source's scope, so a read of it
                // follows the declaring project's options.
                Some(finish(
                    self.graph().intern_preserving_scope(
                        resolved,
                        SemanticNodeData::Array {
                            element: value,
                            readonly: modified_readonly(readonly, mapper.readonly),
                        },
                    ),
                    false,
                ))
            }
            SemanticNodeData::Tuple { elements, readonly } if mapper.name_remap.is_none() => {
                let (elements, readonly) = (Arc::clone(elements.as_arc()), *readonly);
                drop(data);
                let mut mapped: Vec<crate::semantic_query::TupleElement> =
                    Vec::with_capacity(elements.len());
                for (position, element) in elements.iter().enumerate() {
                    let value = if element.rest {
                        // A rest element holds its array type: it maps as
                        // that array does.
                        let rest = self
                            .evaluate_deferred_semantic_node_with_context(element.value, context)
                            .into_active_query_build_node(self);
                        if !matches!(
                            self.graph().node_data(rest).as_deref(),
                            Some(SemanticNodeData::Array { .. })
                        ) {
                            return None;
                        }
                        let read = self.execute_read(SemanticQueryKey::MappedType {
                            source: rest,
                            mapper: self.homomorphic_mapper_at(mapper, source, rest, context),
                            context,
                        });
                        match read.value {
                            QueryResult::Value(node) => node,
                            _ => return None,
                        }
                    } else {
                        let key = self.graph().intern_node(SemanticNodeData::Literal(
                            LiteralValue::String(position.to_string()),
                        ));
                        self.homomorphic_template(
                            mapper,
                            source,
                            resolved,
                            key,
                            Some(element.optional),
                            context,
                        )?
                    };
                    let optional = !element.rest
                        && match mapper.optionality {
                            crate::semantic_query::OptionalityMod::Add => true,
                            crate::semantic_query::OptionalityMod::Remove => false,
                            crate::semantic_query::OptionalityMod::Keep => element.optional,
                        };
                    mapped.push(crate::semantic_query::TupleElement {
                        label: element.label.clone(),
                        value,
                        optional,
                        rest: element.rest,
                    });
                }
                Some(finish(
                    self.graph().intern_preserving_scope(
                        resolved,
                        SemanticNodeData::Tuple {
                            elements: crate::semantic_query::PayloadArray::from(
                                mapped.into_boxed_slice(),
                            ),
                            readonly: modified_readonly(readonly, mapper.readonly),
                        },
                    ),
                    false,
                ))
            }
            _ => None,
        }
    }

    /// The mapper that maps `arm` — one constituent of the homomorphic
    /// mapping's `source`, or the array a tuple's rest element holds — as
    /// the mapping maps `source`: its keys are `arm`'s, and the template
    /// and `as` clause read `arm` where they read `source`.
    fn homomorphic_mapper_at(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        source: SemanticNodeId,
        arm: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> crate::semantic_query::MapperKey {
        let key_space = match self
            .execute_read(SemanticQueryKey::KeyOf { base: arm, context })
            .value
        {
            QueryResult::Value(node) => node,
            _ => self
                .graph()
                .intern_node(SemanticNodeData::KeyOf { base: arm }),
        };
        crate::semantic_query::MapperKey {
            key_space,
            value_expr: self.substitute_semantic_type_param(mapper.value_expr, source, arm),
            name_remap: mapper
                .name_remap
                .map(|remap| self.substitute_semantic_type_param(remap, source, arm)),
            ..mapper.clone()
        }
    }

    /// Whether the member of the mapped type's `source` at the binder
    /// argument `key` is optional; `None` when the source's surface or the
    /// key does not read.
    fn mapped_source_member_optional(
        &self,
        source: SemanticNodeId,
        key: SemanticNodeId,
    ) -> Option<bool> {
        self.mapped_source_member(source, key)
            .map(|member| member.optional)
    }

    pub(super) fn mapped_source_member(
        &self,
        source: SemanticNodeId,
        key: SemanticNodeId,
    ) -> Option<SurfaceMember> {
        let key = self.mapped_binder_property_key(key)?;
        let object = self.mapped_source_object(source)?;
        match self.graph().node_data(object).as_deref()? {
            SemanticNodeData::Object(surface) => {
                let member = if surface.positive_members().len()
                    > crate::semantic_query_memo::member_index::MEMBER_ORDINAL_INDEX_LINEAR_SCAN_MAX
                {
                    surface
                        .key_index_from_ordinals(self.graph().member_ordinal_index(object, surface))
                        .project_known_key(&key)
                } else {
                    surface.project_known_key(&key)
                };
                match member {
                    crate::semantic_query::SurfaceKeyProjection::Exact(member) => {
                        Some(member.clone())
                    }
                    crate::semantic_query::SurfaceKeyProjection::AbsentProven => None,
                }
            }
            _ => None,
        }
    }

    /// The property a mapped binder argument addresses: a string or number
    /// literal, or the nominal type of a `unique symbol` key. Other keys
    /// (broad primitives, patterns) address no single member.
    pub(super) fn mapped_binder_property_key(
        &self,
        key: SemanticNodeId,
    ) -> Option<crate::semantic_query::PropertyKey> {
        let data = self.graph().node_data(key)?;
        match data.as_ref() {
            SemanticNodeData::Literal(crate::semantic_query::LiteralValue::String(text)) => {
                Some(crate::semantic_query::PropertyKey::String(
                    verter_type_expr::OwnedStr::from(text.as_str()),
                ))
            }
            SemanticNodeData::Literal(crate::semantic_query::LiteralValue::Number(number)) => Some(
                crate::semantic_query::PropertyKey::String(verter_type_expr::OwnedStr::from(
                    crate::semantic_query::index_key::js_number_to_string(*number).as_str(),
                )),
            ),
            SemanticNodeData::TypeOfNominal(_) => data
                .typeof_nominal_identity()
                .map(|identity| crate::semantic_query::PropertyKey::UniqueSymbol(identity.clone())),
            _ => None,
        }
    }

    /// The object surface a mapped type's `source` reads its authored
    /// member modifiers from, resolved once for any number of keys.
    pub(super) fn mapped_source_object(&self, source: SemanticNodeId) -> Option<SemanticNodeId> {
        // Read authored modifiers before a relation's apparent-type view can
        // replace them with the member's read type.
        if matches!(
            self.graph().node_data(source).as_deref(),
            Some(SemanticNodeData::Object(_))
        ) {
            return Some(source);
        }
        let read = self.execute_read(SemanticQueryKey::ProjectPath {
            base: source,
            path: verter_type_expr::OwnedSlice::from([]),
            context: crate::semantic_query::ProjectionReductionContext::published(
                ProjectionMode::Shallow,
            ),
        });
        if !read.fact_status.is_complete() {
            return None;
        }
        match read.value {
            QueryResult::Value(resolved) => Some(resolved),
            _ => None,
        }
    }

    /// Folds `value` into the member `produced` already holds under the
    /// property spelling of `name`, as the checker unites the productions
    /// of one property (`{ [K in 1 | "1"]: K }` is `{ 1: 1 | "1" }`); the
    /// first production keeps the member's slot. `false` when no production
    /// of that spelling exists yet.
    pub(super) fn join_mapped_production(
        &self,
        produced: &mut MappedProducedMembers,
        name: &PropertyKey,
        value: SemanticNodeId,
    ) -> bool {
        let Some(&ordinal) = produced
            .by_spelling
            .get(&crate::semantic_query::property_spelling(name.clone()))
        else {
            return false;
        };
        let existing = &mut produced.members[ordinal];
        if existing.value != value {
            existing.value =
                self.intern_normalized_union_or_intersection(&[existing.value, value], true);
        }
        true
    }

    /// A mapped member's value as the mapped type holds it under its
    /// optionality modifier: `-?` removes the `undefined` an optional
    /// source member added (`source_optional` reads that member's
    /// optionality), and a kept `?` over a value that is the modifiers
    /// type's own member read (`X[P]`, `kept_optional_read` that member)
    /// drops the `undefined` the read added, since the member's optional
    /// flag carries absence.
    pub(super) fn settle_mapped_member_value(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        value: SemanticNodeId,
        source: SemanticNodeId,
        kept_optional_read: Option<&SurfaceMember>,
        source_optional: impl Fn() -> Option<bool>,
    ) -> SemanticNodeId {
        if mapper.optionality == crate::semantic_query::OptionalityMod::Remove {
            return self.mapped_member_optionality_with(mapper, value, source, source_optional);
        }
        match (kept_optional_read, mapper.modifiers_type) {
            (Some(member), Some(modifiers)) if member.optional => {
                self.read_without_optional_member_undefined(value, member.value, modifiers)
            }
            _ => value,
        }
    }

    /// A mapped member's value read at its key under its optionality
    /// modifier, as the checker types a mapped symbol's property under
    /// `strictNullChecks` (`resolveMappedTypeMembers`): `+?` adds `undefined`
    /// unless the value holds it, Keep inherits the source's optionality,
    /// and `-?` removes the `undefined` an
    /// optional source member `key` added (`removeMissingOrUndefinedType`).
    /// Without `strictNullChecks` the value is unchanged.
    pub(super) fn mapped_member_optionality(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        value: SemanticNodeId,
        source: SemanticNodeId,
        key: SemanticNodeId,
    ) -> SemanticNodeId {
        self.mapped_member_optionality_with(mapper, value, source, || {
            self.mapped_source_member_optional(source, key)
        })
    }

    /// [`Self::mapped_member_optionality`] with the source member's
    /// optionality read by the caller, which may answer many keys from one
    /// index over the source surface.
    pub(super) fn mapped_member_optionality_with(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        value: SemanticNodeId,
        source: SemanticNodeId,
        source_optional: impl Fn() -> Option<bool>,
    ) -> SemanticNodeId {
        let (strict_null_checks, exact_optional) = self.optional_member_compiler_options(source);
        if !strict_null_checks {
            return value;
        }
        let arms = self.union_arms(value);
        let is_undefined = |arm: &SemanticNodeId| self.is_undefined_node(*arm);
        match mapper.optionality {
            crate::semantic_query::OptionalityMod::Add
                if !exact_optional && !arms.iter().any(is_undefined) =>
            {
                let mut arms = arms;
                arms.push(self.primitive_node(PrimitiveKind::Undefined));
                self.intern_normalized_union_or_intersection(&arms, true)
            }
            crate::semantic_query::OptionalityMod::Keep
                if !exact_optional
                    && !arms.iter().any(is_undefined)
                    && source != mapper.key_space
                    && source_optional() == Some(true) =>
            {
                let mut arms = arms;
                arms.push(self.primitive_node(PrimitiveKind::Undefined));
                self.intern_normalized_union_or_intersection(&arms, true)
            }
            crate::semantic_query::OptionalityMod::Remove
                if !exact_optional
                    && arms.iter().any(is_undefined)
                    && source_optional() == Some(true) =>
            {
                self.without_undefined_arms(arms)
            }
            _ => value,
        }
    }

    /// The read `value` of an optional member whose kept `?` carries the
    /// `undefined` the read added (`removeMissingType`): `value` without
    /// its `undefined` arm, unless the member's `declared` type holds one
    /// itself. Without `strictNullChecks`, or under
    /// `exactOptionalPropertyTypes`, a read adds none and `value` is kept.
    /// `scope` is the node whose file's options decide.
    pub(super) fn read_without_optional_member_undefined(
        &self,
        value: SemanticNodeId,
        declared: SemanticNodeId,
        scope: SemanticNodeId,
    ) -> SemanticNodeId {
        let (strict_null_checks, exact_optional) = self.optional_member_compiler_options(scope);
        if !strict_null_checks || exact_optional {
            return value;
        }
        let arms = self.union_arms(value);
        if !arms.iter().any(|arm| self.is_undefined_node(*arm))
            || self
                .union_arms(declared)
                .iter()
                .any(|arm| self.is_undefined_node(*arm))
        {
            return value;
        }
        self.without_undefined_arms(arms)
    }

    /// `(strictNullChecks, exactOptionalPropertyTypes)` of the file `node`
    /// is scoped to; a node with no file scope reads the strict defaults.
    fn optional_member_compiler_options(&self, node: SemanticNodeId) -> (bool, bool) {
        self.graph()
            .node_scope(node)
            .and_then(|scope| scope.canonical_file())
            .map_or((true, false), |canonical| {
                let options = self.ctx.semantic_compiler_options_for(&canonical);
                (
                    options.strict_null_checks,
                    options.exact_optional_property_types,
                )
            })
    }

    pub(super) fn union_arms(&self, node: SemanticNodeId) -> Vec<SemanticNodeId> {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Union(members)) => members.members_arc().to_vec(),
            _ => vec![node],
        }
    }

    fn is_undefined_node(&self, node: SemanticNodeId) -> bool {
        matches!(
            self.graph().node_data(node).as_deref(),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Undefined))
        )
    }

    fn without_undefined_arms(&self, arms: Vec<SemanticNodeId>) -> SemanticNodeId {
        let kept: Vec<SemanticNodeId> = arms
            .into_iter()
            .filter(|arm| !self.is_undefined_node(*arm))
            .collect();
        match kept.as_slice() {
            [] => self.primitive_node(PrimitiveKind::Never),
            [only] => *only,
            _ => self.intern_normalized_union_or_intersection(&kept, true),
        }
    }

    /// The mapping's template at the key `key` over the array or tuple
    /// `container` (TypeScript's `instantiateMappedTypeTemplate`): the
    /// container's element read at `key` for an identity mapping, else the
    /// template with the binder bound to `key` and `source` read as
    /// `container`, then the optional modifier under `strictNullChecks`
    /// — `+?` adds `undefined` unless the type already admits it (for a
    /// tuple element under `exactOptionalPropertyTypes` the element's
    /// optional flag carries it instead), `-?` removes it from an array
    /// element or an optional tuple element. `tuple_element` is the
    /// element's own optionality, `None` for an array's element.
    fn homomorphic_template(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        source: SemanticNodeId,
        container: SemanticNodeId,
        key: SemanticNodeId,
        tuple_element: Option<bool>,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<SemanticNodeId> {
        let template = match mapper.kind {
            crate::semantic_query::MapperKind::Identity => {
                self.graph().intern_node(SemanticNodeData::IndexedAccess {
                    object: container,
                    index: self.normalized_index_key_node(key),
                })
            }
            crate::semantic_query::MapperKind::Computed => {
                let over_container =
                    self.substitute_semantic_type_param(mapper.value_expr, source, container);
                let instantiated =
                    self.substitute_semantic_type_param(over_container, mapper.parameter_node, key);
                // The instantiated template reduces the operators its
                // instantiation closed wherever they sit (`{ v: T[K] }`
                // over `[1, 2]` at `"0"` is `{ v: 1 }`).
                self.evaluate_selected_value_with_context(instantiated, context)
            }
        };
        let value = self
            .evaluate_deferred_semantic_node_with_context(template, context)
            .into_active_query_build_node(self);
        if matches!(
            self.graph().node_data(value).as_deref(),
            Some(SemanticNodeData::Opaque(_))
        ) {
            return None;
        }
        let (strict_null_checks, exact_optional) = self
            .graph()
            .node_scope(container)
            .and_then(|scope| scope.canonical_file())
            .map_or((true, false), |canonical| {
                let options = self.ctx.semantic_compiler_options_for(&canonical);
                (
                    options.strict_null_checks,
                    options.exact_optional_property_types,
                )
            });
        let mut arms: Vec<SemanticNodeId> = Vec::new();
        match self.graph().node_data(value).as_deref() {
            Some(SemanticNodeData::Union(members)) => arms.extend(members.members_arc().iter()),
            _ => arms.push(value),
        }
        if !strict_null_checks {
            // With `strictNullChecks` off `null` and `undefined` are no
            // types of their own: the element erases them.
            return Some(if arms.len() < 2 {
                value
            } else {
                self.intern_normalized_union(
                    &arms,
                    verter_session_query::flow::policy::NullabilityPolicy::Erased,
                )
            });
        }
        let admits_undefined = |arm: &SemanticNodeId| {
            matches!(
                self.graph().node_data(*arm).as_deref(),
                Some(SemanticNodeData::Primitive(
                    PrimitiveKind::Undefined | PrimitiveKind::Void
                ))
            )
        };
        match mapper.optionality {
            crate::semantic_query::OptionalityMod::Add
                if !(exact_optional && tuple_element.is_some())
                    && !arms.iter().any(admits_undefined) =>
            {
                arms.push(self.primitive_node(PrimitiveKind::Undefined));
                Some(self.intern_normalized_union_or_intersection(&arms, true))
            }
            crate::semantic_query::OptionalityMod::Remove if tuple_element.unwrap_or(true) => {
                let kept: Vec<SemanticNodeId> = arms
                    .into_iter()
                    .filter(|arm| {
                        !matches!(
                            self.graph().node_data(*arm).as_deref(),
                            Some(SemanticNodeData::Primitive(PrimitiveKind::Undefined))
                        )
                    })
                    .collect();
                Some(match kept.as_slice() {
                    [] => self.primitive_node(PrimitiveKind::Never),
                    [only] => *only,
                    _ => self.intern_normalized_union_or_intersection(&kept, true),
                })
            }
            _ => Some(value),
        }
    }

    /// Mapped-type rewrite.
    ///
    /// For a mapped type `{ [K in key_space]: value_expr }` with
    /// optional / readonly modifiers (stored on the `MapperKey` and
    /// participating in the cache key):
    ///
    /// 1. Carrier-stops run first: outside a publication demand
    ///    (`may_reduce_operator(context)` is false), or when the
    ///    produced surface still depends on an unbound OUTER generic
    ///    (`mapped_type_is_open_or_unknown` — the route/mode-independent
    ///    L1 Shallow-By-Default rule), return the deferred
    ///    `SemanticNodeData::Mapped { source, mapper }` carrier with one
    ///    `Normalize` edge over the contribution set.
    /// 2. Enumerate the key domain: the source's projected member names
    ///    when the source surfaces an Object (synthetic-name keyspaces
    ///    reroute through the keyspace node's literals), else the
    ///    keyspace node's literal union. Neither enumerable → the
    ///    deferred `Mapped` carrier again.
    /// 3. For each key, apply the `as`-clause `name_remap` FIRST via
    ///    [`Self::mapped_member_name_remap_outcome`] — the key-domain
    ///    decision precedes the value force. `Drop` filters the key;
    ///    duplicate produced names union their per-key values;
    ///    `DeferCarrier` fails the whole mapped type closed back to the
    ///    deferred `Mapped` carrier. A remap-dropped key is DEAD: its
    ///    value operand is never substituted, evaluated, instantiated,
    ///    or passed to the per-K materialiser.
    /// 4. For each surviving key, reserve a member slot. Member
    ///    optionality / readonly derive from the mapper's modifiers
    ///    (`Add` → always on, `Remove` → always off, `Keep` → inherit
    ///    from the source if available, else default off).
    /// 5. Member values dispatch on `mapper.kind`. An `Identity` mapper
    ///    (the canonical `{ [K in keyof T]: T[K] }` behind `Partial` /
    ///    `Required` / `Readonly`) reuses the matching source member's
    ///    value directly; a key without a projectable source member
    ///    dispatches `source[K]` through the shared `IndexedAccess`
    ///    query, publishing the ADDRESSABLE deferred `IndexedAccess`
    ///    carrier when the access cannot close — never the builtin
    ///    mapper's `Opaque(Miss)` `value_expr` shell marker. A
    ///    `Computed` mapper substitutes the binder and evaluates via
    ///    [`Self::materialize_mapped_member_value_for_key`]
    ///    (K-independent value bodies hoist one shared evaluation above
    ///    the loop), falling back to the substituted carrier on `Opaque`
    ///    so the free binder never leaks onto the published surface.
    /// 6. Emit one `Normalize` edge from the mapped result over the full
    ///    contribution set (`[source, key_space, value_expr,
    ///    name_remap?]`) and one `ProjectMember` edge per produced
    ///    member value sourcing `[source, key_space]` with
    ///    `OriginMeta::ProjectedMember` (provenance
    ///    `MemberEdgeProvenance::MappedKeyEnumerated`) carrying the
    ///    produced name (post-remap if `name_remap` is set).
    ///
    /// The `mapper: MapperKey` participates in the `SemanticQueryKey`
    /// hash so different modifier / value-expression combinations
    /// intern distinct entries — enforced by
    /// `mapped_type_optionality_and_readonly_modifiers_in_cache_key`.
    ///
    /// Mapper-value classification is done at lowering time, not at
    /// build time. Every [`MapperKey`](crate::semantic_query::MapperKey)
    /// carries a stable [`MapperKind`](crate::semantic_query::MapperKind)
    /// tag (see
    /// [`crate::semantic_query::MapperKind::classify_value_expr`]);
    /// `build_mapped_type` matches on `mapper.kind` directly rather
    /// than re-classifying the runtime AST shape.
    pub(super) fn build_mapped_type(
        &self,
        source: SemanticNodeId,
        mapper: &crate::semantic_query::MapperKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        // Cancellation before any mapped work. A cancelled request
        // never enumerates a key domain, never substitutes a remap, and
        // never forces a value operand; the typed `Cancelled` output is
        // `ReturnOnly` (cache-suppressed) so no partial per-key work can
        // warm a whole-surface candidate.
        if self.cancellation.is_cancelled() {
            return self.cancelled_build_output();
        }
        // A mapping over a type parameter instantiates the checker's way:
        // unions distribute, primitives pass through, arrays and tuples map
        // element-wise.
        if mapper.over_type_variable {
            if let Some(instantiated) = self.instantiate_homomorphic_mapped(source, mapper, context)
            {
                return instantiated;
            }
        }
        // §22 fast-reject on the mapped SOURCE: over `any` ⇒ `any`; over
        // `never` ⇒ `{}`; over `error` ⇒ `error`; a direct mapping over
        // `unknown` is illegal ⇒ error. Runs before key-space enumeration.
        // An intersection the checker reduces to `never` is `never` here.
        let reduced_source = match self.graph().node_data(source).as_deref() {
            Some(SemanticNodeData::Intersection(arms))
                if self.intersection_arms_reduce_to_never(&arms.members_arc()) =>
            {
                self.primitive_node(PrimitiveKind::Never)
            }
            _ => source,
        };
        // A mapping over `keyof S` (homomorphic) whose `S` is `any` maps the
        // one key type the checker reads off `any`, `string`
        // (`forEachMappedTypePropertyKeyTypeAndIndexSignatureKeyType`): it
        // is `{ [x: string]: … }` (`{ [K in keyof T]: T[K] }` over `any` is
        // `{ [x: string]: any }`), never `any`.
        let homomorphic_over_any = (mapper.over_type_variable || mapper.key_space != source)
            && matches!(
                self.graph().node_data(reduced_source).as_deref(),
                Some(SemanticNodeData::Primitive(PrimitiveKind::Any))
            );
        if !homomorphic_over_any {
            if let Some(absorbed) = self.absorb_mapped(reduced_source) {
                return absorbed;
            }
        }
        let graph = self.graph();
        let fence = self.project_generation_signature();
        // Mapped contribution set: the `source` surface, the `key_space`,
        // the `value_expr` — plus the `as`-clause `name_remap` when
        // present. The remap is a first-class decision input (the
        // open-mapped carrier-stop consults it; the per-key remap
        // evaluation consumes it), so it participates in BOTH the memo
        // entry's observed self-roots (a remap-only edit must reject the
        // warm entry on the read-side validator — the R6/R21 invalidation
        // rail) AND the structural `Normalize` origin edges below. A
        // modifiers type other than `source` decides each produced member's
        // modifiers, so it joins the set the same way.
        let contribution_nodes: Vec<SemanticNodeId> = [source, mapper.key_space, mapper.value_expr]
            .into_iter()
            .chain(mapper.name_remap)
            .chain(mapper.modifiers_type)
            .collect();
        // Self-version rooting: all contribution nodes are
        // already-interned. Root the memo entry on the file content
        // version each file-derived input was lowered from.
        let observed_self_roots =
            self.observed_self_roots_from_nodes(contribution_nodes.iter().copied());

        // demand-driven reducer carrier-stop: outside a
        // publication-mode-Expanded demand the build returns a
        // deferred `Mapped { source, mapper }` carrier without
        // enumerating the source's key space or emitting per-member
        // `ProjectMember` edges. Member materialisation is publication
        // work; structural-transit callers (relation engine, deferred-
        // shell evaluation, generic substitution) inspect the carrier
        // directly. The decision is purely on `context` — no
        // operand-name inspection.
        if !crate::semantic_query::may_reduce_operator(context) {
            let node = graph.intern_node(SemanticNodeData::Mapped {
                source,
                mapper: mapper.clone(),
            });
            // Capture the contribution set on a single `Normalize`
            // edge so origin-graph consumers still see the structural
            // dependency; per-member edges only emit on the
            // publication path below.
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                node,
                OriginEdgeKind::Normalize,
                Arc::from(contribution_nodes.clone().into_boxed_slice()),
                OriginMeta::None,
                fence.clone(),
            );
            return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(node),
                fence,
            ))
            .with_observed_self_roots(observed_self_roots);
        }

        // Route/mode-INDEPENDENT L1 (Shallow-By-Default), MAPPED-TYPE
        // family. Under a publication demand (`Published` /
        // `MacroObjectSurface`, where `may_reduce_operator` is true) a
        // mapped type whose produced surface still depends on an unbound
        // OUTER generic — an open source / key space, or a value body /
        // name remap reaching the outer generic (NOT the bound mapper
        // binder `K`) — must NOT enumerate its keys and materialise the
        // per-key value. That per-key value loop over an open value body
        // is the `ChatMessagesSlots<T>` / `TableSlots<T>` storm across
        // `node_modules`. Instead return the COMPLETE deferred `Mapped`
        // carrier verbatim (a shallow shell preserving source / key space
        // / value / name-remap); consumers re-resolve on demand. A CLOSED
        // mapped type (`Partial`/`Required`/`Readonly`, `{ [K in keyof
        // Closed]: Closed[K] }`, a K-only transform, a finite keyspace)
        // falls through to enumerate path-precisely.
        if crate::project_semantic_dispatch::raise::mapped_type_is_open_or_unknown(
            self, source, mapper,
        ) {
            let node = graph.intern_node(SemanticNodeData::Mapped {
                source,
                mapper: mapper.clone(),
            });
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                node,
                OriginEdgeKind::Normalize,
                Arc::from(contribution_nodes.clone().into_boxed_slice()),
                OriginMeta::None,
                fence.clone(),
            );
            return crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                QueryResult::Value(node),
                fence,
            ))
            .with_observed_self_roots(observed_self_roots);
        }

        // 1. Resolve the key space.
        //
        // TS semantics: `{ [K in keyof T]: V }` walks T's member names.
        // When `source` is an Object, its member names ARE the correct
        // keys — even if `mapper.key_space` was pre-computed as a union
        // of string-literal primitives (the current graph model has no
        // literal-type PrimitiveKind, so we recover names from the
        // source directly). If `source` is not an Object we can read
        // member names from, fall back to the keyspace shape — but
        // opaque keyspaces terminate the mapped dispatch cleanly.
        // Two-signal fold partiality accumulator, CLASS-PRESERVING. Folds
        // the partiality of every nested subquery this mapped-type build
        // surfaces (the source-member ProjectPath, the K-independent
        // value hoist's nested Instantiate) into the published surface so
        // a genuinely-incomplete (budget / recursion / walker-fatal) input
        // taints the mapped result even though it surfaces as a complete
        // `Value` — with the reason CLASSES intact, so a contained
        // positional class (a member-local flow-return marker reached
        // through the source's heritage) is not re-lifted as the
        // anonymous `PROPAGATED` bridge downstream.
        let mut mapped_partial_reasons = crate::semantic_query::PartialReasonSet::empty();
        let source_projection = if homomorphic_over_any {
            Some((
                Vec::new(),
                crate::semantic_query::PartialReasonSet::empty(),
                true,
                vec![crate::semantic_query::IndexSignature {
                    key_type: self.primitive_node(PrimitiveKind::String),
                    value_type: source,
                    readonly: false,
                    key_name: None,
                    spans: verter_type_expr::IndexSignatureSpans::default(),
                    declaration_origin: None,
                }],
            ))
        } else {
            // Only the identity mapper reads a source member's value; any
            // other reads the source's keys and modifiers alone.
            let keys_only = !matches!(mapper.kind, crate::semantic_query::MapperKind::Identity);
            self.source_projection_with_key_domain(source, context, keys_only)
        };
        // A source that RESOLVED (to any surface, including an EMPTY one)
        // is distinct from a source that did NOT project: only the latter
        // defers a homomorphic mapping — see the resolved-empty arm below.
        let source_surface_resolved = source_projection.is_some();
        let (
            source_members,
            source_member_reasons,
            source_domain_is_finite,
            source_index_signatures,
        ): (
            Vec<SurfaceMember>,
            crate::semantic_query::PartialReasonSet,
            bool,
            Vec<crate::semantic_query::IndexSignature>,
        ) = source_projection.unwrap_or_else(|| {
            (
                Vec::new(),
                crate::semantic_query::PartialReasonSet::empty(),
                false,
                Vec::new(),
            )
        });
        mapped_partial_reasons = mapped_partial_reasons.union(source_member_reasons);
        let source_member_keys = |members: &[SurfaceMember]| {
            super::enumerate::KeyDomainKey::from_keys(
                members
                    .iter()
                    .filter_map(|member| member.key.cloned_known())
                    .collect(),
            )
        };
        // A HOMOMORPHIC mapper (`[K in keyof S]` over this same source,
        // `as` remaps included) inherits per-member modifiers from `S`;
        // enumerated key NAMES alone cannot carry them. When the source
        // surface has not projected yet, a keyspace-only enumeration
        // would synthesize every produced member non-optional /
        // non-readonly, so the build defers exactly as an unenumerable
        // keyspace does — the re-dispatch enumerates keys AND the
        // source surface together. A source that RESOLVED to an EMPTY
        // surface is NOT that case: its key domain is CLOSED and empty
        // (`Partial<{}>` is `{}` at the checker), so the build proceeds
        // with zero keys and materialises the empty object — complete
        // and warm-capable, never a deferred carrier every re-dispatch
        // returns unchanged. The resolved-empty classification is DIRECT:
        // the source node's own data must be a plainly empty `Object`
        // (no members, signatures, index signatures, or keyspace). A
        // projection that merely SYNTHESISED an empty surface for an
        // open carrier — an `infer T` mapped source, an unbound generic
        // — is NOT closed-and-empty: the deferred shell must survive for
        // the reverse-inference and re-dispatch machinery, and an
        // index-signature-bearing source keeps its deferral (homomorphic
        // mapping preserves index signatures, which zero keys cannot).
        let homomorphic_over_source = matches!(
            graph.node_data(mapper.key_space).as_deref(),
            Some(SemanticNodeData::KeyOf { base }) if *base == source
        );
        let homomorphic_over_unprojected_source =
            source_members.is_empty() && !source_surface_resolved && homomorphic_over_source;
        let resolved_empty_homomorphic_source = source_members.is_empty()
            && homomorphic_over_source
            && matches!(
                graph.node_data(source).as_deref(),
                Some(SemanticNodeData::Object(view))
                    if view.entries.is_empty()
                        && view.positive_members().is_empty()
                        && view.call_signatures.is_empty()
                        && view.construct_signatures.is_empty()
                        && view.index_signatures.is_empty()
                        && view.keyspace.is_none()
            );
        // A public member whose key is an unfolded COMPUTED expression is
        // a key the source HAS but cannot NAME. `source_member_keys`
        // keeps only the keys it can name, so enumerating over such a
        // surface yields the key domain's nameable SUBSET rather than the
        // key domain — and every consumer downstream then reads a missing
        // key as ABSENT rather than as unknown. On
        // `{ known: string; [E.A]: number }` the mapped surface published
        // `known` alone and `Mapped['alpha']` answered the key-absent
        // sentinel for the very member the computed key produces, cleanly
        // and warm.
        //
        // An unnameable key is therefore `KeyEnumeration::Unresolvable`:
        // neither the source surface nor a keyspace derived from it
        // enumerates the real key set, so the build falls through to the
        // deferred `Mapped` shell below and re-dispatches once the key
        // becomes nameable. This is the same fail-closed disposition
        // `intern_keyspace_keys` already takes for a `UniqueSymbol` key it
        // cannot lower to a literal leaf — preserve the typed surface
        // rather than enumerate a domain that is missing members.
        let source_keys_are_nameable = source_members
            .iter()
            .all(|member| member.key.as_known().is_some());
        // Source members carry modifiers, but cannot prove a finite domain
        // when the homomorphic source also declares an index signature.
        let finite_homomorphic_keys = (homomorphic_over_source
            && source_keys_are_nameable
            && !homomorphic_over_unprojected_source)
            .then(|| {
                // A shallow infer/type-parameter projection may have no
                // members while retaining an unresolved keyspace. Only a
                // directly empty source or successful constraint enumeration
                // proves that a homomorphic mapping has zero keys.
                if source_domain_is_finite
                    && (!source_members.is_empty() || resolved_empty_homomorphic_source)
                {
                    Some(source_member_keys(&source_members))
                } else {
                    self.key_literals_from_keyspace_node(mapper.key_space)
                }
            })
            .flatten();
        // A homomorphic mapping (`[K in keyof S]`, its key space possibly
        // reduced already) over a source with index signatures maps each
        // signature's key type to an index signature beside the source's
        // properties, as the checker's `resolveMappedTypeMembers` maps it
        // (`forEachMappedTypePropertyKeyTypeAndIndexSignatureKeyType`): it
        // reads the source's own signatures, never `keyof S`'s widened
        // `string | number`.
        let homomorphic = homomorphic_over_source || mapper.key_space != source;
        let index_domain: Option<(Vec<super::enumerate::KeyDomainKey>, Vec<MappedIndexKey>)> =
            (homomorphic
                && source_surface_resolved
                && source_keys_are_nameable
                && !source_index_signatures.is_empty())
            .then(|| {
                (
                    source_member_keys(&source_members),
                    source_index_signatures
                        .iter()
                        .map(|signature| MappedIndexKey {
                            key_type: signature.key_type,
                            source: Some(signature.clone()),
                        })
                        .collect(),
                )
            });
        let (index_keys, index_domain_keys) = match index_domain {
            Some((keys, index_keys)) => (index_keys, Some(keys)),
            None => (Vec::new(), None),
        };
        let keys: Vec<super::enumerate::KeyDomainKey> = if let Some(keys) = index_domain_keys {
            keys
        } else if let Some(keys) = finite_homomorphic_keys {
            keys
        } else if !homomorphic_over_source && !source_members.is_empty() && source_keys_are_nameable
        {
            if self.uses_synthetic_mapped_key_names(&source_members) {
                match self.key_literals_from_keyspace_node(mapper.key_space) {
                    Some(keys) => keys,
                    None => source_member_keys(&source_members),
                }
            } else {
                source_member_keys(&source_members)
            }
        } else if resolved_empty_homomorphic_source {
            Vec::new()
        } else if let Some(keys) = (!homomorphic_over_source
            && source_keys_are_nameable
            && !homomorphic_over_unprojected_source)
            .then(|| self.key_literals_from_keyspace_node(mapper.key_space))
            .flatten()
        {
            keys
        } else {
            // Change M: `KeyEnumeration::Unresolvable`. Neither the
            // source surface nor the key space enumerate to concrete names.
            // The canonical form is a deferred
            // `SemanticNodeData::Mapped { source, mapper }` shell — callers
            // can re-dispatch through `MappedType` once one of the inputs
            // becomes enumerable. One `Normalize` edge captures the
            // contribution set (`[source, key_space, value_expr]`); the
            // `mapper.name_remap` field is preserved verbatim via the
            // interned `mapper` key.
            //
            // This replaces the retired `Alias(KeyOf(source))` surrogate.
            // The surrogate reinterpreted the mapped result AS its keyspace
            // (a relation confusion), which no downstream consumer could
            // safely navigate. `SemanticNodeData::Mapped` is the
            // dispatch-native deferred form.
            let node = graph.intern_node(SemanticNodeData::Mapped {
                source,
                mapper: mapper.clone(),
            });
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                node,
                OriginEdgeKind::Normalize,
                Arc::from(contribution_nodes.clone().into_boxed_slice()),
                OriginMeta::None,
                fence.clone(),
            );
            let mut deferred_output =
                crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(node),
                    fence,
                ))
                .with_observed_self_roots(observed_self_roots.clone());
            deferred_output.add_partial_reasons(mapped_partial_reasons);
            return deferred_output;
        };

        // 2. Build member slots.
        //
        // For each key K, the mapped member's VALUE type comes from
        // the value expression. The fast path — reading
        // `source_member.value` directly from the enumerated source
        // object — is ONLY valid when `mapper.kind` is
        // `MapperKind::Identity` (the canonical
        // `{ [K in keyof T]: T[K] }` pattern behind `Partial<T>` /
        // `Required<T>` / `Readonly<T>`). For any other value shape
        // (e.g. `keyof T['variants'][K]`, `ExtendSlotWithPlan<TPlan, K>`,
        // `infer`-bearing conditional bodies), classification yields
        // `MapperKind::Computed` and the value goes through the
        // substitute-and-evaluate path: intern `Literal(name)`,
        // substitute the mapper parameter in `mapper.value_expr`,
        // then evaluate the substituted node. Evaluation yielding
        // `Opaque(_)` publishes the un-evaluated substituted node so
        // the value stays addressable by path re-dispatch.
        //
        // Identity vs Computed is decided once at lowering time and
        // carried on `mapper.kind`; the build path reads the tag
        // directly rather than re-inspecting the value-expression AST
        // at runtime.
        let value_is_identity = matches!(mapper.kind, crate::semantic_query::MapperKind::Identity);
        // Key-space-independent value hoist. When the mapper's binder
        // (`mapper.parameter_node`) is not structurally reachable
        // inside `mapper.value_expr`, the per-K substitution collapses
        // to the identity (`substitute_with_change_tracking` returns
        // `(node, false)` for the whole subtree), so every K's
        // substituted carrier IS `value_expr` itself. Reduce
        // `value_expr` ONCE under the caller's context and reuse the
        // result for every enumerated key. Skipping this hoist is
        // correct but wasteful: each K otherwise re-walks the same
        // `evaluate_deferred_*` chain (Conditional / IndexedAccess /
        // Mapped re-dispatch + any nested cross-package import
        // resolution embedded in the body) even though the underlying
        // dispatch sees identical inputs across K.
        //
        // The hoist is gated on `!value_is_identity` because the
        // identity fast-path reads `source_member.value` directly and
        // never enters the materialiser. The check declines on any
        // structural reference to the binder so the per-K materialiser
        // remains the authority for K-dependent value expressions
        // (`T[K]`-style, `K`-keyed `IndexedAccess`, conditional checks
        // on `K`, etc.). Cross-variant `infer`-name matches are also
        // counted as references (see `subtree_references_node`'s
        // contract), preventing over-aggressive hoisting on
        // `infer`-bearing value expressions.
        //
        // Correctness mirror: when the hoist applies the substitution
        // for the K-independent case IS the identity, so the per-K
        // materialiser would compute exactly the same evaluation we
        // perform here. The `InstantiationRef` redispatch and
        // `Opaque` fallback below mirror
        // `materialize_mapped_member_value_for_key` exactly so both
        // paths produce the same surface member value.
        let value_expr_is_k_independent = !value_is_identity
            && !self.subtree_references_node(mapper.value_expr, mapper.parameter_node);
        // LAZY memo, not an eager hoist. The shared evaluation still runs
        // at most once per mapped type, but it runs on the FIRST
        // SURVIVING key's demand rather than above the loop. A mapped type
        // whose every key is remap-dropped
        // (`{ [K in 'a' | 'b' as never]: Box<number> }`) publishes an EMPTY
        // surface, so its value operand is dead; evaluating above the
        // key-domain decision forced it anyway and re-introduced, once per
        // mapped type, exactly the dead-operand work the per-key ordering
        // removes. The evaluation itself is unchanged — see
        // [`Self::evaluate_k_independent_mapped_value`].
        let mut shared_value: Option<SemanticNodeId> = None;
        let mut produced = MappedProducedMembers::with_capacity(keys.len());
        let mut project_member_edges: Vec<(SemanticNodeId, PropertyKey)> = Vec::new();
        // A key whose `as` remap fails closed (`DeferCarrier`) taints the whole
        // mapped type: it returns the deferred `Mapped` carrier rather than a
        // torn surface (set inside the loop, checked after).
        let mut remap_defers = false;
        // A cancelled request abandons the key loop; the surface built so
        // far is discarded rather than published torn.
        let mut cancelled = false;
        let mut source_member_index = FxHashMap::default();
        for member in &source_members {
            if let Some(key) = member.key.cloned_known() {
                source_member_index.entry(key).or_insert(member);
            }
        }
        let source_accessors =
            crate::semantic_query::AccessorReadonlyByProperty::of(&source_members);
        // A kept modifier is read off the modifiers type
        // (`getModifiersTypeFromMappedType`): `source` itself, or the `X` of
        // a key parameter constrained to `keyof X`. One that does not
        // project leaves the source's (absent) modifiers.
        let inherits_modifiers = mapper.optionality == crate::semantic_query::OptionalityMod::Keep
            || mapper.readonly == crate::semantic_query::ReadonlyMod::Keep;
        let modifiers_members = mapper
            .modifiers_type
            .filter(|_| inherits_modifiers && !keys.is_empty())
            .and_then(|modifiers| self.source_members_for_published_projection(modifiers, context))
            .map(|(members, reasons)| {
                mapped_partial_reasons = mapped_partial_reasons.union(reasons);
                members
            });
        let modifiers_member_index = modifiers_members.as_deref().map(|members| {
            let mut index = FxHashMap::default();
            for member in members {
                if let Some(key) = member.key.cloned_known() {
                    index.entry(key).or_insert(member);
                }
            }
            index
        });
        let modifiers_accessors = modifiers_members
            .as_deref()
            .map(crate::semantic_query::AccessorReadonlyByProperty::of);
        // `X[P]` over the modifiers type `X` is the property read `X[P]` — an
        // overloaded method's whole signature group, an accessor's read
        // type — under the member's kept `?`, which carries the `undefined`
        // the read adds for an optional member.
        let value_reads_modifiers_member = modifiers_member_index.is_some()
            && mapper.modifiers_type.is_some_and(|modifiers| {
                crate::semantic_query::MapperKind::classify_value_expr(
                    graph.store(),
                    mapper.value_expr,
                    modifiers,
                    mapper.parameter_node,
                ) == crate::semantic_query::MapperKind::Identity
            });
        for key in &keys {
            // Cancellation before this key's remap substitution AND before
            // its value force — the two per-key forcing points.
            if self.cancellation.is_cancelled() {
                cancelled = true;
                break;
            }
            // Key-domain decision BEFORE the value operand is forced.
            //
            // The `as <expr>` remap is a KEY-DOMAIN operator: it decides
            // whether an iteration key survives onto the produced surface
            // and under which name(s). It reads `mapper.name_remap`, never
            // `mapper.value_expr`, so it is computable without forcing the
            // value. Deciding it first makes a REMAP-DROPPED key genuinely
            // dead: its value operand is never substituted, never
            // evaluated, never dispatched through `Instantiate`, and never
            // reaches the per-K materialiser. Forcing the value first and
            // discarding it on `Drop` is exactly the dead-operand work this
            // ordering forbids — and `DeferCarrier` (the fail-closed arm)
            // likewise abandons the surface, so every value forced before
            // the deferring key was also dead.
            //
            // `Drop` filters the key; `Keys` emits one member per produced
            // name; `DeferCarrier` fails the whole mapped type closed.
            let produced_names = match self.mapped_member_name_remap_outcome(mapper, key, context) {
                MappedKeyRemapOutcome::Keep(n) => vec![n],
                MappedKeyRemapOutcome::Keys(ns) => ns,
                MappedKeyRemapOutcome::Drop => continue,
                MappedKeyRemapOutcome::DeferCarrier => {
                    remap_defers = true;
                    break;
                }
            };
            let source_member = source_member_index.get(&key.key).copied();
            // An accessor maps as the property it is: `readonly` without a
            // setter, its value read through the key, never the accessor.
            let source_accessor_readonly = source_accessors.readonly(&key.key);
            let modifiers_member = match &modifiers_member_index {
                Some(index) => index.get(&key.key).copied(),
                None => source_member,
            };
            let modifiers_accessor_readonly = match &modifiers_accessors {
                Some(accessors) => accessors.readonly(&key.key),
                None => source_accessor_readonly,
            };
            let optional = match mapper.optionality {
                crate::semantic_query::OptionalityMod::Add => true,
                crate::semantic_query::OptionalityMod::Remove => false,
                crate::semantic_query::OptionalityMod::Keep => {
                    modifiers_member.map(|m| m.optional).unwrap_or(false)
                }
            };
            let readonly = match mapper.readonly {
                crate::semantic_query::ReadonlyMod::Add => true,
                crate::semantic_query::ReadonlyMod::Remove => false,
                crate::semantic_query::ReadonlyMod::Keep => modifiers_accessor_readonly
                    .or(modifiers_member.map(|m| m.readonly))
                    .unwrap_or(false),
            };
            // Value selection branches:
            //
            // - `source_members` matches this key AND `mapper.kind` is
            //   `Identity` → use the member value directly
            //   (Partial/Required/Readonly-style mapped types).
            // - `mapper.kind` is `Identity` but the source surface did
            //   NOT project a matching member (non-Object source whose
            //   key space still enumerated, synthetic-name keyspace
            //   reroute) → the per-key value is STILL `source[K]` by
            //   definition: dispatch the shared `IndexedAccess` query,
            //   never a substitution into `mapper.value_expr` — the
            //   builtin Identity mapper carries the lazy `Opaque(Miss)`
            //   placeholder there, and substituting into it forges
            //   `Opaque(Miss)` as an EXISTING member's published value.
            //   An access the query cannot close publishes the
            //   ADDRESSABLE deferred `IndexedAccess` carrier instead.
            // - `value_expr` does NOT reference `mapper.parameter_node`
            //   → reuse `shared_value` (the once-per-mapped-type
            //   evaluation hoisted above the loop). Both correctness
            //   and the substituted-carrier fallback collapse to the
            //   identical surface member value the per-K materialiser
            //   would produce.
            // - Otherwise (`value_expr` is not `T[K]` and IS K-dependent,
            //   or a Computed mapper's source has no matching member) →
            //   defer to the shared per-key materialiser
            //   [`Self::materialize_mapped_member_value_for_key`].
            //   That helper substitutes the binder, evaluates under the
            //   caller's `context` (publication callers reify; transit
            //   callers carrier-stop), and falls back to the substituted
            //   carrier on `Opaque` so the free mapper binder never leaks
            //   onto the published surface. The Shallow walker's
            //   `synthesise_mapped_surface` calls the same helper at the
            //   Published(Shallow) macro publication boundary so both
            //   paths converge on identical per-key semantics.
            if self.cancellation.is_cancelled() {
                cancelled = true;
                break;
            }
            let value_member = source_member.filter(|_| source_accessor_readonly.is_none());
            let value = if let (Some(source_member), true) = (value_member, value_is_identity) {
                source_member.value
            } else if value_is_identity {
                let read = self.execute_read(SemanticQueryKey::IndexedAccess {
                    base: source,
                    index: IndexKey::from_known(key.key.clone()),
                    mode: ProjectionMode::Navigate,
                });
                if read.result_is_partial() {
                    mapped_partial_reasons =
                        mapped_partial_reasons.union(read.partial_reason_classes());
                }
                match read.value {
                    QueryResult::Value(id)
                        if !matches!(
                            graph.node_data(id).as_deref(),
                            Some(SemanticNodeData::Opaque(_))
                        ) =>
                    {
                        id
                    }
                    _ => graph.intern_node(SemanticNodeData::IndexedAccess {
                        object: source,
                        index: IndexKey::from_known(key.key.clone()),
                    }),
                }
            } else if value_expr_is_k_independent {
                // The first SURVIVING key materialises the shared value;
                // every later key reuses it. Zero surviving keys ⇒ it is
                // never evaluated at all.
                if shared_value.is_none() {
                    let (value, reasons) =
                        self.evaluate_k_independent_mapped_value(mapper, context);
                    mapped_partial_reasons = mapped_partial_reasons.union(reasons);
                    shared_value = Some(value);
                }
                shared_value.expect("initialised immediately above")
            } else {
                let Some(binder) = self.key_domain_binder(key) else {
                    remap_defers = true;
                    break;
                };
                self.materialize_mapped_member_value_for_key(mapper, binder, context)
            };
            // A surface's optional flag carries absence; adding `undefined`
            // belongs to a member read. Removing optionality must settle its
            // value before the source modifier is lost.
            let value = self.settle_mapped_member_value(
                mapper,
                value,
                source,
                modifiers_member.filter(|_| value_reads_modifiers_member && optional),
                || {
                    self.key_domain_binder(key)
                        .and_then(|key_node| self.mapped_source_member_optional(source, key_node))
                },
            );
            // `produced_names` was decided above, before this key's value
            // operand was forced — see the key-domain ordering note at the
            // top of the loop.
            for produced_name in produced_names {
                // Duplicate produced names UNION their per-K values: the
                // numeric key `1` and the string key `"1"` address the
                // SAME property, each contributing its own kind (pinned
                // tsgo, probe12: `{ [K in 1 | "1"]: K }` = `{ 1: 1 | "1" }`
                // — both first-wins and last-wins were falsified). The
                // first production keeps the member slot (position,
                // modifiers, and declaration site); later same-name
                // productions fold their value into a Union arm.
                if self.join_mapped_production(&mut produced, &produced_name, value) {
                    project_member_edges.push((value, produced_name.clone()));
                    continue;
                }
                // Rationale on [`mapped_produced_key_inherits_declaration_site`]
                // — the one shared predicate both rails judge inheritance with.
                // A member taking its modifiers from the modifiers type links
                // to that member's declaration (`shouldLinkPropDeclarations`).
                let identity_source = source_member.or(modifiers_member).filter(|_| {
                    mapped_produced_key_inherits_declaration_site(&produced_name, &key.key)
                });
                // SAFETY: mapped-type member synthesis (e.g.,
                // `Partial<T>` / `Required<T>` / `{ [K in S]: V }`).
                // Members reach the surface via the mapped construction,
                // NOT via own-body declaration in any consuming macro's
                // T body. The construction layer is structurally
                // heritage-equivalent — `false` is the truth.
                produced.push(SurfaceMember {
                    key: crate::semantic_query::AuthoredPropertyKey::from_known(
                        produced_name.clone(),
                    ),
                    value,
                    optional,
                    readonly,
                    method_kind: None,
                    has_implementation_body: false,
                    // Mapped-type produced member. The key domain is already
                    // public-only (non-public class members are filtered out of
                    // the keyspace at `source_members_for_published_projection` /
                    // `key_names_step`), so every produced member is public. For
                    // the homomorphic case (`{ [K in keyof T]: T[K] }` / Partial /
                    // Required / Readonly) thread the matched source member's
                    // (public) visibility verbatim so the invariant is preserved
                    // even if the keyspace gate is ever bypassed; otherwise the
                    // synthesized member is `Public`.
                    visibility: source_member
                        .map_or(verter_type_expr::MemberVisibility::Public, |m| m.visibility),
                    // Mapped-type synthesis is never a literal origin.
                    excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                    declared_in_macro_type_arg: crate::semantic_query::MacroOwnBodyStamp::NEUTRAL,
                    // Mapped-type produced members are synthesized by the mapped
                    // construction, never an interface/class heritage overlay —
                    // `Authored` (they do not participate in own-body shadowing).
                    merge_role: crate::semantic_query::MergeRoleStamp::NEUTRAL,
                    spans: identity_source.map(|m| m.spans).unwrap_or_default(),
                    declaration_origin: identity_source.and_then(|m| m.declaration_origin.clone()),
                });
                project_member_edges.push((value, produced_name.clone()));
            }
        }

        // Each key type maps to an index signature keyed by the type its
        // remap produces (the key type itself without one), its value the
        // mapping's value at that key type. Signatures keyed alike unite
        // their values (`appendIndexInfo`). A property name the remap
        // produces from a key type is a property of that value.
        let mut produced_index: Vec<crate::semantic_query::IndexSignature> = Vec::new();
        for index_key in &index_keys {
            if remap_defers || cancelled {
                break;
            }
            if self.cancellation.is_cancelled() {
                cancelled = true;
                break;
            }
            let MappedIndexRemap {
                key_types: produced_key_types,
                names: produced_names,
            } = match mapper.name_remap {
                None => MappedIndexRemap {
                    key_types: vec![index_key.key_type],
                    names: Vec::new(),
                },
                Some(remap) => {
                    match self.mapped_index_name_remap(mapper, remap, index_key.key_type, context) {
                        Some(produced) => produced,
                        None => {
                            remap_defers = true;
                            break;
                        }
                    }
                }
            };
            if produced_key_types.is_empty() && produced_names.is_empty() {
                continue;
            }
            let value = match (&index_key.source, value_is_identity) {
                (Some(signature), true) => signature.value_type,
                (None, true) => graph.intern_node(SemanticNodeData::IndexedAccess {
                    object: source,
                    index: IndexKey::Computed(index_key.key_type),
                }),
                (_, false) if value_expr_is_k_independent => {
                    if shared_value.is_none() {
                        let (value, reasons) =
                            self.evaluate_k_independent_mapped_value(mapper, context);
                        mapped_partial_reasons = mapped_partial_reasons.union(reasons);
                        shared_value = Some(value);
                    }
                    shared_value.expect("initialised immediately above")
                }
                (_, false) => self.materialize_mapped_member_value_for_key(
                    mapper,
                    index_key.key_type,
                    context,
                ),
            };
            // A property named from a key type has no source property to
            // inherit modifiers from: only the mapping's own `+?` and
            // `+readonly` apply. A name produced again unites its values.
            for produced_name in produced_names {
                if self.join_mapped_production(&mut produced, &produced_name, value) {
                    project_member_edges.push((value, produced_name));
                    continue;
                }
                produced.push(SurfaceMember {
                    key: crate::semantic_query::AuthoredPropertyKey::from_known(
                        produced_name.clone(),
                    ),
                    value,
                    optional: mapper.optionality == crate::semantic_query::OptionalityMod::Add,
                    readonly: mapper.readonly == crate::semantic_query::ReadonlyMod::Add,
                    method_kind: None,
                    has_implementation_body: false,
                    visibility: verter_type_expr::MemberVisibility::Public,
                    excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
                    declared_in_macro_type_arg: crate::semantic_query::MacroOwnBodyStamp::NEUTRAL,
                    merge_role: crate::semantic_query::MergeRoleStamp::NEUTRAL,
                    spans: Default::default(),
                    declaration_origin: None,
                });
                project_member_edges.push((value, produced_name));
            }
            // `+?` adds `undefined` to an index signature's value; `-?`
            // leaves it, as an index signature is never optional.
            let value = if mapper.optionality == crate::semantic_query::OptionalityMod::Add {
                let undefined = self.primitive_node(PrimitiveKind::Undefined);
                self.intern_normalized_union_or_intersection(&[value, undefined], true)
            } else {
                value
            };
            for key_type in produced_key_types {
                // A kept modifier is the one of the source signature the
                // checker applies to the PRODUCED key type, never the one
                // the key type was read from: `[k: number]` remapped to
                // `string` keeps no `readonly` of the number signature.
                let readonly = match mapper.readonly {
                    crate::semantic_query::ReadonlyMod::Add => true,
                    crate::semantic_query::ReadonlyMod::Remove => false,
                    crate::semantic_query::ReadonlyMod::Keep => {
                        self.applicable_source_index_readonly(&source_index_signatures, key_type)
                    }
                };
                if let Some(existing) = produced_index
                    .iter_mut()
                    .find(|signature| signature.key_type == key_type)
                {
                    if existing.value_type != value {
                        existing.value_type = self.intern_normalized_union_or_intersection(
                            &[existing.value_type, value],
                            true,
                        );
                    }
                    existing.readonly |= readonly;
                    continue;
                }
                produced_index.push(crate::semantic_query::IndexSignature {
                    key_type,
                    value_type: value,
                    readonly,
                    key_name: None,
                    spans: index_key
                        .source
                        .as_ref()
                        .map(|signature| signature.spans)
                        .unwrap_or_default(),
                    declaration_origin: index_key
                        .source
                        .as_ref()
                        .and_then(|signature| signature.declaration_origin.clone()),
                });
            }
        }

        // Cancelled mid-loop: return the typed `Cancelled` output rather
        // than publishing the keys that happened to complete first.
        if cancelled || self.cancellation.is_cancelled() {
            return self.cancelled_build_output();
        }

        // Fail closed: a key whose remap could not resolve to a finite key set
        // returns the deferred `Mapped` carrier (callers re-dispatch once the
        // remap becomes decidable) — never a torn partial surface.
        if remap_defers {
            let node = graph.intern_node(SemanticNodeData::Mapped {
                source,
                mapper: mapper.clone(),
            });
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                node,
                OriginEdgeKind::Normalize,
                Arc::from(contribution_nodes.clone().into_boxed_slice()),
                OriginMeta::None,
                fence.clone(),
            );
            let mut deferred_output =
                crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                    QueryResult::Value(node),
                    fence,
                ))
                .with_observed_self_roots(observed_self_roots);
            deferred_output.add_partial_reasons(mapped_partial_reasons);
            return deferred_output;
        }

        let has_index_signature = !produced_index.is_empty();
        let view = SurfaceView::from_entries(
            produced_index
                .into_iter()
                .map(crate::semantic_query::SurfaceEntry::IndexSignature)
                .chain(
                    produced
                        .into_members()
                        .into_iter()
                        .map(crate::semantic_query::SurfaceEntry::Member),
                )
                .collect(),
            Some(mapper.key_space),
            has_index_signature,
        );
        let node = graph.intern_node(SemanticNodeData::Object(view));

        // 3. Emit origin edges.
        //    - Normalize: result ← [source, key_space, value_expr,
        //      name_remap?] (the full contribution set).
        //    - ProjectMember per produced member.
        crate::semantic_query_memo::record_origin_edge!(
            graph,
            node,
            OriginEdgeKind::Normalize,
            Arc::from(contribution_nodes.clone().into_boxed_slice()),
            OriginMeta::None,
            fence.clone(),
        );
        for (value_id, key) in project_member_edges {
            crate::semantic_query_memo::record_origin_edge!(
                graph,
                value_id,
                OriginEdgeKind::ProjectMember,
                Arc::from(vec![source, mapper.key_space].into_boxed_slice()),
                OriginMeta::ProjectedMember {
                    key,
                    provenance: verter_audit::MemberEdgeProvenance::MappedKeyEnumerated,
                },
                fence.clone(),
            );
        }

        let mut mapped_output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node),
            fence,
        ))
        .with_observed_self_roots(observed_self_roots);
        mapped_output.add_partial_reasons(mapped_partial_reasons);
        // Every key in the settled domain was processed; unavailable member
        // values remain typed gaps at those positions in the produced shape.
        mapped_output.approximation = Some(if source_member_reasons.is_empty() {
            super::projection_fact::ProjectionInterpretation::Positional
        } else {
            super::projection_fact::ProjectionInterpretation::PresenceOnly
        });
        mapped_output
    }

    /// Per-key Mapped member value materialiser — the SHARED
    /// substrate used by both [`Self::build_mapped_type`]
    /// (Published(Expanded) publication path) and the Shallow walker's
    /// `synthesise_mapped_surface` (Published(Shallow) surface
    /// synthesis at the macro publication boundary).
    ///
    /// Substitutes the mapper binder (`mapper.parameter_node`) with the
    /// enumerated key's ORIGINAL literal (kind-preserving: a numeric
    /// keyspace member substitutes `Literal::Number`, never its
    /// stringified member name — pinned tsgo, probe12:
    /// `{ [K in 1]: K }` = `{ 1: 1 }`) inside `mapper.value_expr`, then
    /// materialises the substituted node only enough to close the
    /// selected key under the caller's `context`:
    ///
    /// 1. The shared selected-value evaluator walks
    ///    Alias / KeyOf / IndexedAccess / Mapped / Conditional / TypeOf
    ///    / TemplateLiteral / DeclPlaceholder hops. Under
    ///    [`crate::semantic_query::ReductionDemand::StructuralTransit`]
    ///    every `KeyOf` / `MappedType` re-dispatch carrier-stops via
    ///    [`crate::semantic_query::may_reduce_operator`]; `Conditional`
    ///    reduction is gated separately by the relation engine and
    ///    still fires when the post-substitution check is concrete.
    /// 2. A remaining `InstantiationRef` binds through the shared
    ///    `Instantiate` query, and selected-value evaluation continues
    ///    through its returned helper aliases. Under the caller's transit demand
    ///    the body lowering inherits
    ///    `may_reduce_operator(context) == false`, so nested `KeyOf`/
    ///    `Mapped` operators stay carrier-shaped; only `Conditional`
    ///    reduces. This is what turns `ExtendSlotWithPlan<TPlan,
    ///    "badge">` into the `Function` surface the slot-binding
    ///    extractor reads.
    /// 3. When materialisation returns `Opaque`, fall back to the
    ///    SUBSTITUTED carrier (the InstantiationRef with the binder
    ///    replaced) — NEVER the original `mapper.value_expr`, which
    ///    still contains the free mapper binder. The substituted
    ///    carrier remains addressable by path re-dispatch and never
    ///    leaks the free binder onto the consumer surface.
    pub(super) fn materialize_mapped_member_value_for_key(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key_arg: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        self.graph().record_mapped_per_k_materialization();
        // Instrumentation — classify this per-K call as
        // unique or repeated based on the identity tuple a typed
        // mapped-member materialization cache would key on. The
        // classifier records the tuple in the per-request observed
        // set and bumps the matching unique/repeated counter pair.
        crate::observe_request!(C::Observe => on self.observation.request.as_deref() => |ctx| {
            ctx.classify_mapped_member_materialization(
                crate::request_context::MappedMemberIdentity {
                    parameter_node: mapper.parameter_node.0,
                    value_expr: mapper.value_expr.0,
                    key_node: key_arg.0,
                    context_bits: encode_projection_reduction_context_bits(context),
                    variant: 0,
                },
            );
        });
        let substituted =
            self.substitute_semantic_type_param(mapper.value_expr, mapper.parameter_node, key_arg);
        let resolved = self
            .evaluate_mapped_member_value_outcome(substituted, context)
            .into_active_query_build_node(self);
        if matches!(
            self.graph().node_data(resolved).as_deref(),
            Some(SemanticNodeData::Opaque(_))
        ) {
            substituted
        } else {
            resolved
        }
    }

    /// Substitute one selected key, then evaluate its value through the
    /// shared continuation runtime. Instantiation and conditional reduction
    /// retain the full publication context and typed completion outcome.
    /// Numeric, enum-member and nominal keys retain their original identity
    /// during substitution. The active build adopts the typed evaluation
    /// rails before receiving a node.
    pub(super) fn materialize_selected_key_mapped_value_with_node(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key_arg: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        self.materialize_selected_key_mapped_value_outcome(mapper, key_arg, context)
            .into_active_query_build_node(self)
    }

    /// Index expressions in this template that read this exact source at the
    /// mapper binder. Their selected member evidence can be reused after the
    /// batch has validated one source view. Other expressions retain the
    /// ordinary evaluator; no source or binder is matched by spelling.
    pub(super) fn mapped_index_source_reads(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        source: SemanticNodeId,
        resolved_source: SemanticNodeId,
    ) -> Result<Vec<SemanticNodeId>, crate::semantic_query::PartialReasonSet> {
        let mut reads = Vec::new();
        let mut seen = crate::semantic_query::small_node_set::SmallNodeSet::default();
        let mut pending = vec![mapper.value_expr];
        while let Some(node) = pending.pop() {
            if !seen.insert(node) {
                continue;
            }
            self.charge_connected_work()?;
            let Some(data) = self.graph().node_data(node) else {
                return Err(crate::semantic_query::PartialReasonSet::MISSING_SEMANTIC_NODE_DATA);
            };
            if matches!(data.as_ref(), SemanticNodeData::IndexedAccess {
                object, index: crate::semantic_query::IndexKey::Computed(index),
            } if (*object == source || *object == resolved_source) && *index == mapper.parameter_node)
            {
                reads.push(node);
                continue;
            }
            let _ = data.for_each_child(|child| pending.push(child));
        }
        Ok(reads)
    }

    /// A selected member retains exact completion and availability through
    /// helper instantiation, without forcing the instantiated object's members.
    pub(super) fn materialize_selected_key_mapped_value_outcome(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key_arg: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> super::evaluate::EvaluateDeferredOutcome {
        let substituted = self.substitute_selected_mapped_value(mapper, key_arg, context);
        self.evaluate_mapped_member_value_outcome(substituted, context)
    }

    /// An index batch consumes the value composition, including helper bodies.
    pub(super) fn materialize_mapped_index_value_outcome(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key_arg: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> super::evaluate::EvaluateDeferredOutcome {
        let substituted = self.substitute_selected_mapped_value(mapper, key_arg, context);
        self.evaluate_mapped_index_value_outcome(substituted, context)
    }

    fn substitute_selected_mapped_value(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key_arg: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        self.graph().record_mapped_per_k_materialization();
        // Instrumentation — selected-key variant.
        crate::observe_request!(C::Observe => on self.observation.request.as_deref() => |ctx| {
            ctx.classify_mapped_member_materialization(
                crate::request_context::MappedMemberIdentity {
                    parameter_node: mapper.parameter_node.0,
                    value_expr: mapper.value_expr.0,
                    key_node: key_arg.0,
                    context_bits: encode_projection_reduction_context_bits(context),
                    variant: 1,
                },
            );
        });
        self.substitute_semantic_type_param(mapper.value_expr, mapper.parameter_node, key_arg)
    }

    /// A binder-independent selected value uses the same typed evaluator,
    /// with no substitution and no second forcing route.
    pub(super) fn materialize_selected_key_mapped_value_k_independent(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        self.evaluate_mapped_member_value_outcome(mapper.value_expr, context)
            .into_active_query_build_node(self)
    }

    /// Source-surface enumeration for the Shallow walker's
    /// `synthesise_mapped_surface` ONLY.
    ///
    /// Transit-shallow publication (leak-fix-3b) — closes the
    /// architectural gap that prevented the macro-publication boundary
    /// from migrating from `Published(Expanded)` to
    /// `StructuralTransit(Navigate)`.
    ///
    /// **Why this helper, not an extension of `key_names_step`**: the
    /// global key-name enumerators
    /// (`key_names_from_base_node`, `key_names_from_keyspace_node`,
    /// `key_names_step`) are deliberately scoped to
    /// `build_mapped_type`'s Identity fast path (`Readonly<T>` /
    /// `Partial<T>` / `Required<T>`) where the source surface is
    /// already an `Object` lowered through the Expanded path.
    /// Teaching them to unwrap `DeclRef` / `InstantiationRef`
    /// interferes with that Identity-mapper case — observable as a
    /// `mapped_readonly.correctness.snap.json` regression — so the
    /// `Navigate`-lowered carrier-unwrap path is factored into this
    /// separate helper instead.
    ///
    /// This helper is the local fallback `synthesise_mapped_surface`
    /// calls when `key_names_from_base_node(source)` returns `None`
    /// because the source is a `DeclRef` / `InstantiationRef` carrier
    /// (the canonical form imported interfaces take under
    /// `structural_transit_with_mode(Navigate)` lowering). It dispatches
    /// `ProjectPath { source, [], Published(Shallow) }` so the walker
    /// unwraps the carrier through the existing `Instantiate(Published(
    /// Shallow))` path and returns the source's
    /// [`SurfaceMember`]s directly.
    ///
    /// Returning the full `SurfaceMember` list (not just names) lets the
    /// Shallow walker's `synthesise_mapped_surface`:
    ///   - reuse `source_member.value` directly for the Identity-mapper
    ///     case (preserving `Readonly<T>` / `Partial<T>` semantics even
    ///     when the source is a DeclRef);
    ///   - inherit `source_member.optional` / `source_member.readonly`
    ///     bits for the `OptionalityMod::Keep` / `ReadonlyMod::Keep`
    ///     cases;
    ///   - fall back to the per-key
    ///     [`Self::materialize_mapped_member_value_for_key`] substrate
    ///     for the `MapperKind::Computed` case.
    ///
    /// **Diagnostic propagation**: the inner dispatch's
    /// `walker_diagnostics` / `dep_signature` / `cache_suppress` flow
    /// into the active fact tracer via the dispatch's own
    /// `execute` cache pipeline; no diagnostics are silently dropped.
    ///
    /// **Recursion safety**: the helper dispatches one
    /// `SemanticQueryKey::ProjectPath` and reads its terminal node. The
    /// dispatch's same-path recursion sentinel guards against
    /// `Mapped`-shaped sources whose synthesise call re-enters this
    /// helper (the recursion is caught by the dispatch layer's
    /// reentrance check and returns `Recursive`, which surfaces as
    /// `None` here).
    ///
    /// **`context` parameter**: carries the caller's orthogonal Vue heritage
    /// policy into the source projection. The internal dispatch remains
    /// `Published(Shallow)` so mapped key enumeration keeps TypeScript
    /// intersection semantics; only producer-addressed runtime heritage
    /// suppression is inherited.
    pub(super) fn mapped_surface_source_members_for_projection(
        &self,
        source: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<(Vec<SurfaceMember>, crate::semantic_query::PartialReasonSet)> {
        // Returns the source surface PLUS the A2 partiality CLASSES of the
        // underlying ProjectPath read so the Shallow walker's
        // `synthesise_mapped_surface` caller can taint its surface when
        // the source projection was genuinely incomplete — with the class
        // preserved, so a contained positional class (a member-local
        // flow-return marker) is not re-lifted into the anonymous
        // `PROPAGATED` bridge no consumer lane contains.
        self.source_members_for_published_projection(source, context)
    }

    /// Per-key Mapped key-remap OUTCOME — shared by
    /// [`Self::build_mapped_type`] and the Shallow walker's
    /// `synthesise_mapped_surface`.
    ///
    /// Applies the mapper's `name_remap` (the `as <expr>` clause) by
    /// substituting the binder with the key literal and evaluating the remap
    /// under the caller's `context`, then classifies the result per the TS
    /// key-remap contract:
    ///
    /// - no remap clause ⇒ [`MappedKeyRemapOutcome::Keep`] (the iteration key);
    /// - `never` ⇒ [`MappedKeyRemapOutcome::Drop`] (the key is filtered out);
    /// - a finite string OR numeric `Literal` ⇒ [`MappedKeyRemapOutcome::Keys`]
    ///   with that one key (a numeric literal publishes under its canonical
    ///   `js_number_to_string` name — pinned tsgo, probe16: `{ [K in 1 as K]:
    ///   K }` = `{ 1: 1 }`, `{ [K in 1e21 as K]: K }` = `{ "1e+21": 1e21 }`);
    ///   a finite union of such literals ⇒ those keys;
    /// - an unresolved / non-finite / non-key-capable remap ⇒
    ///   [`MappedKeyRemapOutcome::DeferCarrier`] — the mapped type FAILS CLOSED
    ///   to its deferred carrier (it NEVER falls back to the original key,
    ///   which would publish a wrong surface).
    ///
    /// The template-literal evaluator folds `` `prefix-${K}` `` shapes through
    /// the shared `TemplateLiteralReduce` producer before this classification.
    pub(super) fn mapped_member_name_remap_outcome(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        key: &super::enumerate::KeyDomainKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> MappedKeyRemapOutcome {
        let Some(remap_node) = mapper.name_remap else {
            return MappedKeyRemapOutcome::Keep(key.key.clone());
        };
        #[cfg(any(test, feature = "test-support"))]
        MAPPED_NAME_REMAP_EVALUATIONS.set(MAPPED_NAME_REMAP_EVALUATIONS.get() + 1);
        // Kind-preserving substitution: the `as` clause sees the key's
        // ORIGINAL literal (probe12: `{ [K in 1 as K extends number ?
        // "n" : "s"]: K }` = `{ n: 1 }` — a stringified K would select
        // the wrong branch).
        let Some(key_literal) = self.key_domain_binder(key) else {
            return MappedKeyRemapOutcome::DeferCarrier;
        };
        let substituted_remap =
            self.substitute_semantic_type_param(remap_node, mapper.parameter_node, key_literal);
        // A remap whose conditional the relation engine cannot decide
        // (`T[K] extends Function` over an operand it has no judgement for)
        // leaves this key's name unknown: the key domain is unknown, so the
        // mapped type stays its deferred carrier, as it does over an open
        // domain, instead of a gap. The undecided reading is declined, but
        // its roots stay, and the carrier it led to is never warm-admitted.
        // Any other partial (a budget, a missing dependency alone, a
        // degraded read) joins the build as it would unobserved.
        let read = self.observe_read(|| self.evaluate_remap_outcome(substituted_remap, context));
        let undecided = crate::semantic_query::PartialReasonSet::UNDECIDED_CONDITIONAL;
        let reasons = read.result_completeness().reasons();
        if matches!(read.value(), MappedKeyRemapOutcome::DeferCarrier)
            && reasons.contains(undecided)
            && undecided
                .union(crate::semantic_query::PartialReasonSet::MISSING_DEPENDENCY)
                .contains(reasons)
        {
            read.preserve_reuse_evidence(self);
            self.fold_into_top_build_local_taint(false, true);
            return read
                .discard()
                .unwrap_or(MappedKeyRemapOutcome::DeferCarrier);
        }
        read.adopt(self)
            .unwrap_or(MappedKeyRemapOutcome::DeferCarrier)
    }

    /// The `as`-clause outcome of one substituted remap: its evaluation,
    /// a helper application bound and re-evaluated, then classified.
    fn evaluate_remap_outcome(
        &self,
        substituted_remap: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> MappedKeyRemapOutcome {
        let evaluated_remap = self
            .evaluate_deferred_semantic_node_with_context(substituted_remap, context)
            .into_active_query_build_node(self);
        // A userland helper remap (`as Rename<K>`) lowers to an
        // `InstantiationRef` carrier, and the deferred-shell evaluator
        // deliberately STOPS at that carrier without instantiating. Left
        // there the remap classifies as `DeferCarrier` and the whole
        // mapped type fails closed — a helper-authored remap would never
        // decide, while the SAME remap written inline as a conditional
        // would. Bind the substituted key argument through the shared
        // `Instantiate` query and re-evaluate the body, exactly as
        // [`Self::materialize_mapped_member_value_for_key`] does for the
        // value operand, so builtin, inline and userland-helper remaps
        // route through one machinery and decide identically.
        //
        // Fail-closed is preserved: an `Instantiate` that does not close
        // leaves the carrier in place and `classify_remap_outcome` still
        // returns `DeferCarrier`.
        let reduced_remap = self.reduce_remap_instantiation_carrier(evaluated_remap, context);
        self.classify_remap_outcome(reduced_remap, context)
    }

    /// Bind a residual `InstantiationRef` key-remap carrier through the
    /// shared `Instantiate` query and re-evaluate its body, returning the
    /// input unchanged for any other shape or when the instantiation does
    /// not close.
    ///
    /// The trailing re-evaluation is what drives a helper whose body is a
    /// `Conditional` (`type Rename<K> = K extends 'a' ? 'x' : never`) to
    /// its realised arm; without it the instantiation returns the body
    /// `Conditional` carrier and the remap would still fail closed.
    fn reduce_remap_instantiation_carrier(
        &self,
        node: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let Some(SemanticNodeData::InstantiationRef { base, args }) = self
            .graph()
            .node_data(node)
            .as_deref()
            .map(crate::semantic_query::SemanticNodeData::clone)
        else {
            return node;
        };
        let slot = self.type_slot_for(
            base.canonical_id.clone(),
            base.owner,
            base.decl_name.clone(),
        );
        let inst_ctx = self.instantiate_context_for(&base.canonical_id, context);
        let read = self.execute_read(SemanticQueryKey::Instantiate(
            crate::semantic_query::InstantiateKey::new(slot, args.as_arc().clone(), inst_ctx),
        ));
        crate::request_context::observe_component_meta_read_suppress(&read);
        let QueryResult::Value(instantiated) = read.value else {
            return node;
        };
        self.evaluate_deferred_semantic_node_with_context(instantiated, context)
            .into_active_query_build_node(self)
    }

    /// Evaluate a mapped type's K-INDEPENDENT value expression once.
    ///
    /// When `mapper.value_expr` does not structurally reference the
    /// mapper binder, the per-K substitution is the identity, so every
    /// enumerated key's substituted carrier IS `value_expr` itself.
    /// Both rails therefore evaluate it once and reuse the result for
    /// every surviving key — but only on a surviving key's DEMAND: the
    /// call sites hold this behind a lazy `Option`, so a mapped type
    /// whose keys are all remap-dropped never evaluates it.
    ///
    /// The `InstantiationRef` redispatch and the `Opaque` fallback
    /// mirror [`Self::materialize_mapped_member_value_for_key`] exactly,
    /// so the hoisted result equals what the per-K materialiser would
    /// have produced. Returns the value plus any partial-reason classes
    /// the nested `Instantiate` read contributed, for the caller to
    /// union into its own result taint.
    fn evaluate_k_independent_mapped_value(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> (SemanticNodeId, crate::semantic_query::PartialReasonSet) {
        let output = self
            .evaluate_mapped_member_value_outcome(mapper.value_expr, context)
            .into_query_build_output(self);
        let reasons = output.completeness.reasons();
        let node = match output.result {
            QueryResult::Value(node) | QueryResult::Recursive(node) => node,
            QueryResult::Error(error) => self.opaque(error),
        };
        (node, reasons)
    }

    /// Key-domain PREIMAGE of one demanded PRODUCED name through a
    /// mapper's `as`-clause remap — the single-key entrance for a
    /// remapping mapped type.
    ///
    /// With an `as <expr>` clause the surface name a consumer demands is
    /// a PRODUCED name, not an iteration key, so iteration-key
    /// membership cannot answer it. This helper inverts the remap
    /// without materialising the mapped surface: it enumerates the key
    /// DOMAIN (through the shared keyspace enumerator, which evaluates
    /// under `structural_transit` and therefore reifies no per-member
    /// value edges) and runs [`Self::mapped_member_name_remap_outcome`]
    /// per iteration key. The remap substitutes into `mapper.name_remap`
    /// and never reads `mapper.value_expr`, so every non-producing key —
    /// including every remap-DROPPED key — is decided with ZERO value
    /// forcing: no substitution into the value body, no
    /// `evaluate_deferred_*` walk, no `Instantiate` dispatch, no per-K
    /// materialiser call.
    ///
    /// Returns:
    /// - `None` — the preimage is UNDECIDABLE and the caller must take
    ///   the whole-surface route. Three causes, all fail-closed: the key
    ///   domain is OPEN or unknown (the L1 carrier-stop is authoritative
    ///   — an open domain is never enumerated to answer a narrower
    ///   demand), the key space does not enumerate, or some iteration
    ///   key's remap is [`MappedKeyRemapOutcome::DeferCarrier`] (one
    ///   undecidable remap makes the whole produced key set unknown).
    /// - `Some(keys)` — exactly these iteration keys produce `demanded`.
    ///   An EMPTY vector means the closed key domain provably produces no
    ///   such name; callers that do not own key-absent miss semantics
    ///   should treat it as a decline.
    ///
    /// Name comparison is `element_access_collides`, the same
    /// numeric/string element-access identity
    /// [`Self::build_mapped_type`] folds duplicate produced names with,
    /// so `M[1]` and `M['1']` address one produced member on both rails.
    pub(super) fn mapped_iteration_keys_producing_name(
        &self,
        source: SemanticNodeId,
        mapper: &crate::semantic_query::MapperKey,
        demanded: &PropertyKey,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<Vec<super::enumerate::KeyDomainKey>> {
        if crate::project_semantic_dispatch::raise::mapped_type_key_domain_is_open_or_unknown(
            self, source, mapper,
        ) {
            return None;
        }
        // Cancellation before key enumeration. A cancelled request must
        // not start a domain walk it will discard; declining sends the
        // caller to the coarse route, which fails closed at
        // [`Self::build_mapped_type`]'s own entry check.
        if self.cancellation.is_cancelled() {
            return None;
        }
        let domain = self.key_literals_from_keyspace_node(mapper.key_space)?;
        // DEMAND-DIRECTED admission for an IDENTITY remap.
        //
        // `as K` (the remap expression IS the mapper binder) is the one
        // remap whose inverse is known without evaluating it: it maps
        // every iteration key to itself, so the preimage of a demanded
        // produced name is that same key. Decide it by MEMBERSHIP over
        // the enumerated domain — zero substitutions into
        // `name_remap`, zero deferred evaluations, zero `Instantiate`
        // dispatches — instead of substituting and evaluating the remap
        // once per domain key. This is what keeps a single-key demand
        // through a wide identity-remapped mapper independent of source
        // WIDTH rather than linear in it.
        //
        // A literal-less domain key stays undecidable exactly as the
        // general classifier treats it
        // ([`MappedKeyRemapOutcome::DeferCarrier`]), so the
        // short-circuit and the general path decline on the same input.
        if mapper.name_remap == Some(mapper.parameter_node) {
            let mut matched: Vec<super::enumerate::KeyDomainKey> = Vec::new();
            for key in domain {
                self.key_domain_binder(&key)?;
                if key.key.element_access_collides(demanded) {
                    matched.push(key);
                }
            }
            return Some(matched);
        }
        // General (non-invertible) remap: `as Rename<K>` /
        // `as K extends … ? … : never` / template-literal remaps have no
        // closed-form inverse, so the preimage is computed by deciding
        // the remap per iteration key. That decision is the KEY-DOMAIN
        // work the mapped contract schedules BEFORE dead-ness begins: it
        // reads `mapper.name_remap` only, so every non-producing key —
        // including every remap-dropped key — is eliminated with zero
        // value forcing, and the alternative (whole-surface resolution)
        // performs this same remap decision AND forces every surviving
        // key's value. Enumeration cannot stop at the first producer:
        // several iteration keys may produce one surface name and their
        // values union.
        let mut matched: Vec<super::enumerate::KeyDomainKey> = Vec::new();
        for key in domain {
            // Cancellation before each remap substitution.
            if self.cancellation.is_cancelled() {
                return None;
            }
            let produces = match self.mapped_member_name_remap_outcome(mapper, &key, context) {
                MappedKeyRemapOutcome::Keep(name) => name.element_access_collides(demanded),
                MappedKeyRemapOutcome::Keys(names) => names
                    .iter()
                    .any(|name| name.element_access_collides(demanded)),
                // A dropped key contributes no produced name. It is dead
                // from here on: the caller never forces its value.
                MappedKeyRemapOutcome::Drop => false,
                MappedKeyRemapOutcome::DeferCarrier => return None,
            };
            if produces {
                matched.push(key);
            }
        }
        Some(matched)
    }

    /// The index-signature key types and property names a mapping's `as`
    /// clause produces for the key TYPE `key_type` (`string` of a
    /// `[k: string]` source): the remap evaluated at it, a union read arm by
    /// arm — `never` produces none; `string`, `number`, `symbol` or a
    /// template pattern produces itself as an index key type; a string or
    /// number literal produces a property name. `None` when the remap does
    /// not settle to such keys: the mapping then stays deferred.
    fn mapped_index_name_remap(
        &self,
        mapper: &crate::semantic_query::MapperKey,
        remap: SemanticNodeId,
        key_type: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> Option<MappedIndexRemap> {
        let substituted =
            self.substitute_semantic_type_param(remap, mapper.parameter_node, key_type);
        let mut pending = vec![substituted];
        let mut produced = MappedIndexRemap::default();
        while let Some(node) = pending.pop() {
            let evaluated = self
                .evaluate_deferred_semantic_node_with_context(node, context)
                .into_active_query_build_node(self);
            let evaluated = self.reduce_remap_instantiation_carrier(evaluated, context);
            match self.graph().node_data(evaluated).as_deref() {
                Some(SemanticNodeData::Primitive(PrimitiveKind::Never)) => {}
                Some(SemanticNodeData::Primitive(
                    PrimitiveKind::String | PrimitiveKind::Number | PrimitiveKind::Symbol,
                )) => produced.key_types.push(evaluated),
                Some(SemanticNodeData::TemplateLiteral { .. })
                    if !super::raise::builtin_lowering_argument_is_open(self, evaluated) =>
                {
                    produced.key_types.push(evaluated);
                }
                Some(SemanticNodeData::Literal(LiteralValue::String(text))) => {
                    produced
                        .names
                        .push(PropertyKey::string_literal(text.as_str()));
                }
                Some(SemanticNodeData::Literal(LiteralValue::Number(number))) => {
                    produced.names.push(PropertyKey::from_js_number(*number));
                }
                Some(SemanticNodeData::Union(members)) => {
                    pending.extend(members.members_arc().iter().rev().copied());
                }
                _ => return None,
            }
        }
        Some(produced)
    }

    /// Whether the source index signature the checker applies to the index
    /// key type `key_type` is readonly — `getApplicableIndexInfo` over a
    /// homomorphic mapping's modifiers type. Every applicable non-`string`
    /// signature must be readonly; when none applies, a `string` signature
    /// applies to any key but a symbol. No applicable signature leaves the
    /// produced signature mutable.
    fn applicable_source_index_readonly(
        &self,
        signatures: &[crate::semantic_query::IndexSignature],
        key_type: SemanticNodeId,
    ) -> bool {
        let graph = self.graph();
        let mut string_readonly = None;
        let mut applicable_readonly = None;
        for signature in signatures {
            // A union key type declares one signature per constituent.
            let arms: Vec<SemanticNodeId> = match graph.node_data(signature.key_type).as_deref() {
                Some(SemanticNodeData::Union(members)) => members.members_arc().to_vec(),
                _ => vec![signature.key_type],
            };
            for arm in arms {
                if matches!(
                    graph.node_data(arm).as_deref(),
                    Some(SemanticNodeData::Primitive(PrimitiveKind::String))
                ) {
                    string_readonly = Some(signature.readonly);
                } else if self.index_key_type_applies(key_type, arm) {
                    applicable_readonly =
                        Some(applicable_readonly.unwrap_or(true) && signature.readonly);
                }
            }
        }
        let symbol_key = matches!(
            graph.node_data(key_type).as_deref(),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Symbol))
        );
        applicable_readonly
            .or(string_readonly.filter(|_| !symbol_key))
            .unwrap_or(false)
    }

    /// Whether a non-`string` index signature keyed by `index_key` applies to
    /// the key type `key` (`isApplicableIndexType`): the key is assignable to
    /// it, or the key is `` `${number}` `` and the index `number`.
    fn index_key_type_applies(&self, key: SemanticNodeId, index_key: SemanticNodeId) -> bool {
        if key == index_key {
            return true;
        }
        let graph = self.graph();
        let numeric_index = matches!(
            graph.node_data(index_key).as_deref(),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Number))
        );
        let numeric_string_key = match graph.node_data(key).as_deref() {
            Some(SemanticNodeData::TemplateLiteral {
                quasis,
                expressions,
            }) => {
                quasis.iter().all(|quasi| quasi.is_empty())
                    && matches!(
                        expressions.as_ref(),
                        [only] if matches!(
                            graph.node_data(*only).as_deref(),
                            Some(SemanticNodeData::Primitive(PrimitiveKind::Number))
                        )
                    )
            }
            _ => false,
        };
        if numeric_index && numeric_string_key {
            return true;
        }
        matches!(
            self.execute_relate_pair(key, index_key),
            super::dispatch_txn::RelationStep::Assignable { .. }
        )
    }

    /// Classify an evaluated key-remap node into a [`MappedKeyRemapOutcome`].
    /// `never` ⇒ Drop, a string / numeric literal or a finite union of them ⇒
    /// Keys (numeric literals under their canonical `js_number_to_string`
    /// names), anything else (broad `string`, an unresolved shell, a
    /// non-key-capable shape — boolean / bigint literals are not property
    /// keys) ⇒ DeferCarrier (fail closed). Recurses through union arms,
    /// evaluating each arm through the shared deferred-node evaluator first:
    /// the root evaluation folds a bare template remap, but a one-to-many
    /// union remap (`as K | `x-${K}``) reaches here with its substituted arm
    /// shells unfolded — each arm gets the same evaluation demand, and the
    /// same helper instantiation, the root already received.
    fn classify_remap_outcome(
        &self,
        node: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> MappedKeyRemapOutcome {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Literal(LiteralValue::String(text))) => {
                MappedKeyRemapOutcome::Keys(vec![PropertyKey::string_literal(text.as_str())])
            }
            Some(SemanticNodeData::Literal(LiteralValue::Number(number))) => {
                MappedKeyRemapOutcome::Keys(vec![PropertyKey::from_js_number(*number)])
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Never)) => MappedKeyRemapOutcome::Drop,
            Some(SemanticNodeData::Union(members)) => {
                let members = members.members_arc();
                let mut keys: Vec<PropertyKey> = Vec::new();
                for member in members.iter() {
                    let evaluated = self
                        .evaluate_deferred_semantic_node_with_context(*member, context)
                        .into_active_query_build_node(self);
                    // An arm that applies a helper (`as Rename<K> | 'x'`)
                    // binds its key argument as a root helper remap does.
                    let evaluated = self.reduce_remap_instantiation_carrier(evaluated, context);
                    match self.classify_remap_outcome(evaluated, context) {
                        MappedKeyRemapOutcome::Keys(ks) => keys.extend(ks),
                        // A `never` arm contributes no key (filtered);
                        // anything non-finite taints the whole remap.
                        MappedKeyRemapOutcome::Drop => {}
                        MappedKeyRemapOutcome::Keep(_) | MappedKeyRemapOutcome::DeferCarrier => {
                            return MappedKeyRemapOutcome::DeferCarrier;
                        }
                    }
                }
                if keys.is_empty() {
                    MappedKeyRemapOutcome::Drop
                } else {
                    MappedKeyRemapOutcome::Keys(keys)
                }
            }
            _ => MappedKeyRemapOutcome::DeferCarrier,
        }
    }

    /// The one typed `Cancelled` build output — shared by every builder
    /// that checks cancellation (conditional selection, mapped key
    /// enumeration / per-key forcing, …). It is `ReturnOnly`:
    /// `cache_suppress` keeps a cancelled result out of every warm
    /// candidate, so partially forced per-key work can never warm a
    /// complete family entry.
    pub(super) fn cancelled_build_output(&self) -> super::walk::QueryBuildOutput {
        let mut output = super::walk::QueryBuildOutput::from((
            QueryResult::Error(QueryError::Cancelled),
            self.project_generation_signature(),
        ));
        output.cache_suppress = true;
        output.mark_partial();
        output.add_partial_reasons(crate::semantic_query::PartialReasonSet::CANCELLED);
        output
    }

    /// Deep `Infer`-occurrence scan over a node's structural subtree
    /// (mirrors `subtree_references_node`'s child walk, target-free).
    /// Guards the infer-routing: an `Infer` anywhere outside the in-scope
    /// direct positions keeps the conditional deferred rather than
    /// leaking an unbound placeholder into the selected branch.
    pub fn subtree_contains_infer(&self, root: SemanticNodeId) -> bool {
        !self.infer_scan(root, false).infers.is_empty()
    }

    /// The `infer` declarations in `root`'s structural subtree (the first
    /// one alone unless `collect_all`), and whether the subtree holds a
    /// nested conditional or mapped type, whose own binders scope what lies
    /// under them ([`Self::subtree_contains_infer`]'s walk).
    pub(super) fn infer_scan(&self, root: SemanticNodeId, collect_all: bool) -> InferScan {
        let mut scan = InferScan::default();
        let graph = self.graph();
        let mut visited: rustc_hash::FxHashSet<SemanticNodeId> = rustc_hash::FxHashSet::default();
        let mut stack: Vec<SemanticNodeId> = vec![root];
        while let Some(node) = stack.pop() {
            if !visited.insert(node) {
                continue;
            }
            let Some(data) = graph.node_data(node) else {
                continue;
            };
            match data.as_ref() {
                SemanticNodeData::Infer { .. } => {
                    scan.infers.push(node);
                    if !collect_all {
                        return scan;
                    }
                }
                SemanticNodeData::Alias(inner) => stack.push(*inner),
                composite @ (SemanticNodeData::Union(_) | SemanticNodeData::Intersection(_)) => {
                    let members = composite.composite_members().expect("composite arm");
                    for member in members.iter() {
                        stack.push(*member);
                    }
                }
                SemanticNodeData::Array { element, .. } => stack.push(*element),
                SemanticNodeData::Tuple { elements, .. } => {
                    for element in elements.iter() {
                        stack.push(element.value);
                    }
                }
                SemanticNodeData::Object(surface) => {
                    for member in surface.positive_members().iter() {
                        stack.push(member.value);
                    }
                    for signature in surface.call_signatures.iter() {
                        stack.push(*signature);
                    }
                    for signature in surface.construct_signatures.iter() {
                        stack.push(*signature);
                    }
                    for signature in surface.index_signatures.iter() {
                        stack.push(signature.key_type);
                        stack.push(signature.value_type);
                    }
                    if let Some(k) = surface.keyspace {
                        stack.push(k);
                    }
                }
                SemanticNodeData::Signature {
                    params,
                    return_type,
                    type_parameters,
                    predicate,
                    ..
                } => {
                    for param in params.iter() {
                        stack.push(param.ty);
                    }
                    stack.push(*return_type);
                    for tp in type_parameters.iter() {
                        if let Some(c) = tp.constraint {
                            stack.push(c);
                        }
                        if let Some(d) = tp.default {
                            stack.push(d);
                        }
                    }
                    stack.extend(predicate.and_then(|predicate| predicate.ty));
                }
                SemanticNodeData::Conditional {
                    check,
                    extends,
                    true_branch_ref,
                    false_branch_ref,
                    pending,
                    ..
                } => {
                    scan.binder_scope = true;
                    if let Some(pending) = pending {
                        stack.extend(pending.argument_nodes());
                    }
                    stack.push(*check);
                    stack.push(*extends);
                    stack.push(*true_branch_ref);
                    stack.push(*false_branch_ref);
                }
                SemanticNodeData::InstantiationRef { args, .. } => {
                    for arg in args.iter() {
                        stack.push(*arg);
                    }
                }
                SemanticNodeData::MergedDecl { contributors } => {
                    for contributor in contributors.iter() {
                        stack.push(*contributor);
                    }
                }
                SemanticNodeData::TemplateLiteral { expressions, .. } => {
                    for expr in expressions.iter() {
                        stack.push(*expr);
                    }
                }
                SemanticNodeData::KeyOf { base } => stack.push(*base),
                SemanticNodeData::IndexedAccess { object, index } => {
                    stack.push(*object);
                    if let crate::semantic_query::IndexKey::Computed(idx_node) = index {
                        stack.push(*idx_node);
                    }
                }
                SemanticNodeData::Mapped { source, mapper } => {
                    scan.binder_scope = true;
                    stack.push(*source);
                    stack.push(mapper.key_space);
                    stack.push(mapper.value_expr);
                    if let Some(remap) = mapper.name_remap {
                        stack.push(remap);
                    }
                }
                _ => {}
            }
        }
        scan
    }

    construction_ordinal_seam! {
        /// Ordered union reduction — the `ReduceUnion` query builder. Routes
        /// through the canonical algebra (recursive flattening, §22 lattice
        /// absorption, literal subsumption, structural `T | T = T`), threading
        /// the canonicalization's freshness evidence onto the memo entry
        /// EXPLICITLY: the inspected-root set (discarded duplicates and
        /// `Global`-intermediate descendants included) joins the direct-member
        /// self-roots, and an incomplete comparison sets `cache_suppress`
        /// (ReturnOnly — never a warm canonical result).
        ///
        /// Emits one `Normalize` origin edge from the result to EVERY
        /// contributing source member whenever the input had more than one
        /// member — lattice-extreme and proven-disjoint folds included — so
        /// provenance recovery finds the pre-canonical input set even after
        /// absorption / dedup / sorting (`ReduceIntersection([string,
        /// number])` records `string` and `number` on the shared `never`).
        /// Edges landing on a shared `Global` primitive are accepted growth:
        /// the derivation store deduplicates identical edges, and each edge is
        /// a true "some normalization folded these contributors here" fact.
        fn build_reduce_union(
            &self,
            members: &Arc<[SemanticNodeId]>,
            nullability: verter_session_query::flow::policy::NullabilityPolicy,
        ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
            verter_audit::attribute!(ReduceUnion);
            self.build_normalize_composite(
                members,
                super::canonical_algebra::intern_ordered_union_charged(
                    self.graph(),
                    members,
                    nullability,
                    self.construction_meter(),
                ),
            )
        }
    }

    construction_ordinal_seam! {
        /// Ordered intersection reduction — the `ReduceIntersection` query
        /// builder. Same evidence threading and origin-edge discipline as
        /// [`Self::build_reduce_union`]; the algebra additionally applies
        /// the intersection lattice laws and the PROVEN-disjoint scalar
        /// collapse (`string & number = never`). Operand order is preserved.
        /// The purpose selects a derived intersection's reduction or a
        /// written type node's, which keeps the written `string & {}` pair.
        fn build_reduce_intersection(
            &self,
            input: crate::semantic_query::IntersectionInputRef,
            purpose: crate::semantic_query::IntersectionPurpose,
            context: crate::semantic_query::SemanticContextId,
        ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
            verter_audit::attribute!(ReduceIntersection);
            let reduce = |members: &[SemanticNodeId]| match purpose {
                crate::semantic_query::IntersectionPurpose::CheckerReduction => {
                    super::canonical_algebra::intern_ordered_intersection_charged(
                        self.graph(),
                        members,
                        self.construction_meter(),
                    )
                }
                crate::semantic_query::IntersectionPurpose::WrittenTypeNode(nullability) => {
                    super::canonical_algebra::intern_written_intersection_charged(
                        self.graph(),
                        members,
                        nullability,
                        self.construction_meter(),
                    )
                }
            };
            if let Some(steps) = input.as_steps() {
                let mut members: Vec<SemanticNodeId> = Vec::with_capacity(steps.len());
                for step in steps.iter() {
                    match step {
                        crate::semantic_query::IntersectionTerm::Value(id) => members.push(*id),
                        crate::semantic_query::IntersectionTerm::EvaluateSubgroup {
                            input: nested,
                            purpose,
                        } => {
                            let nested_key =
                                crate::semantic_query::SemanticQueryKey::ReduceIntersection {
                                    input: nested.clone(),
                                    purpose: *purpose,
                                    context: context.clone(),
                                };
                            match self.execute_read(nested_key).value {
                                crate::semantic_query::QueryResult::Value(node) => members.push(node),
                                crate::semantic_query::QueryResult::Recursive(node) => {
                                    members.push(node)
                                }
                                crate::semantic_query::QueryResult::Error(_) => {}
                            }
                        }
                    }
                }
                let members: Arc<[SemanticNodeId]> = Arc::from(members.into_boxed_slice());
                self.build_normalize_composite(&members, reduce(&members))
            } else {
                let members: Arc<[SemanticNodeId]> = Arc::from(input.as_ordered_values());
                self.build_normalize_composite(&members, reduce(&members))
            }
        }
    }

    /// Shared body of the two normalization builders: records the origin
    /// edges and the evidence of the canonical `composite` built over
    /// `members`.
    fn build_normalize_composite(
        &self,
        members: &Arc<[SemanticNodeId]>,
        composite: super::canonical_algebra::CanonicalComposite,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let node = composite.node;
        let fence = self.project_generation_signature();
        if members.len() > 1 {
            crate::semantic_query_memo::record_origin_edge!(
                self.graph(),
                node,
                OriginEdgeKind::Normalize,
                Arc::clone(members),
                OriginMeta::None,
                fence.clone(),
            );
        }
        // Self-version rooting: the normalised composite depends on every
        // contributing member node AND on every file-scoped node the
        // canonical identity walk inspected — including discarded
        // duplicates, whose file edits must miss the warm read even though
        // the duplicate no longer appears in the result.
        let mut observed_self_roots = self.observed_self_roots_from_nodes(members.iter().copied());
        super::extend_unique_self_roots(
            &mut observed_self_roots,
            composite.evidence.inspected_file_roots,
        );
        let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node),
            fence,
        ))
        .with_observed_self_roots(observed_self_roots);
        // An incomplete or budget-tripped canonical comparison is
        // ReturnOnly: the value flows to the caller, the memo refuses
        // admission.
        output.cache_suppress |= composite.evidence.incomplete;
        // A refused intersection's recovery is a resource partial.
        if composite.evidence.refusal.is_some() {
            self.fold_local_partial_completeness(
                crate::semantic_query::PartialReasonSet::OPERATION_BUDGET,
            );
        }
        // A distribution the connected demand could not pay for is the
        // written composite, a partial of the rails it exhausted.
        if !composite.evidence.exhausted.is_empty() {
            self.fold_local_partial_completeness(composite.evidence.exhausted);
        }
        output
    }

    /// The checker's `getStringMappingType` for the intrinsic `intrinsic`
    /// over `operand`, read where the application is written
    /// ([`Self::settle_string_operand`]): a union maps each constituent,
    /// `never` stays `never`, a string literal maps its text, and a
    /// template literal type maps its texts and holes
    /// (`applyTemplateStringMapping`). `string`, `any` and another string
    /// mapping keep the application (`Uppercase<string>`; the same mapping
    /// twice is one), and `number` / `bigint` apply to their pattern
    /// template (`` Uppercase<`${number}`> ``). A non-string literal is the
    /// operand itself, and an operand that does not settle — an open
    /// binder, a generic `keyof` — keeps the application over the operand
    /// as authored, so a later substitution reduces it.
    pub(super) fn apply_string_intrinsic(
        &self,
        intrinsic: &str,
        operand: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let graph = self.graph();
        let resolved = self.settle_string_operand(operand, context);
        let data = graph.node_data(resolved);
        match data.as_deref() {
            Some(SemanticNodeData::Literal(LiteralValue::String(text))) => {
                let transformed = transform_string_intrinsic(intrinsic, text);
                graph.intern_node(SemanticNodeData::Literal(LiteralValue::String(transformed)))
            }
            Some(SemanticNodeData::Literal(_)) => resolved,
            Some(SemanticNodeData::Union(members)) => {
                let members = members.members_arc();
                drop(data);
                let mapped: Vec<SemanticNodeId> = members
                    .iter()
                    .map(|member| self.apply_string_intrinsic(intrinsic, *member, context))
                    .collect();
                let read = self.execute_read(SemanticQueryKey::ReduceUnion {
                    members: Arc::from(mapped.into_boxed_slice()),
                    nullability: verter_session_query::flow::policy::NullabilityPolicy::Strict,
                });
                match read.value {
                    QueryResult::Value(id) => id,
                    _ => self.string_mapping_carrier(intrinsic, operand),
                }
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Never)) => resolved,
            Some(SemanticNodeData::Primitive(PrimitiveKind::String | PrimitiveKind::Any)) => {
                drop(data);
                self.string_mapping_carrier(intrinsic, resolved)
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Number | PrimitiveKind::BigInt)) => {
                drop(data);
                let pattern = graph.intern_node(SemanticNodeData::TemplateLiteral {
                    quasis: verter_type_expr::OwnedSlice::from(vec![
                        OwnedStr::from(""),
                        OwnedStr::from(""),
                    ]),
                    expressions: crate::semantic_query::PayloadArray::from(
                        vec![resolved].into_boxed_slice(),
                    ),
                });
                self.string_mapping_carrier(intrinsic, pattern)
            }
            Some(SemanticNodeData::TemplateLiteral {
                quasis,
                expressions,
            }) if expressions.iter().all(|hole| self.is_template_hole(*hole)) => {
                let (quasis, expressions) = (quasis.clone(), Arc::clone(expressions.as_arc()));
                drop(data);
                self.apply_template_string_mapping(intrinsic, &quasis, &expressions, context)
            }
            _ => {
                drop(data);
                match self.string_mapping_of(resolved) {
                    Some((existing, _)) if existing.as_ref() == intrinsic => resolved,
                    Some(_) => self.string_mapping_carrier(intrinsic, resolved),
                    None => self.string_mapping_carrier(intrinsic, operand),
                }
            }
        }
    }

    /// `applyTemplateStringMapping`: `Uppercase` / `Lowercase` map every
    /// text and every hole of a template literal type; `Capitalize` /
    /// `Uncapitalize` map its first text, or its first hole when that text
    /// is empty.
    fn apply_template_string_mapping(
        &self,
        intrinsic: &str,
        quasis: &[OwnedStr],
        holes: &[SemanticNodeId],
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let whole = matches!(intrinsic, "Uppercase" | "Lowercase");
        let first_text_empty = quasis.first().is_none_or(|text| text.is_empty());
        let mut pieces: Vec<TemplatePiece> = Vec::with_capacity(quasis.len() + holes.len());
        for (index, text) in quasis.iter().enumerate() {
            let text = if whole || (index == 0 && !first_text_empty) {
                transform_string_intrinsic(intrinsic, text)
            } else {
                text.to_string()
            };
            pieces.push(TemplatePiece::Text(text));
            if let Some(hole) = holes.get(index) {
                pieces.push(TemplatePiece::Hole(
                    if whole || (index == 0 && first_text_empty) {
                        self.apply_string_intrinsic(intrinsic, *hole, context)
                    } else {
                        *hole
                    },
                ));
            }
        }
        self.template_type_from_pieces(pieces)
    }

    /// The `__builtin__` string-mapping application `intrinsic<operand>`.
    fn string_mapping_carrier(&self, intrinsic: &str, operand: SemanticNodeId) -> SemanticNodeId {
        self.graph()
            .intern_node(SemanticNodeData::InstantiationRef {
                base: crate::semantic_query::DeclIdentity {
                    canonical_id: verter_type_expr::OwnedStr::from("__builtin__"),
                    owner: verter_type_expr::TopLevelOwnerId::ordinary_file(),
                    whole_hash: crate::semantic_query::HashValue::default(),
                    decl_name: verter_type_expr::OwnedStr::from(intrinsic),
                },
                args: crate::semantic_query::PayloadArray::from(vec![operand].into_boxed_slice()),
            })
    }

    /// The string mapping a `__builtin__` application applies, with its
    /// operand.
    pub(super) fn string_mapping_of(
        &self,
        node: SemanticNodeId,
    ) -> Option<(Arc<str>, SemanticNodeId)> {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::InstantiationRef { base, args })
                if base.canonical_id.as_ref() == "__builtin__"
                    && matches!(
                        base.decl_name.as_ref(),
                        "Uppercase" | "Lowercase" | "Capitalize" | "Uncapitalize"
                    )
                    && args.len() == 1 =>
            {
                Some((
                    std::sync::Arc::<str>::from(base.decl_name.as_str()),
                    args[0],
                ))
            }
            _ => None,
        }
    }

    /// Whether a template literal type keeps `node` as a hole: `string`,
    /// `number`, `bigint`, `any`, a template literal type made of those, or
    /// a string mapping over one of them.
    pub(super) fn is_template_hole(&self, node: SemanticNodeId) -> bool {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Primitive(
                PrimitiveKind::String
                | PrimitiveKind::Number
                | PrimitiveKind::BigInt
                | PrimitiveKind::Any,
            )) => true,
            Some(SemanticNodeData::TemplateLiteral { expressions, .. }) => {
                expressions.iter().all(|hole| self.is_template_hole(*hole))
            }
            _ => self
                .string_mapping_of(node)
                .is_some_and(|(_, operand)| self.is_template_hole(operand)),
        }
    }

    /// The type an operand of a string mapping or a template literal type
    /// denotes where it is written: an alias, a declaration or application
    /// carrier settles to what it names, a `keyof` whose keys settle is
    /// that key union, and an intersection is the canonical intersection of
    /// its settled members (`keyof T & string` over `T = Plain` is
    /// `"a" | "b"`). A string-mapping application and every other shape is
    /// itself.
    pub(super) fn settle_string_operand(
        &self,
        node: SemanticNodeId,
        context: crate::semantic_query::ProjectionReductionContext,
    ) -> SemanticNodeId {
        let mut visited = crate::semantic_query::small_node_set::SmallNodeSet::default();
        let mut current = self
            .evaluate_deferred_semantic_node_with_context(node, context)
            .into_active_query_build_node(self);
        while visited.insert(current) {
            if self.string_mapping_of(current).is_some() {
                return current;
            }
            let data = self.graph().node_data(current);
            let next = match data.as_deref() {
                Some(SemanticNodeData::Alias(inner)) => *inner,
                Some(
                    SemanticNodeData::DeclRef { .. } | SemanticNodeData::InstantiationRef { .. },
                ) => {
                    drop(data);
                    self.resolve_signature_source_carrier(current, context)
                }
                Some(SemanticNodeData::KeyOf { base }) => {
                    let base = *base;
                    drop(data);
                    match self.key_set_of(base) {
                        Some(keys) => keys,
                        None => return current,
                    }
                }
                Some(SemanticNodeData::Intersection(members)) => {
                    let members = members.members_arc();
                    drop(data);
                    let settled: Vec<SemanticNodeId> = members
                        .iter()
                        .map(|member| self.settle_string_operand(*member, context))
                        .collect();
                    if settled.as_slice() == members.as_ref() {
                        return current;
                    }
                    self.intern_normalized_union_or_intersection(&settled, false)
                }
                _ => return current,
            };
            if next == current {
                return current;
            }
            current = self
                .evaluate_deferred_semantic_node_with_context(next, context)
                .into_active_query_build_node(self);
        }
        current
    }

    /// Template-literal reduction — the LIVE producer for
    /// [`SemanticQueryKey::TemplateLiteralReduce`].
    ///
    /// ONE-ENGINE shape: this build is the SINGLE shared template-literal
    /// reducer. It resolves every interpolated expression of the key's
    /// `pattern` (quasis) + `args` (expressions) to its finite set of
    /// string-literal choices through the shared deferred evaluator, then
    /// forms the CARTESIAN PRODUCT of those choices into the folded surface
    /// ([`Self::reduce_template_literal_nodes`]). An all-single-literal
    /// template folds to one [`SemanticNodeData::Literal`] string; a finite
    /// union of choices renormalises through
    /// [`SemanticQueryKey::ReduceUnion`]; any non-finite expression
    /// carrier-stops to the `TemplateLiteral` shell. There is no second
    /// walker — the deferred evaluator's `TemplateLiteral` arm and the
    /// mapped key-remap path both reach this reducer THROUGH this query.
    ///
    /// A product at the checker's limit is its TS2590 recovery, a complete
    /// fact. A construction the connected-work ledger refuses carrier-stops
    /// to the deferred shell, marked NON-CACHEABLE / budget-tainted
    /// (`cache_suppress` + `result_is_partial`): an exhausted product is
    /// never warm-admitted.
    ///
    /// Self-version rooting: the reduction depends on every interpolated
    /// arg node, so the memo entry roots on the file content version each
    /// file-derived arg was lowered from (mirrors `build_reduce_union`).
    /// `args` is consumed in ORDER — concatenation order is semantic and is
    /// never reordered.
    pub(super) fn build_template_literal_reduce(
        &self,
        pattern: &verter_type_expr::OwnedSlice<OwnedStr>,
        args: &Arc<[SemanticNodeId]>,
        _context: crate::semantic_query::TemplateLiteralReduceContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let reduced = self.reduce_template_literal_nodes(
            pattern,
            args,
            crate::semantic_query::ProjectionReductionContext::published(ProjectionMode::Expanded),
        );
        let observed_self_roots = self.observed_self_roots_from_nodes(args.iter().copied());
        let node = reduced.unwrap_or_else(|_| {
            self.graph().intern_node(SemanticNodeData::TemplateLiteral {
                quasis: pattern.clone(),
                expressions: crate::semantic_query::PayloadArray::from(Arc::clone(args)),
            })
        });
        let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            QueryResult::Value(node),
            self.project_generation_signature(),
        ))
        .with_observed_self_roots(observed_self_roots);
        if reduced.is_err() {
            // The ledger refused the construction: the value is the deferred
            // carrier-stop shell, not the enumerated surface. It is a
            // non-cacheable budget-tainted partial, never warm-admitted, and
            // the taint folds into the enclosing request.
            output.cache_suppress = true;
            output.mark_partial();
            // The refused Cartesian construction keeps every original quasi
            // and interpolation operand at the addressed template position.
            output = output.with_positional_guarantee();
        }
        output
    }

    /// Whether `node` is a SETTLED shape the awaited relations provably
    /// reduce to ITSELF without reading its structure — it cannot be a
    /// thenable, so there is nothing to unwrap.
    ///
    /// The shared prelude's fast path for both relations. A `then`-bearing
    /// object surface is NOT settled here: the structural arms decide it by
    /// the checker's thenable protocol (`surface_thenability`).
    ///
    /// NEGATIVE EVIDENCE ONLY. `false` means "not proven settled", never
    /// "is a thenable": the caller falls through to the real reduction or to
    /// the canonical deferred intrinsic, and never fabricates an answer. An
    /// unresolved carrier (a `DeclRef`, an alias, an open parameter) answers
    /// `false` and defers, because it CAN still resolve to a `Promise` once
    /// substituted — the inverse polarity of a "does it look like Promise"
    /// gate, which would default to passthrough for anything it did not
    /// recognise and silently publish the wrong type.
    pub fn settled_non_thenable(&self, node: SemanticNodeId) -> bool {
        match self.graph().node_data(node).as_deref() {
            // Nullish passes through — the lib conditional's first clause.
            Some(SemanticNodeData::Primitive(PrimitiveKind::Null | PrimitiveKind::Undefined)) => {
                true
            }
            Some(
                SemanticNodeData::Primitive(_)
                | SemanticNodeData::Literal(_)
                | SemanticNodeData::TemplateLiteral { .. }
                | SemanticNodeData::Signature { .. }
                | SemanticNodeData::Tuple { .. }
                | SemanticNodeData::Array { .. },
            ) => true,
            // An object surface settles here only when it carries NO `then`
            // member; a `then`-bearing surface goes to the thenable
            // protocol. Member PRESENCE only — no signature logic lives on
            // this fast path.
            Some(SemanticNodeData::Object(surface)) => then_members(surface).is_empty(),
            // A union settles only if EVERY arm does.
            Some(SemanticNodeData::Union(members)) => members
                .iter()
                .all(|member| self.settled_non_thenable(*member)),
            _ => false,
        }
    }

    /// The canonical deferred form of the awaited relation over an operand
    /// whose binder is still open: `IntrinsicApplication(Awaited, [operand])`.
    ///
    /// A settled, memoizable SYMBOLIC value — NOT a refusal and NOT an
    /// `InstantiationRef` of a lib alias. Minting it as a declaration
    /// application (the shape this replaced) would let a userland `Awaited`
    /// declaration capture a compiler-native operation by spelling.
    fn deferred_awaited(&self, operand: SemanticNodeId) -> SemanticNodeId {
        self.graph().intern_node(
            SemanticNodeData::intrinsic_application(
                crate::semantic_query::CompilerIntrinsicTypeOp::Awaited,
                Arc::from(vec![operand].into_boxed_slice()),
            )
            .expect("Awaited takes exactly the one operand supplied here"),
        )
    }

    /// The checker's error type after `diagnostic`, as the typed recovery
    /// carrier.
    fn checker_recovery(
        &self,
        diagnostic: crate::semantic_query::CheckerDiagnostic,
    ) -> SemanticNodeId {
        crate::semantic_query::checker_policy::checker_recovery(self.graph(), diagnostic)
    }

    /// Whether `reduced` is `relation`'s TS1062 failure for `operand` — the
    /// relation's own recovery carrier, reached from an operand that was not
    /// already an error type (an error-type operand is its own answer, so it
    /// passes through as a value).
    fn awaited_relation_failed_on(
        &self,
        relation: AwaitedRelation,
        operand: SemanticNodeId,
        reduced: SemanticNodeId,
    ) -> bool {
        use crate::project_semantic_dispatch::absorb::SpecialKind;
        matches!(
            self.graph().node_data(reduced).as_deref(),
            Some(SemanticNodeData::Opaque(QueryError::CheckerRecovery { diagnostic, .. }))
                if *diagnostic == relation.recursion_diagnostic()
        ) && !matches!(
            self.peek_special(operand),
            Some((SpecialKind::Error | SpecialKind::Wildcard, _))
        )
    }

    /// Whether the runtime awaited relation FAILED on `operand` with TS1062,
    /// given the node `awaited_normalize_for_flow` answered for it.
    pub(super) fn awaited_normalize_failed_on(
        &self,
        operand: SemanticNodeId,
        reduced: SemanticNodeId,
    ) -> bool {
        self.awaited_relation_failed_on(AwaitedRelation::Normalize, operand, reduced)
    }

    /// Whether `operand` is a type `relation` is ALREADY unwrapping on the
    /// current path — the checker's own recursion rule
    /// (`getAwaitedTypeNoAlias` and its `awaitedTypeStack`): the thenable
    /// that promised it references itself, directly or indirectly, in its
    /// fulfillment callback, and the checker reports TS1062 and fails the
    /// step. The path is every operand an enclosing run of this relation
    /// has reached (its tail steps included, which open no query) plus every
    /// in-flight query of the relation. Which operands are in flight is a
    /// fact about this path, not about `operand`, so every answer built over
    /// such a failure stays out of the warm memo.
    fn awaited_operand_on_path(
        &self,
        relation: AwaitedRelation,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> bool {
        let on_path = self.awaited_active.borrow().contains(relation, operand)
            || self
                .graph()
                .is_same_path_claim_at(&relation.key(operand, context), self.checking_site.get());
        if on_path {
            self.fold_into_top_build_local_taint(false, true);
        }
        on_path
    }

    /// Re-enter `relation`'s own family on `operand` — a NESTED unwrap (a
    /// union arm, a type parameter's constraint arm). Going back through the
    /// query puts it under the family memo and the singleflight; each
    /// relation re-enters ONLY itself, so an async return payload never
    /// comes back as `Awaited<T>` for a nested naked `T`. An operand already
    /// on the path fails the step with TS1062
    /// ([`Self::awaited_operand_on_path`]).
    fn awaited_relation_step(
        &self,
        relation: AwaitedRelation,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedOutcome {
        if self.awaited_operand_on_path(relation, operand, context) {
            return AwaitedOutcome::Failed;
        }
        match self.execute_read(relation.key(operand, context)).value {
            QueryResult::Value(node)
                if self.awaited_relation_failed_on(relation, operand, node) =>
            {
                AwaitedOutcome::Failed
            }
            QueryResult::Value(node) => AwaitedOutcome::Value(node),
            _ => AwaitedOutcome::Refused,
        }
    }

    /// One RUN of `relation` from `operand`: its tail steps
    /// ([`AwaitedStep::Next`], [`AwaitedStep::Expand`]) continue in this
    /// loop rather than re-entering the query, so a chain of distinct
    /// thenables costs no query depth — the checker's own relation has no
    /// depth rule (a 5000-step chain awaits to its value on tsc 7.0.2).
    ///
    /// Every operand the run reaches is on the path for the checker's
    /// recursion rule while the run lasts, nested runs included
    /// ([`Self::awaited_operand_on_path`]). Every tail step is charged to
    /// the connected-work budget, so genuinely unbounded work (a thenable
    /// that grows without repeating) stops as a typed partial instead of
    /// running on.
    fn awaited_relation_run(
        &self,
        relation: AwaitedRelation,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedOutcome {
        let base = self.awaited_active.borrow().len();
        let _path = AwaitedPathGuard {
            active: &self.awaited_active,
            base,
        };
        self.awaited_active.borrow_mut().push(relation, operand);
        // The declaration carriers expanded consecutively into `current`,
        // outermost first: when `current` is its own answer, the innermost
        // carrier is, and so on outwards while each carrier was its
        // predecessor's body.
        let mut carriers: Vec<(SemanticNodeId, SemanticNodeId)> = Vec::new();
        let mut current = operand;
        loop {
            let step = match relation {
                AwaitedRelation::Normalize => self.awaited_normalize_node(current, context),
                AwaitedRelation::Payload => self.async_return_payload_node(current, context),
            };
            let next = match step {
                AwaitedStep::Value(mut node) => {
                    for (carrier, body) in carriers.iter().rev() {
                        if node != *body {
                            break;
                        }
                        node = *carrier;
                    }
                    return AwaitedOutcome::Value(node);
                }
                AwaitedStep::Failed => return AwaitedOutcome::Failed,
                AwaitedStep::Refused => return AwaitedOutcome::Refused,
                AwaitedStep::Next(next) => {
                    carriers.clear();
                    next
                }
                AwaitedStep::Expand { carrier, body } => {
                    carriers.push((carrier, body));
                    body
                }
            };
            if self.awaited_operand_on_path(relation, next, context) {
                return AwaitedOutcome::Failed;
            }
            if let Err(reasons) = self.charge_connected_work() {
                self.fold_local_partial_completeness(reasons);
                return AwaitedOutcome::Refused;
            }
            self.awaited_active.borrow_mut().push(relation, next);
            current = next;
        }
    }

    /// Distribute `relation` over union arms the way the checker maps
    /// `getAwaitedTypeNoAlias` over a union: an arm that FAILS (TS1062) is
    /// dropped, and the union fails only when every arm does. An arm that
    /// refuses defers the whole reduction — a partial distribution would
    /// silently drop information.
    fn awaited_union_step(
        &self,
        relation: AwaitedRelation,
        arms: &[SemanticNodeId],
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedStep {
        let mut reduced: Vec<SemanticNodeId> = Vec::with_capacity(arms.len());
        for arm in arms {
            match self.awaited_relation_step(relation, *arm, context) {
                AwaitedOutcome::Value(node) => reduced.push(node),
                AwaitedOutcome::Failed => {}
                AwaitedOutcome::Refused => return AwaitedStep::Refused,
            }
        }
        match reduced.as_slice() {
            [] => AwaitedStep::Failed,
            [single] => AwaitedStep::Value(*single),
            _ => AwaitedStep::Value(self.intern_normalized_union_or_intersection(&reduced, true)),
        }
    }

    /// The instantiation a lowering-time self-reference sentinel names.
    ///
    /// A declaration's body lowers a reference to the declaration itself as
    /// `RecursiveRef { name, args }` (`interface Rec { then(f: (v: Rec) =>
    /// void): void }` — the `Rec` in the callback; `G<[T]>` inside the body
    /// of `G<string>`), scoped to the declaring file. The sentinel records
    /// the instantiation it stands for, so it answers as that application's
    /// carrier: the `InstantiationRef` over the recorded arguments, or the
    /// `DeclRef` of a declaration with no type parameters. A generic
    /// declaration referenced without arguments, and a function-local
    /// declaration (not addressable by its file slot), stay the sentinel.
    pub(super) fn self_reference_declaration(
        &self,
        node: SemanticNodeId,
    ) -> Option<SemanticNodeId> {
        let (name, args) = match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::Opaque(QueryError::RecursiveRef { name, args })) => {
                (name.clone(), Arc::<[SemanticNodeId]>::from(args.operands()))
            }
            _ => return None,
        };
        let scope = self.graph().node_scope(node)?;
        let NodeScopeId::File {
            canonical_id,
            owner,
            whole_hash,
            local_scope: None,
        } = &scope
        else {
            return None;
        };
        let prepared = self.ctx.prepared_type_decl_return_only(
            canonical_id.as_ref(),
            *owner,
            name.as_ref(),
        )?;
        if args.is_empty() && !prepared.type_parameters.is_empty() {
            return None;
        }
        let identity = crate::semantic_query::DeclIdentity {
            canonical_id: canonical_id.clone(),
            owner: *owner,
            whole_hash: *whole_hash,
            decl_name: name,
        };
        let carrier = if args.is_empty() {
            SemanticNodeData::DeclRef { identity }
        } else {
            SemanticNodeData::InstantiationRef {
                base: identity,
                args: crate::semantic_query::PayloadArray::from(args),
            }
        };
        Some(self.graph().intern_node_with_scope(carrier, scope.clone()))
    }

    /// Settle the operand once, through the shared deferred evaluator, and
    /// answer the lattice extremes both relations share. `Err(())` is the
    /// honest refusal; `Ok(Some(node))` a decided answer; `Ok(None)` means
    /// "keep going, inspect the structure".
    fn awaited_operand_prelude(
        &self,
        operand: SemanticNodeId,
    ) -> (SemanticNodeId, Option<SemanticNodeId>) {
        use crate::project_semantic_dispatch::absorb::SpecialKind;
        let resolved = self
            .evaluate_deferred_semantic_node_with_context(
                operand,
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
            .into_active_query_build_node(self);
        // A declaration's lowering-time reference to itself is the
        // declaration it names.
        let resolved = self
            .self_reference_declaration(resolved)
            .unwrap_or(resolved);
        // `any` / `never` / `unknown` and the dominating error carrier all
        // answer with the resolved operand verbatim.
        if let Some((kind, special)) = self.peek_special(resolved) {
            let decided = match kind {
                SpecialKind::Any
                | SpecialKind::Never
                | SpecialKind::Unknown
                | SpecialKind::Error
                | SpecialKind::Wildcard => special,
            };
            return (resolved, Some(decided));
        }
        // Settled non-thenable (including nullish, and a union of only such
        // arms): both relations are the identity here.
        if self.settled_non_thenable(resolved) {
            return (resolved, Some(resolved));
        }
        (resolved, None)
    }

    /// The structural arms BOTH compiler awaited relations share, reached
    /// after each family's own arms declined. They follow the checker's
    /// runtime awaited-type protocol (`getAwaitedType` /
    /// `getPromisedTypeOfPromise`) — NOT the lib `Awaited<T>` conditional,
    /// which types malformed thenables differently (see
    /// [`Self::lib_awaited_node`]):
    ///
    /// - an object surface is decided by its `then` member
    ///   ([`Self::surface_thenability`]): not thenable ⇒ itself; a valid
    ///   thenable ⇒ the run continues on a single promised value, and
    ///   several are the checker's union, each arm a nested unwrap; a callable `then`
    ///   with no callable `onfulfilled` ⇒ `any` (the checker reports the
    ///   operand and types it `any`); the promised values are one union to
    ///   the checker, so a value the relation FAILS on is dropped, and the
    ///   step fails only when every value does;
    /// - a declaration carrier (`DeclRef` / `InstantiationRef`) expands ONE
    ///   level through the shared `Instantiate` family and the run continues
    ///   on its body. When the body comes back unchanged the
    ///   CARRIER is the answer, so a non-thenable alias keeps its authored
    ///   identity (`Promise<Box<T>>`, never the expanded `{ w: T }`).
    ///
    /// Anything the protocol cannot decide refuses honestly.
    fn awaited_structural_node(
        &self,
        relation: AwaitedRelation,
        resolved: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedStep {
        let Some(data) = self.graph().node_data(resolved) else {
            return AwaitedStep::Refused;
        };
        match data.as_ref() {
            SemanticNodeData::Object(surface) => {
                self.note_awaited_evidence(surface.positive_members().iter().map(|m| m.value));
                let thenability = self.surface_thenability(resolved, surface);
                drop(data);
                match thenability {
                    Thenability::NotThenable => AwaitedStep::Value(resolved),
                    // A single promised value is a tail step; several are
                    // the checker's union, each arm its own nested unwrap.
                    Thenability::Promised(values) => match values.as_slice() {
                        [single] => AwaitedStep::Next(*single),
                        _ => self.awaited_union_step(relation, &values, context),
                    },
                    Thenability::Malformed => AwaitedStep::Value(
                        self.graph()
                            .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Any)),
                    ),
                    Thenability::Undecided => AwaitedStep::Refused,
                }
            }
            SemanticNodeData::DeclRef { .. } | SemanticNodeData::InstantiationRef { .. } => {
                drop(data);
                let Some(body) = self.declaration_carrier_body(resolved) else {
                    return AwaitedStep::Refused;
                };
                self.note_awaited_evidence([body]);
                if self.same_node_payload(body, resolved) {
                    return AwaitedStep::Refused;
                }
                AwaitedStep::Expand {
                    carrier: resolved,
                    body,
                }
            }
            _ => AwaitedStep::Refused,
        }
    }

    /// Whether two node ids carry the same payload. Carriers minted in
    /// different scopes intern as different ids, so "the family gave the
    /// carrier back" is a payload comparison, not an id comparison.
    fn same_node_payload(&self, left: SemanticNodeId, right: SemanticNodeId) -> bool {
        left == right
            || matches!(
                (self.graph().node_data(left), self.graph().node_data(right)),
                (Some(left), Some(right)) if *left == *right
            )
    }

    construction_ordinal_seam! {
        /// Expand a declaration carrier ONE level through the shared
        /// `Instantiate` family — `None` for any other node or when the family
        /// produces no value. The carrier may come back unchanged (a carrier-stop
        /// or a deferred application); callers compare payloads.
        fn declaration_carrier_body(&self, carrier: SemanticNodeId) -> Option<SemanticNodeId> {
            match self
                .execute_read(self.declaration_carrier_key(carrier)?)
                .value
            {
                QueryResult::Value(body) => Some(body),
                _ => None,
            }
        }
    }

    /// The `Instantiate` key [`Self::declaration_carrier_body`] reads for a
    /// declaration carrier, or `None` for any other node. A runtime nominal
    /// the project declares (`Promise<T>`) reads the global declaration it
    /// refers to.
    fn declaration_carrier_key(&self, carrier: SemanticNodeId) -> Option<SemanticQueryKey> {
        let (identity, args) = match self.graph().node_data(carrier).as_deref() {
            Some(SemanticNodeData::DeclRef { identity }) => (
                identity.clone(),
                Arc::from(Vec::<SemanticNodeId>::new().into_boxed_slice()),
            ),
            Some(SemanticNodeData::InstantiationRef { base, args }) => {
                (base.clone(), Arc::clone(args.as_arc()))
            }
            _ => return None,
        };
        let identity = self
            .runtime_nominal_declaration(carrier, &identity)
            .unwrap_or(identity);
        let slot = self.type_slot_for(
            identity.canonical_id.clone(),
            identity.owner,
            identity.decl_name.clone(),
        );
        let context = self.instantiate_context_for(
            &identity.canonical_id,
            crate::semantic_query::ProjectionReductionContext::published(
                crate::semantic_query::ProjectionMode::Expanded,
            ),
        );
        Some(SemanticQueryKey::Instantiate(
            crate::semantic_query::InstantiateKey::new(slot, args, context),
        ))
    }

    /// Bind the lexical demand scope to `node`'s declaring file for one
    /// awaited protocol read, when nothing has bound a scope already.
    ///
    /// The protocol resolves apparent globals — a primitive's wrapper
    /// interface, a lib runtime nominal's `declare global` contributors —
    /// in the project owning the type's declaring file. Reached with no
    /// request canonical and no enclosing demand site (a direct relation
    /// execution), those lookups have no project to ask and refuse, turning
    /// a decidable protocol answer into a miss.
    fn awaited_demand_scope(
        &self,
        node: SemanticNodeId,
    ) -> Option<super::LexicalDemandScopeGuard<'_>> {
        if crate::request_context::current_request_canonical().is_some()
            || !self.lexical_demand_scope.borrow().is_empty()
        {
            return None;
        }
        match self.graph().node_scope(node) {
            Some(NodeScopeId::File { canonical_id, .. }) => Some(
                super::LexicalDemandScopeGuard::push(&self.lexical_demand_scope, canonical_id),
            ),
            _ => None,
        }
    }

    /// Record that the awaited protocol READ `nodes`: their declaring files
    /// join the relation's self-roots, so the entry's validity is a function
    /// of the reads it actually performed rather than of the operand alone.
    ///
    /// Today's operands transitively carry the content version of everything
    /// the protocol reaches through them, so this is defence in depth rather
    /// than the only rail holding cross-file invalidation up (which
    /// `awaited_result_follows_a_cross_file_then_edit_and_ignores_unrelated_ones`
    /// pins end to end). It is deliberately narrow — only the nodes a read
    /// returned — so it cannot degenerate into blanket invalidation.
    fn note_awaited_evidence(&self, nodes: impl IntoIterator<Item = SemanticNodeId>) {
        let roots = self.observed_self_roots_from_nodes(nodes);
        if !roots.is_empty() {
            self.deposit_operand_self_roots(&roots);
        }
    }

    /// Whether the operand may call a `then` signature that declares
    /// `receiver` as its `this`: the checker keeps only the `then`
    /// signatures whose `this` the operand is assignable to. `None` is an
    /// undecided judgement — never either answer.
    ///
    /// The judgement comes from the shared relation authority; a `void`
    /// receiver is the checker's "no receiver requirement".
    fn receiver_accepts_operand(
        &self,
        operand: SemanticNodeId,
        receiver: SemanticNodeId,
    ) -> Option<bool> {
        if matches!(
            self.graph().node_data(receiver).as_deref(),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Void))
        ) {
            return Some(true);
        }
        match self.execute_relate_pair(operand, receiver) {
            crate::project_semantic_dispatch::dispatch_txn::RelationStep::Assignable { .. } => {
                Some(true)
            }
            crate::project_semantic_dispatch::dispatch_txn::RelationStep::NotAssignable => {
                Some(false)
            }
            // An assumed SCC edge is not a published proof, and a budget or
            // deferred judgement is no fact at all.
            _ => None,
        }
    }

    /// The checker's RUNTIME thenable protocol over one object surface
    /// (`getPromisedTypeOfPromise` + `isThenableType`).
    ///
    /// No `then` member, or a `then` with no call signature (`then: number`),
    /// is not thenable. A `then` signature whose declared `this` the operand
    /// is not assignable to is dropped, and a `then` all of whose signatures
    /// are dropped that way is malformed — the checker reports
    /// "The 'this' context of type X is not assignable to method's 'this'"
    /// and types the await `any`. Otherwise the promised values are the
    /// union, over EVERY surviving `then` call signature, of the first
    /// parameter of every call signature of its `onfulfilled` callback
    /// (nullish callback arms removed; a parameterless callback promises
    /// `never`). A callable `then` that yields no promised value is
    /// malformed, and so is an OPTIONAL callable `then`: the checker finds
    /// no call signature on `then | undefined` (no promise) yet still calls
    /// the operand thenable. A union callback or a signature source that
    /// does not settle is undecided.
    ///
    /// Every signature and every argument position here is read through the
    /// shared discovery authority and the one positional model, so a union
    /// `then`, an intersection callback, an overload set and a global
    /// augmentation all decide the same way they do for any other consumer.
    fn surface_thenability(
        &self,
        operand: SemanticNodeId,
        surface: &crate::semantic_query::SurfaceView,
    ) -> Thenability {
        let thens = then_members(surface);
        if thens.is_empty() {
            return Thenability::NotThenable;
        }
        let _demand_scope = self.awaited_demand_scope(operand);
        let optional = thens.iter().any(|member| member.optional);
        let mut reads = Vec::new();
        for member in &thens {
            match self.shared_positional_reads(
                member.value,
                crate::semantic_query::SignatureKind::Call,
                0,
            ) {
                Ok(found) => reads.extend(found),
                Err(_) => return Thenability::Undecided,
            }
        }
        if reads.is_empty() {
            return Thenability::NotThenable;
        }
        if optional {
            return Thenability::Malformed;
        }
        let mut eligible = Vec::with_capacity(reads.len());
        for read in reads {
            match read.receiver {
                None => eligible.push(read.argument),
                Some(receiver) => match self.receiver_accepts_operand(operand, receiver) {
                    Some(true) => eligible.push(read.argument),
                    Some(false) => {}
                    None => return Thenability::Undecided,
                },
            }
        }
        // Every `then` signature rejected the operand's receiver: the
        // checker has no promise to adopt and types the await `any`.
        if eligible.is_empty() {
            return Thenability::Malformed;
        }
        let mut promised = Vec::new();
        for argument in eligible {
            let arms = match argument {
                // `then()` names no callback: it contributes no promised value.
                PositionalArgument::Absent => continue,
                PositionalArgument::Type {
                    non_nullish_arms, ..
                } => non_nullish_arms,
            };
            let callback = match arms.as_slice() {
                [] => continue,
                [single] => *single,
                _ => return Thenability::Undecided,
            };
            self.note_awaited_evidence([callback]);
            let callbacks = match self.shared_positional_reads(
                callback,
                crate::semantic_query::SignatureKind::Call,
                0,
            ) {
                Ok(found) => found,
                Err(_) => return Thenability::Undecided,
            };
            for read in callbacks {
                match read.argument {
                    PositionalArgument::Type { ty, .. } => promised.push(ty),
                    PositionalArgument::Absent => promised.push(
                        self.graph()
                            .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Never)),
                    ),
                }
            }
        }
        if promised.is_empty() {
            Thenability::Malformed
        } else {
            Thenability::Promised(promised)
        }
    }

    /// The single argument of an authored lib `Awaited<X>` carrier, by
    /// declaration identity (the `__builtin__` sentinel the shadowing gates
    /// mint for the unshadowed lib declaration), or `None`.
    fn lib_awaited_carrier_argument(&self, node: SemanticNodeId) -> Option<SemanticNodeId> {
        match self.graph().node_data(node).as_deref() {
            Some(SemanticNodeData::InstantiationRef { base, args })
                if args.len() == 1
                    && matches!(
                        self.builtin_sentinel_utility(base),
                        Some(BuiltinUtility::Awaited)
                    ) =>
            {
                Some(args[0])
            }
            _ => None,
        }
    }

    /// Whether the declaration an instantiation builds declares a
    /// conditional type as its body (through `Alias` wrappers): only then
    /// is its body applying the declaration again a step of the checker's
    /// tail loop. `None` when the body cannot be recovered — unknown, never
    /// evidence of a circular declaration. Read once per build.
    fn declares_conditional_body(&self, build: &mut InstantiateBuild) -> Option<bool> {
        if let Some(known) = build.conditional_body {
            return known;
        }
        let identity = crate::semantic_query::DeclIdentity {
            canonical_id: build.decl_canonical.clone(),
            owner: build.decl_owner,
            whole_hash: build.decl_whole_hash,
            decl_name: build.decl_name.clone(),
        };
        let known = match self.declared_alias_body(&identity) {
            Some(Some(body)) => Some(matches!(
                self.graph().node_data(body).as_deref(),
                Some(SemanticNodeData::Conditional { .. })
            )),
            Some(None) | None => None,
        };
        build.conditional_body = Some(known);
        known
    }

    /// The next arguments of this declaration's tail run, directly or
    /// through aliases that only forward their own bare parameters.
    /// Applications nested inside constructors and conditional alias bodies
    /// stay on the ordinary evaluation path, never a guessed tail edge.
    /// Eligibility is read only after a non-self application is found;
    /// ordinary aliases never scan the rest of their forwarding chain.
    fn conditional_tail_arguments(
        &self,
        result: SemanticNodeId,
        canonical: &verter_type_expr::OwnedStr,
        owner: verter_type_expr::TopLevelOwnerId,
        name: &verter_type_expr::OwnedStr,
        forwarding_allowed: impl FnOnce() -> bool,
    ) -> Option<Arc<[SemanticNodeId]>> {
        let graph = self.graph();
        let reference = |node| match graph.node_data(node).as_deref() {
            Some(
                SemanticNodeData::InstantiationRef { .. }
                | SemanticNodeData::Opaque(QueryError::RecursiveRef { .. }),
            ) => self.raw_generic_reference(node),
            _ => None,
        };
        let (mut declaration, mut arguments) = reference(result)?;
        let mut seen = rustc_hash::FxHashSet::default();
        let mut forwarding_allowed = Some(forwarding_allowed);
        loop {
            if declaration.canonical_id == *canonical
                && declaration.owner == owner
                && declaration.decl_name == *name
            {
                return Some(arguments);
            }
            if let Some(allowed) = forwarding_allowed.take() {
                if !allowed() {
                    return None;
                }
            }
            if self.cancellation.is_cancelled() || !seen.insert(declaration.clone()) {
                return None;
            }
            let prepared = self.ctx.prepared_type_decl_return_only(
                declaration.canonical_id.as_ref(),
                declaration.owner,
                declaration.decl_name.as_ref(),
            )?;
            if prepared.kind != verter_session_query::declarations::TypeDeclKind::Alias {
                return None;
            }
            // A forwarding alias changes no type: `Wrap<T> = Grow<T>`
            // takes Grow's selected branch back to Grow with the same
            // arguments. Read only that declared application, never
            // evaluate another conditional or descend into a constructor.
            let body = self.declared_alias_body(&declaration)??;
            let (next, parameters) = reference(body)?;
            let forwarded = parameters
                .iter()
                .map(|parameter| match graph.node_data(*parameter).as_deref() {
                    Some(SemanticNodeData::TypeParam {
                        decl, param_index, ..
                    }) if decl.canonical_id == declaration.canonical_id
                        && decl.owner == declaration.owner
                        && decl.decl_name == declaration.decl_name =>
                    {
                        arguments.get(usize::from(*param_index)).copied()
                    }
                    _ => None,
                })
                .collect::<Option<Vec<_>>>()?;
            declaration = next;
            arguments = forwarded.into();
        }
    }

    /// The authored lib `Awaited<X>` application over `argument`, as the
    /// syntax-preserving `__builtin__` carrier.
    fn lib_awaited_carrier(&self, argument: SemanticNodeId) -> SemanticNodeId {
        self.graph()
            .intern_node(SemanticNodeData::InstantiationRef {
                base: crate::semantic_query::DeclIdentity {
                    canonical_id: verter_type_expr::OwnedStr::from("__builtin__"),
                    owner: verter_type_expr::TopLevelOwnerId::ordinary_file(),
                    whole_hash: crate::semantic_query::HashValue::default(),
                    decl_name: verter_type_expr::OwnedStr::from("Awaited"),
                },
                args: crate::semantic_query::PayloadArray::from(vec![argument].into_boxed_slice()),
            })
    }

    /// Read the lib `Awaited<X>` over `argument` through the `Instantiate`
    /// family (its memo, singleflight and cycle guard), classified:
    /// `Some(None)` when the application stays deferred, `Some(Some(node))`
    /// when it reduced, `None` on refusal.
    ///
    /// The conditional's own recursion is evaluated inside one root
    /// ([`Self::lib_awaited_node`]); this read is a root. When
    /// `Awaited<argument>` is a root whose evaluation is ALREADY in progress
    /// on this path, the conditional has come back to itself with the same
    /// argument: through exact steps it can never reach a value — a
    /// certified divergence: the checker reports TS2589 and continues with
    /// its error type, which dominates each union and branch on the way.
    /// That recovery is the answer, a complete one
    /// ([`Self::lib_awaited_recurs`]). The steps are every step since that
    /// application began, in its own frame and each frame built on top of
    /// it ([`Self::exact_steps_since`]), so a partial read anywhere on the
    /// cycle proves nothing.
    fn lib_awaited_read(&self, argument: SemanticNodeId) -> Option<Option<SemanticNodeId>> {
        let application = self.declaration_carrier_key(self.lib_awaited_carrier(argument))?;
        if self
            .graph()
            .is_same_path_claim_at(&application, self.checking_site.get())
        {
            return match self.lib_awaited_recurs(self.exact_steps_since(&application)) {
                LibAwaited::Reduced(recovery) => Some(Some(recovery)),
                _ => None,
            };
        }
        let body = match self.execute_read(application).value {
            QueryResult::Value(body) => body,
            _ => return None,
        };
        if self.lib_awaited_carrier_argument(body) == Some(argument) {
            return Some(None);
        }
        if matches!(
            self.graph().node_data(body).as_deref(),
            Some(SemanticNodeData::Opaque(QueryError::Miss))
        ) {
            return None;
        }
        Some(Some(body))
    }

    /// The lib `Awaited<T>` CONDITIONAL over `operand`, as the root of one
    /// evaluation:
    ///
    /// ```text
    /// type Awaited<T> = T extends null | undefined ? T
    ///   : T extends object & { then(onfulfilled: infer F, ...args: infer _): any }
    ///     ? F extends (value: infer V, ...args: infer _) => any ? Awaited<V> : never
    ///   : T;
    /// ```
    ///
    /// Deliberately NOT the compiler's runtime awaited relation: a callable
    /// `then` with no callable `onfulfilled` is `never` here (the runtime
    /// relation types it `any`), an OPTIONAL `then` does not satisfy the
    /// required `then(...)` so the operand is its own result (the runtime
    /// relation calls it malformed), and an overloaded `then` infers from its
    /// LAST signature (the runtime relation unions every signature).
    ///
    /// Distributes over a union (a union with a deferred arm defers whole);
    /// an open binder, a compiler-deferred awaited value, or a nested
    /// deferred application defers; a declaration carrier expands one level
    /// and keeps its identity when the result is the body itself.
    ///
    /// The conditional's recursion into `Awaited<V>` is evaluated the way
    /// the checker evaluates it and stops where the checker stops, counted
    /// by the checker compatibility policy: a tail run reaching Verter's
    /// tail budget, far past the checker's
    /// ([`ConditionalTail`](crate::semantic_query::checker_policy::ConditionalTail)),
    /// or a path reaching the checker's instantiation depth (the nested walk
    /// recurses natively, which that depth bounds)
    /// ([`INSTANTIATION_DEPTH`](crate::semantic_query::checker_policy::INSTANTIATION_DEPTH))
    /// is the TS2589 recovery, a resource partial. So, complete, is an
    /// application that recurs on its own path with the same argument: a
    /// certified divergence.
    fn lib_awaited_node(&self, operand: SemanticNodeId) -> LibAwaited {
        let mut walk = LibAwaitedWalk {
            depth: crate::semantic_query::checker_policy::InstantiationDepth::entered(
                LIB_AWAITED_ENTRY_DEPTH,
            ),
            path: Vec::new(),
            on_path: rustc_hash::FxHashSet::default(),
        };
        self.lib_awaited_run(operand, &mut walk, 0)
    }

    /// Exercise the library walk under the caller's build-local observations.
    #[cfg(any(test, feature = "test-support"))]
    pub fn lib_awaited_for_tests(&self, operand: SemanticNodeId) -> Option<SemanticNodeId> {
        match self.lib_awaited_node(operand) {
            LibAwaited::Reduced(node) => Some(node),
            LibAwaited::Deferred | LibAwaited::Refused => None,
        }
    }

    /// The lib conditional re-entering itself with an argument it is still
    /// evaluating on this path: the same application under the same
    /// context. Through `exact` steps that is a certified divergence, its
    /// TS2589 recovery a complete answer, kept. Without that witness — a
    /// step on the cycle read a partial, or the frame that began the
    /// application is not on this stack — it proves nothing: the
    /// cross-query application stops as a same-path partial, never kept.
    /// A local walk with an executable transition instead continues through
    /// `lib_awaited_resolved` under its work and depth allowances.
    fn lib_awaited_recurs(&self, exact: Option<ExactSteps>) -> LibAwaited {
        let Some(exact) = exact else {
            self.fold_local_partial_completeness(
                crate::semantic_query::PartialReasonSet::SAME_PATH_RECURSION,
            );
            return LibAwaited::Refused;
        };
        LibAwaited::Reduced(crate::semantic_query::checker_policy::divergence_recovery(
            self.graph(),
            crate::semantic_query::checker_policy::CertifiedDivergence::exact_recurrence(
                crate::semantic_query::CheckerDiagnosticOperation::LibAwaited,
                exact,
            ),
            None,
        ))
    }

    /// The TS2589 recovery of the lib conditional after `refusal`.
    fn lib_awaited_too_deep(
        &self,
        refusal: crate::semantic_query::checker_policy::OperationRefusal,
    ) -> SemanticNodeId {
        self.recover_at_operation_budget(refusal, None)
    }

    /// One TAIL RUN of the lib conditional from `operand`, entered with
    /// `tail_start` steps already counted: each application whose recursion
    /// is a single `Awaited<V>` over a non-union `V` continues the run, and
    /// the run fails at Verter's tail budget. Every step is charged to
    /// the connected-work budget, whose trip is a typed partial.
    fn lib_awaited_run(
        &self,
        operand: SemanticNodeId,
        walk: &mut LibAwaitedWalk,
        tail_start: u32,
    ) -> LibAwaited {
        let mark = walk.path.len();
        let mut current = operand;
        let mut tail = crate::semantic_query::checker_policy::ConditionalTail::resumed(tail_start);
        let result = loop {
            match self.lib_awaited_application(current, walk) {
                LibStep::Done(result) => break result,
                LibStep::Next(value) if self.settled_union_arms_of(value).is_some() => {
                    break self.lib_awaited_nested(value, walk, false);
                }
                LibStep::Next(value) => {
                    if let Err(refusal) = self.connected_demand.tail_step(
                        &mut tail,
                        crate::semantic_query::CheckerDiagnosticOperation::LibAwaited,
                    ) {
                        break LibAwaited::Reduced(self.lib_awaited_too_deep(refusal));
                    }
                    if let Err(reasons) = self.charge_connected_work() {
                        self.fold_local_partial_completeness(reasons);
                        break LibAwaited::Refused;
                    }
                    current = value;
                }
            }
        };
        for left in walk.path.drain(mark..) {
            walk.on_path.remove(&left);
        }
        result
    }

    /// A NESTED step to `Awaited<value>`: one through a callback union
    /// (`through_callback_union`), one into a union `value`, two for both.
    /// The path fails at the checker's instantiation depth. A union's arms each
    /// start a fresh tail run; a callback arm continues into a run the
    /// checker enters with one step already counted.
    fn lib_awaited_nested(
        &self,
        value: SemanticNodeId,
        walk: &mut LibAwaitedWalk,
        through_callback_union: bool,
    ) -> LibAwaited {
        let is_union = self.settled_union_arms_of(value).is_some();
        let steps = u32::from(through_callback_union) + u32::from(is_union);
        let within = walk.depth.enter(
            steps,
            crate::semantic_query::CheckerDiagnosticOperation::LibAwaited,
        );
        let result = if let Err(refusal) = within {
            LibAwaited::Reduced(self.lib_awaited_too_deep(refusal))
        } else if let Err(reasons) = self.charge_connected_work() {
            self.fold_local_partial_completeness(reasons);
            LibAwaited::Refused
        } else {
            self.lib_awaited_run(value, walk, if is_union { 0 } else { 1 })
        };
        walk.depth.leave(steps);
        result
    }

    /// One application of the lib conditional: its value, or the single
    /// `V` a tail step continues with.
    fn lib_awaited_application(
        &self,
        operand: SemanticNodeId,
        walk: &mut LibAwaitedWalk,
    ) -> LibStep {
        use crate::project_semantic_dispatch::absorb::SpecialKind;
        let resolved = self
            .evaluate_deferred_semantic_node_with_context(
                operand,
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
            .into_active_query_build_node(self);
        let resolved = self
            .self_reference_declaration(resolved)
            .unwrap_or(resolved);
        if let Some((kind, special)) = self.peek_special(resolved) {
            return LibStep::Done(match kind {
                SpecialKind::Any
                | SpecialKind::Never
                | SpecialKind::Unknown
                | SpecialKind::Error
                | SpecialKind::Wildcard => LibAwaited::Reduced(special),
            });
        }
        if self.settled_non_thenable(resolved) {
            return LibStep::Done(LibAwaited::Reduced(resolved));
        }
        if walk.on_path.contains(&resolved) {
            if let Some(exact) = self.exact_steps() {
                return LibStep::Done(self.lib_awaited_recurs(Some(exact)));
            }
            // No proof: evaluate the transition again. Tail transitions
            // remain charged by the run; synchronous carrier transitions
            // also need a depth rail, since they can recur without
            // returning a tail step to that run.
            let within = walk.depth.enter(
                1,
                crate::semantic_query::CheckerDiagnosticOperation::LibAwaited,
            );
            let result = if let Err(refusal) = within {
                LibStep::Done(LibAwaited::Reduced(self.lib_awaited_too_deep(refusal)))
            } else if let Err(reasons) = self.charge_connected_work() {
                self.fold_local_partial_completeness(reasons);
                LibStep::Done(LibAwaited::Refused)
            } else {
                self.lib_awaited_resolved(resolved, walk)
            };
            walk.depth.leave(1);
            return result;
        }
        walk.path.push(resolved);
        walk.on_path.insert(resolved);
        self.lib_awaited_resolved(resolved, walk)
    }

    /// Evaluate one resolved operand. Active membership belongs to the
    /// first run that entered it; a repeated transition adds no duplicate
    /// path entry that could remove an enclosing run's membership on exit.
    fn lib_awaited_resolved(&self, resolved: SemanticNodeId, walk: &mut LibAwaitedWalk) -> LibStep {
        let Some(data) = self.graph().node_data(resolved) else {
            return LibStep::Done(LibAwaited::Refused);
        };
        match data.as_ref() {
            SemanticNodeData::TypeParam { .. } | SemanticNodeData::IntrinsicApplication { .. } => {
                LibStep::Done(LibAwaited::Deferred)
            }
            SemanticNodeData::Union(members) => {
                let members = members.share();
                drop(data);
                let mut reduced = Vec::with_capacity(members.len());
                for member in members.iter() {
                    match self.lib_awaited_run(*member, walk, 0) {
                        LibAwaited::Reduced(node) => reduced.push(node),
                        other => return LibStep::Done(other),
                    }
                }
                LibStep::Done(LibAwaited::Reduced(
                    self.intern_normalized_union_or_intersection(&reduced, true),
                ))
            }
            // Verter's own `Promise<V>`, which no declaration of the project
            // describes: its `then`'s `onfulfilled` is the optional, nullable
            // `((value: V) => ...) | null | undefined`, a callback union. A
            // `Promise` the project declares is a reference to that
            // declaration and reads its `then` like any other carrier below.
            SemanticNodeData::InstantiationRef { base, args }
                if args.len() == 1
                    && self.is_promise_global_identity(base)
                    && self.runtime_nominal_declaration(resolved, base).is_none() =>
            {
                let value = args[0];
                drop(data);
                LibStep::Done(self.lib_awaited_nested(value, walk, true))
            }
            SemanticNodeData::InstantiationRef { .. }
                if self.lib_awaited_carrier_argument(resolved).is_some() =>
            {
                // A nested authored application: its own evaluation decides
                // the operand this one continues on; a deferred one keeps the
                // whole deferred.
                let inner = self
                    .lib_awaited_carrier_argument(resolved)
                    .expect("guarded by the arm");
                drop(data);
                match self.lib_awaited_read(inner) {
                    Some(Some(node)) => self.lib_awaited_application(node, walk),
                    Some(None) => LibStep::Done(LibAwaited::Deferred),
                    None => LibStep::Done(LibAwaited::Refused),
                }
            }
            SemanticNodeData::DeclRef { .. } | SemanticNodeData::InstantiationRef { .. } => {
                drop(data);
                let Some(body) = self.declaration_carrier_body(resolved) else {
                    return LibStep::Done(LibAwaited::Refused);
                };
                if self.same_node_payload(body, resolved) {
                    return LibStep::Done(LibAwaited::Refused);
                }
                match self.lib_awaited_application(body, walk) {
                    LibStep::Done(LibAwaited::Reduced(node)) if node == body => {
                        LibStep::Done(LibAwaited::Reduced(resolved))
                    }
                    step => step,
                }
            }
            SemanticNodeData::Object(surface) => {
                let outcome = self.lib_awaited_surface(resolved, surface, walk);
                drop(data);
                match outcome {
                    LibThen::NotMatched => LibStep::Done(LibAwaited::Reduced(resolved)),
                    LibThen::Result(node) => LibStep::Done(LibAwaited::Reduced(node)),
                    LibThen::Next(value) => LibStep::Next(value),
                    LibThen::Deferred => LibStep::Done(LibAwaited::Deferred),
                    LibThen::Refused => LibStep::Done(LibAwaited::Refused),
                }
            }
            _ => LibStep::Done(LibAwaited::Refused),
        }
    }

    /// `node`'s settled union arms, or `None` when it is not a union.
    /// Settles through the shared deferred evaluator first, so an alias
    /// carrier over a union answers as the union it denotes.
    fn settled_union_arms_of(&self, node: SemanticNodeId) -> Option<Vec<SemanticNodeId>> {
        let resolved = self
            .evaluate_deferred_semantic_node_with_context(
                node,
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
            .into_active_query_build_node(self);
        match self.graph().node_data(resolved).as_deref() {
            Some(SemanticNodeData::Union(members)) => Some(members.iter().copied().collect()),
            _ => None,
        }
    }

    /// The `F` the lib conditional infers from the `then` signatures of
    /// `sources` (an overloaded `then` is several surface members carrying
    /// one signature each, so they read as ONE source list): conditional
    /// inference from a signature source reads its LAST signature.
    ///
    /// The outer `None` is an incomplete read; the inner `None` is "no call
    /// signature at all", which does not satisfy the required member.
    fn lib_inferred_onfulfilled(
        &self,
        sources: &[SemanticNodeId],
    ) -> Option<Option<PositionalArgument>> {
        let mut reads = Vec::new();
        for source in sources {
            match self.shared_positional_reads(
                *source,
                crate::semantic_query::SignatureKind::Call,
                0,
            ) {
                Ok(found) => reads.extend(found),
                Err(_) => return None,
            }
        }
        Some(reads.pop().map(|read| read.argument))
    }

    /// The `object & { then(onfulfilled: infer F, ...) }` branch of the lib
    /// conditional over one object surface.
    ///
    /// Deliberately NOT the runtime protocol: this branch never filters a
    /// `then` signature by receiver eligibility (tsc 7.0.2 types
    /// `Awaited<{ y: 2; then(this: { x: 1 }, onfulfilled: (v: number) => void): void }>`
    /// as `number`, where awaiting the same value is `any`).
    ///
    /// A single callback `F` is the checker's tail recursion: its `V` is
    /// [`LibThen::Next`]. A callback UNION (several `then` sources, several
    /// callable arms, or a nullable or optional `onfulfilled`) distributes,
    /// each arm a nested step.
    fn lib_awaited_surface(
        &self,
        operand: SemanticNodeId,
        surface: &crate::semantic_query::SurfaceView,
        walk: &mut LibAwaitedWalk,
    ) -> LibThen {
        let thens = then_members(surface);
        // An absent or OPTIONAL `then` does not satisfy the required member.
        if thens.is_empty() || thens.iter().any(|member| member.optional) {
            return LibThen::NotMatched;
        }
        let _demand_scope = self.awaited_demand_scope(operand);
        self.note_awaited_evidence(thens.iter().map(|member| member.value));
        let never = self
            .graph()
            .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Never));
        let settled_then = |member: &crate::semantic_query::SurfaceMember| {
            self.evaluate_deferred_semantic_node_with_context(
                member.value,
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
            .into_active_query_build_node(self)
        };
        // A `then` typed by an open type parameter leaves the conditional's
        // check type generic: the application is unresolved, and neither
        // branch may be taken. The honest shell, never a guess either way.
        if thens.iter().any(|member| {
            matches!(
                self.graph().node_data(settled_then(member)).as_deref(),
                Some(SemanticNodeData::TypeParam { .. })
            )
        }) {
            return LibThen::Refused;
        }
        // A `then` typed `any` or `never` is assignable to the required
        // method but infers no `onfulfilled`: `F` is `unknown`, so `never`
        // (tsc 7.0.2: `Awaited<{ then: any }>` is `never`; `then: unknown`
        // is not assignable and leaves the operand).
        if thens.iter().any(|member| {
            matches!(
                self.graph().node_data(settled_then(member)).as_deref(),
                Some(SemanticNodeData::Primitive(
                    PrimitiveKind::Any | PrimitiveKind::Never
                ))
            )
        }) {
            return LibThen::Result(never);
        }
        // Inference from a UNION source collects one candidate per
        // constituent, so `then: A | B` infers `F` as the union of each
        // arm's first parameter and the distributed arm step below unions
        // their results (tsc 7.0.2). Only a single, genuinely union-typed
        // `then` takes that route; an overload set stays ONE source list
        // whose LAST signature infers.
        let then_sources: Vec<Vec<SemanticNodeId>> = match thens.as_slice() {
            [only] => match self.settled_union_arms_of(only.value) {
                Some(arms) => arms.iter().map(|arm| vec![*arm]).collect(),
                None => vec![vec![only.value]],
            },
            members => vec![members.iter().map(|member| member.value).collect()],
        };
        let single_source = then_sources.len() == 1;
        let mut results = Vec::new();
        for source in &then_sources {
            let Some(inferred) = self.lib_inferred_onfulfilled(source) else {
                return LibThen::Refused;
            };
            let (onfulfilled, callback_union) = match inferred {
                Some(PositionalArgument::Type {
                    ty,
                    non_nullish_arms,
                    includes_undefined,
                }) => {
                    let callback_union = !single_source
                        || includes_undefined
                        || non_nullish_arms.len() != 1
                        || self.settled_union_arms_of(ty).is_some();
                    (non_nullish_arms, callback_union)
                }
                // `infer F` over a missing parameter is `unknown`, which is
                // not a function: `never`.
                Some(PositionalArgument::Absent) => return LibThen::Result(never),
                // No call signature: the required member is not matched.
                None => return LibThen::NotMatched,
            };
            // `F extends (value: infer V, ...) => any` distributes over `F`:
            // a nullish or non-callable arm contributes `never`. An `any` arm
            // takes BOTH branches with `V` inferred as `unknown`, so it
            // contributes `Awaited<unknown>` (tsc 7.0.2:
            // `then(onfulfilled: any)` is `unknown`).
            for arm in onfulfilled {
                let value = if matches!(
                    self.graph().node_data(arm).as_deref(),
                    Some(SemanticNodeData::Primitive(PrimitiveKind::Any))
                ) {
                    self.graph()
                        .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Unknown))
                } else {
                    self.note_awaited_evidence([arm]);
                    let callbacks = match self.shared_positional_reads(
                        arm,
                        crate::semantic_query::SignatureKind::Call,
                        0,
                    ) {
                        Ok(found) => found,
                        Err(_) => return LibThen::Refused,
                    };
                    let Some(callback) = callbacks.last() else {
                        continue;
                    };
                    match &callback.argument {
                        PositionalArgument::Type { ty, .. } => *ty,
                        PositionalArgument::Absent => self
                            .graph()
                            .intern_node(SemanticNodeData::Primitive(PrimitiveKind::Unknown)),
                    }
                };
                if !callback_union {
                    return LibThen::Next(value);
                }
                match self.lib_awaited_nested(value, walk, true) {
                    LibAwaited::Reduced(node) => results.push(node),
                    LibAwaited::Deferred => return LibThen::Deferred,
                    LibAwaited::Refused => return LibThen::Refused,
                }
            }
        }
        LibThen::Result(match results.as_slice() {
            [] => never,
            [single] => *single,
            _ => self.intern_normalized_union_or_intersection(&results, true),
        })
    }

    /// Whether an awaited type parameter must stay the deferred `Awaited<T>`
    /// — the checker's `isAwaitedTypeNeeded` over the parameter's constraint.
    /// Needed for no constraint, an `any` / `unknown` / empty-object /
    /// `object` constraint, or one that is not provably its own awaited type
    /// (a thenable, or undecidable); not needed when awaiting the constraint
    /// gives the constraint back (`string`, `{ p: string }`, `Plain`,
    /// `number | Plain`).
    fn awaited_type_parameter_needs_deferral(
        &self,
        constraint: Option<SemanticNodeId>,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> bool {
        let Some(bound) = constraint else {
            return true;
        };
        let bound = self
            .evaluate_deferred_semantic_node_with_context(
                bound,
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
            )
            .into_active_query_build_node(self);
        let empty_or_top = match self.graph().node_data(bound).as_deref() {
            Some(SemanticNodeData::Primitive(
                PrimitiveKind::Any | PrimitiveKind::Unknown | PrimitiveKind::Object,
            )) => true,
            Some(SemanticNodeData::Object(surface)) => {
                surface.positive_members().is_empty()
                    && surface.call_signatures.is_empty()
                    && surface.construct_signatures.is_empty()
                    && surface.index_signatures.is_empty()
            }
            _ => false,
        };
        if empty_or_top {
            return true;
        }
        // The checker asks whether SOME constituent is thenable, so a union
        // is decided arm by arm rather than by re-normalizing the whole.
        let arms: Vec<SemanticNodeId> = match self.graph().node_data(bound).as_deref() {
            Some(SemanticNodeData::Union(members)) => members.iter().copied().collect(),
            _ => vec![bound],
        };
        arms.into_iter().any(|arm| {
            !matches!(
                self.awaited_relation_step(AwaitedRelation::Normalize, arm, context),
                AwaitedOutcome::Value(node) if node == arm
            )
        })
    }

    /// The awaited-type normalization — the LIVE producer for
    /// [`SemanticQueryKey::AwaitedNormalize`]. See that variant for the full
    /// per-shape contract and the tsc 7.0.2 rows it is measured against.
    ///
    /// An honest refusal is `QueryResult::Error(QueryError::Miss)`, which is
    /// never warm-published — a `then` shape the protocol reader cannot
    /// enumerate, a carrier that does not expand, or an arm whose own family
    /// read refused, all land there rather than fabricating a passthrough.
    pub(super) fn build_awaited_normalize(
        &self,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        self.graph().record_awaited_normalize();
        let reduced = self.awaited_relation_run(AwaitedRelation::Normalize, operand, context);
        self.awaited_relation_output(AwaitedRelation::Normalize, operand, reduced)
    }

    fn awaited_normalize_node(
        &self,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedStep {
        let (resolved, decided) = self.awaited_operand_prelude(operand);
        if let Some(node) = decided {
            return AwaitedStep::Value(node);
        }
        let Some(data) = self.graph().node_data(resolved) else {
            return AwaitedStep::Refused;
        };
        match data.as_ref() {
            // `Promise<V>` — recognised by RESOLVED declaration identity
            // through the registry, never by spelling — unwraps its payload:
            // a tail step of this relation's run.
            SemanticNodeData::InstantiationRef { base, args }
                if args.len() == 1 && self.is_promise_global_identity(base) =>
            {
                AwaitedStep::Next(args[0])
            }
            // Union distribution: every arm re-enters the family and the
            // results renormalise canonically.
            SemanticNodeData::Union(members) => {
                let members = members.share();
                drop(data);
                self.awaited_union_step(AwaitedRelation::Normalize, &members, context)
            }
            // A type parameter whose constraint is provably its own awaited
            // type is its own awaited type; every other open parameter is the
            // canonical deferred intrinsic — a settled symbolic value, not a
            // refusal.
            SemanticNodeData::TypeParam { constraint, .. } => {
                let constraint = *constraint;
                drop(data);
                if self.awaited_type_parameter_needs_deferral(constraint, context) {
                    AwaitedStep::Value(self.deferred_awaited(resolved))
                } else {
                    AwaitedStep::Value(resolved)
                }
            }
            // The awaited operation is idempotent: awaiting a deferred
            // `Awaited<T>` gives it back.
            SemanticNodeData::IntrinsicApplication {
                op: crate::semantic_query::CompilerIntrinsicTypeOp::Awaited,
                ..
            } => AwaitedStep::Value(resolved),
            // An authored lib `Awaited<X>` (by declaration identity): the lib
            // conditional decides it first; a deferred application is
            // already an awaited type (the checker's
            // `isAwaitedTypeInstantiation`), a reduced one is awaited again.
            SemanticNodeData::InstantiationRef { .. }
                if self.lib_awaited_carrier_argument(resolved).is_some() =>
            {
                let argument = self
                    .lib_awaited_carrier_argument(resolved)
                    .expect("guarded by the arm");
                drop(data);
                match self.lib_awaited_read(argument) {
                    None => AwaitedStep::Refused,
                    Some(None) => AwaitedStep::Value(resolved),
                    Some(Some(reduced)) => AwaitedStep::Next(reduced),
                }
            }
            // Object surfaces and declaration carriers follow the shared
            // thenable protocol; conditionals, intersections, mapped
            // carriers and infer shells refuse honestly.
            _ => {
                drop(data);
                self.awaited_structural_node(AwaitedRelation::Normalize, resolved, context)
            }
        }
    }

    /// The async-function return payload — the LIVE producer for
    /// [`SemanticQueryKey::AsyncReturnPayload`].
    ///
    /// The ONE shape where this deliberately disagrees with
    /// [`Self::build_awaited_normalize`] is a naked type parameter, which is
    /// its own payload whatever its constraint. That disagreement is the
    /// architecture: `async f<T>(v: T)` publishes `Promise<T>`, so
    /// instantiating `T` with `Promise<string>` genuinely nests.
    pub(super) fn build_async_return_payload(
        &self,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        self.graph().record_async_return_payload();
        let reduced = self.awaited_relation_run(AwaitedRelation::Payload, operand, context);
        self.awaited_relation_output(AwaitedRelation::Payload, operand, reduced)
    }

    fn async_return_payload_node(
        &self,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> AwaitedStep {
        let (resolved, decided) = self.awaited_operand_prelude(operand);
        if let Some(node) = decided {
            return AwaitedStep::Value(node);
        }
        let Some(data) = self.graph().node_data(resolved) else {
            return AwaitedStep::Refused;
        };
        match data.as_ref() {
            // THE DISCRIMINATOR. A naked type parameter is its own payload
            // REGARDLESS of constraint — no constraint test here, deliberately.
            SemanticNodeData::TypeParam { .. } => {
                drop(data);
                AwaitedStep::Value(resolved)
            }
            // An awaited operand contributes NOTHING to the published
            // payload: measured on tsc 7.0.2, `async f<T>(v: T) { return await
            // v }` is `Promise<T>`, and so is `async f<T>(v: Awaited<T>) {
            // return v }` — the wrapper strips whether it came from an `await`
            // expression or was authored, and whatever the constraint.
            //
            // Top level ONLY. `async f<T>(v: Array<Awaited<T>>)` is
            // `Promise<Awaited<T>[]>`, so stripping must not reach under a type
            // constructor — it does not, because an array operand settles in
            // the prelude and never reaches this arm. And a SYNC function does
            // not strip at all (`g8` returns `Awaited<T>`), which is why this
            // belongs to the publication relation rather than to a general
            // `Awaited` simplifier.
            SemanticNodeData::IntrinsicApplication { op, args }
                if matches!(op, crate::semantic_query::CompilerIntrinsicTypeOp::Awaited)
                    && args.len() == 1 =>
            {
                AwaitedStep::Next(args[0])
            }
            // An authored lib `Awaited<X>` at the TOP of the payload arrives as
            // the syntax-preserving `__builtin__` carrier, recognised by
            // declaration identity. The lib conditional decides it first: a
            // reduced application (`Awaited<{ then(): void }>` is `never`) is
            // the payload's operand; a deferred one (`Awaited<T>`) strips to
            // its argument, whatever the constraint (tsc 7.0.2:
            // `async f<T extends Promise<string>>(v: Awaited<T>)` is
            // `Promise<T>`, and `Awaited<Awaited<T>>` strips twice). Only this
            // top-level carrier is read: `Awaited<T>[]` settles in the prelude
            // and keeps its authored representation.
            SemanticNodeData::InstantiationRef { .. }
                if self.lib_awaited_carrier_argument(resolved).is_some() =>
            {
                let argument = self
                    .lib_awaited_carrier_argument(resolved)
                    .expect("guarded by the arm");
                drop(data);
                match self.lib_awaited_read(argument) {
                    None => AwaitedStep::Refused,
                    Some(None) => AwaitedStep::Next(argument),
                    Some(Some(reduced)) => AwaitedStep::Next(reduced),
                }
            }
            SemanticNodeData::InstantiationRef { base, args }
                if args.len() == 1 && self.is_promise_global_identity(base) =>
            {
                AwaitedStep::Next(args[0])
            }
            SemanticNodeData::Union(members) => {
                let members = members.share();
                drop(data);
                self.awaited_union_step(AwaitedRelation::Payload, &members, context)
            }
            _ => {
                drop(data);
                self.awaited_structural_node(AwaitedRelation::Payload, resolved, context)
            }
        }
    }

    /// Shared output shape for both relations: the reduced node rooted on the
    /// operand's file-derived version; for a TS1062 failure, the checker's
    /// error type the operation continues with, carrying that diagnostic;
    /// otherwise a non-admitting honest refusal.
    fn awaited_relation_output(
        &self,
        relation: AwaitedRelation,
        operand: SemanticNodeId,
        reduced: AwaitedOutcome,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let observed_self_roots = self.observed_self_roots_from_nodes([operand]);
        let result = match reduced {
            AwaitedOutcome::Value(node) => QueryResult::Value(node),
            AwaitedOutcome::Failed => {
                QueryResult::Value(self.checker_recovery(relation.recursion_diagnostic()))
            }
            AwaitedOutcome::Refused => QueryResult::Error(QueryError::Miss),
        };
        let output: crate::project_semantic_dispatch::walk::QueryBuildOutput =
            (result, self.project_generation_signature()).into();
        output.with_observed_self_roots(observed_self_roots)
    }

    /// Production constructor for the env-bearing
    /// [`StructuralReduceContext`](crate::semantic_query::StructuralReduceContext)
    /// both awaited relations carry. Neither key has a decl slot; the
    /// already-lowered operand carries the content roots, so the context
    /// carries ONLY the R/T/L/J environment (R21). No content/version hash
    /// enters the query-identity key (R6).
    pub fn structural_reduce_context(&self) -> crate::semantic_query::StructuralReduceContext {
        let env = self.request_view_env_hashes();
        crate::semantic_query::StructuralReduceContext {
            resolve_env_hash: env.resolve_env_hash,
            type_env_hash: env.type_env_hash,
            lib_env_hash: env.lib_env_hash,
            project_identity: self.request_view_project_identity().fold_u32(),
        }
    }
    /// Production constructor for the env-bearing
    /// [`TemplateLiteralReduceContext`](crate::semantic_query::TemplateLiteralReduceContext).
    /// The key has no decl slot; the already-lowered arg nodes carry the
    /// content roots, so the context carries ONLY the R/T/L/J environment
    /// (R21). No content/version hash enters the query-identity key (R6).
    pub fn template_literal_reduce_context(
        &self,
    ) -> crate::semantic_query::TemplateLiteralReduceContext {
        let env = self.request_view_env_hashes();
        crate::semantic_query::TemplateLiteralReduceContext {
            resolve_env_hash: env.resolve_env_hash,
            type_env_hash: env.type_env_hash,
            lib_env_hash: env.lib_env_hash,
            project_identity: self.request_view_project_identity().fold_u32(),
        }
    }

    /// The ONE shared template-literal reduction helper (typed-IR only) —
    /// the checker's `getTemplateLiteralType`. Every interpolated
    /// expression is read where it is written
    /// ([`Self::settle_string_operand`]: an alias, a settled `keyof`, an
    /// intersection) and the template distributes over each union among
    /// them, forming the CARTESIAN PRODUCT of their constituents:
    ///
    /// - a literal (string, number, boolean, bigint) and `null` /
    ///   `undefined` contribute their text, and `boolean` its two;
    /// - `string`, `number`, `bigint`, `any`, a string mapping over one of
    ///   those and a nested template literal type stay HOLES, so
    ///   `` `k${keyof Rec}` `` over `Rec`'s string index signature is
    ///   `` `k${string}` | `k${number}` ``; a hole alone is itself when
    ///   it is `string` or a string mapping;
    /// - an all-text product is a `Literal` string, an empty product
    ///   (some expression resolved to `never`) is `never`;
    /// - any other expression — an open binder, a generic `keyof` —
    ///   carrier-stops to the authored `TemplateLiteral` shell (the caller
    ///   re-dispatches once it resolves).
    ///
    /// The product is the checker's (`checkCrossProductUnion`), weighed on
    /// the expressions' distinct constituent counts before any
    /// concatenation is built: at the limit the template is its TS2590
    /// recovery, a resource partial holding the authored template as its
    /// origin. Below it every concatenation built is charged to the
    /// connected-work ledger; a refused construction is `Err` with the
    /// ledger's trip, folded into the build's completeness.
    ///
    /// The multi-result case renormalises through
    /// [`SemanticQueryKey::ReduceUnion`] so the union is canonical. Used by
    /// [`Self::build_template_literal_reduce`] (the live query producer); the
    /// deferred evaluator's `TemplateLiteral` arm and the mapped key-remap path
    /// both reach this helper THROUGH that query, never a second walker.
    pub(super) fn reduce_template_literal_nodes(
        &self,
        quasis: &[OwnedStr],
        args: &[SemanticNodeId],
        eval_context: crate::semantic_query::ProjectionReductionContext,
    ) -> Result<SemanticNodeId, crate::semantic_query::PartialReasonSet> {
        let graph = self.graph();
        let spliced = self.spliced_template(quasis, args);
        let (quasis, args): (&[OwnedStr], &[SemanticNodeId]) = match &spliced {
            Some((quasis, args)) => (quasis, args),
            None => (quasis, args),
        };
        let authored = || {
            graph.intern_node(SemanticNodeData::TemplateLiteral {
                quasis: verter_type_expr::OwnedSlice::from(quasis),
                expressions: crate::semantic_query::PayloadArray::from(
                    args.to_vec().into_boxed_slice(),
                ),
            })
        };
        let plan = match self.template_plan(quasis, args, eval_context) {
            TemplateSpans::Plan(plan) => plan,
            // An open template keeps its open holes; its literal holes fold
            // into its text as the checker's construction folds them.
            TemplateSpans::Open => {
                return Ok(match self.folded_literal_holes(quasis, args) {
                    Some((quasis, args)) => graph.intern_node(SemanticNodeData::TemplateLiteral {
                        quasis: verter_type_expr::OwnedSlice::from(quasis.as_slice()),
                        expressions: crate::semantic_query::PayloadArray::from(
                            args.into_boxed_slice(),
                        ),
                    }),
                    None => authored(),
                })
            }
            TemplateSpans::TooComplex(refusal) => {
                return Ok(self.recover_at_operation_budget(refusal, Some(authored())));
            }
            TemplateSpans::Exhausted(reasons) => {
                self.fold_local_partial_completeness(reasons);
                return Err(reasons);
            }
            // An interpolant that is neither a literal nor a placeholder
            // type (an enum member whose value is not a constant) makes the
            // whole template `string`, as the checker's template
            // construction does.
            TemplateSpans::AnyString => {
                return Ok(graph.intern_node(SemanticNodeData::Primitive(PrimitiveKind::String)))
            }
        };
        // Every concatenation interns one derived node: the work and the
        // bytes of all of them are charged, from the factored plan, before
        // the first is built.
        if let Err(reasons) = self.charge_template_product(&plan) {
            self.fold_local_partial_completeness(reasons);
            return Err(reasons);
        }
        // The charge above refused any product whose count overflows.
        let mut members: Vec<SemanticNodeId> = Vec::with_capacity(
            plan.cardinality()
                .expect("an admitted template product's cardinality fits a usize"),
        );
        let mut cursor = plan.cursor();
        while let Some(concatenation) = cursor.next_concatenation() {
            members.push(self.template_type_from_concatenation(concatenation));
        }
        drop(plan);
        Ok(match members.as_slice() {
            [] => graph.intern_node(SemanticNodeData::Primitive(PrimitiveKind::Never)),
            [single] => *single,
            _ => {
                let read = self.execute_read(SemanticQueryKey::ReduceUnion {
                    members: Arc::from(members.into_boxed_slice()),
                    nullability: verter_session_query::flow::policy::NullabilityPolicy::Strict,
                });
                match read.value {
                    QueryResult::Value(id) => id,
                    _ => authored(),
                }
            }
        })
    }

    /// The texts and holes of a template of `quasis` and `args` with every
    /// hole that is itself a template literal type spliced in — the
    /// checker's template construction adds such a hole's texts and types
    /// to its own (`getTemplateLiteralType`), so `` `a${`b${T}`}` `` is
    /// `` `ab${T}` ``. A nest of template literal types splices from an
    /// explicit stack, never a reduction per level. None when no hole is a
    /// template literal type.
    fn spliced_template(
        &self,
        quasis: &[OwnedStr],
        args: &[SemanticNodeId],
    ) -> Option<(Vec<OwnedStr>, Vec<SemanticNodeId>)> {
        let graph = self.graph();
        let nested = |arg: SemanticNodeId| match graph.node_data(arg).as_deref() {
            Some(SemanticNodeData::TemplateLiteral {
                quasis,
                expressions,
            }) => Some((quasis.clone(), Arc::clone(expressions.as_arc()))),
            _ => None,
        };
        if !args.iter().any(|arg| nested(*arg).is_some()) {
            return None;
        }
        let text = |quasis: &[OwnedStr], index: usize| {
            quasis
                .get(index)
                .map(|q| q.as_ref())
                .unwrap_or_default()
                .to_owned()
        };
        let mut texts: Vec<String> = vec![text(quasis, 0)];
        let mut holes: Vec<SemanticNodeId> = Vec::new();
        // Each template being spliced: its texts, its holes and its next hole.
        type Splicing = (
            verter_type_expr::OwnedSlice<OwnedStr>,
            Arc<[SemanticNodeId]>,
            usize,
        );
        let mut stack: Vec<Splicing> = vec![(
            verter_type_expr::OwnedSlice::from(quasis),
            Arc::from(args),
            0,
        )];
        while let Some((quasis, args, next)) = stack.last_mut() {
            let Some(&arg) = args.get(*next) else {
                stack.pop();
                // The enclosing template's text after the hole just spliced.
                if let Some((quasis, _, next)) = stack.last() {
                    let after = text(quasis, *next);
                    texts.last_mut().expect("a text").push_str(&after);
                }
                continue;
            };
            *next += 1;
            match nested(arg) {
                Some((inner_quasis, inner_args)) => {
                    let head = text(&inner_quasis, 0);
                    texts.last_mut().expect("a text").push_str(&head);
                    stack.push((inner_quasis, inner_args, 0));
                }
                None => {
                    holes.push(arg);
                    texts.push(text(quasis, *next));
                }
            }
        }
        Some((texts.into_iter().map(OwnedStr::from).collect(), holes))
    }

    /// The texts and holes of a template of `quasis` and `args` with every
    /// hole that is one literal type, `null` or `undefined` folded into the
    /// text around it — the checker's template construction folds such a
    /// hole whatever its other holes are (`getTemplateLiteralType`), so
    /// `` `${infer H}${D}${infer T}` `` with `D := "."` is
    /// `` `${infer H}.${infer T}` ``, the pattern an inference matches. None
    /// when no hole folds, or when every hole does: a closed template is the
    /// string its construction builds ([`Self::reduce_template_literal_nodes`]).
    pub(super) fn folded_literal_holes(
        &self,
        quasis: &[OwnedStr],
        args: &[SemanticNodeId],
    ) -> Option<(Vec<OwnedStr>, Vec<SemanticNodeId>)> {
        let graph = self.graph();
        let folded = |arg: SemanticNodeId| match graph.node_data(arg).as_deref() {
            Some(SemanticNodeData::Literal(value)) => Some(literal_value_template_text(value)),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Null)) => Some("null".to_owned()),
            Some(SemanticNodeData::Primitive(PrimitiveKind::Undefined)) => {
                Some("undefined".to_owned())
            }
            _ => None,
        };
        let text = |index: usize| quasis.get(index).map(|q| q.as_ref()).unwrap_or_default();
        let mut texts: Vec<String> = vec![text(0).to_owned()];
        let mut holes: Vec<SemanticNodeId> = Vec::with_capacity(args.len());
        for (index, &arg) in args.iter().enumerate() {
            match folded(arg) {
                Some(spelled) => {
                    let current = texts.last_mut().expect("a text");
                    current.push_str(&spelled);
                    current.push_str(text(index + 1));
                }
                None => {
                    holes.push(arg);
                    texts.push(text(index + 1).to_owned());
                }
            }
        }
        (!holes.is_empty() && holes.len() < args.len())
            .then(|| (texts.into_iter().map(OwnedStr::from).collect(), holes))
    }

    /// The factored product of a template of `quasis` and `args`: each
    /// expression's constituents ([`Self::template_arg_alternatives`]) as
    /// one span of a [`TemplatePlan`]. The product is weighed as the checker
    /// weighs it (`checkCrossProductUnion` over the spans' constituent
    /// counts) before anything is built: at the checker's limit it is TS2590.
    ///
    /// A `never` expression empties the product wherever it sits, so the
    /// template is `never` even when another expression is still open: the
    /// checker finds the empty span before it reads any other.
    fn template_plan(
        &self,
        quasis: &[OwnedStr],
        args: &[SemanticNodeId],
        eval_context: crate::semantic_query::ProjectionReductionContext,
    ) -> TemplateSpans {
        use crate::semantic_query::checker_policy::{cross_product_union, ProductFactor};
        let mut spans: Vec<Vec<TemplateConstituent>> = Vec::with_capacity(args.len());
        let mut stopped: Option<TemplateSpans> = None;
        for &arg in args {
            match self.template_arg_alternatives(arg, eval_context) {
                TemplateArgAlternatives::Finite(constituents) => spans.push(constituents),
                TemplateArgAlternatives::Stop(TemplateSpans::Exhausted(reasons)) => {
                    return TemplateSpans::Exhausted(reasons)
                }
                TemplateArgAlternatives::Stop(other) => {
                    stopped.get_or_insert(other);
                }
            }
        }
        let texts = (0..=args.len())
            .map(|index| quasis.get(index).map(|q| q.to_string()).unwrap_or_default())
            .collect();
        let plan = TemplatePlan::new(texts, spans);
        if plan.cardinality() == Some(0) {
            return TemplateSpans::Plan(plan);
        }
        if let Some(stopped) = stopped {
            return stopped;
        }
        let factors = plan.span_widths().map(|width| match width {
            0 => ProductFactor::Never,
            1 => ProductFactor::Single,
            width => ProductFactor::Union(width),
        });
        if let Err(refusal) = cross_product_union(
            factors,
            crate::semantic_query::CheckerDiagnosticOperation::TemplateLiteral,
        ) {
            return TemplateSpans::TooComplex(refusal);
        }
        TemplateSpans::Plan(plan)
    }

    /// Charge the construction of `plan`'s product to the connected-work
    /// ledger before any of it is built: one unit per concatenation and the
    /// bytes they hold. `Err` with the ledger's trip when it refuses.
    fn charge_template_product(
        &self,
        plan: &TemplatePlan,
    ) -> Result<(), crate::semantic_query::PartialReasonSet> {
        self.connected_demand
            .charge_units(plan.cardinality().unwrap_or(usize::MAX))?;
        self.connected_demand
            .reserve_bytes(plan.construction_bytes().unwrap_or(usize::MAX))
    }

    /// The constituents ONE interpolated expression contributes, each a
    /// sequence of pieces: its text for a literal (TS-stringified —
    /// `` `${1 | 2}` `` is `"1" | "2"`, a bigint its base-10 digits) and for
    /// `null` / `undefined`, both texts for `boolean`, nothing at all for
    /// `never` (an empty product factor), the distinct constituents of a
    /// union (the union the checker forms from them: a string literal a
    /// nested template forms again is one constituent, a number literal
    /// spelling the same text another), a nested template literal type's own
    /// concatenations, and a hole for `string` / `number` / `bigint` / `any`
    /// or a string mapping over one. A residual string-mapping application
    /// reduces first, so `` `on${Capitalize<K>}` `` folds once `K` is
    /// substituted. Every other shape leaves the template open.
    fn template_arg_alternatives(
        &self,
        arg: SemanticNodeId,
        eval_context: crate::semantic_query::ProjectionReductionContext,
    ) -> TemplateArgAlternatives {
        let graph = self.graph();
        let mut resolved = self.settle_string_operand(arg, eval_context);
        if let Some((intrinsic, operand)) = self.string_mapping_of(resolved) {
            resolved = self.apply_string_intrinsic(&intrinsic, operand, eval_context);
        }
        let text = |text: String, spelled: Option<SemanticNodeId>| {
            TemplateArgAlternatives::Finite(vec![TemplateConstituent {
                pieces: vec![TemplatePiece::Text(text)],
                spelled,
            }])
        };
        let data = graph.node_data(resolved);
        match data.as_deref() {
            Some(SemanticNodeData::Literal(value)) => text(
                literal_value_template_text(value),
                (!matches!(value, LiteralValue::String(_))).then_some(resolved),
            ),
            // An enum member interpolates as its value; a member whose
            // value is not a constant is no literal and spells any string.
            Some(SemanticNodeData::EnumLiteral(literal)) => {
                if super::canonical_algebra::enum_literal_is_unit(graph.store(), literal) {
                    let base = literal.base;
                    drop(data);
                    // The member is its own constituent, whatever its value.
                    match self.template_arg_alternatives(base, eval_context) {
                        TemplateArgAlternatives::Finite(constituents) => {
                            TemplateArgAlternatives::Finite(
                                constituents
                                    .into_iter()
                                    .map(|constituent| TemplateConstituent {
                                        spelled: Some(resolved),
                                        ..constituent
                                    })
                                    .collect(),
                            )
                        }
                        other => other,
                    }
                } else {
                    TemplateArgAlternatives::Stop(TemplateSpans::AnyString)
                }
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Never)) => {
                TemplateArgAlternatives::Finite(Vec::new())
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Null)) => {
                text("null".to_owned(), Some(resolved))
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Undefined)) => {
                text("undefined".to_owned(), Some(resolved))
            }
            Some(SemanticNodeData::Primitive(PrimitiveKind::Boolean)) => {
                TemplateArgAlternatives::Finite(
                    ["false", "true"]
                        .into_iter()
                        .map(|text| TemplateConstituent {
                            pieces: vec![TemplatePiece::Text(text.to_owned())],
                            spelled: Some(resolved),
                        })
                        .collect(),
                )
            }
            Some(SemanticNodeData::Union(members)) => {
                let members = members.members_arc();
                drop(data);
                // The span is the union the checker holds: its literal
                // reduction runs first (a pattern absorbs the literals it
                // matches).
                let reduced = self.intern_normalized_union(
                    &members,
                    verter_session_query::flow::policy::NullabilityPolicy::Strict,
                );
                let members: Arc<[SemanticNodeId]> = match graph.node_data(reduced).as_deref() {
                    Some(SemanticNodeData::Union(reduced)) => reduced.members_arc(),
                    _ => Arc::from(vec![reduced].into_boxed_slice()),
                };
                let mut out: Vec<TemplateConstituent> = Vec::new();
                let mut seen: FxHashSet<TemplateConstituent> = FxHashSet::default();
                for member in members.iter() {
                    match self.template_arg_alternatives(*member, eval_context) {
                        TemplateArgAlternatives::Finite(alternatives) => out.extend(
                            alternatives
                                .into_iter()
                                .filter(|alternative| seen.insert(alternative.clone())),
                        ),
                        other => return other,
                    }
                }
                TemplateArgAlternatives::Finite(out)
            }
            // A nested template literal type is the union of its own
            // concatenations, built as the checker builds that type: weighed
            // and charged as a product of its own, then streamed.
            Some(SemanticNodeData::TemplateLiteral {
                quasis,
                expressions,
            }) => {
                let (quasis, expressions) = (quasis.clone(), Arc::clone(expressions.as_arc()));
                drop(data);
                let plan = match self.template_plan(&quasis, &expressions, eval_context) {
                    TemplateSpans::Plan(plan) => plan,
                    other => return TemplateArgAlternatives::Stop(other),
                };
                if let Err(reasons) = self.charge_template_product(&plan) {
                    return TemplateArgAlternatives::Stop(TemplateSpans::Exhausted(reasons));
                }
                let mut cursor = plan.cursor();
                TemplateArgAlternatives::Finite(
                    std::iter::from_fn(|| cursor.next_constituent()).collect(),
                )
            }
            _ => {
                drop(data);
                if self.is_template_hole(resolved) {
                    TemplateArgAlternatives::Finite(vec![TemplateConstituent::string(vec![
                        TemplatePiece::Hole(resolved),
                    ])])
                } else {
                    TemplateArgAlternatives::Stop(TemplateSpans::Open)
                }
            }
        }
    }

    /// The type one distributed template concatenation denotes: adjacent
    /// texts join; with no hole it is the string literal; a lone hole with
    /// no text around it is the hole itself when that is `string` or a
    /// string mapping; otherwise the template literal type of its texts and
    /// holes.
    pub(super) fn template_type_from_pieces(&self, pieces: Vec<TemplatePiece>) -> SemanticNodeId {
        let mut concatenation = TemplateConcatenation {
            texts: vec![String::new()],
            holes: Vec::new(),
        };
        for piece in pieces {
            match piece {
                TemplatePiece::Text(text) => concatenation
                    .texts
                    .last_mut()
                    .expect("one text per hole plus one")
                    .push_str(&text),
                TemplatePiece::Hole(hole) => {
                    concatenation.holes.push(hole);
                    concatenation.texts.push(String::new());
                }
            }
        }
        self.template_type_from_concatenation(concatenation)
    }

    /// The type one built concatenation denotes (see
    /// [`Self::template_type_from_pieces`]). A concatenation with no hole
    /// moves its one text into the string literal it is.
    pub(super) fn template_type_from_concatenation(
        &self,
        concatenation: TemplateConcatenation,
    ) -> SemanticNodeId {
        let graph = self.graph();
        let TemplateConcatenation { mut texts, holes } = concatenation;
        if holes.is_empty() {
            let text = texts.pop().expect("one text per hole plus one");
            return graph.intern_node(SemanticNodeData::Literal(LiteralValue::String(text)));
        }
        // Every text empty and every hole `string`: the template is `string`
        // (`${string}${string}` spells any string).
        let is_string = |hole: &SemanticNodeId| {
            matches!(
                graph.node_data(*hole).as_deref(),
                Some(SemanticNodeData::Primitive(PrimitiveKind::String))
            )
        };
        if texts.iter().all(String::is_empty) && holes.iter().all(is_string) {
            return holes[0];
        }
        if let [hole] = holes.as_slice() {
            if texts.iter().all(String::is_empty)
                && (matches!(
                    graph.node_data(*hole).as_deref(),
                    Some(SemanticNodeData::Primitive(PrimitiveKind::String))
                ) || self.string_mapping_of(*hole).is_some())
            {
                return *hole;
            }
        }
        graph.intern_node(SemanticNodeData::TemplateLiteral {
            quasis: texts
                .into_iter()
                .map(|text| OwnedStr::from(text.as_str()))
                .collect(),
            expressions: crate::semantic_query::PayloadArray::from(holes.into_boxed_slice()),
        })
    }

    /// `ResolveMacroPayload` body.
    ///
    /// Resolve a Vue compiler macro's payload to a single
    /// `SemanticNodeId` representing the macro's effective TypeExpr.
    /// The `DefineEmits` / `DefineSlots` / `DefineModel` arms read the
    /// owner SFC's `AnalyzedMacro` sidecar (`macros.get(macro_index)`
    /// off the owner artifact's `script_analysis`) rather than
    /// re-walking the AST. The `owner` slot is the env-bearing,
    /// content-free `ResolvedDeclSlotIdentity` (R6) — its whole_hash is
    /// NOT in the key. At value-build time the owner's current content
    /// version is re-sourced live via
    /// `ensure_indexed_ready_serve(owner.defining_canonical)`; a real-file
    /// owner unknown to the live view is a stale key and the build is
    /// marked non-cacheable (`cache_suppress`) (see the arm body for
    /// the stale-key guard).
    ///
    /// Per-arm logic mirrors §3.2 body sketch:
    /// - `DefineProps` / `WithDefaults`: 0 args → `Opaque(Miss)`;
    ///   1 arg → arg unchanged; ≥2 args → `ReduceIntersection`.
    /// - `DefineEmits`: dispatch `type_args[0]` through `ProjectPath`
    ///   in the caller's mode. Returns the projected surface; the
    ///   consumer (`extract_component_meta` at
    ///   `verter_semantic/src/analysis/component_meta.rs:2449+`) walks
    ///   `properties` + `call_signatures` from the resulting
    ///   `Object`. Sidecar lookup confirms the macro exists and
    ///   anchors the dep_signature.
    /// - `DefineSlots`: dispatch `type_args[0]` through `ProjectPath`
    ///   in the caller's mode; consumer walks slot members from the
    ///   projected `Object`.
    /// - `DefineModel`: dispatch `type_args[0]` through `ProjectPath`
    ///   in the caller's mode; consumer constructs the
    ///   `{ <model_name>: T, "update:<model_name>": (val: T) -> void }`
    ///   shape from `analyzed.model_name` + the resolved T payload.
    /// - `DefineExpose` / `DefineOptions`: 0 args → `Opaque(Miss)`;
    ///   else `type_args[0]` unchanged.
    ///
    /// A real-file owner records `(owner.defining_canonical,
    /// WholeHash(<re-sourced live whole_hash>))` in the local fence so
    /// warm-hit revalidation against the live `StoreView` observes the
    /// macro's owning file generation. A non-file owner (the global /
    /// structural sentinel, a `__builtin__` carrier, or a `<synthetic>`
    /// test identity) records NO file whole_hash and roots its version
    /// entirely through its `type_args` nodes. Every arm additionally
    /// pins the project generation in the fence.
    ///
    /// **Recursion safety:** A self-reference like
    /// `type R = { next: R }; defineEmits<{ recurse: [R] }>()` reaches
    /// the same `Instantiate` key during projection of `R` and the
    /// dispatch sentinel emits `Opaque(QueryError::RecursiveRef)` —
    /// the projection path observes a `Recursive` `QueryResult`,
    /// which propagates here as `QueryResult::Recursive(node)`.
    pub(super) fn build_resolve_macro_payload(
        &self,
        owner: &crate::semantic_query::ResolvedDeclSlotIdentity,
        macro_index: usize,
        macro_kind: verter_session_query::analysis::types::AnalyzedMacroKind,
        type_args: &Arc<[SemanticNodeId]>,
        mode: ProjectionMode,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        match self.begin_resolve_macro_payload(owner, macro_index, macro_kind, type_args, mode) {
            MacroPayloadStep::Done(output) => *output,
            // A producer evaluated in place reads its payload operation in
            // place, as every nested read of a synchronous build is made.
            MacroPayloadStep::Need(build) => {
                let read = self.execute_read(build.payload().clone());
                self.finish_resolve_macro_payload(*build, read)
            }
        }
    }

    /// The first stage of a macro payload's resolution: the owning file's
    /// indexed input and the fence it seeds, then either the payload's value
    /// or the one payload operation the value is read from — the props
    /// intersection, or the emits / slots / model projection — retained with
    /// everything read so far for [`Self::finish_resolve_macro_payload`].
    pub(super) fn begin_resolve_macro_payload(
        &self,
        owner: &crate::semantic_query::ResolvedDeclSlotIdentity,
        macro_index: usize,
        macro_kind: verter_session_query::analysis::types::AnalyzedMacroKind,
        type_args: &Arc<[SemanticNodeId]>,
        mode: ProjectionMode,
    ) -> MacroPayloadStep {
        use verter_session_query::analysis::types::AnalyzedMacroKind;
        self.graph().record_macro_payload_owner_read();

        // R6 / R20: the key is content-free. Re-source the owning
        // SFC's content version from the live indexed view at
        // value-build time so the cached `MemoEntry` self-roots on
        // the current generation's whole_hash. Three classes of
        // non-file owner exist and must NOT invent a synthetic
        // `FileWholeHash` (mirrors the `build_instantiate` non-file
        // base rule):
        //  - the global / structural sentinel (`canonical_id == ""`);
        //  - built-in utility carriers (`canonical_id == "__builtin__"`);
        //  - synthetic test identities (`canonical_id == "<synthetic>"`).
        // These owners root self-version through their `type_args`
        // nodes only (no file fact in the fence or the self-root set).
        // A real-file owner whose `ensure_indexed_ready_serve` returns `None`
        // (the file is unknown to the live view) is a STALE KEY: the
        // build still hands the value to the caller but marks the
        // output non-cacheable (`cache_suppress`) rather than publishing
        // a result self-rooted on the sentinel hash `0`, which could
        // later serve stale.
        let owner_canonical_str = owner.defining_canonical.as_ref();
        let is_non_file_owner = crate::semantic_query::is_non_file_base(owner_canonical_str);
        let owner_indexed: Option<Arc<verter_session_query::inputs::indexed::IndexedInputRecord>> =
            if is_non_file_owner {
                None
            } else {
                self.ctx
                    .ensure_indexed_ready_serve(owner_canonical_str)
                    .map(|serve| serve.indexed)
            };
        // A real-file owner unknown to the live view is a stale key —
        // suppress admission so the next caller cold-recomputes.
        let stale_real_file_owner = !is_non_file_owner && owner_indexed.is_none();
        let owner_whole_hash: crate::semantic_query::HashValue = owner_indexed
            .as_ref()
            .map(|indexed| indexed.whole_hash)
            .unwrap_or_default();

        // Seed the local fence with the macro's owning canonical and
        // the re-sourced content version — but ONLY for a real-file
        // owner. A non-file owner has no `FileWholeHash` to root on;
        // recording `(non_file_canonical, 0)` would fabricate a content
        // version for a builtin/structural carrier. The non-file owner
        // roots entirely through its `type_args` (the same rule
        // `build_instantiate` applies to a non-file base).
        let mut local_fence: Vec<crate::semantic_query::DepEntry> = Vec::new();
        let owner_canonical =
            verter_session_query::retention::owned::OwnedStr::new(&owner.defining_canonical);
        if !is_non_file_owner {
            local_fence.push(crate::semantic_query::DepEntry(
                owner_canonical.clone(),
                crate::semantic_query::DepVersion::WholeHash(owner_whole_hash),
            ));
        }
        // Always pin the project-generation so the fence catches
        // workspace-wide changes that could invalidate the lowering
        // basis (mirrors `dep_signature_for` semantics).
        let project_gen = self.snapshot.current_project_generation();
        local_fence.push(crate::semantic_query::DepEntry(
            owner_canonical,
            crate::semantic_query::DepVersion::ProjectGeneration(project_gen),
        ));

        let rooting = MacroPayloadRooting {
            owner: owner.defining_canonical.clone(),
            is_non_file_owner,
            owner_whole_hash,
            stale_real_file_owner,
            type_args: Arc::clone(type_args),
        };
        let answered = |rooting, result, local_fence| {
            MacroPayloadStep::Done(Box::new(self.macro_payload_output(
                rooting,
                local_fence,
                result,
                false,
                false,
            )))
        };
        let payload = match macro_kind {
            AnalyzedMacroKind::DefineProps | AnalyzedMacroKind::WithDefaults => {
                // §3.2 sketch: 0 args → Miss; 1 arg → arg directly;
                // ≥2 args → intersection-normalised result.
                if type_args.is_empty() {
                    let miss = QueryResult::Value(self.opaque(QueryError::Miss));
                    return answered(rooting, miss, local_fence);
                }
                if type_args.len() == 1 {
                    return answered(rooting, QueryResult::Value(type_args[0]), local_fence);
                }
                SemanticQueryKey::reduce_intersection_operands(
                    self.graph().store(),
                    Arc::clone(type_args),
                )
            }
            AnalyzedMacroKind::DefineEmits
            | AnalyzedMacroKind::DefineSlots
            | AnalyzedMacroKind::DefineModel => {
                // Read the macro snapshot directly from the live
                // indexed view obtained at function entry.
                // Source-and-consistency: `owner_indexed` came from
                // `ensure_indexed_ready_serve` (the live view), and its
                // `whole_hash` already discriminates content versions
                // through the cached `MemoEntry`'s self-root rail. A
                // missing `IndexedReady` for a snapshot-consuming arm
                // is a stale key — refuse admission so the next
                // caller cold-recomputes. A missing `script_analysis`
                // on a present `IndexedReady` means the SFC carries no
                // macros — return Miss.
                let snapshot = match owner_indexed
                    .as_ref()
                    .and_then(|indexed| indexed.script_analysis.clone())
                {
                    Some(s) => s,
                    None => {
                        let mut out =
                            crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
                                QueryResult::Error(QueryError::Miss),
                                fence_to_dep_signature(local_fence),
                            ));
                        // Only suppress when the owner artifact is
                        // genuinely missing (stale key). A present
                        // `IndexedReady` with no macros yields the
                        // non-suppressing Miss above.
                        if owner_indexed.is_none() {
                            out.cache_suppress = true;
                        }
                        return MacroPayloadStep::Done(Box::new(out));
                    }
                };
                if snapshot.macros.get(macro_index).is_none() {
                    return MacroPayloadStep::Done(Box::new(
                        (
                            QueryResult::Error(QueryError::Miss),
                            fence_to_dep_signature(local_fence),
                        )
                            .into(),
                    ));
                }
                if type_args.is_empty() {
                    let miss = QueryResult::Value(self.opaque(QueryError::Miss));
                    return answered(rooting, miss, local_fence);
                }
                // Project the macro's first type argument through the
                // shared `ProjectPath` dispatcher in the caller's
                // mode. The consumer (component_meta extractor at
                // `verter_semantic/src/analysis/component_meta.rs:2449+`
                // for emits, the slot-bindings walker for slots, and
                // the model-name composer) walks the resulting
                // surface. Mode-aware so Navigate callers don't pay
                // for full member expansion.
                SemanticQueryKey::ProjectPath {
                    base: type_args[0],
                    path: verter_type_expr::OwnedSlice::from(
                        Vec::<PathSegment>::new().into_boxed_slice(),
                    ),
                    context: crate::semantic_query::ProjectionReductionContext::published(mode),
                }
            }
            AnalyzedMacroKind::DefineExpose | AnalyzedMacroKind::DefineOptions => {
                let result = if type_args.is_empty() {
                    QueryResult::Value(self.opaque(QueryError::Miss))
                } else {
                    QueryResult::Value(type_args[0])
                };
                return answered(rooting, result, local_fence);
            }
        };
        MacroPayloadStep::Need(Box::new(MacroPayloadBuild {
            rooting,
            local_fence,
            payload,
        }))
    }

    /// The last stage of a macro payload's resolution: the payload
    /// operation's read folded into what the first stage retained.
    ///
    /// Fold BOTH metadata signals from the nested macro-payload read:
    /// `cache_suppress` (inner-memo non-cacheability) and
    /// `result_is_partial` (budget/walker partial). A bare
    /// `read.value`-only extraction here would drop both via
    /// `QueryBuildOutput::from`'s default-false, letting a budget-tripped
    /// nested read's partial warm the component-meta result.
    pub(super) fn finish_resolve_macro_payload(
        &self,
        build: MacroPayloadBuild,
        read: crate::semantic_query::CacheRead<QueryResult<SemanticNodeId>>,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let MacroPayloadBuild {
            rooting,
            mut local_fence,
            ..
        } = build;
        crate::fact_signature_helpers::merge_dep_signature_into_local_fence(
            &mut local_fence,
            &read.dep_signature,
        );
        let partial = read.result_is_partial();
        self.macro_payload_output(
            rooting,
            local_fence,
            read.value,
            read.cache_suppress,
            partial,
        )
    }

    /// A macro payload's output: its value under the fence its stages
    /// recorded, rooted on the owning file and on every file its type
    /// arguments were lowered from, tainted by its payload operation's read.
    fn macro_payload_output(
        &self,
        rooting: MacroPayloadRooting,
        local_fence: Vec<crate::semantic_query::DepEntry>,
        result: QueryResult<SemanticNodeId>,
        nested_cache_suppress: bool,
        nested_result_is_partial: bool,
    ) -> crate::project_semantic_dispatch::walk::QueryBuildOutput {
        let MacroPayloadRooting {
            owner,
            is_non_file_owner,
            owner_whole_hash,
            stale_real_file_owner,
            type_args,
        } = rooting;
        // Self-version rooting: the macro payload was resolved from the
        // owning SFC's macro analysis at the re-sourced `owner_whole_hash`
        // AND from the `type_args` nodes — every arm derives its value
        // from `type_args` (returned directly for `DefineProps` /
        // `WithDefaults` 1-arg and `DefineExpose` / `DefineOptions`;
        // `ReduceIntersection`-normalised for the ≥2-arg props arms;
        // `ProjectPath`-projected for `DefineEmits` / `DefineSlots` /
        // `DefineModel`). When a type argument is file-derived from
        // another canonical the result transitively depends on that
        // file's content, so the carrier must self-root on it too.
        // Root the memo entry on the owning canonical AND on each
        // `NodeScopeId::File`-scoped `type_args` node's
        // `(canonical, observed_hash)` self-root so a content edit to the
        // SFC OR to any type argument's originating file misses the warm
        // read. Structural type args (`Global`-scoped primitives) and an
        // empty `type_args` set contribute nothing.
        //
        // Non-file owner fork: when the owner names no file (the
        // structural sentinel `""`, the builtin carrier `"__builtin__"`,
        // or the synthetic test sentinel `"<synthetic>"`), there is no
        // `FileWholeHash` to root on — `owner_whole_hash` is the default
        // sentinel `0`. Skip the file-side self-root in those cases and
        // rely entirely on the `type_args` self-roots (the same rule the
        // `build_instantiate` non-file base path applies).
        let mut observed_self_roots: Vec<crate::semantic_query_memo::ObservedGraphSelfRoot> =
            if is_non_file_owner {
                Vec::new()
            } else {
                vec![(owner, owner_whole_hash)]
            };
        for arg_root in self.observed_self_roots_from_nodes(type_args.iter().copied()) {
            if !observed_self_roots
                .iter()
                .any(|(c, h)| *c == arg_root.0 && *h == arg_root.1)
            {
                observed_self_roots.push(arg_root);
            }
        }
        let mut output = crate::project_semantic_dispatch::walk::QueryBuildOutput::from((
            result,
            fence_to_dep_signature(local_fence),
        ))
        .with_observed_self_roots(observed_self_roots);
        // Fold the nested macro-payload reads' metadata onto the build
        // output so a budget/walker partial in a nested
        // `ReduceIntersection` / `ProjectPath` read taints this macro
        // payload result (and suppresses the component-meta warm gate),
        // while a benign non-cacheable nested read still refuses inner-memo
        // admission without falsely marking this result partial.
        output.cache_suppress |= nested_cache_suppress;
        output.fold_partial(nested_result_is_partial);
        // Stale real-file owner: the key names a file unknown to the
        // live view (`ensure_indexed_ready_serve == None`). The value flows to
        // the caller, but the entry is non-cacheable — never publish a
        // result self-rooted on the sentinel hash `0`.
        if stale_real_file_owner {
            output.cache_suppress = true;
        }
        output
    }

    /// The dispatch-level canonical-composite funnel: every dispatch-context
    /// union / intersection CONSTRUCTION routes here, and this routes through
    /// the canonical algebra
    /// ([`canonical_algebra::intern_ordered_union`] /
    /// [`canonical_algebra::intern_ordered_intersection`]) — recursive flattening,
    /// lattice absorption, structural `T | T = T`, proven-disjoint scalar
    /// intersection collapse. The canonicalization's freshness evidence is
    /// deposited ambiently on the active cold-build taint frame
    /// ([`Self::deposit_canonical_evidence`]): inspected file self-roots
    /// (discarded duplicates included) reach the enclosing build's memo
    /// entry, and an `Incomplete` comparison folds `cache_suppress`
    /// (ReturnOnly — never a warm canonical result).
    ///
    /// A union built here runs the strict-null algebra: the type-level
    /// operations and projections that construct through this funnel are
    /// shared across projects and do not model `strictNullChecks`. A
    /// producer that answers under one project's policy — the flow-return
    /// evaluator or a published Expanded locator projection — constructs
    /// through [`Self::intern_normalized_union`] with that policy instead.
    /// The union an intersection of `arms` denotes when an arm is a union —
    /// the checker's distribution (`getIntersectionType`), even where the
    /// canonical construction keeps the written intersection as its printed
    /// origin. `None` when no arm is a union or the cross product is wider
    /// than the canonical distribution builds.
    pub(super) fn distributed_intersection(
        &self,
        arms: &[SemanticNodeId],
    ) -> Option<SemanticNodeId> {
        let mut evidence = super::canonical_algebra::CanonicalEvidence::default();
        let distributed = super::canonical_algebra::distribute_over_unions(
            self.graph(),
            arms,
            verter_session_query::flow::policy::NullabilityPolicy::Strict,
            super::canonical_algebra::DistributionOrigin::Distributed,
            self.construction_meter(),
            &mut evidence,
        );
        self.deposit_canonical_evidence(evidence);
        distributed
    }

    construction_ordinal_seam! {
        fn intern_normalized_union_or_intersection(
            &self,
            members: &[SemanticNodeId],
            is_union: bool,
        ) -> SemanticNodeId {
            if is_union {
                self.intern_normalized_union(
                    members,
                    verter_session_query::flow::policy::NullabilityPolicy::Strict,
                )
            } else {
                match self
                    .execute_read(
                        crate::semantic_query::SemanticQueryKey::reduce_intersection_operands(
                            self.graph().store(),
                            std::sync::Arc::from(members.to_vec().into_boxed_slice()),
                        ),
                    )
                    .value
                {
                    crate::semantic_query::QueryResult::Value(node) => node,
                    crate::semantic_query::QueryResult::Recursive(node) => node,
                    crate::semantic_query::QueryResult::Error(_) => {
                        let composite =
                            super::canonical_algebra::intern_ordered_intersection_charged(
                                self.graph(),
                                members,
                                self.construction_meter(),
                            );
                        self.deposit_canonical_evidence(composite.evidence);
                        composite.node
                    }
                }
            }
        }
    }

    construction_ordinal_seam! {
        /// The canonical union of `members` under `nullability` — the union
        /// half of [`Self::intern_normalized_union_or_intersection`] with the
        /// `null` / `undefined` algebra stated by the caller. Under
        /// [`NullabilityPolicy::Erased`](verter_session_query::flow::policy::NullabilityPolicy::Erased)
        /// the result carries no `null` / `undefined` member beside any other
        /// member, and its canonical stamp records the erased algebra.
        fn intern_normalized_union(
            &self,
            members: &[SemanticNodeId],
            nullability: verter_session_query::flow::policy::NullabilityPolicy,
        ) -> SemanticNodeId {
            let composite = super::canonical_algebra::intern_ordered_union_charged(
                self.graph(),
                members,
                nullability,
                self.construction_meter(),
            );
            self.deposit_canonical_evidence(composite.evidence);
            composite.node
        }
    }

    construction_ordinal_seam! {
        /// The type the checker constructs from a WRITTEN union
        /// (`getUnionType` over its arms) when that construction absorbs a
        /// literal: `"a" | string` is `string`, `1 | number | "x"` is
        /// `number | "x"`, `"a1" | `a${number}` | "ab"` is
        /// `"ab" | `a${number}``.
        ///
        /// An alias is transparent to that construction, so a named arm
        /// (`type A = "a"`) is resolved before absorption is decided: an arm
        /// resolving to a literal, primitive or pattern template stands for
        /// its resolution, and one resolving to a union contributes that
        /// union's arms, resolved the same way. Any other named arm stays
        /// written by its name. A canonical union is offered too: the
        /// canonical algebra keeps a named arm unresolved, so only its named
        /// arms can still absorb or be absorbed.
        ///
        /// `None` for any other node and for a written union with no literal
        /// beside a primitive or pattern template that could absorb it: such
        /// a union is not re-decided here and stays the authored display form
        /// in its written order (`"a" | "b" | never`, `A | "b"`).
        ///
        /// Otherwise the shared `ReduceUnion` query decides the resolved arms
        /// under `nullability`, the root file's `null` / `undefined`
        /// algebra, and the outcome is
        /// returned typed: the reduced type when it absorbed a literal, the
        /// written node itself when it absorbed none, and the reducer's (or a
        /// named arm's resolution) error or opaque result verbatim, for the
        /// caller to classify as a fault or a miss.
        fn reduced_written_union(
            &self,
            node: SemanticNodeId,
            nullability: verter_session_query::flow::policy::NullabilityPolicy,
        ) -> Option<QueryResult<SemanticNodeId>> {
            use crate::semantic_query::composite::CompositeOriginCategory as Category;
            let graph = self.graph();
            let arms = match graph.node_data(node)?.as_ref() {
                SemanticNodeData::Union(arms)
                    if matches!(
                        arms.origin_category(),
                        Category::AuthoredShell
                            | Category::PreservingRebuild
                            | Category::Canonical(_)
                            | Category::CanonicalUnproven
                    ) =>
                {
                    arms.members_arc()
                }
                _ => return None,
            };
            // A named arm: a declaration reference, an alias shell or a
            // declaration placeholder.
            let is_named = |arm: SemanticNodeId| {
                matches!(
                    graph.node_data(arm).as_deref(),
                    Some(
                        SemanticNodeData::DeclRef { .. }
                            | SemanticNodeData::Alias(_)
                            | SemanticNodeData::Opaque(crate::semantic_query::QueryError::DeclPlaceholder { .. })
                    )
                )
            };
            // The arm a named arm stands for when deciding absorption: its
            // resolution through the whole alias chain, unless that is
            // neither a union nor a literal, primitive or pattern template. A
            // chain is finite, as the declarations it names are; one that
            // comes back to a node it already passed is a recursive alias,
            // which stays written by its name. A resolution that fails is
            // returned for the caller to classify.
            let resolve_named = |arm: SemanticNodeId| -> Result<SemanticNodeId, QueryResult<SemanticNodeId>> {
                let mut resolved = arm;
                let mut passed: FxHashSet<SemanticNodeId> = FxHashSet::default();
                loop {
                    if !passed.insert(resolved) {
                        return Ok(arm);
                    }
                    let key = match graph.node_data(resolved).as_deref() {
                        Some(SemanticNodeData::Alias(inner)) => {
                            resolved = *inner;
                            continue;
                        }
                        Some(SemanticNodeData::DeclRef { identity }) => {
                            SemanticQueryKey::ResolveDecl(super::resolve_decl_key(
                                &identity.canonical_id,
                                identity.owner,
                                &identity.decl_name,
                            ))
                        }
                        Some(SemanticNodeData::Opaque(
                            crate::semantic_query::QueryError::DeclPlaceholder {
                                canonical_id,
                                owner,
                                name,
                                ..
                            },
                        )) => SemanticQueryKey::Instantiate(crate::semantic_query::InstantiateKey::new(
                            self.type_slot_for(canonical_id.clone(), *owner, name.clone()),
                            Arc::from(Vec::new().into_boxed_slice()),
                            self.instantiate_context_for(
                                canonical_id,
                                crate::semantic_query::ProjectionReductionContext::published(
                                    ProjectionMode::Navigate,
                                ),
                            ),
                        )),
                        Some(
                            SemanticNodeData::Union(_)
                            | SemanticNodeData::Literal(_)
                            | SemanticNodeData::TemplateLiteral { .. }
                            | SemanticNodeData::Primitive(_),
                        ) => return Ok(resolved),
                        Some(SemanticNodeData::Opaque(_)) if resolved != arm => {
                            return Err(QueryResult::Value(resolved));
                        }
                        _ => return Ok(arm),
                    };
                    match self.execute_read(key).value {
                        QueryResult::Value(next) => resolved = next,
                        // A recursive alias stays written by its name.
                        QueryResult::Recursive(_) => return Ok(arm),
                        error @ QueryResult::Error(_) => return Err(error),
                    }
                }
            };
            // The written arms, nested and named unions flattened as the
            // reducer reads them, and named arms standing for their
            // resolution.
            let mut flat = Vec::with_capacity(arms.len());
            let mut seen_names: FxHashSet<SemanticNodeId> = FxHashSet::default();
            let mut pending: Vec<SemanticNodeId> = arms.iter().rev().copied().collect();
            while let Some(arm) = pending.pop() {
                let arm = if is_named(arm) {
                    if !seen_names.insert(arm) {
                        flat.push(arm);
                        continue;
                    }
                    match resolve_named(arm) {
                        Ok(resolved) => resolved,
                        Err(outcome) => return Some(outcome),
                    }
                } else {
                    arm
                };
                match graph.node_data(arm).as_deref() {
                    Some(SemanticNodeData::Union(inner)) => {
                        pending.extend(inner.iter().rev().copied());
                    }
                    _ => flat.push(arm),
                }
            }
            // Each arm's part in absorption: a literal, a pattern template, or a
            // supertype a literal may be absorbed into (its primitive, `any` or
            // `unknown`).
            let role = |arm: SemanticNodeId| match graph.node_data(arm).as_deref() {
                Some(SemanticNodeData::Literal(_)) => AbsorptionRole::Literal,
                Some(SemanticNodeData::TemplateLiteral { .. }) => AbsorptionRole::PatternTemplate,
                Some(SemanticNodeData::Primitive(
                    PrimitiveKind::String
                    | PrimitiveKind::Number
                    | PrimitiveKind::BigInt
                    | PrimitiveKind::Boolean
                    | PrimitiveKind::Any
                    | PrimitiveKind::Unknown,
                )) => AbsorptionRole::Supertype,
                _ => AbsorptionRole::Inert,
            };
            let reducible = may_absorb_a_literal(&flat, role);
            if !reducible {
                return None;
            }
            let members: Arc<[SemanticNodeId]> = Arc::from(flat.as_slice());
            let key = SemanticQueryKey::ReduceUnion {
                members,
                nullability,
            };
            let reduced = match self.execute_read(key).value {
                QueryResult::Value(reduced) => reduced,
                other => return Some(other),
            };
            let is_literal = |arm: SemanticNodeId| {
                matches!(
                    role(arm),
                    AbsorptionRole::Literal | AbsorptionRole::PatternTemplate
                )
            };
            let absorbed = match graph.node_data(reduced).as_deref() {
                // An opaque reduction is the caller's to classify.
                Some(SemanticNodeData::Opaque(_)) => true,
                Some(SemanticNodeData::Union(kept)) => {
                    let kept: FxHashSet<SemanticNodeId> = kept.iter().copied().collect();
                    flat.iter()
                        .any(|&arm| is_literal(arm) && !kept.contains(&arm))
                }
                Some(_) => flat.iter().any(|&arm| is_literal(arm) && arm != reduced),
                None => false,
            };
            Some(QueryResult::Value(if absorbed { reduced } else { node }))
        }
    }

    /// Whether a member-wise composite REBUILD may re-decide its arm list
    /// through the canonical authority — the carrier-semantics dispatch for
    /// projection/expansion/realization rebuild sites, driven by the
    /// original payload's at-rest [`CompositeOriginCategory`] fact.
    ///
    /// A rebuild of a `Canonical`, `CanonicalUnproven` or `AuthoredShell`
    /// composite is a DERIVED result (the authored shell stays recoverable
    /// through the original node and origin evidence; an unproven-canonical
    /// list is the budgeted derived value, and re-deciding gives the
    /// authority another complete attempt), so it routes canonical. Every
    /// other category preserves verbatim: `OrderedCarrier` order IS
    /// overload precedence; a `Heritage` body is a declaration, not an
    /// intersection type; `PreservingRebuild` lost its original's
    /// category, so re-deciding is unproven; `QuerySubject` shape is
    /// caller contract; `TestFixture` is a deliberately raw fixture.
    ///
    /// INTERSECTION rebuilds additionally fail CLOSED on callability —
    /// mirroring the substitution split: when any rebuilt arm may
    /// contribute call signatures the rebuilt list is an overload-ordered
    /// carrier and the commutative route must not reorder it. (This guard
    /// NARROWS — it does not close — the one order-bearing first-wins tag
    /// collision: order semantics independent of callability, such as
    /// heritage topology, rendered-text fidelity and intersection-merge
    /// slot order, stay exposed when an ordered mint collides with an
    /// earlier `Canonical`-tagged twin — see the `composite` module docs'
    /// identity discipline for the disclosed window.)
    ///
    /// EXHAUSTIVE over the category registry — no wildcard arm.
    pub fn composite_rebuild_re_decides(
        &self,
        category: crate::semantic_query::composite::CompositeOriginCategory,
        rebuilt: &[SemanticNodeId],
        is_union: bool,
    ) -> bool {
        use crate::semantic_query::composite::CompositeOriginCategory as C;
        let derived = match category {
            C::Canonical(_) | C::CanonicalUnproven | C::AuthoredShell => true,
            C::OrderedCarrier
            | C::OverloadGroup
            | C::MergedOverloadGroup
            | C::Heritage
            | C::PreservingRebuild
            | C::QuerySubject => false,
            #[cfg(any(test, feature = "test-support"))]
            C::TestFixture => false,
        };
        derived
            && (is_union
                || !rebuilt.iter().any(|&arm| {
                    super::walk::value_may_contribute_call_signatures(self.graph().store(), arm)
                }))
    }
}

/// Path-prefix peek. Walks `path` from longest to
/// shortest non-empty prefix, returning the warm `(base, path[..k],
/// Navigate)` entry's resolved node and `k` if any such prefix is
/// memoized. Returns `None` when no prefix is warm — caller falls back
/// to walking the full path from `base`.
///
/// The lookup forces `mode: Navigate` regardless of
/// the caller's mode because intermediate path hops MUST be cached as
/// Navigate per the path-precise rule (CLAUDE.md "Macro Type Traversal
/// Rule"). The terminal hop keeps the caller's mode and is published by
/// `execute_cooperative` directly; the prefix peek only inspects
/// intermediate hops.
///
/// Increments the test-only `PREFIX_PEEK_HITS` thread-local on success
/// so `project_path_prefix_peek_short_circuits_sibling_walk` can
/// discriminate pre-fix (no helper / always None) vs post-fix (peek hits
/// the warm prefix).
fn find_longest_warm_prefix<C: crate::resolver_core::ResolverCapabilities>(
    graph: &crate::semantic_query_memo::SemanticGraphStore,
    ctx: &dyn crate::resolver_core::ResolverContext<C>,
    base: SemanticNodeId,
    path: &verter_type_expr::OwnedSlice<PathSegment>,
    admit: impl Fn(&crate::semantic_query::ReadReceipt) -> bool,
) -> Option<(SemanticNodeId, usize)> {
    for k in (1..path.len()).rev() {
        let prefix_path: verter_type_expr::OwnedSlice<PathSegment> =
            verter_type_expr::OwnedSlice::from(path[..k].to_vec().into_boxed_slice());
        let prefix_key = SemanticQueryKey::ProjectPath {
            base,
            path: prefix_path,
            context: crate::semantic_query::ProjectionReductionContext::published(
                ProjectionMode::Navigate,
            ),
        };
        // Validate-before-bubble: a stale prefix entry must neither
        // surface as a hit nor pollute the active fact tracer.
        if let Some(hit) = graph.get_validated(&prefix_key, ctx) {
            if !admit(&hit.receipt) {
                return None;
            }
            if let QueryResult::Value(prefix_node) = hit.value {
                #[cfg(any(test, feature = "test-support"))]
                PREFIX_PEEK_HITS.with(|c| *c.borrow_mut() += 1);
                return Some((prefix_node, k));
            }
        }
    }
    None
}

/// Collect per-linear-prefix backfill records for the
/// `(base, path[..i+1], Navigate)` keys.
///
/// **Deferred publication.** Returns a `Vec<PrefixBackfill>` the
/// caller threads onto `QueryBuildOutput.pending_prefix_backfills`.
/// The shared cold-build helper publishes those records AFTER
/// `install_fact_tracer` finalises so each backfilled memo entry's
/// carrier holds the parent's authoritative path-precise fact
/// signature (not a fence-derived legacy-only signature that loses
/// `Parse(...)` / `ResolveImports(...)` / `RouteSurface(...)`
/// facts).
///
/// Skips the last index — the full key is owned by
/// `execute_cooperative` (it carries the caller's mode, not Navigate;
/// the path-precise rule places terminal hops at the caller's mode).
///
/// Skips `None` entries (arm-splits at Union / Intersection /
/// open-Conditional positions); those positions have no single
/// canonical answer for `(base, path[..k], Navigate)`.
/// The §3.4 materialised-record set for a path-projection terminal entry:
/// the terminal point at the FULL `path` (the caller's `terminal_mode`)
/// PLUS one `Demand::navigate(path[..k])` per CONTIGUOUS LINEAR walked
/// intermediate. The linear run spans the warm prefix already established
/// by [`find_longest_warm_prefix`] (`start_index` positions, all linear by
/// construction — a prior walk produced a single canonical node at
/// `path[..start_index]`) plus the leading `Some` run of the current
/// walk's `intermediates` (excluding the terminal slot), stopping at the
/// first arm-split `None` exactly as [`collect_prefix_backfills`] does.
///
/// The navigate-hop points are inert for the terminal family's own
/// warm-hit gate (requests there are always at the full path); they record
/// the honest materialisation per §3.4 and NEVER inflate a prefix hop to
/// the terminal mode it never expanded.
pub fn path_walk_materialized_set(
    path: &verter_type_expr::OwnedSlice<PathSegment>,
    terminal_mode: ProjectionMode,
    start_index: usize,
    intermediates: &[Option<SemanticNodeId>],
) -> MaterializedSet {
    let n = path.len();
    let mut terminal = Demand::from(terminal_mode);
    terminal.projection.path = ProjectionPath::from(path.clone());
    let mut points = vec![MaterializedPoint::new(terminal)];
    if n >= 2 {
        // Number of full-path intermediate positions (1..=n-1) that are on
        // the contiguous linear run. `start_index` warm-prefix positions
        // are linear; the current walk extends the run by its leading
        // `Some` count (excluding the terminal slot at index
        // `walker_path.len() - 1`).
        let walker_path_len = n - start_index;
        let walked_linear = intermediates
            .iter()
            .take(walker_path_len.saturating_sub(1))
            .take_while(|node| node.is_some())
            .count();
        let linear_hops = (start_index + walked_linear).min(n - 1);
        for k in 1..=linear_hops {
            let prefix: verter_type_expr::OwnedSlice<PathSegment> =
                verter_type_expr::OwnedSlice::from(path[..k].to_vec().into_boxed_slice());
            points.push(MaterializedPoint::new(Demand::navigate(
                ProjectionPath::from(prefix),
            )));
        }
    }
    MaterializedSet::from_points(points)
}

fn collect_prefix_backfills(
    base: SemanticNodeId,
    path: &verter_type_expr::OwnedSlice<PathSegment>,
    intermediates: &[Option<SemanticNodeId>],
    receipts: Vec<Arc<crate::project_semantic_dispatch::cost_receipt::DemandCostReceipt>>,
) -> Vec<crate::project_semantic_dispatch::walk::PrefixBackfill> {
    let mut receipts = receipts.into_iter();
    // Backfill is only meaningful for the contiguous LINEAR prefix of
    // the walk — the leading run of `Some(node)` entries before any
    // arm-split. Once the walker hits a Union / Intersection /
    // Conditional, subsequent intermediates may belong to per-arm
    // sub-walks (which the iterative worklist runs as their own
    // advance_step calls) and no longer line up with the trunk's
    // path index.
    //
    // Bound `i` so that:
    //   - `i < intermediates.len() - 1` — skip the last intermediate;
    //     the terminal full-path key is owned by `execute_cooperative`
    //     (it carries the caller's mode, not Navigate).
    //   - `i < path.len() - 1` — keep `path[..i + 1]` strictly shorter
    //     than the full path (sibling-sharable prefixes only) and avoid
    //     out-of-range slicing when arm-split sub-walks pushed extra
    //     entries past `path.len()`.
    //   - Break at the first `None` — after an arm-split the index no
    //     longer lines up with `path[..i + 1]` so subsequent entries
    //     are not canonical answers for that key.
    let max_i = intermediates.len().min(path.len()).saturating_sub(1);
    let mut out = Vec::new();
    for i in 0..max_i {
        let Some(node) = intermediates[i] else { break };
        let prefix_path: verter_type_expr::OwnedSlice<PathSegment> =
            verter_type_expr::OwnedSlice::from(path[..i + 1].to_vec().into_boxed_slice());
        let prefix_key = SemanticQueryKey::ProjectPath {
            base,
            path: prefix_path.clone(),
            context: crate::semantic_query::ProjectionReductionContext::published(
                ProjectionMode::Navigate,
            ),
        };
        // §3.4: the prefix family's entry records exactly its own
        // `Navigate` hop at the prefix path — NOT a nominal/meet point. A
        // `Navigate` request at this prefix self-satisfies; a `Shallow` /
        // `Expanded` request at this prefix misses (the walk never
        // expanded the prefix — it only navigated through it).
        let satisfied_projection = MaterializedSet::single(MaterializedPoint::new(
            Demand::navigate(ProjectionPath::from(prefix_path)),
        ));
        out.push(crate::project_semantic_dispatch::walk::PrefixBackfill {
            key: prefix_key,
            node,
            cost_receipt: receipts.next(),
            satisfied_projection,
        });
    }
    out
}

/// Helper — convert a per-call local fence (one
/// `(canonical, version)` entry per dep fact accumulated during the
/// build path) into the canonical `Arc<[crate::semantic_query::DepEntry]>`
/// shape returned alongside `QueryResult`.
fn fence_to_dep_signature(fence: Vec<crate::semantic_query::DepEntry>) -> DepSignature {
    crate::semantic_query::DepSignature::new(fence)
}

/// Apply a TS string-intrinsic case transform to a single string literal value.
/// `Capitalize` / `Uncapitalize` toggle the case of the FIRST character only;
/// `Uppercase` / `Lowercase` transform the whole string.
pub(super) fn transform_string_intrinsic(intrinsic: &str, text: &str) -> String {
    match intrinsic {
        "Uppercase" => text.to_uppercase(),
        "Lowercase" => text.to_lowercase(),
        "Capitalize" => {
            let mut chars = text.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
                None => String::new(),
            }
        }
        "Uncapitalize" => {
            let mut chars = text.chars();
            match chars.next() {
                Some(first) => first.to_lowercase().collect::<String>() + chars.as_str(),
                None => String::new(),
            }
        }
        // Unreachable in practice (the caller matches the four names), but a
        // total function is safer than a panic on a future caller.
        _ => text.to_string(),
    }
}

/// The outcome of applying a mapped-type key remap (`[K in … as <expr>]`) to a
/// single iteration key. The shared classifier
/// [`ProjectSemanticDispatch::mapped_member_name_remap_outcome`] produces this;
/// both the Expanded build ([`ProjectSemanticDispatch::build_mapped_type`]) and
/// the Shallow walker's `synthesise_mapped_surface` consume it identically.
#[derive(Debug, Clone)]
pub(super) enum MappedKeyRemapOutcome {
    /// No `as` clause — keep the iteration key verbatim.
    Keep(crate::semantic_query::PropertyKey),
    /// The remap resolved to `never` — DROP this key from the surface.
    Drop,
    /// The remap resolved to a finite string literal / union of literals —
    /// these are the produced key(s) (usually one).
    Keys(Vec<crate::semantic_query::PropertyKey>),
    /// The remap is unresolved / non-finite / non-string — the mapped type
    /// FAILS CLOSED to its deferred carrier (never the original key).
    DeferCarrier,
}

/// One ambient declaration of a module, `declare module "specifier" { … }`
/// ([`ProjectSemanticDispatch::ambient_module_blocks`]).
#[derive(Debug, Clone)]
pub(super) struct AmbientModuleBlock {
    /// The file declaring the block.
    pub(super) canonical: Arc<str>,
    /// The file owner the block's members are declared in.
    pub(super) owner: verter_type_expr::TopLevelOwnerId,
    /// The block's augmentation scope.
    pub(super) scope: verter_session_query::declarations::AugmentationScopeKind,
    /// The name its `export default` declaration declares.
    pub(super) default_export: Option<Arc<str>>,
    /// The name it assigns the module to with `export = X`.
    pub(super) export_assignment: Option<Arc<str>>,
}

impl AmbientModuleBlock {
    /// The value root of the block's member `name`.
    pub(super) fn root(&self, name: Arc<str>) -> ValueRootKey {
        ValueRootKey {
            scope: crate::semantic_query::ScopeId {
                canonical_id: verter_type_expr::OwnedStr::from(self.canonical.clone()),
                owner: self.owner,
                local_scope: None,
                binder_scope_id: match &self.scope {
                    verter_session_query::declarations::AugmentationScopeKind::Module(
                        specifier,
                    ) => crate::semantic_query::BinderScopeId::augmentation_module_scope(
                        self.owner,
                        specifier.as_str().into(),
                    ),
                    verter_session_query::declarations::AugmentationScopeKind::Global => {
                        crate::semantic_query::BinderScopeId::augmentation_global_scope(self.owner)
                    }
                },
            },
            name: name.into(),
        }
    }
}

/// The symbol space a global declaration is looked up in
/// ([`ProjectSemanticDispatch::lib_global_declaration`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum GlobalSpace {
    /// An interface, type alias, class or enum type.
    Type,
    /// A `var` / `let` / `const`, function, class or enum value.
    Value,
}

/// The result of [`ProjectSemanticDispatch::normalize_tuple_spread`]: either a
/// (possibly spliced) element list that interns as a `Tuple`, or the one
/// node the tuple already is — the array a sole rest-of-array tuple
/// collapses to (`[...E[]]` ≡ `E[]`), or the checker's error-type recovery
/// of a splice past its tuple-size limit (TS2799 / TS2800).
#[derive(Debug)]
pub enum NormalizedTupleShape {
    Tuple(Vec<crate::semantic_query::TupleElement>),
    Array(SemanticNodeId),
}

/// Whether a mapped-type produced member inherits the matched source member's
/// declaration site (spans + `declaration_origin`).
///
/// Declaration-site inheritance is judged PER PRODUCED NAME: a produced member
/// inherits the matched source member's spans + `declaration_origin` ONLY when
/// its produced name is identical to the source key — the homomorphic /
/// name-preserving image (no-`as` Partial / Required / Readonly, `as K`
/// identity, the verbatim arm of a one-to-many remap). TypeScript preserves
/// JSDoc through that image, and the typeinfo JSDoc enrichment anchors on
/// these spans. A key-remapped arm (a true `as` rename, including renamed arms
/// of a one-to-many remap) publishes a name no source declaration declares —
/// inheriting the source's spans/origin would be a false declaration-site
/// claim, so both sever (default spans, no origin). Optional / readonly /
/// visibility / value selection stay sourced from the matched source member
/// regardless: the rename severs the declaration-site claim, not the member
/// semantics.
///
/// Both rails — the Expanded build ([`ProjectSemanticDispatch::build_mapped_type`])
/// and the Shallow walker's `synthesise_mapped_surface` — judge inheritance
/// through this one predicate so they can never drift.
pub(super) fn mapped_produced_key_inherits_declaration_site(
    produced_key: &PropertyKey,
    source_key: &PropertyKey,
) -> bool {
    produced_key == source_key
}

/// Which awaited relation a shared structural arm re-enters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub(crate) enum AwaitedRelation {
    /// [`SemanticQueryKey::AwaitedNormalize`].
    Normalize,
    /// [`SemanticQueryKey::AsyncReturnPayload`].
    Payload,
}

impl AwaitedRelation {
    /// This relation's family key over `operand`.
    fn key(
        self,
        operand: SemanticNodeId,
        context: crate::semantic_query::StructuralReduceContext,
    ) -> SemanticQueryKey {
        match self {
            Self::Normalize => SemanticQueryKey::AwaitedNormalize { operand, context },
            Self::Payload => SemanticQueryKey::AsyncReturnPayload { operand, context },
        }
    }

    /// The diagnostic this relation raises on a thenable whose promised
    /// value it is already unwrapping: TS1062, from the operation the
    /// relation serves.
    fn recursion_diagnostic(self) -> crate::semantic_query::CheckerDiagnostic {
        use crate::semantic_query::CheckerDiagnosticOperation;
        crate::semantic_query::CheckerDiagnostic {
            code: crate::semantic_query::CheckerDiagnosticCode::RecursiveFulfillmentCallback,
            operation: match self {
                Self::Normalize => CheckerDiagnosticOperation::AwaitOperand,
                Self::Payload => CheckerDiagnosticOperation::AsyncReturnPayload,
            },
        }
    }
}

/// One step of an awaited relation.
#[derive(Debug, Clone, Copy)]
enum AwaitedStep {
    /// The relation reduced the operand to this node.
    Value(SemanticNodeId),
    /// The relation reached a thenable whose promised value it is already
    /// unwrapping, and the checker reports TS1062. Its `getAwaitedType`
    /// answers `undefined` here: a union drops the arm, anything else fails
    /// whole, and the operation continues with its error type.
    Failed,
    /// The protocol cannot decide the operand.
    Refused,
    /// A TAIL step: the relation's answer for the operand is its answer for
    /// this one node (a `Promise<V>` payload, a thenable promising a single
    /// value, an awaited application's argument). The run continues with it
    /// in the same loop ([`ProjectSemanticDispatch::awaited_relation_run`]).
    Next(SemanticNodeId),
    /// A declaration carrier expanded to its body: the run continues with
    /// the body, and when the body is its own answer the CARRIER is, so a
    /// non-thenable alias keeps its authored identity.
    Expand {
        /// The carrier the step expanded.
        carrier: SemanticNodeId,
        /// Its body, the node the run continues with.
        body: SemanticNodeId,
    },
}

/// The outcome of one awaited relation over an operand.
#[derive(Debug, Clone, Copy)]
enum AwaitedOutcome {
    /// The relation reduced the operand to this node.
    Value(SemanticNodeId),
    /// The checker's TS1062 failure ([`AwaitedStep::Failed`]).
    Failed,
    /// The protocol cannot decide the operand, or the connected-work budget
    /// ran out first.
    Refused,
}

/// Pops the operands one awaited run pushed onto the dispatch's path when
/// the run ends, however it ends.
struct AwaitedPathGuard<'g> {
    active: &'g std::cell::RefCell<AwaitedPath>,
    base: usize,
}

impl Drop for AwaitedPathGuard<'_> {
    fn drop(&mut self) {
        self.active.borrow_mut().truncate(self.base);
    }
}

/// The operands the awaited relations are unwrapping on the current path
/// ([`ProjectSemanticDispatch::awaited_active`]), in push order, with
/// their membership counted: a run asks whether each operand it reaches is
/// already on the path, so the check is one lookup rather than a scan of
/// every operand the run has reached — a chain of `n` distinct thenables
/// costs `O(n)` checks, never `O(n²)` comparisons. Owned by the dispatch
/// with the ordered stack it indexes: an operand enters both on a push and
/// leaves both when its run's [`AwaitedPathGuard`] truncates (an operand a
/// nested run pushed again stays a member until its outer entry goes), so
/// the index holds nothing once the outermost run ends.
#[derive(Debug, Default)]
pub(crate) struct AwaitedPath {
    order: Vec<(AwaitedRelation, SemanticNodeId)>,
    members: rustc_hash::FxHashMap<(AwaitedRelation, SemanticNodeId), u32>,
}

impl AwaitedPath {
    pub(crate) fn len(&self) -> usize {
        self.order.len()
    }

    pub(crate) fn contains(&self, relation: AwaitedRelation, operand: SemanticNodeId) -> bool {
        self.members.contains_key(&(relation, operand))
    }

    pub(crate) fn push(&mut self, relation: AwaitedRelation, operand: SemanticNodeId) {
        *self.members.entry((relation, operand)).or_insert(0) += 1;
        self.order.push((relation, operand));
    }

    pub(crate) fn truncate(&mut self, len: usize) {
        while self.order.len() > len {
            let Some(entry) = self.order.pop() else {
                break;
            };
            if let std::collections::hash_map::Entry::Occupied(mut count) =
                self.members.entry(entry)
            {
                *count.get_mut() -= 1;
                if *count.get() == 0 {
                    count.remove();
                }
            }
        }
    }
}

/// The lib `Awaited<T>` conditional's outcome over one operand.
#[derive(Debug)]
enum LibAwaited {
    /// The conditional selected a branch and reduced to this node.
    Reduced(SemanticNodeId),
    /// The check type is still generic: the application stays deferred.
    Deferred,
    /// The operand does not settle far enough to decide.
    Refused,
}

/// One application of the lib conditional.
#[derive(Debug)]
enum LibStep {
    /// The application's outcome.
    Done(LibAwaited),
    /// The application recurses into `Awaited<V>` through a single callback:
    /// the checker's tail step, continuing the current run on `V`.
    Next(SemanticNodeId),
}

/// The instantiation depth the checker has entered on reaching the lib
/// `Awaited<T>` conditional's first application: the alias instantiation
/// and the conditional it instantiates. Each NESTED step then enters one
/// level more, so the path fails on its 98th nested step at the checker's
/// depth of 100.
///
/// A nested step either goes through a callback union (an optional or
/// nullable `onfulfilled`, a union-typed `then`, every `Promise`) or into a
/// union `V`; a step that does both enters two levels. Measured on
/// TypeScript 7.0.2: 97 nested steps answer the chain's value (reporting
/// TS2589 on some shapes while keeping the value), 98 are `any` under
/// TS2589, whether the application is written directly, through a generic
/// alias, through a signature, or over `ReturnType`. A TAIL step (`Awaited<X>`
/// to `Awaited<V>` through a single callback into a non-union `V`) is the
/// conditional's tail run instead: over chains of distinct thenables `C0 →
/// C1 → … → number`, 999 steps answer `number`, 1000 are `any` under
/// TS2589, and a run entered through a callback union starts with one step
/// already counted (998 further steps answer, 999 fail).
const LIB_AWAITED_ENTRY_DEPTH: u32 = 2;

/// Whether a class property's type names nothing outside its own text: a
/// keyword, a literal, or a union, parenthesised type, array or tuple of
/// them. Such a type lowers to the same scope-free nodes in every file and
/// under every binding, so the member's own elements are its only input.
/// Anything else — a reference, a type parameter, `this`, `typeof`, an
/// operator, an object or function type (whose members carry declaration
/// origins) — is not, nor is a type wider than a small fixed number of
/// nodes.
fn is_independent_member_type(
    ty: &TypeExpr,
    name_resolution: &FxHashMap<verter_type_expr::OwnedStr, ResolvedRootIdentity>,
) -> bool {
    verter_session_query::source::deref::independent_class_member_type(ty, name_resolution)
}

/// What one class of an inheritance path answers for a demanded member
/// read.
enum ClassMemberStep {
    /// The class declares the member: an object of its own members of that
    /// name.
    Declared(SemanticNodeId),
    /// The class does not declare it: its `extends` arm, and the class
    /// declaration (with the clause's type arguments) that arm references,
    /// when it references one.
    Inherited {
        heritage: SemanticNodeId,
        base: Option<(crate::semantic_query::DeclIdentity, Vec<SemanticNodeId>)>,
    },
}

/// The lib conditional's recursion on one evaluation path, counted the way
/// the checker counts it.
#[derive(Debug)]
struct LibAwaitedWalk {
    /// The checker's instantiation depth along the path: every nested
    /// (non-tail) step enters it one level deeper.
    depth: crate::semantic_query::checker_policy::InstantiationDepth,
    /// The applications on the path, in order, for the recurrence that
    /// never reaches a value.
    path: Vec<SemanticNodeId>,
    /// The same applications, to look one up in constant time.
    on_path: rustc_hash::FxHashSet<SemanticNodeId>,
}

/// The lib conditional's `then` branch over one object surface.
#[derive(Debug)]
enum LibThen {
    /// The surface does not satisfy `{ then(onfulfilled: infer F, ...) }`.
    NotMatched,
    /// The branch result.
    Result(SemanticNodeId),
    /// A single callback `F`: the conditional continues as `Awaited<V>`.
    Next(SemanticNodeId),
    /// A promised value is still generic.
    Deferred,
    /// A signature source did not settle.
    Refused,
}

/// The `then` members of one object surface, in surface order.
///
/// Member PRESENCE by name and nothing else: the settled fast path and both
/// thenable readers agree on which members are `then` through this one
/// definition, and every signature decision over those members belongs to
/// the shared discovery authority.
fn then_members(
    surface: &crate::semantic_query::SurfaceView,
) -> Vec<&crate::semantic_query::SurfaceMember> {
    surface
        .positive_members()
        .iter()
        .filter(|member| member.string_name() == Some("then"))
        .collect()
}

/// An object surface's standing under the checker's RUNTIME thenable protocol.
#[derive(Debug)]
enum Thenability {
    /// No callable `then`: the surface is its own awaited type.
    NotThenable,
    /// A valid thenable promising these values.
    Promised(Vec<SemanticNodeId>),
    /// A callable `then` that promises nothing: the checker types it `any`.
    Malformed,
    /// This reader cannot decide the protocol.
    Undecided,
}

/// The declaration scope a type-parameter binding lowers its defaults in:
/// the declaration's file scope, its scope payload and shadow set, and the
/// authored-resolution debt of a declaration recovered as a partial.
/// How [`ProjectSemanticDispatch::begin_instantiate`] begins.
pub(super) enum InstantiateStart {
    /// The instantiation is answered.
    Done(Box<crate::project_semantic_dispatch::walk::QueryBuildOutput>),
    /// Its body is being lowered.
    Build(Box<InstantiateBuild>),
}

/// Where a macro payload's resolution stands after its first stage
/// ([`ProjectSemanticDispatch::begin_resolve_macro_payload`]).
pub(super) enum MacroPayloadStep {
    /// The payload is answered.
    Done(Box<crate::project_semantic_dispatch::walk::QueryBuildOutput>),
    /// The payload is read from its payload operation.
    Need(Box<MacroPayloadBuild>),
}

/// A macro payload's resolution while its payload operation is read: what
/// its first stage read of the owning file and the fence it seeded, kept so
/// the operation's read finishes the resolution without reading the owner
/// again ([`ProjectSemanticDispatch::finish_resolve_macro_payload`]).
pub(super) struct MacroPayloadBuild {
    rooting: MacroPayloadRooting,
    local_fence: Vec<crate::semantic_query::DepEntry>,
    payload: SemanticQueryKey,
}

impl MacroPayloadBuild {
    /// The payload operation the value is read from.
    pub(super) fn payload(&self) -> &SemanticQueryKey {
        &self.payload
    }
}

/// What a macro payload's output is rooted on: the owning file at the
/// content version its first stage observed, and its type arguments.
struct MacroPayloadRooting {
    owner: OwnedStr,
    is_non_file_owner: bool,
    owner_whole_hash: crate::semantic_query::HashValue,
    stale_real_file_owner: bool,
    type_args: Arc<[SemanticNodeId]>,
}

/// Where an instantiation's build stands after it ran as far as it could.
pub(super) enum InstantiatePoll {
    Done(Box<crate::project_semantic_dispatch::walk::QueryBuildOutput>),
    /// The build waits on this instantiation.
    Need(crate::semantic_query::SemanticQueryKey),
}

/// A generic declaration's instantiation between its steps: everything the
/// build owns while its body projection waits on another instantiation.
pub(super) struct InstantiateBuild {
    pub(super) active_identity: super::InstantiateIdentity,
    decl_canonical: verter_type_expr::OwnedStr,
    decl_owner: verter_type_expr::TopLevelOwnerId,
    decl_name: verter_type_expr::OwnedStr,
    is_non_file_base: bool,
    decl_whole_hash: crate::semantic_query::HashValue,
    base: SemanticNodeId,
    pub(super) args: Arc<[SemanticNodeId]>,
    effective_args: Arc<[SemanticNodeId]>,
    scope: NodeScopeId,
    prepared: verter_retention::heap_size::OwnedValue<PreparedTypeDecl>,
    scope_payload: Option<crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: crate::resolver_core::scope_shadowing::ScopeShadowing,
    authored_resolution_debt:
        Option<crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame>,
    context: crate::semantic_query::ProjectionReductionContext,
    body_mode: crate::semantic_query::ProjectionMode,
    env: FxHashMap<String, SemanticNodeId>,
    substitutions: Vec<(Arc<str>, SemanticNodeId)>,
    tail: crate::semantic_query::checker_policy::ConditionalTail,
    /// Every argument list the tail run has taken, for the recurrence that
    /// never reaches a value.
    tail_arguments: rustc_hash::FxHashSet<Arc<[SemanticNodeId]>>,
    /// The arguments of the tail run's current step.
    tail_current: Arc<[SemanticNodeId]>,
    /// The declaration's uniform growth ([`GrowthShape`]), once read
    /// (`Some(None)` when its body has none).
    growth: Option<Option<GrowthShape>>,
    /// Whether the declaration's body is a conditional type, once read
    /// (`Some(None)` when it could not be recovered).
    conditional_body: Option<Option<bool>>,
    generic: bool,
    suspend: bool,
    /// Whether the body is an enum's member union: every block of the enum,
    /// augmenting ones included, already contributed its members.
    enum_body: bool,
    body: BodyLowering,
    complete_structure: bool,
}

/// What a mapping's `as` clause produces for one key TYPE of its key domain.
#[derive(Default)]
struct MappedIndexRemap {
    /// The index-signature key types it produces.
    key_types: Vec<SemanticNodeId>,
    /// The property names it produces.
    names: Vec<PropertyKey>,
}

/// The members a mapped type produces, in production order, indexed by
/// property spelling so a later production of the same property joins the
/// first ([`ProjectSemanticDispatch::join_mapped_production`]).
pub(super) struct MappedProducedMembers {
    members: Vec<SurfaceMember>,
    by_spelling: FxHashMap<PropertyKey, usize>,
}

impl MappedProducedMembers {
    pub(super) fn with_capacity(capacity: usize) -> Self {
        Self {
            members: Vec::with_capacity(capacity),
            by_spelling: FxHashMap::with_capacity_and_hasher(capacity, Default::default()),
        }
    }

    /// Adds the first production of a property.
    pub(super) fn push(&mut self, member: SurfaceMember) {
        if let Some(key) = member.key.cloned_known() {
            self.by_spelling
                .entry(crate::semantic_query::property_spelling(key))
                .or_insert(self.members.len());
        }
        self.members.push(member);
    }

    pub(super) fn into_members(self) -> Vec<SurfaceMember> {
        self.members
    }
}

/// A key TYPE of a homomorphic mapping's key domain — its source's index
/// signature — which maps to an index signature.
struct MappedIndexKey {
    key_type: SemanticNodeId,
    /// The source's index signature it reads.
    source: Option<crate::semantic_query::IndexSignature>,
}

/// How a `typeof` build begins on the continuation runtime.
pub(super) enum TypeofStart {
    /// The `typeof` is answered.
    Done(Box<crate::project_semantic_dispatch::walk::QueryBuildOutput>),
    /// Its value's authored value position is being lowered.
    Build(Box<TypeofBuild>),
}

/// The declaration scope a `typeof`'s value-position lowering runs in.
struct TypeofBodyScope<'p> {
    prepared: &'p verter_retention::heap_size::OwnedValue<
        verter_session_query::type_solver::PreparedValueDecl,
    >,
    env: FxHashMap<String, SemanticNodeId>,
    scope: NodeScopeId,
    scope_payload: Option<crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: crate::resolver_core::scope_shadowing::ScopeShadowing,
    substitutions: Vec<(Arc<str>, SemanticNodeId)>,
}

/// The authored value position of `prepared`'s own declaration: where its
/// inferred initializer type and its const-object shape are recovered.
fn value_position_locator(
    prepared: &verter_session_query::type_solver::PreparedValueDecl,
    augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
) -> verter_type_expr::locators::AuthoredBodyLocator {
    scoped_type_body_locator(
        &verter_type_expr::locators::TypeBodySlot {
            anchor: verter_type_expr::locators::AuthoredAnchor {
                canonical_id: prepared.root_identity.canonical_id.clone(),
                owner: prepared.root_identity.owner,
                symbol: prepared.root_identity.symbol_name.clone(),
                space: verter_type_expr::locators::LocatorSymbolSpace::Value,
            },
            path: verter_type_expr::OwnedSlice::default(),
        },
        augmentation,
    )
}

/// A `typeof` whose value position (its annotation, its inferred
/// initializer or its const-object shape) or one of whose signatures is
/// lowering, between the steps of its frame: the lowering's scope, the
/// projection itself, what follows it, and what the build's output roots on.
pub(super) struct TypeofBuild {
    redirects: Vec<TypeofRedirect>,
    /// The declaration the body lowering now belongs to.
    prepared: verter_retention::heap_size::OwnedValue<
        verter_session_query::type_solver::PreparedValueDecl,
    >,
    env: FxHashMap<String, SemanticNodeId>,
    scope: NodeScopeId,
    scope_payload: Option<crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: crate::resolver_core::scope_shadowing::ScopeShadowing,
    substitutions: Vec<(Arc<str>, SemanticNodeId)>,
    self_value: Option<verter_type_expr::locators::AuthoredAnchor>,
    body: TypeofBody,
    then: TypeofThen,
    value_root: ValueRootKey,
    path: verter_type_expr::OwnedSlice<verter_type_expr::OwnedStr>,
    context: crate::semantic_query::ProjectionReductionContext,
    observed_hash: verter_session_query::analysis::types::Hash16,
}

/// The authored import head and file root a qualified redirect retains until
/// its declaring value completes, in inner-to-outer completion order.
struct TypeofRedirect {
    declaring: ValueRootKey,
    authored: ValueRootKey,
    path: verter_type_expr::OwnedSlice<verter_type_expr::OwnedStr>,
    observed_hash: verter_session_query::analysis::types::Hash16,
}

impl TypeofBuild {
    pub(super) fn checking_site(
        &self,
    ) -> crate::semantic_query::checker_policy::TupleSplicePosition {
        use crate::semantic_query::checker_policy::TupleSplicePosition;
        match self.body {
            TypeofBody::Expression(_) => TupleSplicePosition::Expression,
            _ => TupleSplicePosition::Type,
        }
    }
}

/// What a `typeof` build evaluates between its frame's steps.
enum TypeofBody {
    /// Nothing yet: the build is about to begin its first body.
    Unstarted,
    /// A declaration body's lowering.
    Lowering(BodyLowering),
    /// The value's initializer, an expression source.
    Expression(Box<super::flow_return::ExpressionSourceRun>),
}

/// What a `typeof` build's lowered body is.
enum TypeofThen {
    /// The value's type.
    Value,
    /// One of the value's signatures, the rest of which follow it.
    Signatures(Box<SignatureLowering>),
    /// The value of one of the member positions a member path reads where
    /// the value declares it; the rest follow it.
    Member(Box<MemberLowering>),
}

/// The modifiers of one own member position.
#[derive(Clone, Copy)]
struct ValueMemberFacts {
    optional: bool,
    readonly: bool,
    method_kind: Option<verter_type_expr::ObjectMethodKind>,
    has_body: bool,
    visibility: verter_type_expr::MemberVisibility,
}

/// The scope a value's own member positions lower in.
struct ValueMemberScope {
    env: FxHashMap<String, SemanticNodeId>,
    scope: NodeScopeId,
    scope_payload: Option<crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: crate::resolver_core::scope_shadowing::ScopeShadowing,
}

/// The own member positions of one name a value's authored object or class
/// declares, lowering one at a time, and the members lowered so far.
pub(super) struct ValueMembers {
    name: verter_type_expr::OwnedStr,
    canonical: verter_type_expr::OwnedStr,
    owner: verter_type_expr::TopLevelOwnerId,
    symbol: verter_type_expr::OwnedStr,
    positions: std::collections::VecDeque<(u32, ValueMemberFacts)>,
    class_type_params: Vec<verter_type_expr::facts::NarrowTypeParam>,
    context: crate::semantic_query::ProjectionReductionContext,
    own: Vec<SurfaceEntry>,
}

impl ValueMembers {
    /// The authored value position of the member at `ordinal`.
    fn locator(&self, ordinal: u32) -> verter_type_expr::locators::AuthoredBodyLocator {
        verter_type_expr::locators::AuthoredBodyLocator::DeclBody(
            verter_type_expr::locators::TypeBodySlot {
                anchor: verter_type_expr::locators::AuthoredAnchor {
                    canonical_id: self.canonical.clone(),
                    owner: self.owner,
                    symbol: self.symbol.clone(),
                    space: verter_type_expr::locators::LocatorSymbolSpace::Value,
                },
                path: verter_type_expr::OwnedSlice::from(
                    vec![
                        verter_type_expr::locators::TypeBodyPathStep::Member { ordinal },
                        verter_type_expr::locators::TypeBodyPathStep::MemberValue,
                    ]
                    .into_boxed_slice(),
                ),
            },
        )
    }

    /// Record the lowered `value` of a member position with its modifiers.
    fn record(&mut self, facts: ValueMemberFacts, value: SemanticNodeId) {
        self.own.push(SurfaceEntry::Member(SurfaceMember {
            key: crate::semantic_query::AuthoredPropertyKey::string(self.name.as_ref()),
            value,
            optional: facts.optional,
            readonly: facts.readonly,
            method_kind: facts.method_kind,
            has_implementation_body: facts.has_body,
            visibility: facts.visibility,
            excess_origin: verter_type_expr::ExcessPropertyOrigin::NonLiteral,
            spans: verter_type_expr::MemberSpans::default(),
            declaration_origin: Some(self.canonical.clone()),
            declared_in_macro_type_arg: crate::semantic_query::MacroOwnBodyStamp::default(),
            merge_role: crate::semantic_query::MergeRoleStamp::default(),
        }));
    }
}

/// A member path's `typeof` lowering the member where the value declares
/// it, one position at a time: the positions, the one lowering now, and
/// the declaring file the member roots on.
pub(super) struct MemberLowering {
    members: ValueMembers,
    current: Option<ValueMemberFacts>,
    declaring: verter_type_expr::OwnedStr,
}

/// A function value's signatures, lowering one at a time: its own
/// declaration's, then those of each later file's declaration of a global
/// function. Module augmentations join once in `finish_value_signatures`.
pub(super) struct SignatureLowering {
    /// The function's own declaration.
    own: verter_retention::heap_size::OwnedValue<
        verter_session_query::type_solver::PreparedValueDecl,
    >,
    is_class: bool,
    /// The signatures queued to lower.
    jobs: std::collections::VecDeque<SignatureJob>,
    /// The merged declarations whose signatures follow, not yet read.
    peers: std::collections::VecDeque<ResolvedRootIdentity>,
    /// The signature groups lowered so far, one per declaration block.
    groups: Vec<Vec<SemanticNodeId>>,
    /// The block of the last signature grouped.
    current_block: Option<Option<u32>>,
    /// The block of the signature lowering now, and whether it opens its
    /// declaration's groups.
    lowering: Option<(Option<u32>, bool)>,
}

/// One visible signature of a function value to lower.
struct SignatureJob {
    /// The declaration that declares it.
    prepared: verter_retention::heap_size::OwnedValue<
        verter_session_query::type_solver::PreparedValueDecl,
    >,
    locator: verter_type_expr::locators::AuthoredBodyLocator,
    /// The declaration block it groups by.
    block: Option<u32>,
    /// The first of its declaration's signatures.
    opens_declaration: bool,
}

/// How a function value's signatures lowered.
enum SignaturesLowered {
    /// Into its type, with the augmenting files it roots on and whether one
    /// of them was unobservable.
    Lowered(
        (
            SemanticNodeId,
            Vec<crate::semantic_query_memo::ObservedGraphSelfRoot>,
            bool,
        ),
    ),
    /// A merged declaration has no prepared value.
    Miss,
    /// The lowering continues in the build handed over.
    Suspended,
}

impl SignatureLowering {
    /// The signatures of `own` and its merged global declarations.
    fn new<C: crate::resolver_core::ResolverCapabilities>(
        dispatch: &ProjectSemanticDispatch<'_, C>,
        own: &verter_retention::heap_size::OwnedValue<
            verter_session_query::type_solver::PreparedValueDecl,
        >,
        is_class: bool,
        global_peers: Vec<ResolvedRootIdentity>,
        augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
    ) -> Self {
        Self {
            own: own.clone(),
            is_class,
            jobs: dispatch.value_signature_jobs(own, augmentation).into(),
            peers: global_peers.into(),
            groups: Vec::new(),
            current_block: None,
            lowering: None,
        }
    }

    /// Group the signature that just lowered to `node`.
    fn record(&mut self, node: SemanticNodeId) {
        let (block, opens_declaration) = self.lowering.take().expect("a signature was lowering");
        if opens_declaration {
            self.current_block = None;
        }
        match self.groups.last_mut() {
            Some(group) if self.current_block == Some(block) => group.push(node),
            _ => self.groups.push(vec![node]),
        }
        self.current_block = Some(block);
    }
}

/// A declaration body's lowering in progress.
pub(super) enum BodyLowering {
    /// The body lowered to this node without a projection.
    Ready(SemanticNodeId),
    /// Its substituted shape is being projected.
    Project(Box<crate::project_semantic_dispatch::locator_view::DeclBodyProjection>),
}

/// Where a body lowering stands after it ran as far as it could.
pub(super) enum BodyPoll {
    Done(SemanticNodeId, bool),
    Need(crate::semantic_query::SemanticQueryKey),
}

/// Address one declared body position in its exact inventory.
fn scoped_type_body_locator(
    slot: &verter_type_expr::locators::TypeBodySlot,
    augmentation: Option<&verter_session_query::declarations::AugmentationScopeKind>,
) -> verter_type_expr::locators::AuthoredBodyLocator {
    use verter_type_expr::locators::{
        AugmentationBodyLocator, AuthoredAugmentationScope, AuthoredBodyLocator,
    };
    let Some(augmentation) = augmentation else {
        return AuthoredBodyLocator::DeclBody(slot.clone());
    };
    let scope = match augmentation {
        verter_session_query::declarations::AugmentationScopeKind::Global => {
            AuthoredAugmentationScope::Global
        }
        verter_session_query::declarations::AugmentationScopeKind::Module(specifier) => {
            AuthoredAugmentationScope::Module {
                specifier: verter_type_expr::OwnedStr::from(specifier.as_str()),
            }
        }
    };
    AuthoredBodyLocator::AugmentationBody(AugmentationBodyLocator {
        anchor: slot.anchor.clone(),
        scope,
        path: slot.path.clone(),
    })
}

struct DeclarationBindingScope<'s> {
    augmentation: Option<&'s verter_session_query::declarations::AugmentationScopeKind>,
    scope: &'s NodeScopeId,
    scope_payload: Option<&'s crate::resolver_core::bare_name_resolve::DeclarationScopePayload>,
    shadowing: &'s crate::resolver_core::scope_shadowing::ScopeShadowing,
    authored_resolution_debt:
        Option<&'s crate::project_semantic_dispatch::carrier::AuthoredResolutionDebtFrame>,
}

/// The readonly state a mapped type's `readonly` modifier gives an array or
/// tuple that was `readonly` (TypeScript's `getModifiedReadonlyState`).
fn modified_readonly(readonly: bool, modifier: crate::semantic_query::ReadonlyMod) -> bool {
    match modifier {
        crate::semantic_query::ReadonlyMod::Add => true,
        crate::semantic_query::ReadonlyMod::Remove => false,
        crate::semantic_query::ReadonlyMod::Keep => readonly,
    }
}

#[cfg(test)]
mod same_path_witness_tests {
    use super::exact_since_producer;
    use crate::project_semantic_dispatch::{BuildLocalTaint, FrameProduction};
    use crate::semantic_query::checker_policy::TupleSplicePosition;
    use crate::semantic_query::{SemanticNodeId, SemanticQueryKey};
    use std::sync::Arc;

    /// An instantiation of one declaration over the single argument `arg`.
    fn application(arg: u64) -> SemanticQueryKey {
        SemanticQueryKey::Instantiate(crate::semantic_query::InstantiateKey::new(
            crate::semantic_query::ResolvedDeclSlotIdentity::type_slot_unscoped(
                Arc::<str>::from("/a.ts"),
                verter_type_expr::TopLevelOwnerId::ordinary_file(),
                Arc::<str>::from("Loop"),
            ),
            Arc::from(vec![SemanticNodeId(arg)].into_boxed_slice()),
            crate::semantic_query::InstantiateContext::non_file(
                crate::semantic_query::ProjectionReductionContext::structural_transit(),
                Default::default(),
                crate::project_semantic_dispatch::BodySourceWitness::mint_for_unit_tests(),
            ),
        ))
    }

    /// How a frame's steps so far read.
    #[derive(Clone, Copy)]
    enum Steps {
        Exact,
        /// A step read a partial.
        Partial,
        /// A step read a complete result its memo would not keep.
        Suppressed,
    }

    fn frame(produces: Option<(u64, TupleSplicePosition)>, steps: Steps) -> BuildLocalTaint {
        BuildLocalTaint {
            produces: produces.and_then(|(arg, site)| FrameProduction::of(&application(arg), site)),
            result_is_partial: matches!(steps, Steps::Partial),
            cache_suppress: matches!(steps, Steps::Suppressed),
            ..BuildLocalTaint::default()
        }
    }

    const TYPE: TupleSplicePosition = TupleSplicePosition::Type;
    const EXPRESSION: TupleSplicePosition = TupleSplicePosition::Expression;
    const CLAIMED: u64 = 7;
    const OTHER: u64 = 3;

    /// A same-path claim on an application an enclosing build produces is
    /// proved only through every frame from that build's to the top: a
    /// partial, or a complete result its memo would not keep, in the
    /// producer's frame or in any frame between refuses the proof even when
    /// the innermost frame is clean; a partial below the producer (its
    /// callers') does not; and a producer that is not on the stack (a
    /// suspended continuation's) proves nothing. The producer is the frame
    /// building exactly the claimed key at the claimed checking site: a
    /// frame building it at the other site is no producer, neither standing
    /// in for an absent one nor ending the walk before a tainted frame
    /// above the real one.
    #[test]
    fn a_same_path_claim_is_exact_only_through_every_frame_since_its_producer() {
        use Steps::{Exact, Partial, Suppressed};
        let claimed = Some((CLAIMED, TYPE));
        let cases = [
            (vec![frame(claimed, Exact), frame(None, Exact)], true),
            (vec![frame(claimed, Partial), frame(None, Exact)], false),
            (vec![frame(claimed, Suppressed), frame(None, Exact)], false),
            (
                vec![
                    frame(claimed, Exact),
                    frame(Some((OTHER, TYPE)), Partial),
                    frame(None, Exact),
                ],
                false,
            ),
            (
                vec![
                    frame(claimed, Exact),
                    frame(Some((OTHER, TYPE)), Suppressed),
                    frame(None, Exact),
                ],
                false,
            ),
            (
                vec![
                    frame(None, Partial),
                    frame(claimed, Exact),
                    frame(None, Exact),
                ],
                true,
            ),
            (
                vec![frame(Some((OTHER, TYPE)), Exact), frame(None, Exact)],
                false,
            ),
            (
                vec![
                    frame(Some((CLAIMED, EXPRESSION)), Exact),
                    frame(None, Exact),
                ],
                false,
            ),
            (
                vec![
                    frame(claimed, Exact),
                    frame(None, Partial),
                    frame(Some((CLAIMED, EXPRESSION)), Exact),
                    frame(None, Exact),
                ],
                false,
            ),
        ];
        let claimed_key = application(CLAIMED);
        for (index, (frames, exact)) in cases.iter().enumerate() {
            assert_eq!(
                exact_since_producer(frames, &claimed_key, TYPE),
                *exact,
                "case {index}"
            );
        }
    }
}

#[cfg(test)]
mod awaited_path_tests {
    use super::{AwaitedPath, AwaitedRelation};
    use crate::semantic_query::SemanticNodeId;

    /// The awaited relations' path ([`AwaitedPath`]) answers
    /// membership by lookup, and a truncation takes exactly the entries it
    /// pops: an operand a nested run pushed again stays on the path until the
    /// outer run's own entry goes, as the ordered stack alone would say.
    #[test]
    fn the_awaited_path_counts_each_entry_until_its_run_truncates() {
        let operand = |index: u64| SemanticNodeId(index);
        let mut path = AwaitedPath::default();
        path.push(AwaitedRelation::Normalize, operand(1));
        path.push(AwaitedRelation::Normalize, operand(2));
        let nested = path.len();
        path.push(AwaitedRelation::Normalize, operand(1));
        path.push(AwaitedRelation::Payload, operand(3));
        assert!(path.contains(AwaitedRelation::Payload, operand(3)));
        assert!(!path.contains(AwaitedRelation::Normalize, operand(3)));
        path.truncate(nested);
        assert!(
            path.contains(AwaitedRelation::Normalize, operand(1)),
            "the outer run's entry keeps the operand on the path"
        );
        assert!(!path.contains(AwaitedRelation::Payload, operand(3)));
        path.truncate(0);
        assert!(!path.contains(AwaitedRelation::Normalize, operand(1)));
        assert!(!path.contains(AwaitedRelation::Normalize, operand(2)));
        assert_eq!(path.len(), 0);
    }
}

/// Whether `key` is new to `seen`, recording it: the one membership test
/// of [`ProjectSemanticDispatch::finite_index_keys`], a hash probe.
fn first_index_key(
    seen: &mut FxHashSet<crate::semantic_query::IndexKey>,
    key: &crate::semantic_query::IndexKey,
) -> bool {
    #[cfg(any(test, feature = "test-support"))]
    INDEX_KEY_PROBES.with(|probes| probes.set(probes.get() + 1));
    seen.insert(key.clone())
}

#[cfg(any(test, feature = "test-support"))]
std::thread_local! {
    static INDEX_KEY_PROBES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static BINDER_COLLECTION_VISITS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// The nodes the per-name binder collection visited on this thread, so far
/// (test-only): the work a clause instantiation spends finding the binders
/// it substitutes.
#[cfg(any(test, feature = "test-support"))]
pub fn binder_collection_visits_for_tests() -> usize {
    BINDER_COLLECTION_VISITS.with(std::cell::Cell::get)
}

/// The key comparisons the finite index-key sets made on this thread, so
/// far (test-only).
#[cfg(any(test, feature = "test-support"))]
pub fn index_key_probes_for_tests() -> usize {
    INDEX_KEY_PROBES.with(std::cell::Cell::get)
}

/// A clause's base substitution: each named parameter's base constraint,
/// in clause order.
struct ClauseBaseSubstitution<'n> {
    names: Vec<&'n str>,
    bases: Vec<SemanticNodeId>,
}

/// Whether the contributor `entry` declares the GLOBAL type of its name: a
/// module's `declare global` interface or alias, or a script's file-scope
/// one. A `declare global` block in a SCRIPT is an error that binds
/// nothing; the automatic libraries are read through the project's library.
fn declares_global_type(
    entry: &verter_session_query::inputs::contributors::ContributorEntry,
) -> bool {
    use verter_session_query::inputs::contributors::{ContributorOrigin, FileModuleKind};
    !entry.is_automatic_lib
        && match entry.origin {
            ContributorOrigin::DeclareGlobal => entry.module_kind == FileModuleKind::Module,
            ContributorOrigin::FileScopeInterface | ContributorOrigin::FileScopeType => true,
            ContributorOrigin::FileScopeNamespace
            | ContributorOrigin::FileScopeValue
            | ContributorOrigin::ModuleAugmentation => false,
        }
}

/// A transaction read being recorded across the steps of its work
/// ([`ProjectSemanticDispatch::begin_transaction_read`]). Dropped unfinished
/// — an unwind — it uninstalls every scope it installed and records nothing.
pub(super) struct TransactionReadRecording<'g> {
    // Uninstalled innermost first: the recorder, then the refusal scope,
    // the build-local frame and the private completeness scope.
    reads: crate::resolver_core::resolver_context::FactReadRecording,
    refusals: crate::fact_tracing::RefusalObservationScope,
    frame: super::BuildLocalTaintGuard<'g>,
    private_completeness: Option<crate::request_context::ColdComputeCompletenessScope>,
    evidence_epoch: u64,
}

impl TransactionReadRecording<'_> {
    /// End the recording: fold what it observed into the enclosing build,
    /// and return what reusing the read must replay — `None` when it is not
    /// reusable (it was partial, `complete` is false, or its refusal is not
    /// one a later reader of this transaction may share).
    pub(super) fn finish<C: crate::resolver_core::ResolverCapabilities>(
        self,
        dispatch: &ProjectSemanticDispatch<'_, C>,
        complete: bool,
    ) -> Option<(
        verter_session_query::facts::reuse::ReuseClass,
        super::dispatch_txn::FlowMemberReuse,
    )> {
        let Self {
            reads,
            refusals,
            frame,
            private_completeness,
            evidence_epoch,
        } = self;
        let reads = reads.finish();
        let refused = refusals.observed();
        drop(refusals);
        let observed = frame.finish();
        let folded_partial =
            crate::request_context::current_cold_compute_completeness().is_partial();
        if let Some(scope) = private_completeness {
            scope.discard();
        }
        dispatch.fold_observed_frame_into_top(&observed);
        let refusal = match refused {
            Some(reason) => verter_session_query::facts::reuse::ObservedRefusal::Typed(reason),
            None if reads.non_cacheable || observed.cache_suppress => {
                verter_session_query::facts::reuse::ObservedRefusal::Unattributed
            }
            None => verter_session_query::facts::reuse::ObservedRefusal::None,
        };
        let complete = !observed.result_is_partial && !folded_partial && complete;
        let reuse = verter_session_query::facts::reuse::classify_reuse(refusal, complete);
        if !reuse.is_request_reusable() {
            return None;
        }
        let replay = super::dispatch_txn::FlowMemberReuse {
            reads,
            observed_self_roots: observed.observed_self_roots,
            canonical_evidence_deposited: dispatch.canonical_evidence_epoch.get() != evidence_epoch,
        };
        Some((reuse, replay))
    }
}
